import { connectToQueueOwner } from "./ipc-transport.js";
import { readQueueOwnerRecord, readQueueOwnerStatus } from "./lease-store.js";

export type QueueOwnerHealth = {
  sessionId: string;
  hasLease: boolean;
  healthy: boolean;
  socketReachable: boolean;
  pidAlive: boolean;
  pid?: number;
  socketPath?: string;
  ownerGeneration?: number;
  queueDepth?: number;
};

export async function probeQueueOwnerHealth(sessionId: string): Promise<QueueOwnerHealth> {
  const ownerRecord = await readQueueOwnerRecord(sessionId);
  if (!ownerRecord) {
    return {
      sessionId,
      hasLease: false,
      healthy: false,
      socketReachable: false,
      pidAlive: false,
    };
  }

  const owner = await readQueueOwnerStatus(sessionId);
  if (!owner) {
    return {
      sessionId,
      hasLease: false,
      healthy: false,
      socketReachable: false,
      pidAlive: false,
    };
  }

  const pidAlive = owner.alive;
  let socketReachable = false;
  try {
    const socket = await connectToQueueOwner(ownerRecord, 2);
    if (socket) {
      socketReachable = true;
      if (!socket.destroyed) {
        socket.end();
      }
    }
  } catch {
    socketReachable = false;
  }

  return {
    sessionId,
    hasLease: true,
    healthy: socketReachable,
    socketReachable,
    pidAlive,
    pid: owner.pid,
    socketPath: owner.socketPath,
    ownerGeneration: owner.ownerGeneration,
    queueDepth: owner.queueDepth,
  };
}

import net from "node:net";
import type { SetSessionConfigOptionResponse } from "@agentclientprotocol/sdk";
import { normalizeOutputError } from "../../acp/error-normalization.js";
import { recordPerfDuration } from "../../perf-metrics.js";
import { textPrompt } from "../../prompt-content.js";
import type {
  AcpClientOptions,
  NonInteractivePermissionPolicy,
  PermissionMode,
  PromptInput,
  SessionResumePolicy,
} from "../../types.js";
import {
  parseQueueRequest,
  type QueueOwnerErrorMessage,
  type QueueOwnerMessage,
  type QueueRequest,
} from "./messages.js";

type QueueOwnerSocketLease = {
  socketPath: string;
  ownerGeneration?: number;
};

const QUEUE_SOCKET_DRAIN_TIMEOUT_MS = 1_000;

function makeQueueOwnerError(
  requestId: string,
  message: string,
  detailCode: string,
  options: {
    retryable?: boolean;
  } = {},
): QueueOwnerErrorMessage {
  return {
    type: "error",
    requestId,
    ownerGeneration: undefined,
    code: "RUNTIME",
    detailCode,
    origin: "queue",
    retryable: options.retryable,
    message,
  };
}

function makeQueueOwnerErrorFromUnknown(
  requestId: string,
  error: unknown,
  detailCode: string,
  options: {
    retryable?: boolean;
  } = {},
): QueueOwnerErrorMessage {
  const normalized = normalizeOutputError(error, {
    defaultCode: "RUNTIME",
    origin: "queue",
    detailCode,
    retryable: options.retryable,
  });

  return {
    type: "error",
    requestId,
    code: normalized.code,
    detailCode: normalized.detailCode,
    origin: normalized.origin,
    message: normalized.message,
    retryable: normalized.retryable,
    acp: normalized.acp,
  };
}

function writeQueueMessage(socket: net.Socket, message: QueueOwnerMessage): void {
  if (socket.destroyed || !socket.writable) {
    return;
  }
  socket.write(`${JSON.stringify(message)}\n`);
}

export type QueueTask = {
  requestId: string;
  message: string;
  prompt: PromptInput;
  permissionMode: PermissionMode;
  resumePolicy?: SessionResumePolicy;
  nonInteractivePermissions?: NonInteractivePermissionPolicy;
  permissionPolicy?: AcpClientOptions["permissionPolicy"];
  timeoutMs?: number;
  suppressSdkConsoleErrors?: boolean;
  promptRetries?: number;
  sessionOptions?: NonNullable<AcpClientOptions["sessionOptions"]>;
  waitForCompletion: boolean;
  enqueuedAt: number;
  send: (message: QueueOwnerMessage) => void;
  close: () => void;
};

export type QueueOwnerControlHandlers = {
  cancelPrompt: () => Promise<boolean>;
  closeSession: (timeoutMs?: number) => Promise<boolean>;
  setSessionMode: (modeId: string, timeoutMs?: number) => Promise<void>;
  setSessionModel: (
    modelId: string,
    timeoutMs?: number,
  ) => Promise<SetSessionConfigOptionResponse | undefined>;
  setSessionConfigOption: (
    configId: string,
    value: string,
    timeoutMs?: number,
  ) => Promise<SetSessionConfigOptionResponse>;
};

type SessionQueueOwnerOptions = {
  maxQueueDepth: number;
  onQueueDepthChanged?: (queueDepth: number) => void;
};

export class SessionQueueOwner {
  private readonly server: net.Server;
  private readonly controlHandlers: QueueOwnerControlHandlers;
  private readonly ownerGeneration?: number;
  private readonly maxQueueDepth: number;
  private readonly onQueueDepthChanged?: (queueDepth: number) => void;
  private readonly pending: QueueTask[] = [];
  private readonly waiters: Array<(task: QueueTask | undefined) => void> = [];
  private readonly sockets = new Set<net.Socket>();
  private readonly taskSockets = new Set<net.Socket>();
  private readonly drainingSockets = new Set<net.Socket>();
  private closed = false;

  private constructor(
    server: net.Server,
    controlHandlers: QueueOwnerControlHandlers,
    lease: QueueOwnerSocketLease,
    options: SessionQueueOwnerOptions,
  ) {
    this.server = server;
    this.controlHandlers = controlHandlers;
    this.ownerGeneration = lease.ownerGeneration;
    this.maxQueueDepth = Math.max(1, Math.round(options.maxQueueDepth));
    this.onQueueDepthChanged = options.onQueueDepthChanged;
  }

  static async start(
    lease: QueueOwnerSocketLease,
    controlHandlers: QueueOwnerControlHandlers,
    options: SessionQueueOwnerOptions = {
      maxQueueDepth: 16,
    },
  ): Promise<SessionQueueOwner> {
    const ownerRef: { current: SessionQueueOwner | undefined } = { current: undefined };
    const server = net.createServer((socket) => {
      ownerRef.current?.handleConnection(socket);
    });
    ownerRef.current = new SessionQueueOwner(server, controlHandlers, lease, options);

    await new Promise<void>((resolve, reject) => {
      const onListening = () => {
        server.off("error", onError);
        resolve();
      };
      const onError = (error: Error) => {
        server.off("listening", onListening);
        reject(error);
      };

      server.once("listening", onListening);
      server.once("error", onError);
      server.listen(lease.socketPath);
    });

    return ownerRef.current;
  }

  beginShutdown(): void {
    if (this.closed) {
      return;
    }

    this.closed = true;
    for (const waiter of this.waiters.splice(0)) {
      waiter(undefined);
    }

    for (const task of this.pending.splice(0)) {
      if (task.waitForCompletion) {
        task.send(
          makeQueueOwnerError(
            task.requestId,
            "Queue owner shutting down before prompt execution",
            "QUEUE_OWNER_SHUTTING_DOWN",
            {
              retryable: true,
            },
          ),
        );
      }
      task.close();
    }
    for (const socket of this.sockets) {
      if (!this.taskSockets.has(socket) && !this.drainingSockets.has(socket)) {
        socket.destroy();
      }
    }
    this.emitQueueDepth();
  }

  async close(): Promise<void> {
    this.beginShutdown();

    await new Promise<void>((resolve) => {
      const forceCloseTimer = setTimeout(() => {
        for (const socket of this.sockets) {
          socket.destroy();
        }
      }, QUEUE_SOCKET_DRAIN_TIMEOUT_MS);
      forceCloseTimer.unref();
      this.server.close(() => {
        clearTimeout(forceCloseTimer);
        resolve();
      });
    });
  }

  async nextTask(timeoutMs?: number): Promise<QueueTask | undefined> {
    if (this.pending.length > 0) {
      const task = this.pending.shift();
      this.emitQueueDepth();
      if (task) {
        recordPerfDuration("queue.owner.wait_ms", Date.now() - task.enqueuedAt);
      }
      return task;
    }
    if (this.closed) {
      return undefined;
    }

    return await new Promise<QueueTask | undefined>((resolve) => {
      const shouldTimeout = timeoutMs != null;
      const timer =
        shouldTimeout &&
        setTimeout(
          () => {
            const index = this.waiters.indexOf(waiter);
            if (index >= 0) {
              this.waiters.splice(index, 1);
            }
            resolve(undefined);
          },
          Math.max(0, timeoutMs),
        );

      const waiter = (task: QueueTask | undefined) => {
        if (timer) {
          clearTimeout(timer);
        }
        resolve(task);
      };

      this.waiters.push(waiter);
    });
  }

  queueDepth(): number {
    return this.pending.length;
  }

  private emitQueueDepth(): void {
    this.onQueueDepthChanged?.(this.pending.length);
  }

  private enqueue(task: QueueTask): boolean {
    if (this.closed) {
      task.send(
        makeQueueOwnerError(
          task.requestId,
          "Queue owner is shutting down",
          "QUEUE_OWNER_SHUTTING_DOWN",
          {
            retryable: true,
          },
        ),
      );
      task.close();
      return false;
    }

    const waiter = this.waiters.shift();
    if (waiter) {
      waiter(task);
      return true;
    }

    if (this.pending.length >= this.maxQueueDepth) {
      task.send({
        ...makeQueueOwnerError(
          task.requestId,
          `Queue owner is overloaded (${this.pending.length}/${this.maxQueueDepth} queued)`,
          "QUEUE_OWNER_OVERLOADED",
          {
            retryable: true,
          },
        ),
        ownerGeneration: this.ownerGeneration,
      });
      task.close();
      return false;
    }

    this.pending.push(task);
    this.emitQueueDepth();
    return true;
  }

  private handleControlRequest<TMessage extends QueueOwnerMessage>(options: {
    socket: net.Socket;
    requestId: string;
    run: () => Promise<TMessage>;
  }): void {
    writeQueueMessage(options.socket, {
      type: "accepted",
      requestId: options.requestId,
      ownerGeneration: this.ownerGeneration,
    });

    void options
      .run()
      .then((message) => {
        writeQueueMessage(options.socket, {
          ...message,
          ownerGeneration: this.ownerGeneration,
        });
      })
      .catch((error) => {
        writeQueueMessage(options.socket, {
          ...makeQueueOwnerErrorFromUnknown(
            options.requestId,
            error,
            "QUEUE_CONTROL_REQUEST_FAILED",
          ),
          ownerGeneration: this.ownerGeneration,
        });
      })
      .finally(() => {
        this.endSocket(options.socket);
      });
  }

  private endSocket(socket: net.Socket): void {
    if (socket.destroyed || this.drainingSockets.has(socket)) {
      return;
    }
    this.taskSockets.delete(socket);
    this.drainingSockets.add(socket);
    socket.end(() => {
      this.drainingSockets.delete(socket);
      socket.destroy();
    });
  }

  private failRequest(
    socket: net.Socket,
    requestId: string,
    message: string,
    detailCode: string,
  ): void {
    writeQueueMessage(socket, {
      ...makeQueueOwnerError(requestId, message, detailCode, {
        retryable: false,
      }),
      ownerGeneration: this.ownerGeneration,
    });
    this.endSocket(socket);
  }

  private parseRequestLine(socket: net.Socket, line: string): QueueRequest | undefined {
    let parsed: unknown;
    try {
      parsed = JSON.parse(line);
    } catch {
      this.failRequest(
        socket,
        "unknown",
        "Invalid queue request payload",
        "QUEUE_REQUEST_PAYLOAD_INVALID_JSON",
      );
      return undefined;
    }
    const request = parseQueueRequest(parsed);
    if (!request) {
      this.failRequest(socket, "unknown", "Invalid queue request", "QUEUE_REQUEST_INVALID");
    }
    return request ?? undefined;
  }

  private rejectStaleOwnerGeneration(socket: net.Socket, request: QueueRequest): boolean {
    if (
      request.ownerGeneration === undefined ||
      this.ownerGeneration === undefined ||
      request.ownerGeneration === this.ownerGeneration
    ) {
      return false;
    }
    this.failRequest(
      socket,
      request.requestId,
      "Queue request targeted a stale queue owner generation",
      "QUEUE_OWNER_GENERATION_MISMATCH",
    );
    return true;
  }

  private rejectClosedOwner(socket: net.Socket, request: QueueRequest): boolean {
    if (!this.closed) {
      return false;
    }
    writeQueueMessage(socket, {
      ...makeQueueOwnerError(
        request.requestId,
        "Queue owner is shutting down",
        "QUEUE_OWNER_CLOSED",
        {
          retryable: true,
        },
      ),
      ownerGeneration: this.ownerGeneration,
    });
    this.endSocket(socket);
    return true;
  }

  private handleControlQueueRequest(socket: net.Socket, request: QueueRequest): boolean {
    if (request.type === "cancel_prompt") {
      this.handleControlRequest({
        socket,
        requestId: request.requestId,
        run: async () => ({
          type: "cancel_result",
          requestId: request.requestId,
          cancelled: await this.controlHandlers.cancelPrompt(),
        }),
      });
      return true;
    }
    if (request.type === "close_session") {
      this.handleControlRequest({
        socket,
        requestId: request.requestId,
        run: async () => ({
          type: "close_session_result",
          requestId: request.requestId,
          closed: await this.controlHandlers.closeSession(request.timeoutMs),
        }),
      });
      return true;
    }
    return this.handleSessionControlQueueRequest(socket, request);
  }

  private handleSessionControlQueueRequest(socket: net.Socket, request: QueueRequest): boolean {
    if (request.type === "set_mode") {
      this.handleControlRequest({
        socket,
        requestId: request.requestId,
        run: async () => {
          await this.controlHandlers.setSessionMode(request.modeId, request.timeoutMs);
          return {
            type: "set_mode_result",
            requestId: request.requestId,
            modeId: request.modeId,
          };
        },
      });
      return true;
    }
    if (request.type === "set_model") {
      this.handleControlRequest({
        socket,
        requestId: request.requestId,
        run: async () => {
          const response = await this.controlHandlers.setSessionModel(
            request.modelId,
            request.timeoutMs,
          );
          return {
            type: "set_model_result",
            requestId: request.requestId,
            modelId: request.modelId,
            response,
          };
        },
      });
      return true;
    }
    if (request.type === "set_config_option") {
      this.handleControlRequest({
        socket,
        requestId: request.requestId,
        run: async () => ({
          type: "set_config_option_result",
          requestId: request.requestId,
          response: await this.controlHandlers.setSessionConfigOption(
            request.configId,
            request.value,
            request.timeoutMs,
          ),
        }),
      });
      return true;
    }
    return false;
  }

  private enqueuePromptRequest(
    socket: net.Socket,
    request: Extract<QueueRequest, { type: "submit_prompt" }>,
  ): void {
    this.taskSockets.add(socket);
    const task: QueueTask = {
      requestId: request.requestId,
      message: request.message,
      prompt: request.prompt ?? textPrompt(request.message),
      permissionMode: request.permissionMode,
      resumePolicy: request.resumePolicy,
      nonInteractivePermissions: request.nonInteractivePermissions,
      permissionPolicy: request.permissionPolicy,
      timeoutMs: request.timeoutMs,
      suppressSdkConsoleErrors: request.suppressSdkConsoleErrors,
      promptRetries: request.promptRetries,
      sessionOptions: request.sessionOptions,
      waitForCompletion: request.waitForCompletion,
      enqueuedAt: Date.now(),
      send: (message) => {
        writeQueueMessage(socket, {
          ...message,
          ownerGeneration: this.ownerGeneration,
        });
      },
      close: () => {
        this.endSocket(socket);
      },
    };

    const enqueued = this.enqueue(task);
    if (!enqueued) {
      return;
    }

    writeQueueMessage(socket, {
      type: "accepted",
      requestId: request.requestId,
      ownerGeneration: this.ownerGeneration,
    });
    if (!request.waitForCompletion) {
      task.close();
    }
  }

  private handleConnection(socket: net.Socket): void {
    this.sockets.add(socket);
    socket.setEncoding("utf8");
    socket.once("close", () => {
      this.sockets.delete(socket);
      this.taskSockets.delete(socket);
      this.drainingSockets.delete(socket);
    });

    let buffer = "";
    let handled = false;

    const processLine = (line: string): void => {
      if (handled) {
        return;
      }
      handled = true;

      const request = this.parseRequestLine(socket, line);
      if (
        !request ||
        this.rejectClosedOwner(socket, request) ||
        this.rejectStaleOwnerGeneration(socket, request)
      ) {
        return;
      }
      if (this.handleControlQueueRequest(socket, request)) {
        return;
      }
      if (request.type !== "submit_prompt") {
        this.failRequest(
          socket,
          request.requestId,
          "Invalid queue request",
          "QUEUE_REQUEST_INVALID",
        );
        return;
      }
      this.enqueuePromptRequest(socket, request);
    };

    socket.on("data", (chunk: string) => {
      buffer += chunk;

      let index = buffer.indexOf("\n");
      while (index >= 0) {
        const line = buffer.slice(0, index).trim();
        buffer = buffer.slice(index + 1);

        if (line.length > 0) {
          processLine(line);
        }

        index = buffer.indexOf("\n");
      }
    });

    socket.on("error", () => {
      // no-op: queue processing continues even if client disconnects
    });
  }
}

import net from "node:net";
import { measurePerf } from "../../perf-metrics.js";
import { type QueueOwnerRecord, waitMs } from "./lease-store.js";

const QUEUE_CONNECT_ATTEMPTS = 40;
export const QUEUE_CONNECT_RETRY_MS = 50;
export const SOCKET_CONNECTION_TIMEOUT_MS = 5000;

function shouldRetryQueueConnect(error: unknown): boolean {
  const code = (error as NodeJS.ErrnoException).code;
  return code === "ENOENT" || code === "ECONNREFUSED";
}

async function connectToSocket(
  socketPath: string,
  timeoutMs = SOCKET_CONNECTION_TIMEOUT_MS,
): Promise<net.Socket> {
  return await new Promise<net.Socket>((resolve, reject) => {
    const socket = net.createConnection(socketPath);
    let settled = false;

    const timeout = setTimeout(() => {
      if (settled) {
        return;
      }
      settled = true;
      socket.destroy();
      reject(new Error(`Connection to ${socketPath} timed out after ${timeoutMs}ms`));
    }, timeoutMs);

    const onConnect = () => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timeout);
      socket.off("error", onError);
      resolve(socket);
    };
    const onError = (error: Error) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timeout);
      socket.off("connect", onConnect);
      reject(error);
    };

    socket.once("connect", onConnect);
    socket.once("error", onError);
  });
}

export async function connectToQueueOwner(
  owner: QueueOwnerRecord,
  maxAttempts = QUEUE_CONNECT_ATTEMPTS,
): Promise<net.Socket | undefined> {
  let lastError: unknown;

  const attempts = Math.max(1, Math.trunc(maxAttempts));
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await measurePerf(
        "queue.connect",
        async () => await connectToSocket(owner.socketPath),
      );
    } catch (error) {
      lastError = error;
      if (!shouldRetryQueueConnect(error)) {
        throw error;
      }
      await waitMs(QUEUE_CONNECT_RETRY_MS);
    }
  }

  if (lastError && !shouldRetryQueueConnect(lastError)) {
    throw lastError;
  }

  return undefined;
}

