import { randomUUID } from "node:crypto";
import path from "node:path";

export function createAtomicWriteTempPath(
  filePath: string,
  createUniqueId: () => string = randomUUID,
): string {
  const tempName = `.acpx-write.${process.pid}.${Date.now()}.${createUniqueId()}.tmp`;
  return path.join(path.dirname(filePath), tempName);
}

import fs from "node:fs/promises";
import path from "node:path";
import type { SessionRecord } from "../../types.js";
import { createAtomicWriteTempPath } from "./atomic-write.js";
import { parseSessionRecord } from "./parse.js";

const SESSION_INDEX_SCHEMA = "acpx.session-index.v1";

export type SessionIndexEntry = {
  file: string;
  acpxRecordId: string;
  acpSessionId: string;
  agentCommand: string;
  cwd: string;
  name?: string;
  closed: boolean;
  lastUsedAt: string;
};

type SessionIndex = {
  schema: typeof SESSION_INDEX_SCHEMA;
  files: string[];
  entries: SessionIndexEntry[];
};

function asRecord(value: unknown): Record<string, unknown> | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return undefined;
  }
  return value as Record<string, unknown>;
}

function parseIndexEntry(raw: unknown): SessionIndexEntry | undefined {
  const record = asRecord(raw);
  if (!record) {
    return undefined;
  }
  if (!hasRequiredIndexEntryFields(record)) {
    return undefined;
  }
  if (record.name !== undefined && typeof record.name !== "string") {
    return undefined;
  }
  return {
    file: record.file,
    acpxRecordId: record.acpxRecordId,
    acpSessionId: record.acpSessionId,
    agentCommand: record.agentCommand,
    cwd: record.cwd,
    name: record.name,
    closed: record.closed,
    lastUsedAt: record.lastUsedAt,
  };
}

function hasRequiredIndexEntryFields(record: Record<string, unknown>): record is Record<
  string,
  unknown
> & {
  file: string;
  acpxRecordId: string;
  acpSessionId: string;
  agentCommand: string;
  cwd: string;
  lastUsedAt: string;
  closed: boolean;
} {
  return (
    ["file", "acpxRecordId", "acpSessionId", "agentCommand", "cwd", "lastUsedAt"].every(
      (key) => typeof record[key] === "string",
    ) && typeof record.closed === "boolean"
  );
}

export function sessionIndexPath(sessionDir: string): string {
  return path.join(sessionDir, "index.json");
}

export function toSessionIndexEntry(record: SessionRecord, fileName: string): SessionIndexEntry {
  return {
    file: fileName,
    acpxRecordId: record.acpxRecordId,
    acpSessionId: record.acpSessionId,
    agentCommand: record.agentCommand,
    cwd: record.cwd,
    name: record.name,
    closed: record.closed === true,
    lastUsedAt: record.lastUsedAt,
  };
}

export async function readSessionIndex(sessionDir: string): Promise<SessionIndex | undefined> {
  const filePath = sessionIndexPath(sessionDir);
  try {
    const payload = await fs.readFile(filePath, "utf8");
    const parsed = JSON.parse(payload) as unknown;
    const record = asRecord(parsed);
    if (!record || record.schema !== SESSION_INDEX_SCHEMA || !Array.isArray(record.files)) {
      return undefined;
    }
    const files = record.files.filter((entry): entry is string => typeof entry === "string");
    if (files.length !== record.files.length || !Array.isArray(record.entries)) {
      return undefined;
    }
    const entries = record.entries
      .map((entry) => parseIndexEntry(entry))
      .filter((entry): entry is SessionIndexEntry => Boolean(entry));
    if (entries.length !== record.entries.length) {
      return undefined;
    }
    return {
      schema: SESSION_INDEX_SCHEMA,
      files,
      entries,
    };
  } catch {
    return undefined;
  }
}

export async function writeSessionIndex(
  sessionDir: string,
  index: {
    files: string[];
    entries: SessionIndexEntry[];
  },
): Promise<void> {
  const filePath = sessionIndexPath(sessionDir);
  const tempFile = createAtomicWriteTempPath(filePath);
  const payload = JSON.stringify(
    {
      schema: SESSION_INDEX_SCHEMA,
      files: [...index.files].toSorted(),
      entries: [...index.entries].toSorted((a, b) => b.lastUsedAt.localeCompare(a.lastUsedAt)),
    },
    null,
    2,
  );
  await fs.writeFile(tempFile, `${payload}\n`, "utf8");
  await fs.rename(tempFile, filePath);
}

export async function rebuildSessionIndex(sessionDir: string): Promise<SessionIndex> {
  const entries = await fs.readdir(sessionDir, { withFileTypes: true });
  const files = entries
    .filter(
      (entry) => entry.isFile() && entry.name.endsWith(".json") && entry.name !== "index.json",
    )
    .map((entry) => entry.name)
    .toSorted();

  const indexEntries: SessionIndexEntry[] = [];
  for (const file of files) {
    try {
      const payload = await fs.readFile(path.join(sessionDir, file), "utf8");
      const parsed = parseSessionRecord(JSON.parse(payload));
      if (!parsed) {
        continue;
      }
      indexEntries.push(toSessionIndexEntry(parsed, file));
    } catch {
      // ignore corrupt session files while rebuilding the cache index
    }
  }

  const index: SessionIndex = {
    schema: SESSION_INDEX_SCHEMA,
    files,
    entries: indexEntries,
  };
  await writeSessionIndex(sessionDir, index);
  return index;
}

export async function loadOrRebuildSessionIndex(sessionDir: string): Promise<SessionIndex> {
  const files = (await fs.readdir(sessionDir, { withFileTypes: true }))
    .filter(
      (entry) => entry.isFile() && entry.name.endsWith(".json") && entry.name !== "index.json",
    )
    .map((entry) => entry.name)
    .toSorted();
  const existing = await readSessionIndex(sessionDir);
  if (
    existing &&
    existing.files.length === files.length &&
    existing.files.every((file, index) => file === files[index])
  ) {
    return existing;
  }
  return await rebuildSessionIndex(sessionDir);
}

import { resolveAgentArgvForCommand } from "../../acp/builtin-command-migration.js";
import type {
  SessionAcpxState,
  SessionEventLog,
  SessionRecord,
  SessionConversation,
} from "../../types.js";
import { SESSION_RECORD_SCHEMA } from "../../types.js";
import { defaultSessionEventLog } from "../event-log.js";
import { normalizeRuntimeSessionId } from "../runtime-session-id.js";

function asRecord(value: unknown): Record<string, unknown> | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return undefined;
  }
  return value as Record<string, unknown>;
}

function hasOwn(source: object, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(source, key);
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((entry) => typeof entry === "string");
}

function parseOptionalAgentArgv(value: unknown): string[] | undefined {
  return isStringArray(value) && value.length > 0 && value[0]?.length > 0 ? value : undefined;
}

function parsePersistedAgentArgv(record: Record<string, unknown>): string[] | undefined {
  return (
    parseOptionalAgentArgv(record.agent_argv) ??
    (typeof record.agent_command === "string"
      ? resolveAgentArgvForCommand(record.agent_command)
      : undefined)
  );
}

function hasModelConfigOption(options: unknown): boolean {
  if (!Array.isArray(options)) {
    return false;
  }
  return options.some((entry) => {
    const option = asRecord(entry);
    return option?.category === "model" || option?.id === "model";
  });
}

function parseConfigOptions(raw: unknown): SessionAcpxState["config_options"] | undefined {
  if (!Array.isArray(raw) || !raw.every((entry) => asRecord(entry) !== undefined)) {
    return undefined;
  }
  return raw as SessionAcpxState["config_options"];
}

function parseAvailableCommand(
  raw: unknown,
): NonNullable<SessionAcpxState["available_commands"]>[number] | undefined {
  if (typeof raw === "string") {
    const name = raw.trim();
    return name ? { name } : undefined;
  }
  const record = asRecord(raw);
  if (!record) {
    return undefined;
  }
  const name = parseNonEmptyString(record.name);
  if (!name) {
    return undefined;
  }
  const description = parseNonEmptyString(record.description);
  return {
    name,
    ...(description ? { description } : {}),
    ...(typeof record.has_input === "boolean" ? { has_input: record.has_input } : {}),
  };
}

function parseAvailableCommands(raw: unknown): SessionAcpxState["available_commands"] | undefined {
  if (!Array.isArray(raw)) {
    return undefined;
  }
  const commands = raw
    .map((entry) => parseAvailableCommand(entry))
    .filter(
      (entry): entry is NonNullable<SessionAcpxState["available_commands"]>[number] =>
        entry !== undefined,
    );
  return commands.length > 0 ? commands : undefined;
}

function parseNonEmptyString(value: unknown): string | undefined {
  if (typeof value !== "string") {
    return undefined;
  }
  const trimmed = value.trim();
  return trimmed ? trimmed : undefined;
}

function parseTokenUsage(
  raw: unknown,
): SessionConversation["cumulative_token_usage"] | null | undefined {
  if (raw === undefined || raw === null) {
    return undefined;
  }

  const record = asRecord(raw);
  if (!record) {
    return null;
  }

  const usage: SessionConversation["cumulative_token_usage"] = {};
  const fields: Array<keyof SessionConversation["cumulative_token_usage"]> = [
    "input_tokens",
    "output_tokens",
    "cache_creation_input_tokens",
    "cache_read_input_tokens",
    "thought_tokens",
    "total_tokens",
  ];

  for (const field of fields) {
    const value = record[field];
    if (value === undefined) {
      continue;
    }
    if (!isNonNegativeFiniteNumber(value)) {
      return null;
    }
    usage[field] = value;
  }

  return usage;
}

function isNonNegativeFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

function parseUsageCost(raw: unknown): SessionConversation["cumulative_cost"] | null | undefined {
  if (raw === undefined || raw === null) {
    return undefined;
  }
  const record = asRecord(raw);
  if (!record) {
    return null;
  }
  return parseUsageCostRecord(record);
}

function parseUsageCostRecord(
  record: Record<string, unknown>,
): SessionConversation["cumulative_cost"] | null | undefined {
  const amount = parseCostAmount(record.amount);
  const currency = parseCostCurrency(record.currency);
  if (amount === null || currency === null) {
    return null;
  }
  const cost: NonNullable<SessionConversation["cumulative_cost"]> = {
    ...(amount !== undefined ? { amount } : {}),
    ...(currency !== undefined ? { currency } : {}),
  };
  return Object.keys(cost).length > 0 ? cost : undefined;
}

function parseCostAmount(value: unknown): number | null | undefined {
  if (value === undefined) {
    return undefined;
  }
  return isNonNegativeFiniteNumber(value) ? value : null;
}

function parseCostCurrency(value: unknown): string | null | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== "string") {
    return null;
  }
  const currency = value.trim();
  return currency.length > 0 ? currency : undefined;
}

function parseRequestTokenUsage(
  raw: unknown,
): SessionConversation["request_token_usage"] | null | undefined {
  if (raw === undefined || raw === null) {
    return undefined;
  }

  const record = asRecord(raw);
  if (!record) {
    return null;
  }

  const usage: SessionConversation["request_token_usage"] = {};
  for (const [key, value] of Object.entries(record)) {
    const parsed = parseTokenUsage(value);
    if (parsed == null) {
      return null;
    }
    usage[key] = parsed;
  }

  return usage;
}

function isSessionMessageImage(raw: unknown): boolean {
  const record = asRecord(raw);
  if (!record || typeof record.source !== "string") {
    return false;
  }

  if (record.size === undefined || record.size === null) {
    return true;
  }

  const size = asRecord(record.size);
  return !!size && isFiniteNumber(size.width) && isFiniteNumber(size.height);
}

function isSessionMessageAudio(raw: unknown): boolean {
  const record = asRecord(raw);
  return !!record && typeof record.source === "string" && typeof record.mime_type === "string";
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function isUserContent(raw: unknown): boolean {
  const record = asRecord(raw);
  if (!record) {
    return false;
  }

  if (typeof record.Text === "string") {
    return true;
  }

  if (record.Mention !== undefined) {
    const mention = asRecord(record.Mention);
    return !!mention && typeof mention.uri === "string" && typeof mention.content === "string";
  }

  if (record.Image !== undefined) {
    return isSessionMessageImage(record.Image);
  }

  if (record.Audio !== undefined) {
    return isSessionMessageAudio(record.Audio);
  }

  return false;
}

function isToolUse(raw: unknown): boolean {
  const record = asRecord(raw);
  return (
    !!record &&
    hasStringFields(record, ["id", "name", "raw_input"]) &&
    hasOwn(record, "input") &&
    typeof record.is_input_complete === "boolean" &&
    isOptionalString(record.thought_signature)
  );
}

function hasStringFields(record: Record<string, unknown>, keys: readonly string[]): boolean {
  return keys.every((key) => typeof record[key] === "string");
}

function isOptionalString(value: unknown): boolean {
  return value === undefined || value === null || typeof value === "string";
}

function isToolResultContent(raw: unknown): boolean {
  const record = asRecord(raw);
  if (!record) {
    return false;
  }

  if (typeof record.Text === "string") {
    return true;
  }

  if (record.Image !== undefined) {
    return isSessionMessageImage(record.Image);
  }

  return false;
}

function isToolResult(raw: unknown): boolean {
  const record = asRecord(raw);
  return (
    !!record &&
    typeof record.tool_use_id === "string" &&
    typeof record.tool_name === "string" &&
    typeof record.is_error === "boolean" &&
    isToolResultContent(record.content)
  );
}

function isAgentContent(raw: unknown): boolean {
  const record = asRecord(raw);
  if (!record) {
    return false;
  }

  if (typeof record.Text === "string") {
    return true;
  }

  if (record.Thinking !== undefined) {
    return isThinkingContent(record.Thinking);
  }

  if (typeof record.RedactedThinking === "string") {
    return true;
  }

  if (record.ToolUse !== undefined) {
    return isToolUse(record.ToolUse);
  }

  return false;
}

function isThinkingContent(raw: unknown): boolean {
  const thinking = asRecord(raw);
  return !!thinking && typeof thinking.text === "string" && isOptionalString(thinking.signature);
}

function isUserMessage(raw: unknown): boolean {
  const record = asRecord(raw);
  if (!record || record.User === undefined) {
    return false;
  }

  const user = asRecord(record.User);
  return (
    !!user &&
    typeof user.id === "string" &&
    Array.isArray(user.content) &&
    user.content.every((entry) => isUserContent(entry))
  );
}

function isAgentMessage(raw: unknown): boolean {
  const record = asRecord(raw);
  if (!record || record.Agent === undefined) {
    return false;
  }

  const agent = asRecord(record.Agent);
  if (!agent || !Array.isArray(agent.content) || !agent.content.every(isAgentContent)) {
    return false;
  }

  const toolResults = asRecord(agent.tool_results);
  if (!toolResults) {
    return false;
  }

  return Object.values(toolResults).every(isToolResult);
}

function isConversationMessage(raw: unknown): boolean {
  return raw === "Resume" || isUserMessage(raw) || isAgentMessage(raw);
}

function parseConversationRecord(record: Record<string, unknown>): SessionConversation | undefined {
  if (!hasValidConversationCore(record)) {
    return undefined;
  }

  const title = parseConversationTitle(record.title);
  if (title === INVALID_VALUE) {
    return undefined;
  }

  const cumulativeTokenUsage = parseTokenUsage(record.cumulative_token_usage);
  const cumulativeCost = parseUsageCost(record.cumulative_cost);
  const requestTokenUsage = parseRequestTokenUsage(record.request_token_usage);
  if (cumulativeTokenUsage === null || cumulativeCost === null || requestTokenUsage === null) {
    return undefined;
  }

  return {
    title,
    messages: record.messages,
    updated_at: record.updated_at,
    cumulative_token_usage: cumulativeTokenUsage ?? {},
    cumulative_cost: cumulativeCost,
    request_token_usage: requestTokenUsage ?? {},
  };
}

const INVALID_VALUE = Symbol("invalid");

function parseConversationTitle(value: unknown): string | null | undefined | typeof INVALID_VALUE {
  if (value === undefined || value === null || typeof value === "string") {
    return value;
  }
  return INVALID_VALUE;
}

function hasValidConversationCore(record: Record<string, unknown>): record is Record<
  string,
  unknown
> & {
  messages: SessionConversation["messages"];
  updated_at: string;
} {
  return (
    Array.isArray(record.messages) &&
    record.messages.every(isConversationMessage) &&
    typeof record.updated_at === "string"
  );
}

function parseAcpxState(raw: unknown): SessionAcpxState | undefined {
  const record = asRecord(raw);
  if (!record) {
    return undefined;
  }

  const state: SessionAcpxState = {};

  assignBooleanTrue(state, "reset_on_next_ensure", record.reset_on_next_ensure);
  assignStringState(state, "current_mode_id", record.current_mode_id);
  assignStringState(state, "desired_mode_id", record.desired_mode_id);

  assignDesiredConfigOptions(state, record.desired_config_options);

  assignParsedModelState(state, record);

  const availableCommands = parseAvailableCommands(record.available_commands);
  if (availableCommands) {
    state.available_commands = availableCommands;
  }

  assignParsedSessionOptions(state, record.session_options);

  return state;
}

function assignParsedModelState(state: SessionAcpxState, record: Record<string, unknown>): void {
  assignStringState(state, "current_model_id", record.current_model_id);
  if (isStringArray(record.available_models)) {
    state.available_models = [...record.available_models];
  }
  if (record.model_control === "config_option" || record.model_control === "legacy_set_model") {
    state.model_control = record.model_control;
  }
  const configOptions = parseConfigOptions(record.config_options);
  if (configOptions) {
    state.config_options = configOptions;
  }
  if (state.model_control === undefined && state.available_models !== undefined) {
    state.model_control = hasModelConfigOption(state.config_options)
      ? "config_option"
      : "legacy_set_model";
  }
}

function assignBooleanTrue(
  state: SessionAcpxState,
  key: "reset_on_next_ensure",
  value: unknown,
): void {
  if (value === true) {
    state[key] = true;
  }
}

function assignStringState(
  state: SessionAcpxState,
  key: "current_mode_id" | "desired_mode_id" | "current_model_id",
  value: unknown,
): void {
  if (typeof value === "string") {
    state[key] = value;
  }
}

function assignDesiredConfigOptions(state: SessionAcpxState, raw: unknown): void {
  const desiredConfigOptions = asRecord(raw);
  if (!desiredConfigOptions) {
    return;
  }

  const parsed = Object.fromEntries(
    Object.entries(desiredConfigOptions).filter((entry): entry is [string, string] => {
      const [, value] = entry;
      return typeof value === "string";
    }),
  );
  if (Object.keys(parsed).length > 0) {
    state.desired_config_options = parsed;
  }
}

function assignParsedSessionOptions(state: SessionAcpxState, raw: unknown): void {
  const sessionOptions = asRecord(raw);
  if (!sessionOptions) {
    return;
  }

  const parsedSessionOptions: NonNullable<SessionAcpxState["session_options"]> = {};
  assignSessionOptionModel(parsedSessionOptions, sessionOptions.model);
  assignSessionOptionAllowedTools(parsedSessionOptions, sessionOptions.allowed_tools);
  assignSessionOptionMaxTurns(parsedSessionOptions, sessionOptions.max_turns);
  assignSessionOptionSystemPrompt(parsedSessionOptions, sessionOptions.system_prompt);
  assignSessionOptionEnv(parsedSessionOptions, sessionOptions.env);
  assignSessionOptionPolicyBinding(
    parsedSessionOptions,
    sessionOptions.claude_execution_policy_ref,
    sessionOptions.claude_execution_policy_sha256,
  );

  if (Object.keys(parsedSessionOptions).length > 0) {
    state.session_options = parsedSessionOptions;
  }
}

function assignSessionOptionModel(
  options: NonNullable<SessionAcpxState["session_options"]>,
  value: unknown,
): void {
  if (typeof value === "string") {
    options.model = value;
  }
}

function assignSessionOptionAllowedTools(
  options: NonNullable<SessionAcpxState["session_options"]>,
  value: unknown,
): void {
  if (isStringArray(value)) {
    options.allowed_tools = [...value];
  }
}

function assignSessionOptionMaxTurns(
  options: NonNullable<SessionAcpxState["session_options"]>,
  value: unknown,
): void {
  if (typeof value === "number" && Number.isInteger(value) && value > 0) {
    options.max_turns = value;
  }
}

function assignSessionOptionSystemPrompt(
  options: NonNullable<SessionAcpxState["session_options"]>,
  value: unknown,
): void {
  if (typeof value === "string" && value.length > 0) {
    options.system_prompt = value;
    return;
  }

  const appendRecord = asRecord(value);
  if (appendRecord && typeof appendRecord.append === "string" && appendRecord.append.length > 0) {
    options.system_prompt = { append: appendRecord.append };
  }
}

function assignSessionOptionEnv(
  options: NonNullable<SessionAcpxState["session_options"]>,
  value: unknown,
): void {
  const env = asRecord(value);
  if (!env) {
    return;
  }

  const parsed = Object.fromEntries(
    Object.entries(env).filter((entry): entry is [string, string] => {
      const [, raw] = entry;
      return typeof raw === "string";
    }),
  );
  if (Object.keys(parsed).length > 0) {
    options.env = parsed;
  }
}

function assignSessionOptionPolicyBinding(
  options: NonNullable<SessionAcpxState["session_options"]>,
  ref: unknown,
  sha256: unknown,
): void {
  if (
    typeof ref === "string" &&
    ref.trim().length > 0 &&
    typeof sha256 === "string" &&
    /^[a-f0-9]{64}$/.test(sha256)
  ) {
    options.claude_execution_policy_ref = ref;
    options.claude_execution_policy_sha256 = sha256;
  }
}

function parseEventLog(raw: unknown, sessionId: string): SessionEventLog {
  const record = asRecord(raw);
  if (!record || !hasValidEventLogCore(record)) {
    return defaultSessionEventLog(sessionId);
  }

  return {
    active_path: record.active_path,
    segment_count: record.segment_count,
    max_segment_bytes: record.max_segment_bytes,
    max_segments: record.max_segments,
    last_write_at: typeof record.last_write_at === "string" ? record.last_write_at : undefined,
    last_write_error:
      record.last_write_error == null || typeof record.last_write_error === "string"
        ? record.last_write_error
        : null,
  };
}

function hasValidEventLogCore(record: Record<string, unknown>): record is Record<
  string,
  unknown
> & {
  active_path: string;
  segment_count: number;
  max_segment_bytes: number;
  max_segments: number;
} {
  return (
    typeof record.active_path === "string" &&
    isPositiveInteger(record.segment_count) &&
    isPositiveInteger(record.max_segment_bytes) &&
    isPositiveInteger(record.max_segments)
  );
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

function parseImportedFrom(raw: unknown): SessionRecord["importedFrom"] | null | undefined {
  if (raw == null) {
    return undefined;
  }

  const record = asRecord(raw);
  if (
    !record ||
    typeof record.record_id !== "string" ||
    typeof record.cwd_original !== "string" ||
    typeof record.exported_by !== "string" ||
    typeof record.exported_at !== "string"
  ) {
    return null;
  }

  return {
    recordId: record.record_id,
    cwdOriginal: record.cwd_original,
    exportedBy: record.exported_by,
    exportedAt: record.exported_at,
  };
}

function parseSessionRecordMetadata(record: Record<string, unknown>): {
  lastRequestId: string | undefined;
  importedFrom: SessionRecord["importedFrom"];
} | null {
  const lastRequestId = normalizeOptionalString(record.last_request_id);
  if (lastRequestId === null) {
    return null;
  }

  const importedFrom = parseImportedFrom(record.imported_from);
  if (importedFrom === null) {
    return null;
  }

  return { lastRequestId, importedFrom };
}

function normalizeOptionalName(value: unknown): string | undefined | null {
  if (value == null) {
    return undefined;
  }

  if (typeof value !== "string") {
    return null;
  }

  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

function normalizeOptionalPid(value: unknown): number | undefined | null {
  if (value == null) {
    return undefined;
  }

  if (!Number.isInteger(value) || (value as number) <= 0) {
    return null;
  }

  return value as number;
}

function normalizeOptionalBoolean(value: unknown, fallback = false): boolean | null {
  if (value == null) {
    return fallback;
  }
  return typeof value === "boolean" ? value : null;
}

function normalizeOptionalString(value: unknown): string | undefined | null {
  if (value == null) {
    return undefined;
  }
  return typeof value === "string" ? value : null;
}

function normalizeOptionalExitCode(value: unknown): number | null | undefined | symbol {
  if (value === undefined) {
    return undefined;
  }
  if (value === null) {
    return null;
  }
  if (Number.isInteger(value)) {
    return value as number;
  }
  return Symbol("invalid");
}

function normalizeOptionalSignal(value: unknown): NodeJS.Signals | null | undefined | symbol {
  if (value === undefined) {
    return undefined;
  }
  if (value === null) {
    return null;
  }
  if (typeof value === "string") {
    return value as NodeJS.Signals;
  }
  return Symbol("invalid");
}

export function parseSessionRecord(raw: unknown): SessionRecord | null {
  const record = asRecord(raw);
  if (!record) {
    return null;
  }

  if (record.schema !== SESSION_RECORD_SCHEMA) {
    return null;
  }

  const name = normalizeOptionalName(record.name);
  const pid = normalizeOptionalPid(record.pid);
  const closed = normalizeOptionalBoolean(record.closed, false);
  const closedAt = normalizeOptionalString(record.closed_at);
  const agentStartedAt = normalizeOptionalString(record.agent_started_at);
  const lastPromptAt = normalizeOptionalString(record.last_prompt_at);
  const lastAgentExitCode = normalizeOptionalExitCode(record.last_agent_exit_code);
  const lastAgentExitSignal = normalizeOptionalSignal(record.last_agent_exit_signal);
  const lastAgentExitAt = normalizeOptionalString(record.last_agent_exit_at);
  const lastAgentDisconnectReason = normalizeOptionalString(record.last_agent_disconnect_reason);
  const optionals = validSessionOptionals({
    name,
    pid,
    closed,
    closedAt,
    agentStartedAt,
    lastPromptAt,
    lastAgentExitCode,
    lastAgentExitSignal,
    lastAgentExitAt,
    lastAgentDisconnectReason,
  });

  if (!hasValidSessionRecordCore(record) || !optionals) {
    return null;
  }

  const conversation = parseConversationRecord(record);
  if (!conversation) {
    return null;
  }

  const eventLog = parseEventLog(record.event_log, record.acpx_record_id);
  const metadata = parseSessionRecordMetadata(record);
  if (!metadata) {
    return null;
  }

  return {
    schema: SESSION_RECORD_SCHEMA,
    acpxRecordId: record.acpx_record_id,
    acpSessionId: record.acp_session_id,
    agentSessionId: normalizeRuntimeSessionId(record.agent_session_id),
    agentCommand: record.agent_command,
    agentArgv: parsePersistedAgentArgv(record),
    cwd: record.cwd,
    name: optionals.name,
    createdAt: record.created_at,
    lastUsedAt: record.last_used_at,
    lastSeq: record.last_seq,
    lastRequestId: metadata.lastRequestId,
    eventLog,
    closed: optionals.closed,
    closedAt: optionals.closedAt,
    pid: optionals.pid,
    agentStartedAt: optionals.agentStartedAt,
    lastPromptAt: optionals.lastPromptAt,
    lastAgentExitCode: optionals.lastAgentExitCode,
    lastAgentExitSignal: optionals.lastAgentExitSignal,
    lastAgentExitAt: optionals.lastAgentExitAt,
    lastAgentDisconnectReason: optionals.lastAgentDisconnectReason,
    protocolVersion:
      typeof record.protocol_version === "number" ? record.protocol_version : undefined,
    agentCapabilities: asRecord(record.agent_capabilities) as SessionRecord["agentCapabilities"],
    title: conversation.title,
    messages: conversation.messages,
    updated_at: conversation.updated_at,
    cumulative_token_usage: conversation.cumulative_token_usage,
    cumulative_cost: conversation.cumulative_cost,
    request_token_usage: conversation.request_token_usage,
    acpx: parseAcpxState(record.acpx),
    importedFrom: metadata.importedFrom,
  };
}

function hasValidSessionRecordCore(record: Record<string, unknown>): record is Record<
  string,
  unknown
> & {
  acpx_record_id: string;
  acp_session_id: string;
  agent_command: string;
  cwd: string;
  created_at: string;
  last_used_at: string;
  last_seq: number;
} {
  return (
    hasStringFields(record, [
      "acpx_record_id",
      "acp_session_id",
      "agent_command",
      "cwd",
      "created_at",
      "last_used_at",
    ]) &&
    typeof record.last_seq === "number" &&
    Number.isInteger(record.last_seq) &&
    record.last_seq >= 0
  );
}

type NormalizedSessionOptionals = {
  name: string | undefined | null;
  pid: number | undefined | null;
  closed: boolean | null;
  closedAt: string | undefined | null;
  agentStartedAt: string | undefined | null;
  lastPromptAt: string | undefined | null;
  lastAgentExitCode: number | null | undefined | symbol;
  lastAgentExitSignal: NodeJS.Signals | null | undefined | symbol;
  lastAgentExitAt: string | undefined | null;
  lastAgentDisconnectReason: string | undefined | null;
};

type ValidSessionOptionals = {
  name: string | undefined;
  pid: number | undefined;
  closed: boolean;
  closedAt: string | undefined;
  agentStartedAt: string | undefined;
  lastPromptAt: string | undefined;
  lastAgentExitCode: number | null | undefined;
  lastAgentExitSignal: NodeJS.Signals | null | undefined;
  lastAgentExitAt: string | undefined;
  lastAgentDisconnectReason: string | undefined;
};

function validSessionOptionals(options: NormalizedSessionOptionals): ValidSessionOptionals | null {
  if (hasNullOptionalSessionFields(options) || hasInvalidExitStatus(options)) {
    return null;
  }
  return options as ValidSessionOptionals;
}

function hasNullOptionalSessionFields(options: NormalizedSessionOptionals): boolean {
  return [
    options.name,
    options.pid,
    options.closed,
    options.closedAt,
    options.agentStartedAt,
    options.lastPromptAt,
    options.lastAgentExitAt,
    options.lastAgentDisconnectReason,
  ].some((value) => value === null);
}

function hasInvalidExitStatus(options: NormalizedSessionOptionals): boolean {
  return (
    typeof options.lastAgentExitCode === "symbol" || typeof options.lastAgentExitSignal === "symbol"
  );
}

import { statSync } from "node:fs";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { SessionNotFoundError, SessionResolutionError } from "../../errors.js";
import { incrementPerfCounter, measurePerf } from "../../perf-metrics.js";
import { assertPersistedKeyPolicy } from "../../persisted-key-policy.js";
import type { SessionRecord } from "../../types.js";
import { createAtomicWriteTempPath } from "./atomic-write.js";
import {
  loadOrRebuildSessionIndex,
  rebuildSessionIndex,
  toSessionIndexEntry,
  writeSessionIndex,
  type SessionIndexEntry,
} from "./index.js";
import { parseSessionRecord } from "./parse.js";
import { serializeSessionRecordForDisk } from "./serialize.js";

export const DEFAULT_HISTORY_LIMIT = 20;

type FindSessionOptions = {
  agentCommand: string;
  cwd: string;
  name?: string;
  includeClosed?: boolean;
};

type FindSessionByDirectoryWalkOptions = {
  agentCommand: string;
  cwd: string;
  name?: string;
  boundary?: string;
};

function sessionFilePath(acpxRecordId: string): string {
  const safeId = encodeURIComponent(acpxRecordId);
  return path.join(sessionBaseDir(), `${safeId}.json`);
}

function sessionBaseDir(): string {
  return path.join(os.homedir(), ".acpx", "sessions");
}

async function ensureSessionDir(): Promise<void> {
  await fs.mkdir(sessionBaseDir(), { recursive: true });
}

async function loadRecordFromIndexEntry(
  entry: SessionIndexEntry,
): Promise<SessionRecord | undefined> {
  try {
    const payload = await fs.readFile(path.join(sessionBaseDir(), entry.file), "utf8");
    return parseSessionRecord(JSON.parse(payload)) ?? undefined;
  } catch {
    return undefined;
  }
}

async function loadSessionIndexEntries(): Promise<SessionIndexEntry[]> {
  await ensureSessionDir();
  const index = await measurePerf("session.index_load", async () => {
    return await loadOrRebuildSessionIndex(sessionBaseDir());
  });
  return index.entries;
}

function matchesSessionEntry(
  session: SessionIndexEntry,
  normalizedCwd: string,
  normalizedName: string | undefined,
  includeClosed = false,
): boolean {
  if (session.cwd !== normalizedCwd) {
    return false;
  }
  if (!includeClosed && session.closed) {
    return false;
  }
  if (normalizedName == null) {
    return session.name == null;
  }
  return session.name === normalizedName;
}

export async function writeSessionRecord(record: SessionRecord): Promise<void> {
  await measurePerf("session.write_record", async () => {
    await ensureSessionDir();

    const persisted = serializeSessionRecordForDisk(record);
    assertPersistedKeyPolicy(persisted);

    const file = sessionFilePath(record.acpxRecordId);
    const tempFile = createAtomicWriteTempPath(file);
    const payload = JSON.stringify(persisted, null, 2);
    await fs.writeFile(tempFile, `${payload}\n`, "utf8");
    await fs.rename(tempFile, file);

    const sessionDir = sessionBaseDir();
    const index = await loadOrRebuildSessionIndex(sessionDir);
    const fileName = path.basename(file);
    const entries = index.entries.filter((entry) => entry.file !== fileName);
    entries.push(toSessionIndexEntry(record, fileName));
    const files = [...new Set([...index.files.filter((entry) => entry !== fileName), fileName])];
    await writeSessionIndex(sessionDir, { files, entries });
  });
}

export async function resolveSessionRecord(sessionId: string): Promise<SessionRecord> {
  await ensureSessionDir();

  const directPath = sessionFilePath(sessionId);
  try {
    const directPayload = await measurePerf("session.resolve_direct", async () => {
      return await fs.readFile(directPath, "utf8");
    });
    const directRecord = parseSessionRecord(JSON.parse(directPayload));
    if (directRecord) {
      return directRecord;
    }
  } catch {
    // fallback to indexed search
  }

  const entries = await loadSessionIndexEntries();
  const exactEntries = entries.filter(
    (entry) => entry.acpxRecordId === sessionId || entry.acpSessionId === sessionId,
  );
  const exactRecords = (
    await Promise.all(exactEntries.map((entry) => loadRecordFromIndexEntry(entry)))
  ).filter((entry): entry is SessionRecord => Boolean(entry));
  if (exactRecords.length === 1) {
    return exactRecords[0];
  }
  if (exactRecords.length > 1) {
    throw new SessionResolutionError(`Multiple sessions match id: ${sessionId}`);
  }

  const suffixEntries = entries.filter(
    (entry) => entry.acpxRecordId.endsWith(sessionId) || entry.acpSessionId.endsWith(sessionId),
  );
  const suffixRecords = (
    await Promise.all(suffixEntries.map((entry) => loadRecordFromIndexEntry(entry)))
  ).filter((entry): entry is SessionRecord => Boolean(entry));
  if (suffixRecords.length === 1) {
    return suffixRecords[0];
  }
  if (suffixRecords.length > 1) {
    throw new SessionResolutionError(`Session id is ambiguous: ${sessionId}`);
  }

  incrementPerfCounter("session.resolve_miss");
  throw new SessionNotFoundError(sessionId);
}

function hasGitDirectory(dir: string): boolean {
  const gitPath = path.join(dir, ".git");
  try {
    return statSync(gitPath).isDirectory();
  } catch {
    return false;
  }
}

function isWithinBoundary(boundary: string, target: string): boolean {
  const relative = path.relative(boundary, target);
  return relative.length === 0 || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

export function absolutePath(value: string): string {
  return path.resolve(value);
}

export function findGitRepositoryRoot(startDir: string): string | undefined {
  let current = absolutePath(startDir);
  const root = path.parse(current).root;

  for (;;) {
    if (hasGitDirectory(current)) {
      return current;
    }

    if (current === root) {
      return undefined;
    }

    const parent = path.dirname(current);
    if (parent === current) {
      return undefined;
    }
    current = parent;
  }
}

export function normalizeName(value: string | undefined): string | undefined {
  if (value == null) {
    return undefined;
  }

  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

export function isoNow(): string {
  return new Date().toISOString();
}

export async function listSessions(): Promise<SessionRecord[]> {
  await ensureSessionDir();
  const entries = await loadSessionIndexEntries();
  const records: SessionRecord[] = [];

  for (const entry of entries) {
    const parsed = await loadRecordFromIndexEntry(entry);
    if (parsed) {
      records.push(parsed);
    }
  }

  records.sort((a, b) => b.lastUsedAt.localeCompare(a.lastUsedAt));
  return records;
}

export async function listSessionsForAgent(agentCommand: string): Promise<SessionRecord[]> {
  const entries = (await loadSessionIndexEntries()).filter(
    (session) => session.agentCommand === agentCommand,
  );
  const records = await Promise.all(entries.map((entry) => loadRecordFromIndexEntry(entry)));
  return records
    .filter((entry): entry is SessionRecord => Boolean(entry))
    .toSorted((a, b) => b.lastUsedAt.localeCompare(a.lastUsedAt));
}

export async function findSession(options: FindSessionOptions): Promise<SessionRecord | undefined> {
  const normalizedCwd = absolutePath(options.cwd);
  const normalizedName = normalizeName(options.name);
  const entries = await loadSessionIndexEntries();
  const match = entries.find(
    (session) =>
      session.agentCommand === options.agentCommand &&
      matchesSessionEntry(session, normalizedCwd, normalizedName, options.includeClosed),
  );
  if (!match) {
    return undefined;
  }
  return await loadRecordFromIndexEntry(match);
}

export async function findSessionByDirectoryWalk(
  options: FindSessionByDirectoryWalkOptions,
): Promise<SessionRecord | undefined> {
  const normalizedName = normalizeName(options.name);
  const normalizedStart = absolutePath(options.cwd);
  const normalizedBoundary = absolutePath(options.boundary ?? normalizedStart);
  const walkBoundary = isWithinBoundary(normalizedBoundary, normalizedStart)
    ? normalizedBoundary
    : normalizedStart;
  const sessions = (await loadSessionIndexEntries()).filter(
    (session) => session.agentCommand === options.agentCommand,
  );

  let current = normalizedStart;
  const walkRoot = path.parse(current).root;

  for (;;) {
    const match = sessions.find((session) => matchesSessionEntry(session, current, normalizedName));
    if (match) {
      return await loadRecordFromIndexEntry(match);
    }

    const parent = nextWalkParent(current, walkBoundary, walkRoot);
    if (!parent) {
      return undefined;
    }
    current = parent;
  }
}

function nextWalkParent(
  current: string,
  walkBoundary: string,
  walkRoot: string,
): string | undefined {
  if (current === walkBoundary || current === walkRoot) {
    return undefined;
  }

  const parent = path.dirname(current);
  if (parent === current || !isWithinBoundary(walkBoundary, parent)) {
    return undefined;
  }

  return parent;
}

function killSignalCandidates(signal: NodeJS.Signals | undefined): NodeJS.Signals[] {
  if (!signal) {
    return ["SIGTERM", "SIGKILL"];
  }

  const normalized = signal.toUpperCase() as NodeJS.Signals;
  if (normalized === "SIGKILL") {
    return ["SIGKILL"];
  }

  return [normalized, "SIGKILL"];
}

export type PruneOptions = {
  agentCommand?: string;
  before?: Date;
  olderThanMs?: number;
  includeHistory?: boolean;
  dryRun?: boolean;
};

export type PruneResult = {
  pruned: SessionRecord[];
  bytesFreed: number;
  dryRun: boolean;
};

function closedAtOrLastUsedAt(record: SessionRecord): string {
  return record.closedAt ?? record.lastUsedAt;
}

function isSessionStreamFile(fileName: string, safeId: string): boolean {
  return (
    fileName === `${safeId}.stream.ndjson` ||
    fileName === `${safeId}.stream.lock` ||
    fileName.startsWith(`${safeId}.stream.`)
  );
}

export async function pruneSessions(options: PruneOptions = {}): Promise<PruneResult> {
  await ensureSessionDir();
  const entries = await loadSessionIndexEntries();

  const eligible = filterPruneCandidates(entries, options.agentCommand);

  const cutoff =
    options.before ??
    (options.olderThanMs != null ? new Date(Date.now() - options.olderThanMs) : undefined);

  const records = await loadPrunableRecords(eligible, cutoff);

  if (options.dryRun) {
    return { pruned: records, bytesFreed: 0, dryRun: true };
  }

  const sessionDir = sessionBaseDir();
  let bytesFreed = 0;

  // Read the directory once upfront so stream-file matching doesn't re-read
  // it for every session in the loop.
  let dirEntries: string[] = [];
  if (options.includeHistory) {
    try {
      dirEntries = await fs.readdir(sessionDir);
    } catch {
      // ignore
    }
  }

  for (const record of records) {
    bytesFreed += await pruneSessionFiles(
      record,
      sessionDir,
      dirEntries,
      options.includeHistory === true,
    );
  }

  await rebuildSessionIndex(sessionDir).catch(() => {
    // best effort cache rebuild
  });

  return { pruned: records, bytesFreed, dryRun: false };
}

function filterPruneCandidates(
  entries: SessionIndexEntry[],
  agentCommand: string | undefined,
): SessionIndexEntry[] {
  return entries.filter(
    (entry) => entry.closed && (!agentCommand || entry.agentCommand === agentCommand),
  );
}

async function loadPrunableRecords(
  entries: SessionIndexEntry[],
  cutoff: Date | undefined,
): Promise<SessionRecord[]> {
  const records: SessionRecord[] = [];
  const cutoffIso = cutoff?.toISOString();
  for (const entry of entries) {
    const record = await loadRecordFromIndexEntry(entry);
    if (record && isBeforeCutoff(record, cutoffIso)) {
      records.push(record);
    }
  }
  return records;
}

function isBeforeCutoff(record: SessionRecord, cutoffIso: string | undefined): boolean {
  return !cutoffIso || closedAtOrLastUsedAt(record) < cutoffIso;
}

async function pruneSessionFiles(
  record: SessionRecord,
  sessionDir: string,
  dirEntries: string[],
  includeHistory: boolean,
): Promise<number> {
  const safeId = encodeURIComponent(record.acpxRecordId);
  let bytesFreed = await unlinkCountingBytes(path.join(sessionDir, `${safeId}.json`));
  if (includeHistory) {
    for (const name of dirEntries.filter((entry) => isSessionStreamFile(entry, safeId))) {
      bytesFreed += await unlinkCountingBytes(path.join(sessionDir, name));
    }
  }
  return bytesFreed;
}

async function unlinkCountingBytes(filePath: string): Promise<number> {
  let bytes = 0;
  try {
    const stat = await fs.stat(filePath);
    bytes = stat.size;
  } catch {
    // file already gone
  }
  await fs.unlink(filePath).catch(() => undefined);
  return bytes;
}

export async function closeSession(id: string): Promise<SessionRecord> {
  const record = await resolveSessionRecord(id);
  const now = isoNow();

  if (record.pid) {
    for (const signal of killSignalCandidates(record.lastAgentExitSignal ?? undefined)) {
      try {
        process.kill(record.pid, signal);
      } catch {
        // ignore
      }
    }
  }

  record.closed = true;
  record.closedAt = now;
  record.pid = undefined;
  record.lastUsedAt = now;
  record.lastPromptAt = record.lastPromptAt ?? now;

  await writeSessionRecord(record);
  await rebuildSessionIndex(sessionBaseDir()).catch(() => {
    // best effort cache rebuild
  });
  return record;
}

export { serializeSessionRecordForDisk } from "./persistence/serialize.js";
export { parseSessionRecord } from "./persistence/parse.js";
export {
  DEFAULT_HISTORY_LIMIT,
  absolutePath,
  closeSession,
  findGitRepositoryRoot,
  findSession,
  findSessionByDirectoryWalk,
  isoNow,
  listSessions,
  listSessionsForAgent,
  normalizeName,
  pruneSessions,
  resolveSessionRecord,
  writeSessionRecord,
} from "./persistence/repository.js";
export type { PruneOptions, PruneResult } from "./persistence/repository.js";

