      "--yes",
      `--package=${BUILT_IN_AGENT_PACKAGES.codex.packageName}@${BUILT_IN_AGENT_PACKAGES.codex.packageRange}`,
      "--",
      BUILT_IN_AGENT_PACKAGES.codex.preferredBinName,
