            },
          },
        },
        null,
        2,
      )}\n`,
      "utf8",
    );

    const sessionId = "mode-replay-session";
    await writeSessionRecord(homeDir, {
      acpxRecordId: sessionId,
      acpSessionId: sessionId,
      agentCommand: MOCK_AGENT_WITH_LOAD_FALLBACK,
      cwd,
      createdAt: "2026-01-01T00:00:00.000Z",
