        {
          defaultAgent: "codex",
          defaultPermissions: "deny-all",
          nonInteractivePermissions: "fail",
          authPolicy: "fail",
          ttl: 15,
          timeout: 30,
          queueMaxDepth: 9,
          format: "json",
          agents: {
            custom: { command: "global-custom" },
          },
