      "utf8",
    );

    await fs.writeFile(
      path.join(cwd, ".acpxrc.json"),
      `${JSON.stringify(
        {
          defaultPermissions: "approve-all",
          nonInteractivePermissions: "deny",
          authPolicy: "skip",
          ttl: 42,
          timeout: null,
          queueMaxDepth: 5,
