            project_method: "project-token",
          },
          mcpServers: [
            {
              name: "project-stdio",
              type: "stdio",
              command: "./bin/project-mcp",
              args: ["--serve"],
              env: [{ name: "TOKEN", value: "secret" }],
            },
          ],
