import assert from "node:assert/strict";
import test from "node:test";
import {
  exitCodeForOutputErrorCode,
  normalizeOutputError,
  isAcpQueryClosedBeforeResponseError,
  isAcpResourceNotFoundError,
} from "../src/acp/error-normalization.js";
import {
  PermissionPromptUnavailableError,
  QueueConnectionError,
  AuthPolicyError,
} from "../src/errors.js";

test("normalizeOutputError maps permission prompt unavailable errors", () => {
  const normalized = normalizeOutputError(new PermissionPromptUnavailableError(), {
    origin: "runtime",
  });

  assert.equal(normalized.code, "PERMISSION_PROMPT_UNAVAILABLE");
  assert.equal(normalized.origin, "runtime");
  assert.match(normalized.message, /Permission prompt unavailable/i);
});

test("normalizeOutputError maps ACP resource not found errors to NO_SESSION", () => {
  const error = {
    code: -32002,
    message: "Resource not found: session",
    data: {
      sessionId: "abc",
    },
  };

  const normalized = normalizeOutputError(error, {
    origin: "acp",
  });

  assert.equal(normalized.code, "NO_SESSION");
  assert.equal(normalized.origin, "acp");
  assert.deepEqual(normalized.acp, {
    code: -32002,
    message: "Resource not found: session",
    data: {
      sessionId: "abc",
    },
  });
  assert.equal(isAcpResourceNotFoundError(error), true);
});

test("isAcpResourceNotFoundError recognizes session-not-found hints in nested errors", () => {
  assert.equal(
    isAcpResourceNotFoundError({
      cause: {
        message: "session not found while reconnecting",
      },
    }),
    true,
  );
});

test("isAcpResourceNotFoundError recognizes Cursor session-not-found format", () => {
  // Cursor returns: {"code":-32602,"message":"Invalid params","data":{"message":"Session \"xxx\" not found"}}
  const cursorError = {
    code: -32602,
    message: "Invalid params",
    data: {
      message: 'Session "nonexistent-session-id" not found',
    },
  };

  assert.equal(isAcpResourceNotFoundError(cursorError), true);
});
test("isAcpQueryClosedBeforeResponseError matches typed ACP payload", () => {
  const error = {
    code: -32603,
    message: "Internal error",
    data: {
      details: "Query closed before response received",
    },
  };

  assert.equal(isAcpQueryClosedBeforeResponseError(error), true);
});

test("isAcpQueryClosedBeforeResponseError ignores unrelated ACP errors", () => {
  const error = {
    code: -32603,
    message: "Internal error",
    data: {
      details: "other detail",
    },
  };

  assert.equal(isAcpQueryClosedBeforeResponseError(error), false);
});

test("normalizeOutputError preserves queue metadata from typed queue errors", () => {
  const error = new QueueConnectionError("Queue denied control request", {
    outputCode: "PERMISSION_DENIED",
    detailCode: "QUEUE_CONTROL_REQUEST_FAILED",
    origin: "queue",
    retryable: false,
  });

  const normalized = normalizeOutputError(error);
  assert.equal(normalized.code, "PERMISSION_DENIED");
  assert.equal(normalized.detailCode, "QUEUE_CONTROL_REQUEST_FAILED");
  assert.equal(normalized.origin, "queue");
  assert.equal(normalized.retryable, false);
});

test("normalizeOutputError maps AuthPolicyError to AUTH_REQUIRED detail", () => {
  const normalized = normalizeOutputError(
    new AuthPolicyError("missing credentials for auth method token"),
  );

  assert.equal(normalized.code, "RUNTIME");
  assert.equal(normalized.detailCode, "AUTH_REQUIRED");
  assert.equal(normalized.origin, "acp");
});

test("normalizeOutputError infers AUTH_REQUIRED detail from ACP payload", () => {
  const normalized = normalizeOutputError({
    error: {
      code: -32000,
      message: "Authentication required",
      data: {
        methodId: "token",
      },
    },
  });

  assert.equal(normalized.code, "RUNTIME");
  assert.equal(normalized.detailCode, "AUTH_REQUIRED");
  assert.equal(normalized.acp?.code, -32000);
});

test("normalizeOutputError extracts ACP payload from wrapped errors", () => {
  const wrapped = new Error("Agent rejected session/set_mode");
  (
    wrapped as Error & {
      acp?: { code: number; message: string; data?: unknown };
    }
  ).acp = {
    code: -32602,
    message: "Invalid params",
    data: {
      method: "session/set_mode",
      modeId: "plan",
    },
  };

  const normalized = normalizeOutputError(wrapped);

  assert.equal(normalized.code, "RUNTIME");
  assert.equal(normalized.acp?.code, -32602);
  assert.deepEqual(normalized.acp?.data, {
    method: "session/set_mode",
    modeId: "plan",
  });
});

test("exitCodeForOutputErrorCode maps machine codes to stable exits", () => {
  assert.equal(exitCodeForOutputErrorCode("USAGE"), 2);
  assert.equal(exitCodeForOutputErrorCode("TIMEOUT"), 3);
  assert.equal(exitCodeForOutputErrorCode("NO_SESSION"), 4);
  assert.equal(exitCodeForOutputErrorCode("PERMISSION_DENIED"), 5);
  assert.equal(exitCodeForOutputErrorCode("PERMISSION_PROMPT_UNAVAILABLE"), 5);
  assert.equal(exitCodeForOutputErrorCode("RUNTIME"), 1);
});

.tools/acpx-e1/source/test/events.test.t:
import assert from "node:assert/strict";
import test from "node:test";
import {
  isAcpMessageObject,
  isAcpJsonRpcMessage,
  isJsonRpcNotification,
  isSessionUpdateNotification,
  parseJsonRpcErrorMessage,
  parsePromptStopReason,
} from "../src/acp/jsonrpc.js";

test("isAcpMessageObject rejects non-object JSON values", () => {
  assert.equal(isAcpMessageObject(1), false);
  assert.equal(isAcpMessageObject(null), false);
  assert.equal(isAcpMessageObject("message"), false);
  assert.equal(isAcpMessageObject([]), false);
});

test("isAcpMessageObject accepts object-shaped protocol values", () => {
  assert.equal(isAcpMessageObject({}), true);
  assert.equal(isAcpMessageObject({ jsonrpc: "2.0", method: "session/update" }), true);
});

test("isAcpJsonRpcMessage accepts JSON-RPC request", () => {
  assert.equal(
    isAcpJsonRpcMessage({
      jsonrpc: "2.0",
      id: "req-1",
      method: "session/prompt",
      params: {
        sessionId: "session-1",
        prompt: [{ type: "text", text: "hi" }],
      },
    }),
    true,
  );
});

test("isAcpJsonRpcMessage accepts JSON-RPC notification", () => {
  assert.equal(
    isAcpJsonRpcMessage({
      jsonrpc: "2.0",
      method: "session/update",
      params: {
        sessionId: "session-1",
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: "hello" },
        },
      },
    }),
    true,
  );
});

test("isAcpJsonRpcMessage accepts JSON-RPC success response", () => {
  assert.equal(
    isAcpJsonRpcMessage({
      jsonrpc: "2.0",
      id: "req-1",
      result: { stopReason: "end_turn" },
    }),
    true,
  );
});

test("isAcpJsonRpcMessage accepts JSON-RPC error response", () => {
  assert.equal(
    isAcpJsonRpcMessage({
      jsonrpc: "2.0",
      id: "req-1",
      error: {
        code: -32000,
        message: "runtime error",
      },
    }),
    true,
  );
});

test("isAcpJsonRpcMessage rejects non-JSON-RPC payload", () => {
  assert.equal(
    isAcpJsonRpcMessage({
      type: "custom_event",
      content: "hello",
    }),
    false,
  );
});

test("isAcpJsonRpcMessage rejects invalid request and response shapes", () => {
  assert.equal(
    isAcpJsonRpcMessage({
      jsonrpc: "2.0",
      id: {},
      method: "session/prompt",
    }),
    false,
  );

  assert.equal(
    isAcpJsonRpcMessage({
      jsonrpc: "2.0",
      id: "req-1",
      result: {},
      error: {
        code: -32000,
        message: "runtime error",
      },
    }),
    false,
  );

  assert.equal(
    isAcpJsonRpcMessage({
      jsonrpc: "2.0",
      id: "req-1",
      error: {
        code: "bad",
        message: "runtime error",
      },
    }),
    false,
  );
});

test("isAcpJsonRpcMessage accepts request/notification/response fixtures after roundtrip", () => {
  const fixtures: unknown[] = [
    {
      jsonrpc: "2.0",
      id: "req-1",
      method: "session/prompt",
      params: {
        sessionId: "session-1",
        prompt: [{ type: "text", text: "hi" }],
      },
    },
    {
      jsonrpc: "2.0",
      method: "session/update",
      params: {
        sessionId: "session-1",
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: "hello" },
        },
      },
    },
    {
      jsonrpc: "2.0",
      id: "req-2",
      result: { stopReason: "end_turn" },
    },
    {
      jsonrpc: "2.0",
      id: "req-3",
      error: {
        code: -32000,
        message: "runtime error",
      },
    },
  ];

  for (const fixture of fixtures) {
    const roundTripped = JSON.parse(JSON.stringify(fixture));
    assert.equal(isAcpJsonRpcMessage(roundTripped), true);
  }
});

test("isSessionUpdateNotification matches session/update notifications only", () => {
  assert.equal(
    isSessionUpdateNotification({
      jsonrpc: "2.0",
      method: "session/update",
      params: {
        sessionId: "session-1",
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: "hello" },
        },
      },
    }),
    true,
  );

  assert.equal(
    isSessionUpdateNotification({
      jsonrpc: "2.0",
      id: "req-1",
      method: "session/prompt",
      params: {
        sessionId: "session-1",
        prompt: [{ type: "text", text: "hello" }],
      },
    }),
    false,
  );

  assert.equal(
    isSessionUpdateNotification({
      jsonrpc: "2.0",
      id: "req-2",
      result: { stopReason: "end_turn" },
    }),
    false,
  );
});

test("notification and response helpers parse expected fields only", () => {
  const notification = {
    jsonrpc: "2.0",
    method: "session/update",
    params: {
      sessionId: "session-1",
    },
  } as const;
  assert.equal(isJsonRpcNotification(notification), true);

  const response = {
    jsonrpc: "2.0",
    id: "req-1",
    result: { stopReason: "end_turn" },
  } as const;
  assert.equal(parsePromptStopReason(response), "end_turn");
  assert.equal(parsePromptStopReason(notification as never), undefined);

  const errorResponse = {
    jsonrpc: "2.0",
    id: "req-2",
    error: {
      code: -32000,
      message: "bad request",
    },
  } as const;
  assert.equal(parseJsonRpcErrorMessage(errorResponse), "bad request");
  assert.equal(parseJsonRpcErrorMessage(response as never), undefined);
  assert.equal(
    parseJsonRpcErrorMessage({
      jsonrpc: "2.0",
      id: "req-3",
      error: {
        code: -32000,
      },
    } as never),
    undefined,
  );
});

