    ],
  );

  assert.deepEqual(mergePromptSourceWithText("   ", "world"), [{ type: "text", text: "world" }]);
  assert.deepEqual(mergePromptSourceWithText("hello", "   "), [{ type: "text", text: "hello" }]);
});

test("promptToDisplayText renders text, resources, and images", () => {
