import fs from "node:fs/promises";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import { AcpClient } from "../src/acp/client.js";
import { createOutputFormatter } from "../src/cli/output/output.js";
import {
  runSessionSetConfigOptionDirect,
  runSessionSetModelDirect,
  runSessionSetModeDirect,
} from "../src/cli/session/prompt-runner.js";
import { sendSessionDirect } from "../src/cli/session/runtime.js";
import { resolveSessionRecord } from "../src/session/persistence/repository.js";
import {
  makeSessionRecord as makeSessionRecordFixture,
  sessionFilePath,
  withTempHome as withTempHomeFixture,
  writeSessionRecordFile as writeSessionRecord,
} from "./runtime-test-helpers.js";

const MOCK_AGENT_PATH = fileURLToPath(new URL("./mock-agent.js", import.meta.url));

test("sendSessionDirect rejects an unbound request before changing a bound record", async () => {
  await withTempHome(async (homeDir) => {
    const cwd = path.join(homeDir, "workspace");
    await fs.mkdir(cwd, { recursive: true });
    const record = makeSessionRecord({
      acpxRecordId: "direct-policy-conflict",
      acpSessionId: "direct-policy-conflict-backend",
      agentCommand: `node ${JSON.stringify(MOCK_AGENT_PATH)} --supports-load-session`,
      cwd,
      acpx: {
        session_options: {
          claude_execution_policy_ref: "runs/run-1/execution-authority/policy.json",
          claude_execution_policy_sha256: "a".repeat(64),
        },
      },
    });
    await writeSessionRecord(homeDir, record);
    const recordPath = sessionFilePath(homeDir, record.acpxRecordId);
    const before = await fs.readFile(recordPath, "utf8");

    await assert.rejects(
      sendSessionDirect({
        sessionId: record.acpxRecordId,
        prompt: [{ type: "text", text: "must not be recorded" }],
        permissionMode: "approve-all",
        outputFormatter: createOutputFormatter("quiet"),
        timeoutMs: 5_000,
      }),
      /CLAUDE_EXECUTION_POLICY_CONFLICT/,
    );

    assert.equal(await fs.readFile(recordPath, "utf8"), before);
  });
});

test("sendSessionDirect checkpoints replacement options after a fresh-session fallback", async () => {
  await withTempHome(async (homeDir) => {
    const cwd = path.join(homeDir, "workspace");
    await fs.mkdir(cwd, { recursive: true });
    const agentCommand = `node ${JSON.stringify(MOCK_AGENT_PATH)} --supports-load-session --load-session-fails-on-empty`;
    const policyRef = "runs/run-1/execution-authority/policy.json";
    const policySha256 = "a".repeat(64);
    const record = makeSessionRecord({
      acpxRecordId: "direct-fresh-policy-replacement",
      acpSessionId: "stale-policy-session",
      agentCommand,
      cwd,
      messages: [],
      acpx: {
        session_options: {
          allowed_tools: ["OldTool"],
          claude_execution_policy_ref: policyRef,
          claude_execution_policy_sha256: policySha256,
        },
      },
    });
    await writeSessionRecord(homeDir, record);
    const client = new AcpClient({
      agentCommand,
      cwd,
      permissionMode: "approve-all",
    });

    try {
      await sendSessionDirect({
        sessionId: record.acpxRecordId,
        prompt: [{ type: "text", text: "checkpoint the fresh session" }],
        permissionMode: "approve-all",
        outputFormatter: createOutputFormatter("quiet"),
        client,
        timeoutMs: 5_000,
        sessionOptions: {
          allowedTools: ["Read"],
          claudeExecutionPolicyRef: policyRef,
          claudeExecutionPolicySha256: policySha256,
        },
      });
    } finally {
      await client.close();
    }

    const persisted = await resolveSessionRecord(record.acpxRecordId);
    assert.notEqual(persisted.acpSessionId, "stale-policy-session");
    assert.deepEqual(persisted.acpx?.session_options, {
      allowed_tools: ["Read"],
      claude_execution_policy_ref: policyRef,
      claude_execution_policy_sha256: policySha256,
    });
  });
});

test("sendSessionDirect closes a shared client after reconnect preference failure", async () => {
  await withTempHome(async (homeDir) => {
    const cwd = path.join(homeDir, "workspace");
    await fs.mkdir(cwd, { recursive: true });
    const record = makeSessionRecord({
      acpxRecordId: "failed-shared-reconnect",
      acpSessionId: "failed-shared-reconnect-backend",
      agentCommand: `node ${JSON.stringify(MOCK_AGENT_PATH)} --supports-load-session --advertise-models`,
      cwd,
      acpx: { session_options: { model: "unavailable-saved-model" } },
    });
    await writeSessionRecord(homeDir, record);
    const client = new AcpClient({
      agentCommand: record.agentCommand,
      cwd,
      permissionMode: "approve-all",
    });
    try {
      await assert.rejects(
        sendSessionDirect({
          sessionId: record.acpxRecordId,
