      ({
        sourceType: "recent",
        label: run.runId,
      }) as never,
    listRecentRuns: async () => [firstRun],
    loadRunBundle: async (reader) => {
      if ((reader as { label?: string }).label === firstRun.runId) {
        return firstLoad;
      }
      if ((reader as { label?: string }).label === secondRun.runId) {
        return secondLoad;
      }
      throw new Error("Unexpected recent run reader");
