        state: buildViewerRunsState([secondRun, firstRun]),
      });
      await flushReactWork();
    });

    await act(async () => {
      resolveSecondLoad(secondBundle);
      await secondLoad;
      await flushReactWork();
    });

    assert.equal(renderedRuns, 2);
    assert.equal(renderedRunId, secondRun.runId);

    await act(async () => {
      resolveFirstLoad(firstBundle);
      await firstLoad;
      await flushReactWork();
    });

