  assert.deepEqual(await iterator.next(), {
    done: true,
    value: undefined,
  });
  assert.deepEqual(await turn.result, {
    status: "completed",
    stopReason: "end_turn",
  });
  assert.deepEqual(await iterator.next(), {
    done: true,
    value: undefined,
  });
});

