  assert.deepEqual(liveStatusAfterTurn.details?.configOptions, expectedConfigOptions);
  assert.equal(cancelRequested, 1);
  assert.deepEqual(events, []);
  assert.deepEqual(result, { status: "cancelled", stopReason: "cancelled" });
