package dev.dual.adapter.acpx;

import dev.dual.core.execution.AdapterSignalType;

/**
 * acpx adapter 输出的稳定失败语义。
 *
 * Provider 或 ACP wrapper 的原始错误文案可以变化，但进入 runtime/ledger
 * 之前必须先归一化成这里的 reason。这样 workflow 和 recovery 只消费
 * typed failure fact，不依赖供应商自然语言。
 */
enum AcpxFailureReason {
    AGENT_MODEL_MISMATCH("RECOVERABLE_AGENT_MODEL_MISMATCH"),
    AGENT_OVERLOADED("RECOVERABLE_AGENT_OVERLOADED"),
    AGENT_RECONNECT("RECOVERABLE_AGENT_RECONNECT"),
    AGENT_OUTPUT_INTERRUPTED("RECOVERABLE_AGENT_OUTPUT_INTERRUPTED"),
    AGENT_PERMISSION_BLOCKED("RECOVERABLE_AGENT_PERMISSION_BLOCKED"),
    AGENT_AUTH_FAILED("RECOVERABLE_AGENT_AUTH_FAILED"),
    PROVIDER_CONNECTION_FAILED("RECOVERABLE_PROVIDER_CONNECTION_FAILED"),
    SESSION_BOOTSTRAP_FAILED("RECOVERABLE_SESSION_BOOTSTRAP_FAILED"),
    SESSION_MISSING("RECOVERABLE_SESSION_MISSING"),
    RATE_LIMIT("RECOVERABLE_RATE_LIMIT"),
    CONTEXT_WINDOW("RECOVERABLE_CONTEXT_WINDOW"),
    TRANSPORT_FAILED("RECOVERABLE_TRANSPORT_FAILED");

    private final String code;

    AcpxFailureReason(String code) {
        this.code = code;
    }

    String code() {
        return code;
    }

    AdapterSignalType adapterSignalType() {
        return switch (this) {
            case AGENT_MODEL_MISMATCH -> AdapterSignalType.MODEL_MISMATCH;
            case AGENT_OVERLOADED, RATE_LIMIT -> AdapterSignalType.RATE_LIMITED;
            case AGENT_RECONNECT -> AdapterSignalType.AGENT_RECONNECT_REQUIRED;
            case AGENT_OUTPUT_INTERRUPTED, TRANSPORT_FAILED -> AdapterSignalType.PROCESS_STALLED;
            case AGENT_PERMISSION_BLOCKED -> AdapterSignalType.PERMISSION_BLOCKED;
            case AGENT_AUTH_FAILED -> AdapterSignalType.AUTH_FAILED;
            case PROVIDER_CONNECTION_FAILED -> AdapterSignalType.PROVIDER_CONNECTION_FAILED;
            case SESSION_BOOTSTRAP_FAILED -> AdapterSignalType.SESSION_BOOTSTRAP_FAILED;
            case SESSION_MISSING -> AdapterSignalType.SESSION_RESUME_FAILED;
            case CONTEXT_WINDOW -> AdapterSignalType.CONTEXT_WINDOW_EXCEEDED;
        };
    }
}

package dev.dual.adapter.acpx;

import dev.dual.core.execution.AdapterSignal;

import java.util.List;

record AcpxFailureSignal(
        String id,
        AcpxFailureReason reason,
        int priority,
        String message,
        boolean recoverable,
        boolean interruptRunningProcess,
        List<Matcher> matchers
) {
    boolean matches(AcpxFailureEvidence evidence) {
        var text = evidence.combinedTextLowercase();
        return matchers.stream().anyMatch(matcher -> matcher.matches(text));
    }

    AdapterSignal toAdapterSignal(long sequence, String source) {
        return new AdapterSignal(reason.adapterSignalType(), message, sequence, source, "", false);
    }

    static Matcher contains(String text) {
        return new Matcher(text == null ? "" : text.toLowerCase());
    }

    record Matcher(String needle) {
        boolean matches(String text) {
            return !needle.isBlank() && text.contains(needle);
        }
    }
}

package dev.dual.adapter.acpx;

import java.util.List;

/**
 * acpx/Claude Code 工具权限的 adapter 边界模型。
 *
 * Workflow node 只声明语义化 profile；这里负责把 profile 翻译成两层权限：
 * acpx 的 ACP 权限种类（read/search/execute）和 Claude Code 的免确认工具集。
 *
 * acpx 的 `--permission-policy` 不理解 `Bash(ls *)` 这类 Claude Code 模式；
 * 它只能按 ACP 工具种类或标题批准权限请求。Claude Code 的
 * `--allowed-tools` 实际表示工具可以无需询问即执行，不是可见性白名单。
 * 它不能弥补 ACP 层对 execute 的过度批准。因此 discovery/observe/review
 * 不自动批准 execute；
 * intake contract discovery 只批准 read/search，并继续关闭 terminal；它不依赖
 * deny-all 与 permission-policy 的组合优先级来获得基本读取能力。
 */
record AcpxPermissionProfile(
        String name,
        boolean approveAll,
        boolean denyAll,
        boolean terminalEnabled,
        boolean simpleClaudeCode,
        List<String> autoApprovedTools,
        List<String> autoApproveKinds,
        List<String> escalateKinds,
        int promptRetries
) {
    AcpxPermissionProfile {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("permission profile name is required");
        }
        if (promptRetries < 0) {
            throw new IllegalArgumentException("promptRetries must be zero or positive");
        }
        autoApprovedTools = autoApprovedTools == null ? List.of() : List.copyOf(autoApprovedTools);
        autoApproveKinds = autoApproveKinds == null ? List.of() : List.copyOf(autoApproveKinds);
        escalateKinds = escalateKinds == null ? List.of() : List.copyOf(escalateKinds);
    }

    static AcpxPermissionProfile fromName(String name, boolean approveAllFallback) {
        if (approveAllFallback) {
            return new AcpxPermissionProfile(
                    "implement",
                    true,
                    false,
                    true,
                    false,
                    List.of(),
                    List.of(),
                    List.of(),
                    0
            );
        }
        if (name == null || name.isBlank()) {
            return observe();
        }
        return switch (name) {
            case "contract_discovery" -> contractDiscovery();
            case "observe" -> observe();
            case "review" -> review();
            case "implement" -> implement();
            default -> throw new IllegalArgumentException("unsupported acpx permission profile: " + name);
        };
    }

    static AcpxPermissionProfile contractDiscovery() {
        return new AcpxPermissionProfile("contract_discovery", false, false, false, true, List.of(
                "Read",
                "Grep",
                "Glob"
        ), List.of("read", "search"), List.of("fetch"), 1);
    }

    static AcpxPermissionProfile observe() {
        return new AcpxPermissionProfile("observe", false, false, true, false, List.of(
                "Read",
                "Grep",
                "Glob"
        ), List.of("read", "search"), List.of("fetch"), 1);
    }

    static AcpxPermissionProfile review() {
        var observe = observe();
        return new AcpxPermissionProfile(
                "review",
                false,
                false,
                true,
                false,
                observe.autoApprovedTools(),
                observe.autoApproveKinds(),
                observe.escalateKinds(),
                observe.promptRetries()
        );
    }

    static AcpxPermissionProfile implement() {
        return new AcpxPermissionProfile("implement", false, false, true, false, List.of(
                "Read",
                "Write",
                "Edit",
                "MultiEdit",
                "Grep",
                "Glob",
                "Bash"
        ), List.of("read", "search", "edit", "execute"), List.of("fetch"), 0);
    }

    static AcpxPermissionProfile contractCorrection() {
        return new AcpxPermissionProfile(
                "contract_correction",
                false,
                true,
                false,
                false,
                List.of(),
                List.of(),
                List.of(),
                0
        );
    }

    String autoApprovedToolsArgument() {
        return String.join(",", autoApprovedTools);
    }

    boolean approveReads() {
        return autoApproveKinds.contains("read");
    }

    boolean requiresFreshSession() {
        return simpleClaudeCode;
    }

    boolean escalates(String kind) {
        return kind != null && escalateKinds.contains(kind);
    }

    boolean allowsLocalBinding() {
        return "implement".equals(name);
    }

    boolean autoAllowsSandboxedBash() {
        return !denyAll && !approveAll && autoApproveKinds.contains("execute")
                && autoApprovedTools.contains("Bash");
    }

    AcpxPermissionProfile withAutoApprovedTool(String tool) {
        if (tool == null || tool.isBlank() || autoApprovedTools.contains(tool)) {
            return this;
        }
        var tools = new java.util.ArrayList<>(autoApprovedTools);
        tools.add(tool);
        return new AcpxPermissionProfile(
                name,
                approveAll,
                denyAll,
                terminalEnabled,
                simpleClaudeCode,
                tools,
                autoApproveKinds,
                escalateKinds,
                promptRetries
        );
    }

    String permissionPolicyJson() {
        if (autoApproveKinds.isEmpty() && escalateKinds.isEmpty()) {
            return "";
        }
        var autoApprove = autoApproveKinds.stream()
                .map(kind -> "\"" + kind + "\"")
                .collect(java.util.stream.Collectors.joining(","));
        var escalate = escalateKinds.stream()
                .map(kind -> "\"" + kind + "\"")
                .collect(java.util.stream.Collectors.joining(","));
        return "{\"autoApprove\":[" + autoApprove + "],\"escalate\":[" + escalate
                + "],\"defaultAction\":\"deny\"}";
    }
}

package dev.dual.adapter.acpx;

import java.util.Set;

final class AcpxProcessCleanupPolicy {
    private AcpxProcessCleanupPolicy() {
    }

    static boolean shouldCleanup(ProcessInfo process, Set<Long> knownBefore) {
        if (knownBefore.contains(process.pid())) {
            return false;
        }
        var commandLine = process.commandLine().toLowerCase(java.util.Locale.ROOT);
        return isCodexSerenaMcp(commandLine);
    }

    private static boolean isCodexSerenaMcp(String commandLine) {
        return commandLine.contains("serena")
                && commandLine.contains("start-mcp-server")
                && commandLine.contains("--context")
                && commandLine.contains("codex");
    }

    record ProcessInfo(long pid, String commandLine) {
    }
}

