 * {@code AgentResultEnvelope} contract.</p>
 */
public record AcpxPromptCompletion(
        String requestId,
        String stopReason,
        String finalAssistantMessage
) {
    public static final AcpxPromptCompletion EMPTY = new AcpxPromptCompletion("", "", "");

