package dev.dual.adapter.acpx;

import dev.dual.core.execution.AdapterSignal;
import dev.dual.core.execution.ProcessResult;

import java.time.Duration;
import java.time.Instant;
import java.util.List;

public record AcpxRunResult(
        Instant startedAt,
        Instant finishedAt,
        List<String> command,
        List<AcpxExecutionEvent> executionTimeline,
        AcpxUsage usage,
        AcpxPromptCompletion promptCompletion,
        ProcessResult processResult,
        List<AdapterSignal> adapterSignals,
        List<dev.dual.core.execution.AgentExecutionEvidence.ToolObservation> toolObservations
) {
    public AcpxRunResult {
        command = command == null ? List.of() : List.copyOf(command);
        executionTimeline = executionTimeline == null ? List.of() : List.copyOf(executionTimeline);
        promptCompletion = promptCompletion == null ? AcpxPromptCompletion.EMPTY : promptCompletion;
        if (processResult == null) {
            throw new IllegalArgumentException("processResult is required");
        }
        adapterSignals = adapterSignals == null ? List.of() : List.copyOf(adapterSignals);
        toolObservations = toolObservations == null ? List.of() : List.copyOf(toolObservations);
    }

    /** Bootstrap/failed calls have no internal tool evidence; an empty list grants no verification success. */
    public AcpxRunResult(Instant startedAt, Instant finishedAt, List<String> command,
                         List<AcpxExecutionEvent> executionTimeline, AcpxUsage usage,
                         AcpxPromptCompletion promptCompletion, ProcessResult processResult, List<AdapterSignal> adapterSignals) {
        this(startedAt, finishedAt, command, executionTimeline, usage, promptCompletion, processResult, adapterSignals, List.of());
    }

    public int exitCode() {
        return processResult.exitCode() == null ? -1 : processResult.exitCode();
    }

    public List<AdapterSignal> activeAdapterSignals() {
        return adapterSignals.stream().filter(signal -> !signal.superseded()).toList();
    }

    public long durationMs() {
        return Duration.between(startedAt, finishedAt).toMillis();
    }

    public boolean reachedDeclaredTimeout(Duration grace) {
        var timeoutSeconds = declaredTimeoutSeconds();
        if (timeoutSeconds <= 0) {
            return false;
        }
        var thresholdMs = Duration.ofSeconds(timeoutSeconds).minus(grace).toMillis();
        return durationMs() >= Math.max(0, thresholdMs);
    }

    private long declaredTimeoutSeconds() {
        if (command == null) {
            return 0;
        }
        for (int i = 0; i < command.size() - 1; i++) {
            if (!"--timeout".equals(command.get(i))) {
                continue;
            }
            try {
                return Long.parseLong(command.get(i + 1));
            } catch (NumberFormatException ignored) {
                return 0;
            }
        }
        return 0;
    }

}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.Path;
import java.util.*;

/** Last recorded ACP handshake, not proof of current engine bytes or arbitrary tool capability. */
final class AcpxSessionCompatibility {
    private static final ObjectMapper JSON = new ObjectMapper();
    record Assessment(boolean compatible, Map<String, Object> observation) {}

    static Assessment assess(String output, Path cwd, String session) {
        var fact = new LinkedHashMap<String, Object>();
        fact.put("source", "acpx.sessions.show");
        fact.put("native_version", "UNKNOWN");
        String failure = "invalid session metadata";
        try {
            var doc = JSON.readTree(output);
            if (doc == null || !doc.isObject()) throw new IllegalArgumentException(failure);
            for (var key : List.of("schema", "acpxRecordId", "acpSessionId", "agentSessionId", "cwd", "name")) {
                var field = doc.path(key);
                if (field.isTextual()) fact.put(key, field.asText());
            }
            if (doc.path("protocolVersion").isIntegralNumber()) fact.put("protocolVersion", doc.path("protocolVersion").intValue());
            fact.put("closed", doc.path("closed").asBoolean(false));
            var version = doc.path("agentInfo").path("version");
            if (version.isTextual() && !version.asText().isBlank() && version.asText().length() <= 120)
                fact.put("native_version", version.asText());
            var capabilities = new LinkedHashMap<String, Object>();
            var caps = doc.path("agentCapabilities");
            if (caps.path("loadSession").isBoolean()) capabilities.put("loadSession", caps.path("loadSession").booleanValue());
            var prompt = new LinkedHashMap<String, Object>();
            for (var key : List.of("image", "audio", "embeddedContext"))
                if (caps.path("promptCapabilities").path(key).isBoolean())
                    prompt.put(key, caps.path("promptCapabilities").path(key).booleanValue());
            capabilities.put("promptCapabilities", prompt);
            fact.put("agentCapabilities", capabilities);
            failure = failure(doc, cwd, session);
        } catch (Exception invalid) {
            // Never retain the full record: it may contain chat history, config or credentials.
        }
        fact.put("compatible", failure == null);
        if (failure != null) fact.put("failure", failure);
        return new Assessment(failure == null, Collections.unmodifiableMap(fact));
    }

    private static String failure(JsonNode doc, Path cwd, String session) throws Exception {
        if (!"acpx.session.v1".equals(doc.path("schema").asText())) return "unsupported acpx session metadata schema";
        for (var key : List.of("acpxRecordId", "acpSessionId", "agentSessionId"))
            if (!doc.path(key).isTextual() || doc.path(key).asText().isBlank()) return "missing session identity: " + key;
        if (!session.equals(doc.path("name").asText())) return "session name differs from invocation";
        if (!doc.path("cwd").isTextual() || !Path.of(doc.path("cwd").asText()).toRealPath().equals(cwd.toRealPath()))
            return "session workspace differs from invocation";
        if (!doc.path("closed").isBoolean() || doc.path("closed").booleanValue()) return "session is closed or has unknown open state";
        if (!doc.path("protocolVersion").isIntegralNumber() || doc.path("protocolVersion").intValue() != 1)
            return "required ACP protocol version 1 is unavailable";
        return null;
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * P0 session 生命周期止损：读取一个 workstream 的 run ledger，对其用过的每个
 * (agent, session) 调用 {@code acpx <agent> sessions close}。
 *
 * <p>设计要点：</p>
 * <ul>
 *     <li>session 名直接来自各 {@code runs/<runId>/run.json} 的 {@code agent}+{@code session}
 *     字段——即 adapter 实际开过的 session，不靠反推命名规则。</li>
 *     <li>整个方法 <b>永不抛异常</b>：任何 run 读不出、acpx 不可用、close 失败都计入 failed，
 *     绝不影响 workflow 状态。</li>
 *     <li>只调 {@code acpx sessions close}，不删 {@code ~/.acpx/sessions} 文件。</li>
 *     <li>把清理结果追加写入 {@code session-cleanup.log}，方便追踪。</li>
 * </ul>
 *
 * <p>本类只做 lifecycle cleanup，不解决 token 雪球。</p>
 */
public final class AcpxSessionLifecycle implements WorkstreamSessionCloser {

    private static final Set<String> SUPPORTED_AGENTS = Set.of("claude", "codex");

    private final AcpxAgentTransport transport;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public AcpxSessionLifecycle() {
        this(new AcpxAgentTransport());
    }

    public AcpxSessionLifecycle(AcpxAgentTransport transport) {
        this.transport = transport;
    }

    @Override
    public CloseSummary closeWorkstreamSessions(Path workspaceRoot, String workstreamId) {
        var targets = collectSessionTargets(workspaceRoot, workstreamId);
        int closed = 0;
        int failed = 0;
        for (SessionTarget target : targets) {
            try {
                if (transport.closeSession(target.agent, workspaceRoot, target.session)) {
                    closed++;
                } else {
                    failed++;
                }
            } catch (RuntimeException ignored) {
                failed++;
            }
        }
        writeDiagnostic(workspaceRoot, workstreamId, targets, closed, failed);
        return new CloseSummary(workstreamId, targets.size(), closed, failed);
    }

    private List<SessionTarget> collectSessionTargets(Path workspaceRoot, String workstreamId) {
        var runsDir = workspaceRoot.resolve(".agent").resolve("workstreams").resolve(workstreamId).resolve("runs");
        var targets = new LinkedHashSet<SessionTarget>();
        if (!Files.isDirectory(runsDir)) {
            return List.of();
        }
        try (var stream = Files.list(runsDir)) {
            for (var runDir : stream.filter(Files::isDirectory).toList()) {
                var runJson = runDir.resolve("run.json");
                if (!Files.isRegularFile(runJson)) {
                    continue;
                }
                readTarget(runJson).ifPresent(targets::add);
            }
        } catch (IOException ignored) {
            // runs dir unreadable: nothing to close
        }
        return new ArrayList<>(targets);
    }

    private java.util.Optional<SessionTarget> readTarget(Path runJson) {
        try {
            JsonNode node = objectMapper.readTree(runJson.toFile());
            var agent = text(node.get("agent"));
            var session = text(node.get("session"));
            if (SUPPORTED_AGENTS.contains(agent) && !session.isBlank()) {
                return java.util.Optional.of(new SessionTarget(agent, session));
            }
        } catch (IOException ignored) {
            // skip unreadable run.json
        }
        return java.util.Optional.empty();
    }

    private void writeDiagnostic(Path workspaceRoot, String workstreamId,
                                 List<SessionTarget> targets, int closed, int failed) {
        var logPath = workspaceRoot.resolve(".agent").resolve("workstreams")
                .resolve(workstreamId).resolve("session-cleanup.log");
        try {
            Files.createDirectories(logPath.getParent());
            var builder = new StringBuilder()
                    .append("session-cleanup workstream=").append(workstreamId)
                    .append(" distinct=").append(targets.size())
                    .append(" closed=").append(closed)
                    .append(" failed=").append(failed)
                    .append(System.lineSeparator());
            for (var target : targets) {
                builder.append("  ").append(target.agent).append(' ').append(target.session)
                        .append(System.lineSeparator());
            }
            Files.writeString(logPath, builder.toString(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException ignored) {
            // diagnostic is best-effort
        }
    }

    private static String text(JsonNode node) {
        return node == null || node.isNull() ? "" : node.asText("").trim();
    }

    record SessionTarget(String agent, String session) {
    }
}

package dev.dual.adapter.acpx;

import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Ordered semantic projection of decoded acpx session-stream messages.
 *
 * <p>This class owns request-id correlation and session recovery ordering. It
 * never parses raw JSON and never applies workflow or retry policy.</p>
 */
final class AcpxSessionStreamProjector {
    private final Map<String, ArrayDeque<String>> pendingRequests = new HashMap<>();
    private final List<AcpxStreamEvidence.TypedError> errors = new ArrayList<>();
    private boolean sessionReady;
    private String promptStopReason = "";
    private String currentPromptRequestId = "";
    private final StringBuilder ungroupedAssistantDeltas = new StringBuilder();
    private final Map<String, String> assistantMessages = new LinkedHashMap<>();
    private AcpxPromptCompletion promptCompletion = AcpxPromptCompletion.EMPTY;
    private final Map<String, AgentLifecycleEvent.PermissionEvidence> permissionDetails = new HashMap<>();
    private final Map<String, String> toolNamesByCallId = new HashMap<>();
    private String currentSession = "";
    private boolean promptActive;
    private final Map<String, dev.dual.core.execution.AdapterSignal.OperationRef> permissionOperations = new HashMap<>();
    private final Map<String, Map<String,String>> permissionOptionKinds = new HashMap<>();
    private final java.util.Set<String> seenPermissionIds = new java.util.HashSet<>();
    private final java.util.Set<String> invalidPermissionIds = new java.util.HashSet<>();
    private final AcpxToolObservations toolObservations = new AcpxToolObservations();

    List<dev.dual.core.execution.AgentExecutionEvidence.ToolObservation> toolObservations() {
        return toolObservations.values();
    }

    Optional<AgentLifecycleEvent> accept(long sequence, AcpxStreamWireLine wire) {
        return accept(sequence, wire, true);
    }

    Optional<AgentLifecycleEvent> accept(
            long sequence,
            AcpxStreamWireLine wire,
            boolean currentObservation
    ) {
        return switch (wire.kind()) {
            case JSONRPC_REQUEST -> request(sequence, wire, currentObservation);
            case JSONRPC_OK -> success(sequence, wire, currentObservation);
            case JSONRPC_ERROR, TYPED_FAILURE_EVENT -> failure(sequence, wire);
            case NOTIFICATION -> notification(sequence, wire, currentObservation);
            case MALFORMED -> Optional.empty();
        };
    }

    AcpxStreamEvidence evidence() {
        if (errors.isEmpty()
                && !sessionReady
                && promptStopReason.isEmpty()
                && !hasPendingControlRequest()) {
            return AcpxStreamEvidence.EMPTY;
        }
        return new AcpxStreamEvidence(
                List.copyOf(errors),
                sessionReady,
                promptStopReason,
                hasPendingControlRequest()
        );
    }

    AcpxPromptCompletion promptCompletion() {
        return promptCompletion;
    }

    private Optional<AgentLifecycleEvent> request(
            long sequence,
            AcpxStreamWireLine wire,
            boolean currentObservation
    ) {
        if (("session/prompt".equals(wire.method()) || "session/request_permission".equals(wire.method()))
                && !currentObservation) {
            return Optional.empty();
        }
        pendingRequests.computeIfAbsent(wire.requestId(), ignored -> new ArrayDeque<>())
                .addLast(wire.method());
        if (isControlRequest(wire.method())) {
            promptStopReason = "";
        }
        if ("session/prompt".equals(wire.method())) {
            startPrompt(wire.requestId());
            currentSession = wire.request().sessionId(); promptActive = currentSession != null && !currentSession.isBlank();
            permissionDetails.clear(); permissionOperations.clear(); permissionOptionKinds.clear();
            toolNamesByCallId.clear(); toolObservations.start(currentSession, currentPromptRequestId);
        }
        if ("session/new".equals(wire.method()) || "session/resume".equals(wire.method())) {
            sessionReady = false;
        }
        if ("session/request_permission".equals(wire.method())) {
            var request = wire.request();
            if (!seenPermissionIds.add(wire.requestId())) invalidPermissionIds.add(wire.requestId());
            var evidence = permissionEvidence(request);
            permissionDetails.put(wire.requestId(), evidence);
            // A current but uncorrelated request still produces a blocking permission fact.
            // It cannot acquire an operation identity eligible for nonessential assessment.
            if (!promptActive || !currentSession.equals(request.sessionId()))
                return Optional.of(AgentLifecycleEvent.permissionRequested(sequence, evidence));
            permissionOptionKinds.put(wire.requestId(), request.permissionOptionKinds());
            permissionOperations.put(wire.requestId(), new dev.dual.core.execution.AdapterSignal.OperationRef(
                    currentSession, currentPromptRequestId, wire.requestId(), request.permissionToolCallId(), sequence, -1,
                    request.permissionToolKind(), dev.dual.core.execution.AdapterSignal.parametersHash(request.permissionRawInput()),
                    request.permissionRequestJson(), dev.dual.core.execution.AdapterSignal.digest(request.permissionRequestJson()), "", ""));
            return Optional.of(AgentLifecycleEvent.permissionRequested(sequence, evidence));
        }
        return switch (wire.method()) {
            case "session/new" -> Optional.of(AgentLifecycleEvent.sessionNewRequested(sequence));
            case "session/prompt" -> Optional.of(AgentLifecycleEvent.promptAccepted(sequence));
            default -> Optional.empty();
        };
    }

    private Optional<AgentLifecycleEvent> success(
            long sequence,
            AcpxStreamWireLine wire,
            boolean currentObservation
    ) {
        var method = completedMethodFor(wire);
        if ("session/new".equals(method) || "session/resume".equals(method)) {
            sessionReady = true;
        }
        if ("session/new".equals(method)) {
            errors.removeIf(error -> "session/resume".equals(error.method()));
            return Optional.of(AgentLifecycleEvent.sessionNewCreated(sequence));
        }
        if (currentObservation
                && "session/prompt".equals(method)
                && !currentPromptRequestId.isBlank()
                && currentPromptRequestId.equals(wire.requestId())) {
            promptStopReason = wire.result() == null ? "" : wire.result().stopReason();
            var requestId = wire.requestId().isBlank() ? currentPromptRequestId : wire.requestId();
            promptCompletion = new AcpxPromptCompletion(
                    requestId,
                    promptStopReason,
                    finalAssistantMessage()
            );
            toolObservations.finish(); promptActive = false;
            return Optional.of(AgentLifecycleEvent.promptCompleted(sequence));
        }
        if (currentObservation && "session/request_permission".equals(method)) {
            var evidence = permissionDetails.remove(wire.requestId());
            if (evidence == null) {
                return Optional.empty();
            }
            var operation = permissionOperations.remove(wire.requestId());
            var options = permissionOptionKinds.remove(wire.requestId());
            var outcome = wire.result() == null ? "" : wire.result().permissionOutcome();
            var optionId = wire.result() == null ? "" : wire.result().permissionOptionId();
            var optionKind = options == null ? "" : options.getOrDefault(optionId, "");
            boolean current = promptActive && operation != null && currentSession.equals(operation.sessionId())
                    && !invalidPermissionIds.contains(wire.requestId());
            if (current && "selected".equals(outcome) && ("reject_once".equals(optionKind) || "reject_always".equals(optionKind))) {
                var response = wire.result().responseJson();
                operation = new dev.dual.core.execution.AdapterSignal.OperationRef(operation.sessionId(), operation.promptId(),
                        operation.requestId(), operation.toolCallId(), operation.requestSequence(), sequence, operation.kind(),
                        operation.parametersSha256(), operation.requestJson(), operation.requestSha256(), response,
                        dev.dual.core.execution.AdapterSignal.digest(response));
                return Optional.of(AgentLifecycleEvent.permissionDenied(sequence, evidence.withDisposition("DENIED").withOperation(operation)));
            }
            if (current && "selected".equals(outcome) && ("allow_once".equals(optionKind) || "allow_always".equals(optionKind)))
                return Optional.of(AgentLifecycleEvent.permissionApproved(sequence, evidence.withDisposition("APPROVED")));
            if (current && "cancelled".equals(outcome))
                return Optional.of(AgentLifecycleEvent.permissionCancelled(sequence, evidence.withDisposition("CANCELLED")));
            return Optional.of(AgentLifecycleEvent.permissionUnresolved(sequence, evidence.withDisposition("UNKNOWN")));
        }
        if (wire.result() != null && wire.result().usage() != null) {
            return Optional.of(AgentLifecycleEvent.usageUpdate(sequence));
        }
        return Optional.empty();
    }

    private Optional<AgentLifecycleEvent> failure(long sequence, AcpxStreamWireLine wire) {
        var method = completedMethodFor(wire);
        var error = wire.error();
        var typed = new AcpxStreamEvidence.TypedError(
                method,
                error == null || error.code() == null ? 0 : error.code(),
                error == null ? "" : error.message(),
                error == null ? "" : error.dataMessage(),
                error == null ? "" : error.dataDetails()
        );
        errors.add(typed);
        return Optional.of("session/resume".equals(method)
                ? AgentLifecycleEvent.sessionResumeFailed(sequence, typed)
                : AgentLifecycleEvent.providerFailure(sequence, typed));
    }

    private Optional<AgentLifecycleEvent> notification(
            long sequence,
            AcpxStreamWireLine wire,
            boolean currentObservation
    ) {
        if (!"session/update".equals(wire.method())) {
            return Optional.empty();
        }
        var notification = wire.notification();
        if (currentObservation && notification != null) toolObservations.accept(notification);
        var updateKind = notification == null ? "" : notification.updateKind();
        if (notification != null
                && !notification.toolCallId().isBlank()
                && !notification.toolName().isBlank()) {
            toolNamesByCallId.put(notification.toolCallId(), notification.toolName());
        }
        // A bounded tail may start after session/new. A structurally complete
        // typed session/update still proves that the named session was active;
        // malformed/bare notifications contribute no readiness fact.
        if (notification != null
                && !notification.sessionId().isBlank()
                && !updateKind.isBlank()) {
            sessionReady = true;
        }
        if (currentObservation
                && notification != null
                && "agent_message_chunk".equals(updateKind)
                && "text".equals(notification.contentType())) {
            appendAssistantMessage(notification.messageId(), notification.text());
        }
        return Optional.of("usage_update".equals(updateKind)
                ? AgentLifecycleEvent.usageUpdate(sequence)
                : AgentLifecycleEvent.agentActivity(sequence));
    }

    private void startPrompt(String requestId) {
        currentPromptRequestId = requestId == null ? "" : requestId;
        ungroupedAssistantDeltas.setLength(0);
        assistantMessages.clear();
        promptCompletion = AcpxPromptCompletion.EMPTY;
    }

    private void appendAssistantMessage(String messageId, String text) {
        var value = text == null ? "" : text;
        if (messageId == null || messageId.isBlank()) {
            ungroupedAssistantDeltas.append(value);
            return;
        }
        var current = assistantMessages.getOrDefault(messageId, "");
        if (value.equals(current) || (!current.isEmpty() && value.startsWith(current))) {
            assistantMessages.put(messageId, value);
            return;
        }
        assistantMessages.put(messageId, current + value);
    }

    private String finalAssistantMessage() {
        if (!assistantMessages.isEmpty()) {
            String latest = "";
            for (var value : assistantMessages.values()) {
                latest = value;
            }
            return latest;
        }
        return ungroupedAssistantDeltas.toString();
    }

    private String completedMethodFor(AcpxStreamWireLine wire) {
        var requests = pendingRequests.get(wire.requestId());
        var correlated = requests == null ? null : requests.pollLast();
        if (requests != null && requests.isEmpty()) {
            pendingRequests.remove(wire.requestId());
        }
        if (correlated != null && !correlated.isBlank()) {
            return correlated;
        }
        if (wire.method() != null && !wire.method().isBlank()) {
            return wire.method();
        }
        if (wire.result() != null && !wire.result().sessionId().isBlank()) {
            return "session/new";
        }
        return "";
    }

    private boolean hasPendingControlRequest() {
        return pendingRequests.values().stream()
                .flatMap(java.util.Collection::stream)
                .anyMatch(this::isControlRequest);
    }

    private boolean isControlRequest(String method) {
        return "session/new".equals(method)
                || "session/resume".equals(method)
                || "session/prompt".equals(method);
    }

    private AgentLifecycleEvent.PermissionEvidence permissionEvidence(AcpxStreamWireLine.Request request) {
        if (request == null) {
            return AgentLifecycleEvent.PermissionEvidence.EMPTY;
        }
        return new AgentLifecycleEvent.PermissionEvidence(
                crop(request.permissionToolCallId(), 160),
                crop(request.permissionToolKind(), 80),
                crop(toolNamesByCallId.get(request.permissionToolCallId()), 80),
                crop(request.permissionTitle(), 240),
                crop(request.permissionCommand(), 512),
                request.permissionOptions(),
                "REQUESTED"
        );
    }

    private String crop(String value, int maxLength) {
        var normalized = value == null ? "" : value.replaceAll("\\s+", " ").strip();
        return normalized.length() <= maxLength ? normalized : normalized.substring(0, maxLength) + "...";
    }
}

package dev.dual.adapter.acpx;

import java.util.List;

/**
 * Normalized, typed evidence derived from an acpx session stream.
 *
 * <p>This is the second layer of the adapter boundary: it carries only real
 * top-level JSON-RPC errors (correlated to their request method) plus the
 * ordered session-ready and prompt-stop facts needed to arbitrate wrapper
 * diagnostics. It never carries agent prose, usage metadata, tool results, or
 * recovered {@code session/resume} errors. The
 * {@link #normalizedErrorText()} projection is the only stream content that
 * reaches provider-error matching.
 */
record AcpxStreamEvidence(
        List<TypedError> errors,
        boolean sessionReady,
        String promptStopReason,
        boolean pendingControlRequest
) {

    static final AcpxStreamEvidence EMPTY = new AcpxStreamEvidence(List.of(), false, "", false);

    AcpxStreamEvidence {
        errors = errors == null ? List.of() : List.copyOf(errors);
        promptStopReason = promptStopReason == null ? "" : promptStopReason;
    }

    AcpxStreamEvidence(List<TypedError> errors) {
        this(errors, false, "", false);
    }

    /**
     * One real JSON-RPC error: the method it answered (when correlatable via
     * request id), the error code, the top-level message, and the nested
     * {@code error.data.message} / {@code error.data.details} where the real
     * provider error (HTTP status / type) typically lives for Codex ACP.
     */
    record TypedError(String method, int code, String message, String dataMessage, String dataDetails) {
        TypedError {
            method = method == null ? "" : method;
            message = message == null ? "" : message;
            dataMessage = dataMessage == null ? "" : dataMessage;
            dataDetails = dataDetails == null ? "" : dataDetails;
        }
    }

    boolean isEmpty() {
        return errors.isEmpty();
    }

    boolean hasFacts() {
        return !errors.isEmpty() || sessionReady || !promptStopReason.isEmpty() || pendingControlRequest;
    }

    boolean provesRecoveredPromptCompletion() {
        return errors.isEmpty()
                && sessionReady
                && !pendingControlRequest
                && ("end_turn".equals(promptStopReason) || "completed".equals(promptStopReason));
    }

    /**
     * Joined typed error fields only: method/code context plus the top-level
     * message and the nested {@code data.message}/{@code data.details}, so the
     * catalog can classify the failure type from the real provider error
     * wherever it is nested — never from raw stream lines or agent prose.
     */
    String normalizedErrorText() {
        if (errors.isEmpty()) {
            return "";
        }
        var builder = new StringBuilder();
        for (var error : errors) {
            if (!error.method().isEmpty()) {
                builder.append(error.method()).append(' ');
            }
            builder.append("error ").append(error.code()).append(": ").append(error.message());
            if (!error.dataMessage().isEmpty()) {
                builder.append(" | data: ").append(error.dataMessage());
            }
            if (!error.dataDetails().isEmpty()) {
                builder.append(" | details: ").append(error.dataDetails());
            }
            builder.append('\n');
        }
        return builder.toString();
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

/**
 * Adapter-local wire view of one acpx session-stream NDJSON line.
 *
 * <p>This is the single owner of the top-level acpx JSON-RPC grammar. Consumers
 * receive typed request, result, notification, or error fields and must not
 * parse the raw NDJSON line again.</p>
 */
record AcpxStreamWireLine(
        Kind kind,
        String requestId,
        String method,
        Request request,
        Result result,
        Notification notification,
        Error error
) {
    private static final ObjectMapper MAPPER = new ObjectMapper();

    enum Kind {
        JSONRPC_ERROR,
        TYPED_FAILURE_EVENT,
        JSONRPC_OK,
        JSONRPC_REQUEST,
        NOTIFICATION,
        MALFORMED
    }

    record Request(
            String sessionId,
            String promptText,
            String permissionToolCallId,
            String permissionToolKind,
            String permissionTitle,
            String permissionCommand,
            List<String> permissionOptions,
            java.util.Map<String,String> permissionOptionKinds,
            JsonNode permissionRawInput,
            String permissionRequestJson
    ) {
        Request {
            promptText = promptText == null ? "" : promptText;
            permissionToolCallId = permissionToolCallId == null ? "" : permissionToolCallId;
            permissionToolKind = permissionToolKind == null ? "" : permissionToolKind;
            permissionTitle = permissionTitle == null ? "" : permissionTitle;
            permissionCommand = permissionCommand == null ? "" : permissionCommand;
            permissionOptions = permissionOptions == null ? List.of() : List.copyOf(permissionOptions);
        }
    }

    record Result(String sessionId, String stopReason, Usage usage, String permissionOutcome, String permissionOptionId, String responseJson) {
        Result {
            sessionId = sessionId == null ? "" : sessionId;
            stopReason = stopReason == null ? "" : stopReason;
            permissionOutcome = permissionOutcome == null ? "" : permissionOutcome;
            permissionOptionId = permissionOptionId == null ? "" : permissionOptionId;
        }
    }

    record Notification(
            String sessionId,
            String updateKind,
            String messageId,
            String contentType,
            String text,
            String toolCallId,
            String toolName,
            UsageUpdate usageUpdate,
            JsonNode toolUpdate
    ) {
        Notification {
            sessionId = sessionId == null ? "" : sessionId;
            updateKind = updateKind == null ? "" : updateKind;
            messageId = messageId == null ? "" : messageId;
            contentType = contentType == null ? "" : contentType;
            text = text == null ? "" : text;
            toolCallId = toolCallId == null ? "" : toolCallId;
            toolName = toolName == null ? "" : toolName;
        }
    }

    record Error(Integer code, String message, String dataMessage, String dataDetails) {
        Error {
            message = message == null ? "" : message;
            dataMessage = dataMessage == null ? "" : dataMessage;
            dataDetails = dataDetails == null ? "" : dataDetails;
        }
    }

    record Usage(
            long inputTokens,
            long outputTokens,
            long cachedReadTokens,
            long cachedWriteTokens,
            long totalTokens
    ) {
    }

    record UsageUpdate(long used, BigDecimal costAmount, String costCurrency) {
        UsageUpdate {
            costCurrency = costCurrency == null ? "" : costCurrency;
        }
    }

    static AcpxStreamWireLine parse(String line) {
        if (line == null) {
            return malformed();
        }
        var trimmed = line.strip();
        if (trimmed.isEmpty() || trimmed.charAt(0) != '{') {
            return malformed();
        }
        JsonNode node;
        try {
            node = MAPPER.readTree(trimmed);
        } catch (Exception ignored) {
            return malformed();
        }
        if (node == null || !node.isObject()) {
            return malformed();
        }

        var requestId = id(node.get("id"));
        var method = text(node.get("method"));
        var errorNode = node.get("error");
        if (errorNode != null && errorNode.isObject()) {
            return new AcpxStreamWireLine(
                    Kind.JSONRPC_ERROR,
                    requestId,
                    method,
                    null,
                    null,
                    null,
                    error(errorNode)
            );
        }

        var type = text(node.get("type"));
        if (isTypedFailure(type, method, errorNode)) {
            var failureType = !type.isBlank() ? type : method;
            return new AcpxStreamWireLine(
                    Kind.TYPED_FAILURE_EVENT,
                    requestId,
                    methodForFailureType(failureType),
                    null,
                    null,
                    null,
                    new Error(null, textualError(node, errorNode), "", "")
            );
        }

        if (node.has("result")) {
            var resultNode = node.path("result");
            return new AcpxStreamWireLine(
                    Kind.JSONRPC_OK,
                    requestId,
                    method,
                    null,
                    new Result(
                            text(resultNode.get("sessionId")),
                            text(resultNode.get("stopReason")),
                            usage(resultNode.get("usage")),
                            text(resultNode.at("/outcome/outcome")),
                            text(resultNode.at("/outcome/optionId")),
                            trimmed
                    ),
                    null,
                    null
            );
        }

        if (!method.isBlank() && !requestId.isBlank()) {
            return new AcpxStreamWireLine(
                    Kind.JSONRPC_REQUEST,
                    requestId,
                    method,
                    new Request(
                            text(node.at("/params/sessionId")),
                            text(node.at("/params/prompt/0/text")),
                            text(node.at("/params/toolCall/toolCallId")),
                            text(node.at("/params/toolCall/kind")),
                            text(node.at("/params/toolCall/title")),
                            permissionResource(node.at("/params/toolCall/rawInput")),
                            strings(node.at("/params/options"), "optionId"),
                            optionKinds(node.at("/params/options")),
                            node.at("/params/toolCall/rawInput").deepCopy(), trimmed
                    ),
                    null,
                    null,
                    null
            );
        }

        if (!method.isBlank()) {
            var update = node.at("/params/update");
            var updateKind = text(update.get("sessionUpdate"));
            return new AcpxStreamWireLine(
                    Kind.NOTIFICATION,
                    "",
                    method,
                    null,
                    null,
                    new Notification(
                            text(node.at("/params/sessionId")),
                            updateKind,
                            text(update.get("messageId")),
                            text(update.at("/content/type")),
                            text(update.at("/content/text")),
                            text(update.get("toolCallId")),
                            text(update.at("/_meta/claudeCode/toolName")),
                            usageUpdate(updateKind, update),
                            ("tool_call".equals(updateKind) || "tool_call_update".equals(updateKind))
                                    ? update.deepCopy() : null
                    ),
                    null
            );
        }
        return malformed();
    }

    private static java.util.Map<String,String> optionKinds(JsonNode options) {
        var map = new java.util.LinkedHashMap<String,String>();
        if (options != null && options.isArray()) for (var item : options) {
            var id = text(item.get("optionId")); var kind = text(item.get("kind"));
            if (!id.isBlank()) map.merge(id, kind, (old, next) -> "AMBIGUOUS");
        }
        return java.util.Map.copyOf(map);
    }

    private static Error error(JsonNode errorNode) {
        var data = errorNode.path("data");
        var code = errorNode.get("code");
        return new Error(
                code != null && code.isInt() ? code.asInt() : null,
                text(errorNode.get("message")),
                text(data.get("message")),
                text(data.get("details"))
        );
    }

    private static String permissionResource(JsonNode rawInput) {
        if (rawInput == null || !rawInput.isObject()) {
            return "";
        }
        var command = text(rawInput.get("command"));
        return command.isBlank() ? text(rawInput.get("query")) : command;
    }

    private static Usage usage(JsonNode usage) {
        if (usage == null || !usage.isObject()) {
            return null;
        }
        return new Usage(
                number(usage.get("inputTokens")),
                number(usage.get("outputTokens")),
                number(usage.get("cachedReadTokens")),
                number(usage.get("cachedWriteTokens")),
                number(usage.get("totalTokens"))
        );
    }

    private static UsageUpdate usageUpdate(String updateKind, JsonNode update) {
        if (!"usage_update".equals(updateKind)) {
            return null;
        }
        var cost = update.path("cost");
        return new UsageUpdate(
                number(update.get("used")),
                decimal(cost.get("amount")),
                text(cost.get("currency"))
        );
    }

    private static boolean isTypedFailure(String type, String method, JsonNode errorNode) {
        return (type != null && type.endsWith("/failed"))
                || (method != null && method.endsWith("/failed") && errorNode != null && errorNode.isTextual());
    }

    private static String textualError(JsonNode node, JsonNode errorNode) {
        if (errorNode != null && errorNode.isTextual()) {
            return errorNode.asText();
        }
        return text(node.get("message"));
    }

    private static String methodForFailureType(String type) {
        return type == null ? "" : type.substring(0, type.length() - "/failed".length());
    }

    private static String id(JsonNode node) {
        return node == null || node.isNull() || (!node.isTextual() && !node.isNumber()) ? "" : node.asText();
    }

    private static String text(JsonNode node) {
        return node == null || node.isMissingNode() || node.isNull() ? "" : node.asText();
    }

    private static long number(JsonNode node) {
        return node == null || !node.isNumber() ? 0 : node.asLong();
    }

    private static BigDecimal decimal(JsonNode node) {
        return node == null || !node.isNumber() ? null : node.decimalValue();
    }

    private static List<String> strings(JsonNode node, String field) {
        if (node == null || !node.isArray()) {
            return List.of();
        }
        var values = new ArrayList<String>();
        for (var item : node) {
            var value = text(item.get(field));
            if (!value.isBlank()) {
                values.add(value);
            }
        }
        return List.copyOf(values);
    }

    private static AcpxStreamWireLine malformed() {
        return new AcpxStreamWireLine(Kind.MALFORMED, "", "", null, null, null, null);
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import dev.dual.core.execution.AgentExecutionEvidence.ToolObservation;
import java.util.*;

/** Correlates only typed updates inside the current prompt. No prose or transcript heuristics. */
final class AcpxToolObservations {
    private String session = "";
    private boolean active;
    private String prompt = "";
    private final Map<String, Call> calls = new LinkedHashMap<>();

    void start(String session) { start(session, ""); }
    void start(String session, String prompt) { this.prompt = prompt == null ? "" : prompt; this.session = session == null ? "" : session; active = !this.session.isBlank(); calls.clear(); }
    void finish() { active = false; }
    List<ToolObservation> values() { return calls.values().stream().map(Call::freeze).toList(); }

    void accept(AcpxStreamWireLine.Notification notification) {
        if (!active || !session.equals(notification.sessionId()) || notification.toolUpdate() == null
                || notification.toolCallId().isBlank()) return;
        var update = notification.toolUpdate();
        var id = notification.toolCallId();
        var call = calls.get(id);
        if ("tool_call".equals(notification.updateKind())) {
            if (call != null) { call.invalid = true; return; }
            call = new Call(session, id, prompt); calls.put(id, call);
        } else if (call == null) {
            // A result without the call's creation/input is not evidence of this prompt's execution.
            call = new Call(session, id, prompt); call.invalid = true; calls.put(id, call);
        }
        if (call.terminal && !call.raw.contains(update)) call.invalid = true;
        if (call.raw.contains(update)) return;
        call.raw.add(update.deepCopy());
        if (!notification.toolName().isBlank()) call.name = notification.toolName();
        if (update.hasNonNull("kind")) call.kind = update.path("kind").asText();
        if (update.hasNonNull("rawInput")) {
            if (call.input != null && call.terminal && !call.input.equals(update.get("rawInput"))) call.invalid = true;
            call.input = update.get("rawInput").deepCopy();
        }
        if (update.hasNonNull("rawOutput")) { call.output = update.get("rawOutput").deepCopy(); call.hasRawOutput = true; }
        else if (update.has("content") || update.path("_meta").has("terminal_output")) {
            var result = JsonNodeFactory.instance.objectNode();
            if (update.has("content")) result.set("content", update.get("content").deepCopy());
            if (update.path("_meta").has("terminal_output"))
                result.set("terminal_output", update.path("_meta").get("terminal_output").deepCopy());
            call.outputChunks.add(result);
            if (!call.hasRawOutput) call.output = call.outputChunks.deepCopy();
        }
        if (update.hasNonNull("status")) call.status = update.path("status").asText();
        var reported = update.at("/_meta/terminal_exit/exit_code");
        if (reported.isIntegralNumber() && reported.canConvertToInt()) call.reported = reported.intValue();
        // Pinned Claude ACP forwards this exact result branch in rawOutput. Its _meta exit alone is synthetic/ambiguous.
        if ("Bash".equals(call.name) && call.output != null
                && "bash_code_execution_result".equals(call.output.path("type").asText())) {
            var actual = call.output.path("return_code");
            if (actual.isIntegralNumber() && actual.canConvertToInt()) {
                call.actual = actual.intValue(); call.actualSource = "claude.rawOutput.bash_code_execution_result.return_code";
            }
        }
        call.terminal = "completed".equals(call.status) || "failed".equals(call.status);
    }

    private static final class Call {
        final String session, id, prompt;
        String name = "", kind = "", status = "", actualSource = "";
        JsonNode input, output;
        Integer reported, actual;
        boolean invalid, terminal, hasRawOutput;
        final com.fasterxml.jackson.databind.node.ArrayNode outputChunks = JsonNodeFactory.instance.arrayNode();
        final List<JsonNode> raw = new ArrayList<>();
        Call(String session, String id, String prompt) { this.session = session; this.id = id; this.prompt = prompt; }
        ToolObservation freeze() { return new ToolObservation(session, id, name, kind, input, output,
                status, reported, actual, actualSource, invalid, raw, prompt); }
    }
}

package dev.dual.adapter.acpx;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.Optional;
import java.util.regex.Pattern;

/**
 * Extracts adapter-level tool telemetry from an acpx transcript.
 *
 * This reader intentionally produces execution facts only. Workflow routing and
 * product acceptance must continue to use typed artifacts and ledger state, not
 * these transcript heuristics.
 */
final class AcpxTranscriptToolUsageReader {
    private static final Pattern JSON_TOOL = Pattern.compile(
            "\"(?:name|tool|tool_name|toolName)\"\\s*:\\s*\"(?<tool>Read|Edit|Write|MultiEdit|Glob|Grep|Bash|LS|Task)\"",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern TEXT_TOOL = Pattern.compile(
            "^\\s*(?:tool[_ -]?use\\s*)?(?<tool>Read|Edit|Write|MultiEdit|Glob|Grep|Bash|LS|Task)\\s*(?:\\(|\\{|:|$)",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern PATH_VALUE = Pattern.compile(
            "\"(?:file_path|path|notebook_path)\"\\s*:\\s*\"(?<path>[^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\""
    );
    private static final Pattern COMMAND_VALUE = Pattern.compile(
            "\"command\"\\s*:\\s*\"(?<command>[^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\""
    );
    private static final Pattern COMMAND_ARRAY = Pattern.compile(
            "\"command\"\\s*:\\s*\\[(?<command>[^]]*)]"
    );
    private static final Pattern JSON_STRING = Pattern.compile("\"(?<value>[^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\"");
    private static final Pattern BRACKET_TOOL = Pattern.compile(
            "^\\s*\\[tool]\\s*(?<body>.*?)\\s*\\((?<state>pending|running|completed)\\)\\s*$",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern INPUT_LINE = Pattern.compile("^\\s*input:\\s*(?<body>.*)$", Pattern.CASE_INSENSITIVE);

    AcpxToolUsage read(Path transcriptPath, Path workspaceRoot) throws IOException {
        if (transcriptPath == null || !Files.isRegularFile(transcriptPath)) {
            return AcpxToolUsage.empty();
        }
        var byTool = new LinkedHashMap<String, Integer>();
        var toolIds = new LinkedHashSet<String>();
        var readFiles = new LinkedHashSet<String>();
        var directReadFiles = new LinkedHashSet<String>();
        var writeFiles = new LinkedHashSet<String>();
        var bashCommands = new LinkedHashSet<String>();
        var commandExecutables = new LinkedHashSet<String>();
        PendingTool pending = null;
        for (var line : Files.readAllLines(transcriptPath, StandardCharsets.UTF_8)) {
            var bracketTool = bracketToolIn(line, workspaceRoot);
            if (bracketTool.isPresent()) {
                if (pending != null) {
                    record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
                }
                pending = bracketTool.get();
                if (pending.hasEvidence()) {
                    record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
                    pending = null;
                }
                continue;
            }
            if (pending != null && mergeInputLine(pending, line, workspaceRoot)) {
                record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
                pending = null;
                continue;
            }
            if (pending != null && !line.trim().isBlank()) {
                record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
                pending = null;
            }
            consumeLine(line, workspaceRoot, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
        }
        if (pending != null) {
            record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
        }
        var readCount = countMatching(byTool, "Read", "Glob", "Grep", "LS");
        var writeCount = countMatching(byTool, "Edit", "Write", "MultiEdit");
        var bashCount = countMatching(byTool, "Bash");
        var total = byTool.values().stream().mapToInt(Integer::intValue).sum();
        var known = readCount + writeCount + bashCount + countMatching(byTool, "Task");
        return new AcpxToolUsage(
                1,
                total,
                readCount,
                writeCount,
                bashCount,
                Math.max(0, total - known),
                Map.copyOf(byTool),
                List.copyOf(toolIds),
                List.copyOf(readFiles),
                List.copyOf(directReadFiles),
                List.copyOf(writeFiles),
                List.copyOf(bashCommands),
                List.copyOf(commandExecutables)
        );
    }

    private static void consumeLine(
            String line,
            Path workspaceRoot,
            Map<String, Integer> byTool,
            Set<String> toolIds,
            Set<String> readFiles,
            Set<String> directReadFiles,
            Set<String> writeFiles,
            Set<String> bashCommands,
            Set<String> commandExecutables
    ) {
        var tools = toolsIn(line);
        if (tools.isEmpty()) {
            return;
        }
        var paths = new LinkedHashSet<>(pathsIn(line, workspaceRoot));
        for (var tool : tools) {
            var behaviorTool = tool;
            toolIds.add(tool);
            if ("Bash".equals(tool)) {
                var command = commandIn(line);
                if (command.isPresent()) {
                    recordCommand(command.get(), bashCommands, commandExecutables);
                    behaviorTool = classifyCommand(command.get()).orElse("Bash");
                    commandPath(behaviorTool, command.get(), workspaceRoot).ifPresent(paths::add);
                }
            }
            byTool.merge(behaviorTool, 1, Integer::sum);
            if (isReadTool(behaviorTool)) {
                readFiles.addAll(paths);
                if (isDirectReadTool(behaviorTool)) {
                    directReadFiles.addAll(paths);
                }
            } else if (isWriteTool(behaviorTool)) {
                writeFiles.addAll(paths);
            }
        }
    }

    private static Optional<PendingTool> bracketToolIn(String line, Path workspaceRoot) {
        var matcher = BRACKET_TOOL.matcher(line);
        if (!matcher.find() || !"completed".equalsIgnoreCase(matcher.group("state"))) {
            return Optional.empty();
        }
        var body = matcher.group("body").trim();
        var toolId = toolIdFromBracketBody(body);
        var tool = toolFromBracketBody(body);
        var pending = new PendingTool(toolId, tool);
        pathsIn(body, workspaceRoot).forEach(pending::addPath);
        fallbackPathFromBody(tool, body, workspaceRoot).ifPresent(pending::addPath);
        if ("Bash".equals(tool) && !isGenericBashBody(body)) {
            pending.setCommand(body);
        }
        return Optional.of(pending);
    }

    private static boolean mergeInputLine(PendingTool pending, String line, Path workspaceRoot) {
        var matcher = INPUT_LINE.matcher(line);
        if (!matcher.find()) {
            return false;
        }
        var body = matcher.group("body");
        pathsIn(body, workspaceRoot).forEach(pending::addPath);
        commandIn(body).ifPresent(command -> {
            pending.setCommand(command);
            classifyCommand(command).ifPresent(pending::setTool);
            commandPath(pending.tool(), command, workspaceRoot).ifPresent(pending::addPath);
        });
        return true;
    }

    private static void record(
            PendingTool pending,
            Map<String, Integer> byTool,
            Set<String> toolIds,
            Set<String> readFiles,
            Set<String> directReadFiles,
            Set<String> writeFiles,
            Set<String> bashCommands,
            Set<String> commandExecutables
    ) {
        var tool = pending.tool();
        byTool.merge(tool, 1, Integer::sum);
        toolIds.add(pending.toolId());
        if (isReadTool(tool)) {
            readFiles.addAll(pending.paths());
            if (isDirectReadTool(tool)) {
                directReadFiles.addAll(pending.paths());
            }
        } else if (isWriteTool(tool)) {
            writeFiles.addAll(pending.paths());
        } else if ("Bash".equals(tool)) {
            pending.command().ifPresent(command -> recordCommand(command, bashCommands, commandExecutables));
        }
        pending.command().ifPresent(command -> executableIn(command).ifPresent(commandExecutables::add));
    }

    private static void recordCommand(String command, Set<String> bashCommands, Set<String> commandExecutables) {
        bashCommands.add(command);
        executableIn(command).ifPresent(commandExecutables::add);
    }

    private static List<String> toolsIn(String line) {
        var tools = new LinkedHashSet<String>();
        var json = JSON_TOOL.matcher(line);
        while (json.find()) {
            tools.add(canonicalTool(json.group("tool")));
        }
        var text = TEXT_TOOL.matcher(line);
        if (text.find()) {
            tools.add(canonicalTool(text.group("tool")));
        }
        return List.copyOf(tools);
    }

    private static List<String> pathsIn(String line, Path workspaceRoot) {
        var paths = new LinkedHashSet<String>();
        var matcher = PATH_VALUE.matcher(line);
        while (matcher.find()) {
            var normalized = normalizePath(unescapeJson(matcher.group("path")), workspaceRoot);
            if (!normalized.isBlank()) {
                paths.add(normalized);
            }
        }
        return List.copyOf(paths);
    }

    private static Optional<String> commandIn(String line) {
        var matcher = COMMAND_VALUE.matcher(line);
        if (matcher.find()) {
            var command = unescapeJson(matcher.group("command")).trim();
            return normalizedCommand(command);
        }
        var array = COMMAND_ARRAY.matcher(line);
        if (!array.find()) {
            return Optional.empty();
        }
        return commandFromArray(array.group("command"));
    }

    private static Optional<String> commandFromArray(String rawArray) {
        var values = new ArrayList<String>();
        var strings = JSON_STRING.matcher(rawArray);
        while (strings.find()) {
            values.add(unescapeJson(strings.group("value")));
        }
        if (values.isEmpty()) {
            return Optional.empty();
        }
        if (values.size() >= 3 && "-lc".equals(values.get(1))) {
            return normalizedCommand(values.get(2));
        }
        return normalizedCommand(String.join(" ", values));
    }

    private static Optional<String> normalizedCommand(String command) {
        if (command.length() > 240) {
            command = command.substring(0, 240) + "...";
        }
        return command.isBlank() ? Optional.empty() : Optional.of(command);
    }

    private static Optional<String> executableIn(String command) {
        var tokens = shellTokens(command);
        for (var token : tokens) {
            var text = unquote(token);
            if (text.isBlank() || text.contains("=") && text.indexOf('=') > 0 && !text.startsWith("./")) {
                continue;
            }
            if ("env".equals(text)) {
                continue;
            }
            return Optional.of(normalizeExecutable(text));
        }
        return Optional.empty();
    }

    private static List<String> shellTokens(String command) {
        var tokens = new ArrayList<String>();
        var current = new StringBuilder();
        char quote = 0;
        for (var i = 0; i < command.length(); i++) {
            var ch = command.charAt(i);
            if (quote != 0) {
                if (ch == quote) {
                    quote = 0;
                } else {
                    current.append(ch);
                }
                continue;
            }
            if (ch == '\'' || ch == '"') {
                quote = ch;
                continue;
            }
            if (Character.isWhitespace(ch)) {
                addShellToken(tokens, current);
                continue;
            }
            if (ch == '&' || ch == '|' || ch == ';') {
                addShellToken(tokens, current);
                break;
            }
            current.append(ch);
        }
        addShellToken(tokens, current);
        return List.copyOf(tokens);
    }

    private static void addShellToken(List<String> tokens, StringBuilder current) {
        if (!current.isEmpty()) {
            tokens.add(current.toString());
            current.setLength(0);
        }
    }

    private static String normalizeExecutable(String value) {
        var text = value.toLowerCase(Locale.ROOT);
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        var slash = text.lastIndexOf('/');
        return slash >= 0 ? text.substring(slash + 1) : text;
    }

    private static String toolFromBracketBody(String body) {
        var command = body.trim();
        return classifyCommand(command).orElse("Bash");
    }

    private static String toolIdFromBracketBody(String body) {
        var command = body.trim();
        return nativeToolId(command).orElse("Bash");
    }

    private static Optional<String> nativeToolId(String command) {
        var lower = command.trim().toLowerCase(Locale.ROOT);
        if (lower.equals("read file")) {
            return Optional.of("Read");
        }
        if (lower.equals("edit")) {
            return Optional.of("Edit");
        }
        if (lower.equals("write")) {
            return Optional.of("Write");
        }
        if (lower.equals("multiedit")) {
            return Optional.of("MultiEdit");
        }
        if (lower.equals("find") || lower.equals("glob")) {
            return Optional.of("Glob");
        }
        if (lower.equals("grep")) {
            return Optional.of("Grep");
        }
        if (lower.equals("ls")) {
            return Optional.of("LS");
        }
        if (lower.equals("task")) {
            return Optional.of("Task");
        }
        return Optional.empty();
    }

    private static Optional<String> classifyCommand(String command) {
        var normalized = command.trim();
        var lower = normalized.toLowerCase(Locale.ROOT);
        if (containsShellControlOperator(lower)) {
            return Optional.of("Bash");
        }
        var tokenTool = classifyCommandTokens(shellTokens(normalized));
        if (tokenTool.isPresent()) {
            return tokenTool;
        }
        if (lower.equals("read file") || lower.startsWith("read ") || lower.startsWith("rtk read ")) {
            return Optional.of("Read");
        }
        if (lower.startsWith("edit ")) {
            return Optional.of("Edit");
        }
        if (lower.startsWith("write ")) {
            return Optional.of("Write");
        }
        if (lower.startsWith("multiedit ")) {
            return Optional.of("MultiEdit");
        }
        if (lower.equals("find") || lower.startsWith("find ") || lower.startsWith("glob ") || lower.startsWith("rtk find ")) {
            return Optional.of("Glob");
        }
        if (lower.startsWith("grep ") || lower.startsWith("rg ") || lower.startsWith("rtk grep ")) {
            return Optional.of("Grep");
        }
        if (lower.equals("ls") || lower.startsWith("ls ") || lower.startsWith("rtk ls ")) {
            return Optional.of("LS");
        }
        if (lower.startsWith("task ")) {
            return Optional.of("Task");
        }
        return Optional.empty();
    }

    private static Optional<String> classifyCommandTokens(List<String> tokens) {
        if (tokens.isEmpty()) {
            return Optional.empty();
        }
        var executable = normalizeExecutable(unquote(tokens.get(0)));
        var commandIndex = 0;
        if ("rtk".equals(executable)) {
            if (tokens.size() < 2) {
                return Optional.empty();
            }
            executable = normalizeExecutable(unquote(tokens.get(1)));
            commandIndex = 1;
        }
        return switch (executable) {
            case "read" -> tokens.size() > commandIndex + 1 ? Optional.of("Read") : Optional.empty();
            case "edit" -> tokens.size() > commandIndex + 1 ? Optional.of("Edit") : Optional.empty();
            case "write" -> tokens.size() > commandIndex + 1 ? Optional.of("Write") : Optional.empty();
            case "multiedit" -> tokens.size() > commandIndex + 1 ? Optional.of("MultiEdit") : Optional.empty();
            case "find", "glob" -> Optional.of("Glob");
            case "grep", "rg" -> Optional.of("Grep");
            case "ls" -> Optional.of("LS");
            case "task" -> tokens.size() > commandIndex + 1 ? Optional.of("Task") : Optional.empty();
            default -> Optional.empty();
        };
    }

    private static boolean containsShellControlOperator(String command) {
        return command.contains("&&") || command.contains("||") || command.contains(";") || command.contains("|");
    }

    private static Optional<String> fallbackPathFromBody(String tool, String body, Path workspaceRoot) {
        if (!isReadTool(tool) && !isWriteTool(tool)) {
            return Optional.empty();
        }
        if ("read file".equalsIgnoreCase(body.trim())) {
            return Optional.empty();
        }
        return commandPath(tool, body, workspaceRoot);
    }

    private static boolean isGenericBashBody(String body) {
        var normalized = body.trim().toLowerCase(Locale.ROOT);
        return "bash".equals(normalized) || "terminal".equals(normalized);
    }

    private static Optional<String> commandPath(String behaviorTool, String command, Path workspaceRoot) {
        var parts = command.trim().split("\\s+");
        if (parts.length == 0) {
            return Optional.empty();
        }
        var index = pathArgumentIndex(behaviorTool, parts);
        while (index >= 0 && index < parts.length && parts[index].startsWith("-")) {
            index++;
        }
        if (index < 0 || index >= parts.length) {
            return Optional.empty();
        }
        var path = normalizePath(unquote(parts[index]), workspaceRoot);
        return path.isBlank() ? Optional.empty() : Optional.of(path);
    }

    private static int pathArgumentIndex(String behaviorTool, String[] parts) {
        if ("Grep".equals(behaviorTool)) {
            return grepPathArgumentIndex(parts);
        }
        if (parts.length >= 3 && isCommand(parts[0], "rtk")) {
            return 2;
        }
        if (parts.length >= 2) {
            return 1;
        }
        return -1;
    }

    private static int grepPathArgumentIndex(String[] parts) {
        if (parts.length < 3) {
            return -1;
        }
        var commandIndex = isCommand(parts[0], "rtk") ? 1 : 0;
        if (commandIndex >= parts.length || !isGrepExecutable(parts[commandIndex])) {
            return -1;
        }
        for (var index = parts.length - 1; index > commandIndex; index--) {
            var value = unquote(parts[index]);
            if (!value.isBlank() && !value.startsWith("-")) {
                return index;
            }
        }
        return -1;
    }

    private static boolean isGrepExecutable(String value) {
        return isCommand(value, "grep") || isCommand(value, "rg");
    }

    private static boolean isCommand(String value, String expected) {
        return normalizeExecutable(value).equals(expected);
    }

    private static String unquote(String text) {
        if ((text.startsWith("`") && text.endsWith("`"))) {
            return text.substring(1, text.length() - 1);
        }
        if ((text.startsWith("\"") && text.endsWith("\"")) || (text.startsWith("'") && text.endsWith("'"))) {
            return text.substring(1, text.length() - 1);
        }
        return text;
    }

    private static String canonicalTool(String tool) {
        return switch (tool.toLowerCase(Locale.ROOT)) {
            case "read" -> "Read";
            case "edit" -> "Edit";
            case "write" -> "Write";
            case "multiedit" -> "MultiEdit";
            case "glob" -> "Glob";
            case "grep" -> "Grep";
            case "bash" -> "Bash";
            case "ls" -> "LS";
            case "task" -> "Task";
            default -> tool;
        };
    }

    private static boolean isReadTool(String tool) {
        return "Read".equals(tool) || "Glob".equals(tool) || "Grep".equals(tool) || "LS".equals(tool);
    }

    private static boolean isDirectReadTool(String tool) {
        return "Read".equals(tool);
    }

    private static boolean isWriteTool(String tool) {
        return "Edit".equals(tool) || "Write".equals(tool) || "MultiEdit".equals(tool);
    }

    private static int countMatching(Map<String, Integer> byTool, String... tools) {
        var total = 0;
        for (var tool : tools) {
            total += byTool.getOrDefault(tool, 0);
        }
        return total;
    }

    private static String normalizePath(String raw, Path workspaceRoot) {
        var text = raw == null ? "" : raw.trim();
        if (text.isBlank()) {
            return "";
        }
        try {
            var path = Path.of(text);
            if (path.isAbsolute() && workspaceRoot != null) {
                var root = workspaceRoot.toAbsolutePath().normalize();
                var normalized = path.toAbsolutePath().normalize();
                if (normalized.startsWith(root)) {
                    return root.relativize(normalized).toString();
                }
            }
        } catch (RuntimeException ignored) {
            return stripRelativePrefix(text);
        }
        return stripRelativePrefix(text);
    }

    private static String stripRelativePrefix(String text) {
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    private static String unescapeJson(String text) {
        return text.replace("\\\"", "\"")
                .replace("\\/", "/")
                .replace("\\\\", "\\");
    }

    private static final class PendingTool {
        private final String toolId;
        private String tool;
        private final List<String> paths = new ArrayList<>();
        private String command;

        private PendingTool(String toolId, String tool) {
            this.toolId = toolId;
            this.tool = tool;
        }

        private String toolId() {
            return toolId;
        }

        private String tool() {
            return tool;
        }

        private void setTool(String tool) {
            this.tool = tool;
        }

        private List<String> paths() {
            return paths;
        }

        private void addPath(String path) {
            if (path != null && !path.isBlank() && !paths.contains(path)) {
                paths.add(path);
            }
        }

        private Optional<String> command() {
            return command == null || command.isBlank() ? Optional.empty() : Optional.of(command);
        }

        private void setCommand(String command) {
            normalizedCommand(command).ifPresent(value -> this.command = value);
        }

        private boolean hasEvidence() {
            return !paths.isEmpty() || command().isPresent();
        }
    }
}

package dev.dual.adapter.acpx;

import java.math.BigDecimal;

/**
 * 一次 acpx agent run 的 token usage 观测事实。
 *
 * <p>三种 measurementType 必须严格区分，不能互相伪装：</p>
 * <ul>
 *     <li>{@link #PROVIDER_RUN_USAGE}：来自 stream 中 {@code result.usage} 的本次 provider
 *     用量，允许聚合进 metrics 总量。</li>
 *     <li>{@link #SESSION_USED_SNAPSHOT}：来自 {@code usage_update.used} 的会话累计/上下文
 *     快照，<b>不允许</b>当作单次 run 用量加总，只能单独展示用于判断 session 是否滚雪球。</li>
 *     <li>{@code ARTIFACT_ESTIMATE}（由 ledger 侧按文件大小估算，不在此 record 构造）：
 *     仅作 fallback，不进入总量。</li>
 * </ul>
 *
 * <p>{@link #attribution} 进一步说明 provider_run_usage 是如何归因到本次 run 的，避免把
 * “最近一条 prompt 的 result”伪装成精确匹配。</p>
 */
record AcpxUsage(
        long inputTokens,
        long outputTokens,
        long cachedReadTokens,
        long cachedWriteTokens,
        long totalTokens,
        BigDecimal costAmount,
        String costCurrency,
        String source,
        String measurementType,
        String attribution,
        boolean cumulative,
        long contextUsedTokens,
        BigDecimal sessionCostAmount,
        String sessionCostCurrency,
        String providerId,
        String model,
        String billingMode,
        String providerMetadataSource,
        String unavailableReason
) {
    static final String PROVIDER_RUN_USAGE = "PROVIDER_RUN_USAGE";
    static final String SESSION_USED_SNAPSHOT = "SESSION_USED_SNAPSHOT";
    static final String UNAVAILABLE = "UNAVAILABLE";

    /** result.usage 精确匹配到本次 prompt 文本。 */
    static final String ATTR_EXACT_PROMPT_MATCH = "EXACT_PROMPT_MATCH";
    /** 无法精确匹配 prompt 文本，按 request id 取会话内最近一条 prompt 的 result.usage。 */
    static final String ATTR_LATEST_PROMPT_IN_SESSION = "LATEST_PROMPT_IN_SESSION";
    /** 只有 usage_update，没有 result.usage，记录为会话累计快照。 */
    static final String ATTR_SESSION_USAGE_UPDATE = "SESSION_USAGE_UPDATE";
    static final String ATTR_MULTI_PROMPT_SUM = "MULTI_PROMPT_SUM";
    AcpxUsage {
        if (measurementType == null || measurementType.isBlank()) {
            measurementType = PROVIDER_RUN_USAGE;
        }
        if (attribution == null) {
            attribution = "";
        }
        if (costCurrency == null) {
            costCurrency = "";
        }
        if (sessionCostCurrency == null) {
            sessionCostCurrency = "";
        }
        if (providerId == null) {
            providerId = "";
        }
        if (model == null) {
            model = "";
        }
        if (billingMode == null) {
            billingMode = "";
        }
        if (providerMetadataSource == null) {
            providerMetadataSource = "";
        }
        if (unavailableReason == null) {
            unavailableReason = "";
        }
    }

    static AcpxUsage unavailable(String reason) {
        return unavailable(reason, AcpxProviderMetadata.empty());
    }

    static AcpxUsage unavailable(String reason, AcpxProviderMetadata metadata) {
        return new AcpxUsage(
                0,
                0,
                0,
                0,
                0,
                null,
                "",
                "not_available",
                UNAVAILABLE,
                "",
                false,
                0,
                null,
                "",
                "",
                "",
                "",
                "",
                reason == null ? "" : reason
        ).withProviderMetadata(metadata);
    }

    AcpxUsage withProviderMetadata(AcpxProviderMetadata metadata) {
        if (metadata == null || metadata.isEmpty()) {
            return this;
        }
        return new AcpxUsage(
                inputTokens,
                outputTokens,
                cachedReadTokens,
                cachedWriteTokens,
                totalTokens,
                costAmount,
                costCurrency,
                source,
                measurementType,
                attribution,
                cumulative,
                contextUsedTokens,
                sessionCostAmount,
                sessionCostCurrency,
                firstNonBlank(providerId, metadata.providerId()),
                firstNonBlank(model, metadata.model()),
                firstNonBlank(billingMode, metadata.billingMode()),
                firstNonBlank(providerMetadataSource, metadata.source()),
                unavailableReason
        );
    }

    AcpxUsage withUnavailableReason(String reason) {
        return new AcpxUsage(
                inputTokens,
                outputTokens,
                cachedReadTokens,
                cachedWriteTokens,
                totalTokens,
                costAmount,
                costCurrency,
                source,
                measurementType,
                attribution,
                cumulative,
                contextUsedTokens,
                sessionCostAmount,
                sessionCostCurrency,
                providerId,
                model,
                billingMode,
                providerMetadataSource,
                reason == null ? "" : reason
        );
    }

    static AcpxUsage aggregatePromptOccurrences(AcpxUsage first, AcpxUsage second) {
        if (first == null) {
            return second;
        }
        if (second == null) {
            return first;
        }
        if (!PROVIDER_RUN_USAGE.equals(first.measurementType)
                || !PROVIDER_RUN_USAGE.equals(second.measurementType)
                || first.cumulative
                || second.cumulative
                || !first.providerId.equals(second.providerId)
                || !first.model.equals(second.model)
                || !first.billingMode.equals(second.billingMode)) {
            return second.withUnavailableReason("MULTI_PROMPT_USAGE_REQUIRES_OCCURRENCE_SUM");
        }
        var currency = first.costCurrency.equals(second.costCurrency) ? first.costCurrency : "";
        var cost = currency.isBlank() || first.costAmount == null || second.costAmount == null
                ? null
                : first.costAmount.add(second.costAmount);
        return new AcpxUsage(
                first.inputTokens + second.inputTokens,
                first.outputTokens + second.outputTokens,
                first.cachedReadTokens + second.cachedReadTokens,
                first.cachedWriteTokens + second.cachedWriteTokens,
                first.totalTokens + second.totalTokens,
                cost,
                currency,
                "agent_result_acquisition",
                PROVIDER_RUN_USAGE,
                ATTR_MULTI_PROMPT_SUM,
                false,
                second.contextUsedTokens,
                second.sessionCostAmount,
                second.sessionCostCurrency,
                second.providerId,
                second.model,
                second.billingMode,
                second.providerMetadataSource,
                ""
        );
    }

    private static String firstNonBlank(String current, String fallback) {
        return current == null || current.isBlank() ? (fallback == null ? "" : fallback) : current;
    }
}

package dev.dual.adapter.acpx;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;
import java.util.regex.Pattern;

/**
 * 读取 acpx session stream 中属于当前 prompt 的 token usage。
 *
 * <p>参数说明：</p>
 * <ul>
 *     <li>{@code promptPath}: 当前 NodeExecution 写入 acpx 的 prompt 文件。</li>
 *     <li>{@code stderrPath}: acpx stderr 文件，用于提取真实 session id。</li>
 * </ul>
 *
 * <p>归因优先级（必须严格区分，不得伪装）：</p>
 * <ol>
 *     <li>优先按 request id 链路定位本次 prompt 的 {@code result.usage}：
 *     先尝试 prompt 文本精确匹配，命中则 {@code attribution=EXACT_PROMPT_MATCH}；
 *     命中不了则取会话内最近一条 {@code session/prompt} 的 request id，再找同 id 的
 *     {@code result.usage}，{@code attribution=LATEST_PROMPT_IN_SESSION}。两者都是真实的
 *     provider run usage，允许聚合。</li>
 *     <li>若该 request id 一直没有 {@code result.usage}（部分 adapter 只回 usage_update），
 *     则把最新 {@code usage_update.used} 记录为 {@code SESSION_USED_SNAPSHOT} 会话累计快照，
 *     {@code attribution=SESSION_USAGE_UPDATE}，<b>不</b>当作单次 run 用量加总。</li>
 *     <li>都没有则返回空，交由 ledger 侧 fallback 到 artifact_estimate。</li>
 * </ol>
 *
 * <p>result.usage 是由 acpx 异步追加到 stream 的，常常晚于 agent 进程退出。本读取器会
 * 在首次没拿到 provider run usage 时按 {@code retryAttempts}×{@code retryDelayMs} 轮询
 * 重读（默认窗口远大于旧的 1.2s），<b>且</b>即便已经看到 usage_update 快照也会继续等
 * provider run usage，避免被早到的快照短路成假阴性的 measured=0。</p>
 *
 * <p>这个类只产出外部 adapter 的结构化观测事实，不参与 workflow 路由，也不解析自然语言正文。</p>
 */
final class AcpxUsageReader {
    private static final int DEFAULT_RETRY_ATTEMPTS = 50;
    private static final long DEFAULT_RETRY_DELAY_MS = 200L;
    private static final String RETRY_ATTEMPTS_ENV = "DUAL_ACPX_USAGE_READ_ATTEMPTS";
    private static final String RETRY_DELAY_ENV = "DUAL_ACPX_USAGE_READ_DELAY_MS";
    private static final Pattern SESSION_ID_PATTERN = Pattern.compile(
            "\\(([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\\)"
    );

    private final Path sessionsDir;
    private final int retryAttempts;
    private final long retryDelayMs;
    private final AcpxProviderMetadata fallbackMetadata;

    AcpxUsageReader() {
        this(Path.of(System.getProperty("user.home"), ".acpx", "sessions"));
    }

    AcpxUsageReader(Path sessionsDir) {
        this(sessionsDir, configuredRetryAttempts(), configuredRetryDelayMs());
    }

    AcpxUsageReader(Path sessionsDir, int retryAttempts, long retryDelayMs) {
        this(sessionsDir, retryAttempts, retryDelayMs, null);
    }

    AcpxUsageReader(Path sessionsDir, int retryAttempts, long retryDelayMs, AcpxProviderMetadata fallbackMetadata) {
        this.sessionsDir = sessionsDir;
        this.retryAttempts = Math.max(1, retryAttempts);
        this.retryDelayMs = Math.max(0, retryDelayMs);
        this.fallbackMetadata = fallbackMetadata;
    }

    private static int configuredRetryAttempts() {
        return envInt(RETRY_ATTEMPTS_ENV, DEFAULT_RETRY_ATTEMPTS);
    }

    private static long configuredRetryDelayMs() {
        return envLong(RETRY_DELAY_ENV, DEFAULT_RETRY_DELAY_MS);
    }

    private static int envInt(String name, int fallback) {
        var value = System.getenv(name);
        if (value == null || value.isBlank()) {
            return fallback;
        }
        try {
            var parsed = Integer.parseInt(value.trim());
            return parsed > 0 ? parsed : fallback;
        } catch (NumberFormatException ignored) {
            return fallback;
        }
    }

    private static long envLong(String name, long fallback) {
        var value = System.getenv(name);
        if (value == null || value.isBlank()) {
            return fallback;
        }
        try {
            var parsed = Long.parseLong(value.trim());
            return parsed >= 0 ? parsed : fallback;
        } catch (NumberFormatException ignored) {
            return fallback;
        }
    }

    Optional<AcpxUsage> read(String agent, Path promptPath, Path stderrPath) {
        try {
            var stderr = Files.exists(stderrPath) ? Files.readString(stderrPath) : "";
            var sessionId = sessionIdFrom(stderr);
            if (sessionId.isEmpty() || !Files.isRegularFile(promptPath)) {
                var metadata = fallbackMetadata != null ? fallbackMetadata : agentFallbackMetadata(agent);
                return metadata.isEmpty()
                        ? Optional.empty()
                        : Optional.of(AcpxUsage.unavailable("NO_ACPX_SESSION_ID", metadata));
            }
            var streamPath = sessionsDir.resolve(sessionId.get() + ".stream.ndjson");
            if (!Files.isRegularFile(streamPath)) {
                return Optional.empty();
            }
            var metadata = AcpxProviderMetadata.read(sessionsDir.resolve(sessionId.get() + ".json"));
            return readMatchingUsageWithRetry(streamPath, Files.readString(promptPath), metadata);
        } catch (IOException ignored) {
            return Optional.empty();
        }
    }

    /**
     * Identity fallback when no current-agent session metadata is observable. Only
     * Claude may reuse Claude settings/env as a labelled fallback; any other agent
     * (e.g. Codex) must remain {@code unknown} rather than be projected through a
     * Claude-specific config. This affects metrics/metadata projection only.
     */
    private static AcpxProviderMetadata agentFallbackMetadata(String agent) {
        return "claude".equals(agent) ? AcpxProviderMetadata.runtimeDefault() : AcpxProviderMetadata.empty();
    }

    private Optional<AcpxUsage> readMatchingUsageWithRetry(
            Path streamPath,
            String promptText,
            AcpxProviderMetadata metadata
    ) throws IOException {
        for (var attempt = 0; attempt < retryAttempts; attempt++) {
            var match = readMatchingUsage(streamPath, promptText);
            if (match.hasProviderUsage() || attempt == retryAttempts - 1) {
                var best = match.best();
                return best == null ? Optional.empty() : Optional.of(best.withProviderMetadata(metadata));
            }
            sleepBeforeRetry();
        }
        return Optional.empty();
    }

    /**
     * 一次扫描 stream 的结果。三档按优先级取：精确 provider &gt; 最近 provider &gt; 会话快照。
     * 包级可见以便单测直接验证归因/优先级，而不依赖重试时序。
     */
    record Match(AcpxUsage exact, AcpxUsage latest, AcpxUsage snapshot) {
        boolean hasProviderUsage() {
            return exact != null || latest != null;
        }

        AcpxUsage best() {
            return exact != null ? exact : latest != null ? latest : snapshot;
        }
    }

    Match readMatchingUsage(Path streamPath, String promptText) throws IOException {
        String matchedRequestId = null;
        String latestPromptRequestId = null;
        AcpxUsage exactUsage = null;
        AcpxUsage fallbackUsage = null;
        AcpxUsage usageUpdateFallback = null;
        BigDecimal costAmount = null;
        String costCurrency = "";
        BigDecimal matchedPromptStartingCost = null;
        BigDecimal latestPromptStartingCost = null;
        for (var line : Files.readAllLines(streamPath)) {
            if (line == null || line.isBlank()) {
                continue;
            }
            var wire = AcpxStreamWireLine.parse(line);
            if (wire.kind() == AcpxStreamWireLine.Kind.MALFORMED) {
                continue;
            }
            if (isPrompt(wire)) {
                var firstPrompt = latestPromptRequestId == null;
                latestPromptRequestId = wire.requestId();
                latestPromptStartingCost = startingCostForPrompt(costAmount, firstPrompt);
                if (matchedRequestId == null && isMatchingPrompt(wire, promptText)) {
                    matchedRequestId = latestPromptRequestId;
                    matchedPromptStartingCost = latestPromptStartingCost;
                }
                continue;
            }
            if (isUsageUpdate(wire)) {
                var update = wire.notification().usageUpdate();
                if (update.costAmount() != null) {
                    costAmount = update.costAmount();
                    costCurrency = update.costCurrency();
                }
                var used = update.used();
                if (used > 0) {
                    usageUpdateFallback = new AcpxUsage(
                            0,
                            0,
                            0,
                            0,
                            0,
                            null,
                            "",
                            "acpx_usage_update",
                            AcpxUsage.SESSION_USED_SNAPSHOT,
                            AcpxUsage.ATTR_SESSION_USAGE_UPDATE,
                            true,
                            used,
                            costAmount,
                            costCurrency,
                            "",
                            "",
                            "",
                            "",
                            ""
                    );
                }
            }
            if (wire.kind() == AcpxStreamWireLine.Kind.JSONRPC_OK
                    && wire.result() != null
                    && wire.result().usage() != null) {
                var requestId = wire.requestId();
                if (matchedRequestId != null && matchedRequestId.equals(requestId)) {
                    exactUsage = usageFrom(
                            wire.result().usage(),
                            matchedPromptStartingCost,
                            costAmount,
                            costCurrency,
                            AcpxUsage.ATTR_EXACT_PROMPT_MATCH
                    );
                }
                if (latestPromptRequestId != null && latestPromptRequestId.equals(requestId)) {
                    fallbackUsage = usageFrom(
                            wire.result().usage(),
                            latestPromptStartingCost,
                            costAmount,
                            costCurrency,
                            AcpxUsage.ATTR_LATEST_PROMPT_IN_SESSION
                    );
                }
            }
        }
        return new Match(exactUsage, fallbackUsage, usageUpdateFallback);
    }

    private BigDecimal startingCostForPrompt(BigDecimal observedCostAmount, boolean firstPrompt) {
        if (observedCostAmount != null) {
            return observedCostAmount;
        }
        return firstPrompt ? BigDecimal.ZERO : null;
    }

    private boolean isPrompt(AcpxStreamWireLine wire) {
        return wire.kind() == AcpxStreamWireLine.Kind.JSONRPC_REQUEST
                && "session/prompt".equals(wire.method());
    }

    private boolean isMatchingPrompt(AcpxStreamWireLine wire, String promptText) {
        return isPrompt(wire)
                && wire.request() != null
                && promptText.equals(wire.request().promptText());
    }

    private AcpxUsage usageFrom(
            AcpxStreamWireLine.Usage usage,
            BigDecimal startingCostAmount,
            BigDecimal sessionCostAmount,
            String sessionCostCurrency,
            String attribution
    ) {
        var runCostAmount = costDelta(startingCostAmount, sessionCostAmount);
        return new AcpxUsage(
                usage.inputTokens(),
                usage.outputTokens(),
                usage.cachedReadTokens(),
                usage.cachedWriteTokens(),
                usage.totalTokens(),
                runCostAmount,
                sessionCostCurrency,
                "acpx_stream",
                AcpxUsage.PROVIDER_RUN_USAGE,
                attribution,
                false,
                0,
                sessionCostAmount,
                sessionCostCurrency,
                "",
                "",
                "",
                "",
                ""
        );
    }

    private BigDecimal costDelta(BigDecimal startingCostAmount, BigDecimal sessionCostAmount) {
        if (sessionCostAmount == null || startingCostAmount == null) {
            return null;
        }
        var delta = sessionCostAmount.subtract(startingCostAmount);
        return delta.signum() < 0 ? null : delta;
    }

    private boolean isUsageUpdate(AcpxStreamWireLine wire) {
        return wire.kind() == AcpxStreamWireLine.Kind.NOTIFICATION
                && "session/update".equals(wire.method())
                && wire.notification() != null
                && wire.notification().usageUpdate() != null;
    }

    private Optional<String> sessionIdFrom(String stderr) {
        if (stderr == null || stderr.isBlank() || !stderr.contains("[acpx] session")) {
            return Optional.empty();
        }
        var matcher = SESSION_ID_PATTERN.matcher(stderr);
        String latest = null;
        while (matcher.find()) {
            latest = matcher.group(1);
        }
        return Optional.ofNullable(latest);
    }

    private void sleepBeforeRetry() {
        if (retryDelayMs == 0) {
            return;
        }
        try {
            Thread.sleep(retryDelayMs);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

