        var map = event.toMap();

        assertEquals("process_started", map.get("kind"));
        assertEquals("stdout", map.get("source"));
        assertEquals(3L, map.get("sequence"));
        assertEquals("2026-06-30T00:00:00Z", map.get("observedAt"));
        assertEquals(1200L, map.get("elapsedMs"));
    }

    @Test
    void serializesDetailsWhenPresent() {
        var event = new AcpxExecutionEvent(
                AgentExecutionTimelineEventKind.PROCESS_WAIT_COMPLETED,
                "adapter",
                4,
                Instant.parse("2026-06-30T00:00:01Z"),
                2200,
                Map.of(
                        "exitCode", 0,
                        "waitMode", "process_exit",
                        "action", "terminate_process_tree"
                )
        );

        var map = event.toMap();

        @SuppressWarnings("unchecked")
        var details = (Map<String, Object>) map.get("details");
        assertEquals(0, details.get("exitCode"));
        assertEquals("process_exit", details.get("waitMode"));
        assertEquals("terminate_process_tree", details.get("action"));
    }

    @Test
    void rejectsMissingKind() {
        assertThrows(IllegalArgumentException.class, () -> new AcpxExecutionEvent(
                null,
                "adapter",
                0,
                Instant.parse("2026-06-30T00:00:00Z"),
                0
        ));
    }
}

package dev.dual.adapter.acpx;

import org.junit.jupiter.api.Test;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Set;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

class AcpxExecutionFactOwnershipBoundaryTest {
    private static final Path PRODUCTION_PACKAGE = Path.of("src/main/java/dev/dual/adapter/acpx");

    @Test
    void deletedPostHocControlOwnersCannotReturn() throws Exception {
        assertFalse(Files.exists(PRODUCTION_PACKAGE.resolve("AcpxFailureClassifier.java")));
        assertFalse(Files.exists(PRODUCTION_PACKAGE.resolve("AcpxSessionStreamFailureEvidenceReader.java")));

        var production = productionSource();
        assertFalse(production.contains("new AcpxFailureClassifier("));
        assertFalse(production.contains("failureClassifier.classify("));
        assertFalse(production.contains("transportFailureResult("));
        assertFalse(production.contains("interruptedOutputFailure("));
        assertFalse(production.contains("readStringIfExists("));
    }

    @Test
    void currentRunProcessResultsAreConstructedOnlyByTransport() throws Exception {
        assertEquals(
                Set.of("AcpxAgentTransport.java"),
                filesContaining("new ProcessResult(")
        );
    }

    @Test
    void wireGrammarHasOnlyLiveControlAndUsageOwners() throws Exception {
        assertEquals(
                Set.of("AgentLifecycleEventReader.java", "AcpxUsageReader.java"),
                filesContaining("AcpxStreamWireLine.parse(")
        );
    }

    private static Set<String> filesContaining(String marker) throws Exception {
        try (var files = Files.list(PRODUCTION_PACKAGE)) {
            return files
                    .filter(path -> path.getFileName().toString().endsWith(".java"))
                    .filter(path -> contains(path, marker))
                    .map(path -> path.getFileName().toString())
                    .collect(Collectors.toUnmodifiableSet());
        }
    }

    private static String productionSource() throws Exception {
        var source = new StringBuilder();
        try (var files = Files.list(PRODUCTION_PACKAGE)) {
            for (var path : files
                    .filter(candidate -> candidate.getFileName().toString().endsWith(".java"))
                    .sorted()
                    .toList()) {
                source.append(Files.readString(path)).append('\n');
            }
        }
        return source.toString();
    }

    private static boolean contains(Path path, String marker) {
        try {
            return Files.readString(path).contains(marker);
        } catch (Exception failure) {
            throw new IllegalStateException("failed to inspect production source " + path, failure);
        }
    }
}

package dev.dual.adapter.acpx;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AcpxFailureSignalCatalogTest {
    private final AcpxFailureSignalCatalog catalog = new AcpxFailureSignalCatalog();

    @Test
    void oldAndCurrentProgressDiagnosticsHaveTheSameFailureOwner() {
        for (var message : List.of(
                "agent accepted the prompt but produced no trusted progress before the progress timeout",
                "agent process produced no observed progress before the progress timeout")) {
            assertEquals("agent_output_interrupted",
                    catalog.match(new AcpxFailureEvidence("", message, 4)).orElseThrow().id());
        }
    }

    @Test
    void matchesRateLimitSignalsAcrossStdoutAndLanguages() {
        var evidence = new AcpxFailureEvidence(
                "[error] RUNTIME: API Error: Request rejected (429) 已达到 5 小时的使用上限",
                "[acpx] session claude-main · agent connected",
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("rate_limit", signal.id());
        assertEquals("RECOVERABLE_RATE_LIMIT", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void matchesProviderOverloadBeforeReconnect() {
        var evidence = new AcpxFailureEvidence(
                "",
                """
                [acpx] session claude-main · agent needs reconnect
                Internal error: API Error: 529 [1305][该模型当前访问量过大，请您稍后再试]
                """,
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("model_overloaded", signal.id());
        assertEquals("RECOVERABLE_AGENT_OVERLOADED", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void matchesModelMismatchBeforeReconnectOrGenericInvalidRequest() {
        var evidence = new AcpxFailureEvidence(
                "",
                """
                [acpx] session claude-main · agent needs reconnect
                Internal error: API Error: 400 {"error":{"message":"The supported API model names are deepseek-v4-pro or deepseek-v4-flash, but you passed glm-5.2.","type":"invalid_request_error"}}
                """,
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("model_mismatch", signal.id());
        assertEquals("RECOVERABLE_AGENT_MODEL_MISMATCH", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void matchesAuthFailureBeforeReconnect() {
        var evidence = new AcpxFailureEvidence(
                """
                [client] session/new (running)
                Failed to authenticate. API Error: 401 Invalid authentication credentials
                [error] RUNTIME: Internal error: Failed to authenticate. API Error: 401 Invalid authentication credentials
                """,
                "[acpx] session claude-main · agent needs reconnect",
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("agent_auth_failed", signal.id());
        assertEquals("RECOVERABLE_AGENT_AUTH_FAILED", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void matchesProviderConnectionFailureBeforeGenericExit() {
        var evidence = new AcpxFailureEvidence(
                "[error] RUNTIME: API Error: Unable to connect to API (FailedToOpenSocket)",
                "",
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("provider_connection_failed", signal.id());
        assertEquals("RECOVERABLE_PROVIDER_CONNECTION_FAILED", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void choosesHighestPrioritySignalInsteadOfListOrder() {
        var catalog = new AcpxFailureSignalCatalog(List.of(
                new AcpxFailureSignal(
                        "agent_reconnect",
                        AcpxFailureReason.AGENT_RECONNECT,
                        10,
                        "reconnect",
                        true,
                        false,
                        List.of(AcpxFailureSignal.contains("agent needs reconnect"))
                ),
                new AcpxFailureSignal(
                        "model_mismatch",
                        AcpxFailureReason.AGENT_MODEL_MISMATCH,
                        100,
                        "model mismatch",
                        true,
                        false,
                        List.of(AcpxFailureSignal.contains("supported api model names"))
                )
        ));
        var evidence = new AcpxFailureEvidence(
                "",
                """
                [acpx] session claude-main · agent needs reconnect
                The supported API model names are deepseek-v4-pro or deepseek-v4-flash, but you passed glm-5.2.
                """,
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("model_mismatch", signal.id());
        assertEquals("RECOVERABLE_AGENT_MODEL_MISMATCH", signal.reason().code());
    }

    @Test
    void matchesReconnectSignalFromStderr() {
        var evidence = new AcpxFailureEvidence("", "[acpx] session claude-main · agent needs reconnect", 5);

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("agent_reconnect", signal.id());
        assertEquals("RECOVERABLE_AGENT_RECONNECT", signal.reason().code());
    }

    @Test
    void matchesAdapterGeneratedOutputInterruptedDiagnostic() {
        var evidence = new AcpxFailureEvidence(
                "",
                "[dual] acpx recoverable signal persisted reason=RECOVERABLE_AGENT_OUTPUT_INTERRUPTED progress_timeout_ms=1000",
                4
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("agent_output_interrupted", signal.id());
        assertEquals("RECOVERABLE_AGENT_OUTPUT_INTERRUPTED", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void rawPermissionWordingCannotCreateCurrentTurnPermissionAuthority() {
        var evidence = new AcpxFailureEvidence(
                """
                <tool_use_error>Cancelled: parallel tool call Bash(ls /repo)
                Tool permission request failed: Error: Tool use aborted
                """,
                "",
                4
        );

        assertTrue(catalog.match(evidence).isEmpty());
    }

    @Test
    void doesNotMatchUnknownExitText() {
        var evidence = new AcpxFailureEvidence("plain failure", "tool exited", 9);

        assertTrue(catalog.match(evidence).isEmpty());
    }

    @Test
    void bareQuotaWordIsNotRateLimit() {
        // "quota" appearing without an explicit rate-limit indicator (e.g. in an
        // unrelated error message or agent prose that reached the catalog) must
        // not classify as RATE_LIMIT.
        var evidence = new AcpxFailureEvidence("", "billing quota update failed", 1);

        var match = catalog.match(evidence);
        assertTrue(match.isEmpty() || match.get().reason() != AcpxFailureReason.RATE_LIMIT);
    }

    @Test
    void sessionIdentifierContainingFourTwentyNineIsNotRateLimit() {
        var evidence = new AcpxFailureEvidence(
                "",
                "Resource not found: 0bf2d846-4e3e-429b-8f6d-86483c3e9326",
                4
        );

        var match = catalog.match(evidence);

        assertTrue(match.isEmpty() || match.get().reason() != AcpxFailureReason.RATE_LIMIT);
    }

    @Test
    void explicitRateLimitIndicatorsClassifyAsRateLimit() {
        for (var text : new String[]{
                "Request rejected (429): too many requests",
                "HTTP 429 from provider",
                "API error: 429",
                "status code 429",
                "rate_limit_exceeded",
                "Rate limit exceeded, please retry",
                "已达到 5 小时的使用上限"
        }) {
            var evidence = new AcpxFailureEvidence("", text, 1);
            var signal = catalog.match(evidence).orElseThrow();
            assertEquals(AcpxFailureReason.RATE_LIMIT, signal.reason(), "expected RATE_LIMIT for: " + text);
        }
    }
}

package dev.dual.adapter.acpx;

import dev.dual.core.execution.AgentExecutionTimelineEventKind;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Offline adapter command boundary: the executable is a local shell fixture, never a provider. */
class AcpxNativeCommandSequenceTest {
    @TempDir Path root;

    @ParameterizedTest @ValueSource(strings = {"claude", "codex"})
    void abnormalPromptAndExplicitRecoveryRecordBeforeEachCommandAndPairOneResult(String agent) throws Exception {
        var events = new ArrayList<AcpxExecutionEvent>();
        var script = executable();
        var transport = new AcpxAgentTransport(script.toString());
        var request = request(event -> {
            events.add(event);
            if (event.kind() == AgentExecutionTimelineEventKind.COMMAND_INTENT) {
                try { Files.writeString(root.resolve("intent"), String.valueOf(event.details().get("command_id"))); }
                catch (java.io.IOException e) { throw new java.io.UncheckedIOException(e); }
            }
        });
        if (agent.equals("claude")) transport.runClaudeDesign(request); else transport.runCodexDesignReview(request);
        assertTrue(transport.stopRecordedSession(agent, request));
        var intents = events.stream().filter(e -> e.kind() == AgentExecutionTimelineEventKind.COMMAND_INTENT).toList();
        var results = events.stream().filter(e -> e.kind() == AgentExecutionTimelineEventKind.COMMAND_RESULT).toList();
        assertEquals(List.of("session_ensure", "session_compatibility", "prompt", "session_cancel", "session_close", "session_cancel", "session_close"),
                intents.stream().map(e -> e.details().get("purpose")).toList());
        assertEquals(intents.size(), results.size());
        assertEquals(intents.stream().map(e -> e.details().get("command_id")).toList(), Files.readAllLines(root.resolve("executed")));
        for (var intent : intents) {
            var matching = results.stream().filter(r -> r.details().get("command_id").equals(intent.details().get("command_id"))).toList();
            assertEquals(1, matching.size(), "pair by identity, including stop commands nested inside prompt completion");
            var result = matching.getFirst();
            var pair = new LinkedHashMap<>(result.details());
            assertNotNull(pair.remove("observation"));
            assertEquals(intent.details(), pair);
            assertTrue(events.indexOf(intent) < events.indexOf(result));
        }
    }

    @ParameterizedTest @ValueSource(strings = {"intent", "result"})
    void failedPersistenceCannotAdvanceToTheNextExternalPhase(String cut) throws Exception {
        var transport = new AcpxAgentTransport(executable().toString());
        var request = request(event -> {
            if (event.kind() == AgentExecutionTimelineEventKind.COMMAND_INTENT) {
                if (cut.equals("intent")) throw new IllegalStateException("intent persistence failed");
                try { Files.writeString(root.resolve("intent"), String.valueOf(event.details().get("command_id"))); }
                catch (java.io.IOException e) { throw new java.io.UncheckedIOException(e); }
            }
            if (event.kind() == AgentExecutionTimelineEventKind.COMMAND_RESULT) throw new IllegalStateException("result persistence failed");
        });
        assertThrows(RuntimeException.class, () -> transport.runCodexDesignReview(request));
        assertEquals(cut.equals("intent") ? 0 : 1, Files.exists(root.resolve("executed")) ? Files.readAllLines(root.resolve("executed")).size() : 0);
    }

    private AcpxRunRequest request(AcpxExecutionEventSink sink) throws Exception {
        var prompt = root.resolve("prompt.md"); Files.writeString(prompt, "Fixture prompt");
        return new AcpxRunRequest(root, "exact-session", prompt, root.resolve("stdout"), root.resolve("stderr"), AcpxPermissionProfile.implement(), sink);
    }

    @ParameterizedTest @ValueSource(booleans = {false, true})
    void revokingPolicyStopsProgressButDoesNotBlockExactSessionCleanup(boolean corrupted) throws Exception {
        var policy = ClaudeExecutionPolicy.write(root, "ws", "node", "run", Files.createDirectories(root.resolve("run")));
        if (corrupted) Files.writeString(root.resolve(policy.ref()), "revoked policy");
        var events = new ArrayList<AcpxExecutionEvent>();
        var initial = request(event -> {
            events.add(event);
            if (event.kind() == AgentExecutionTimelineEventKind.COMMAND_INTENT) {
                try { Files.writeString(root.resolve("intent"), String.valueOf(event.details().get("command_id"))); }
                catch (java.io.IOException failure) { throw new java.io.UncheckedIOException(failure); }
            }
        });
        var bound = new AcpxRunRequest(root, initial.sessionName(), initial.promptPath(), initial.stdoutPath(), initial.stderrPath(),
                initial.permissionProfile(), initial.executionEventSink(), policy);
        assertTrue(new AcpxAgentTransport(executable().toString()).stopRecordedSession("claude", bound));
        assertEquals(List.of("session_cancel", "session_close"), events.stream()
                .filter(e -> e.kind() == AgentExecutionTimelineEventKind.COMMAND_INTENT).map(e -> e.details().get("purpose")).toList());
        assertTrue(events.stream().allMatch(e -> Boolean.TRUE.equals(e.details().get("cleanup"))
                && List.of().equals(e.details().get("request_options"))));
    }
    private Path executable() throws Exception {
        var script = root.resolve("fixture.sh");
        Files.writeString(script, "#!/bin/sh\n[ -s intent ] || exit 93\ncat intent >> executed\nprintf '\\n' >> executed\nrm intent\nfor arg in \"$@\"; do [ \"$arg\" = cancel ] && exit 1; done\nprintf '[done] end_turn\\n'\nexit 0\n");
        Files.writeString(script, Files.readString(script).replace("for arg in", SessionMetadataFixture.RESPONSE + "for arg in"));
        assertTrue(script.toFile().setExecutable(true)); return script;
    }
}

