    private static final class Transport extends AcpxAgentTransport {
        final List<String> calls = new ArrayList<>();
        final Set<String> correctedSessions = new java.util.HashSet<>();
        int corrections;
        String mutation = "";
        String activeId;
        String revisedNode;
        Path revisedRun;
        ObjectNode valid;
        com.fasterxml.jackson.databind.JsonNode bindings;
        AcpxRunRequest initial;
        List<dev.dual.core.execution.AgentExecutionEvidence.ToolObservation> observations = List.of();
        AuthoredExecutionContext.Snapshot snapshot;

        @Override public AcpxRunResult runClaudeDesign(AcpxRunRequest request) throws java.io.IOException { return initial(request); }
        @Override public AcpxRunResult runCodexDesignReview(AcpxRunRequest request) throws java.io.IOException { return initial(request); }

        private AcpxRunResult initial(AcpxRunRequest request) throws java.io.IOException {
            var manifest = JSON.readTree(PromptManifestWriter.manifestPathFor(request.promptPath()).toFile());
            snapshot = JSON.treeToValue(manifest.get("authoredContext"), AuthoredExecutionContext.Snapshot.class);
            calls.add(snapshot.nodeId());
            observations = List.of();
            var decision = snapshot.nodeId().equals("plan.claude_plan") ? "READY_FOR_PLAN_REVIEW"
                    : snapshot.nodeId().equals("plan.codex_plan_review") ? "READY_TO_IMPLEMENT"
                    : snapshot.nodeId().equals("implement.claude_implement") ? "IMPLEMENTED"
                    : snapshot.nodeId().equals("implement.claude_self_test_report") ? "SELF_TEST_COMPLETE" : "READY_FOR_ARCH_REVIEW";
            var prompt = AgentResultPromptContract.render(snapshot.workstreamId(), snapshot.runId(), snapshot.nodeId(), decision, Set.of(decision));
            valid = (ObjectNode) JSON.readTree(prompt.substring(prompt.indexOf('{')));
            var result = (ObjectNode) valid.get("result");
            if (result.has("must_fix")) result.putArray("must_fix");
            if (result.has("plan")) {
                var plan = (ObjectNode) result.get("plan");
                plan.putArray("edit_files").add("repo/relative/new.ext");
                plan.putArray("files").addObject().put("path", "repo/relative/new.ext").put("operation", "CREATE");
                plan.set("verification_bindings", bindings.deepCopy());
                plan.putArray("authority_refs");
            }
            if (result.has("verification_checks")) {
                // Real local fixture observation, not a claim that a native test command ran.
                var content = Files.readString(request.workdir().resolve("README.md"));
                observations = List.of(new dev.dual.core.execution.AgentExecutionEvidence.ToolObservation(
                        "fixture-session", "read-readme", "fixture.read", "read",
                        JSON.valueToTree(Map.of("path", "README.md")), JSON.valueToTree(Map.of("content", content)),
                        "completed", null, null, "", false, List.of()));
                var checks = result.putArray("verification_checks");
                for (var binding : bindings) {
                    var check = checks.addObject().put("criterion_id", binding.path("criterion_id").asText())
                            .put("assertion", "Read the fixture README").put("execution_ref", "CURRENT");
                    check.putArray("tool_call_ids").add("read-readme"); check.putArray("material_refs");
                }
            }
            if (mutation.equals("schema") && result.has("revision_responses")) {
                revisedNode = snapshot.nodeInstanceId();
                revisedRun = request.promptPath().getParent().getParent().resolve("run.json");
                initial = request;
                var invalid = valid.deepCopy();
                ((ObjectNode) invalid.get("result")).remove("checks");
                return output(request, invalid.toString());
            }
            if (result.has("revision_responses")) {
                var responses = result.putArray("revision_responses");
                snapshot.obligations().forEach(obligation -> responses.addObject().put("obligation_id", obligation.id())
                        .put("disposition", "ADDRESSED").put("evidence", "Frozen response"));
                if (!snapshot.obligations().isEmpty()) {
                    activeId = snapshot.obligations().getFirst().id();
                    revisedNode = snapshot.nodeInstanceId();
                    revisedRun = request.promptPath().getParent().getParent().resolve("run.json");
                    initial = request;
                    var invalid = valid.deepCopy();
                    ((ObjectNode) invalid.at("/result/revision_responses/0")).put("obligation_id", activeId + ".old");
                    return output(request, invalid.toString());
                }
            }
            return output(request, valid.toString());
        }

        @Override AcpxRunResult runAgentResultCorrection(String agent, AcpxRunRequest request) throws java.io.IOException {
            corrections++;
            assertTrue(correctedSessions.add(request.sessionName()), "at most one correction for this occurrence");
            assertEquals(initial.sessionName(), request.sessionName());
            assertTrue(request.permissionProfile().denyAll());
            assertFalse(request.permissionProfile().terminalEnabled());
            if (activeId != null) assertTrue(Files.readString(request.promptPath()).contains(activeId));
            if (mutation.equals("schema")) ((ObjectNode) valid.get("result")).put("summary", "Changed conclusion");
            if (mutation.equals("evidence")) ((ObjectNode) valid.at("/result/revision_responses/0")).put("evidence", "Changed response");
            if (mutation.equals("malformed")) ((ObjectNode) valid.at("/result/revision_responses/0")).put("obligation_id", activeId + ".old");
            if (mutation.equals("source")) Files.writeString(request.workdir().resolve(snapshot.trigger().ref()), "{}");
            return output(request, valid.toString());
        }

        private AcpxRunResult output(AcpxRunRequest request, String value) throws java.io.IOException {
            Files.createDirectories(request.stdoutPath().getParent());
            Files.writeString(request.stdoutPath(), "fixture transcript"); Files.writeString(request.stderrPath(), "");
            var now = Instant.now();
            return new AcpxRunResult(now, now.plusMillis(1), List.of("fixture"), List.of(), null,
                    new AcpxPromptCompletion("fixture-request", "end_turn", value),
                    new ProcessResult("fixture", null, 0, ProcessUsability.EXITED_ZERO, 1, "", "", false, false), List.of(), observations);
        }
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ClaudeExecutionPolicyTest {
    private static final ObjectMapper MAPPER = new ObjectMapper();

    @TempDir
    Path tempDir;

    @Test
    void writesFixedFailClosedPolicyAndVerifiesItsLineage() throws Exception {
        var runDir = Files.createDirectories(tempDir.resolve(".agent/workstreams/ws-1/runs/run-1"));

        var binding = ClaudeExecutionPolicy.write(tempDir, "ws-1", "node-1", "run-1", runDir);
        binding.verify(tempDir);

        Map<String, Object> document = MAPPER.readValue(
                tempDir.resolve(binding.ref()).toFile(), new TypeReference<>() {
                });
        assertEquals(ClaudeExecutionPolicy.SCHEMA, document.get("schema_version"));
        assertEquals(ClaudeExecutionPolicy.NETWORK_TRANSPORT_OWNER, document.get("network_transport_owner"));
        assertEquals(List.of("ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL"),
                document.get("provider_subprocess_denied_env_names"));
        assertEquals(List.of(), document.get("setting_sources"));
        var sandbox = map(document.get("sandbox"));
        assertEquals(true, sandbox.get("enabled"));
        assertEquals(true, sandbox.get("fail_if_unavailable"));
        assertEquals(false, sandbox.get("allow_unsandboxed_commands"));
        assertEquals(false, sandbox.get("auto_allow_sandboxed_bash"));
        var network = map(sandbox.get("network"));
        assertEquals(true, network.get("strict_allowlist"));
        assertEquals(List.of(), network.get("allowed_domains"));
        assertEquals(false, network.get("allow_local_binding"));
        assertEquals(List.of(), network.get("allow_unix_sockets"));
        assertEquals(List.of(tempDir.toRealPath().resolve(".agent/workstreams/ws-1/nodes").toString(),
                        tempDir.toRealPath().resolve(".agent/workstreams/ws-1/execution-authority").toString()),
                map(sandbox.get("filesystem")).get("deny_write"));
        var serialized = Files.readString(tempDir.resolve(binding.ref()));
        assertFalse(serialized.contains("secret-value"));
        assertTrue(serialized.contains("ANTHROPIC_AUTH_TOKEN"));
        assertFalse(serialized.contains("HTTP_PROXY"));
        assertFalse(serialized.contains("\"subprocess_denied_env_names\""));
    }

    @Test
    void sandboxBashApprovalFollowsExecuteCapabilityNotTerminalOrWebSearch() throws Exception {
        var profiles = List.of(AcpxPermissionProfile.contractDiscovery(), AcpxPermissionProfile.observe(),
                AcpxPermissionProfile.review(), AcpxPermissionProfile.contractCorrection(),
                AcpxPermissionProfile.review().withAutoApprovedTool("WebSearch"),
                AcpxPermissionProfile.implement());
        for (int i = 0; i < profiles.size(); i++) {
            var profile = profiles.get(i);
            var run = "run-profile-" + i;
            var runDir = Files.createDirectories(tempDir.resolve(".agent/workstreams/ws-1/runs/" + run));
            var binding = ClaudeExecutionPolicy.write(tempDir, "ws-1", "node-1", run, runDir, profile);
            binding.verify(tempDir);
            var document = MAPPER.readTree(tempDir.resolve(binding.ref()).toFile());
            assertEquals(profile.autoApproveKinds().contains("execute") && !profile.denyAll(),
                    document.path("sandbox").path("auto_allow_sandboxed_bash").booleanValue(), profile.name());
        }
    }

    @Test
    void enablesLocalBindingOnlyForImplementProfile() throws Exception {
        var implementRun = Files.createDirectories(tempDir.resolve(".agent/workstreams/ws-1/runs/run-implement"));
        var reviewRun = Files.createDirectories(tempDir.resolve(".agent/workstreams/ws-1/runs/run-review"));

        var implement = ClaudeExecutionPolicy.write(
                tempDir, "ws-1", "node-implement", "run-implement", implementRun,
                AcpxPermissionProfile.implement());
        var review = ClaudeExecutionPolicy.write(
                tempDir, "ws-1", "node-review", "run-review", reviewRun,
                AcpxPermissionProfile.review());

        assertEquals(true, localBinding(implement));
        assertEquals(false, localBinding(review));
        assertTrue(AcpxPermissionProfile.implement().allowsLocalBinding());
        assertFalse(AcpxPermissionProfile.contractDiscovery().allowsLocalBinding());
        assertFalse(AcpxPermissionProfile.observe().allowsLocalBinding());
        assertFalse(AcpxPermissionProfile.review().allowsLocalBinding());
        assertFalse(AcpxPermissionProfile.contractCorrection().allowsLocalBinding());
    }

    @Test
    void rejectsDeletionTamperingAndLineageDrift() throws Exception {
        var runDir = Files.createDirectories(tempDir.resolve(".agent/workstreams/ws-1/runs/run-1"));
        var binding = ClaudeExecutionPolicy.write(tempDir, "ws-1", "node-1", "run-1", runDir);
        var policy = tempDir.resolve(binding.ref());

        Files.writeString(policy, "{}\n", StandardCharsets.UTF_8);
        assertThrows(IOException.class, () -> binding.verify(tempDir));

        var restored = ClaudeExecutionPolicy.write(tempDir, "ws-1", "node-1", "run-1", runDir);
        Files.delete(tempDir.resolve(restored.ref()));
        assertThrows(IOException.class, () -> restored.verify(tempDir));

        var valid = ClaudeExecutionPolicy.write(tempDir, "ws-1", "node-1", "run-1", runDir);
        var wrongLineage = new ClaudeExecutionPolicy.Binding(
                valid.ref(), valid.sha256(), "ws-1", "node-2", "run-1");
        assertThrows(IOException.class, () -> wrongLineage.verify(tempDir));
    }

    @Test
    void rejectsRunDirectoryOutsideWorkspace() throws Exception {
        var outside = Files.createDirectories(tempDir.getParent().resolve("outside-policy-run"));
        try {
            assertThrows(IOException.class,
                    () -> ClaudeExecutionPolicy.write(tempDir, "ws-1", "node-1", "run-1", outside));
        } finally {
            Files.deleteIfExists(outside);
        }
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object value) {
        return (Map<String, Object>) value;
    }

    private boolean localBinding(ClaudeExecutionPolicy.Binding binding) throws IOException {
        Map<String, Object> document = MAPPER.readValue(
                tempDir.resolve(binding.ref()).toFile(), new TypeReference<>() {
                });
        return (boolean) map(map(document.get("sandbox")).get("network")).get("allow_local_binding");
    }
}

