        assertTrue(templateText.contains("Calibration Candidate: candidate-6"));
        assertTrue(templateText.contains("<!-- calibration-candidate: candidate-6 -->"));
        assertTrue(templateText.contains("Prefer contract principles that name observable acceptance evidence."));
