package dev.dual.core.provider;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

public final class ProviderBillingCsvCalibration {
    private ProviderBillingCsvCalibration() {
    }

    public static PairedReport compareUsageAndCost(String usageCsv, String costCsv, ProviderPricingCatalog pricing) {
        var usageReport = parse(usageCsv, pricing);
        var costReport = parse(costCsv, pricing);
        var delta = usageReport.exportedTotal().subtract(costReport.exportedTotal()).abs()
                .setScale(6, RoundingMode.HALF_UP);
        return new PairedReport(usageReport, costReport, delta, costSummaryConsistency(usageReport.exportedTotal(), costReport.exportedTotal()));
    }

    public static Report parse(String csv, ProviderPricingCatalog pricing) {
        var lines = csv == null ? List.<String>of() : csv.lines()
                .filter(line -> !line.isBlank())
                .toList();
        if (lines.size() < 2) {
            return new Report(List.of(), BigDecimal.ZERO, BigDecimal.ZERO, "empty");
        }
        var headers = splitCsv(lines.get(0)).stream()
                .map(ProviderBillingCsvCalibration::normalizeHeader)
                .toList();
        if (headers.contains("type") && headers.contains("price") && headers.contains("amount")) {
            return parseUsageAmountRows(lines, headers, pricing);
        }
        if (headers.contains("cost") && !headers.contains("type") && !hasTokenBreakdown(headers)) {
            return parseCostSummaryRows(lines, headers);
        }
        var rows = new ArrayList<Row>();
        var exportedTotal = BigDecimal.ZERO;
        var calculatedTotal = BigDecimal.ZERO;
        for (int i = 1; i < lines.size(); i++) {
            var values = splitCsv(lines.get(i));
            var item = new LinkedHashMap<String, String>();
            for (int j = 0; j < headers.size() && j < values.size(); j++) {
                item.put(headers.get(j), values.get(j).trim());
            }
            var providerId = text(item, "providerid");
            var model = text(item, "model");
            var currency = text(item, "currency");
            var exported = exportedCost(item);
            var price = pricing.priceFor(providerId, model).orElse(null);
            if (price == null) {
                rows.add(new Row(providerId, model, currency, exported, BigDecimal.ZERO, "pricing_unknown"));
                exportedTotal = exportedTotal.add(exported);
                continue;
            }
            var calculated = price.cost(
                    number(item.get("inputcachehittokens")),
                    number(item.get("inputcachemisstokens")),
                    number(item.get("outputtokens")),
                    number(item.get("cachewritetokens"))
            );
            rows.add(new Row(providerId, model, price.currency(), exported, calculated, consistency(exported, calculated)));
            exportedTotal = exportedTotal.add(exported);
            calculatedTotal = calculatedTotal.add(calculated);
        }
        return new Report(rows, exportedTotal.setScale(6, RoundingMode.HALF_UP),
                calculatedTotal.setScale(6, RoundingMode.HALF_UP),
                consistency(exportedTotal, calculatedTotal));
    }

    private static boolean hasTokenBreakdown(List<String> headers) {
        return headers.contains("inputcachehittokens")
                || headers.contains("inputcachemisstokens")
                || headers.contains("outputtokens")
                || headers.contains("cachewritetokens");
    }

    private static Report parseCostSummaryRows(List<String> lines, List<String> headers) {
        var rows = new ArrayList<Row>();
        var exportedTotal = BigDecimal.ZERO;
        for (int i = 1; i < lines.size(); i++) {
            var values = splitCsv(lines.get(i));
            var item = new LinkedHashMap<String, String>();
            for (int j = 0; j < headers.size() && j < values.size(); j++) {
                item.put(headers.get(j), values.get(j).trim());
            }
            var exported = decimal(item.get("cost"));
            rows.add(new Row("", text(item, "model"), text(item, "currency"), exported, BigDecimal.ZERO,
                    "cost_summary_only"));
            exportedTotal = exportedTotal.add(exported);
        }
        return new Report(rows, exportedTotal.setScale(6, RoundingMode.HALF_UP),
                BigDecimal.ZERO.setScale(6, RoundingMode.HALF_UP),
                rows.isEmpty() ? "empty" : "cost_summary_only");
    }

    private static Report parseUsageAmountRows(
            List<String> lines,
            List<String> headers,
            ProviderPricingCatalog pricing
    ) {
        var aggregates = new LinkedHashMap<String, UsageAggregate>();
        for (int i = 1; i < lines.size(); i++) {
            var values = splitCsv(lines.get(i));
            var item = new LinkedHashMap<String, String>();
            for (int j = 0; j < headers.size() && j < values.size(); j++) {
                item.put(headers.get(j), values.get(j).trim());
            }
            var model = text(item, "model");
            var type = text(item, "type");
            if (model.isBlank() || type.isBlank() || "request_count".equals(type)) {
                continue;
            }
            var key = text(item, "date") + "\t" + model + "\t" + text(item, "apikeyname") + "\t" + text(item, "apikey");
            aggregates.computeIfAbsent(key, ignored -> new UsageAggregate(model))
                    .add(type, number(item.get("amount")), decimal(item.get("price")));
        }

        var rows = new ArrayList<Row>();
        var exportedTotal = BigDecimal.ZERO;
        var calculatedTotal = BigDecimal.ZERO;
        for (var aggregate : aggregates.values()) {
            var price = selectPrice(pricing, aggregate);
            if (price == null) {
                var exported = aggregate.exportedCost();
                rows.add(new Row("", aggregate.model, "", exported, BigDecimal.ZERO, "pricing_unknown"));
                exportedTotal = exportedTotal.add(exported);
                continue;
            }
            var exported = aggregate.exportedCost();
            var calculated = price.cost(
                    aggregate.inputCacheHitTokens,
                    aggregate.inputCacheMissTokens,
                    aggregate.outputTokens,
                    aggregate.cacheWriteTokens
            );
            rows.add(new Row(price.providerId(), aggregate.model, price.currency(), exported, calculated,
                    consistency(exported, calculated)));
            exportedTotal = exportedTotal.add(exported);
            calculatedTotal = calculatedTotal.add(calculated);
        }
        return new Report(rows, exportedTotal.setScale(6, RoundingMode.HALF_UP),
                calculatedTotal.setScale(6, RoundingMode.HALF_UP),
                consistency(exportedTotal, calculatedTotal));
    }

    private static ProviderPricingCatalog.ModelPrice selectPrice(
            ProviderPricingCatalog pricing,
            UsageAggregate aggregate
    ) {
        var candidates = pricing.pricesForModel(aggregate.model);
        if (candidates.size() == 1) {
            return candidates.get(0);
        }
        return candidates.stream()
                .filter(price -> aggregate.matchesObservedPrices(price))
                .findFirst()
                .orElse(null);
    }

    private static String consistency(BigDecimal exported, BigDecimal calculated) {
        if (calculated.signum() <= 0) {
            return exported.signum() <= 0 ? "matches_official_pricing" : "pricing_unknown";
        }
        var drift = calculated.subtract(exported).abs()
                .divide(calculated.max(exported), 4, RoundingMode.HALF_UP);
        return drift.compareTo(new BigDecimal("0.15")) <= 0
                ? "matches_official_pricing"
                : "differs_from_official_pricing";
    }

    private static String costSummaryConsistency(BigDecimal usageExported, BigDecimal costSummaryExported) {
        if (costSummaryExported.signum() <= 0) {
            return usageExported.signum() <= 0 ? "matches_cost_summary" : "cost_summary_missing";
        }
        var drift = usageExported.subtract(costSummaryExported).abs()
                .divide(usageExported.max(costSummaryExported), 4, RoundingMode.HALF_UP);
        return drift.compareTo(new BigDecimal("0.15")) <= 0
                ? "matches_cost_summary"
                : "differs_from_cost_summary";
    }

    private static String text(Map<String, String> row, String key) {
        return row.getOrDefault(key, "").trim();
    }

    private static BigDecimal exportedCost(Map<String, String> row) {
        var amount = decimal(row.get("amount"));
        return amount.signum() != 0 ? amount : decimal(row.get("cost"));
    }

    private static long number(String value) {
        if (value == null || value.isBlank()) {
            return 0;
        }
        try {
            return new BigDecimal(value.trim()).longValue();
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    private static BigDecimal decimal(String value) {
        if (value == null || value.isBlank()) {
            return BigDecimal.ZERO;
        }
        try {
            return new BigDecimal(value.trim());
        } catch (NumberFormatException ignored) {
            return BigDecimal.ZERO;
        }
    }

    private static String normalizeHeader(String value) {
        var normalized = value == null ? "" : value
                .trim()
                .replace("\uFEFF", "")
                .replace("_", "")
                .replace("-", "")
                .replace(" ", "")
                .toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "provider", "providerid", "providername" -> "providerid";
            case "model", "modelid", "modelname" -> "model";
            case "utcdate", "date", "day" -> "date";
            case "apikeyname" -> "apikeyname";
            case "apikey" -> "apikey";
            case "type", "tokentype", "usagetype" -> "type";
            case "price", "unitprice" -> "price";
            case "inputcachehittokens", "cachehittokens", "cachedreadtokens" -> "inputcachehittokens";
            case "inputcachemisstokens", "cachemisstokens", "inputtokens" -> "inputcachemisstokens";
            case "outputtokens", "completiontokens" -> "outputtokens";
            case "cachewritetokens", "cachedwritetokens" -> "cachewritetokens";
            case "cost", "fee" -> "cost";
            case "amount" -> "amount";
            case "currency" -> "currency";
            default -> normalized;
        };
    }

    private static List<String> splitCsv(String line) {
        var out = new ArrayList<String>();
        var current = new StringBuilder();
        var quoted = false;
        for (int i = 0; i < line.length(); i++) {
            var ch = line.charAt(i);
            if (ch == '"') {
                if (quoted && i + 1 < line.length() && line.charAt(i + 1) == '"') {
                    current.append('"');
                    i++;
                } else {
                    quoted = !quoted;
                }
            } else if (ch == ',' && !quoted) {
                out.add(current.toString());
                current.setLength(0);
            } else {
                current.append(ch);
            }
        }
        out.add(current.toString());
        return out;
    }

    public record Row(
            String providerId,
            String model,
            String currency,
            BigDecimal exportedCost,
            BigDecimal calculatedCost,
            String consistency
    ) {
    }

    public record Report(
            List<Row> rows,
            BigDecimal exportedTotal,
            BigDecimal calculatedTotal,
            String consistency
    ) {
        public Report {
            rows = List.copyOf(rows);
        }
    }

    public record PairedReport(
            Report usageReport,
            Report costReport,
            BigDecimal exportedDelta,
            String consistency
    ) {
    }

    private static final class UsageAggregate {
        private final String model;
        private long inputCacheHitTokens;
        private long inputCacheMissTokens;
        private long outputTokens;
        private long cacheWriteTokens;
        private BigDecimal inputCacheHitPrice = BigDecimal.ZERO;
        private BigDecimal inputCacheMissPrice = BigDecimal.ZERO;
        private BigDecimal outputPrice = BigDecimal.ZERO;
        private BigDecimal cacheWritePrice = BigDecimal.ZERO;

        private UsageAggregate(String model) {
            this.model = model;
        }

        private void add(String type, long amount, BigDecimal price) {
            switch (type) {
                case "input_cache_hit_tokens" -> {
                    inputCacheHitTokens += amount;
                    inputCacheHitPrice = nonZero(price, inputCacheHitPrice);
                }
                case "input_cache_miss_tokens" -> {
                    inputCacheMissTokens += amount;
                    inputCacheMissPrice = nonZero(price, inputCacheMissPrice);
                }
                case "output_tokens" -> {
                    outputTokens += amount;
                    outputPrice = nonZero(price, outputPrice);
                }
                case "cache_write_tokens" -> {
                    cacheWriteTokens += amount;
                    cacheWritePrice = nonZero(price, cacheWritePrice);
                }
                default -> {
                    // Unknown usage types do not participate in token cost calibration.
                }
            }
        }

        private BigDecimal exportedCost() {
            return BigDecimal.ZERO
                    .add(inputCacheHitPrice.multiply(BigDecimal.valueOf(inputCacheHitTokens)))
                    .add(inputCacheMissPrice.multiply(BigDecimal.valueOf(inputCacheMissTokens)))
                    .add(outputPrice.multiply(BigDecimal.valueOf(outputTokens)))
                    .add(cacheWritePrice.multiply(BigDecimal.valueOf(cacheWriteTokens)))
                    .setScale(6, RoundingMode.HALF_UP);
        }

        private boolean matchesObservedPrices(ProviderPricingCatalog.ModelPrice price) {
            return matches(inputCacheHitPrice, price.inputCacheHitPer1M())
                    && matches(inputCacheMissPrice, price.inputCacheMissPer1M())
                    && matches(outputPrice, price.outputPer1M())
                    && matches(cacheWritePrice, price.cacheWritePer1M());
        }

        private static boolean matches(BigDecimal observedPerToken, BigDecimal catalogPerMillion) {
            if (observedPerToken.signum() <= 0) {
                return true;
            }
            var expected = catalogPerMillion.divide(BigDecimal.valueOf(1_000_000L), 18, RoundingMode.HALF_UP);
            return observedPerToken.compareTo(expected.stripTrailingZeros()) == 0
                    || observedPerToken.setScale(18, RoundingMode.HALF_UP)
                    .compareTo(expected.setScale(18, RoundingMode.HALF_UP)) == 0;
        }

        private static BigDecimal nonZero(BigDecimal value, BigDecimal fallback) {
            return value.signum() > 0 ? value : fallback;
        }
    }
}

package dev.dual.core.provider;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class ProviderCachePolicy {
    private static final BigDecimal CHEAP_RATIO = new BigDecimal("0.20");
    private static final BigDecimal EXPENSIVE_RATIO = new BigDecimal("0.50");

    private ProviderCachePolicy() {
    }

    public static Decision decide(BigDecimal inputCacheHitPer1M, BigDecimal inputCacheMissPer1M) {
        if (inputCacheHitPer1M == null || inputCacheMissPer1M == null || inputCacheMissPer1M.signum() <= 0) {
            return new Decision("measure_only", "", "pricing missing");
        }
        var ratio = inputCacheHitPer1M.divide(inputCacheMissPer1M, 6, RoundingMode.HALF_UP);
        if (ratio.compareTo(CHEAP_RATIO) <= 0) {
            return new Decision("preserve_session", ratio.toPlainString(), "cache hit is cheap relative to cache miss");
        }
        if (ratio.compareTo(EXPENSIVE_RATIO) >= 0) {
            return new Decision("consider_compaction", ratio.toPlainString(), "cache hit is expensive relative to cache miss");
        }
        return new Decision("measure_only", ratio.toPlainString(), "cache hit economics are moderate");
    }

    public record Decision(String recommendation, String cacheHitToMissRatio, String reason) {
    }
}

package dev.dual.core.provider;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Function;

public final class ProviderCostAttribution {
    private ProviderCostAttribution() {
    }

    public static Map<String, Object> calculate(
            ProviderPricingCatalog pricing,
            Map<String, Object> usage,
            String agent,
            Function<String, String> env
    ) {
        var result = new LinkedHashMap<String, Object>();
        var agentKey = agent == null ? "" : agent.trim().toUpperCase();
        var providerId = nonBlank(
                text(usage.get("providerId")),
                nonBlank(env.apply("DUAL_PROVIDER_ID_" + agentKey), nonBlank(env.apply("DUAL_PROVIDER_ID"), ""))
        );
        var model = nonBlank(
                text(usage.get("model")),
                nonBlank(env.apply("DUAL_MODEL_" + agentKey), nonBlank(env.apply("DUAL_MODEL"), ""))
        );
        var billingMode = normalizeBillingMode(nonBlank(text(usage.get("billingMode")), env.apply("DUAL_BILLING_MODE")));
        result.put("providerId", providerId);
        result.put("model", model);
        result.put("billingMode", billingMode);
        result.put("providerMetadataSource", text(usage.get("providerMetadataSource")));
        result.put("inputCacheHitTokens", longValue(usage.get("cachedReadTokens")));
        result.put("inputCacheMissTokens", longValue(usage.get("inputTokens")));
        result.put("outputTokens", longValue(usage.get("outputTokens")));
        result.put("cacheWriteTokens", longValue(usage.get("cachedWriteTokens")));
        result.put("clientReportedCost", decimalValue(usage.get("costAmount")));
        result.put("clientReportedCurrency", text(usage.get("costCurrency")));
        var type = text(usage.get("measurementType"));
        if (!"PROVIDER_RUN_USAGE".equals(type)) {
            result.put("cacheSignalReliability", "not_applicable");
            result.put("costEstimateReliability", "not_applicable");
            result.put("providerCacheDecision", "not_applicable");
            result.put("reason", "not provider run usage");
            return result;
        }
        if (providerId.isBlank() || model.isBlank()) {
            result.put("cacheSignalReliability", "pricing_unknown");
            result.put("costEstimateReliability", "pricing_unknown");
            result.put("providerCacheDecision", "measure_only");
            result.put("reason", "provider/model missing");
            return result;
        }
        var price = pricing.priceFor(providerId, model).orElse(null);
        if (price == null) {
            if (isSubscriptionTokenBilling(billingMode)) {
                result.put("cacheSignalReliability", longValue(usage.get("cachedReadTokens")) > 0
                        ? "provider_cache_tokens_reported"
                        : "provider_usage_tokens_reported");
                result.put("costEstimateReliability", "subscription_unpriced");
                result.put("providerCacheDecision", "token_policy_active");
                result.put("providerCacheDecisionReason",
                        "provider/model and cache token signal are known; amount is subscription-unpriced");
                result.put("reason", "subscription or bundled billing; token usage is attributable but no per-token cost is visible");
                return result;
            }
            result.put("cacheSignalReliability", "pricing_unknown");
            result.put("costEstimateReliability", "pricing_unknown");
            result.put("providerCacheDecision", "measure_only");
            result.put("reason", "no pricing entry for provider/model");
            return result;
        }
        var policy = ProviderCachePolicy.decide(price.inputCacheHitPer1M(), price.inputCacheMissPer1M());
        result.put("providerCacheDecision", policy.recommendation());
        result.put("providerCacheDecisionReason", policy.reason());
        result.put("cacheHitToMissRatio", policy.cacheHitToMissRatio());
        var calculated = price.cost(
                longValue(usage.get("cachedReadTokens")),
                longValue(usage.get("inputTokens")),
                longValue(usage.get("outputTokens")),
                longValue(usage.get("cachedWriteTokens"))
        );
        var reported = decimalValue(usage.get("costAmount"));
        result.put("officialCalculatedCost", calculated);
        result.put("officialCalculatedCurrency", price.currency());
        result.put("officialPricingSourceUrl", price.sourceUrl());
        result.put("dualCalculatedCost", calculated);
        result.put("dualCalculatedCurrency", price.currency());
        result.put("cacheSignalReliability", longValue(usage.get("cachedReadTokens")) > 0
                ? "provider_cache_tokens_reported"
                : "provider_usage_tokens_reported");
        if ("TOKENS_ONLY".equalsIgnoreCase(price.currency())) {
            result.put("providerCacheDecision", "token_policy_active");
            result.put("providerCacheDecisionReason",
                    "provider/model and cache token signal are known; amount is token-only");
            result.put("costEstimateReliability", "token_only");
            result.put("reason", "provider/model has no visible per-token billing; token usage only");
            return result;
        }
        result.put("costEstimateReliability", "official_pricing");
        if (reported.signum() <= 0) {
            result.put("reason", "client reported cost missing; using official pricing calculation");
            return result;
        }
        var drift = calculated.subtract(reported).abs()
                .divide(calculated.max(reported), 4, RoundingMode.HALF_UP);
        result.put("clientCostDriftRatio", drift);
        if (drift.compareTo(new BigDecimal("0.15")) <= 0) {
            result.put("clientCostConsistency", "matches_official_pricing");
        } else {
            result.put("clientCostConsistency", "differs_from_official_pricing");
        }
        return result;
    }

    public static String normalizeBillingMode(String billingMode) {
        if ("subscription_tokens".equalsIgnoreCase(billingMode) || "token_only".equalsIgnoreCase(billingMode)) {
            return "subscription_token_only";
        }
        return billingMode == null ? "" : billingMode;
    }

    static boolean isSubscriptionTokenBilling(String billingMode) {
        return "subscription_token_only".equalsIgnoreCase(billingMode)
                || "subscription_tokens".equalsIgnoreCase(billingMode)
                || "token_only".equalsIgnoreCase(billingMode);
    }

    static long longValue(Object value) {
        if (value instanceof Number number) {
            return number.longValue();
        }
        if (value != null) {
            try {
                return Long.parseLong(String.valueOf(value));
            } catch (NumberFormatException ignored) {
                return 0;
            }
        }
        return 0;
    }

    static BigDecimal decimalValue(Object value) {
        if (value instanceof BigDecimal decimal) {
            return decimal;
        }
        if (value instanceof Number number) {
            return BigDecimal.valueOf(number.doubleValue());
        }
        if (value != null) {
            try {
                return new BigDecimal(String.valueOf(value));
            } catch (NumberFormatException ignored) {
                return BigDecimal.ZERO;
            }
        }
        return BigDecimal.ZERO;
    }

    private static String nonBlank(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.core.provider;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;

public final class ProviderPricingCatalog {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private static final String DEFAULT_RESOURCE = "/dev/dual/core/provider/provider-pricing.default.json";

    private final List<ModelPrice> prices;

    private ProviderPricingCatalog(List<ModelPrice> prices) {
        this.prices = List.copyOf(prices);
    }

    public static ProviderPricingCatalog load(Path workspaceRoot, ObjectMapper objectMapper) {
        return load(workspaceRoot, objectMapper, System::getenv);
    }

    public static ProviderPricingCatalog load(
            Path workspaceRoot,
            ObjectMapper objectMapper,
            Function<String, String> lookup
    ) {
        var configured = lookup.apply("DUAL_PROVIDER_PRICING_PATH");
        var path = configured == null || configured.isBlank()
                ? workspaceRoot.resolve(".agent").resolve("provider-pricing.json")
                : Path.of(configured);
        if (!Files.isRegularFile(path)) {
            if (configured != null && !configured.isBlank()) {
                return new ProviderPricingCatalog(List.of());
            }
            return loadDefaultResource(objectMapper);
        }
        try {
            return fromDocument(objectMapper.readValue(path.toFile(), MAP_TYPE));
        } catch (IOException ignored) {
            return new ProviderPricingCatalog(List.of());
        }
    }

    private static ProviderPricingCatalog loadDefaultResource(ObjectMapper objectMapper) {
        try (var stream = ProviderPricingCatalog.class.getResourceAsStream(DEFAULT_RESOURCE)) {
            if (stream == null) {
                return new ProviderPricingCatalog(List.of());
            }
            return fromDocument(objectMapper.readValue(stream, MAP_TYPE));
        } catch (IOException ignored) {
            return new ProviderPricingCatalog(List.of());
        }
    }

    private static ProviderPricingCatalog fromDocument(Map<String, Object> doc) {
        var out = new ArrayList<ModelPrice>();
        for (var item : mapList(doc.get("models"))) {
            var providerId = text(item.get("providerId"));
            var model = text(item.get("model"));
            if (providerId.isBlank() || model.isBlank()) {
                continue;
            }
            out.add(new ModelPrice(
                    providerId,
                    model,
                    nonBlank(text(item.get("currency")), "USD"),
                    decimal(item.get("inputCacheHitPer1M")),
                    decimal(item.get("inputCacheMissPer1M")),
                    decimal(item.get("outputPer1M")),
                    decimal(item.get("cacheWritePer1M")),
                    text(item.get("sourceUrl"))
            ));
        }
        return new ProviderPricingCatalog(out);
    }

    public Optional<ModelPrice> priceFor(String providerId, String model) {
        for (var price : prices) {
            if (price.matches(providerId, model)) {
                return Optional.of(price);
            }
        }
        return Optional.empty();
    }

    public List<ModelPrice> pricesForModel(String model) {
        if (model == null || model.isBlank()) {
            return List.of();
        }
        return prices.stream()
                .filter(price -> price.matchesModel(model))
                .toList();
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> mapList(Object value) {
        return value instanceof List<?> list ? (List<Map<String, Object>>) list : List.of();
    }

    private static String nonBlank(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static BigDecimal decimal(Object value) {
        if (value instanceof BigDecimal decimal) {
            return decimal;
        }
        if (value instanceof Number number) {
            return BigDecimal.valueOf(number.doubleValue());
        }
        if (value != null) {
            try {
                return new BigDecimal(String.valueOf(value));
            } catch (NumberFormatException ignored) {
                return BigDecimal.ZERO;
            }
        }
        return BigDecimal.ZERO;
    }

    public record ModelPrice(
            String providerId,
            String model,
            String currency,
            BigDecimal inputCacheHitPer1M,
            BigDecimal inputCacheMissPer1M,
            BigDecimal outputPer1M,
            BigDecimal cacheWritePer1M,
            String sourceUrl
    ) {
        public boolean matches(String candidateProvider, String candidateModel) {
            return providerId.equalsIgnoreCase(candidateProvider)
                    && matchesModel(candidateModel);
        }

        public boolean matchesModel(String candidateModel) {
            return model.equals(candidateModel)
                    || (model.endsWith("*") && candidateModel.startsWith(model.substring(0, model.length() - 1)));
        }

        public BigDecimal cost(long cacheHit, long cacheMiss, long output, long cacheWrite) {
            return BigDecimal.ZERO
                    .add(perMillion(cacheHit, inputCacheHitPer1M))
                    .add(perMillion(cacheMiss, inputCacheMissPer1M))
                    .add(perMillion(output, outputPer1M))
                    .add(perMillion(cacheWrite, cacheWritePer1M))
                    .setScale(6, RoundingMode.HALF_UP);
        }

        private BigDecimal perMillion(long tokens, BigDecimal price) {
            if (tokens <= 0 || price == null || price.signum() == 0) {
                return BigDecimal.ZERO;
            }
            return price.multiply(BigDecimal.valueOf(tokens))
                    .divide(BigDecimal.valueOf(1_000_000L), 12, RoundingMode.HALF_UP);
        }
    }
}

