package dev.dual.ledger.file;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.WorkflowDefinition;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

public final class CompletionAuditWriter {
    private static final TypeReference<java.util.Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper objectMapper;

    public CompletionAuditWriter(AtomicJsonWriter jsonWriter) {
        this.jsonWriter = jsonWriter;
        this.objectMapper = jsonWriter.objectMapper();
    }

    public CompletionAuditDocument write(
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            NodeInstanceDocument finalNode,
            String finalOutcome,
            Instant completedAt
    ) throws IOException {
        var audit = evaluate(paths, definition, finalNode.nodeDefinitionId(), finalOutcome, completedAt);
        jsonWriter.write(paths.completionAuditJson(), audit);
        return audit;
    }

    public CompletionAuditDocument evaluate(
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            String finalNodeDefinitionId,
            String finalOutcome,
            Instant completedAt
    ) {
        var gaps = new ArrayList<String>();
        auditFinalReport(paths, gaps);
        if (requiresArtifact(definition, "stage_handoff")) {
            auditHandoff(paths, gaps);
        }
        if (requiresHandler(definition, "prompt.generate_next_stage")) {
            auditNextStagePrompt(paths, gaps);
        }
        return new CompletionAuditDocument(
                1,
                "ENDED",
                gaps.isEmpty() ? "ready" : "needs_review",
                "COMPLETED",
                blankToEmpty(finalNodeDefinitionId),
                blankToEmpty(finalOutcome),
                List.copyOf(gaps),
                completedAt,
                Instant.now()
        );
    }

    private static boolean requiresArtifact(WorkflowDefinition definition, String artifactType) {
        return definition.nodes().stream()
                .anyMatch(node -> artifactType.equals(text(node.config().get("expected_artifact"))));
    }

    private static boolean requiresHandler(WorkflowDefinition definition, String handlerType) {
        return definition.nodes().stream().anyMatch(node -> handlerType.equals(node.handlerType()));
    }

    private void auditFinalReport(WorkstreamPaths paths, List<String> gaps) {
        var reportPath = paths.workstreamDir().resolve("reports").resolve("latest-final-report.md");
        if (!Files.isRegularFile(reportPath)) {
            gaps.add("final report is missing");
            return;
        }
        var report = readText(reportPath);
        for (var heading : List.of("## User Request", "## Verification Evidence", "## Acceptance Summary", "## Git Evidence")) {
            if (!report.contains(heading)) {
                gaps.add("final report missing " + heading);
            }
        }
    }

    private void auditHandoff(WorkstreamPaths paths, List<String> gaps) {
        var handoffPath = paths.workstreamDir().resolve("artifacts").resolve("next-stage").resolve("handoff.json");
        if (!Files.isRegularFile(handoffPath)) {
            gaps.add("handoff.json is missing");
            return;
        }
        var handoff = readJson(handoffPath);
        if (text(handoff.get("workstreamId")).isBlank()) {
            gaps.add("handoff.json missing workstreamId");
        }
        if (textList(handoff.get("completedWork")).isEmpty() && textList(handoff.get("changedFiles")).isEmpty()) {
            gaps.add("handoff.json has no completedWork or changedFiles");
        }
        if (text(handoff.get("recommendedNextStage")).isBlank()
                && text(handoff.get("suggestedNextPrompt")).isBlank()) {
            gaps.add("handoff.json has no recommendedNextStage or suggestedNextPrompt");
        }
    }

    private void auditNextStagePrompt(WorkstreamPaths paths, List<String> gaps) {
        var promptPath = paths.workstreamDir().resolve("artifacts").resolve("next-stage").resolve("next-stage-prompt.md");
        if (!Files.isRegularFile(promptPath)) {
            gaps.add("next-stage prompt is missing");
            return;
        }
        var prompt = readText(promptPath);
        if (!prompt.contains("## Prompt")) {
            gaps.add("next-stage prompt missing ## Prompt section");
        }
        if (!prompt.contains("## Handoff Context")) {
            gaps.add("next-stage prompt missing ## Handoff Context section");
        }
    }

    private java.util.Map<String, Object> readJson(java.nio.file.Path path) {
        try {
            return jsonWriter.read(path, MAP_TYPE);
        } catch (IOException ignored) {
            return java.util.Map.of();
        }
    }

    private static String readText(java.nio.file.Path path) {
        try {
            return Files.readString(path, StandardCharsets.UTF_8);
        } catch (IOException ignored) {
            return "";
        }
    }

    private static List<String> textList(Object value) {
        if (value instanceof List<?> list) {
            return list.stream().map(String::valueOf).toList();
        }
        return List.of();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private static String blankToEmpty(String value) {
        return value == null ? "" : value;
    }
}

package dev.dual.ledger.file;

import java.time.Instant;
import java.util.List;

/** Immutable byte identity presented to the final human acceptance gate. */
public record DeliveryCandidateDocument(
        int schemaVersion,
        String workstreamId,
        String producerNodeInstanceId,
        String iterationId,
        String sourceWorkspaceId,
        String sourceEffectiveWorkdir,
        String baseCommit,
        String baseTree,
        List<String> acceptedFiles,
        List<String> excludedFiles,
        ArtifactReference patch,
        String expectedResultTree,
        ArtifactReference commitMessage,
        ArtifactReference prBody,
        Instant createdAt
) {
    public DeliveryCandidateDocument {
        if (schemaVersion <= 0) throw new IllegalArgumentException("schemaVersion must be positive");
        requireText(workstreamId, "workstreamId");
        requireText(producerNodeInstanceId, "producerNodeInstanceId");
        requireText(iterationId, "iterationId");
        requireText(sourceWorkspaceId, "sourceWorkspaceId");
        requireText(sourceEffectiveWorkdir, "sourceEffectiveWorkdir");
        requireHash(baseCommit, "baseCommit");
        requireHash(baseTree, "baseTree");
        acceptedFiles = sortedCopy(acceptedFiles, "acceptedFiles", false);
        excludedFiles = sortedCopy(excludedFiles, "excludedFiles", true);
        if (patch == null) throw new IllegalArgumentException("patch is required");
        requireHash(expectedResultTree, "expectedResultTree");
        if (commitMessage == null) throw new IllegalArgumentException("commitMessage is required");
        if (prBody == null) throw new IllegalArgumentException("prBody is required");
        if (createdAt == null) throw new IllegalArgumentException("createdAt is required");
    }

    private static List<String> sortedCopy(List<String> values, String field, boolean allowEmpty) {
        var copy = List.copyOf(values == null ? List.of() : values);
        if (!allowEmpty && copy.isEmpty()) throw new IllegalArgumentException(field + " is required");
        copy.forEach(value -> requireText(value, field));
        var sorted = copy.stream().sorted().toList();
        if (!copy.equals(sorted) || copy.stream().distinct().count() != copy.size()) {
            throw new IllegalArgumentException(field + " must be sorted and unique");
        }
        return copy;
    }

    private static void requireHash(String value, String field) {
        requireText(value, field);
        if (!value.matches("[0-9a-f]{40}|[0-9a-f]{64}")) {
            throw new IllegalArgumentException(field + " must be a lowercase Git or SHA-256 identity");
        }
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(field + " is required");
    }

    public record ArtifactReference(String ref, String sha256) {
        public ArtifactReference {
            requireText(ref, "artifact ref");
            requireText(sha256, "artifact sha256");
            if (!sha256.matches("[0-9a-f]{64}")) {
                throw new IllegalArgumentException("artifact sha256 must be 64 lowercase hexadecimal characters");
            }
        }
    }
}

package dev.dual.ledger.file;

import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Map;
import java.util.UUID;

/** Atomically publishes one immutable candidate occurrence. */
public final class DeliveryCandidateWriter {
    private final AtomicJsonWriter jsonWriter;

    public DeliveryCandidateWriter() {
        this(new AtomicJsonWriter());
    }

    DeliveryCandidateWriter(AtomicJsonWriter jsonWriter) {
        this.jsonWriter = jsonWriter;
    }

    public Published publish(
            WorkstreamPaths paths,
            DeliveryCandidateDocument candidate,
            Map<String, byte[]> artifacts
    ) throws IOException {
        var finalDir = paths.deliveryCandidateDir(candidate.producerNodeInstanceId()).toAbsolutePath().normalize();
        var existing = existing(paths, candidate.producerNodeInstanceId());
        if (existing != null) return existing;

        Files.createDirectories(paths.deliveryCandidatesDir());
        var temporaryDir = paths.deliveryCandidatesDir().resolve(
                ".tmp-" + candidate.producerNodeInstanceId() + "-" + UUID.randomUUID()
        );
        Files.createDirectories(temporaryDir);
        try {
            for (var entry : artifacts.entrySet()) {
                requireFileName(entry.getKey());
                Files.write(temporaryDir.resolve(entry.getKey()), entry.getValue());
            }
            verifyArtifactReferences(paths, finalDir, temporaryDir, candidate);
            var candidateBytes = jsonWriter.objectMapper().writeValueAsBytes(candidate);
            var candidateSha = sha256(candidateBytes);
            var candidateName = "candidate-" + candidateSha + ".json";
            Files.write(temporaryDir.resolve(candidateName), candidateBytes);
            moveDirectory(temporaryDir, finalDir);
            var candidatePath = finalDir.resolve(candidateName);
            return new Published(workspaceRef(paths, candidatePath), candidateSha, candidate, candidatePath);
        } finally {
            deleteRecursively(temporaryDir);
        }
    }

    public Published existing(WorkstreamPaths paths, String producerNodeInstanceId) throws IOException {
        var dir = paths.deliveryCandidateDir(producerNodeInstanceId);
        if (!Files.isDirectory(dir)) return null;
        try (var stream = Files.list(dir)) {
            var candidates = stream
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().matches("candidate-[0-9a-f]{64}\\.json"))
                    .toList();
            if (candidates.size() != 1) {
                throw new IOException("delivery candidate occurrence must contain exactly one candidate document: " + dir);
            }
            var path = candidates.get(0);
            var bytes = Files.readAllBytes(path);
            var sha = sha256(bytes);
            if (!path.getFileName().toString().equals("candidate-" + sha + ".json")) {
                throw new IOException("delivery candidate filename SHA does not match its bytes: " + path);
            }
            var document = jsonWriter.objectMapper().readValue(bytes, DeliveryCandidateDocument.class);
            if (!producerNodeInstanceId.equals(document.producerNodeInstanceId())) {
                throw new IOException("delivery candidate producer node does not match occurrence directory");
            }
            verifyArtifactReferences(paths, dir.toAbsolutePath().normalize(), dir, document);
            return new Published(workspaceRef(paths, path), sha, document, path);
        }
    }

    private void verifyArtifactReferences(
            WorkstreamPaths paths,
            Path finalDir,
            Path actualDir,
            DeliveryCandidateDocument candidate
    ) throws IOException {
        for (var reference : new DeliveryCandidateDocument.ArtifactReference[]{
                candidate.patch(), candidate.commitMessage(), candidate.prBody()
        }) {
            var expectedFinal = paths.workspaceRoot().resolve(reference.ref()).toAbsolutePath().normalize();
            if (!expectedFinal.startsWith(finalDir) || expectedFinal.equals(finalDir)) {
                throw new IOException("delivery candidate artifact ref is outside its occurrence: " + reference.ref());
            }
            var actual = actualDir.resolve(expectedFinal.getFileName());
            if (!Files.isRegularFile(actual) || !reference.sha256().equals(sha256(Files.readAllBytes(actual)))) {
                throw new IOException("delivery candidate artifact SHA does not match: " + reference.ref());
            }
        }
    }

    private static void moveDirectory(Path source, Path target) throws IOException {
        try {
            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE);
        } catch (AtomicMoveNotSupportedException unsupported) {
            Files.move(source, target);
        }
    }

    private static void requireFileName(String value) {
        if (value == null || value.isBlank() || !Path.of(value).getFileName().toString().equals(value)) {
            throw new IllegalArgumentException("delivery candidate artifact name must be a file name");
        }
    }

    private static String workspaceRef(WorkstreamPaths paths, Path path) {
        return paths.workspaceRoot().toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    public static String sha256(byte[] bytes) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException("SHA-256 is unavailable", impossible);
        }
    }

    private static void deleteRecursively(Path root) throws IOException {
        if (!Files.exists(root)) return;
        try (var stream = Files.walk(root)) {
            for (var path : stream.sorted(java.util.Comparator.reverseOrder()).toList()) {
                Files.deleteIfExists(path);
            }
        }
    }

    public record Published(
            String ref,
            String sha256,
            DeliveryCandidateDocument document,
            Path path
    ) {
    }
}

