    package dev.dual.ledger.file;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.ser.std.StdSerializer;
import dev.dual.core.workflow.EdgeCondition;

import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Jackson module for serializing/deserializing {@link EdgeCondition} polymorphic instances.
 * Uses the {@code type()} and {@code params()} methods on EdgeCondition so the module
 * stays decoupled from concrete implementation classes.
 */
public final class EdgeConditionModule extends SimpleModule {

    public EdgeConditionModule() {
        super("EdgeConditionModule");
        addSerializer(EdgeCondition.class, new Serializer());
        addDeserializer(EdgeCondition.class, new Deserializer());
    }

    static final class Serializer extends StdSerializer<EdgeCondition> {
        Serializer() { super(EdgeCondition.class); }

        @Override
        public void serialize(EdgeCondition value, JsonGenerator gen, SerializerProvider provider) throws IOException {
            // Unconditional → write null (consumers treat missing/null condition as unconditional)
            if ("unconditional".equals(value.type())) {
                gen.writeNull();
                return;
            }
            gen.writeStartObject();
            gen.writeStringField("type", value.type());
            gen.writeObjectFieldStart("params");
            for (var entry : value.params().entrySet()) {
                gen.writeObjectField(entry.getKey(), entry.getValue());
            }
            gen.writeEndObject();
            gen.writeEndObject();
        }
    }

    static final class Deserializer extends StdDeserializer<EdgeCondition> {
        Deserializer() { super(EdgeCondition.class); }

        @Override
        public EdgeCondition deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            JsonNode node = p.getCodec().readTree(p);
            if (node == null || node.isNull()) {
                return EdgeCondition.unconditional();
            }
            String type = node.has("type") ? node.get("type").asText() : "unconditional";
            Map<String, Object> params = new LinkedHashMap<>();
            if (node.has("params") && node.get("params").isObject()) {
                var fields = node.get("params").fields();
                while (fields.hasNext()) {
                    var entry = fields.next();
                    params.put(entry.getKey(), textValue(entry.getValue()));
                }
            }
            return EdgeCondition.fromTypeAndParams(type, params);
        }

        private static Object textValue(JsonNode node) {
            if (node.isTextual()) return node.asText();
            if (node.isNumber()) return node.numberValue();
            if (node.isBoolean()) return node.asBoolean();
            return node.asText();
        }
    }
}

package dev.dual.ledger.file;

import dev.dual.core.contract.TaskContractValidator;
import java.util.List;

/** Machine-produced approval fact; not a model-supplied permission grant. */
public record EvidenceCollectionBaseline(String gateNodeInstanceId, String contractRef, String contractSha256,
                                         String head, String indexSha256, String sourceSha256,
                                         List<String> paths) {
    public EvidenceCollectionBaseline {
        if (gateNodeInstanceId == null || !gateNodeInstanceId.matches("[A-Za-z0-9._-]+")
                || contractRef == null || !contractRef.matches("\\.agent/workstreams/[A-Za-z0-9_-]+/artifacts/contracts/[A-Za-z0-9._-]+/task-contract\\.json")
                || !sha(contractSha256) || !sha(indexSha256) || !sha(sourceSha256)
                || head == null || !head.matches("[0-9a-f]{40}|[0-9a-f]{64}") || paths == null || paths.isEmpty()) {
            throw new IllegalArgumentException("invalid evidence collection baseline");
        }
        paths = List.copyOf(paths);
        if (!paths.equals(paths.stream().distinct().sorted().toList()) || paths.stream().anyMatch(path ->
                !TaskContractValidator.isCanonicalPath(path) || path.equals(".git") || path.startsWith(".git/")
                        || path.equals(".agent") || path.startsWith(".agent/"))) {
            throw new IllegalArgumentException("invalid evidence collection source paths");
        }
    }
    private static boolean sha(String value) { return value != null && value.matches("[0-9a-f]{64}"); }
}

package dev.dual.ledger.file;

/** Machine-owned reference to a prepared external verification submission. */
public record EvidenceSubmission(String requestId, String preparationRef, String preparationSha256,
                                 String manifestRef, String manifestSha256, EvidenceCollectionBaseline baseline) {
    public EvidenceSubmission {
        if (requestId == null || !requestId.matches("[A-Za-z0-9._-]{1,80}") || baseline == null
                || !reference(preparationRef) || !reference(manifestRef)
                || !sha(preparationSha256) || !sha(manifestSha256))
            throw new IllegalArgumentException("invalid external evidence submission");
    }
    private static boolean reference(String ref) {
        return ref != null && ref.matches("\\.agent/workstreams/[A-Za-z0-9_-]+/artifacts/verification/[A-Za-z0-9._/-]+")
                && !ref.contains("..") && !ref.contains("//");
    }
    private static boolean sha(String value) { return value != null && value.matches("[0-9a-f]{64}"); }
}

package dev.dual.ledger.file;

import java.util.Map;

/**
 * Shared read-model classifier for legacy run status vs typed execution facts.
 *
 * <p>This is projection semantics, not a workflow transition owner. It exists so
 * CLI/API/report projections do not each invent their own consistency rules.</p>
 */
public final class ExecutionConsistencyClassifier {
    private ExecutionConsistencyClassifier() {
    }

    public static String classify(Map<String, Object> run) {
        var attempt = map(run.get("executionAttempt"));
        var outcome = map(run.get("executionOutcome"));
        if (attempt.isEmpty() && outcome.isEmpty()) {
            return "missing_attempt_and_outcome";
        }
        if (attempt.isEmpty()) {
            return "missing_attempt";
        }
        if (outcome.isEmpty()) {
            return "missing_outcome";
        }
        var legacyStatus = text(run.get("status"));
        var attemptStatus = text(attempt.get("status"));
        var outcomeStatus = text(outcome.get("status"));
        var nodeMaySucceed = Boolean.TRUE.equals(outcome.get("nodeMaySucceed"));
        if (nodeMaySucceed && !"COMPLETED".equals(attemptStatus)) {
            return "attempt_outcome_conflict";
        }
        if (!nodeMaySucceed && "COMPLETED".equals(attemptStatus)) {
            return "attempt_outcome_conflict";
        }
        if ("running".equals(legacyStatus) && isTerminalAttemptStatus(attemptStatus)) {
            return "stale_legacy_running";
        }
        if (nodeMaySucceed && !"completed".equals(legacyStatus)) {
            return "legacy_outcome_conflict";
        }
        if (!nodeMaySucceed && "completed".equals(legacyStatus)) {
            return "legacy_outcome_conflict";
        }
        return outcomeStatus.isBlank() ? "missing_outcome_status" : "consistent";
    }

    private static boolean isTerminalAttemptStatus(String value) {
        return !value.isBlank() && !"RUNNING".equals(value);
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object value) {
        if (value instanceof Map<?, ?> map) {
            return (Map<String, Object>) map;
        }
        return Map.of();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.WorkflowStatus;

import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

/**
 * Writes durable execution facts for workflow and node executions.
 *
 * This writer is intentionally narrow: it records runtime evidence such as
 * status, pid, duration, output refs, adapter metadata, and exceptions. It does
 * not route workflow state and does not decide whether the product goal is
 * satisfied; those belong to workflow routing and domain artifacts.
 */
final class ExecutionLedgerWriter {
    private final AtomicJsonWriter jsonWriter;

    ExecutionLedgerWriter(AtomicJsonWriter jsonWriter) {
        this.jsonWriter = jsonWriter;
    }

    WorkflowExecutionDocument startWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            String trigger
    ) throws IOException {
        var authoritative = jsonWriter.read(paths.workflowCurrentJson(), WorkflowCurrentDocument.class);
        if (!authoritative.equals(current) || authoritative.status().isTerminal())
            throw new IOException("cannot start execution from terminal or stale workflow state");
        for (var id : authoritative.activeNodeInstanceIds()) {
            var active = jsonWriter.read(paths.nodeJson(id), NodeInstanceDocument.class);
            if (active.status() == NodeStatus.COMPLETED)
                throw new IOException("active workflow points to a completed node without a pending commit");
        }
        for (var id : authoritative.openGateIds()) {
            var gate = jsonWriter.read(paths.gateJson(id), GateDocument.class);
            if (!"open".equals(gate.status()) || !authoritative.activeNodeInstanceIds().contains(gate.nodeInstanceId()))
                throw new IOException("current open gate is resolved or belongs to another occurrence");
        }
        var now = Instant.now();
        var document = new WorkflowExecutionDocument(
                1,
                nextId("wfe"),
                current.workflowInstanceId(),
                paths.workstreamId().value(),
                textOrDefault(trigger, "resume"),
                WorkflowExecutionStatus.RUNNING,
                List.of(),
                "",
                now,
                null,
                null
        );
        jsonWriter.write(paths.workflowExecutionJson(document.workflowExecutionId()), document);
        return document;
    }

    WorkflowExecutionDocument finishWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            List<String> nodeExecutionIds,
            WorkflowExecutionStatus status,
            String stopReason
    ) throws IOException {
        var finishedAt = Instant.now();
        var document = new WorkflowExecutionDocument(
                workflowExecution.schemaVersion(),
                workflowExecution.workflowExecutionId(),
                workflowExecution.workflowInstanceId(),
                workflowExecution.workstreamId(),
                workflowExecution.trigger(),
                status == null ? WorkflowExecutionStatus.STOPPED : status,
                List.copyOf(nodeExecutionIds == null ? List.of() : nodeExecutionIds),
                stopReason == null ? "" : stopReason,
                workflowExecution.startedAt(),
                finishedAt,
                durationMs(workflowExecution.startedAt(), finishedAt)
        );
        jsonWriter.write(paths.workflowExecutionJson(document.workflowExecutionId()), document);
        return document;
    }

    NodeExecutionDocument startNodeExecution(
            WorkstreamPaths paths,
            String workflowExecutionId,
            NodeInstanceDocument node,
            AgentTaskDocument agentTask,
            long pid
    ) throws IOException {
        var current = jsonWriter.read(paths.workflowCurrentJson(), WorkflowCurrentDocument.class);
        var actual = jsonWriter.read(paths.nodeJson(node.nodeInstanceId()), NodeInstanceDocument.class);
        if (agentTask == null || current.status().isTerminal()
                || !current.activeNodeInstanceIds().contains(node.nodeInstanceId()) || !actual.equals(node))
            throw new IOException("execution requires a task bound to the current eligible node");
        var task = jsonWriter.read(paths.agentTaskJson(agentTask.agentTaskId()), AgentTaskDocument.class);
        if (!task.equals(agentTask) || task.status() != AgentTaskStatus.QUEUED
                || !task.nodeInstanceId().equals(node.nodeInstanceId()))
            throw new IOException("task is not available for a unique claim");
        boolean queued = node.status() == NodeStatus.RUNNING
                && task.agentTaskId().equals(node.result().get("queued_agent_task_id"))
                && "QUEUED".equals(node.result().get("dispatch_state"));
        if (node.status() != NodeStatus.READY && !queued)
            throw new IOException("node is neither READY nor waiting for this queued task");
        var previous = latestNodeExecution(paths, node);
        if (previous.isPresent() && previous.get().status() == NodeExecutionStatus.RUNNING)
            throw new IOException("previous execution still owns the node");
        var now = Instant.now();
        var document = new NodeExecutionDocument(
                1,
                nextId("nxe"),
                agentTask == null ? "" : agentTask.agentTaskId(),
                workflowExecutionId,
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.handlerType(),
                NodeExecutionStatus.RUNNING,
                pid,
                "",
                null,
                List.of(),
                Map.of("claim", Map.of(
                        "executor_pid", pid,
                        "executor_started_at", ProcessHandle.of(pid).flatMap(p -> p.info().startInstant())
                                .orElseThrow(() -> new IOException("executor start identity unavailable")).toString(),
                        "input_identity", inputIdentity(node))),
                "",
                node.runRef(),
                "",
                "",
                "",
                null,
                now,
                null,
                null
        );
        jsonWriter.write(paths.nodeExecutionJson(document.nodeExecutionId()), document);
        return document;
    }

    NodeExecutionDocument finishNodeExecution(
            WorkstreamPaths paths,
            NodeExecutionDocument nodeExecution,
            NodeResult result
    ) throws IOException {
        nodeExecution = currentRunningExecution(paths, nodeExecution);
        return writeFinished(paths, nodeExecution, result);
    }

    NodeExecutionDocument adoptVerifiedResult(WorkstreamPaths paths, NodeExecutionDocument execution, NodeResult result)
            throws IOException {
        var actual = jsonWriter.read(paths.nodeExecutionJson(execution.nodeExecutionId()), NodeExecutionDocument.class);
        var node = jsonWriter.read(paths.nodeJson(actual.nodeInstanceId()), NodeInstanceDocument.class);
        var current = jsonWriter.read(paths.workflowCurrentJson(), WorkflowCurrentDocument.class);
        if (!actual.equals(execution) || actual.status() != NodeExecutionStatus.FAILED
                || !"UNKNOWN".equals(actual.result().get("external_effect"))
                || current.status() != WorkflowStatus.WAITING_FOR_RECOVERY
                || !current.activeNodeInstanceIds().equals(List.of(node.nodeInstanceId()))
                || node.status() != NodeStatus.FAILED || !node.latestExecutionId().equals(actual.nodeExecutionId())
                || !(actual.result().get("claim") instanceof Map<?, ?> claim)
                || !inputIdentity(node).equals(claim.get("input_identity")))
            throw new IOException("late completion is not for the current unknown execution");
        var facts = new LinkedHashMap<String, Object>(actual.result());
        facts.put("prior_unknown_observation", Map.of("outcome", actual.outcome(), "result", actual.result(),
                "finished_at", actual.finishedAt().toString()));
        for (var key : java.util.List.of("reason", "external_effect", "provider_invocation", "automatic_retry")) facts.remove(key);
        return writeFinished(paths, withFacts(actual, facts), result);
    }

    private NodeExecutionDocument writeFinished(WorkstreamPaths paths, NodeExecutionDocument nodeExecution, NodeResult result)
            throws IOException {
        var finishedAt = Instant.now();
        var resultMap = mergeOwnedFacts(nodeExecution, result == null ? Map.of() : result.result());
        var document = new NodeExecutionDocument(
                nodeExecution.schemaVersion(),
                nodeExecution.nodeExecutionId(),
                nodeExecution.agentTaskId(),
                nodeExecution.workflowExecutionId(),
                nodeExecution.nodeInstanceId(),
                nodeExecution.nodeDefinitionId(),
                nodeExecution.handlerType(),
                executionStatus(result == null ? null : result.status()),
                nodeExecution.pid(),
                result == null ? "" : result.outcome(),
                result == null ? null : result.status(),
                result == null ? List.of() : result.outputRefs(),
                resultMap,
                result == null ? "" : nullToEmpty(result.errorMessage()),
                text(resultMap.get("run_id")),
                text(resultMap.get("run_metadata")),
                text(resultMap.get("agent")),
                text(resultMap.get("session")),
                intValue(resultMap.get("exit_code")),
                nodeExecution.startedAt(),
                finishedAt,
                durationMs(nodeExecution.startedAt(), finishedAt)
        );
        jsonWriter.write(paths.nodeExecutionJson(document.nodeExecutionId()), document);
        return document;
    }

    NodeExecutionDocument failNodeExecution(
            WorkstreamPaths paths,
            NodeExecutionDocument nodeExecution,
            Exception failure
    ) throws IOException {
        nodeExecution = currentRunningExecution(paths, nodeExecution);
        var finishedAt = Instant.now();
        var details = new LinkedHashMap<String, Object>(nodeExecution.result());
        details.put("exception_type", failure == null ? "" : failure.getClass().getName());
        details.put("exception_message", failure == null ? "" : nullToEmpty(failure.getMessage()));
        var document = new NodeExecutionDocument(
                nodeExecution.schemaVersion(),
                nodeExecution.nodeExecutionId(),
                nodeExecution.agentTaskId(),
                nodeExecution.workflowExecutionId(),
                nodeExecution.nodeInstanceId(),
                nodeExecution.nodeDefinitionId(),
                nodeExecution.handlerType(),
                NodeExecutionStatus.FAILED,
                nodeExecution.pid(),
                "exception",
                NodeStatus.FAILED,
                List.of(),
                details,
                failure == null ? "" : nullToEmpty(failure.getMessage()),
                nodeExecution.runRef(),
                nodeExecution.agentRunRef(),
                nodeExecution.agent(),
                nodeExecution.session(),
                null,
                nodeExecution.startedAt(),
                finishedAt,
                durationMs(nodeExecution.startedAt(), finishedAt)
        );
        jsonWriter.write(paths.nodeExecutionJson(document.nodeExecutionId()), document);
        return document;
    }

    List<NodeExecutionDocument> readNodeExecutions(WorkstreamPaths paths) throws IOException {
        if (!jsonWriter.exists(paths.nodeExecutionsDir())) {
            return List.of();
        }
        var documents = new ArrayList<NodeExecutionDocument>();
        try (var stream = jsonWriter.list(paths.nodeExecutionsDir()).stream()) {
            var files = stream
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted()
                    .toList();
            for (var file : files) {
                documents.add(jsonWriter.read(file, NodeExecutionDocument.class));
            }
        }
        return documents;
    }

    Optional<NodeExecutionDocument> latestNodeExecution(WorkstreamPaths paths, NodeInstanceDocument node) throws IOException {
        if (node.latestExecutionId().isBlank()) {
            return Optional.empty();
        }
        var path = paths.nodeExecutionJson(node.latestExecutionId());
        if (!jsonWriter.exists(path)) {
            return Optional.empty();
        }
        return Optional.of(jsonWriter.read(path, NodeExecutionDocument.class));
    }

    NodeExecutionDocument markNodeExecutionStale(
            WorkstreamPaths paths,
            NodeExecutionDocument nodeExecution,
            String note
    ) throws IOException {
        var finishedAt = Instant.now();
        var staleResult = new LinkedHashMap<String, Object>();
        staleResult.putAll(nodeExecution.result());
        staleResult.put("reason", "STALE_RUNNING_PROCESS");
        staleResult.put("stale_running_pid", nodeExecution.pid() == null ? "" : nodeExecution.pid());
        staleResult.put("recovery_note", nullToEmpty(note));
        var document = new NodeExecutionDocument(
                nodeExecution.schemaVersion(),
                nodeExecution.nodeExecutionId(),
                nodeExecution.agentTaskId(),
                nodeExecution.workflowExecutionId(),
                nodeExecution.nodeInstanceId(),
                nodeExecution.nodeDefinitionId(),
                nodeExecution.handlerType(),
                NodeExecutionStatus.STALE,
                nodeExecution.pid(),
                "STALE_RUNNING_PROCESS",
                NodeStatus.FAILED,
                nodeExecution.outputRefs(),
                staleResult,
                "Running node had no live process.",
                nodeExecution.runRef(),
                nodeExecution.agentRunRef(),
                nodeExecution.agent(),
                nodeExecution.session(),
                nodeExecution.exitCode(),
                nodeExecution.startedAt(),
                finishedAt,
                durationMs(nodeExecution.startedAt(), finishedAt)
        );
        jsonWriter.write(paths.nodeExecutionJson(document.nodeExecutionId()), document);
        return document;
    }

    private static NodeExecutionStatus executionStatus(NodeStatus status) {
        if (status == null) {
            return NodeExecutionStatus.FAILED;
        }
        return switch (status) {
            case COMPLETED -> NodeExecutionStatus.SUCCEEDED;
            case FAILED, BLOCKED -> NodeExecutionStatus.FAILED;
            case RUNNING -> NodeExecutionStatus.RUNNING;
            case WAITING -> NodeExecutionStatus.WAITING;
            case READY -> NodeExecutionStatus.READY;
            case CREATED -> NodeExecutionStatus.CREATED;
            case SKIPPED -> NodeExecutionStatus.SKIPPED;
        };
    }

    private NodeExecutionDocument currentRunningExecution(WorkstreamPaths paths, NodeExecutionDocument expected)
            throws IOException {
        var actual = jsonWriter.read(paths.nodeExecutionJson(expected.nodeExecutionId()), NodeExecutionDocument.class);
        var node = jsonWriter.read(paths.nodeJson(expected.nodeInstanceId()), NodeInstanceDocument.class);
        var current = jsonWriter.read(paths.workflowCurrentJson(), WorkflowCurrentDocument.class);
        if (actual.status() != NodeExecutionStatus.RUNNING
                || !actual.agentTaskId().equals(expected.agentTaskId())
                || !actual.nodeInstanceId().equals(expected.nodeInstanceId())
                || !node.latestExecutionId().equals(actual.nodeExecutionId())
                || node.status() != NodeStatus.RUNNING || current.status().isTerminal()
                || !current.activeNodeInstanceIds().contains(node.nodeInstanceId())
                || !(actual.result().get("claim") instanceof Map<?, ?> claim)
                || !inputIdentity(node).equals(claim.get("input_identity"))
                || (actual.result().get("permission_reply") instanceof Map<?, ?> reply
                    && Boolean.TRUE.equals(reply.get("closed"))))
            throw new IOException("execution claim is no longer current");
        return actual;
    }

    NodeExecutionDocument verifyClaim(WorkstreamPaths paths, NodeExecutionDocument expected) throws IOException {
        return currentRunningExecution(paths, expected);
    }

    void bindPreparedRun(WorkstreamPaths paths, NodeExecutionDocument expected, Map<String, String> reference)
            throws IOException {
        var value = currentRunningExecution(paths, expected);
        if (!reference.keySet().equals(java.util.Set.of("ref", "sha256"))
                || reference.get("ref").isBlank() || !reference.get("sha256").matches("[a-f0-9]{64}"))
            throw new IOException("invalid prepared run reference");
        var prior = value.result().get("prepared_run");
        if (prior != null && !prior.equals(reference)) throw new IOException("claim already binds another preparation");
        var facts = new LinkedHashMap<String, Object>(value.result());
        facts.put("prepared_run", reference);
        jsonWriter.write(paths.nodeExecutionJson(value.nodeExecutionId()), withFacts(value, facts));
    }

    private String inputIdentity(NodeInstanceDocument node) throws IOException {
        try {
            var bytes = jsonWriter.objectMapper().writer().with(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS).writeValueAsBytes(Map.of(
                    "node", node.nodeInstanceId(), "iteration", node.iterationId(),
                    "input_refs", node.inputRefs(), "input_transition", node.inputTransition()));
            return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }

    private static NodeExecutionDocument withFacts(NodeExecutionDocument value, Map<String, Object> facts) {
        return new NodeExecutionDocument(value.schemaVersion(), value.nodeExecutionId(), value.agentTaskId(),
                value.workflowExecutionId(), value.nodeInstanceId(), value.nodeDefinitionId(), value.handlerType(),
                value.status(), value.pid(), value.outcome(), value.nodeStatus(), value.outputRefs(), facts,
                value.errorMessage(), value.runRef(), value.agentRunRef(), value.agent(), value.session(),
                value.exitCode(), value.startedAt(), value.finishedAt(), value.durationMs());
    }

    void closePermissionReply(WorkstreamPaths paths, String executionId) throws IOException {
        var value = jsonWriter.read(paths.nodeExecutionJson(executionId), NodeExecutionDocument.class);
        if (value.status() == NodeExecutionStatus.RUNNING || value.status() == NodeExecutionStatus.CREATED
                || value.status() == NodeExecutionStatus.READY)
            throw new IOException("in-flight execution must be resolved before replacing readiness");
        var result = new LinkedHashMap<String, Object>(value.result());
        var reply = new LinkedHashMap<String, Object>();
        if (result.get("permission_reply") instanceof Map<?, ?> prior)
            prior.forEach((key, item) -> reply.put(String.valueOf(key), item));
        reply.put("closed", true);
        result.put("permission_reply", reply);
        jsonWriter.write(paths.nodeExecutionJson(executionId), new NodeExecutionDocument(value.schemaVersion(),
                value.nodeExecutionId(), value.agentTaskId(), value.workflowExecutionId(), value.nodeInstanceId(),
                value.nodeDefinitionId(), value.handlerType(), value.status(), value.pid(), value.outcome(), value.nodeStatus(),
                value.outputRefs(), result, value.errorMessage(), value.runRef(), value.agentRunRef(), value.agent(),
                value.session(), value.exitCode(), value.startedAt(), value.finishedAt(), value.durationMs()));
    }

    private static Map<String, Object> mergeOwnedFacts(NodeExecutionDocument execution, Map<String, Object> result)
            throws IOException {
        var merged = new LinkedHashMap<String, Object>(execution.result());
        for (var entry : result.entrySet()) {
            if (java.util.Set.of("claim", "authorization", "permission_reply", "prepared_run")
                    .contains(entry.getKey()))
                throw new IOException("handler result cannot replace execution-owned fact: " + entry.getKey());
            merged.put(entry.getKey(), entry.getValue());
        }
        return merged;
    }

    private static Long durationMs(Instant startedAt, Instant finishedAt) {
        if (startedAt == null || finishedAt == null) {
            return null;
        }
        return Duration.between(startedAt, finishedAt).toMillis();
    }

    private static String nextId(String prefix) {
        return prefix + "-" + Instant.now().toEpochMilli() + "-" + UUID.randomUUID().toString().substring(0, 8);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private static String textOrDefault(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }

    private static String nullToEmpty(String value) {
        return value == null ? "" : value;
    }

    private static Integer intValue(Object value) {
        return value instanceof Number number ? number.intValue() : null;
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/** Operator authority for one execution; callers hold the workstream lock. */
public final class ExecutionNetworkGrantStore {
    public static final String REF_KEY = "execution_network_grant_ref";
    private static final String SHA_KEY = "execution_network_grant_sha256";
    private final AtomicJsonWriter writer;
    private final boolean scoped;
    private final WorkflowFileLedger ledger;

    public ExecutionNetworkGrantStore(WorkflowFileLedger ledger) {
        this.ledger = java.util.Objects.requireNonNull(ledger);
        this.scoped = ledger.hasSession();
        this.writer = scoped ? new AtomicJsonWriter(ledger.files()) : new AtomicJsonWriter();
    }

    public record Grant(int schemaVersion, String workstreamId, String sourceNodeInstanceId,
                        String targetNodeDefinitionId, String definitionSha256, List<String> domains,
                        String note, String approvedAt, String state, String claimedNodeInstanceId,
                        String claimedRunId) {
        public Grant {
            domains = List.copyOf(domains == null ? List.of() : domains);
        }
    }

    public record Claim(String ref, String sha256, List<String> domains) {
        public Claim { domains = List.copyOf(domains); }
        public Map<String, Object> metadata() {
            return Map.of("grantRef", ref, "grantSha256", sha256, "allowedDomains", domains);
        }
    }

    public String approve(WorkstreamPaths paths, String target, List<String> domains, String note) throws IOException {
        if (!scoped) {
            try (var write = ledger.writeSession(paths, "network grant approval", UUID.randomUUID().toString())) {
                var result = new ExecutionNetworkGrantStore(write.ledger()).approve(paths, target, domains, note);
                write.commit();
                return result;
            }
        }
        var source = waitingSource(paths);
        var definition = ledger.loadDefinition(paths);
        var canonical = canonicalDomains(domains);
        if (note == null || note.isBlank()) throw new IOException("network approval note is required");
        if (!eligible(definition.node(target))) throw new IOException("target must use Claude implement profile");
        if (source.kind() == NodeKind.GATE) {
            if (!targets(definition, source).contains(target)) throw new IOException("target is not reachable before another gate");
        } else if (!source.nodeDefinitionId().equals(target)) {
            throw new IOException("a failed execution can authorize only its own retry");
        }
        if (source.inputTransition().containsKey(REF_KEY)) {
            var previous = read(paths, source.inputTransition().get(REF_KEY).toString());
            if (previous.state().equals("PENDING")) throw new IOException("cancel the pending network grant before replacing it");
        }
        var path = directory(paths).resolve("grant-" + UUID.randomUUID() + ".json");
        var ref = paths.workspaceRoot().relativize(path).toString();
        var grant = new Grant(1, paths.workstreamId().value(), source.nodeInstanceId(), target,
                sha(writer.readBytes(paths.workflowDefinitionJson())), canonical, note.trim(),
                Instant.now().toString(), "PENDING", "", "");
        writer.write(path, grant);
        var transition = new LinkedHashMap<>(source.inputTransition());
        transition.put(REF_KEY, ref);
        transition.put(SHA_KEY, sha(writer.objectMapper().writeValueAsBytes(grant)));
        writer.write(paths.nodeJson(source.nodeInstanceId()), new NodeInstanceDocument(
                source.schemaVersion(), source.nodeInstanceId(), source.nodeDefinitionId(), source.kind(),
                source.handlerType(), source.status(), source.stageId(), source.iterationId(), source.inputRefs(),
                transition, source.outputRefs(), source.result(), source.runRef(), source.latestExecutionId(),
                source.startedAt(), source.finishedAt()));
        return ref;
    }

    public void cancel(WorkstreamPaths paths) throws IOException {
        if (!scoped) {
            try (var write = ledger.writeSession(paths, "network grant cancellation", UUID.randomUUID().toString())) {
                new ExecutionNetworkGrantStore(write.ledger()).cancel(paths);
                write.commit();
                return;
            }
        }
        var source = waitingSource(paths);
        var value = source.inputTransition().get(REF_KEY);
        if (!(value instanceof String ref)) throw new IOException("no network grant on the current waiting node");
        var grant = read(paths, ref);
        if (!grant.state().equals("PENDING")) throw new IOException("only an unclaimed network grant can be cancelled");
        writer.write(resolve(paths, ref), withState(grant, "CANCELLED", "", ""));
    }

    public Map<String, Object> view(WorkstreamPaths paths) throws IOException {
        try { return ledger.inspect(paths, (snapshot, files) -> new ExecutionNetworkGrantStore(snapshot).validView(paths)); }
        catch (IOException invalid) {
            return Map.of("canApprove", false, "canCancel", false, "status", "INVALID", "reason", invalid.getMessage());
        }
    }

    private Map<String, Object> validView(WorkstreamPaths paths) throws IOException {
        var current = ledger.loadCurrent(paths);
        if (current.activeNodeInstanceIds().size() != 1) return Map.of("canApprove", false, "canCancel", false);
        var node = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
        var result = new LinkedHashMap<String, Object>();
        var waiting = isWaiting(current, node);
        if (waiting) waitingSource(paths);
        var candidates = waiting ? targets(ledger.loadDefinition(paths), node) : List.<String>of();
        result.put("canApprove", !candidates.isEmpty());
        result.put("targets", candidates);
        result.put("canCancel", false);
        result.put("scope", "one_execution");
        var value = node.inputTransition().get(REF_KEY);
        if (value instanceof String ref) {
            var grant = read(paths, ref);
            result.put("grant", grant);
            result.put("grantRef", ref);
            var pending = grant.state().equals("PENDING");
            result.put("canApprove", !candidates.isEmpty() && !pending);
            result.put("canCancel", waiting && pending);
        }
        return Map.copyOf(result);
    }

    /** The atomic claim deliberately burns the grant even if subsequent startup fails. */
    public Claim claimIfPresent(WorkstreamPaths paths, String nodeId, String runId) throws IOException {
        if (!scoped) {
            try (var write = ledger.writeSession(paths, "network grant optional claim", UUID.randomUUID().toString())) {
                var result = new ExecutionNetworkGrantStore(write.ledger()).claimIfPresent(paths, nodeId, runId);
                write.commit();
                return result;
            }
        }
        if (!writer.exists(paths.nodeJson(nodeId))) return null;
        if (!ledger.loadNode(paths, nodeId).inputTransition().containsKey(REF_KEY)) return null;
        return claim(paths, nodeId, runId);
    }

    public Claim claim(WorkstreamPaths paths, String nodeId, String runId) throws IOException {
        if (!scoped) {
            try (var write = ledger.writeSession(paths, "network grant claim", UUID.randomUUID().toString())) {
                var result = new ExecutionNetworkGrantStore(write.ledger()).claim(paths, nodeId, runId);
                write.commit();
                return result;
            }
        }
        var current = ledger.loadCurrent(paths);
        if (current.status() != WorkflowStatus.RUNNING || !current.activeNodeInstanceIds().contains(nodeId)) {
            throw new IOException("network grant requires the current running execution");
        }
        var node = ledger.loadNode(paths, nodeId);
        var value = node.inputTransition().get(REF_KEY);
        if (value == null) return null;
        if (!(value instanceof String ref)) throw new IOException("invalid network grant reference");
        var grant = read(paths, ref);
        if (!grant.targetNodeDefinitionId().equals(node.nodeDefinitionId())) return null;
        if (!eligible(ledger.loadDefinition(paths).node(node.nodeDefinitionId()))) throw new IOException("network grant target capability mismatch");
        if (node.status() != NodeStatus.RUNNING) throw new IOException("network grant target is not running");
        if (!grant.state().equals("PENDING")) return null;
        if (runId == null || !runId.matches("[A-Za-z0-9._-]+")) throw new IOException("invalid network grant run id");
        var source = ledger.loadNode(paths, grant.sourceNodeInstanceId());
        if (!ref.equals(source.inputTransition().get(REF_KEY))) throw new IOException("network grant was superseded");
        if (source.kind() == NodeKind.GATE) {
            if (source.status() != NodeStatus.COMPLETED
                    || !List.of("approve", "approved", "revise").contains(source.result().get("human_action"))) {
                throw new IOException("network grant does not replace the business gate decision");
            }
        } else if (!source.nodeInstanceId().equals(nodeId)) {
            throw new IOException("network retry grant cannot cross node instances");
        }
        var path = resolve(paths, ref);
        writer.write(path, withState(grant, "CLAIMED", nodeId, runId));
        return new Claim(ref, sha(writer.readBytes(path)), grant.domains());
    }

    public static Map<String, Object> forward(AtomicJsonWriter reader, WorkstreamPaths paths, NodeInstanceDocument source,
                                               NodeDefinition next, Map<String, Object> attributes) throws IOException {
        var result = new LinkedHashMap<>(attributes);
        result.remove(REF_KEY);
        var value = source.inputTransition().get(REF_KEY);
        if (value instanceof String ref && next.kind() != NodeKind.GATE) {
            var grant = readDocument(reader, paths, ref);
            var origin = reader.read(paths.nodeJson(grant.sourceNodeInstanceId()), NodeInstanceDocument.class);
            var originalSha = sha(reader.objectMapper().writeValueAsBytes(withState(grant, "PENDING", "", "")));
            if (!ref.equals(origin.inputTransition().get(REF_KEY)) || !originalSha.equals(origin.inputTransition().get(SHA_KEY)))
                throw new IOException("network grant approval binding mismatch");
            if (grant.state().equals("PENDING") && !source.nodeDefinitionId().equals(grant.targetNodeDefinitionId())) {
                result.put(REF_KEY, ref);
            }
        }
        return Map.copyOf(result);
    }

    public static void verifyClaim(WorkstreamPaths paths, Claim claim, String nodeId, String runId) throws IOException {
        // Historical execution evidence is bound by its recorded SHA, not today's source pointer.
        var grant = readDocument(new AtomicJsonWriter(), paths, claim.ref());
        if (!grant.state().equals("CLAIMED") || !nodeId.equals(grant.claimedNodeInstanceId())
                || !runId.equals(grant.claimedRunId()) || !claim.domains().equals(grant.domains())
                || !claim.sha256().equals(sha(Files.readAllBytes(resolve(paths, claim.ref()))))) {
            throw new IOException("network grant claim mismatch");
        }
    }

    private NodeInstanceDocument waitingSource(WorkstreamPaths paths) throws IOException {
        var current = ledger.loadCurrent(paths);
        if (current.activeNodeInstanceIds().size() != 1) throw new IOException("network approval requires one active waiting node");
        var node = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
        if (!isWaiting(current, node)) throw new IOException("network approval requires a human gate or failed execution");
        if (node.kind() == NodeKind.GATE) {
            var open = false;
            for (var gateId : current.openGateIds()) {
                var gate = writer.read(paths.gateJson(gateId), GateDocument.class);
                open |= gate.nodeInstanceId().equals(node.nodeInstanceId()) && gate.status().equals("open");
            }
            if (!open) throw new IOException("network approval requires a matching open gate");
        }
        return node;
    }

    private static boolean isWaiting(WorkflowCurrentDocument current, NodeInstanceDocument node) {
        return current.status() == WorkflowStatus.WAITING_FOR_HUMAN && node.kind() == NodeKind.GATE && node.status() == NodeStatus.WAITING
                || current.status() == WorkflowStatus.WAITING_FOR_RECOVERY && node.kind() == NodeKind.TASK
                && (node.status() == NodeStatus.FAILED || node.status() == NodeStatus.BLOCKED);
    }

    private static boolean eligible(NodeDefinition node) {
        return node.handlerType().equals("acpx.agent_run") && "claude".equals(node.config().get("agent"))
                && "implement".equals(node.config().get("permission_profile"));
    }

    private static List<String> targets(WorkflowDefinition definition, NodeInstanceDocument source) {
        if (source.kind() != NodeKind.GATE) return eligible(definition.node(source.nodeDefinitionId())) ? List.of(source.nodeDefinitionId()) : List.of();
        var queue = new ArrayDeque<String>();
        definition.edgesFrom(source.nodeDefinitionId()).stream()
                .filter(e -> List.of("approve", "approved", "revise").contains(e.on())).forEach(e -> queue.add(e.to()));
        var seen = new HashSet<String>();
        var targets = new java.util.TreeSet<String>();
        while (!queue.isEmpty()) {
            var id = queue.removeFirst();
            if (!seen.add(id)) continue;
            var node = definition.node(id);
            if (node.kind() == NodeKind.GATE) continue;
            if (eligible(node)) targets.add(id);
            definition.edgesFrom(id).forEach(e -> queue.add(e.to()));
        }
        return List.copyOf(targets);
    }

    private Grant read(WorkstreamPaths paths, String ref) throws IOException {
        var grant = readDocument(writer, paths, ref);
        var source = ledger.loadNode(paths, grant.sourceNodeInstanceId());
        var originalSha = sha(writer.objectMapper().writeValueAsBytes(withState(grant, "PENDING", "", "")));
        if (!ref.equals(source.inputTransition().get(REF_KEY)) || !originalSha.equals(source.inputTransition().get(SHA_KEY))) {
            throw new IOException("network grant approval binding mismatch");
        }
        return grant;
    }

    private static Grant readDocument(AtomicJsonWriter writer, WorkstreamPaths paths, String ref) throws IOException {
        var grant = writer.read(resolve(paths, ref), Grant.class);
        if (grant == null || grant.schemaVersion() != 1 || !paths.workstreamId().value().equals(grant.workstreamId())
                || !sha(writer.readBytes(paths.workflowDefinitionJson())).equals(grant.definitionSha256())
                || grant.state() == null || !List.of("PENDING", "CLAIMED", "CANCELLED").contains(grant.state())
                || grant.targetNodeDefinitionId() == null || !grant.targetNodeDefinitionId().matches("[A-Za-z0-9._-]+")
                || grant.sourceNodeInstanceId() == null || !grant.sourceNodeInstanceId().matches("[A-Za-z0-9._-]+")
                || grant.note() == null || grant.note().isBlank() || grant.approvedAt() == null || grant.approvedAt().isBlank()
                || !canonicalDomains(grant.domains()).equals(grant.domains())) throw new IOException("invalid execution network grant");
        return grant;
    }

    public static List<String> canonicalDomains(List<String> domains) throws IOException {
        if (domains == null || domains.isEmpty() || domains.size() > 32) throw new IOException("provide 1-32 exact public DNS names");
        var result = new java.util.TreeSet<String>();
        for (var domain : domains) {
            if (domain == null || domain.length() > 253 || !domain.equals(domain.toLowerCase(java.util.Locale.ROOT))
                    || !domain.matches("[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+")
                    || domain.matches("[0-9.]+") || domain.endsWith(".localhost") || domain.endsWith(".local")
                    || java.util.Arrays.stream(domain.split("\\.")).anyMatch(label -> label.length() > 63)) {
                throw new IOException("network domain must be an exact canonical DNS name without URL, wildcard, IP or local suffix");
            }
            result.add(domain);
        }
        return List.copyOf(result);
    }

    private static Grant withState(Grant g, String state, String node, String run) {
        return new Grant(g.schemaVersion(), g.workstreamId(), g.sourceNodeInstanceId(), g.targetNodeDefinitionId(),
                g.definitionSha256(), g.domains(), g.note(), g.approvedAt(), state, node, run);
    }

    private static Path directory(WorkstreamPaths paths) { return paths.workstreamDir().resolve("execution-authority/network-grants"); }
    private static Path resolve(WorkstreamPaths paths, String ref) throws IOException {
        var path = paths.workspaceRoot().resolve(ref).normalize();
        if (!path.getParent().equals(directory(paths).normalize())
                || !path.getFileName().toString().matches("grant-[0-9a-f-]{36}\\.json")
                || !path.toRealPath().equals(path.toAbsolutePath())) throw new IOException("invalid network grant path");
        return path;
    }
    private static String sha(byte[] bytes) {
        try { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)); }
        catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
}

package dev.dual.ledger.file;

final class FailureReasonSemantics {
    private FailureReasonSemantics() {
    }

    static boolean isArtifactContractFailure(String failureReason) {
        if (failureReason == null || failureReason.isBlank()) {
            return false;
        }
        return failureReason.contains("DUAL_CONTROL")
                || failureReason.contains("CONTRACT")
                || "AGENT_OUTPUT_CONTRACT_VIOLATION".equals(failureReason);
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import java.util.Map;

final class FailureSummaryWriter {
    private final ObjectMapper objectMapper;

    FailureSummaryWriter(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    void write(WorkstreamPaths paths, String nodeInstanceId) throws IOException {
        var node = objectMapper.readValue(paths.nodeJson(nodeInstanceId).toFile(), NodeInstanceDocument.class);
        var current = objectMapper.readValue(paths.workflowCurrentJson().toFile(), WorkflowCurrentDocument.class);
        Files.createDirectories(paths.recoveryDir());
        Files.writeString(paths.currentFailureMarkdown(), render(paths, current, node), StandardCharsets.UTF_8);
    }

    String render(WorkstreamPaths paths, WorkflowCurrentDocument current, NodeInstanceDocument node) {
        var result = node.result() == null ? Map.<String, Object>of() : node.result();
        var outputRefs = node.outputRefs() == null ? List.<String>of() : node.outputRefs();
        var reason = text(firstNonBlank(
                result.get("acpx_failure.reason"),
                result.get("reason"),
                result.get("error"),
                result.get("message"),
                ""
        ));
        var recoverable = text(firstNonBlank(result.get("acpx_failure.recoverable"), result.get("recoverable"), ""));
        var exitCode = text(firstNonBlank(result.get("exit_code"), ""));
        var runId = text(firstNonBlank(result.get("run_id"), ""));
        var agent = text(firstNonBlank(result.get("agent"), ""));
        var session = text(firstNonBlank(result.get("session"), ""));
        var attention = WorkstreamAttentionEvaluator.evaluate(paths);

        var content = new StringBuilder();
        content.append("# Current Failure\n\n");
        content.append("## Summary\n\n");
        line(content, "Workflow Status", current.status().name());
        line(content, "Node", node.nodeDefinitionId());
        line(content, "Node Instance", node.nodeInstanceId());
        line(content, "Node Status", node.status().name());
        line(content, "Handler", node.handlerType());
        line(content, "Reason", reason);
        line(content, "Recoverable", recoverable);
        line(content, "Exit Code", exitCode);
        line(content, "Run ID", runId);
        line(content, "Agent", agent);
        line(content, "Session", session);
        line(content, "Attention Category", attention.category().name());
        line(content, "Retry Safe", String.valueOf(attention.retrySafe()));
        appendContractFailureDiagnostic(content, result);
        content.append("\n## Evidence\n\n");
        if (outputRefs.isEmpty()) {
            content.append("- Output refs: N/A\n");
        } else {
            for (var ref : outputRefs) {
                content.append("- ").append(ref).append('\n');
            }
        }
        content.append("\n## Suggested Action\n\n");
        content.append("- ").append(blankDefault(attention.detail(), "Inspect the evidence files listed above.")).append('\n');
        content.append("- ").append(blankDefault(attention.nextAction(), "Inspect the workstream ledger before choosing the next action.")).append('\n');
        if (!attention.command().isBlank()) {
            content.append("- Command: `").append(attention.command()).append("`.\n");
        }
        return content.toString();
    }

    @SuppressWarnings("unchecked")
    private static void appendContractFailureDiagnostic(StringBuilder content, Map<String, Object> result) {
        var diagnosticJson = text(result.get("contract_failure_diagnostic_ref"));
        var diagnosticMarkdown = text(result.get("contract_failure_diagnostic_markdown_ref"));
        if (diagnosticJson.isBlank() && diagnosticMarkdown.isBlank() && !result.containsKey("parse_error")) {
            return;
        }
        content.append("\n## Contract Failure Diagnostic\n\n");
        line(content, "Diagnostic JSON", diagnosticJson);
        line(content, "Diagnostic Markdown", diagnosticMarkdown);
        if (result.get("parse_error") instanceof Map<?, ?> parseError) {
            line(content, "Error Code", text(parseError.get("code")));
            line(content, "Error Message", text(parseError.get("message")));
            var details = parseError.get("details");
            if (details instanceof Map<?, ?> detailsMap && !detailsMap.isEmpty()) {
                content.append("- Details:\n");
                for (var entry : detailsMap.entrySet()) {
                    content.append("  - ").append(text(entry.getKey())).append(": ")
                            .append(text(entry.getValue())).append('\n');
                }
            }
        }
    }

    private static void line(StringBuilder content, String label, String value) {
        content.append("- ").append(label).append(": ");
        content.append(value == null || value.isBlank() ? "N/A" : value);
        content.append('\n');
    }

    private static Object firstNonBlank(Object... values) {
        for (var value : values) {
            if (value != null && !value.toString().isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static String text(Object value) {
        return value == null ? "" : value.toString();
    }

    private static String blankDefault(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }
}

