package dev.dual.ledger.file;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Builds a deterministic recovery read model for CLI and API callers.
 *
 * Runtime handlers write the raw node result and optional contract diagnostic.
 * This class does not decide workflow transitions; it only explains why the
 * current node stopped and what an operator should inspect next.
 *
 * <p>{@code retrySafe} is the authoritative operator recovery fact: whether the
 * operator may continue recovery by running {@code suggestedCommand}. It is
 * declared at construction for every recovery result; downstream renderers
 * (WorkstreamAttention, CLI, API, reports) must copy it and never re-derive it
 * from {@code classification} or {@code retryReadiness}.
 */
public record RecoveryAssessment(
        String classification,
        String retryReadiness,
        String reason,
        String suggestedCommand,
        String diagnosticJsonRef,
        String diagnosticMarkdownRef,
        Map<String, Object> contractDiagnostic,
        boolean retrySafe,
        Map<String, Object> permissionRequest,
        java.util.List<String> allowedActions
) {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    public RecoveryAssessment(
            String classification,
            String retryReadiness,
            String reason,
            String suggestedCommand,
            String diagnosticJsonRef,
            String diagnosticMarkdownRef,
            Map<String, Object> contractDiagnostic,
            boolean retrySafe
    ) {
        this(classification, retryReadiness, reason, suggestedCommand, diagnosticJsonRef,
                diagnosticMarkdownRef, contractDiagnostic, retrySafe, Map.of(), java.util.List.of());
    }

    public RecoveryAssessment {
        permissionRequest = permissionRequest == null ? Map.of() : Map.copyOf(permissionRequest);
        allowedActions = allowedActions == null ? java.util.List.of() : java.util.List.copyOf(allowedActions);
    }

    public static RecoveryAssessment from(
            NodeInstanceDocument node,
            Path workspaceRoot,
            String workstreamId
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var result = node.result() == null ? Map.<String, Object>of() : node.result();
        var retry = "dualctl retry --workdir " + root + " " + workstreamId;
        var abort = "dualctl recovery abort --workdir " + root + " " + workstreamId;
        if ("UNKNOWN".equals(result.get("external_effect"))) {
            return new RecoveryAssessment("external_result_unknown", "STOP_AND_ADJUDICATE",
                    "An external intent exists without a verified completion. Stopping does not prove the operation had no effect.",
                    "Inspect dualctl recovery show --workdir " + root + " " + workstreamId
                            + "; obtain a recorded native stop, then submit an explicit retry/abort --decision. Ordinary retry is refused.",
                    "", "", Map.of(), false, Map.of(), java.util.List.of("inspect", "stop_recorded_session", "adjudicate"));
        }
        var diagnosticJsonRef = text(result.get("contract_failure_diagnostic_ref"));
        var diagnosticMarkdownRef = text(result.get("contract_failure_diagnostic_markdown_ref"));
        var diagnostic = readDiagnostic(root, diagnosticJsonRef);
        var agent = blankDefault(text(result.get("agent")), "claude");
        var session = blankDefault(text(result.get("session")), agent + "-main");
        if (node.status() == dev.dual.core.workflow.NodeStatus.FAILED
                && ("VERIFICATION_READINESS_REQUIRED".equals(result.get("readiness_reason"))
                || result.get("input_preparation_failure") instanceof Map<?, ?> preparation
                && "VERIFICATION_READINESS_REQUIRED".equals(preparation.get("code"))
                && Boolean.FALSE.equals(preparation.get("providerInvoked")))) {
            return new RecoveryAssessment("verification_readiness_required", "RECORD_READINESS_BEFORE_MANUAL_RETRY",
                    "Verification prerequisites are missing or no longer applicable; this does not report a model output failure.",
                    "Use dualctl review record-readiness --workdir " + root + " --subject " + node.nodeInstanceId()
                            + " --request-id <new-id> --file <declaration.json> " + workstreamId
                            + ". Recording does not approve or execute anything. Retry only with the same reviewed inputs; "
                            + "to revise use dualctl review revise --workdir " + root + " --subject " + node.nodeInstanceId()
                            + " --note <repair-requirement> " + workstreamId + "; the author and independent reviewer must run again.",
                    "", "", Map.of(), false);
        }
        if (result.get("input_preparation_failure") instanceof Map<?, ?> failure
                && node.status() == dev.dual.core.workflow.NodeStatus.FAILED
                && Boolean.FALSE.equals(failure.get("providerInvoked"))) {
            return new RecoveryAssessment("input_preparation_failure", "FIX_INPUTS_BEFORE_MANUAL_RETRY",
                    "Input preparation rejected before provider dispatch: " + text(failure.get("reason"))
                            + " / " + text(failure.get("code")) + ": " + text(failure.get("details")),
                    "Inspect the current input identity and approval evidence before `" + retry
                            + "`; or stop with `" + abort + "`.",
                    "", "", Map.of(), false);
        }
        var outcomeAssessment = fromAgentExecutionOutcome(
                result.get("agent_execution_outcome"),
                retry,
                agent,
                session,
                diagnosticJsonRef,
                diagnosticMarkdownRef,
                diagnostic
        );
        if (outcomeAssessment != null) {
            var permissionRequest = readPermissionEscalation(root, workstreamId, result);
            if ("agent_permission_blocked".equals(outcomeAssessment.classification())
                    && !permissionRequest.isEmpty()) {
                return new RecoveryAssessment(
                        "agent_permission_approval_required",
                        "HUMAN_APPROVE_PUBLIC_WEBSEARCH_OR_ABORT",
                        "The agent requested exact WebSearch for a public fact. The current turn was denied; a human may approve WebSearch for one retry only after confirming this repository is public.",
                        "dualctl recovery approve-websearch --public-repository --note \"<reason>\" --workdir "
                                + root + " " + workstreamId,
                        diagnosticJsonRef,
                        diagnosticMarkdownRef,
                        diagnostic,
                        false,
                        permissionRequest,
                        java.util.List.of("approve_public_websearch", "abort")
                );
            }
            return outcomeAssessment;
        }
        var diagnosticCategory = text(diagnostic.get("category"));
        var diagnosticHint = text(diagnostic.get("recovery_hint"));
        var failureReason = text(firstNonBlank(
                result.get("acpx_failure.reason"),
                result.get("reason"),
                result.get("error"),
                result.get("message")
        ));
        var recoverable = Boolean.TRUE.equals(result.get("acpx_failure.recoverable"))
                || Boolean.TRUE.equals(result.get("recoverable"));

        if ("revision_limit_reached".equals(failureReason) || "BLOCKED".equals(node.status().name())) {
            return new RecoveryAssessment(
                    "semantic_revision_limit",
                    "NEEDS_HUMAN_DECISION",
                    "The workflow exhausted its revision budget. Blind retry will likely repeat the same loop.",
                    "Inspect evidence, adjust the task/contract, then run `" + retry + "`; or stop with `" + abort + "`.",
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if (!diagnosticCategory.isBlank() || FailureReasonSemantics.isArtifactContractFailure(failureReason)) {
            return new RecoveryAssessment(
                    "artifact_contract_failure",
                    "RETRY_AFTER_OUTPUT_CONTRACT_FIX",
                    diagnosticHint.isBlank()
                            ? "The agent output contract was invalid or missing. Inspect the diagnostic before retrying."
                            : diagnosticHint,
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("RECOVERABLE_AGENT_MODEL_MISMATCH".equals(failureReason)) {
            return new RecoveryAssessment(
                    "agent_model_mismatch",
                    "REBUILD_ACPX_SESSION_THEN_RETRY",
                    "The acpx session model state is stale or incompatible with the current Claude Code/provider configuration. Rebuild the acpx session before retrying.",
                    "acpx " + agent + " sessions close " + session
                            + " && acpx " + agent + " sessions new --name " + session
                            + " && " + retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    true
            );
        }
        if ("RECOVERABLE_AGENT_AUTH_FAILED".equals(failureReason)) {
            return new RecoveryAssessment(
                    "agent_auth_failed",
                    "FIX_AGENT_AUTH_THEN_RETRY",
                    "The agent adapter failed authentication. Fix the underlying Claude/Codex runtime credentials or adapter configuration, then retry the same active node.",
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("RECOVERABLE_PROVIDER_CONNECTION_FAILED".equals(failureReason)) {
            return new RecoveryAssessment(
                    "provider_connection_failed",
                    "WAIT_OR_FIX_PROVIDER_CONNECTION_THEN_RETRY",
                    "The agent provider connection failed before a trustworthy agent output boundary. Verify provider/network/socket availability, then retry the same active node.",
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("RECOVERABLE_AGENT_RECONNECT".equals(failureReason)
                || "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED".equals(failureReason)
                || "RECOVERABLE_AGENT_PERMISSION_BLOCKED".equals(failureReason)
                || "RECOVERABLE_SESSION_MISSING".equals(failureReason)
                || "RECOVERABLE_CONTEXT_WINDOW".equals(failureReason)) {
            var classification = "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED".equals(failureReason)
                    ? "agent_output_interrupted"
                    : "RECOVERABLE_AGENT_PERMISSION_BLOCKED".equals(failureReason)
                    ? "agent_permission_blocked"
                    : "agent_session_recovery";
            // A blocked permission is not safe to retry blindly; session/output
            // recovery rebuilds the session first, so the suggested command is safe.
            var branchRetrySafe = !"agent_permission_blocked".equals(classification);
            return new RecoveryAssessment(
                    classification,
                    "REBUILD_ACPX_SESSION_THEN_RETRY",
                    sessionRecoveryReason(failureReason),
                    "acpx " + agent + " sessions close " + session
                            + " && acpx " + agent + " sessions new --name " + session
                            + " && " + retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    branchRetrySafe
            );
        }
        if ("RECOVERABLE_RATE_LIMIT".equals(failureReason)
                || "RECOVERABLE_AGENT_OVERLOADED".equals(failureReason)) {
            return new RecoveryAssessment(
                    "agent_capacity_recovery",
                    "WAIT_THEN_RETRY",
                    capacityRecoveryReason(failureReason),
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    true
            );
        }
        if (recoverable) {
            return new RecoveryAssessment(
                    "recoverable_agent_runtime",
                    "RETRY_AFTER_EXTERNAL_FIX",
                    "The failed node is marked recoverable, but its typed reason is not mapped to a specific operator action yet. Inspect adapter evidence before retrying.",
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    true
            );
        }
        if (FailureReasonSemantics.isArtifactContractFailure(failureReason)) {
            return new RecoveryAssessment(
                    "artifact_contract_failure",
                    "RETRY_AFTER_OUTPUT_CONTRACT_FIX",
                    "The agent output contract was invalid or missing. Inspect the output before retrying.",
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        return new RecoveryAssessment(
                "manual_recovery_required",
                "INSPECT_BEFORE_RETRY",
                "The failure is not marked recoverable. Read the evidence before deciding whether retry is safe.",
                retry + "  # only after fixing the cause",
                diagnosticJsonRef,
                diagnosticMarkdownRef,
                diagnostic,
                false
        );
    }

    private static RecoveryAssessment fromAgentExecutionOutcome(
            Object value,
            String retry,
            String agent,
            String session,
            String diagnosticJsonRef,
            String diagnosticMarkdownRef,
            Map<String, Object> diagnostic
    ) {
        if (!(value instanceof Map<?, ?> raw)) {
            return null;
        }
        var outcome = asStringMap(raw);
        var recoveryCategory = text(outcome.get("recoveryCategory"));
        var primaryReason = text(outcome.get("primaryReason"));
        var operatorMessage = text(outcome.get("operatorMessage"));
        if ("ARTIFACT_CONTRACT_FAILURE".equals(recoveryCategory)) {
            var diagnosticHint = text(diagnostic.get("recovery_hint"));
            return new RecoveryAssessment(
                    "artifact_contract_failure",
                    "RETRY_AFTER_OUTPUT_CONTRACT_FIX",
                    diagnosticHint.isBlank()
                            ? blankDefault(operatorMessage, "The agent output contract was invalid or missing. Inspect the diagnostic before retrying.")
                            : diagnosticHint,
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("OUTPUT_INCOMPLETE".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    "agent_output_incomplete",
                    "process_output_incomplete".equals(primaryReason)
                            ? "RETRY_AFTER_EXTERNAL_FIX" : "RETRY_AFTER_OUTPUT_CONTRACT_FIX",
                    blankDefault(operatorMessage, "The agent output stopped before a valid terminal control and artifact boundary."),
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("TIMEOUT_OR_STALLED".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    "agent_timeout_or_stalled",
                    "RETRY_AFTER_EXTERNAL_FIX",
                    blankDefault(operatorMessage, "The agent process timed out or stalled before completing the execution boundary."),
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("INTERRUPTED".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    "agent_interrupted",
                    "INSPECT_BEFORE_RETRY",
                    blankDefault(operatorMessage, "The agent execution was interrupted before completion."),
                    retry + "  # only after confirming the interruption cause",
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("RECOVERABLE_ADAPTER_FAILURE".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    adapterClassification(primaryReason),
                    adapterRetryReadiness(primaryReason),
                    blankDefault(operatorMessage, "The adapter reported a recoverable execution failure."),
                    adapterSuggestedCommand(primaryReason, agent, session, retry),
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    adapterRetrySafe(primaryReason)
            );
        }
        if ("NON_RECOVERABLE_ADAPTER_FAILURE".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    "non_recoverable_adapter_failure",
                    "NEEDS_HUMAN_DECISION",
                    blankDefault(operatorMessage, "The adapter reported a non-recoverable execution failure."),
                    retry + "  # only after changing adapter configuration or task boundary",
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        return null;
    }

    private static Map<String, Object> asStringMap(Map<?, ?> raw) {
        var map = new LinkedHashMap<String, Object>();
        for (var entry : raw.entrySet()) {
            if (entry.getKey() != null) {
                map.put(entry.getKey().toString(), entry.getValue());
            }
        }
        return map;
    }

    private static String adapterClassification(String primaryReason) {
        return switch (primaryReason) {
            case "adapter_incompatible" -> "agent_interface_incompatible";
            case "auth_failed" -> "agent_auth_failed";
            case "permission_blocked" -> "agent_permission_blocked";
            case "provider_connection_failed" -> "provider_connection_failed";
            case "context_window_exceeded" -> "agent_context_window";
            case "rate_limited" -> "agent_capacity_recovery";
            case "agent_reconnect_required", "session_bootstrap_failed" -> "agent_session_recovery";
            default -> "manual_recovery_required";
        };
    }

    private static String adapterRetryReadiness(String primaryReason) {
        return switch (primaryReason) {
            case "adapter_incompatible" -> "FIX_AGENT_INTERFACE_THEN_RETRY";
            case "auth_failed" -> "FIX_AGENT_AUTH_THEN_RETRY";
            case "rate_limited" -> "WAIT_THEN_RETRY";
            case "provider_connection_failed" -> "WAIT_OR_FIX_PROVIDER_CONNECTION_THEN_RETRY";
            case "agent_reconnect_required" -> "REBUILD_ACPX_SESSION_THEN_RETRY";
            // session_bootstrap_failed is generic: it may be a command timeout, spawn
            // failure, config error or any non-zero exit, not necessarily a missing
            // session. Do not assume `sessions new` recovers it; inspect before retry.
            case "session_bootstrap_failed" -> "INSPECT_BEFORE_RETRY";
            case "permission_blocked",
                 "context_window_exceeded" -> "RETRY_AFTER_EXTERNAL_FIX";
            default -> "INSPECT_BEFORE_RETRY";
        };
    }

    private static boolean adapterRetrySafe(String primaryReason) {
        // Only adapter failures whose suggested action rebuilds the session or
        // waits for capacity are safe to continue without a human decision.
        return switch (primaryReason) {
            case "rate_limited", "agent_reconnect_required" -> true;
            // A generic bootstrap failure is not blindly retry-safe: its cause is
            // unknown, so retrySafe must match the inspect-then-retry command.
            case "session_bootstrap_failed" -> false;
            default -> false;
        };
    }

    private static String adapterSuggestedCommand(
            String primaryReason,
            String agent,
            String session,
            String retry
    ) {
        return switch (primaryReason) {
            case "adapter_incompatible" -> retry + "  # only after fixing the recorded protocol/session mismatch; never resend an unknown call";
            case "agent_reconnect_required" ->
                    "acpx " + agent + " sessions close " + session
                            + " && acpx " + agent + " sessions new --name " + session
                            + " && " + retry;
            // Bootstrap failure is generic (timeout/spawn/config/nonzero); do not assume
            // `sessions new` recovers it. retrySafe is false and the command asks for
            // inspection before a manual retry.
            case "session_bootstrap_failed" ->
                    retry + "  # only after inspecting the session bootstrap failure";
            case "permission_blocked" ->
                    retry + "  # only after changing the permission policy and rebuilding the acpx session";
            case "auth_failed",
                 "provider_connection_failed",
                 "context_window_exceeded",
                 "rate_limited" -> retry;
            default -> retry + "  # only after inspecting the typed adapter failure";
        };
    }

    public Map<String, Object> toMap() {
        var map = new LinkedHashMap<String, Object>();
        map.put("classification", classification);
        map.put("retryReadiness", retryReadiness);
        map.put("retrySafe", retrySafe);
        map.put("reason", reason);
        map.put("suggestedCommand", suggestedCommand);
        map.put("diagnosticJsonRef", diagnosticJsonRef);
        map.put("diagnosticMarkdownRef", diagnosticMarkdownRef);
        map.put("contractDiagnostic", contractDiagnostic);
        map.put("permissionRequest", permissionRequest);
        map.put("allowedActions", allowedActions);
        return map;
    }

    private static Map<String, Object> readPermissionEscalation(
            Path root,
            String workstreamId,
            Map<String, Object> result
    ) {
        var runRef = text(result.get("run_metadata"));
        if (runRef.isBlank()) {
            return Map.of();
        }
        try {
            var path = root.resolve(runRef).normalize();
            var workstreamRoot = root.resolve(".agent/workstreams").resolve(workstreamId).normalize();
            if (!path.startsWith(workstreamRoot) || !Files.isRegularFile(path)) {
                return Map.of();
            }
            var run = OBJECT_MAPPER.readTree(path.toFile());
            var timeline = run.path("executionTimeline");
            if (!timeline.isArray()) {
                return Map.of();
            }
            for (var index = timeline.size() - 1; index >= 0; index--) {
                var event = timeline.get(index);
                var details = event.path("details");
                if ("permission_decision".equals(event.path("kind").asText())
                        && "ESCALATION_REQUIRED".equals(details.path("authorityDisposition").asText())
                        && "fetch".equals(details.path("toolKind").asText())
                        && "WebSearch".equals(details.path("toolName").asText())) {
                    var request = new LinkedHashMap<String, Object>();
                    request.put("toolName", "WebSearch");
                    request.put("toolKind", "fetch");
                    request.put("toolCallId", details.path("toolCallId").asText());
                    request.put("query", details.path("resource").asText());
                    request.put("runRef", runRef);
                    request.put("disposition", details.path("disposition").asText());
                    return Map.copyOf(request);
                }
            }
        } catch (Exception ignored) {
            return Map.of();
        }
        return Map.of();
    }

    private static Map<String, Object> readDiagnostic(Path root, String ref) {
        if (ref.isBlank()) {
            return Map.of();
        }
        try {
            var path = root.resolve(ref).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path)) {
                return Map.of();
            }
            return OBJECT_MAPPER.readValue(path.toFile(), MAP_TYPE);
        } catch (Exception ignored) {
            return Map.of();
        }
    }

    private static Object firstNonBlank(Object... values) {
        for (var value : values) {
            if (value != null && !value.toString().isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static String text(Object value) {
        return value == null ? "" : value.toString().trim();
    }

    private static String blankDefault(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }

    private static String sessionRecoveryReason(String failureReason) {
        return switch (failureReason) {
            case "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED" ->
                    "The agent output stopped before the terminal contract after the acpx timeout. Rebuild the acpx session to avoid continuing a partial context, then retry the same active node.";
            case "RECOVERABLE_AGENT_PERMISSION_BLOCKED" ->
                    "The agent attempted a tool action that was blocked by non-interactive permissions. Inspect the agent output and either adjust the task/session permission policy or retry after confirming the node is allowed to use those tools.";
            case "RECOVERABLE_SESSION_MISSING" ->
                    "The acpx session is missing. Create the session again, then retry the same active node.";
            case "RECOVERABLE_CONTEXT_WINDOW" ->
                    "The agent context window appears exhausted. Rebuild the acpx session to get a fresh context, then retry the same active node.";
            default ->
                    "The acpx agent session needs reconnect. Rebuild the acpx session, then retry the same active node.";
        };
    }

    private static String capacityRecoveryReason(String failureReason) {
        if ("RECOVERABLE_AGENT_OVERLOADED".equals(failureReason)) {
            return "The agent provider is overloaded. Wait for provider capacity to recover, then retry the same active node.";
        }
        return "The agent quota or rate limit was hit. Wait for quota recovery, then retry the same active node.";
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowStatus;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class RevisionTracker {
    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper objectMapper;
    private final LedgerEventLog eventLog;

    RevisionTracker(AtomicJsonWriter jsonWriter, ObjectMapper objectMapper, LedgerEventLog eventLog) {
        this.jsonWriter = jsonWriter;
        this.objectMapper = objectMapper;
        this.eventLog = eventLog;
    }

    WorkflowIterationDocument nextRevisionIteration(
            WorkstreamPaths paths,
            NodeInstanceDocument triggerNode,
            String triggerAction,
            String targetNodeDefinitionId,
            Map<String, Object> result
    ) throws IOException {
        var nextNumber = maxIterationNumber(paths) + 1;
        var iterationId = "iter-" + String.format("%03d", nextNumber);
        return WorkflowIterationDocument.revision(
                iterationId,
                nextNumber,
                triggerNode.iterationId(),
                triggerNode.nodeInstanceId(),
                triggerAction,
                targetNodeDefinitionId,
                LedgerUtils.revisionReason(result),
                Instant.now()
        );
    }

    void blockOnRevisionLimit(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node,
            List<String> outputRefs,
            Map<String, Object> result,
            String outcome,
            int maxRevisions,
            int currentRevisionCount
    ) throws IOException {
        var blockedResult = new LinkedHashMap<String, Object>();
        if (result != null) {
            blockedResult.putAll(result);
        }
        blockedResult.put("reason", "revision_limit_reached");
        blockedResult.put("outcome", outcome);
        blockedResult.put("max_revisions", maxRevisions);
        blockedResult.put("current_revision_count", currentRevisionCount);
        var now = Instant.now();
        jsonWriter.write(paths.nodeJson(node.nodeInstanceId()), new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                NodeStatus.BLOCKED,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                outputRefs,
                blockedResult,
                node.runRef(),
                node.latestExecutionId(),
                node.startedAt(),
                now
        ));

        var recoveryGateId = "recovery-" + node.nodeInstanceId();
        jsonWriter.write(paths.gateJson(recoveryGateId), new GateDocument(
                1,
                recoveryGateId,
                node.nodeInstanceId(),
                "recovery.review",
                "open",
                List.of("retry", "abort"),
                now,
                null,
                Map.of(
                        "node", node.nodeDefinitionId(),
                        "node_status", NodeStatus.BLOCKED.name(),
                        "outcome", outcome,
                        "reason", "revision_limit_reached",
                        "max_revisions", maxRevisions,
                        "current_revision_count", currentRevisionCount
                )
        ));
        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        eventLog.appendEvent(paths, eventId, "revision_limit_reached", Map.of(
                "node", node.nodeDefinitionId(),
                "node_instance_id", node.nodeInstanceId(),
                "outcome", outcome,
                "max_revisions", maxRevisions,
                "current_revision_count", currentRevisionCount,
                "recovery_gate_id", recoveryGateId
        ));
        var stopped = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.WAITING_FOR_RECOVERY,
                List.of(node.nodeInstanceId()),
                List.of(recoveryGateId),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), stopped);
        eventLog.writeInstanceFromCurrent(paths, stopped, now);
    }

    int maxIterationNumber(WorkstreamPaths paths) throws IOException {
        if (!jsonWriter.exists(paths.iterationsDir())) {
            return 1;
        }
        try (var stream = jsonWriter.list(paths.iterationsDir()).stream()) {
            return stream
                    .filter(Files::isRegularFile)
                    .map(path -> path.getFileName().toString())
                    .filter(name -> name.matches("iter-\\d{3}\\.json"))
                    .mapToInt(name -> Integer.parseInt(name.substring("iter-".length(), "iter-000".length())))
                    .max()
                    .orElse(1);
        }
    }

    int revisionCount(
            WorkstreamPaths paths,
            String triggerNodeDefinitionId,
            String targetNodeDefinitionId
    ) throws IOException {
        if (!jsonWriter.exists(paths.iterationsDir())) {
            return 0;
        }
        int count = 0;
        for (var path : jsonWriter.list(paths.iterationsDir())) {
            if (!Files.isRegularFile(path) || !path.getFileName().toString().matches("iter-\\d{3,}\\.json")) continue;
            // An unreadable revision cannot be silently removed from the stage budget.
            var iteration = jsonWriter.read(path, WorkflowIterationDocument.class);
            if ("workflow_started".equals(iteration.triggerAction())) continue;
            var trigger = jsonWriter.read(paths.nodeJson(iteration.triggerNodeInstanceId()), NodeInstanceDocument.class);
            // Readiness repair is another entrance to the existing plan budget, not a fresh allowance.
            boolean planRepair = planTarget(targetNodeDefinitionId) && planTarget(iteration.targetNodeDefinitionId());
            if (planRepair && ("plan.decision".equals(triggerNodeDefinitionId)
                    || "gate.human_plan_approval".equals(triggerNodeDefinitionId))) {
                if ("revise_readiness".equals(iteration.triggerAction()) || "plan.decision".equals(trigger.nodeDefinitionId())
                        || "gate.human_plan_approval".equals(trigger.nodeDefinitionId())) count++;
            } else if (targetNodeDefinitionId.equals(iteration.targetNodeDefinitionId())
                    && triggerNodeDefinitionId.equals(trigger.nodeDefinitionId())) count++;
        }
        return count;
    }

    private static boolean planTarget(String id) {
        return "plan.claude_plan".equals(id) || "context.plan_claude".equals(id);
    }

    static boolean startsNewIteration(String nodeDefinitionId, String outcome, String targetNodeDefinitionId) {
        return IterationSemantics.startsNewIteration(outcome, targetNodeDefinitionId);
    }

    static boolean isRevisionAction(String outcome) {
        return IterationSemantics.isRevisionTrigger(outcome);
    }

    static int maxRevisions(NodeDefinition definition) {
        var configured = definition.config().get("max_revisions");
        if (configured instanceof Number number) {
            return number.intValue();
        }
        if (configured instanceof String text && !text.isBlank()) {
            try {
                return Integer.parseInt(text);
            } catch (NumberFormatException ignored) {
                return -1;
            }
        }
        return -1;
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.flow.FlowExecutionSnapshot;
import dev.dual.core.flow.FlowOrchestrationKernel;
import dev.dual.core.flow.FlowSignal;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.HumanGateActionSemantics;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;

import java.io.IOException;
import java.nio.file.Files;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class RoutingEngine {
    private static final String FINAL_NEXT_STAGE_GATE = "gate.human_next_stage_approval";

    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper objectMapper;
    private final LedgerEventLog eventLog;
    private final RevisionTracker revisionTracker;
    private final FlowOrchestrationKernel flowKernel;
    private final GoalSatisfactionWriter goalSatisfactionWriter;
    private final CompletionAuditWriter completionAuditWriter;

    RoutingEngine(
            AtomicJsonWriter jsonWriter,
            ObjectMapper objectMapper,
            LedgerEventLog eventLog,
            RevisionTracker revisionTracker,
            FlowOrchestrationKernel flowKernel
    ) {
        this.jsonWriter = jsonWriter;
        this.objectMapper = objectMapper;
        this.eventLog = eventLog;
        this.revisionTracker = revisionTracker;
        this.flowKernel = flowKernel;
        this.goalSatisfactionWriter = new GoalSatisfactionWriter(jsonWriter);
        this.completionAuditWriter = new CompletionAuditWriter(jsonWriter);
    }

    WorkflowCurrentDocument loadCurrent(WorkstreamPaths paths) throws IOException {
        return jsonWriter.read(paths.workflowCurrentJson(), WorkflowCurrentDocument.class);
    }

    NodeInstanceDocument loadNode(WorkstreamPaths paths, String nodeInstanceId) throws IOException {
        return jsonWriter.read(paths.nodeJson(nodeInstanceId), NodeInstanceDocument.class);
    }

    void completeAndRoute(
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            String nodeInstanceId,
            NodeStatus completedStatus,
            String outcome,
            List<String> outputRefs,
            Map<String, Object> result
    ) throws IOException {
        completeAndRoute(paths, definition, nodeInstanceId, completedStatus, outcome, outputRefs, result, false);
    }

    private void completeAndRoute(
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            String nodeInstanceId,
            NodeStatus completedStatus,
            String outcome,
            List<String> outputRefs,
            Map<String, Object> result,
            boolean humanAuthorizedRevision
    ) throws IOException {
        var current = loadCurrent(paths);
        if (!current.activeNodeInstanceIds().contains(nodeInstanceId)) {
            throw new IOException("node is not active: " + nodeInstanceId);
        }

        var node = loadNode(paths, nodeInstanceId);
        if (completedStatus == NodeStatus.COMPLETED) {
            dev.dual.core.workflow.SelfTestContinuationSemantics.validateResult(node.nodeDefinitionId(), outcome, result);
        }
        var finishedAt = Instant.now();
        var finished = new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                completedStatus,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                outputRefs,
                result,
                node.runRef(),
                node.latestExecutionId(),
                node.startedAt(),
                finishedAt
        );
        jsonWriter.write(paths.nodeJson(nodeInstanceId), finished);
        goalSatisfactionWriter.evaluateAndWrite(paths, current, finished, completedStatus, outcome, outputRefs, result);

        if (completedStatus != NodeStatus.COMPLETED) {
            stopOnNonCompletedNode(paths, current, node, completedStatus, outcome, result);
            return;
        }

        // Build routing context for conditional edge evaluation
        var routingContext = new LinkedHashMap<String, Object>();
        routingContext.put("outcome", outcome);
        if (result != null) routingContext.putAll(result);

        var routeResult = flowKernel.advance(
                definition,
                new FlowExecutionSnapshot(current.workflowInstanceId(), activeNodeDefinitionIds(paths, current.activeNodeInstanceIds())),
                FlowSignal.completed(node.nodeDefinitionId(), outcome, routingContext)
        );
        var matchingTransitions = routeResult.transitions();

        var effectiveOutcome = outcome;
        var effectiveResult = result;
        Map<String, Object> gateSourceResult = Map.of();
        var lastEventId = current.lastEventId();
        for (var transition : matchingTransitions) {
            var nextDefinition = definition.node(transition.toNodeDefinitionId());
            var transitionAttributes = ExecutionNetworkGrantStore.forward(jsonWriter, paths, node, nextDefinition,
                    collectionTransition(paths, finished, nextDefinition, effectiveTransitionAttributes(node, transition.attributes())));
            if (nextDefinition.kind() == NodeKind.GATE
                    || !startsNewIteration(transitionAttributes, node.nodeDefinitionId(), outcome, nextDefinition.id())) {
                continue;
            }
            var maxRevisions = RevisionTracker.maxRevisions(definition.node(node.nodeDefinitionId()));
            var currentRevisionCount = revisionTracker.revisionCount(
                    paths,
                    node.nodeDefinitionId(),
                    nextDefinition.id()
            );
            if (maxRevisions < 0 || currentRevisionCount < maxRevisions) {
                continue;
            }
            if (humanAuthorizedRevision) {
                continue;
            }

            var blockedResult = new LinkedHashMap<String, Object>();
            if (result != null) {
                blockedResult.putAll(result);
            }
            blockedResult.put("reason", "revision_limit_reached");
            blockedResult.put("revision_limit_original_outcome", outcome);
            blockedResult.put("max_revisions", maxRevisions);
            blockedResult.put("current_revision_count", currentRevisionCount);
            var blockedRoutingContext = new LinkedHashMap<String, Object>(blockedResult);
            blockedRoutingContext.put("outcome", "BLOCKED");
            var blockedRoute = flowKernel.advance(
                    definition,
                    new FlowExecutionSnapshot(current.workflowInstanceId(),
                            activeNodeDefinitionIds(paths, current.activeNodeInstanceIds())),
                    FlowSignal.completed(node.nodeDefinitionId(), "BLOCKED", blockedRoutingContext)
            ).transitions();
            if (blockedRoute.isEmpty()) {
                revisionTracker.blockOnRevisionLimit(paths, current, node, outputRefs, result, outcome,
                        maxRevisions, currentRevisionCount);
                return;
            }
            if (blockedRoute.size() != 1
                    || definition.node(blockedRoute.getFirst().toNodeDefinitionId()).kind() != NodeKind.GATE) {
                throw new IOException("revision limit BLOCKED route must resolve to exactly one human gate: "
                        + node.nodeDefinitionId());
            }
            var blockedTransition = blockedRoute.getFirst();
            var blockedTarget = definition.node(blockedTransition.toNodeDefinitionId());
            var blockedAttributes = effectiveTransitionAttributes(node, blockedTransition.attributes());
            if (startsNewIteration(blockedAttributes, node.nodeDefinitionId(), "BLOCKED", blockedTarget.id())) {
                throw new IOException("revision limit BLOCKED route to a human gate must not start an iteration: "
                        + node.nodeDefinitionId());
            }

            effectiveOutcome = "BLOCKED";
            effectiveResult = blockedResult;
            gateSourceResult = Map.of(
                    "reason", "revision_limit_reached",
                    "revision_limit_original_outcome", outcome,
                    "max_revisions", maxRevisions,
                    "current_revision_count", currentRevisionCount
            );
            matchingTransitions = blockedRoute;
            jsonWriter.write(paths.nodeJson(nodeInstanceId), new NodeInstanceDocument(
                    finished.schemaVersion(),
                    finished.nodeInstanceId(),
                    finished.nodeDefinitionId(),
                    finished.kind(),
                    finished.handlerType(),
                    finished.status(),
                    finished.stageId(),
                    finished.iterationId(),
                    finished.inputRefs(),
                    finished.inputTransition(),
                    finished.outputRefs(),
                    effectiveResult,
                    finished.runRef(),
                    finished.latestExecutionId(),
                    finished.startedAt(),
                    finished.finishedAt()
            ));
            lastEventId = LedgerUtils.nextEventId(lastEventId);
            eventLog.appendEvent(paths, lastEventId, "revision_limit_reached", Map.of(
                    "node", node.nodeDefinitionId(),
                    "node_instance_id", node.nodeInstanceId(),
                    "outcome", outcome,
                    "max_revisions", maxRevisions,
                    "current_revision_count", currentRevisionCount,
                    "declared_blocked_gate", blockedTarget.id()
            ));
            break;
        }

        // Fan-out: create successor nodes for all matching edges
        var successorNodeIds = new java.util.ArrayList<String>();
        var allOpenGateIds = new java.util.ArrayList<String>();
        var workflowStatus = WorkflowStatus.RUNNING;

        for (var transition : matchingTransitions) {
            var nextDefinition = definition.node(transition.toNodeDefinitionId());
            var transitionAttributes = ExecutionNetworkGrantStore.forward(jsonWriter, paths, node, nextDefinition,
                    collectionTransition(paths, finished, nextDefinition, effectiveTransitionAttributes(node, transition.attributes())));
            var occurrenceTransition = new LinkedHashMap<String, Object>(transitionAttributes);
            occurrenceTransition.put("source_node_instance_id", node.nodeInstanceId());
            occurrenceTransition.put("source_node_sha256", LedgerSession.sha(jsonWriter.readBytes(paths.nodeJson(node.nodeInstanceId()))));
            transitionAttributes = Map.copyOf(occurrenceTransition);
            if (!joinReady(paths, current, nodeInstanceId, transitionAttributes)) {
                lastEventId = LedgerUtils.nextEventId(lastEventId);
                eventLog.appendEvent(paths, lastEventId, "join_deferred", Map.of(
                        "from", node.nodeDefinitionId(),
                        "outcome", outcome,
                        "to", nextDefinition.id(),
                        "transition", transitionAttributes,
                        "reason", "waiting_for_branch_group"
                ));
                continue;
            }
            var eventNum = LedgerUtils.currentEventNumber(lastEventId) + 1;
            var nextNodeInstanceId = LedgerUtils.nodeInstanceId(nextDefinition.id(), eventNum);
            var nextStatus = nextDefinition.kind() == NodeKind.GATE ? NodeStatus.WAITING : NodeStatus.READY;
            var nextGateResult = new LinkedHashMap<String, Object>();
            if (nextDefinition.kind() == NodeKind.GATE) {
                nextGateResult.putAll(gateSourceResult);
                nextGateResult.put("source_node_instance_id", node.nodeInstanceId());
            }
            var nextIterationId = node.iterationId();
            var iterationStartedPayload = Map.<String, Object>of();
            if (nextDefinition.kind() != NodeKind.GATE
                    && startsNewIteration(transitionAttributes, node.nodeDefinitionId(), effectiveOutcome, nextDefinition.id())) {
                var maxRevisions = RevisionTracker.maxRevisions(definition.node(node.nodeDefinitionId()));
                var currentRevisionCount = revisionTracker.revisionCount(
                        paths,
                        node.nodeDefinitionId(),
                        nextDefinition.id()
                );
                if (!humanAuthorizedRevision
                        && maxRevisions >= 0
                        && currentRevisionCount >= maxRevisions) {
                    revisionTracker.blockOnRevisionLimit(paths, current, node, outputRefs, effectiveResult,
                            effectiveOutcome, maxRevisions, currentRevisionCount);
                    return;
                }
                var nextIteration = revisionTracker.nextRevisionIteration(
                        paths, node, effectiveOutcome, nextDefinition.id(), effectiveResult);
                Files.createDirectories(paths.iterationsDir());
                jsonWriter.write(paths.iterationJson(nextIteration.iterationId()), nextIteration);
                nextIterationId = nextIteration.iterationId();
                iterationStartedPayload = Map.of(
                        "iteration_id", nextIteration.iterationId(),
                        "parent_iteration_id", nextIteration.parentIterationId(),
                        "trigger_node_instance_id", nextIteration.triggerNodeInstanceId(),
                        "trigger_action", nextIteration.triggerAction(),
                        "target_node_definition_id", nextIteration.targetNodeDefinitionId(),
                        "reason", nextIteration.reason(),
                        "transition_type", text(transitionAttributes.get("transition_type")),
                        "loop_reason", text(transitionAttributes.get("loop_reason")),
                        "branch_group_id", text(transitionAttributes.get("branch_group_id"))
                );
            }
            var nextNode = new NodeInstanceDocument(
                    1,
                    nextNodeInstanceId,
                    nextDefinition.id(),
                    nextDefinition.kind(),
                    nextDefinition.handlerType(),
                    nextStatus,
                    LedgerUtils.stageId(nextDefinition.id()),
                    nextIterationId,
                    outputRefs,
                    transitionAttributes,
                    List.of(),
                    nextDefinition.kind() == NodeKind.GATE ? Map.copyOf(nextGateResult) : Map.of(),
                    null,
                    "",
                    null,
                    null
            );
            jsonWriter.write(paths.nodeJson(nextNodeInstanceId), nextNode);

            var gateId = "";
            if (nextDefinition.kind() == NodeKind.GATE) {
                gateId = "gate-" + nextNodeInstanceId;
                allOpenGateIds.add(gateId);
                workflowStatus = WorkflowStatus.WAITING_FOR_HUMAN;
                jsonWriter.write(paths.gateJson(gateId), new GateDocument(
                        1,
                        gateId,
                        nextNodeInstanceId,
                        nextDefinition.handlerType(),
                        "open",
                        HumanGateActionSemantics.allowedActions(nextDefinition, effectiveOutcome),
                        Instant.now(),
                        null,
                        Map.of(
                                "subject_input_refs", List.copyOf(outputRefs),
                                "source_outcome", effectiveOutcome,
                                "source_node_instance_id", node.nodeInstanceId()
                        )
                    ));
            }

            lastEventId = LedgerUtils.nextEventId(lastEventId);
            var routedPayload = new LinkedHashMap<String, Object>();
            routedPayload.put("from", node.nodeDefinitionId());
            routedPayload.put("outcome", effectiveOutcome);
            routedPayload.put("to", nextDefinition.id());
            routedPayload.put("node_instance_id", nextNodeInstanceId);
            routedPayload.put("gate_id", gateId);
            routedPayload.put("transition", transitionAttributes);
            routedPayload.put("source_node_instance_id", node.nodeInstanceId());
            eventLog.appendEvent(paths, lastEventId, "node_routed", Map.copyOf(routedPayload));
            if (!iterationStartedPayload.isEmpty()) {
                lastEventId = LedgerUtils.nextEventId(lastEventId);
                eventLog.appendEvent(paths, lastEventId, "iteration_started", iterationStartedPayload);
            }
            successorNodeIds.add(nextNodeInstanceId);
        }

        // Compute remaining active: remove completed node, add successors
        var nextActiveIds = new java.util.ArrayList<>(current.activeNodeInstanceIds());
        nextActiveIds.remove(nodeInstanceId);
        nextActiveIds.addAll(successorNodeIds);

        if (nextActiveIds.isEmpty()) {
            completeWorkflow(paths, definition, current, node, outcome);
            return;
        }

        var now = Instant.now();
        var next = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                workflowStatus,
                List.copyOf(nextActiveIds),
                List.copyOf(allOpenGateIds),
                lastEventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), next);
        eventLog.writeInstanceFromCurrent(paths, next, now);
    }

    private boolean joinReady(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            String completedNodeInstanceId,
            Map<String, Object> transitionAttributes
    ) throws IOException {
        if (!"join".equals(text(transitionAttributes.get("transition_type")))) {
            return true;
        }
        var joinStrategy = text(transitionAttributes.get("join_strategy"));
        if (joinStrategy.isBlank()) {
            joinStrategy = "all_terminal";
        }
        if (!"all_terminal".equals(joinStrategy)) {
            throw new IOException("unsupported join strategy: " + joinStrategy);
        }
        var branchGroupId = text(transitionAttributes.get("branch_group_id"));
        if (branchGroupId.isBlank()) {
            throw new IOException("join transition requires branch_group_id");
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            if (activeNodeId.equals(completedNodeInstanceId)) {
                continue;
            }
            var activeNode = loadNode(paths, activeNodeId);
            var activeTransition = activeNode.inputTransition();
            if (branchGroupId.equals(text(activeTransition.get("branch_group_id")))) {
                return false;
            }
        }
        return true;
    }

    private Map<String, Object> collectionTransition(WorkstreamPaths paths, NodeInstanceDocument source, NodeDefinition target,
                                                       Map<String, Object> attributes) throws IOException {
        var result = new LinkedHashMap<>(attributes);
        if (source.kind() == NodeKind.GATE) {
            if ("collect_evidence".equals(source.result().get("human_action"))
                    || "submit_evidence".equals(source.result().get("human_action"))) {
                if (!source.result().containsKey("evidence_collection_baseline"))
                    throw new IOException("missing evidence collection approval baseline");
                result.put("evidence_collection_gate", source.nodeInstanceId());
                try {
                    result.put("evidence_collection_gate_sha256", java.util.HexFormat.of().formatHex(
                            java.security.MessageDigest.getInstance("SHA-256")
                                    .digest(jsonWriter.readBytes(paths.nodeJson(source.nodeInstanceId())))));
                } catch (java.security.NoSuchAlgorithmException impossible) { throw new IOException(impossible); }
            }
        } else if (!"loop".equals(attributes.get("transition_type"))
                || "self_test_report".equals(target.config().get("expected_artifact"))) {
            inheritIfMissing(result, source.inputTransition(), "evidence_collection_gate");
            inheritIfMissing(result, source.inputTransition(), "evidence_collection_gate_sha256");
        }
        return Map.copyOf(result);
    }

    private static Map<String, Object> effectiveTransitionAttributes(
            NodeInstanceDocument sourceNode,
            Map<String, Object> transitionAttributes
    ) {
        var effective = new LinkedHashMap<String, Object>();
        if (transitionAttributes != null) {
            effective.putAll(transitionAttributes);
        }
        var inherited = sourceNode.inputTransition();
        inheritIfMissing(effective, inherited, "branch_group_id");
        inheritIfMissing(effective, inherited, "required");
        inheritIfMissing(effective, inherited, "purpose");
        return Map.copyOf(effective);
    }

    private static void inheritIfMissing(Map<String, Object> target, Map<String, Object> source, String key) {
        if (target.containsKey(key) || !source.containsKey(key)) {
            return;
        }
        target.put(key, source.get(key));
    }

    private static boolean startsNewIteration(
            Map<String, Object> transitionAttributes,
            String sourceNodeDefinitionId,
            String outcome,
            String targetNodeDefinitionId
    ) {
        if ("loop".equals(text(transitionAttributes.get("transition_type")))) {
            return true;
        }
        return RevisionTracker.startsNewIteration(sourceNodeDefinitionId, outcome, targetNodeDefinitionId);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private List<String> activeNodeDefinitionIds(WorkstreamPaths paths, List<String> activeNodeInstanceIds) throws IOException {
        var nodeDefinitionIds = new java.util.ArrayList<String>();
        for (var activeNodeInstanceId : activeNodeInstanceIds) {
            nodeDefinitionIds.add(loadNode(paths, activeNodeInstanceId).nodeDefinitionId());
        }
        return List.copyOf(nodeDefinitionIds);
    }

    void resolveOpenGate(WorkstreamPaths paths, WorkflowDefinition definition, String action, String note)
            throws IOException {
        resolveOpenGate(paths, definition, action, note, null);
    }

    void resolveOpenGate(WorkstreamPaths paths, WorkflowDefinition definition, String action, String note,
                         EvidenceCollectionBaseline collection) throws IOException {
        resolveOpenGate(paths, definition, action, note, collection, null);
    }

    void resolveOpenGate(WorkstreamPaths paths, WorkflowDefinition definition, String action, String note,
                         EvidenceCollectionBaseline collection, EvidenceSubmission submission) throws IOException {
        if ("submit_evidence".equals(action) != (submission != null))
            throw new IOException("submit_evidence requires the typed material submission API");
        if ("request_action".equals(action == null ? "" : action.trim())) {
            throw new IOException("request_action does not resolve a gate; use the action request API");
        }
        if (action == null || action.isBlank()) {
            throw new IOException("human gate action is required");
        }
        var current = loadCurrent(paths);
        if (current.activeNodeInstanceIds().isEmpty()) {
            throw new IOException("no active gate node");
        }
        var node = loadNode(paths, current.activeNodeInstanceIds().get(0));
        if (node.kind() != NodeKind.GATE) {
            throw new IOException("active node is not a gate: " + node.nodeDefinitionId());
        }
        var outgoingEdges = definition.edgesFrom(node.nodeDefinitionId());
        var canonicalAction = HumanGateActionSemantics.canonicalAction(outgoingEdges, action.trim());
        if (FINAL_NEXT_STAGE_GATE.equals(node.nodeDefinitionId())
                && ("approve".equals(canonicalAction) || "approved".equals(canonicalAction))) {
            throw new IOException("final next-stage gate cannot be approved; use complete to finish the workstream");
        }
        var hasEdge = outgoingEdges.stream().anyMatch(edge -> edge.on().equals(canonicalAction));
        var actionAllowed = HumanGateActionSemantics.allowedActions(definition.node(node.nodeDefinitionId()))
                .contains(canonicalAction);
        if (!hasEdge && !actionAllowed) {
            throw new IOException("unsupported gate action for " + node.nodeDefinitionId() + ": " + action);
        }
        var gate = requireOpenGate(paths, current, node);
        var sourceOutcome = text(gate.result().get("source_outcome"));
        if (HumanGateActionSemantics.COLLECT_EVIDENCE.equals(canonicalAction)
                || HumanGateActionSemantics.SUBMIT_EVIDENCE.equals(canonicalAction)) {
            if (collection == null || !collection.gateNodeInstanceId().equals(node.nodeInstanceId())
                    || current.status() != WorkflowStatus.WAITING_FOR_HUMAN
                    || !current.activeNodeInstanceIds().equals(List.of(node.nodeInstanceId()))
                    || note == null || note.isBlank() || !hasEdge
                    || !HumanGateActionSemantics.allowedActions(definition.node(node.nodeDefinitionId()), sourceOutcome)
                    .contains(canonicalAction)
                    || !node.inputRefs().equals(gate.result().get("subject_input_refs"))) {
                throw new IOException("collect_evidence requires a bound source baseline and explicit human note");
            }
        } else if (collection != null) {
            throw new IOException("source baseline is only valid for collect_evidence");
        }
        if (HumanGateActionSemantics.REQUEST_SCOPE_REVISION.equals(canonicalAction)) {
            var applicable = HumanGateActionSemantics.allowedActions(
                    definition.node(node.nodeDefinitionId()), sourceOutcome).contains(canonicalAction);
            if (!applicable || !hasEdge) {
                throw new IOException("scope revision requires a declared scope-repair occurrence and route");
            }
            if (note == null || note.isBlank()) {
                throw new IOException("a decision note is required for scope revision");
            }
            ScopeRevisionRequestGuard.verify(paths, node, gate, objectMapper);
            var max = RevisionTracker.maxRevisions(definition.node(node.nodeDefinitionId()));
            if (max >= 0 && revisionTracker.revisionCount(paths, node.nodeDefinitionId(),
                    "context.intake_claude_brainstorm") >= max) {
                throw new IOException("scope revision request budget exhausted; gate remains open");
            }
        }
        if (HumanGateActionSemantics.requiresDecisionNote(canonicalAction, sourceOutcome)
                && (note == null || note.isBlank())) {
            throw new IOException("a decision note is required for " + canonicalAction + " at "
                    + node.nodeDefinitionId() + " (" + sourceOutcome + ")");
        }
        resolveGateDocument(paths, gate, canonicalAction, note);
        var humanAuthorizedRevision = "revise".equals(canonicalAction)
                && note != null
                && !note.isBlank();
        var resolvedNodeResult = new LinkedHashMap<String, Object>(node.result());
        resolvedNodeResult.put("human_action", canonicalAction);
        resolvedNodeResult.put("requested_action", action);
        resolvedNodeResult.put("note", note == null ? "" : note);
        if (collection != null) resolvedNodeResult.put("evidence_collection_baseline", collection);
        if (submission != null) resolvedNodeResult.put("external_evidence", submission);
        completeAndRoute(paths, definition, node.nodeInstanceId(), NodeStatus.COMPLETED, canonicalAction,
                node.inputRefs(), Map.copyOf(resolvedNodeResult), humanAuthorizedRevision);
    }

    Map<String, Object> requestAction(WorkstreamPaths paths, WorkflowDefinition definition, HumanActionRequest request)
            throws IOException {
        var current = loadCurrent(paths);
        if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN
                || !current.activeNodeInstanceIds().equals(List.of(request.gateNodeInstanceId()))) {
            throw new IOException("action request requires the current waiting gate occurrence");
        }
        var node = loadNode(paths, request.gateNodeInstanceId());
        var gate = requireOpenGate(paths, current, node);
        if (node.kind() != NodeKind.GATE || !HumanGateActionSemantics.allowedActions(
                definition.node(node.nodeDefinitionId()), text(gate.result().get("source_outcome")))
                .contains("request_action")) throw new IOException("action request is not available at this gate");
        if (!node.inputRefs().equals(request.sourceRefs())
                || !node.inputRefs().equals(gate.result().get("subject_input_refs"))) {
            throw new IOException("action request source references do not match the current gate");
        }
        var content = Map.<String, Object>of("request_id", request.requestId(),
                "gate_node_instance_id", request.gateNodeInstanceId(), "source_refs", request.sourceRefs(),
                "expected_result", request.expectedResult(),
                "why_existing_actions_insufficient", request.whyExistingActionsInsufficient());
        var requests = new java.util.ArrayList<Object>();
        var existing = node.result().get("action_requests");
        if (existing != null && !(existing instanceof List<?>)) throw new IOException("invalid action request ledger");
        if (existing instanceof List<?> list) requests.addAll(list);
        for (var entry : requests) {
            if (!(entry instanceof Map<?, ?> item)) throw new IOException("invalid action request ledger");
            if (request.requestId().equals(item.get("request_id"))) {
                if (!content.equals(item.get("content"))) throw new IOException("request id already has different content");
                return objectMapper.convertValue(item, new com.fasterxml.jackson.core.type.TypeReference<Map<String, Object>>() {});
            }
        }
        var record = Map.<String, Object>of("request_id", request.requestId(), "content", content,
                "recorded_at", Instant.now().toString());
        requests.add(record);
        var result = new LinkedHashMap<>(node.result());
        result.put("action_requests", List.copyOf(requests));
        jsonWriter.write(paths.nodeJson(node.nodeInstanceId()), new NodeInstanceDocument(node.schemaVersion(),
                node.nodeInstanceId(), node.nodeDefinitionId(), node.kind(), node.handlerType(), node.status(),
                node.stageId(), node.iterationId(), node.inputRefs(), node.inputTransition(), node.outputRefs(),
                result, node.runRef(), node.latestExecutionId(), node.startedAt(), node.finishedAt()));
        // The node is authoritative even if appending this derived audit event fails.
        eventLog.appendEvent(paths, "human-action-" + java.util.UUID.randomUUID(), "human_action_requested",
                Map.of("node_instance_id", node.nodeInstanceId(), "request_id", request.requestId()));
        return record;
    }

    private GateDocument requireOpenGate(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node
    ) throws IOException {
        for (var gateId : current.openGateIds()) {
            var gatePath = paths.gateJson(gateId);
            if (!jsonWriter.exists(gatePath)) {
                continue;
            }
            var gate = jsonWriter.read(gatePath, GateDocument.class);
            if (gate.nodeInstanceId().equals(node.nodeInstanceId()) && "open".equals(gate.status())) {
                return gate;
            }
        }
        throw new IOException("no matching open gate document for node: " + node.nodeInstanceId());
    }

    private void resolveGateDocument(
            WorkstreamPaths paths,
            GateDocument gate,
            String action,
            String note
    ) throws IOException {
        jsonWriter.write(paths.gateJson(gate.gateId()), gate.resolved(action, note));
    }

    private void completeWorkflow(
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node,
            String outcome
    ) throws IOException {
        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        eventLog.appendEvent(paths, eventId, "workflow_completed", Map.of(
                "last_node", node.nodeDefinitionId(),
                "outcome", outcome
        ));
        var now = Instant.now();
        completionAuditWriter.write(paths, definition, node, outcome, now);
        var completed = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.COMPLETED,
                List.of(),
                List.of(),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), completed);
        eventLog.writeInstanceFromCurrent(paths, completed, now);
    }

    private void stopOnNonCompletedNode(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node,
            NodeStatus nodeStatus,
            String outcome,
            Map<String, Object> result
    ) throws IOException {
        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        var workflowStatus = WorkflowStatus.WAITING_FOR_RECOVERY;
        var recoveryGateId = "recovery-" + node.nodeInstanceId();
        var controlRepair = LedgerUtils.isControlRepairFailure(outcome, result);
        var gateResult = recoveryGateResult(node, nodeStatus, outcome, result, controlRepair);
        jsonWriter.write(paths.gateJson(recoveryGateId), new GateDocument(
                1,
                recoveryGateId,
                node.nodeInstanceId(),
                controlRepair ? "control.repair" : "recovery.review",
                "open",
                List.of("retry", "abort"),
                Instant.now(),
                null,
                gateResult
        ));
        var eventPayload = new LinkedHashMap<>(gateResult);
        eventPayload.put("recovery_gate_id", recoveryGateId);
        eventLog.appendEvent(paths, eventId, controlRepair ? "control_repair_required" : "node_" + nodeStatus.name().toLowerCase(), eventPayload);
        var now = Instant.now();
        var stopped = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                workflowStatus,
                List.of(node.nodeInstanceId()),
                List.of(recoveryGateId),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), stopped);
        eventLog.writeInstanceFromCurrent(paths, stopped, now);
    }

    private static Map<String, Object> recoveryGateResult(
            NodeInstanceDocument node,
            NodeStatus nodeStatus,
            String outcome,
            Map<String, Object> result,
            boolean controlRepair
    ) {
        var gateResult = new LinkedHashMap<String, Object>();
        gateResult.put("node", node.nodeDefinitionId());
        gateResult.put("node_status", nodeStatus.name());
        gateResult.put("outcome", outcome);
        if (controlRepair) {
            gateResult.put("reason", LedgerUtils.text(LedgerUtils.firstNonBlank(LedgerUtils.resultValue(result, "reason"), outcome)));
            gateResult.put("message", LedgerUtils.text(LedgerUtils.resultValue(result, "message")));
            gateResult.put("input_refs", LedgerUtils.resultValueOrDefault(result, "input_refs", List.of()));
            gateResult.put("allowed_decisions", LedgerUtils.resultValueOrDefault(result, "allowed_decisions", List.of()));
            gateResult.put("parse_error", LedgerUtils.resultValueOrDefault(result, "parse_error", Map.of()));
        }
        return gateResult;
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.contract.TaskContractValidator;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.workflow.NodeStatus;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.HexFormat;

/** Pre-mutation integrity check for a human request, not a scope approval. */
final class ScopeRevisionRequestGuard {
    private ScopeRevisionRequestGuard() {}

    static void verify(WorkstreamPaths paths, NodeInstanceDocument gateNode, GateDocument gate,
                       ObjectMapper mapper) throws IOException {
        var root = paths.workstreamDir().toAbsolutePath().normalize().getParent().getParent().getParent();
        var sourceId = String.valueOf(gate.result().get("source_node_instance_id"));
        require(sourceId.matches("[A-Za-z0-9._-]+"), "scope source identity is missing");
        var source = mapper.readValue(paths.nodeJson(sourceId).toFile(), NodeInstanceDocument.class);
        require(sourceId.equals(source.nodeInstanceId()) && source.status() == NodeStatus.COMPLETED
                && source.nodeDefinitionId().equals("implement.artifact_validation")
                && source.handlerType().equals("artifact.validate")
                && source.iterationId().equals(gateNode.iterationId())
                && "FAIL".equals(source.result().get("change_scope_status"))
                && "CHANGE_SCOPE_VIOLATION".equals(source.result().get("change_scope_disposition")),
                "scope source is not a completed violation");
        var binding = mapper.valueToTree(source.result().get("scope_rework_baseline"));
        require(binding != null && binding.isObject(), "scope rework baseline is missing");
        var ref = binding.path("evaluation_ref").asText();
        var sha = binding.path("evaluation_sha256").asText();
        require(ref.equals(source.result().get("change_scope_evaluation_ref"))
                && sha.equals(source.result().get("change_scope_evaluation_sha256"))
                && gateNode.inputRefs().contains(ref) && source.outputRefs().contains(ref)
                && mapper.valueToTree(gateNode.inputRefs()).equals(mapper.valueToTree(gate.result().get("subject_input_refs"))),
                "scope evaluation is not the gate subject");
        var doc = mapper.readTree(verifiedPath(root, paths, ref, sha).toFile());
        require(doc.path("sourceNodeInstanceId").asText().equals(sourceId)
                && doc.path("schemaVersion").asInt() == 1, "scope evaluation identity is invalid");
        var evaluation = doc.path("evaluation");
        require("FAIL".equals(evaluation.path("status").asText()) && evaluation.path("violations").isArray()
                && !evaluation.path("violations").isEmpty(), "scope evaluation has no violations");
        var seen = new HashSet<String>();
        for (var violation : evaluation.path("violations")) {
            var path = violation.path("path").asText();
            require("UNEXPECTED_ACTUAL_CHANGE".equals(violation.path("code").asText())
                    && "CREATE".equals(violation.path("actualOperation").asText())
                    && violation.path("declaredOperation").isNull() && violation.path("previousPath").isNull()
                    && TaskContractValidator.isCanonicalPath(path) && seen.add(path),
                    "scope revision only supports ordinary new file violations");
        }
        for (var field : new String[]{"proposal_review", "contract_gate", "requirement_gate"}) {
            verifiedPath(root, paths, binding.path(field + "_ref").asText(), binding.path(field + "_sha256").asText());
        }
        var proposal = binding.path("proposal_reference");
        verifiedPath(root, paths, proposal.path("artifact_ref").asText(), proposal.path("sha256").asText());
        var contractRef = binding.path("task_contract_ref").asText();
        var resolutionRef = binding.path("contract_resolution_ref").asText();
        var contract = mapper.readValue(verifiedPath(root, paths, contractRef, binding.path("task_contract_sha256").asText()).toFile(), TaskContract.class);
        verifiedPath(root, paths, resolutionRef, binding.path("contract_resolution_sha256").asText());
        require(contract.phase() == TaskContract.Phase.EXECUTION && contract.goalContract() != null,
                "scope baseline must be an execution contract");
        var compileId = binding.path("compile_node_instance_id").asText();
        require(compileId.matches("[A-Za-z0-9._-]+"), "scope compile identity is invalid");
        var compile = mapper.readValue(paths.nodeJson(compileId).toFile(), NodeInstanceDocument.class);
        require(compile.status() == NodeStatus.COMPLETED && compile.nodeDefinitionId().equals("contract.compile_execution")
                && compile.outputRefs().contains(contractRef) && compile.outputRefs().contains(resolutionRef)
                && binding.path("task_contract_sha256").asText().equals(compile.result().get("task_contract_sha256"))
                && binding.path("contract_resolution_sha256").asText().equals(compile.result().get("contract_resolution_sha256")),
                "scope compile baseline changed");
        var goalId = binding.path("goal_compile_node_instance_id").asText();
        require(goalId.matches("[A-Za-z0-9._-]+"), "scope GOAL compile identity is invalid");
        var goal = mapper.readValue(paths.nodeJson(goalId).toFile(), NodeInstanceDocument.class);
        require(goal.status() == NodeStatus.COMPLETED && goal.nodeDefinitionId().equals("contract.compile")
                && goal.outputRefs().contains(contract.goalContract().ref())
                && contract.goalContract().sha256().equals(goal.result().get("task_contract_sha256")),
                "scope GOAL compile binding changed");
        verifiedPath(root, paths, contract.goalContract().ref(), contract.goalContract().sha256());
        var workspaceId = binding.path("workspace_id").asText();
        require(workspaceId.matches("[A-Za-z0-9._-]+"), "scope workspace is missing");
        var workspace = mapper.readTree(paths.workstreamDir().resolve("workspaces/" + workspaceId + ".json").toFile());
        require(binding.path("base_commit").asText().matches("[0-9a-f]{40}|[0-9a-f]{64}")
                && binding.path("base_commit").equals(workspace.path("baseCommit")), "scope original base changed");
    }

    private static Path verifiedPath(Path root, WorkstreamPaths paths, String ref, String sha) throws IOException {
        var target = root.resolve(ref).normalize();
        require(!ref.isBlank() && !Path.of(ref).isAbsolute() && root.relativize(target).toString().equals(ref)
                && target.startsWith(paths.workstreamDir().toAbsolutePath().normalize())
                && Files.isRegularFile(target) && target.toRealPath().equals(root.toRealPath().resolve(ref))
                && sha.matches("[0-9a-f]{64}"), "scope baseline reference is missing or noncanonical");
        try {
            require(sha.equals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(target)))),
                    "scope baseline hash mismatch");
        } catch (NoSuchAlgorithmException impossible) { throw new IOException(impossible); }
        return target;
    }

    private static void require(boolean condition, String reason) throws IOException {
        if (!condition) throw new IOException(reason);
    }
}

