                entry.handlerType(),
                NodeStatus.READY,
                LedgerUtils.stageId(entry.id()),
                "iter-001",
                List.of(),
                Map.of(),
                List.of(),
                Map.of(),
                null,
                "",
                null,
                null
        ));
        refreshProjections(paths);
