package dev.dual.ledger.file;

import dev.dual.core.workflow.WorkflowStatus;

import java.time.Instant;
import java.util.List;

public record WorkflowInstanceDocument(
        int schemaVersion,
        String workflowInstanceId,
        String workflowId,
        int definitionVersion,
        WorkflowStatus status,
        List<String> activeNodeInstanceIds,
        String lastEventId,
        Instant createdAt,
        Instant updatedAt
) {
    public WorkflowInstanceDocument {
        if (schemaVersion <= 0) {
            throw new IllegalArgumentException("schemaVersion must be positive");
        }
        requireText(workflowInstanceId, "workflowInstanceId");
        requireText(workflowId, "workflowId");
        if (definitionVersion <= 0) {
            throw new IllegalArgumentException("definitionVersion must be positive");
        }
        if (status == null) {
            throw new IllegalArgumentException("status is required");
        }
        activeNodeInstanceIds = List.copyOf(activeNodeInstanceIds == null ? List.of() : activeNodeInstanceIds);
        activeNodeInstanceIds.forEach(value -> requireText(value, "activeNodeInstanceIds"));
        requireText(lastEventId, "lastEventId");
        if (createdAt == null) {
            throw new IllegalArgumentException("createdAt is required");
        }
        if (updatedAt == null) {
            throw new IllegalArgumentException("updatedAt is required");
        }
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
    }
}

package dev.dual.ledger.file;

import java.time.Instant;

public record WorkflowIterationDocument(
        int schemaVersion,
        String iterationId,
        String parentIterationId,
        int number,
        String stageId,
        String status,
        String triggerNodeInstanceId,
        String triggerAction,
        String targetNodeDefinitionId,
        String reason,
        Instant createdAt
) {
    public WorkflowIterationDocument {
        if (schemaVersion <= 0) {
            throw new IllegalArgumentException("schemaVersion must be positive");
        }
        requireText(iterationId, "iterationId");
        if (number <= 0) {
            throw new IllegalArgumentException("number must be positive");
        }
        requireText(stageId, "stageId");
        requireText(status, "status");
        requireText(triggerAction, "triggerAction");
        requireText(targetNodeDefinitionId, "targetNodeDefinitionId");
        if (createdAt == null) {
            throw new IllegalArgumentException("createdAt is required");
        }
        parentIterationId = parentIterationId == null ? "" : parentIterationId;
        triggerNodeInstanceId = triggerNodeInstanceId == null ? "" : triggerNodeInstanceId;
        reason = reason == null ? "" : reason;
    }

    public static WorkflowIterationDocument initial(String entryNodeId, Instant createdAt) {
        return new WorkflowIterationDocument(
                1,
                "iter-001",
                "",
                1,
                stageId(entryNodeId),
                "active",
                "",
                "workflow_started",
                entryNodeId,
                "Initial workflow iteration.",
                createdAt
        );
    }

    public static WorkflowIterationDocument revision(
            String iterationId,
            int number,
            String parentIterationId,
            String triggerNodeInstanceId,
            String triggerAction,
            String targetNodeDefinitionId,
            String reason,
            Instant createdAt
    ) {
        return new WorkflowIterationDocument(
                1,
                iterationId,
                parentIterationId,
                number,
                stageId(targetNodeDefinitionId),
                "active",
                triggerNodeInstanceId,
                triggerAction,
                targetNodeDefinitionId,
                reason,
                createdAt
        );
    }

    private static String stageId(String nodeDefinitionId) {
        var separator = nodeDefinitionId.indexOf('.');
        var prefix = separator > 0 ? nodeDefinitionId.substring(0, separator) : "workflow";
        return "stage-" + prefix;
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
    }
}

