    @Test
    void typedPermissionFailurePreservesCurrentActionForOperatorWithoutBlindRetry() {
        var node = failedAcpxNode(Map.of(
                "agent_execution_outcome", Map.of(
                        "status", "RECOVERABLE_ADAPTER_FAILURE",
