package dev.dual.runtime;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;
import java.util.zip.ZipFile;

/** Content identity for the existing packaged entrypoints or the complete development classpath. */
public final class FrozenRuntimeIdentity {
    private FrozenRuntimeIdentity() {}

    public static Map<String, String> capture(Class<?> entrypoint, String configuredKernel,
                                              String effectiveKernel, Map<String, String> behavior) {
        try {
            var identity = new TreeMap<String, String>();
            var classpath = System.getProperty("java.class.path", "");
            if (classpath.isBlank()) throw new IOException("runtime classpath is missing");
            var entries = classpath.split(java.util.regex.Pattern.quote(java.io.File.pathSeparator), -1);
            Path executable = entries.length == 1 ? Path.of(entries[0]).toAbsolutePath().normalize() : null;
            if (executable != null && Files.isRegularFile(executable) && isBootEntry(executable, entrypoint)) {
                var bundle = new TreeMap<String, Path>();
                var role = role(executable);
                bundle.put(role, executable);
                var other = sibling(executable, role);
                if (Files.isRegularFile(other)) bundle.put(role.equals("cli") ? "server" : "cli", other);
                identity.putAll(packaged(bundle));
            } else {
                // Preserve classpath order: reordering shadowed classes changes executable behavior.
                for (int index = 0; index < entries.length; index++) {
                    if (entries[index].isBlank()) throw new IOException("empty runtime classpath entry");
                    identity.put("classpath." + String.format("%04d", index), content(Path.of(entries[index])));
                }
                var source = Path.of(entrypoint.getProtectionDomain().getCodeSource().getLocation().toURI()).toRealPath();
                boolean found = false;
                for (var entry : entries) if (Path.of(entry).toRealPath().equals(source)) found = true;
                if (!found) throw new IOException("entrypoint code source is outside the captured classpath");
            }
            identity.put("identity_schema", "dual-runtime-content.v1");
            identity.put("kernel.configured", configuredKernel == null ? "" : configuredKernel);
            identity.put("kernel.effective", java.util.Objects.requireNonNull(effectiveKernel));
            identity.put("java.runtime", System.getProperty("java.runtime.version"));
            // Only explicit non-secret behavior settings may be supplied; never capture the whole environment.
            behavior.forEach((key, value) -> identity.put("behavior." + key, value));
            return Map.copyOf(identity);
        } catch (Exception failure) {
            throw new IllegalStateException("cannot establish frozen runtime content identity", failure);
        }
    }

    static Map<String, String> packaged(Map<String, Path> artifacts) throws IOException {
        if (artifacts.isEmpty()) throw new IOException("empty runtime artifact set");
        var result = new TreeMap<String, String>();
        Map<String, String> shared = null;
        for (var item : new TreeMap<>(artifacts).entrySet()) {
            if (!java.util.Set.of("cli", "server").contains(item.getKey())) throw new IOException("unknown entrypoint");
            var dependencies = new TreeMap<String, String>();
            try (var zip = new ZipFile(item.getValue().toFile())) {
                var entries = zip.entries();
                while (entries.hasMoreElements()) {
                    var entry = entries.nextElement();
                    if (entry.getName().startsWith("BOOT-INF/lib/dual-")) {
                        try (var input = zip.getInputStream(entry)) {
                            dependencies.put(entry.getName(), sha(input.readAllBytes()));
                        }
                    }
                }
            }
            if (dependencies.isEmpty()) throw new IOException("packaged runtime has no Dual dependencies");
            if (shared != null && !shared.equals(dependencies))
                throw new IOException("CLI/server contain different shared Dual binaries");
            shared = dependencies;
            result.put("executable." + item.getKey(), content(item.getValue()));
        }
        return result;
    }

    static String content(Path input) throws IOException {
        var path = input.toRealPath();
        if (Files.isRegularFile(path)) return sha(Files.readAllBytes(path));
        if (!Files.isDirectory(path)) throw new IOException("unsupported runtime input: " + input);
        var files = new TreeMap<String, String>();
        try (var stream = Files.walk(path)) {
            for (var file : stream.sorted().toList()) {
                if (Files.isSymbolicLink(file)) throw new IOException("symlink in development classpath: " + file);
                if (Files.isRegularFile(file)) files.put(path.relativize(file).toString(), sha(Files.readAllBytes(file)));
            }
        }
        var digest = new StringBuilder();
        files.forEach((name, hash) -> digest.append(name.length()).append(':').append(name).append(':').append(hash).append('\n'));
        return sha(digest.toString().getBytes(StandardCharsets.UTF_8));
    }

    private static boolean isBootEntry(Path path, Class<?> entrypoint) throws IOException {
        try (var zip = new ZipFile(path.toFile())) {
            var manifest = zip.getEntry("META-INF/MANIFEST.MF");
            if (manifest == null) return false;
            try (var input = zip.getInputStream(manifest)) {
                return entrypoint.getName().equals(new java.util.jar.Manifest(input).getMainAttributes().getValue("Start-Class"));
            }
        }
    }

    private static String role(Path executable) throws IOException {
        var name = executable.getFileName().toString();
        if (name.startsWith("dual-cli") && name.endsWith(".jar")) return "cli";
        if (name.startsWith("dual-server") && name.endsWith(".jar")) return "server";
        throw new IOException("unrecognized packaged entrypoint: " + name);
    }

    private static Path sibling(Path executable, String role) {
        var opposite = role.equals("cli") ? "server" : "cli";
        var name = executable.getFileName().toString().replace("dual-" + role, "dual-" + opposite);
        var directory = executable.getParent();
        if (directory.getFileName().toString().equals("target")
                && directory.getParent().getFileName().toString().equals("dual-" + role))
            return directory.getParent().getParent().resolve("dual-" + opposite).resolve("target").resolve(name);
        return directory.resolve(name);
    }

    private static String sha(byte[] bytes) {
        try { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)); }
        catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
}

package dev.dual.runtime;

import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.NodeInstanceDocument;

import java.util.Map;

/**
 * Explains why an active node is not executable by resume.
 *
 * This is a runtime guard/projection boundary: it reads typed node state and
 * retry policy facts, then produces a stable operator message. It does not
 * mutate ledger state and does not decide workflow routing.
 */
final class NodeExecutionGuard {
    private NodeExecutionGuard() {
    }

    static NodeExecutionRejection reject(NodeInstanceDocument node, NodeDefinition definition) {
        return new NodeExecutionRejection(switch (node.status()) {
            case RUNNING -> runningMessage(node);
            case FAILED -> failedMessage(node, definition.config());
            case BLOCKED -> "node " + node.nodeDefinitionId() + " BLOCKED (revision limit), use dualctl retry or recovery abort";
            case WAITING -> "node " + node.nodeDefinitionId() + " is WAITING, not executable via resume";
            case COMPLETED -> "node " + node.nodeDefinitionId() + " already COMPLETED, should not be active";
            case CREATED, SKIPPED -> "node " + node.nodeDefinitionId() + " has illegal status: " + node.status();
            default -> "unexpected node status: " + node.status();
        });
    }

    private static String runningMessage(NodeInstanceDocument node) {
        var pid = node.result().get("running_pid");
        return "node " + node.nodeDefinitionId() + " is RUNNING (PID=" + pid + "), agent process still alive";
    }

    private static String failedMessage(NodeInstanceDocument node, Map<String, Object> config) {
        var outcome = outcomeMap(node.result());
        if (!outcome.isEmpty()) {
            var retryPolicy = text(outcome.get("retryPolicy"));
            var reason = text(outcome.get("primaryReason"));
            if ("AUTO_ALLOWED".equals(retryPolicy)) {
                var policy = RetryPolicyResolver.resolve(reason, config);
                return autoRetryLimitMessage(node, policy, reason);
            }
            if ("MANUAL_ONLY".equals(retryPolicy)) {
                return "node " + node.nodeDefinitionId() + " FAILED (" + reason + "), manual recovery or retry required";
            }
            return "node " + node.nodeDefinitionId() + " FAILED (" + reason + "), use dualctl retry after inspection";
        }
        var recoverable = firstNonNull(node.result().get("acpx_failure.recoverable"), node.result().get("recoverable"));
        if (!Boolean.TRUE.equals(recoverable)) {
            return "node " + node.nodeDefinitionId() + " FAILED (not recoverable), use dualctl retry";
        }
        var reason = failureReason(node);
        var policy = RetryPolicyResolver.resolve(reason, config);
        return autoRetryLimitMessage(node, policy, reason);
    }

    private static String autoRetryLimitMessage(NodeInstanceDocument node, RetryPolicy policy, String reason) {
        var count = node.result().getOrDefault("auto_retry_count", 0);
        var countInt = count instanceof Number n ? n.intValue() : 0;
        return "node " + node.nodeDefinitionId() + " FAILED, auto-retry limit reached ("
                + countInt + "/" + policy.maxRetries() + " for " + reason + "), use dualctl retry";
    }

    private static String failureReason(NodeInstanceDocument node) {
        var reasonValue = node.result().getOrDefault("acpx_failure.reason", "");
        if (String.valueOf(reasonValue).isBlank()) {
            reasonValue = node.result().getOrDefault("reason", "");
        }
        return reasonValue instanceof String s ? s : String.valueOf(reasonValue);
    }

    private static Object firstNonNull(Object first, Object second) {
        return first != null ? first : second;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> outcomeMap(Map<String, Object> result) {
        var value = result.get("agent_execution_outcome");
        return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    record NodeExecutionRejection(String message) {
    }
}

package dev.dual.runtime;

import dev.dual.core.workflow.*;
import dev.dual.ledger.file.*;
import dev.dual.runtime.handler.AgentRunCommitProtocol;
import dev.dual.runtime.handler.ArtifactContractValidator;
import java.util.*;
import java.io.IOException;

/** Shared inline, worker and explicit-recovery reader of R01/R02/R03. Never invokes a provider. */
public final class RecordedExecutionRecovery {
    private RecordedExecutionRecovery() {}

    public static Optional<NodeExecutionDocument> active(WorkflowFileLedger ledger, WorkstreamPaths paths) throws IOException {
        return ledger.inspect(paths, (scoped, files) -> {
            var current = scoped.loadCurrent(paths);
            if (current.status().isTerminal()) return Optional.empty();
            for (var id : current.activeNodeInstanceIds()) {
                var execution = scoped.latestNodeExecution(paths, scoped.loadNode(paths, id));
                if (execution.isPresent() && AgentRunCommitProtocol.hasPrepared(execution.get())) return execution;
            }
            return Optional.empty();
        });
    }

    public static WorkflowRuntimeResult recoverUnprepared(WorkflowFileLedger ledger, WorkstreamPaths paths,
            NodeExecutionDocument claim) throws Exception {
        if (AgentRunCommitProtocol.hasPrepared(claim)) return recover(ledger, paths, claim);
        if (!"acpx.agent_run".equals(claim.handlerType())) throw new IOException("not a native execution claim");
        try (var write = ledger.writeSession(paths, "recover interrupted preparation", claim.nodeExecutionId())) {
            var scoped = write.ledger();
            var actual = scoped.verifyExecutionClaim(paths, claim);
            if (AgentRunCommitProtocol.hasPrepared(actual)) throw new IOException("preparation was bound concurrently");
            if (AgentRunCommitProtocol.executorAlive(actual)) throw new IOException("original executor is still active");
            // R01 was never bound, so no productive native phase could acquire dispatch eligibility.
            var result = dev.dual.runtime.handler.AgentExecutionResultFacts.inputPreparationFailed(
                    "PREPARATION_INTERRUPTED", "PREPARATION_INTERRUPTED", List.of("Executor stopped before prepared input binding"));
            scoped.markAgentTaskFinished(paths, scoped.readAgentTask(paths, actual.agentTaskId()).orElseThrow(), result);
            scoped.finishNodeExecution(paths, actual, result);
            scoped.completeAndRoute(paths, scoped.loadDefinition(paths), actual.nodeInstanceId(), result.status(),
                    result.outcome(), result.outputRefs(), result.result());
            write.commit();
        }
        var current = ledger.loadCurrent(paths);
        return new WorkflowRuntimeResult(paths.workstreamId().value(), current.status(), claim.nodeDefinitionId(),
                "preparation was interrupted before external eligibility; explicit retry may prepare a new attempt");
    }

    public static WorkflowRuntimeResult recover(WorkflowFileLedger ledger, WorkstreamPaths paths,
                                                NodeExecutionDocument claim) throws Exception {
        var node = ledger.loadNode(paths, claim.nodeInstanceId());
        var current = ledger.loadCurrent(paths);
        var observation = AgentRunCommitProtocol.observe(paths, claim);
        if (observation == AgentRunCommitProtocol.Observation.COMPLETED) {
            AgentExecutionCompletion.commit(ledger, paths, claim, null);
        } else if (AgentRunCommitProtocol.executorOwnsInvocation(paths, claim)) {
            return new WorkflowRuntimeResult(paths.workstreamId().value(), current.status(), node.nodeDefinitionId(),
                    "execution is still owned by its original live executor");
        } else if (observation == AgentRunCommitProtocol.Observation.OUTCOME_RECORDED) {
            var result = ArtifactContractValidator.completeRecorded(ledger, paths.workspaceRoot(), paths, claim);
            result = AgentRunCommitProtocol.complete(paths.workspaceRoot(), ledger, paths, claim, result);
            AgentExecutionCompletion.commit(ledger, paths, claim, result);
        } else {
            var unknown = observation == AgentRunCommitProtocol.Observation.EXTERNAL_UNKNOWN;
            var reason = unknown ? "EXTERNAL_RESULT_UNKNOWN" : "PREPARATION_INTERRUPTED";
            var facts = Map.<String, Object>of("reason", reason, "external_effect", unknown ? "UNKNOWN" : "NOT_STARTED",
                    "provider_invocation", unknown ? "UNKNOWN" : "NOT_STARTED", "automatic_retry", false);
            var result = new NodeResult(reason, NodeStatus.FAILED, List.of(), facts,
                    unknown ? "External result is unknown; stop evidence and explicit adjudication are required."
                            : "Preparation stopped before external intent; a new attempt may prepare again.");
            try (var write = ledger.writeSession(paths, "classify stopped execution", claim.nodeExecutionId())) {
                var scoped = write.ledger();
                scoped.verifyExecutionClaim(paths, claim);
                // Repeat executor check in the accepting write session; a live owner cannot be silently superseded.
                if (AgentRunCommitProtocol.executorOwnsInvocation(paths, claim)) throw new IOException("executor became active");
                scoped.markAgentTaskFinished(paths, scoped.readAgentTask(paths, claim.agentTaskId()).orElseThrow(), result);
                scoped.finishNodeExecution(paths, claim, result);
                var nodeFacts = new LinkedHashMap<String, Object>(facts);
                nodeFacts.put("prepared_run", claim.result().get("prepared_run"));
                scoped.completeAndRoute(paths, scoped.loadDefinition(paths), node.nodeInstanceId(), result.status(),
                        result.outcome(), result.outputRefs(), nodeFacts);
                write.commit();
            }
        }
        var next = ledger.loadCurrent(paths);
        var active = next.activeNodeInstanceIds().isEmpty() ? "" : ledger.loadNode(paths, next.activeNodeInstanceIds().getFirst()).nodeDefinitionId();
        return new WorkflowRuntimeResult(paths.workstreamId().value(), next.status(), active,
                "recovered recorded execution state without dispatching a provider");
    }
}

package dev.dual.runtime;

public record RetryPolicy(
        int maxRetries,
        long baseDelayMs,
        double backoffMultiplier
) {
    public long delayForAttempt(int attempt) {
        if (attempt <= 0 || baseDelayMs <= 0) {
            return 0;
        }
        return (long) (baseDelayMs * Math.pow(backoffMultiplier, attempt - 1));
    }
}

package dev.dual.runtime;

import java.util.Map;

/**
 * Resolves retry policy from the default failure catalog plus node-level
 * overrides.
 *
 * Keeping this outside WorkflowRuntime prevents retry limits from drifting
 * between auto-retry execution and operator-facing rejection messages.
 */
final class RetryPolicyResolver {
    private RetryPolicyResolver() {
    }

    static RetryPolicy resolve(String failureReason, Map<String, Object> config) {
        var defaultPolicy = RetryStrategies.forReason(failureReason);
        var maxRetries = config.get("retry.max_retries");
        var baseDelay = config.get("retry.base_delay_ms");
        var multiplier = config.get("retry.backoff_multiplier");
        if (maxRetries == null && baseDelay == null && multiplier == null) {
            return defaultPolicy;
        }
        return new RetryPolicy(
                maxRetries instanceof Number n ? n.intValue() : defaultPolicy.maxRetries(),
                baseDelay instanceof Number n ? n.longValue() : defaultPolicy.baseDelayMs(),
                multiplier instanceof Number n ? n.doubleValue() : defaultPolicy.backoffMultiplier()
        );
    }
}

package dev.dual.runtime;

import java.util.Map;

public final class RetryStrategies {
    private static final RetryPolicy DEFAULT_POLICY = new RetryPolicy(3, 1000, 1.0);

    private static final Map<String, RetryPolicy> POLICIES = Map.of(
            "RECOVERABLE_RATE_LIMIT", new RetryPolicy(5, 3000, 2.0),
            "RECOVERABLE_SESSION_MISSING", new RetryPolicy(3, 2000, 1.5),
            "RECOVERABLE_AGENT_RECONNECT", new RetryPolicy(3, 2000, 1.5),
            "RECOVERABLE_AGENT_AUTH_FAILED", new RetryPolicy(0, 0, 1.0),
            "RECOVERABLE_PROVIDER_CONNECTION_FAILED", new RetryPolicy(3, 3000, 2.0),
            "RECOVERABLE_CONTEXT_WINDOW", new RetryPolicy(2, 1000, 1.0),
            "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED", new RetryPolicy(2, 2000, 1.5)
    );

    public static RetryPolicy forReason(String failureReason) {
        return POLICIES.getOrDefault(failureReason, DEFAULT_POLICY);
    }

    private RetryStrategies() {}
}

package dev.dual.runtime;

import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;

/**
 * Performs stale execution closure before moving the node instance to recovery.
 */
public final class StaleRunningRecovery {
    private final WorkflowFileLedger ledger;

    public StaleRunningRecovery(WorkflowFileLedger ledger) {
        this.ledger = java.util.Objects.requireNonNull(ledger);
    }

    public Result recover(WorkstreamPaths paths, String note) throws Exception {
        if (recoverRecorded(paths)) return new Result(0, 0);
        recoverUnpreparedOrLocal(paths, note);
        return new Result(0, 0);
    }

    public Result terminateAndRecover(WorkstreamPaths paths, String note) throws Exception {
        // Exact native session stop is a separate typed operation. Never kill a process selected from mutable run.json.
        return recover(paths, note);
    }

    private void recoverUnpreparedOrLocal(WorkstreamPaths paths, String note) throws Exception {
        var execution = ledger.inspect(paths, (scoped, files) -> {
            var current = scoped.loadCurrent(paths);
            if (current.activeNodeInstanceIds().size() != 1) throw new java.io.IOException("recovery requires one active occurrence");
            return scoped.latestNodeExecution(paths, scoped.loadNode(paths, current.activeNodeInstanceIds().getFirst()));
        });
        if (execution.isPresent() && "acpx.agent_run".equals(execution.get().handlerType())) {
            RecordedExecutionRecovery.recoverUnprepared(ledger, paths, execution.get());
        } else {
            ledger.recoverStaleRunningNode(paths, note);
        }
    }

    private boolean recoverRecorded(WorkstreamPaths paths) throws Exception {
        try (var local = ledger.writeSession(paths, "explicit local recovery", java.util.UUID.randomUUID().toString())) { local.commit(); }
        var recorded = RecordedExecutionRecovery.active(ledger, paths);
        if (recorded.isEmpty()) return false;
        if (recorded.get().status() != dev.dual.ledger.file.NodeExecutionStatus.RUNNING)
            throw new IllegalStateException("recorded execution already classified; use its recovery decision, not stale reclassification");
        if (dev.dual.runtime.handler.AgentRunCommitProtocol.executorOwnsInvocation(paths, recorded.get()))
            throw new IllegalStateException("original executor still owns the invocation");
        RecordedExecutionRecovery.recover(ledger, paths, recorded.get());
        return true;
    }

    public record Result(int terminatedProcessTrees, int reconciledRuns) {
    }

}

