package dev.dual.runtime;

import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.NodeExecutionStatus;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowExecutionStatus;
import dev.dual.ledger.file.WorkflowExecutionDocument;
import dev.dual.ledger.file.WorkflowCurrentDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import dev.dual.runtime.handler.ArtifactContractValidator;
import dev.dual.runtime.handler.ContractEventTypes;
import dev.dual.runtime.handler.DecisionHandler;
import dev.dual.runtime.handler.GateHandler;
import dev.dual.runtime.handler.HandlerRegistry;
import dev.dual.runtime.handler.TaskHandler;

import java.util.ArrayList;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Drives one workflow instance forward from the authoritative ledger state.
 *
 * Runtime owns transition execution and runtime facts only: it creates workflow
 * and node execution records, invokes handlers, validates artifact contracts,
 * and asks the ledger to route completed nodes. It must not infer product goal
 * satisfaction from prose, and it must guard terminal workflows before creating
 * any new execution side effects.
 */
public final class WorkflowRuntime {
    private final WorkflowFileLedger ledger;
    private final HandlerRegistry handlers;
    private final ArtifactContractValidator artifactContractValidator;
    private final StaleRunningRecovery staleRunningRecovery;
    private final AgentTaskDispatchMode dispatchMode;

    public WorkflowRuntime(WorkflowFileLedger ledger, HandlerRegistry handlers) {
        this(ledger, handlers, AgentTaskDispatchMode.INLINE);
    }

    public WorkflowRuntime(WorkflowFileLedger ledger, HandlerRegistry handlers, AgentTaskDispatchMode dispatchMode) {
        if (ledger == null) {
            throw new IllegalArgumentException("ledger is required");
        }
        if (handlers == null) {
            throw new IllegalArgumentException("handlers is required");
        }
        this.ledger = ledger;
        this.handlers = handlers;
        this.dispatchMode = dispatchMode == null ? AgentTaskDispatchMode.INLINE : dispatchMode;
        this.artifactContractValidator = new ArtifactContractValidator(ledger);
        this.staleRunningRecovery = new StaleRunningRecovery(ledger);
    }

    /**
     * Advances the current workflow until it reaches a gate, recovery boundary,
     * terminal state, or the current active-node snapshot is exhausted.
     *
     * Key steps:
     * 1. Load definition/current from the ledger.
     * 2. Refuse terminal workflows before creating a workflow execution.
     * 3. Create a workflow execution and per-node execution/task records.
     * 4. Execute handlers and validate structured artifacts.
     * 5. Finish the workflow execution with a typed runtime status.
     */
    public WorkflowRuntimeResult resume(WorkflowCommand command) throws Exception {
        var paths = new WorkstreamPaths(command.workspaceRoot(), new DualId(command.workstreamId()));
        // Resume is an explicit writer entrance: fixed local pending bytes may finish before any routing/dispatch.
        try (var local = ledger.writeSession(paths, "resume local recovery", java.util.UUID.randomUUID().toString())) {
            local.commit();
        }
        var definition = ledger.loadDefinition(paths);
        var current = ledger.loadCurrent(paths);

        // Terminal observation is allowed elsewhere, but resume must be side-effect free.
        if (current.status().isTerminal()) {
            return new WorkflowRuntimeResult(
                    command.workstreamId(),
                    current.status(),
                    "",
                    "workflow is terminal: " + current.status()
            );
        }
        // Reconcile any in-flight agent run for the active node whose transport
        // never returned before this resume creates new execution side effects.
        // If a run is reconciled, stop at recovery instead of creating another
        // attempt for the same node.
        var reconciled = reconcileActiveNodeAttempts(command, paths, definition, current);
        if (reconciled != null) {
            return reconciled;
        }

        var workflowExecution = ledger.startWorkflowExecution(paths, current, "resume");
        var nodeExecutionIds = new ArrayList<String>();
        var workflowExecutionFinished = false;
        try {
            var outcome = resumeWithinExecution(command, paths, definition, current, workflowExecution, nodeExecutionIds);
            var finalResult = outcome.result();
            finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, outcome.executionStatus(), finalResult.message());
            workflowExecutionFinished = true;
            return finalResult;
        } catch (Exception failure) {
            if (!workflowExecutionFinished) {
                finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, WorkflowExecutionStatus.FAILED, failure.getMessage());
            }
            throw failure;
        }
    }

    private ResumeOutcome resumeWithinExecution(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds
    ) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return stopped(new WorkflowRuntimeResult(command.workstreamId(), current.status(), "", "workflow has no active node"));
        }
        if (current.status() == WorkflowStatus.WAITING_FOR_RECOVERY) {
            var recoveryRejection = rejectRecoveryOrAutoRetry(command, paths, definition, current);
            if (recoveryRejection != null) {
                return stopped(recoveryRejection);
            }
            current = ledger.loadCurrent(paths);
        }
        var result = executeActiveSnapshot(command, paths, definition, current, workflowExecution, nodeExecutionIds);
        return new ResumeOutcome(result, workflowExecutionStatus(result.status()));
    }

    private WorkflowRuntimeResult reconcileActiveNodeAttempts(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return null;
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            var node = ledger.loadNode(paths, activeNodeId);
            var execution = ledger.latestNodeExecution(paths, node);
            if (execution.isPresent() && dev.dual.runtime.handler.AgentRunCommitProtocol.hasPrepared(execution.get())) {
                if (execution.get().status() != dev.dual.ledger.file.NodeExecutionStatus.RUNNING) continue;
                return RecordedExecutionRecovery.recover(ledger, paths, execution.get());
            }
            if (execution.isPresent() && execution.get().status() == dev.dual.ledger.file.NodeExecutionStatus.RUNNING
                    && "acpx.agent_run".equals(execution.get().handlerType())
                    && !dev.dual.runtime.handler.AgentRunCommitProtocol.executorAlive(execution.get()))
                return RecordedExecutionRecovery.recoverUnprepared(ledger, paths, execution.get());
        }
        return null;
    }

    private WorkflowRuntimeResult rejectRecoveryOrAutoRetry(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        var nodeDoc = ledger.loadNode(paths, current.activeNodeInstanceIds().get(0));
        var nodeDef = definition.node(nodeDoc.nodeDefinitionId());
        if (nodeDoc.status() == NodeStatus.FAILED && attemptAutoRetry(paths, nodeDoc, nodeDef)) {
            return null;
        }
        return rejectionResult(command, current, nodeDoc, nodeDef);
    }

    private WorkflowRuntimeResult executeActiveSnapshot(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds
    ) throws Exception {
        var activeSnapshot = new ArrayList<>(current.activeNodeInstanceIds());
        WorkflowRuntimeResult lastResult = null;

        for (var activeNodeId : activeSnapshot) {
            current = ledger.loadCurrent(paths);
            if (current.activeNodeInstanceIds().isEmpty()) {
                break;
            }
            if (!current.activeNodeInstanceIds().contains(activeNodeId)) {
                continue;
            }
            lastResult = executeActiveNode(command, paths, definition, workflowExecution, nodeExecutionIds, activeNodeId);
        }
        return lastResult != null
                ? lastResult
                : new WorkflowRuntimeResult(command.workstreamId(), current.status(), "", "workflow has no active node");
    }

    private WorkflowRuntimeResult executeActiveNode(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            String activeNodeId
    ) throws Exception {
        var nodeDoc = ledger.loadNode(paths, activeNodeId);
        var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());

        if (nodeDefinition.kind() == NodeKind.GATE) {
            var node = ledger.loadCoreNode(paths, activeNodeId);
            handlers.gate(nodeDefinition.handlerType())
                    .openOrInspect(new GateHandler.GateContext(
                            command.workspaceRoot(), command.workstreamId(), nodeDefinition, node,
                            sourceOutcome(paths, activeNodeId), ledger));
            return new WorkflowRuntimeResult(command.workstreamId(), WorkflowStatus.WAITING_FOR_HUMAN, nodeDefinition.id(), "waiting for human review");
        }

        var guardResult = resolveNodeForExecution(paths, nodeDoc);
        if (guardResult == null) {
            var refreshedCurrent = ledger.loadCurrent(paths);
            var refreshedNode = ledger.loadNode(paths, activeNodeId);
            var refreshedDefinition = definition.node(refreshedNode.nodeDefinitionId());
            return rejectionResult(command, refreshedCurrent, refreshedNode, refreshedDefinition);
        }

        if (dispatchMode == AgentTaskDispatchMode.WORKER) {
            return enqueueAgentTask(command, paths, workflowExecution, nodeDoc, nodeDefinition);
        }

        var result = executeAndRecordNode(command, paths, workflowExecution, nodeExecutionIds, nodeDoc, nodeDefinition);
        var next = ledger.loadCurrent(paths);
        openWaitingGates(command, paths, definition, next);
        var active = activeNodeDefinitionId(paths, next);
        var message = result.status() == NodeStatus.COMPLETED ? "resumed workflow" : "workflow stopped at " + result.status();
        return new WorkflowRuntimeResult(command.workstreamId(), next.status(), active, message);
    }

    private WorkflowRuntimeResult enqueueAgentTask(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            NodeInstanceDocument nodeDoc,
            NodeDefinition nodeDefinition
    ) throws Exception {
        try (var mutation = ledger.writeSession(paths, "enqueue node", nodeDoc.nodeInstanceId())) {
            var scoped = mutation.ledger();
            var currentNode = scoped.loadNode(paths, nodeDoc.nodeInstanceId());
            var agentTask = scoped.createAgentTask(paths, workflowExecution.workflowExecutionId(), nodeDefinition, currentNode);
            scoped.markQueuedForAgentTask(paths, currentNode.nodeInstanceId(), agentTask.agentTaskId());
            mutation.commit();
        }
        return new WorkflowRuntimeResult(command.workstreamId(), WorkflowStatus.RUNNING, nodeDefinition.id(), "agent task queued");
    }

    private WorkflowRuntimeResult rejectionResult(
            WorkflowCommand command,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node,
            NodeDefinition definition
    ) {
        var rejection = NodeExecutionGuard.reject(node, definition);
        return new WorkflowRuntimeResult(command.workstreamId(), current.status(), node.nodeDefinitionId(), rejection.message());
    }

    private String activeNodeDefinitionId(WorkstreamPaths paths, WorkflowCurrentDocument current) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return "";
        }
        return ledger.loadNode(paths, current.activeNodeInstanceIds().get(0)).nodeDefinitionId();
    }

    private static ResumeOutcome stopped(WorkflowRuntimeResult result) {
        return new ResumeOutcome(result, WorkflowExecutionStatus.STOPPED);
    }

    private record ResumeOutcome(WorkflowRuntimeResult result, WorkflowExecutionStatus executionStatus) {
    }

    private NodeResult executeAndRecordNode(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            NodeInstanceDocument nodeDoc,
            NodeDefinition nodeDefinition
    ) throws Exception {
        long pid = ProcessHandle.current().pid();
        dev.dual.ledger.file.AgentTaskDocument agentTask;
        dev.dual.ledger.file.NodeExecutionDocument nodeExecution;
        try (var mutation = ledger.writeSession(paths, "claim inline node", nodeDoc.nodeInstanceId())) {
            var scoped = mutation.ledger();
            var currentNode = scoped.loadNode(paths, nodeDoc.nodeInstanceId());
            agentTask = scoped.createAgentTask(paths, workflowExecution.workflowExecutionId(), nodeDefinition, currentNode);
            nodeExecution = scoped.startNodeExecution(paths, workflowExecution.workflowExecutionId(), currentNode, agentTask, pid);
            agentTask = scoped.markAgentTaskRunning(paths, agentTask, nodeExecution.nodeExecutionId());
            scoped.markRunning(paths, currentNode.nodeInstanceId(), pid);
            mutation.commit();
        }
        nodeExecutionIds.add(nodeExecution.nodeExecutionId());

        try {
        var node = ledger.loadCoreNode(paths, nodeDoc.nodeInstanceId());
        if (nodeDefinition.kind() == NodeKind.DECISION
                || handlers.task(nodeDefinition.handlerType()).localLedgerMutation()) {
            try (var mutation = ledger.writeSession(paths, "local node result and routing", nodeExecution.nodeExecutionId())) {
                var scoped = mutation.ledger();
                var result = executeNode(command, nodeDefinition, scoped.loadCoreNode(paths, node.nodeInstanceId()), scoped);
                result = new ArtifactContractValidator(scoped).validateAndFinalize(command.workspaceRoot(), command.workstreamId(),
                        node.nodeInstanceId(), nodeDefinition, node.inputRefs(), result);
                scoped.markAgentTaskFinished(paths, agentTask, result);
                scoped.finishNodeExecution(paths, nodeExecution, result);
                WorkflowRuntime.emitDomainEvents(scoped, paths, nodeDefinition.id(), nodeDefinition.handlerType(),
                        node.nodeInstanceId(), result);
                scoped.completeAndRoute(paths, scoped.loadDefinition(paths), node.nodeInstanceId(), result.status(),
                        result.outcome(), result.outputRefs(), result.result());
                mutation.commit();
                return result;
            }
        }
            var result = dev.dual.runtime.handler.EvidenceCollection.execute(ledger, command.workspaceRoot(),
                    command.workstreamId(), nodeDoc, () -> executeNode(command, nodeDefinition, node, ledger));
            result = artifactContractValidator.validateAndFinalize(
                    command.workspaceRoot(),
                    command.workstreamId(),
                    node.nodeInstanceId(),
                    nodeDefinition,
                    node.inputRefs(),
                    result
            );
            result = dev.dual.runtime.handler.AgentRunCommitProtocol.complete(command.workspaceRoot(), ledger, paths,
                    nodeExecution, result);
            if (result.result().containsKey("completion_ref"))
                return AgentExecutionCompletion.commit(ledger, paths, nodeExecution, result);
            try (var mutation = ledger.writeSession(paths, "complete inline node", nodeExecution.nodeExecutionId())) {
                var scoped = mutation.ledger();
                scoped.markAgentTaskFinished(paths, agentTask, result);
                scoped.finishNodeExecution(paths, nodeExecution, result);
                emitDomainEvents(scoped, paths, nodeDefinition.id(), nodeDefinition.handlerType(), nodeDoc.nodeInstanceId(), result);
                scoped.completeAndRoute(paths, scoped.loadDefinition(paths), nodeDoc.nodeInstanceId(), result.status(),
                        result.outcome(), result.outputRefs(), result.result());
                mutation.commit();
            }
            return result;
        } catch (Exception nodeFailure) {
            // A pending local completion is replayed as fixed bytes. Do not replace it with an exception outcome.
            try {
                if ("acpx.agent_run".equals(nodeDefinition.handlerType()))
                    dev.dual.runtime.handler.AgentRunCommitProtocol.releaseExecutor(ledger, paths, nodeExecution);
                else AgentExecutionCompletion.recordHandlerFailure(ledger, paths, nodeExecution, nodeFailure);
            }
            catch (Exception releaseFailure) { nodeFailure.addSuppressed(releaseFailure); }
            throw nodeFailure;
        }
    }

    private NodeResult executeNode(WorkflowCommand command, NodeDefinition nodeDefinition, dev.dual.core.workflow.NodeInstance node, WorkflowFileLedger executionLedger) throws Exception {
        return switch (nodeDefinition.kind()) {
            case TASK -> handlers.task(nodeDefinition.handlerType())
                    .execute(new TaskHandler.TaskContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node, executionLedger));
            case DECISION -> handlers.decision(nodeDefinition.handlerType())
                    .evaluate(new DecisionHandler.DecisionContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node, executionLedger));
            case GATE -> throw new IllegalStateException("gate nodes are handled before routing");
        };
    }

    private void finishWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            WorkflowExecutionStatus status,
            String stopReason
    ) throws Exception {
        ledger.finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, status, stopReason);
    }

    private static WorkflowExecutionStatus workflowExecutionStatus(WorkflowStatus status) {
        return switch (status) {
            case CREATED -> WorkflowExecutionStatus.CREATED;
            case RUNNING -> WorkflowExecutionStatus.STOPPED;
            case WAITING_FOR_HUMAN -> WorkflowExecutionStatus.WAITING_FOR_HUMAN;
            case WAITING_FOR_RECOVERY -> WorkflowExecutionStatus.WAITING_FOR_RECOVERY;
            case BLOCKED -> WorkflowExecutionStatus.BLOCKED;
            case COMPLETED -> WorkflowExecutionStatus.ENDED;
            case FAILED -> WorkflowExecutionStatus.FAILED;
        };
    }

    private void openWaitingGates(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN) {
            return;
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            var nodeDoc = ledger.loadNode(paths, activeNodeId);
            if (nodeDoc.kind() != NodeKind.GATE) {
                continue;
            }
            var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());
            var node = ledger.loadCoreNode(paths, activeNodeId);
            handlers.gate(nodeDefinition.handlerType())
                    .openOrInspect(new GateHandler.GateContext(
                            command.workspaceRoot(), command.workstreamId(), nodeDefinition, node,
                            sourceOutcome(paths, activeNodeId), ledger));
        }
    }

    private String sourceOutcome(WorkstreamPaths paths, String nodeInstanceId) throws Exception {
        var value = ledger.loadOpenGateForNode(paths, nodeInstanceId).result().get("source_outcome");
        if (value == null || String.valueOf(value).isBlank()) {
            throw new IllegalStateException("open gate is missing source_outcome: " + nodeInstanceId);
        }
        return String.valueOf(value);
    }

    public static void emitDomainEvents(WorkflowFileLedger ledger, WorkstreamPaths paths, String nodeDefinitionId,
                                 String handlerType, String nodeInstanceId,
                                 NodeResult result) throws java.io.IOException {
        if (result.status() != NodeStatus.COMPLETED) {
            return;
        }
        String eventId = "domain-" + nodeInstanceId;

        var commonPayload = new LinkedHashMap<String, Object>();
        commonPayload.put("handler_type", handlerType);
        commonPayload.put("node_id", nodeDefinitionId);
        commonPayload.put("node_instance_id", nodeInstanceId);

        switch (handlerType) {
            case "contract.compile" -> {
                commonPayload.put("contract_id", result.result().getOrDefault("contract_id", ""));
                commonPayload.put("contract_status", result.result().getOrDefault("contract_status", ""));
                ledger.appendEvent(paths, eventId,
                        ContractEventTypes.COMPILATION_COMPLETED, commonPayload);
            }
            case "acceptance.failure_classify" -> {
                commonPayload.put("category", result.result().getOrDefault("category", ""));
                commonPayload.put("matched_rule", result.result().getOrDefault("matched_rule", ""));
                commonPayload.put("review_decision", result.result().getOrDefault("review_decision", ""));
                ledger.appendEvent(paths, eventId,
                        ContractEventTypes.FAILURE_CLASSIFIED, commonPayload);
            }
            default -> { /* no domain event for this handler type */ }
        }
    }

    private boolean attemptAutoRetry(WorkstreamPaths paths, NodeInstanceDocument node, NodeDefinition nodeDef) throws Exception {
        var outcome = outcomeMap(node.result());
        if (!outcome.isEmpty()) {
            var retryPolicy = text(outcome.get("retryPolicy"));
            if (!"AUTO_ALLOWED".equals(retryPolicy)) {
                return false;
            }
            var policy = RetryPolicyResolver.resolve(text(outcome.get("primaryReason")), nodeDef.config());
            return autoRetry(paths, node, policy);
        }
        var recoverable = node.result().get("acpx_failure.recoverable");
        if (!Boolean.TRUE.equals(recoverable)) {
            return false;
        }
        var reasonValue = node.result().getOrDefault("acpx_failure.reason", "");
        var reason = reasonValue instanceof String s ? s : String.valueOf(reasonValue);
        var policy = RetryPolicyResolver.resolve(reason, nodeDef.config());
        return autoRetry(paths, node, policy);
    }

    private boolean autoRetry(WorkstreamPaths paths, NodeInstanceDocument node, RetryPolicy policy) throws Exception {
        var countValue = node.result().getOrDefault("auto_retry_count", 0);
        var count = (countValue instanceof Number n) ? n.intValue() : 0;
        if (count >= policy.maxRetries()) {
            return false;
        }

        var delay = policy.delayForAttempt(count + 1);
        ledger.autoRetryNode(paths, node.nodeInstanceId(), delay);
        if (delay > 0) {
            Thread.sleep(delay);
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> outcomeMap(Map<String, Object> result) {
        var value = result.get("agent_execution_outcome");
        return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private Boolean resolveNodeForExecution(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        return switch (node.status()) {
            case READY -> true;
            case RUNNING -> resolveRunningNode(paths, node);
            case BLOCKED, WAITING, COMPLETED, CREATED, SKIPPED, FAILED -> null;
        };
    }

    private Boolean resolveRunningNode(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        if (hasActiveQueuedAgentTask(paths, node)) {
            return null;
        }
        var latestExecution = ledger.latestNodeExecution(paths, node);
        if (latestExecution.isPresent()) {
            var execution = latestExecution.get();
            if (execution.status() == NodeExecutionStatus.RUNNING) {
                var pid = execution.pid() == null ? 0L : execution.pid();
                var alive = pid > 0 && ProcessHandle.of(pid).map(ProcessHandle::isAlive).orElse(false);
                if (alive) {
                    return null;
                }
                ledger.markNodeExecutionStale(paths, execution, "detected by runtime resume");
                recoverStaleRunningNode(paths, node, pid <= 0 ? "" : pid);
                return null;
            }
        }
        var pidValue = node.result().get("running_pid");
        if (pidValue instanceof Number number) {
            var pid = number.longValue();
            var alive = ProcessHandle.of(pid).map(ProcessHandle::isAlive).orElse(false);
            if (alive) {
                return null;
            }
            recoverStaleRunningNode(paths, node, pid);
            return null;
        }
        recoverStaleRunningNode(paths, node, "");
        return null;
    }

    private boolean hasActiveQueuedAgentTask(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        var taskId = node.result().get("queued_agent_task_id");
        if (taskId == null || String.valueOf(taskId).isBlank()) {
            return false;
        }
        return ledger.readAgentTask(paths, String.valueOf(taskId))
                .map(task -> task.status() == dev.dual.ledger.file.AgentTaskStatus.QUEUED
                        || task.status() == dev.dual.ledger.file.AgentTaskStatus.RUNNING)
                .orElse(false);
    }

    private void recoverStaleRunningNode(WorkstreamPaths paths, NodeInstanceDocument node, Object pid) throws Exception {
        // Close any in-flight agent run.json (transport never returned / process killed) to a
        // typed terminal executionAttempt+executionOutcome before the node/workflow transition.
        ledger.appendEvent(paths, "stale-running-" + node.nodeInstanceId() + "-" + System.currentTimeMillis(),
                "node_stale_running_detected", Map.of(
                        "node", node.nodeDefinitionId(),
                        "node_instance_id", node.nodeInstanceId(),
                        "previous_running_pid", pid,
                        "action", "move_to_recovery"
                ));
        staleRunningRecovery.recover(paths, "detected by runtime resume");
    }

}

package dev.dual.runtime;

import dev.dual.core.workflow.WorkflowStatus;

public record WorkflowRuntimeResult(
        String workstreamId,
        WorkflowStatus status,
        String activeNode,
        String message
) {
    public WorkflowRuntimeResult {
        if (workstreamId == null || workstreamId.isBlank()) {
            throw new IllegalArgumentException("workstreamId is required");
        }
        if (status == null) {
            throw new IllegalArgumentException("status is required");
        }
        activeNode = activeNode == null ? "" : activeNode;
        message = message == null ? "" : message;
    }
}

package dev.dual.runtime.delivery;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.DeliveryCandidateWriter;
import dev.dual.ledger.file.GateDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/** Resolves the final accepted candidate from authoritative ledger history. */
public final class AcceptedDeliveryCandidateResolver {
    private static final Pattern WORKFLOW_EVENT_ID = Pattern.compile("evt-(\\d{6,})");
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private final ObjectMapper objectMapper;
    private final WorkflowFileLedger ledger;
    private final DeliveryCandidateWriter candidateWriter;

    public AcceptedDeliveryCandidateResolver(WorkflowFileLedger ledger) {
        this(new ObjectMapper().findAndRegisterModules(), ledger, new DeliveryCandidateWriter());
    }

    AcceptedDeliveryCandidateResolver(ObjectMapper objectMapper, WorkflowFileLedger ledger, DeliveryCandidateWriter candidateWriter) {
        this.objectMapper = objectMapper;
        this.ledger = ledger;
        this.candidateWriter = candidateWriter;
    }

    public Accepted resolve(WorkstreamPaths paths) throws IOException {
        return ledger.inspect(paths, (scoped, files) -> new AcceptedDeliveryCandidateResolver(objectMapper, scoped, candidateWriter).resolveSnapshot(paths));
    }

    private Accepted resolveSnapshot(WorkstreamPaths paths) throws IOException {
        var occurrence = lastAcceptanceOccurrence(paths);
        var node = ledger.loadNode(paths, occurrence.nodeInstanceId());
        if (!"gate.human_acceptance".equals(node.nodeDefinitionId()) || node.status() != NodeStatus.COMPLETED) {
            throw new IOException("final acceptance node is not completed");
        }
        var gatePath = paths.gateJson(occurrence.gateId());
        if (!Files.isRegularFile(gatePath)) throw new IOException("final acceptance gate document is missing");
        var gate = objectMapper.readValue(gatePath.toFile(), GateDocument.class);
        if (!gate.nodeInstanceId().equals(node.nodeInstanceId()) || !"resolved".equals(gate.status())) {
            throw new IOException("final acceptance gate lineage or status is invalid");
        }
        var action = text(gate.result().get("human_action"));
        if (!"approve".equals(action) && !"approved".equals(action)) {
            throw new IOException("final acceptance occurrence was not approved: " + action);
        }
        var gateRefs = textList(gate.result().get("subject_input_refs"));
        if (!gateRefs.equals(node.inputRefs())) {
            throw new IOException("final acceptance gate subject refs do not match node input refs");
        }
        var candidateRefs = gateRefs.stream().filter(AcceptedDeliveryCandidateResolver::candidateRef).toList();
        if (candidateRefs.isEmpty()) {
            throw new MissingBindingException("final acceptance gate does not bind a delivery candidate");
        }
        if (candidateRefs.size() != 1) {
            throw new IOException("final acceptance gate must bind exactly one delivery candidate");
        }
        var candidateRef = candidateRefs.get(0);
        var candidatePath = resolveInsideWorkspace(paths, candidateRef);
        var occurrenceDir = candidatePath.getParent();
        if (occurrenceDir == null) throw new IOException("delivery candidate occurrence directory is missing");
        var published = candidateWriter.existing(paths, occurrenceDir.getFileName().toString());
        if (published == null || !published.path().toAbsolutePath().normalize().equals(candidatePath)) {
            throw new IOException("final acceptance candidate ref does not identify the published candidate");
        }
        var candidate = published.document();
        if (!candidate.workstreamId().equals(paths.workstreamId().value())
                || !candidate.iterationId().equals(node.iterationId())) {
            throw new IOException("delivery candidate workstream or iteration lineage does not match acceptance");
        }
        var producer = ledger.loadNode(paths, candidate.producerNodeInstanceId());
        if (!"delivery.prepare_pr".equals(producer.nodeDefinitionId())
                || producer.status() != NodeStatus.COMPLETED
                || !producer.iterationId().equals(candidate.iterationId())
                || !producer.outputRefs().contains(candidateRef)) {
            throw new IOException("delivery candidate producer lineage is invalid");
        }
        return new Accepted(candidateRef, published.sha256(), candidate, gate, node, producer);
    }

    private Occurrence lastAcceptanceOccurrence(WorkstreamPaths paths) throws IOException {
        if (!Files.isRegularFile(paths.eventsJsonl())) throw new IOException("workflow event history is missing");
        var occurrences = new ArrayList<Occurrence>();
        long previousWorkflowSequence = -1;
        for (var line : Files.readAllLines(paths.eventsJsonl(), StandardCharsets.UTF_8)) {
            if (line.isBlank()) continue;
            Map<String, Object> event;
            try {
                event = objectMapper.readValue(line, MAP_TYPE);
            } catch (Exception failure) {
                throw new IOException("workflow event history contains invalid JSON", failure);
            }
            var eventId = text(event.get("event_id"));
            var workflowEvent = WORKFLOW_EVENT_ID.matcher(eventId);
            if (!workflowEvent.matches()) {
                if ("node_routed".equals(text(event.get("event_type")))) {
                    throw new IOException("routing event does not have a workflow event id");
                }
                continue;
            }
            var workflowSequence = Long.parseLong(workflowEvent.group(1));
            if (workflowSequence <= previousWorkflowSequence) {
                throw new IOException("workflow event history is not strictly ordered");
            }
            previousWorkflowSequence = workflowSequence;
            if (!"node_routed".equals(text(event.get("event_type")))) continue;
            var payload = map(event.get("payload"));
            if (!"gate.human_acceptance".equals(text(payload.get("to")))) continue;
            var gateId = text(payload.get("gate_id"));
            var nodeInstanceId = text(payload.get("node_instance_id"));
            if (gateId.isBlank() || nodeInstanceId.isBlank()) {
                throw new IOException("acceptance routing event is missing gate lineage");
            }
            occurrences.add(new Occurrence(eventId, gateId, nodeInstanceId));
        }
        if (occurrences.isEmpty()) throw new MissingBindingException("final acceptance occurrence is missing");
        return occurrences.get(occurrences.size() - 1);
    }

    private static boolean candidateRef(String ref) {
        return ref != null && ref.matches(
                "\\.agent/workstreams/[^/]+/delivery/candidates/[^/]+/candidate-[0-9a-f]{64}\\.json"
        );
    }

    private static java.nio.file.Path resolveInsideWorkspace(WorkstreamPaths paths, String ref) throws IOException {
        var root = paths.workspaceRoot().toAbsolutePath().normalize();
        var resolved = root.resolve(ref).normalize();
        if (!resolved.startsWith(root) || !Files.isRegularFile(resolved)) {
            throw new IOException("delivery candidate ref is missing or outside workspace: " + ref);
        }
        return resolved;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object value) {
        return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
    }

    private static List<String> textList(Object value) {
        return value instanceof List<?> list ? list.stream().map(String::valueOf).toList() : List.of();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    public record Accepted(
            String candidateRef,
            String candidateSha256,
            dev.dual.ledger.file.DeliveryCandidateDocument candidate,
            GateDocument gate,
            NodeInstanceDocument gateNode,
            NodeInstanceDocument producerNode
    ) {
    }

    private record Occurrence(String eventId, String gateId, String nodeInstanceId) {
    }

    public static final class MissingBindingException extends IOException {
        public MissingBindingException(String message) {
            super(message);
        }
    }
}

package dev.dual.runtime.delivery;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.adapter.git.GitPatchMergeService;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.DeliveryCandidateWriter;
import dev.dual.ledger.file.DeliveryMergePlan;
import dev.dual.ledger.file.DeliveryMergePlanWriter;
import dev.dual.ledger.file.DeliveryMergeStatus;
import dev.dual.ledger.file.LockOwner;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamDocument;
import dev.dual.ledger.file.WorkstreamLock;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.LinkedHashMap;

/** Sole application boundary for an accepted candidate and its target repository side effects. */
public final class DeliveryApplicationService {
    private final ObjectMapper objectMapper;
    private final WorkflowFileLedger ledger;
    private final AcceptedDeliveryCandidateResolver resolver;
    private final GitPatchMergeService git;

    public DeliveryApplicationService(WorkflowFileLedger ledger) {
        this(
                new ObjectMapper().findAndRegisterModules(),
                ledger,
                new AcceptedDeliveryCandidateResolver(ledger),
                new GitPatchMergeService()
        );
    }

    DeliveryApplicationService(
            ObjectMapper objectMapper,
            WorkflowFileLedger ledger,
            AcceptedDeliveryCandidateResolver resolver,
            GitPatchMergeService git
    ) {
        this.objectMapper = objectMapper;
        this.ledger = ledger;
        this.resolver = resolver;
        this.git = git;
    }

    public View view(Path sourceWorktree, String workstreamId, Path requestedTarget) {
        var paths = paths(sourceWorktree, workstreamId);
        try {
            return ledger.inspect(paths, (scoped, files) -> new DeliveryApplicationService(objectMapper, scoped,
                    new AcceptedDeliveryCandidateResolver(scoped), git).viewSnapshot(sourceWorktree, workstreamId, requestedTarget));
        } catch (dev.dual.ledger.file.WorkstreamLockedException busy) {
            return new View("BUSY", "LEDGER_BUSY", busy.getMessage(), "", "", "", List.of(), List.of(), "", "", false, false);
        } catch (dev.dual.ledger.file.LedgerSession.PendingCommitException pending) {
            return new View("PENDING", "LEDGER_PENDING", pending.getMessage(), "", "", "", List.of(), List.of(), "", "", false, false);
        } catch (IOException invalid) {
            return new View("INVALID", "LEDGER_INVALID", invalid.getMessage(), "", "", "", List.of(), List.of(), "", "", false, false);
        }
    }

    private View viewSnapshot(Path sourceWorktree, String workstreamId, Path requestedTarget) {
        var paths = paths(sourceWorktree, workstreamId);
        Path target = requestedTarget == null ? null : requestedTarget.toAbsolutePath().normalize();
        try {
            target = targetRepo(paths, requestedTarget);
            var existing = readPlan(paths);
            requireCompleted(paths);
            if (existing != null) {
                if (existing.candidateRef().isBlank()) {
                    if (existing.status() != DeliveryMergeStatus.FAILED) {
                        accepted(paths);
                        throw boundary("ACCEPTED_CANDIDATE_INVALID", "delivery plan is missing its accepted candidate binding");
                    }
                } else {
                    requirePlanCandidate(paths, existing, accepted(paths));
                }
                return fromPlan(existing);
            }
            var accepted = accepted(paths);
            verifySourceCapture(sourceWorktree.toAbsolutePath().normalize(), accepted);
            return new View(
                    "READY", "", "", text(accepted.gate().result().get("human_action")),
                    accepted.candidateRef(), accepted.candidateSha256(),
                    accepted.candidate().acceptedFiles(), accepted.candidate().excludedFiles(), target.toString(), "",
                    true, false
            );
        } catch (Exception failure) {
            return new View(
                    "BLOCKED", reasonCode(failure), message(failure), "", "", "", List.of(), List.of(),
                    target == null ? "" : target.toString(), "", false, false
            );
        }
    }

    public View apply(Path sourceWorktree, String workstreamId, Path requestedTarget) throws Exception {
        try { return applyBound(sourceWorktree, workstreamId, requestedTarget); }
        catch (DeliveryBoundaryException refusal) { return blocked(refusal.code(), refusal.getMessage()); }
    }

    private View applyBound(Path sourceWorktree, String workstreamId, Path requestedTarget) throws Exception {
        var paths = paths(sourceWorktree, workstreamId);
        var target = ledger.inspect(paths, (scoped, files) -> scopedService(scoped).targetRepo(paths, requestedTarget)).toRealPath();
        // Common-dir coordination precedes L. No external effect is part of a replayable local mutation.
        try (var targetLock = WorkstreamLock.acquire(git.commonDirectory(target).resolve("dual-delivery"),
                LockOwner.currentProcess(workstreamId, "delivery target"))) {
            var before = git.applicationObservation(target);
            DeliveryMergePlan intent;
            String patch;
            try (var write = ledger.writeSession(paths, "delivery apply intent", java.util.UUID.randomUUID().toString())) {
                var service = scopedService(write.ledger());
                service.requireCompleted(paths);
                var accepted = service.accepted(paths);
                var previous = service.readPlan(paths);
                if (previous != null && previous.operation().containsKey("apply_intent")) {
                    service.requirePlanCandidate(paths, previous, accepted);
                    if (previous.status() == DeliveryMergeStatus.COMMITTED) return fromPlan(previous);
                    if (applicationMatches(previous, before)) {
                        var recovered = observed(previous, before).withStatus(DeliveryMergeStatus.APPLIED, "", "");
                        service.savePlan(paths, recovered, "delivery_application_observed");
                        write.commit();
                        return fromPlan(recovered);
                    }
                    // An invocation of apply never grants permission to repeat an uncertain external effect.
                    return fromPlan(previous, "DELIVERY_RESULT_UNKNOWN", "The prior operation requires target-state adjudication; no second apply was sent.");
                }
                service.verifySourceCapture(sourceWorktree.toAbsolutePath().normalize(), accepted);
                if (!Boolean.TRUE.equals(before.get("clean"))
                        || !accepted.candidate().baseCommit().equals(before.get("head"))
                        || !accepted.candidate().baseTree().equals(before.get("head_tree")))
                    throw boundary("TARGET_NOT_ELIGIBLE", "target repository base does not match accepted candidate");
                var candidate = accepted.candidate();
                intent = DeliveryMergePlan.create(workstreamId, sourceWorktree.toAbsolutePath().normalize().toString(),
                        target.toString(), text(accepted.gate().result().get("human_action")),
                        accepted.candidateRef(), accepted.candidateSha256(), candidate.baseCommit(), candidate.baseTree(),
                        candidate.expectedResultTree(), candidate.acceptedFiles(), candidate.excludedFiles(),
                        DeliveryMergeStatus.UNKNOWN, "DELIVERY_RESULT_UNKNOWN", "Durable intent exists; application outcome is not yet recorded.")
                        .withOperation(Map.of("id", java.util.UUID.randomUUID().toString(), "apply_intent", true,
                                "before", before, "executor_pid", ProcessHandle.current().pid(),
                                "executor_started_at", ProcessHandle.current().info().startInstant().orElseThrow().toString(),
                                "approval_node", accepted.gateNode().nodeInstanceId(),
                                "approval_sha256", DeliveryCandidateWriter.sha256(Files.readAllBytes(paths.gateJson(accepted.gate().gateId())))));
                patch = Files.readString(resolveRef(paths, candidate.patch().ref()), StandardCharsets.UTF_8);
                service.writeCompatibilityArtifacts(paths, accepted);
                service.savePlan(paths, intent, "delivery_apply_intent");
                write.commit();
            }
            // After this point failures leave UNKNOWN. Never overwrite intent with an unqualified FAILED/retryable state.
            var result = git.apply(target, patch);
            var after = git.applicationObservation(target);
            var facts = new LinkedHashMap<>(intent.operation());
            facts.put("observation", after);
            facts.put("exit_code", result.exitCode());
            facts.put("stdout", result.stdout());
            facts.put("stderr", result.stderr());
            var observed = intent.withOperation(facts);
            var outcome = applicationMatches(intent, after)
                    ? observed.withStatus(DeliveryMergeStatus.APPLIED, "", "")
                    : observed.withStatus(DeliveryMergeStatus.UNKNOWN, "DELIVERY_RESULT_UNKNOWN", "Target differs from the accepted post-state; preserve it for adjudication.");
            try (var write = ledger.writeSession(paths, "delivery application observation", text(intent.operation().get("id")))) {
                var service = scopedService(write.ledger());
                service.requireSameOperation(paths, intent);
                service.requirePlanCandidate(paths, intent, service.accepted(paths));
                service.savePlan(paths, outcome, "delivery_application_observed");
                write.commit();
            }
            return fromPlan(outcome);
        }
    }

    public View finalizeCommit(Path sourceWorktree, String workstreamId, String commitSha) throws Exception {
        try { return finalizeBound(sourceWorktree, workstreamId, commitSha); }
        catch (DeliveryBoundaryException refusal) { return blocked(refusal.code(), refusal.getMessage()); }
    }

    private View finalizeBound(Path sourceWorktree, String workstreamId, String commitSha) throws Exception {
        var paths = paths(sourceWorktree, workstreamId);
        var plan = ledger.inspect(paths, (scoped, files) -> {
            var service = scopedService(scoped);
            service.requireCompleted(paths);
            var existing = service.readPlan(paths);
            if (existing != null) service.requirePlanCandidate(paths, existing, service.accepted(paths));
            return existing;
        });
        if (plan == null) return blocked("DELIVERY_NOT_APPLIED", "delivery candidate has not been applied");
        if (!plan.operation().containsKey("apply_intent")) throw boundary("DELIVERY_INVALID", "plan lacks a bound application operation");
        var target = Path.of(plan.targetRepo()).toRealPath();
        try (var targetLock = WorkstreamLock.acquire(git.commonDirectory(target).resolve("dual-delivery"),
                LockOwner.currentProcess(workstreamId, "delivery finalize"))) {
            var repository = git.repositoryState(target);
            var commit = git.commitState(target, commitSha);
            if (!repository.clean() || !repository.headCommit().equals(commit.commit())
                    || !commit.parent().equals(plan.baseCommit()) || !commit.tree().equals(plan.expectedResultTree()))
                throw boundary("TARGET_NOT_ELIGIBLE", "actual clean HEAD, parent and tree must match the accepted candidate");
            try (var write = ledger.writeSession(paths, "delivery finalize", commit.commit())) {
                var service = scopedService(write.ledger());
                service.requireCompleted(paths);
                service.requireSameOperation(paths, plan);
                service.requirePlanCandidate(paths, plan, service.accepted(paths));
                var actual = service.readPlan(paths);
                if (actual.status() == DeliveryMergeStatus.COMMITTED) {
                    if (!actual.commit().equals(commit.commit())) throw boundary("DELIVERY_INVALID", "different commit was already finalized");
                    return fromPlan(actual);
                }
                var committed = actual.withCommitted(commit.commit());
                service.savePlan(paths, committed, "delivery_committed");
                write.commit();
                return fromPlan(committed);
            }
        }
    }

    private DeliveryApplicationService scopedService(WorkflowFileLedger scoped) {
        return new DeliveryApplicationService(objectMapper, scoped, new AcceptedDeliveryCandidateResolver(scoped), git);
    }

    private void savePlan(WorkstreamPaths paths, DeliveryMergePlan plan, String event) throws IOException {
        new DeliveryMergePlanWriter(ledger.files()).write(paths, plan);
        ledger.appendEvent(paths, "delivery-" + plan.operation().get("id") + "-" + event, event,
                Map.of("operation", plan.operation(), "candidate_ref", plan.candidateRef(), "candidate_sha256", plan.candidateSha256(),
                        "status", plan.status().name(), "commit", plan.commit()));
    }

    private void requireSameOperation(WorkstreamPaths paths, DeliveryMergePlan expected) throws IOException {
        var current = readPlan(paths);
        if (current == null || !java.util.Objects.equals(current.operation().get("id"), expected.operation().get("id"))
                || !current.candidateSha256().equals(expected.candidateSha256()))
            throw boundary("DELIVERY_INVALID", "delivery operation changed");
    }

    private static DeliveryMergePlan observed(DeliveryMergePlan plan, Map<String, Object> observation) {
        var facts = new LinkedHashMap<>(plan.operation());
        facts.put("observation", observation);
        return plan.withOperation(facts);
    }

    private static boolean applicationMatches(DeliveryMergePlan plan, Map<String, Object> observation) {
        return plan.baseCommit().equals(observation.get("head"))
                && plan.expectedResultTree().equals(observation.get("index_tree"))
                && Boolean.TRUE.equals(observation.get("worktree_matches_index"))
                && Boolean.TRUE.equals(observation.get("no_untracked"));
    }

    private void requireCompleted(WorkstreamPaths paths) throws IOException {
        var current = ledger.loadCurrent(paths);
        if (current.status() != WorkflowStatus.COMPLETED) {
            throw boundary("WORKFLOW_NOT_DELIVERABLE", "workstream is not completed: " + current.status());
        }
        if (!Files.isRegularFile(paths.completionAuditJson())) throw boundary("WORKFLOW_NOT_DELIVERABLE", "completion audit is missing");
        var audit = objectMapper.readTree(paths.completionAuditJson().toFile());
        if (!"ready".equalsIgnoreCase(audit.path("status").asText())) {
            throw boundary("WORKFLOW_NOT_DELIVERABLE", "completion audit is not ready: " + audit.path("status").asText());
        }
    }

    private void verifySourceCapture(Path source, AcceptedDeliveryCandidateResolver.Accepted accepted) throws Exception {
        var candidate = accepted.candidate();
        if (!source.toString().equals(candidate.sourceEffectiveWorkdir())) {
            throw boundary("SOURCE_CANDIDATE_DRIFT", "source worktree does not match accepted candidate workspace");
        }
        var current = git.capture(source);
        var patchSha = DeliveryCandidateWriter.sha256(current.patch().getBytes(StandardCharsets.UTF_8));
        if (!current.baseCommit().equals(candidate.baseCommit())
                || !current.baseTree().equals(candidate.baseTree())
                || !current.acceptedFiles().equals(candidate.acceptedFiles())
                || !current.excludedFiles().equals(candidate.excludedFiles())
                || !patchSha.equals(candidate.patch().sha256())
                || !current.expectedResultTree().equals(candidate.expectedResultTree())) {
            throw boundary("SOURCE_CANDIDATE_DRIFT", "source worktree drifted from the accepted delivery candidate");
        }
    }

    private Path targetRepo(WorkstreamPaths paths, Path requestedTarget) throws IOException {
        var workstream = objectMapper.readValue(paths.workstreamJson().toFile(), WorkstreamDocument.class);
        var recorded = Path.of(workstream.repository().originalWorkdir()).toAbsolutePath().normalize();
        if (requestedTarget != null && !recorded.equals(requestedTarget.toAbsolutePath().normalize())) {
            throw boundary("TARGET_NOT_ELIGIBLE", "requested target does not match workstream repository identity");
        }
        return recorded;
    }

    private void requirePlanCandidate(WorkstreamPaths paths, DeliveryMergePlan plan, AcceptedDeliveryCandidateResolver.Accepted accepted)
            throws IOException {
        if (!plan.candidateRef().equals(accepted.candidateRef())
                || !plan.candidateSha256().equals(accepted.candidateSha256())
                || !plan.expectedResultTree().equals(accepted.candidate().expectedResultTree())
                || !accepted.gateNode().nodeInstanceId().equals(plan.operation().get("approval_node"))
                || !DeliveryCandidateWriter.sha256(ledger.files().readBytes(paths.gateJson(accepted.gate().gateId())))
                        .equals(plan.operation().get("approval_sha256"))) {
            throw boundary("ACCEPTED_CANDIDATE_INVALID", "delivery plan does not match the accepted candidate");
        }
    }

    private void writeCompatibilityArtifacts(WorkstreamPaths paths, AcceptedDeliveryCandidateResolver.Accepted accepted)
            throws IOException {
        ledger.files().writeBytes(paths.deliveryMergePatch(), ledger.files().readBytes(resolveRef(paths, accepted.candidate().patch().ref())));
        ledger.files().writeBytes(paths.deliveryChangedFilesTxt(), (String.join(System.lineSeparator(), accepted.candidate().acceptedFiles())
                + System.lineSeparator()).getBytes(StandardCharsets.UTF_8));
        ledger.files().writeBytes(paths.deliveryExcludedFilesTxt(), (String.join(System.lineSeparator(), accepted.candidate().excludedFiles())
                + (accepted.candidate().excludedFiles().isEmpty() ? "" : System.lineSeparator())).getBytes(StandardCharsets.UTF_8));
    }

    private DeliveryMergePlan readPlan(WorkstreamPaths paths) throws IOException {
        return ledger.files().exists(paths.deliveryMergePlanJson())
                ? ledger.files().read(paths.deliveryMergePlanJson(), DeliveryMergePlan.class)
                : null;
    }

    private static Path resolveRef(WorkstreamPaths paths, String ref) throws IOException {
        var root = paths.workspaceRoot().toAbsolutePath().normalize();
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root) || !Files.isRegularFile(path)) throw new IOException("delivery artifact ref is invalid: " + ref);
        return path;
    }

    private static WorkstreamPaths paths(Path source, String workstreamId) {
        return new WorkstreamPaths(source.toAbsolutePath().normalize(), new DualId(workstreamId));
    }

    private static View fromPlan(DeliveryMergePlan plan, String reasonCode) {
        return fromPlan(plan, reasonCode.isBlank() ? plan.failureCode() : reasonCode, plan.failureReason());
    }

    private static View fromPlan(DeliveryMergePlan plan) {
        return fromPlan(plan, plan.failureCode(), plan.failureReason());
    }

    private static View fromPlan(DeliveryMergePlan plan, String reasonCode, String reason) {
        return new View(
                plan.status().name(), reasonCode, reason, plan.acceptanceDecision(), plan.candidateRef(), plan.candidateSha256(),
                plan.changedFiles(), plan.excludedFiles(), plan.targetRepo(), plan.commit(),
                plan.status() == DeliveryMergeStatus.READY,
                plan.status() == DeliveryMergeStatus.APPLIED
        );
    }

    private static View blocked(String code, String reason) {
        return new View("BLOCKED", code, reason, "", "", "", List.of(), List.of(), "", "", false, false);
    }

    private static String reasonCode(Exception failure) {
        if (failure instanceof DeliveryBoundaryException boundary) return boundary.code();
        var message = message(failure);
        if (message.contains("source worktree")) return "SOURCE_CANDIDATE_DRIFT";
        if (message.contains("commit tree") || message.contains("target repository") || message.contains("target staged tree")) {
            return "TARGET_NOT_ELIGIBLE";
        }
        if (message.contains("candidate") || message.contains("acceptance")) return "LEGACY_NOT_BOUND";
        if (message.contains("completed") || message.contains("completion audit")) return "WORKFLOW_NOT_DELIVERABLE";
        if (message.contains("target")) return "TARGET_NOT_ELIGIBLE";
        return "DELIVERY_BOUNDARY_REJECTED";
    }

    private AcceptedDeliveryCandidateResolver.Accepted accepted(WorkstreamPaths paths) throws IOException {
        try {
            return resolver.resolve(paths);
        } catch (AcceptedDeliveryCandidateResolver.MissingBindingException missing) {
            throw boundary("LEGACY_NOT_BOUND", missing.getMessage());
        } catch (IOException invalid) {
            throw boundary("ACCEPTED_CANDIDATE_INVALID", invalid.getMessage());
        }
    }

    private static DeliveryBoundaryException boundary(String code, String message) {
        return new DeliveryBoundaryException(code, message);
    }

    private static String message(Exception failure) {
        return failure.getMessage() == null ? failure.getClass().getSimpleName() : failure.getMessage();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    public record View(
            String status,
            String reasonCode,
            String reason,
            String acceptanceDecision,
            String candidateRef,
            String candidateSha256,
            List<String> changedFiles,
            List<String> excludedFiles,
            String targetRepo,
            String commit,
            boolean canMerge,
            boolean canFinalize
    ) {
        public View {
            changedFiles = List.copyOf(changedFiles);
            excludedFiles = List.copyOf(excludedFiles);
        }
    }

    private static final class DeliveryBoundaryException extends IOException {
        private final String code;

        private DeliveryBoundaryException(String code, String message) {
            super(message);
            this.code = code;
        }

        private String code() {
            return code;
        }
    }
}

package dev.dual.runtime.governance;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Typed projection of exploration capabilities available to an agent run.
 *
 * This is not a prompt policy and not workflow truth. It gives the
 * orchestrator a structured way to say what exploration surfaces are available
 * before an agent chooses how to inspect the repository.
 */
public final class AgentCapabilityCatalog {
    private final String workstreamId;
    private final String nodeDefinitionId;
    private final List<Map<String, Object>> capabilities;

    private AgentCapabilityCatalog(String workstreamId, String nodeDefinitionId, List<Map<String, Object>> capabilities) {
        this.workstreamId = text(workstreamId);
        this.nodeDefinitionId = text(nodeDefinitionId);
        this.capabilities = List.copyOf(capabilities);
    }

    public static AgentCapabilityCatalog detect(String workstreamId, String nodeDefinitionId) {
        return fromAvailableCommands(workstreamId, nodeDefinitionId, availableCommands());
    }

    public static AgentCapabilityCatalog detect(
            String workstreamId,
            String nodeDefinitionId,
            Map<String, Object> nodeConfig
    ) {
        var permission = CapabilityPermission.fromNodeConfig(nodeConfig);
        return fromAvailableCommands(
                workstreamId,
                nodeDefinitionId,
                availableCommands(),
                permission.directReadAllowed(),
                permission.shellAllowed()
        );
    }

    public static AgentCapabilityCatalog fromAvailableCommands(
            String workstreamId,
            String nodeDefinitionId,
            Collection<String> availableCommands
    ) {
        return fromAvailableCommands(workstreamId, nodeDefinitionId, availableCommands, true, true);
    }

    public static AgentCapabilityCatalog fromAvailableCommands(
            String workstreamId,
            String nodeDefinitionId,
            Collection<String> availableCommands,
            boolean directReadAllowed,
            boolean shellAllowed
    ) {
        var commands = new LinkedHashSet<String>();
        if (availableCommands != null) {
            for (var command : availableCommands) {
                var value = text(command).toLowerCase(Locale.ROOT);
                if (!value.isBlank()) {
                    commands.add(value);
                }
            }
        }

        var capabilities = new ArrayList<Map<String, Object>>();
        if (directReadAllowed) {
            capabilities.add(capability("direct_file_read", "Read", "Direct file content retrieval tool."));
        }
        if (shellAllowed && allowsTokenFilteredShell(nodeDefinitionId) && commands.contains("rtk")) {
            capabilities.add(capability("token_filtered_shell", "rtk", "Token-filtered shell command surface."));
        }
        if (shellAllowed && commands.contains("codegraph")) {
            capabilities.add(capability("symbol_index", "codegraph", "Symbol-level repository index."));
        } else if (shellAllowed && commands.contains("gitnexus")) {
            capabilities.add(capability("symbol_index", "gitnexus", "Symbol-level repository index."));
        }
        return new AgentCapabilityCatalog(workstreamId, nodeDefinitionId, capabilities);
    }

    public boolean hasKind(String kind) {
        var expected = text(kind);
        return capabilities.stream().anyMatch(item -> expected.equals(text(item.get("kind"))));
    }

    public List<String> capabilityKinds() {
        return capabilities.stream()
                .map(item -> text(item.get("kind")))
                .filter(value -> !value.isBlank())
                .toList();
    }

    public Map<String, Object> toDocument() {
        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "agent_capability_catalog");
        document.put("workstreamId", workstreamId);
        document.put("nodeDefinitionId", nodeDefinitionId);
        document.put("capabilities", capabilities);
        return document;
    }

    private static Map<String, Object> capability(String kind, String provider, String description) {
        var item = new LinkedHashMap<String, Object>();
        item.put("kind", kind);
        item.put("provider", provider);
        item.put("description", description);
        return item;
    }

    private static boolean allowsTokenFilteredShell(String nodeDefinitionId) {
        return !"intake.claude_brainstorm".equals(text(nodeDefinitionId));
    }

    private static Set<String> availableCommands() {
        var result = new LinkedHashSet<String>();
        for (var command : List.of("rtk", "codegraph", "gitnexus")) {
            if (commandAvailable(command)) {
                result.add(command);
            }
        }
        return result;
    }

    private static boolean commandAvailable(String command) {
        var path = System.getenv("PATH");
        if (path == null || path.isBlank()) {
            return false;
        }
        for (var dir : path.split(java.io.File.pathSeparator)) {
            if (Files.isExecutable(Path.of(dir).resolve(command))) {
                return true;
            }
        }
        return false;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private record CapabilityPermission(boolean directReadAllowed, boolean shellAllowed) {
        static CapabilityPermission fromNodeConfig(Map<String, Object> nodeConfig) {
            var profile = text(nodeConfig == null ? null : nodeConfig.get("permission_profile"));
            if (!profile.isBlank()) {
                return switch (profile) {
                case "contract_discovery" -> new CapabilityPermission(true, false);
                case "observe", "review" -> new CapabilityPermission(true, false);
                case "implement" -> new CapabilityPermission(true, true);
                default -> new CapabilityPermission(true, false);
                };
            }
            return nodeConfig != null && Boolean.TRUE.equals(nodeConfig.get("approve_all"))
                    ? new CapabilityPermission(true, true)
                    : new CapabilityPermission(true, false);
        }
    }
}

package dev.dual.runtime.handler;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import dev.dual.core.arbitration.FailureCategory;

public final class AgentContractSemantics {
    private AgentContractSemantics() {
    }

    static Optional<ContractViolation> validateRereadReasons(Object rawValue) {
        if (!(rawValue instanceof List<?> list) || list.isEmpty()) {
            return Optional.empty();
        }
        for (int i = 0; i < list.size(); i++) {
            var item = list.get(i);
            if (!(item instanceof Map<?, ?> raw)) {
                return violation("REREAD_REASON_ENTRY_NOT_OBJECT",
                        "reread_reasons[" + i + "] must be an object", Map.of("index", i));
            }
            if (text(raw.get("path")).isBlank()) {
                return violation("REREAD_REASON_PATH_REQUIRED",
                        "reread_reasons[" + i + "] requires a non-blank 'path'", Map.of("index", i));
            }
            var reason = text(raw.get("reason"));
            if (!ReadReuseContractReasons.isAllowed(reason)) {
                return violation("REREAD_REASON_REASON_NOT_ALLOWED",
                        "reread_reasons[" + i + "] reason is not in the allowed catalog: " + reason,
                        Map.of("index", i, "reason", reason));
            }
            if (raw.containsKey("stage") && text(raw.get("stage")).isBlank()) {
                return violation("REREAD_REASON_STAGE_BLANK",
                        "reread_reasons[" + i + "] 'stage' is present but blank", Map.of("index", i));
            }
            if (raw.containsKey("evidence") && text(raw.get("evidence")).isBlank()) {
                return violation("REREAD_REASON_EVIDENCE_BLANK",
                        "reread_reasons[" + i + "] 'evidence' is present but blank", Map.of("index", i));
            }
        }
        return Optional.empty();
    }

    static Optional<ContractViolation> validateOutputContract(AgentOutputContractDocument document) {
        if ("self_test_report".equals(document.sourceArtifactType())
                && "SELF_TEST_COMPLETE".equals(document.decision())
                && (!document.mustFix().isEmpty() || !document.missingEvidence().isEmpty())) {
            return violation("SELF_TEST_COMPLETION_CONFLICT",
                    "SELF_TEST_COMPLETE cannot include must_fix or missing_evidence", Map.of());
        }
        if (isAcceptanceReview(document)) {
            var failure = document.failure();
            var classification = validateAcceptanceClassification(document.decision(), failure.categoryHint(),
                    failure.verificationRemediation(), failure.contractGaps(), failure.outOfScopeFiles(),
                    failure.missingTests(), failure.contextGaps(), failure.reason(),
                    document.mustFix(), document.missingEvidence());
            if (classification.isPresent()) return classification;
        }
        return StageOutcomeCompiler.validateEvidenceContract(
                "agent_output_contract",
                document.decision(),
                document.lifecycleStatus(),
                AgentEvidenceState.from(document),
                document.failure());
    }

    static List<String> acceptanceCategories() {
        return java.util.Arrays.stream(FailureCategory.values()).map(Enum::name).toList();
    }

    static boolean isAcceptanceReview(AgentOutputContractDocument document) {
        return "acceptance_review".equals(document.sourceArtifactType())
                || "acceptance.codex_verifier_review".equals(document.nodeId());
    }

    static Optional<ContractViolation> validateAcceptanceClassification(
            String decision, String categoryHint, AgentResultEnvelope.VerificationRemediation remediation,
            List<String> contractGaps, List<String> outOfScope, List<String> missingTests,
            List<String> contextGaps, String reason, List<String> mustFix, List<String> missingEvidence) {
        boolean reject = "REJECT".equals(decision);
        boolean tests = nonempty(missingTests);
        boolean activeRemediation = remediation != null
                && remediation != AgentResultEnvelope.VerificationRemediation.NONE;
        if (reject && tests && !activeRemediation)
            return classificationViolation("result.failure.verification_remediation is required when REJECT lists missing_tests");
        if (!(reject && tests) && activeRemediation)
            return classificationViolation("result.failure.verification_remediation is only allowed when REJECT lists missing_tests");
        if (!reject) {
            return categoryHint == null || categoryHint.isEmpty() ? Optional.empty()
                    : classificationViolation("accepted review must not declare a failure category");
        }
        final FailureCategory category;
        try { category = FailureCategory.valueOf(categoryHint == null ? "" : categoryHint); }
        catch (IllegalArgumentException failure) {
            return classificationViolation("REJECT requires exact failure.category_hint from " + acceptanceCategories());
        }
        boolean contract = category == FailureCategory.CONTRACT_GAP || category == FailureCategory.CONTRACT_AMBIGUITY;
        boolean testChange = remediation == AgentResultEnvelope.VerificationRemediation.TEST_CODE_CHANGE;
        if (contract != nonempty(contractGaps)) {
            return classificationViolation("contract categories require contract_gaps; other categories forbid them");
        }
        boolean valid = switch (category) {
            case CONTRACT_GAP, CONTRACT_AMBIGUITY -> true;
            case IMPLEMENTATION_BUG -> nonempty(mustFix) || nonempty(outOfScope) || testChange;
            case VERIFICATION_INSUFFICIENT -> (tests || nonempty(missingEvidence))
                    && !nonempty(outOfScope) && !nonempty(contextGaps) && !testChange;
            case CONTEXT_INSUFFICIENT -> nonempty(contextGaps) && !nonempty(outOfScope) && !testChange;
            case TOOL_LIMITATION -> reason != null && !reason.isBlank() && !nonempty(outOfScope) && !testChange;
            case REVIEW_NOISE -> reason != null && !reason.isBlank() && !nonempty(outOfScope)
                    && !tests && !nonempty(contextGaps) && !nonempty(missingEvidence)
                    && !nonempty(mustFix) && !activeRemediation;
        };
        return valid ? Optional.empty() : classificationViolation("failure evidence contradicts category " + category);
    }

    private static boolean nonempty(List<?> values) { return values != null && !values.isEmpty(); }

    private static Optional<ContractViolation> classificationViolation(String message) {
        return violation("ACCEPTANCE_CLASSIFICATION_INVALID", message, Map.of());
    }

    static void addSidecarFields(Map<String, Object> sidecar) {
        StageOutcomeCompiler.addSidecarFields(sidecar);
    }

    private static Optional<ContractViolation> violation(String code, String message, Map<String, Object> details) {
        return Optional.of(ContractViolation.of(code, message, details));
    }

    private static StringListValidation stringList(Object rawValue) {
        if (rawValue == null) {
            return new StringListValidation(List.of(), -1);
        }
        if (!(rawValue instanceof List<?> list)) {
            return new StringListValidation(List.of(), 0);
        }
        var values = new java.util.ArrayList<String>();
        for (int i = 0; i < list.size(); i++) {
            var value = list.get(i);
            if (!(value instanceof String item) || item.trim().isBlank()) {
                return new StringListValidation(List.of(), i);
            }
            values.add(item.trim());
        }
        return new StringListValidation(List.copyOf(values), -1);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private record StringListValidation(List<String> values, int invalidIndex) {
    }
}

package dev.dual.runtime.handler;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

record AgentDecisionSummary(
        String nodeId,
        String stageOutcome,
        String decision,
        String summary,
        boolean blocking,
        List<String> mustFix,
        List<String> missingEvidence,
        List<String> openRisks,
        List<String> changedFiles,
        String verificationSummary,
        AgentEvidenceState evidenceState,
        String sidecarPath
) {
    static AgentDecisionSummary empty() {
        return new AgentDecisionSummary(
                "", "", "", "", false, List.of(), List.of(), List.of(), List.of(), "",
                new AgentEvidenceState(false, 0, 0, 0, 0, 0), ""
        );
    }

    static AgentDecisionSummary from(AgentOutputContractDocument document, String sidecarPath) {
        return new AgentDecisionSummary(
                document.nodeId(),
                document.canonicalStageOutcome(),
                document.decision(),
                document.summary(),
                document.blocking(),
                document.mustFix(),
                document.missingEvidence(),
                document.openRisks(),
                document.changedFiles(),
                document.verificationSummary(),
                AgentEvidenceState.from(document),
                sidecarPath
        );
    }

    boolean isEmpty() {
        return !hasDecision();
    }

    boolean hasDecision() {
        return !decision.isBlank();
    }

    Map<String, Object> toReviewPacketMap() {
        if (isEmpty()) {
            return Map.of();
        }
        var summary = new LinkedHashMap<String, Object>();
        summary.put("nodeId", nodeId);
        summary.put("stageOutcome", stageOutcome);
        summary.put("lifecycleStatus", stageOutcome);
        summary.put("decision", decision);
        summary.put("summary", this.summary);
        summary.put("blocking", blocking);
        summary.put("mustFix", mustFix);
        summary.put("missingEvidence", missingEvidence);
        summary.put("openRisks", openRisks);
        summary.put("changedFiles", changedFiles);
        summary.put("verificationSummary", verificationSummary);
        summary.put("evidenceState", evidenceState.toMap());
        summary.put("sidecarPath", sidecarPath);
        return summary;
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Read model for validated agent output sidecars.
 *
 * Consumers should use this index instead of walking runs and re-parsing raw
 * maps independently. It keeps ordering and structured-field interpretation in
 * one place while preserving the file ledger as the source of truth.
 */
public final class AgentEvidenceIndex {
    private final List<Entry> entries;

    private AgentEvidenceIndex(List<Entry> entries) {
        this.entries = List.copyOf(entries);
    }

    static AgentEvidenceIndex fromRefs(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            List<String> refs,
            ObjectMapper objectMapper
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var entries = refs.stream()
                .map(ref -> sidecarPathForRef(root, ref))
                .flatMap(Optional::stream)
                .distinct()
                .map(path -> readEntry(ledger, root, workstreamId, path, objectMapper))
                .flatMap(Optional::stream)
                .sorted(Entry.ORDER.reversed())
                .toList();
        return new AgentEvidenceIndex(entries);
    }

    static Optional<Entry> latestFromRefs(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            List<String> refs,
            ObjectMapper objectMapper
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        return refs.stream()
                .map(ref -> sidecarPathForRef(root, ref))
                .flatMap(Optional::stream)
                .map(path -> readEntry(ledger, root, workstreamId, path, objectMapper))
                .flatMap(Optional::stream)
                .sorted(Entry.ORDER.reversed())
                .findFirst();
    }

    static DecisionRead latestDecisionFromRefs(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            List<String> refs,
            ObjectMapper objectMapper
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        for (int i = refs.size() - 1; i >= 0; i--) {
            var path = sidecarPathForRef(root, refs.get(i));
            if (path.isEmpty()) {
                continue;
            }
            var read = readValidatedEntry(ledger, root, workstreamId, path.get(), objectMapper);
            if (read.entry() == null) {
                return DecisionRead.invalid(read.errorCode(), read.message(), path.get().toString());
            }
            if (!read.entry().document().hasDecision()) {
                return DecisionRead.invalid(
                        "CONTRACT_SIDECAR_MISSING_DECISION",
                        "Contract sidecar is missing required decision: " + path.get().getFileName(),
                        path.get().toString()
                );
            }
            return DecisionRead.valid(read.entry(), path.get().toString());
        }
        return DecisionRead.notFound();
    }

    public static Optional<AgentOutputContractDocument> validatedDocument(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            String ref,
            ObjectMapper objectMapper
    ) {
        var index = fromRefs(ledger, workspaceRoot, workstreamId, List.of(ref), objectMapper);
        return index.entryForRef(workspaceRoot, ref).map(Entry::document);
    }

    List<Entry> recent(int maxItems) {
        if (maxItems <= 0) {
            return List.of();
        }
        return entries.stream().limit(maxItems).toList();
    }

    Optional<Entry> latest() {
        return entries.stream().findFirst();
    }

    Optional<Entry> entryForRef(Path workspaceRoot, String ref) {
        var normalizedRef = normalizeRef(ref);
        return entries.stream()
                .filter(entry -> normalizedRef.equals(normalizeRef(entry.document().sourceOutputRef()))
                        || normalizedRef.equals(normalizeRef(relativeRef(workspaceRoot, entry.path()))))
                .findFirst();
    }

    boolean isValidatedPlanProjectionRef(Path workspaceRoot, String ref) {
        var normalizedRef = normalizeRef(ref);
        return entries.stream()
                .filter(entry -> entry.document().planArtifact() != null)
                .map(entry -> workspaceRoot.resolve(entry.document().sourceOutputRef()).normalize())
                .map(PlanArtifactSidecar::pathFor)
                .map(path -> relativeRef(workspaceRoot, path))
                .map(AgentEvidenceIndex::normalizeRef)
                .anyMatch(normalizedRef::equals);
    }

    List<String> validatedSidecarRefs(Path workspaceRoot) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        return entries.stream()
                .map(Entry::path)
                .map(root::relativize)
                .map(Path::toString)
                .toList();
    }

    boolean contains(String nodeId, String sourceArtifactType, String decision) {
        return entries.stream().map(Entry::document).anyMatch(document ->
                nodeId.equals(document.nodeId())
                        && sourceArtifactType.equals(document.sourceArtifactType())
                        && decision.equals(document.decision())
                        && document.hasRequiredTypedPayload());
    }

    private static Optional<Path> sidecarPathForRef(Path workspaceRoot, String ref) {
        if (ref == null || ref.isBlank() || ref.startsWith("artifact://")) {
            return Optional.empty();
        }
        var referenced = workspaceRoot.resolve(ref).normalize();
        if (!referenced.startsWith(workspaceRoot)) {
            return Optional.empty();
        }
        var path = ref.endsWith(".contract.json")
                ? referenced
                : AgentOutputContractSidecar.pathFor(referenced);
        if (!path.startsWith(workspaceRoot)
                || Files.isSymbolicLink(path)
                || !Files.isRegularFile(path)) {
            return Optional.empty();
        }
        try {
            if (!path.toRealPath().startsWith(workspaceRoot.toRealPath())) {
                return Optional.empty();
            }
        } catch (Exception e) {
            return Optional.empty();
        }
        return Optional.of(path);
    }

    private static Optional<Entry> readEntry(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            Path path,
            ObjectMapper objectMapper
    ) {
        var read = readValidatedEntry(ledger, workspaceRoot, workstreamId, path, objectMapper);
        if (read.entry() == null) {
            throw new IllegalStateException(read.message());
        }
        return Optional.of(read.entry());
    }

    private static EntryRead readValidatedEntry(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            Path path,
            ObjectMapper objectMapper
    ) {
        var document = AgentOutputContractDocument.read(path, objectMapper);
        if (document.isEmpty()) {
            return EntryRead.invalid(
                    "CONTRACT_SIDECAR_PARSE_FAILED",
                    "routed agent evidence sidecar is unreadable: " + path
            );
        }
        var violation = AgentOutputLineageVerifier.violation(ledger, workspaceRoot, workstreamId, path, document.get());
        if (violation.isPresent()) {
            return EntryRead.invalid(
                    "CONTRACT_SIDECAR_LINEAGE_INVALID",
                    "routed agent evidence lineage is invalid: " + violation.get()
            );
        }
        var semanticViolation = AgentContractSemantics.isAcceptanceReview(document.get())
                ? AgentContractSemantics.validateOutputContract(document.get()) : java.util.Optional.<ContractViolation>empty();
        if (semanticViolation.isPresent()) {
            return EntryRead.invalid(semanticViolation.get().errorCode(), semanticViolation.get().message());
        }
        return EntryRead.valid(new Entry(path.toAbsolutePath().normalize(), document.get(), lastModified(path)));
    }

    private static Instant lastModified(Path path) {
        try {
            return Files.getLastModifiedTime(path).toInstant();
        } catch (IOException ignored) {
            return Instant.EPOCH;
        }
    }

    private static String relativeRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize())
                .toString();
    }

    private static String normalizeRef(String value) {
        return value == null ? "" : value.replace('\\', '/');
    }

    record Entry(
            Path path,
            AgentOutputContractDocument document,
            Instant lastModified
    ) {
        private static final Comparator<Entry> ORDER = Comparator
                .comparing(Entry::lastModified)
                .thenComparing(entry -> entry.path().toString());

        Map<String, Object> evidenceState() {
            return AgentEvidenceState.from(document).toMap();
        }
    }

    record DecisionRead(
            Entry entry,
            String errorCode,
            String message,
            String path,
            boolean missing
    ) {
        static DecisionRead valid(Entry entry, String path) {
            return new DecisionRead(entry, "", "", path, false);
        }

        static DecisionRead invalid(String code, String message, String path) {
            return new DecisionRead(null, code, message, path, false);
        }

        static DecisionRead notFound() {
            return new DecisionRead(null, "", "", "", true);
        }
    }

    private record EntryRead(Entry entry, String errorCode, String message) {
        static EntryRead valid(Entry entry) {
            return new EntryRead(entry, "", "");
        }

        static EntryRead invalid(String code, String message) {
            return new EntryRead(null, code, message);
        }
    }
}

package dev.dual.runtime.handler;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

record AgentEvidenceState(
        boolean blocking,
        int evidenceCount,
        int missingEvidenceCount,
        int mustFixCount,
        int acceptanceNoteCount,
        int openRiskCount
) {
    static AgentEvidenceState from(AgentOutputContractDocument document) {
        return new AgentEvidenceState(
                document.blocking(),
                document.evidence().size(),
                document.missingEvidence().size(),
                document.mustFix().size(),
                document.acceptanceNotes().size(),
                document.openRisks().size()
        );
    }

    static AgentEvidenceState fromSidecar(Map<String, Object> document) {
        return new AgentEvidenceState(
                booleanValue(document.get("blocking")),
                listSize(document.get("evidence")),
                listSize(document.get("missing_evidence")),
                listSize(document.get("must_fix")),
                listSize(document.get("acceptance_notes")),
                listSize(document.get("open_risks"))
        );
    }

    boolean hasBlockingDecisionIssues() {
        return blocking || mustFixCount > 0;
    }

    boolean hasMaterialEvidenceGaps() {
        return missingEvidenceCount > 0;
    }

    boolean hasFinalAcceptanceConflicts() {
        return hasBlockingDecisionIssues() || hasMaterialEvidenceGaps();
    }

    boolean hasBlockingIssues() {
        return hasBlockingDecisionIssues() || hasMaterialEvidenceGaps();
    }

    Map<String, Object> toMap() {
        var result = new LinkedHashMap<String, Object>();
        result.put("blocking", blocking);
        result.put("evidence_count", evidenceCount);
        result.put("missing_evidence_count", missingEvidenceCount);
        result.put("must_fix_count", mustFixCount);
        result.put("acceptance_note_count", acceptanceNoteCount);
        result.put("open_risk_count", openRiskCount);
        return result;
    }

    private static int listSize(Object value) {
        return value instanceof List<?> list ? list.size() : 0;
    }

    private static boolean booleanValue(Object value) {
        if (value instanceof Boolean bool) {
            return bool;
        }
        return value != null && Boolean.parseBoolean(String.valueOf(value));
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.execution.ArtifactContractResult;
import dev.dual.core.execution.AgentResultContractResult;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class AgentExecutionResultFacts {
    static final String AGENT_RESULT_CONTRACT = "agent_execution_result_contract";
    static final String ARTIFACT_CONTRACT_RESULTS = "agent_execution_artifact_contract_results";
    static final String REREAD_REASONS = "reread_reasons";

    private AgentExecutionResultFacts() {
    }

    /** Closed, machine-owned input rejection. No provider result or arbitrary metadata can enter here. */
    public static NodeResult inputPreparationFailed(String reason, String code, List<String> details) {
        if (reason == null || reason.isBlank() || code == null || code.isBlank()
                || details == null || details.isEmpty()) {
            throw new IllegalArgumentException("input rejection requires reason, code and details");
        }
        var errors = List.copyOf(details);
        return new NodeResult(reason, NodeStatus.FAILED, List.of(), Map.of(
                "reason", reason, "failure_code", code, "errors", errors,
                "input_preparation_failure", Map.of("reason", reason, "code", code, "details", errors,
                        "providerInvoked", false, "retryPolicy", "MANUAL_ONLY")), String.join("; ", errors));
    }

    /** Reject contradictory facts instead of letting a phase marker become a publication bypass. */
    static boolean inputPreparationFailed(NodeResult result) {
        if (!result.result().containsKey("input_preparation_failure")) return false;
        if (!(result.result().get("input_preparation_failure") instanceof Map<?, ?> failure)
                || !(failure.get("reason") instanceof String reason)
                || !(failure.get("code") instanceof String code)
                || !(failure.get("details") instanceof List<?> details)
                || details.stream().anyMatch(item -> !(item instanceof String))) {
            throw new IllegalArgumentException("invalid input preparation failure fact");
        }
        var expected = inputPreparationFailed(reason, code, details.stream().map(String.class::cast).toList());
        if (!expected.equals(result)) {
            throw new IllegalArgumentException("input preparation failure contradicts node result or execution evidence");
        }
        return true;
    }

    /** Carry an acquisition rejection to publication using the existing terminal contract fact. */
    public static NodeResult rejectAgentResult(NodeResult result, String message) {
        return attach(new NodeResult("AGENT_OUTPUT_CONTRACT_VIOLATION", NodeStatus.FAILED,
                        result.outputRefs(), result.result(), message),
                AgentResultContractResult.invalid(message), List.of(), null);
    }

    static NodeResult attach(
            NodeResult result,
            AgentResultContractResult agentResultContract,
            List<ArtifactContractResult> artifactContractResults,
            Object rereadReasons
    ) {
        var facts = new LinkedHashMap<String, Object>();
        facts.putAll(result.result());
        facts.put(AGENT_RESULT_CONTRACT, agentResultContractToMap(agentResultContract));
        facts.put(ARTIFACT_CONTRACT_RESULTS, artifactContractResults.stream()
                .map(AgentExecutionResultFacts::artifactContractToMap)
                .toList());
        if (rereadReasons != null) {
            facts.put(REREAD_REASONS, rereadReasons);
        }
        return new NodeResult(result.outcome(), result.status(), result.outputRefs(), facts, result.errorMessage());
    }

    static AgentResultContractResult agentResultContract(NodeResult result) {
        var value = result.result().get(AGENT_RESULT_CONTRACT);
        if (value instanceof Map<?, ?> map) {
            return new AgentResultContractResult(
                    booleanValue(map.get("present")),
                    booleanValue(map.get("valid")),
                    text(map.get("decision")),
                    text(map.get("summary")),
                    text(map.get("validationError"))
            );
        }
        return AgentResultContractResult.missing();
    }

    static List<ArtifactContractResult> artifactContractResults(NodeResult result) {
        var value = result.result().get(ARTIFACT_CONTRACT_RESULTS);
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        var results = new ArrayList<ArtifactContractResult>();
        for (var item : list) {
            if (item instanceof Map<?, ?> map) {
                results.add(new ArtifactContractResult(
                        text(map.get("contractType")),
                        booleanValue(map.get("required")),
                        booleanValue(map.get("present")),
                        booleanValue(map.get("valid")),
                        text(map.get("path")),
                        text(map.get("errorCode")),
                        text(map.get("errorMessage"))
                ));
            }
        }
        return List.copyOf(results);
    }

    static Object rereadReasons(NodeResult result) {
        return result.result().get(REREAD_REASONS);
    }

    static boolean present(NodeResult result) {
        return result.result().containsKey(AGENT_RESULT_CONTRACT)
                || result.result().containsKey(ARTIFACT_CONTRACT_RESULTS)
                || (result.result().containsKey("run_metadata")
                && result.result().containsKey("process_usability"));
    }

    static Map<String, Object> agentResultContractToMap(AgentResultContractResult result) {
        var map = new LinkedHashMap<String, Object>();
        map.put("present", result.present());
        map.put("valid", result.valid());
        map.put("decision", result.decision());
        map.put("summary", result.summary());
        map.put("validationError", result.validationError());
        return map;
    }

    static Map<String, Object> artifactContractToMap(ArtifactContractResult artifact) {
        var map = new LinkedHashMap<String, Object>();
        map.put("contractType", artifact.contractType());
        map.put("required", artifact.required());
        map.put("present", artifact.present());
        map.put("valid", artifact.valid());
        map.put("path", artifact.path());
        map.put("errorCode", artifact.errorCode());
        map.put("errorMessage", artifact.errorMessage());
        return map;
    }

    private static boolean booleanValue(Object value) {
        return value instanceof Boolean bool && bool;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.contract.TaskContract;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Typed reader for agent output sidecars.
 *
 * Map-based JSON handling is kept at this boundary. Runtime routing,
 * classification, and human guidance should consume this record instead of
 * repeatedly reading stringly-typed fields from raw maps.
 */
public record AgentOutputContractDocument(
        String workstreamId,
        String runId,
        String nodeId,
        String nodeInstanceId,
        String stageOutcome,
        String lifecycleStatus,
        String decision,
        String summary,
        String sourceArtifactType,
        String sourceOutputRef,
        boolean blocking,
        List<String> checks,
        List<String> evidence,
        List<String> mustFix,
        List<AgentResultEnvelope.ReviewObligation> contractObligations,
        List<String> missingEvidence,
        List<String> acceptanceNotes,
        List<String> openRisks,
        List<String> changedFiles,
        String verificationSummary,
        List<String> completedWork,
        List<String> importantDecisions,
        String recommendedNextStage,
        String suggestedNextPrompt,
        Map<String, String> control,
        FailureFields failure,
        List<RereadReason> rereadReasons,
        TaskContractProposalReference reviewSubject,
        TaskContractProposal taskContractProposal,
        RepositoryFactBinding.Reference repositoryFactBinding,
        ProposalDerivation proposalDerivation,
        PlanArtifactDocument planArtifact,
        AgentResultEnvelope.Design design,
        List<AgentResultEnvelope.AuthoredRevisionResponse> authoredRevisionResponses,
        AuthoredExecutionContext.Reference authoredContext,
        List<AgentResultEnvelope.VerificationCheck> verificationChecks
) {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    static Optional<AgentOutputContractDocument> read(Path path, ObjectMapper objectMapper) {
        try {
            return Optional.of(from(objectMapper.readValue(path.toFile(), MAP_TYPE)));
        } catch (IOException | RuntimeException e) {
            return Optional.empty();
        }
    }

    public static AgentOutputContractDocument from(Map<String, Object> document) {
        return new AgentOutputContractDocument(
                text(document.get("workstream_id")),
                text(document.get("run_id")),
                text(document.get("node_id")),
                text(document.get("node_instance_id")),
                firstNonBlank(document.get("stage_outcome"), document.get("lifecycle_status")),
                text(document.get("lifecycle_status")),
                text(document.get("decision")),
                text(document.get("summary")),
                text(document.get("source_artifact_type")),
                text(document.get("source_output_ref")),
                booleanValue(document.get("blocking")),
                firstNonEmptyList(document.get("checks"), document.get("checks_run")),
                stringList(document.get("evidence")),
                stringList(document.get("must_fix")),
                reviewObligationList(document.get("contract_obligations")),
                stringList(document.get("missing_evidence")),
                stringList(document.get("acceptance_notes")),
                stringList(document.get("open_risks")),
                stringList(document.get("changed_files")),
                text(document.get("verification_summary")),
                stringList(document.get("completed_work")),
                stringList(document.get("important_decisions")),
                text(document.get("recommended_next_stage")),
                text(document.get("suggested_next_prompt")),
                stringMap(document.get("control")),
                FailureFields.from(objectMap(document.get("failure"))),
                rereadReasonList(document.get("reread_reasons")),
                TaskContractProposalReference.fromMap(objectMap(document.get("review_subject"))).orElse(null),
                taskContractProposal(objectMap(document.get("task_contract_proposal"))),
                RepositoryFactBinding.Reference.fromMap(objectMap(document.get("repository_fact_binding"))),
                ProposalDerivation.from(objectMap(document.get("proposal_derivation"))),
                planArtifact(objectMap(document.get("plan_artifact"))),
                design(objectMap(document.get("design"))),
                authoredResponses(document.get("revision_responses")),
                authoredReference(document.get("authored_context")),
                verificationChecks(document.get("verification_checks"))
        );
    }

    public record ProposalDerivation(
            String kind,
            String baseProposalId,
            String baseProposalSha256,
            TaskContractProposalReference baseProposalReference,
            String patchSourceOutputRef
    ) {
        static ProposalDerivation from(Map<String, Object> document) {
            if (document.isEmpty()) {
                return null;
            }
            return new ProposalDerivation(
                    text(document.get("kind")),
                    text(document.get("base_proposal_id")),
                    text(document.get("base_proposal_sha256")),
                    TaskContractProposalReference.fromMap(
                            objectMap(document.get("base_proposal_reference"))).orElse(null),
                    text(document.get("patch_source_output_ref")));
        }

        boolean validFor(TaskContractProposalReference reference, String sourceOutputRef) {
            return "revision_patch_merge".equals(kind)
                    && reference != null
                    && reference.proposalId().equals(baseProposalId)
                    && reference.sha256().equals(baseProposalSha256)
                    && reference.equals(baseProposalReference)
                    && sourceOutputRef != null
                    && sourceOutputRef.equals(patchSourceOutputRef);
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("kind", kind);
            map.put("base_proposal_id", baseProposalId);
            map.put("base_proposal_sha256", baseProposalSha256);
            map.put("base_proposal_reference", baseProposalReference.toMap());
            map.put("patch_source_output_ref", patchSourceOutputRef);
            return Map.copyOf(map);
        }
    }

    public boolean hasValidatedLineage(String expectedWorkstreamId) {
        var normalizedSource = sourceOutputRef.replace('\\', '/');
        return expectedWorkstreamId != null
                && !expectedWorkstreamId.isBlank()
                && expectedWorkstreamId.equals(workstreamId)
                && !runId.isBlank()
                && !nodeId.isBlank()
                && !nodeInstanceId.isBlank()
                && normalizedSource.contains("/runs/" + runId + "/");
    }

    public boolean hasValidatedLineage(
            String expectedWorkstreamId,
            Path workspaceRoot,
            Path sidecarPath
    ) {
        if (!hasValidatedLineage(expectedWorkstreamId)
                || workspaceRoot == null
                || sidecarPath == null) {
            return false;
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var source = root.resolve(sourceOutputRef).normalize();
        if (!source.startsWith(root)) {
            return false;
        }
        return AgentOutputContractSidecar.pathFor(source)
                .equals(sidecarPath.toAbsolutePath().normalize());
    }

    public boolean hasDecision() {
        return !decision.isBlank();
    }

    public String canonicalStageOutcome() {
        return stageOutcome.isBlank() ? lifecycleStatus : stageOutcome;
    }

    public boolean hasRequiredTypedPayload() {
        if (("design_result".equals(sourceArtifactType) || "plan_result".equals(sourceArtifactType))
                && !AuthoredRevisionValidator.shapeErrors(authoredRevisionResponses).isEmpty()) return false;
        if ("design_result".equals(sourceArtifactType)) {
            return DesignScopeValidator.shapeErrors(design).isEmpty();
        }
        if (!"plan_result".equals(sourceArtifactType)) {
            return true;
        }
        return planArtifact != null
                && "plan_artifact".equals(planArtifact.artifactType())
                && planArtifact.schemaVersion() == 2
                && planArtifact.missingRequiredField().isEmpty();
    }

    private static PlanArtifactDocument planArtifact(Map<String, Object> document) {
        return document.isEmpty() ? null : PlanArtifactDocument.from(document);
    }

    private static AuthoredExecutionContext.Reference authoredReference(Object value) {
        if (value == null) return null;
        return AuthoredExecutionContext.JSON.convertValue(value, AuthoredExecutionContext.Reference.class);
    }

    private static List<AgentResultEnvelope.VerificationCheck> verificationChecks(Object value) {
        if (value == null) return List.of();
        return AuthoredExecutionContext.JSON.convertValue(value, new TypeReference<List<AgentResultEnvelope.VerificationCheck>>() {});
    }

    private static List<AgentResultEnvelope.AuthoredRevisionResponse> authoredResponses(Object value) {
        if (!(value instanceof List<?> values)) return null;
        var result = new ArrayList<AgentResultEnvelope.AuthoredRevisionResponse>();
        for (var entry : values) {
            var map = objectMap(entry);
            result.add(new AgentResultEnvelope.AuthoredRevisionResponse(text(map.get("obligation_id")),
                    AgentResultEnvelope.AuthoredRevisionDisposition.valueOf(text(map.get("disposition"))), text(map.get("evidence"))));
        }
        return List.copyOf(result);
    }

    private static AgentResultEnvelope.Design design(Map<String, Object> document) {
        if (!(document.get("planned_files") instanceof List<?> files)) {
            return null;
        }
        var planned = new ArrayList<AgentResultEnvelope.PlannedFile>();
        for (var value : files) {
            var file = objectMap(value);
            TaskContract.ScopeOperation operation = null;
            try {
                operation = TaskContract.ScopeOperation.valueOf(text(file.get("operation")));
            } catch (IllegalArgumentException ignored) {
                // Invalid operations remain invalid, never inferred from the path.
            }
            planned.add(new AgentResultEnvelope.PlannedFile(
                    file.get("path") instanceof String path ? path : null,
                    operation, file.get("responsibility") instanceof String responsibility ? responsibility : null));
        }
        return new AgentResultEnvelope.Design(List.copyOf(planned));
    }

    private static TaskContractProposal taskContractProposal(Map<String, Object> document) {
        if (document.isEmpty()) {
            return null;
        }
        var scope = objectMap(document.get("scope"));
        return new TaskContractProposal(
                text(document.get("artifact_type")),
                integerValue(document.get("schema_version")),
                text(document.get("objective")),
                new TaskContractProposal.Scope(
                        scopeEntries(scope.get("included")),
                        stringList(scope.get("excluded"))),
                contractClauseList(document.get("acceptance_criteria")),
                contractClauseList(document.get("test_requirements")),
                contractClauseList(document.get("constraints")),
                contractClauseList(document.get("non_goals")),
                contractClauseList(document.get("risk_areas")),
                stringList(document.get("evidence_refs")),
                stringList(document.get("open_questions")),
                revisionResponseList(document.get("revision_responses")));
    }

    private static List<TaskContract.ScopeEntry> scopeEntries(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var entries = new ArrayList<TaskContract.ScopeEntry>();
        for (var item : items) {
            var entry = objectMap(item);
            var path = text(entry.get("path"));
            TaskContract.ScopeOperation operation = null;
            try {
                operation = TaskContract.ScopeOperation.valueOf(text(entry.get("operation")));
            } catch (IllegalArgumentException ignored) {
                // The proposal validator reports the missing/invalid operation.
            }
            entries.add(new TaskContract.ScopeEntry(path, operation));
        }
        return List.copyOf(entries);
    }

    boolean isStageHandoffArtifact() {
        return "stage_handoff".equals(sourceArtifactType);
    }

    record FailureFields(
            String categoryHint,
            AgentResultEnvelope.VerificationRemediation verificationRemediation,
            List<String> contractGaps,
            List<String> outOfScopeFiles,
            List<String> missingTests,
            List<String> contextGaps,
            String reason
    ) {
        static FailureFields from(Map<String, Object> document) {
            return new FailureFields(
                    document.get("category_hint") instanceof String category ? category : "",
                    verificationRemediation(document.get("verification_remediation")),
                    stringList(document.get("contract_gaps")),
                    stringList(document.get("out_of_scope_files")),
                    stringList(document.get("missing_tests")),
                    stringList(document.get("context_gaps")),
                    text(document.get("reason"))
            );
        }

        static FailureFields empty() {
            return new FailureFields("", AgentResultEnvelope.VerificationRemediation.NONE,
                    List.of(), List.of(), List.of(), List.of(), "");
        }

        Map<String, Object> toMap() {
            var document = new LinkedHashMap<String, Object>();
            document.put("category_hint", categoryHint);
            document.put("verification_remediation", verificationRemediation == null
                    ? "" : verificationRemediation.name());
            document.put("contract_gaps", contractGaps);
            document.put("out_of_scope_files", outOfScopeFiles);
            document.put("missing_tests", missingTests);
            document.put("context_gaps", contextGaps);
            document.put("reason", reason);
            return document;
        }

        boolean isEmpty() {
            return categoryHint.isBlank()
                    && (verificationRemediation == null
                    || verificationRemediation == AgentResultEnvelope.VerificationRemediation.NONE)
                    && contractGaps.isEmpty()
                    && outOfScopeFiles.isEmpty()
                    && missingTests.isEmpty()
                    && contextGaps.isEmpty()
                    && reason.isBlank();
        }

        private static AgentResultEnvelope.VerificationRemediation verificationRemediation(Object value) {
            var text = value == null ? "" : String.valueOf(value);
            if (text.isEmpty()) {
                return null;
            }
            try {
                return AgentResultEnvelope.VerificationRemediation.valueOf(text);
            } catch (IllegalArgumentException invalid) {
                throw new IllegalArgumentException("Unknown verification_remediation: " + text, invalid);
            }
        }
    }

    /**
     * One declared reason an agent re-read a file already covered by the read-reuse
     * contract. Optional structured field; presence is validated against the
     * allowed-reason catalog (see {@code ReadReuseContractReasons}).
     */
    public record RereadReason(String path, String reason, String stage, String evidence) {
        static RereadReason from(Map<String, Object> document) {
            return new RereadReason(
                    text(document.get("path")),
                    text(document.get("reason")),
                    text(document.get("stage")),
                    text(document.get("evidence")));
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("path", path);
            map.put("reason", reason);
            map.put("stage", stage);
            map.put("evidence", evidence);
            return map;
        }
    }

    static List<RereadReason> rereadReasonList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        var out = new ArrayList<RereadReason>();
        for (var item : list) {
            if (item instanceof Map<?, ?> map) {
                var copy = new LinkedHashMap<String, Object>();
                for (var e : map.entrySet()) {
                    if (e.getKey() instanceof String key) {
                        copy.put(key, e.getValue());
                    }
                }
                out.add(RereadReason.from(copy));
            }
        }
        return List.copyOf(out);
    }

    private static List<TaskContractProposal.ContractClause> contractClauseList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var clauses = new ArrayList<TaskContractProposal.ContractClause>();
        for (var item : items) {
            var document = objectMap(item);
            if (!document.isEmpty()) {
                clauses.add(new TaskContractProposal.ContractClause(
                        text(document.get("id")), text(document.get("text"))));
            }
        }
        return List.copyOf(clauses);
    }

    private static List<TaskContractProposal.RevisionResponse> revisionResponseList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var responses = new ArrayList<TaskContractProposal.RevisionResponse>();
        for (var item : items) {
            var document = objectMap(item);
            if (!document.isEmpty()) {
                responses.add(new TaskContractProposal.RevisionResponse(
                        text(document.get("review_obligation_id")),
                        stringList(document.get("resolved_by_clause_ids"))));
            }
        }
        return List.copyOf(responses);
    }

    private static List<AgentResultEnvelope.ReviewObligation> reviewObligationList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var obligations = new ArrayList<AgentResultEnvelope.ReviewObligation>();
        for (var item : items) {
            var document = objectMap(item);
            if (!document.isEmpty()) {
                obligations.add(new AgentResultEnvelope.ReviewObligation(
                        text(document.get("id")), text(document.get("text"))));
            }
        }
        return List.copyOf(obligations);
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : items) {
            var text = text(item);
            if (!text.isBlank()) {
                result.add(text);
            }
        }
        return List.copyOf(result);
    }

    private static List<String> firstNonEmptyList(Object first, Object second) {
        var firstList = stringList(first);
        return firstList.isEmpty() ? stringList(second) : firstList;
    }

    private static Map<String, String> stringMap(Object value) {
        if (!(value instanceof Map<?, ?> source)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, String>();
        for (var entry : source.entrySet()) {
            if (entry.getKey() != null && entry.getValue() != null) {
                copy.put(String.valueOf(entry.getKey()), String.valueOf(entry.getValue()));
            }
        }
        return copy;
    }

    private static Map<String, Object> objectMap(Object value) {
        if (!(value instanceof Map<?, ?> source)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (var entry : source.entrySet()) {
            if (entry.getKey() instanceof String key) {
                copy.put(key, entry.getValue());
            }
        }
        return copy;
    }

    private static boolean booleanValue(Object value) {
        if (value instanceof Boolean bool) {
            return bool;
        }
        return Boolean.parseBoolean(text(value));
    }

    private static int integerValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static String firstNonBlank(Object first, Object second) {
        var firstText = text(first);
        return firstText.isBlank() ? text(second) : firstText;
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.Optional;

public final class AgentOutputContractSidecar {
    private AgentOutputContractSidecar() {
    }

    public static Path pathFor(Path outputPath) {
        var fileName = outputPath.getFileName().toString();
        var baseName = fileName.endsWith(".md")
                ? fileName.substring(0, fileName.length() - 3)
                : fileName.endsWith(".json")
                ? fileName.substring(0, fileName.length() - 5)
                : fileName;
        var sidecarName = baseName + ".contract.json";
        return outputPath.resolveSibling(sidecarName);
    }

    public static Optional<AgentOutputContractDocument> read(Path outputPath, ObjectMapper objectMapper) {
        if (outputPath == null) {
            return Optional.empty();
        }
        return AgentOutputContractDocument.read(pathFor(outputPath), objectMapper);
    }

    public static String sha256(Path sidecarPath) {
        try {
            return HexFormat.of().formatHex(
                    MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(sidecarPath)));
        } catch (Exception e) {
            throw new IllegalStateException("failed to hash agent output sidecar: " + sidecarPath, e);
        }
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.NodeExecutionStatus;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;

import java.nio.file.Path;
import java.util.Optional;

/** Binds a projected agent-result sidecar to its authoritative ledger occurrence. */
final class AgentOutputLineageVerifier {
    private AgentOutputLineageVerifier() {
    }

    static Optional<String> violation(
            WorkflowFileLedger assembledLedger,
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            AgentOutputContractDocument document
    ) {
        if (!document.hasValidatedLineage(workstreamId, workspaceRoot, sidecarPath)) {
            return Optional.of("sidecar fields or source path are not internally consistent");
        }
        try {
            var paths = new WorkstreamPaths(workspaceRoot, new DualId(workstreamId));
            return assembledLedger.inspect(paths, (ledger, files) -> {
            var node = ledger.loadNode(paths, document.nodeInstanceId());
            if (!document.nodeId().equals(node.nodeDefinitionId())) {
                return Optional.of("sidecar node_id does not match the ledger node occurrence");
            }
            if (node.status() != NodeStatus.COMPLETED) {
                return Optional.of("sidecar node occurrence is not completed");
            }
            var sidecarRef = relativeRef(workspaceRoot, sidecarPath);
            if (!containsRef(node.outputRefs(), document.sourceOutputRef())
                    || !containsRef(node.outputRefs(), sidecarRef)) {
                return Optional.of("sidecar source is not published by the ledger node occurrence");
            }
            if (!document.runId().equals(text(node.result().get("run_id")))) {
                return Optional.of("sidecar run_id does not match the ledger node result");
            }
            if (!document.decision().equals(text(node.result().get("decision")))) {
                return Optional.of("sidecar decision does not match the ledger node result");
            }
            var expectedHash = text(node.result().get("contract_sidecar_sha256"));
            if (expectedHash.isBlank()
                    || !expectedHash.equals(AgentOutputContractSidecar.sha256(sidecarPath))) {
                return Optional.of("sidecar content hash does not match the ledger node result");
            }
            var execution = ledger.latestNodeExecution(paths, node);
            if (execution.isEmpty()) {
                return Optional.of("sidecar node occurrence has no execution fact");
            }
            var actual = execution.get();
            if (actual.status() != NodeExecutionStatus.SUCCEEDED
                    || !document.nodeInstanceId().equals(actual.nodeInstanceId())
                    || !document.nodeId().equals(actual.nodeDefinitionId())
                    || !document.runId().equals(actual.runRef())) {
                return Optional.of("sidecar lineage does not match the successful node execution");
            }
            if (!containsRef(actual.outputRefs(), document.sourceOutputRef())
                    || !containsRef(actual.outputRefs(), sidecarRef)) {
                return Optional.of("sidecar source is not published by the node execution");
            }
            if (!document.decision().equals(text(actual.result().get("decision")))) {
                return Optional.of("sidecar decision does not match the node execution result");
            }
            if (!expectedHash.equals(text(actual.result().get("contract_sidecar_sha256")))) {
                return Optional.of("sidecar content hash does not match the node execution result");
            }
            return Optional.empty();
            });
        } catch (Exception e) {
            return Optional.of("sidecar ledger occurrence cannot be resolved: " + e.getMessage());
        }
    }

    private static String relativeRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize())
                .toString();
    }

    private static boolean containsRef(java.util.List<String> refs, String expected) {
        var normalized = normalize(expected);
        return refs.stream().map(AgentOutputLineageVerifier::normalize).anyMatch(normalized::equals);
    }

    private static String normalize(String value) {
        return value == null ? "" : value.replace('\\', '/');
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.handler;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Projects one validated agent result into the existing durable read models. */
final class AgentResultDocumentProjector {
    Map<String, Object> outputContract(
            AgentResultEnvelope envelope,
            NodeOutputContract contract,
            String handlerType,
            String nodeInstanceId,
            String sourceOutputRef
    ) {
        return outputContract(envelope, contract, handlerType, nodeInstanceId, sourceOutputRef, null, null);
    }

    Map<String, Object> outputContract(
            AgentResultEnvelope envelope,
            NodeOutputContract contract,
            String handlerType,
            String nodeInstanceId,
            String sourceOutputRef,
            TaskContractProposal resolvedProposal,
            AgentOutputContractDocument.ProposalDerivation derivation
    ) {
        var result = envelope.result();
        var document = new LinkedHashMap<String, Object>();
        document.put("artifact_type", "agent_output_contract");
        document.put("schema_version", 1);
        document.put("workstream_id", envelope.workstreamId());
        document.put("run_id", envelope.runId());
        document.put("node_id", envelope.nodeId());
        document.put("node_instance_id", nodeInstanceId == null ? "" : nodeInstanceId);
        document.put("handler_type", handlerType);
        document.put("decision", result.decision());
        document.put("summary", result.summary());
        document.put("required_keys", List.copyOf(contract.requiredKeys()));
        document.put("allowed_decisions", List.copyOf(contract.allowedDecisions()));
        document.put("source_output_ref", sourceOutputRef);
        document.put("source_artifact_type", result.artifactType());
        document.put("generated_at", Instant.now().toString());
        document.put("control", Map.of("decision", result.decision(), "summary", result.summary()));
        document.put("control_source", Map.of("kind", "strict_agent_result_envelope"));

        switch (result) {
            case AgentResultEnvelope.TaskContractProposalResult ignored -> {
                if (resolvedProposal == null) {
                    throw new IllegalStateException("initial proposal must be scope-resolved before projection");
                }
                evidenceDefaults(document);
                document.put("task_contract_proposal", taskContractProposalMap(resolvedProposal));
            }
            case AgentResultEnvelope.TaskContractRevisionPatchResult ignored -> {
                if (resolvedProposal == null || derivation == null) {
                    throw new IllegalStateException("revision patch must be merged before projection");
                }
                evidenceDefaults(document);
                document.put("task_contract_proposal", taskContractProposalMap(resolvedProposal));
                document.put("proposal_derivation", derivation.toMap());
            }
            case AgentResultEnvelope.AgentOutputResult output -> {
                evidenceFields(document, output.lifecycleStatus(), output.blocking(), output.checks(), output.evidence(),
                        output.missingEvidence(), output.mustFix(), output.acceptanceNotes(), output.openRisks(),
                        output.changedFiles(), output.verificationSummary(), output.failure());
                document.put("contract_obligations", safeList(output.contractObligations()).stream()
                        .map(obligation -> Map.of("id", obligation.id(), "text", obligation.text()))
                        .toList());
                document.put("reread_reasons", output.rereadReasons().stream().map(this::rereadReason).toList());
            }
            case AgentResultEnvelope.DesignResult design -> {
                document.put("revision_responses", authoredResponses(design.revisionResponses()));
                document.put("lifecycle_status", design.lifecycleStatus());
                document.put("checks", design.checks());
                document.put("evidence", design.evidence());
                document.put("missing_evidence", design.missingEvidence());
                document.put("must_fix", design.mustFix());
                document.put("open_risks", design.openRisks());
                document.put("verification_summary", design.verificationSummary());
                document.put("design", Map.of("planned_files", design.design().plannedFiles().stream()
                        .map(file -> Map.of("path", file.path(), "operation", file.operation().name(),
                                "responsibility", file.responsibility())).toList()));
            }
            case AgentResultEnvelope.PlanResult plan -> {
                document.put("revision_responses", authoredResponses(plan.revisionResponses()));
                evidenceFields(
                        document, plan.lifecycleStatus(), plan.blocking(), plan.checks(), plan.evidence(),
                        plan.missingEvidence(), plan.mustFix(), plan.acceptanceNotes(), plan.openRisks(),
                        plan.changedFiles(), plan.verificationSummary(), plan.failure());
                document.put("plan_artifact", planArtifact(plan));
            }
            case AgentResultEnvelope.SelfTestResult selfTest -> {
                document.put("verification_checks", selfTest.verificationChecks());
                document.put("lifecycle_status", selfTest.lifecycleStatus());
                document.put("blocking", false);
                document.put("checks_run", selfTest.checksRun());
                document.put("checks_skipped", selfTest.checksSkipped());
                document.put("evidence", selfTest.evidence());
                document.put("missing_evidence", selfTest.missingEvidence());
                document.put("must_fix", selfTest.mustFix());
                document.put("acceptance_notes", selfTest.acceptanceNotes());
                document.put("verification_summary", selfTest.verificationSummary());
                evidenceDefaultsIfAbsent(document);
            }
            case AgentResultEnvelope.AcceptanceReviewResult review -> {
                document.put("verification_checks", review.verificationChecks());
                evidenceFields(
                    document, review.lifecycleStatus(), review.blocking(), review.checks(), review.evidence(),
                    review.missingEvidence(), review.mustFix(), review.acceptanceNotes(), review.openRisks(),
                    review.changedFiles(), review.verificationSummary(), review.failure());
            }
            case AgentResultEnvelope.StageHandoffResult handoff -> {
                document.put("lifecycle_status", handoff.lifecycleStatus());
                document.put("blocking", false);
                document.put("completed_work", handoff.completedWork());
                document.put("important_decisions", handoff.importantDecisions());
                document.put("changed_files", handoff.changedFiles());
                document.put("verification_summary", handoff.verificationState());
                document.put("open_risks", handoff.openRisks());
                document.put("recommended_next_stage", handoff.recommendedNextStage());
                document.put("suggested_next_prompt", handoff.suggestedNextPrompt());
                evidenceDefaultsIfAbsent(document);
            }
        }
        return document;
    }

    private Map<String, Object> taskContractProposalMap(TaskContractProposal proposal) {
        var document = new LinkedHashMap<String, Object>();
        document.put("artifact_type", proposal.artifactType());
        document.put("schema_version", proposal.schemaVersion());
        document.put("objective", proposal.objective());
        document.put("scope", Map.of(
                "included", proposal.scope().included().stream()
                        .map(entry -> Map.of("path", entry.path(), "operation", entry.operation().name()))
                        .toList(),
                "excluded", proposal.scope().excluded()));
        document.put("acceptance_criteria", clauseMapsFromProposal(proposal.acceptanceCriteria()));
        document.put("test_requirements", clauseMapsFromProposal(proposal.testRequirements()));
        document.put("constraints", clauseMapsFromProposal(proposal.constraints()));
        document.put("non_goals", clauseMapsFromProposal(proposal.nonGoals()));
        document.put("risk_areas", clauseMapsFromProposal(proposal.riskAreas()));
        document.put("evidence_refs", proposal.evidenceRefs());
        document.put("open_questions", proposal.openQuestions());
        document.put("revision_responses", proposal.revisionResponses().stream()
                .map(response -> Map.of(
                        "review_obligation_id", response.reviewObligationId(),
                        "resolved_by_clause_ids", response.resolvedByClauseIds()))
                .toList());
        return document;
    }

    private static List<Map<String, String>> clauseMapsFromProposal(
            List<TaskContractProposal.ContractClause> clauses
    ) {
        return safeList(clauses).stream()
                .map(clause -> Map.of("id", clause.id(), "text", clause.text()))
                .toList();
    }

    TaskContractProposal taskContractProposal(
            AgentResultEnvelope.TaskContractProposalResult result,
            List<dev.dual.core.contract.TaskContract.ScopeEntry> resolvedScope
    ) {
        return new TaskContractProposal(
                result.artifactType(),
                TaskContractProposal.SCHEMA_VERSION,
                result.objective(),
                new TaskContractProposal.Scope(resolvedScope, result.scope().excluded()),
                proposalClauses(result.acceptanceCriteria()),
                proposalClauses(result.testRequirements()),
                proposalClauses(result.constraints()),
                proposalClauses(result.nonGoals()),
                proposalClauses(result.riskAreas()),
                result.evidenceRefs(),
                result.openQuestions(),
                revisionResponses(result.revisionResponses())
        );
    }

    private static List<TaskContractProposal.ContractClause> proposalClauses(
            List<AgentResultEnvelope.ContractClause> clauses
    ) {
        return safeList(clauses).stream()
                .map(clause -> new TaskContractProposal.ContractClause(clause.id(), clause.text()))
                .toList();
    }

    private static List<TaskContractProposal.RevisionResponse> revisionResponses(
            List<AgentResultEnvelope.RevisionResponse> responses
    ) {
        return safeList(responses).stream()
                .map(response -> new TaskContractProposal.RevisionResponse(
                        response.reviewObligationId(), response.resolvedByClauseIds()))
                .toList();
    }

    private static List<Map<String, String>> clauseMaps(List<AgentResultEnvelope.ContractClause> clauses) {
        return safeList(clauses).stream()
                .map(clause -> Map.of("id", clause.id(), "text", clause.text()))
                .toList();
    }

    private static <T> List<T> safeList(List<T> values) {
        return values == null ? List.of() : values;
    }

    private List<Map<String, String>> authoredResponses(List<AgentResultEnvelope.AuthoredRevisionResponse> responses) {
        return responses.stream().map(response -> Map.of("obligation_id", response.obligationId(),
                "disposition", response.disposition().name(), "evidence", response.evidence())).toList();
    }

    Map<String, Object> planArtifact(AgentResultEnvelope.PlanResult result) {
        var plan = result.plan();
        var document = new LinkedHashMap<String, Object>();
        document.put("artifact_type", "plan_artifact");
        document.put("schema_version", 2);
        document.put("implementation_steps", plan.implementationSteps());
        document.put("edit_files", plan.editFiles());
        document.put("files", plan.files());
        document.put("verification_bindings", plan.verificationBindings());
        document.put("authority_refs", plan.authorityRefs());
        document.put("reference_files", plan.referenceFiles());
        document.put("file_level_changes", plan.fileLevelChanges());
        document.put("validation_plan", plan.validationPlan());
        document.put("rollback_notes", plan.rollbackNotes());
        document.put("known_risks", plan.knownRisks());
        document.put("human_review_checklist", plan.humanReviewChecklist());
        return document;
    }

    private void evidenceFields(
            Map<String, Object> document,
            String lifecycleStatus,
            boolean blocking,
            List<String> checks,
            List<String> evidence,
            List<String> missingEvidence,
            List<String> mustFix,
            List<String> acceptanceNotes,
            List<String> openRisks,
            List<String> changedFiles,
            String verificationSummary,
            AgentResultEnvelope.Failure failure
    ) {
        document.put("lifecycle_status", lifecycleStatus);
        document.put("blocking", blocking);
        document.put("checks", checks);
        document.put("evidence", evidence);
        document.put("missing_evidence", missingEvidence);
        document.put("must_fix", mustFix);
        document.put("acceptance_notes", acceptanceNotes);
        document.put("open_risks", openRisks);
        document.put("changed_files", changedFiles);
        document.put("verification_summary", verificationSummary);
        document.put("failure", failure(failure));
        document.put("checks_run", List.of());
        document.put("checks_skipped", List.of());
    }

    private static void evidenceDefaults(Map<String, Object> document) {
        document.put("blocking", false);
        document.put("checks_run", List.of("task_contract_proposal mechanical validation"));
        document.put("checks_skipped", List.of());
        document.put("evidence", List.of("canonical task_contract_proposal result"));
        document.put("missing_evidence", List.of());
        document.put("must_fix", List.of());
        document.put("acceptance_notes", List.of());
        document.put("open_risks", List.of());
        document.put("changed_files", List.of());
        document.put("verification_summary", "task contract proposal validated");
        document.put("failure", Map.of());
    }

    private static void evidenceDefaultsIfAbsent(Map<String, Object> document) {
        document.putIfAbsent("checks", List.of());
        document.putIfAbsent("checks_run", List.of());
        document.putIfAbsent("checks_skipped", List.of());
        document.putIfAbsent("evidence", List.of());
        document.putIfAbsent("missing_evidence", List.of());
        document.putIfAbsent("must_fix", List.of());
        document.putIfAbsent("acceptance_notes", List.of());
        document.putIfAbsent("open_risks", List.of());
        document.putIfAbsent("changed_files", List.of());
        document.putIfAbsent("failure", Map.of());
    }

    private Map<String, Object> failure(AgentResultEnvelope.Failure value) {
        if (value == null) {
            return Map.of();
        }
        var failure = new LinkedHashMap<String, Object>();
        failure.put("category_hint", value.categoryHint());
        failure.put("verification_remediation", value.verificationRemediation() == null
                ? "" : value.verificationRemediation().name());
        failure.put("contract_gaps", value.contractGaps());
        failure.put("out_of_scope_files", value.outOfScopeFiles());
        failure.put("missing_tests", value.missingTests());
        failure.put("context_gaps", value.contextGaps());
        failure.put("reason", value.reason());
        return failure;
    }

    private Map<String, Object> rereadReason(AgentResultEnvelope.RereadReason value) {
        var reason = new LinkedHashMap<String, Object>();
        reason.put("path", value.path());
        reason.put("reason", value.reason());
        reason.put("stage", value.stage());
        reason.put("evidence", value.evidence());
        return reason;
    }

}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import dev.dual.core.contract.TaskContract;
