    public static ProposalEmissionContext proposalEmissionContext(
            TaskContractRevisionContextResolver.Context context
    ) {
        if (context == null || !context.revision()) {
            return ProposalEmissionContext.initial();
        }
        if (context.previousReference() == null) {
            throw new IllegalArgumentException("revision proposal reference is required");
        }
        return new ProposalEmissionContext(
                EmissionMode.REVISION_PATCH,
                context.previousReference().proposalId(),
                context.previousReference().sha256(),
                List.copyOf(context.obligations()),
                context.lateRoot() == null ? "" : json(context.lateRoot())
                        + (context.scopeRevision() ? "\nSCOPE REVIEW ONLY: add only a subset of these bound CREATE candidates: "
                            + json(context.scopeReviewCandidates())
                            + ". Do not change clauses, evidence refs, objective, exclusions or any existing scope entry. "
                            + "These files already exist but remain CREATE relative to the original Git base. "
                            + "Respond to obligations using existing clause ids; keep clause_changes and evidence_ref_additions empty."
                            : ""));
    }

    public enum EmissionMode {
        INITIAL_FULL,
        REVISION_PATCH,
        NOT_APPLICABLE
    }

    public record ProposalEmissionContext(
            EmissionMode mode,
            String baseProposalId,
            String baseProposalSha256,
            List<AgentResultEnvelope.ReviewObligation> obligations,
            String acceptanceEvidence
    ) {
        public ProposalEmissionContext {
            obligations = obligations == null ? List.of() : List.copyOf(obligations);
            acceptanceEvidence = acceptanceEvidence == null ? "" : acceptanceEvidence;
        }

        public ProposalEmissionContext(EmissionMode mode, String baseProposalId, String baseProposalSha256,
                                       List<AgentResultEnvelope.ReviewObligation> obligations) {
            this(mode, baseProposalId, baseProposalSha256, obligations, "");
        }

        public static ProposalEmissionContext initial() {
            return new ProposalEmissionContext(EmissionMode.INITIAL_FULL, "", "", List.of());
        }

        public static ProposalEmissionContext notApplicable() {
            return new ProposalEmissionContext(EmissionMode.NOT_APPLICABLE, "", "", List.of());
        }

        boolean revision() {
            return mode == EmissionMode.REVISION_PATCH;
        }
    }

    private static AgentResultEnvelope.Failure emptyFailure() {
        return new AgentResultEnvelope.Failure("", AgentResultEnvelope.VerificationRemediation.NONE,
                List.of(), List.of(), List.of(), List.of(), "");
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.JsonNode;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeResult;
import dev.dual.ledger.file.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Fixed run records and their binding to the existing node-execution claim. No external replay. */
public final class AgentRunCommitProtocol {
    private static final AtomicJsonWriter WRITER = new AtomicJsonWriter();
    private AgentRunCommitProtocol() {}

    public record Prepared(NodeExecutionDocument execution, Map<String, String> reference, Path path) {}

    /** Program facts share the run writer and cannot replace a prior observation or a completed outcome. */
    static dev.dual.core.contract.TaskContract.Reference recordObservation(Path root, String workstream,
                                                                          Prepared prepared, Object observation) throws IOException {
        var run = prepared.path().getParent().getParent();
        var path = run.resolve("outputs/verification-observations.json");
        try (var ignored = lock(run, workstream)) {
            if (!hash(Files.readAllBytes(prepared.path())).equals(prepared.reference().get("sha256"))
                    || !Files.isRegularFile(intentPath(prepared.path())))
                throw new IOException("observation lacks its fixed preparation and execution intent");
            if (Files.exists(completionPath(prepared.path())) || Files.exists(run.resolve("outputs/execution-outcome.json")))
                throw new IOException("completed execution cannot acquire new observations");
            immutable(path, observation);
            return new dev.dual.core.contract.TaskContract.Reference(reference(root, path), hash(Files.readAllBytes(path)));
        }
    }

    public static Prepared prepare(TaskHandler.TaskContext context, Path runDirectory, List<Path> inputs,
                                   Map<String, Object> binding) throws IOException {
        var paths = paths(context);
        NodeExecutionDocument execution;
        try (var read = context.ledger().readSession(paths)) {
            var node = read.ledger().loadNode(paths, context.instance().nodeInstanceId());
            execution = read.ledger().latestNodeExecution(paths, node).orElseThrow(() -> new IOException("run has no execution claim"));
            read.ledger().verifyExecutionClaim(paths, execution);
        }
        var run = runDirectory.toAbsolutePath().normalize();
        if (!run.getParent().equals(paths.runsDir().toAbsolutePath().normalize()))
            throw new IOException("run directory is outside this workstream");
        var inputHashes = new java.util.TreeMap<String, String>();
        for (var input : inputs) inputHashes.put(reference(paths.workspaceRoot(), input), hash(Files.readAllBytes(input)));
        for (var ref : context.instance().inputRefs()) {
            var path = inside(paths.workspaceRoot(), ref);
            inputHashes.put(ref, hash(Files.readAllBytes(path)));
        }
        var document = new LinkedHashMap<String, Object>();
        document.put("schema", "dual.run.prepared.v1");
        document.put("workstream", context.workstreamId());
        document.put("node", execution.nodeInstanceId());
        document.put("task", execution.agentTaskId());
        document.put("execution", execution.nodeExecutionId());
        document.put("claim", execution.result().get("claim"));
        document.put("runtime_identity", context.ledger().frozenRuntimeIdentity());
        document.put("inputs", inputHashes);
        document.put("binding", binding);
        var path = run.resolve("outputs").resolve(execution.nodeExecutionId() + "-prepared.json");
        Map<String, String> ref;
        try (var ignored = lock(run, context.workstreamId())) {
            immutable(path, document);
            ref = Map.of("ref", reference(paths.workspaceRoot(), path), "sha256", hash(Files.readAllBytes(path)));
        }
        // Never hold R while acquiring L. Orphan R01 bytes have no execution authority.
        try (var write = context.ledger().writeSession(paths, "bind prepared run", execution.nodeExecutionId())) {
            write.ledger().bindPreparedRun(paths, execution, ref);
            write.commit();
        }
        return new Prepared(execution, ref, path);
    }

    /** Repeat qualification against the current claim and fixed contract, without producing new inputs. */
    public static void qualifyDispatch(TaskHandler.TaskContext context, Prepared prepared) throws IOException {
        try {
            VerificationEvidence.verifyAcceptanceInputs(context);
        } catch (IOException invalid) {
            throw new AgentRunGovernanceContext.QualificationException("VERIFICATION_EVIDENCE_INVALID", invalid.getMessage());
        }
        var paths = paths(context);
        context.ledger().inspect(paths, (scoped, files) -> {
            scoped.verifyExecutionClaim(paths, prepared.execution());
            var fixed = WRITER.readTree(prepared.path());
            if (!hash(Files.readAllBytes(prepared.path())).equals(prepared.reference().get("sha256")))
                throw new IOException("prepared identity changed");
            verifyInputs(paths.workspaceRoot(), fixed.path("inputs"));
            if (TaskContractProjectionVerifier.requiresContract(context.definition())) {
                var resolution = TaskContractProjectionVerifier.resolve(scoped, paths.workspaceRoot(), context.workstreamId(),
                        TaskContractProjectionVerifier.requiredPhase(context.definition()));
                if (resolution.failure() != null)
                    throw new AgentRunGovernanceContext.QualificationException(resolution.failure().reason(), resolution.failure().message());
                var contract = resolution.qualified().orElseThrow(() -> new IOException("approved contract is absent"));
                if (!contract.contractRef().equals(fixed.path("binding").path("contract_ref").asText())
                        || !contract.sha256().equals(fixed.path("binding").path("contract_sha256").asText()))
                    throw new IOException("qualified contract differs from prepared contract");
            }
            return null;
        });
    }

    /** Only a live executor may create the first durable intent. Existing intent never grants another send. */
    public static void beginExternalCall(TaskHandler.TaskContext context, Prepared prepared) throws IOException {
        var paths = paths(context);
        try (var read = context.ledger().readSession(paths)) {
            var execution = read.ledger().verifyExecutionClaim(paths, prepared.execution());
            if (!prepared.reference().equals(execution.result().get("prepared_run")))
                throw new IOException("prepared run is not the current claim binding");
        }
        var run = prepared.path().getParent().getParent();
        try (var ignored = lock(run, context.workstreamId())) {
            var bytes = Files.readAllBytes(prepared.path());
            if (!hash(bytes).equals(prepared.reference().get("sha256"))) throw new IOException("prepared run bytes changed");
            var document = WRITER.objectMapper().readTree(bytes);
            verifyInputs(paths.workspaceRoot(), document.path("inputs"));
            var owner = document.path("claim");
            var actual = ProcessHandle.current();
            if (actual.pid() != owner.path("executor_pid").asLong()
                    || !actual.info().startInstant().orElseThrow().toString().equals(owner.path("executor_started_at").asText()))
                throw new IOException("preparation belongs to another executor process");
            var intent = intentPath(prepared.path());
            if (Files.exists(intent)) throw new IOException("external intent already exists; no automatic resend");
            immutable(intent, Map.of("schema", "dual.run.intent.v1", "prepared", prepared.reference()));
        }
    }

    /** Each native command has a durable intent; telemetry alone never grants dispatch. */
    public static void commandEvent(TaskHandler.TaskContext context, Prepared prepared, String kind,
                                    Map<String, Object> details) throws IOException {
        if (!kind.equals("command_intent") && !kind.equals("command_result")) return;
        var id = String.valueOf(details.get("command_id"));
        if (!id.matches("[a-f0-9-]{36}")) throw new IOException("native command identity missing");
        var cleanup = Boolean.TRUE.equals(details.get("cleanup"));
        if (kind.equals("command_intent") && !cleanup) qualifyDispatch(context, prepared);
        var run = prepared.path().getParent().getParent();
        try (var ignored = lock(run, context.workstreamId())) {
            if (!hash(Files.readAllBytes(prepared.path())).equals(prepared.reference().get("sha256")))
                throw new IOException("prepared bytes changed before native command");
            if (kind.equals("command_intent")) {
                var fixed = WRITER.readTree(prepared.path());
                verifyNativeCommand(fixed.path("binding"), details);
                if (!cleanup) {
                    var process = ProcessHandle.current();
                    var owner = fixed.path("claim");
                    if (Files.exists(releasePath(prepared.path())) || Files.exists(completionPath(prepared.path()))
                            || Files.exists(prepared.path().getParent().resolve("execution-outcome.json"))
                            || process.pid() != owner.path("executor_pid").asLong()
                            || !process.info().startInstant().orElseThrow().toString().equals(owner.path("executor_started_at").asText()))
                        throw new IOException("recorded external intent does not grant a new executor send authority");
                }
            }
            if (!Files.isRegularFile(intentPath(prepared.path()))) throw new IOException("native command lacks attempt intent");
            var prefix = prepared.execution().nodeExecutionId() + "-command-" + id;
            var intent = run.resolve("outputs").resolve(prefix + "-intent.json");
            if (kind.equals("command_intent") && Files.exists(intent)) throw new IOException("native command intent cannot be sent twice");
            if (kind.equals("command_result") && !Files.isRegularFile(intent)) throw new IOException("native command result lacks intent");
            long ordinal;
            if (kind.equals("command_intent")) {
                ordinal = 1;
                try (var entries = Files.list(run.resolve("outputs"))) {
                    for (var entry : entries.filter(p -> p.getFileName().toString().startsWith(prepared.execution().nodeExecutionId() + "-command-")
                            && p.getFileName().toString().endsWith("-intent.json")).toList())
                        ordinal = Math.max(ordinal, WRITER.readTree(entry).path("ordinal").asLong() + 1);
                }
            } else {
                var declared = WRITER.readTree(intent);
                var actual = WRITER.objectMapper().valueToTree(details).deepCopy();
                ((com.fasterxml.jackson.databind.node.ObjectNode) actual).remove("observation");
                if (!actual.equals(declared.path("details"))) throw new IOException("native command result identity differs from intent");
                ordinal = declared.path("ordinal").asLong();
            }
            immutable(run.resolve("outputs").resolve(prefix + (kind.equals("command_intent") ? "-intent.json" : "-result.json")),
                    Map.of("schema", "dual.run.command.v1", "prepared", prepared.reference(), "kind", kind, "ordinal", ordinal, "details", details));
        }
    }

    private static void verifyNativeCommand(JsonNode binding, Map<String, Object> details) throws IOException {
        var expected = binding.path("native_invocation");
        var actual = WRITER.objectMapper().valueToTree(details.get("invocation"));
        if (!expected.isObject() || !expected.path("schema").asText().equals("dual.acpx.invocation.v1")
                || !expected.equals(actual) || !expected.path("session").asText().equals(details.get("session")))
            throw new IOException("native invocation differs from R01; do not borrow the old session or retry an unknown call");
        var command = WRITER.objectMapper().valueToTree(details.get("command"));
        if (!command.isArray() || command.isEmpty() || !command.path(0).equals(expected.path("executable")))
            throw new IOException("native command executable differs from R01");
        if (Boolean.TRUE.equals(details.get("cleanup"))) {
            var executable = expected.path("executable").asText();
            var agent = expected.path("agent").asText();
            var session = expected.path("session").asText();
            var allowed = switch (String.valueOf(details.get("purpose"))) {
                case "session_cancel" -> List.of(executable, agent, "cancel", "-s", session);
                case "session_close" -> List.of(executable, agent, "sessions", "close", session);
                default -> List.of();
            };
            if (allowed.isEmpty() || !WRITER.objectMapper().valueToTree(allowed).equals(command))
                throw new IOException("cleanup cannot grant native prompt authority");
        } else {
            var options = WRITER.objectMapper().valueToTree(details.get("request_options"));
            var allowed = binding.path("allowed_request_options");
            if (!options.isArray() || !allowed.isArray() || java.util.stream.StreamSupport.stream(allowed.spliterator(), false)
                    .noneMatch(options::equals)) throw new IOException("native permission configuration differs from R01");
        }
    }

    /** A stopped Java invocation is distinct from native session quiescence. It only releases its local claim. */
    public static void releaseExecutor(WorkflowFileLedger ledger, WorkstreamPaths paths, NodeExecutionDocument expected) throws IOException {
        NodeExecutionDocument actual;
        try (var read = ledger.readSession(paths)) {
            actual = read.files().read(paths.nodeExecutionJson(expected.nodeExecutionId()), NodeExecutionDocument.class);
        }
        if (!hasPrepared(actual)) return;
        var prepared = preparedPath(paths, actual);
        var owner = WRITER.readTree(prepared).path("claim");
        var process = ProcessHandle.current();
        if (owner.path("executor_pid").asLong() != process.pid()
                || !owner.path("executor_started_at").asText().equals(process.info().startInstant().orElseThrow().toString()))
            throw new IOException("only the original executor may release its invocation");
        try (var ignored = lock(prepared.getParent().getParent(), paths.workstreamId().value())) {
            immutable(releasePath(prepared), Map.of("schema", "dual.run.executor-release.v1", "prepared", actual.result().get("prepared_run"),
                    "execution", actual.nodeExecutionId(), "claim", actual.result().get("claim")));
        }
    }

    public static boolean executorOwnsInvocation(WorkstreamPaths paths, NodeExecutionDocument execution) throws IOException {
        var prepared = preparedPath(paths, execution);
        if (Files.exists(releasePath(prepared))) {
            var release = WRITER.readTree(releasePath(prepared));
            if (!release.path("schema").asText().equals("dual.run.executor-release.v1")
                    || !release.path("execution").asText().equals(execution.nodeExecutionId())
                    || !release.path("prepared").equals(WRITER.objectMapper().valueToTree(execution.result().get("prepared_run")))
                    || !release.path("claim").equals(WRITER.objectMapper().valueToTree(execution.result().get("claim"))))
                throw new IOException("invalid executor release");
            return false;
        }
        return executorAlive(execution);
    }

    /** R03 fixes the validated completion, actual run observations and every published output identity. */
    public static NodeResult complete(Path root, WorkflowFileLedger ledger, WorkstreamPaths paths,
                                      NodeExecutionDocument expected, NodeResult result) throws IOException {
        if (AgentExecutionResultFacts.inputPreparationFailed(result)) return result;
        final Map<String, String> preparedRef;
        try (var read = ledger.readSession(paths)) {
            // Preserve actual completion even after cancellation; only the L03 consumer grants routing.
            var execution = read.files().read(paths.nodeExecutionJson(expected.nodeExecutionId()), NodeExecutionDocument.class);
            if (!execution.nodeInstanceId().equals(expected.nodeInstanceId())
                    || !execution.agentTaskId().equals(expected.agentTaskId())) throw new IOException("foreign execution");
            if (!(execution.result().get("prepared_run") instanceof Map<?, ?> value)) {
                if (AgentExecutionResultFacts.inputPreparationFailed(result)
                        || !"acpx.agent_run".equals(execution.handlerType())
                        || Boolean.TRUE.equals(result.result().get("prepared"))) return result;
                throw new IOException("external result has no prepared claim binding");
            }
            preparedRef = stringReference(value);
        }
        var preparedPath = inside(root, preparedRef.get("ref"));
        var run = preparedPath.getParent().getParent();
        try (var ignored = lock(run, paths.workstreamId().value())) {
            if (!hash(Files.readAllBytes(preparedPath)).equals(preparedRef.get("sha256"))) throw new IOException("prepared run changed");
            if (!Files.isRegularFile(intentPath(preparedPath))) throw new IOException("external result has no durable intent");
            var input = WRITER.readTree(preparedPath);
            if (!expected.nodeExecutionId().equals(input.path("execution").asText())) throw new IOException("foreign execution result");
            var outputHashes = new java.util.TreeMap<String, String>();
            for (var ref : result.outputRefs()) outputHashes.put(ref, hash(Files.readAllBytes(inside(root, ref))));
            var metadata = WRITER.readTree(run.resolve("outputs/execution-outcome.json")).path("run_observations");
            if (metadata.path("processResult").isMissingNode() || metadata.path("executionOutcome").isMissingNode())
                throw new IOException("run lacks typed process and execution outcome");
            if (!WRITER.objectMapper().readTree(WRITER.objectMapper().writeValueAsBytes(result.result().get("agent_execution_outcome")))
                    .equals(metadata.path("executionOutcome"))) throw new IOException("result contradicts the fixed outcome");
            var completion = completionPath(preparedPath);
            immutable(completion, Map.of("schema", "dual.run.completion.v1", "prepared", preparedRef,
                    "execution", expected.nodeExecutionId(), "result", result,
                    "output_hashes", outputHashes, "run_observations", metadata));
            return withCompletion(root, result, completion);
        }
    }

    /** L03 consumer reads the fixed record; mutable run.json is not a completion authority. */
    public static NodeResult consume(WorkflowFileLedger scoped, WorkstreamPaths paths,
                                     NodeExecutionDocument expected) throws IOException {
        var execution = scoped.verifyExecutionClaim(paths, expected);
        verifyInputs(paths.workspaceRoot(), WRITER.readTree(preparedPath(paths, execution)).path("inputs"));
        return readCompletion(paths, execution);
    }

    public static NodeResult readCompletion(WorkstreamPaths paths, NodeExecutionDocument execution) throws IOException {
        if (!(execution.result().get("prepared_run") instanceof Map<?, ?> value)) throw new IOException("missing prepared binding");
        var ref = stringReference(value);
        var prepared = inside(paths.workspaceRoot(), ref.get("ref"));
        if (!hash(Files.readAllBytes(prepared)).equals(ref.get("sha256"))) throw new IOException("prepared bytes changed");
        verifyInputs(paths.workspaceRoot(), WRITER.readTree(prepared).path("inputs"));
        var completion = completionPath(prepared);
        var doc = WRITER.readTree(completion);
        if (!"dual.run.completion.v1".equals(doc.path("schema").asText())
                || !execution.nodeExecutionId().equals(doc.path("execution").asText())
                || !WRITER.objectMapper().valueToTree(ref).equals(doc.path("prepared")))
            throw new IOException("completion identity mismatch");
        verifyInputs(paths.workspaceRoot(), doc.path("output_hashes"));
        var result = WRITER.objectMapper().treeToValue(doc.path("result"), NodeResult.class);
        return withCompletion(paths.workspaceRoot(), result, completion);
    }

    public static Prepared boundPreparation(WorkstreamPaths paths, NodeExecutionDocument execution) throws IOException {
        var path = preparedPath(paths, execution);
        return new Prepared(execution, stringReference((Map<?, ?>) execution.result().get("prepared_run")), path);
    }

    public static boolean hasPrepared(NodeExecutionDocument execution) { return execution.result().containsKey("prepared_run"); }

    public enum Observation { PREPARED, EXTERNAL_UNKNOWN, OUTCOME_RECORDED, COMPLETED }

    public static Observation observe(WorkstreamPaths paths, NodeExecutionDocument execution) throws IOException {
        var prepared = preparedPath(paths, execution);
        if (Files.isRegularFile(completionPath(prepared))) return Observation.COMPLETED;
        if (Files.isRegularFile(prepared.getParent().resolve("execution-outcome.json"))) return Observation.OUTCOME_RECORDED;
        return Files.exists(intentPath(prepared)) ? Observation.EXTERNAL_UNKNOWN : Observation.PREPARED;
    }

    public static NodeResult recordedCandidate(WorkstreamPaths paths, NodeExecutionDocument execution) throws IOException {
        var prepared = preparedPath(paths, execution);
        var record = WRITER.readTree(prepared.getParent().resolve("execution-outcome.json"));
        if (!"dual.run.outcome.v1".equals(record.path("schema").asText())) throw new IOException("unknown outcome schema");
        verifyInputs(paths.workspaceRoot(), record.path("output_hashes"));
        var candidate = WRITER.objectMapper().treeToValue(record.path("candidate"), NodeResult.class);
        var metadataRef = candidate.result().get("run_metadata");
        if (!(metadataRef instanceof String ref) || !inside(paths.workspaceRoot(), ref).equals(prepared.getParent().getParent().resolve("run.json")))
            throw new IOException("candidate does not belong to prepared run");
        return candidate;
    }

    public static boolean executorAlive(NodeExecutionDocument execution) throws IOException {
        if (!(execution.result().get("claim") instanceof Map<?, ?> claim)
                || !(claim.get("executor_pid") instanceof Number pid)
                || !(claim.get("executor_started_at") instanceof String start)) throw new IOException("missing executor identity");
        var process = ProcessHandle.of(pid.longValue());
        return process.isPresent() && process.get().isAlive()
                && process.get().info().startInstant().orElseThrow(() -> new IOException("executor start identity unavailable"))
                    .toString().equals(start);
    }

    private static Path preparedPath(WorkstreamPaths paths, NodeExecutionDocument execution) throws IOException {
        if (!(execution.result().get("prepared_run") instanceof Map<?, ?> value)) throw new IOException("missing prepared binding");
        var ref = stringReference(value);
        var path = inside(paths.workspaceRoot(), ref.get("ref"));
        if (!hash(Files.readAllBytes(path)).equals(ref.get("sha256"))) throw new IOException("prepared record changed");
        var prepared = WRITER.readTree(path);
        if (!"dual.run.prepared.v1".equals(prepared.path("schema").asText())
                || !execution.nodeExecutionId().equals(prepared.path("execution").asText())
                || !execution.nodeInstanceId().equals(prepared.path("node").asText())
                || !execution.agentTaskId().equals(prepared.path("task").asText())) throw new IOException("foreign preparation");
        return path;
    }

    static void recordPublication(Path root, NodeResult candidate, ArtifactContractValidator.Publication publication) throws IOException {
        if (!(candidate.result().get("run_metadata") instanceof String ref)) throw new IOException("publication has no program run identity");
        var run = inside(root, ref).getParent();
        try (var ignored = lock(run, publication.workstream())) {
            immutable(run.resolve("outputs/publication-plan.json"), Map.of("schema", "dual.run.publication.v1", "publication", publication));
        }
    }

    static ArtifactContractValidator.Publication recordedPublication(Path root, WorkstreamPaths paths,
                                                                      NodeExecutionDocument execution) throws IOException {
        var prepared = preparedPath(paths, execution);
        var outcome = WRITER.readTree(prepared.getParent().resolve("execution-outcome.json"));
        var ref = outcome.path("publication");
        if (ref.isMissingNode()) return null;
        var path = inside(root, ref.path("ref").asText());
        if (!path.equals(prepared.getParent().resolve("publication-plan.json"))
                || !hash(Files.readAllBytes(path)).equals(ref.path("sha256").asText())) throw new IOException("fixed publication changed");
        var plan = WRITER.readTree(path);
        if (!plan.path("schema").asText().equals("dual.run.publication.v1")) throw new IOException("publication schema mismatch");
        var publication = WRITER.objectMapper().treeToValue(plan.path("publication"), ArtifactContractValidator.Publication.class);
        if (!publication.workstream().equals(paths.workstreamId().value()) || !publication.node().equals(execution.nodeInstanceId()))
            throw new IOException("publication identity mismatch");
        return publication;
    }

    static dev.dual.core.execution.AgentExecutionOutcome recordedOutcome(Path root, Path runJson, NodeResult candidate) throws IOException {
        var path = runJson.getParent().resolve("outputs/execution-outcome.json");
        if (!Files.exists(path)) return null;
        var record = WRITER.readTree(path);
        if (!"dual.run.outcome.v1".equals(record.path("schema").asText())
                || !WRITER.objectMapper().readTree(WRITER.objectMapper().writeValueAsBytes(candidate)).equals(record.path("candidate")))
            throw new IOException("candidate differs from the fixed execution decision");
        verifyInputs(root, record.path("output_hashes"));
        return WRITER.objectMapper().treeToValue(record.path("outcome"), dev.dual.core.execution.AgentExecutionOutcome.class);
    }

    static void recordOutcome(Path root, Path runJson, NodeResult candidate,
                              dev.dual.core.execution.AgentExecutionOutcome outcome, JsonNode metadata) throws IOException {
        var run = runJson.getParent();
        var hashes = new java.util.TreeMap<String, String>();
        for (var ref : candidate.outputRefs()) hashes.put(ref, hash(Files.readAllBytes(inside(root, ref))));
        try (var ignored = lock(run, metadata.path("workstreamId").asText("unknown"))) {
            var record = new LinkedHashMap<String, Object>(Map.of("schema", "dual.run.outcome.v1",
                    "candidate", candidate, "outcome", outcome, "output_hashes", hashes, "run_observations", metadata));
            var publication = run.resolve("outputs/publication-plan.json");
            if (Files.isRegularFile(publication)) record.put("publication", Map.of("ref", reference(root, publication), "sha256", hash(Files.readAllBytes(publication))));
            immutable(run.resolve("outputs/execution-outcome.json"), record);
        }
    }

    private static NodeResult withCompletion(Path root, NodeResult result, Path completion) throws IOException {
        var facts = new LinkedHashMap<String, Object>(result.result());
        facts.put("completion_ref", reference(root, completion));
        facts.put("completion_sha256", hash(Files.readAllBytes(completion)));
        return new NodeResult(result.outcome(), result.status(), result.outputRefs(), facts, result.errorMessage());
    }

    private static void verifyInputs(Path root, JsonNode inputs) throws IOException {
        if (!inputs.isObject()) throw new IOException("missing content identities");
        var fields = inputs.fields();
        while (fields.hasNext()) {
            var field = fields.next();
            if (!field.getValue().isTextual() || !hash(Files.readAllBytes(inside(root, field.getKey()))).equals(field.getValue().asText()))
                throw new IOException("run input/output changed: " + field.getKey());
        }
    }

    private static Map<String, String> stringReference(Map<?, ?> value) throws IOException {
        if (!(value.get("ref") instanceof String ref) || !(value.get("sha256") instanceof String sha)
                || !sha.matches("[a-f0-9]{64}")) throw new IOException("invalid fixed record reference");
        return Map.of("ref", ref, "sha256", sha);
    }

    private static void immutable(Path path, Object document) throws IOException {
        var bytes = WRITER.objectMapper().writer().with(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS)
                .writeValueAsBytes(document);
        if (Files.exists(path)) {
            if (!java.util.Arrays.equals(bytes, Files.readAllBytes(path))) throw new IOException("different bytes at immutable run record: " + path);
            return;
        }
        WRITER.writeBytes(path, bytes);
    }

    private static Path releasePath(Path prepared) { return prepared.resolveSibling(prepared.getFileName().toString().replace("-prepared.json", "-released.json")); }
    private static Path intentPath(Path prepared) { return prepared.resolveSibling(prepared.getFileName().toString().replace("-prepared.json", "-intent.json")); }
    private static Path completionPath(Path prepared) { return prepared.resolveSibling(prepared.getFileName().toString().replace("-prepared.json", "-completion.json")); }
    private static WorkstreamPaths paths(TaskHandler.TaskContext context) { return new WorkstreamPaths(context.workspaceRoot(), new DualId(context.workstreamId())); }
    private static WorkstreamLock lock(Path run, String workstream) throws IOException { return WorkstreamLock.acquire(run, LockOwner.currentProcess(workstream, "run commit")); }
    private static Path inside(Path root, String ref) throws IOException {
        var base = root.toAbsolutePath().normalize();
        var path = base.resolve(ref).normalize();
        if (Path.of(ref).isAbsolute() || !path.startsWith(base)) throw new IOException("run reference escapes workspace");
        if (Files.exists(path) && !path.toRealPath().startsWith(base.toRealPath())) throw new IOException("run reference escapes through symlink");
        return path;
    }
    private static String reference(Path root, Path path) throws IOException {
        var ref = root.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
        inside(root, ref);
        return ref;
    }
    private static String hash(byte[] bytes) {
        try { return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes)); }
        catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Optional;

/**
 * Builds the per-agent-run governance context consumed by acpx prompts.
 *
 * Workflow context-package nodes still own rich cross-node packets. This class
 * only guarantees that every concrete agent execution receives its own typed
 * exploration plan and capability catalog projection, even when the workflow
 * graph does not include a dedicated context node before that agent.
 */
public final class AgentRunGovernanceContext {
    public static final String QUALIFICATION_FAILURE_OUTCOME =
            TaskContractProjectionVerifier.FAILURE_OUTCOME;
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
            .enable(SerializationFeature.INDENT_OUTPUT);

    private AgentRunGovernanceContext() {
    }

    public static String ensure(TaskHandler.TaskContext context, String runId) throws IOException {
        return ensureQualified(context, runId).contextRef();
    }

    public static PreparedContext ensureQualified(TaskHandler.TaskContext context, String runId) throws IOException {
        var workspaceRoot = context.workspaceRoot();
        var workstreamDir = workspaceRoot.resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());
        var expectedArtifact = String.valueOf(
                context.definition().config().getOrDefault("expected_artifact", "")).trim();
        var requiresQualification = requiresApprovedTaskContract(context);
        var contractResolution = requiresQualification || "acceptance_review".equals(expectedArtifact)
                ? ("acceptance_review".equals(expectedArtifact)
                        ? TaskContractProjectionVerifier.resolveRoutedAcceptance(
                                context.ledger(), workspaceRoot,
                                context.workstreamId(),
                                context.definition().id(),
                                context.instance().inputRefs())
                        : TaskContractProjectionVerifier.resolve(context.ledger(), workspaceRoot, context.workstreamId(), TaskContractProjectionVerifier.requiredPhase(context.definition())))
                : TaskContractProjectionVerifier.Resolution.absent();
        if (contractResolution.failure() != null) {
            throw qualificationFailure(contractResolution.failure());
        }
        if (requiresQualification && contractResolution.qualified().isEmpty()) {
            throw new QualificationException("APPROVAL_BINDING_MISSING", "node requires an approved task contract");
        }
        if ("acceptance_review".equals(expectedArtifact) && contractResolution.qualified().isEmpty()) {
            throw new QualificationException("CONTEXT_BINDING_MISSING", "acceptance agent has no routed task contract binding");
        }
        try {
            VerificationEvidence.verifyAcceptanceInputs(context);
        } catch (IOException invalid) {
            throw new QualificationException("VERIFICATION_EVIDENCE_INVALID", invalid.getMessage());
        }
        Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract =
                contractResolution.qualified();
        final Optional<AuthoredExecutionContext.Snapshot> authoredContext;
        try {
            authoredContext = AuthoredExecutionContext.prepare(context, runId);
        } catch (IOException failure) {
            throw new AuthoredContextException(failure.getMessage(), failure);
        }

        var contextDir = workstreamDir.resolve("context");
        Files.createDirectories(contextDir);

        var manifest = EvidenceManifest.rebuild(context.ledger(), workspaceRoot, workstreamDir, context.workstreamId(),
                context.instance().inputRefs(), OBJECT_MAPPER, qualifiedContract);
        manifest.write(workstreamDir, OBJECT_MAPPER);
        var governance = RepoScopeGovernance.build(
                workspaceRoot, workstreamDir, context, OBJECT_MAPPER, qualifiedContract, runId);

        var packagePath = contextDir.resolve("agent-governance-"
                + safeFileName(context.instance().nodeInstanceId())
                + "-"
                + safeFileName(runId)
                + ".md");
        var builder = new StringBuilder();
        builder.append("# Agent Run Governance Context\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Target Node: ").append(context.definition().id()).append("\n");
        builder.append("- Agent Node Instance: ").append(context.instance().nodeInstanceId()).append("\n");
        builder.append("- Run Id: ").append(runId == null ? "" : runId).append("\n");
        builder.append("- Generated At: ").append(Instant.now()).append("\n\n");
        RepoScopeGovernance.appendMarkdownGuidance(builder, governance, workspaceRoot, true);
        if (qualifiedContract.isPresent() && qualifiedContract.get().contract().phase() == TaskContract.Phase.GOAL)
            builder.append(VerificationReadiness.context(context.ledger(), workspaceRoot, context.workstreamId(), qualifiedContract.get()));
        Files.writeString(packagePath, builder.toString(), StandardCharsets.UTF_8);
        return new PreparedContext(
                workspaceRoot.relativize(packagePath).toString(),
                qualifiedContract.map(TaskContractProjectionVerifier.QualifiedTaskContract::wrappedPayload),
                governance.repositoryFactBinding(),
                qualifiedContract.map(TaskContractProjectionVerifier.QualifiedTaskContract::contract),
                qualifiedContract.map(TaskContractProjectionVerifier.QualifiedTaskContract::contractRef).orElse(""),
                qualifiedContract.map(TaskContractProjectionVerifier.QualifiedTaskContract::sha256).orElse(""),
                authoredContext);
    }

    public static Optional<String> trustedTaskContractPayload(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            java.util.List<String> inputRefs
    ) {
        return TaskContractProjectionVerifier.trustedWrappedPayload(
                ledger, workspaceRoot, workstreamId, nodeId, inputRefs);
    }

    private static QualificationException qualificationFailure(TaskContractProjectionVerifier.Failure failure) {
        return new QualificationException(failure.reason(), failure.message());
    }

    public static boolean requiresApprovedTaskContract(TaskHandler.TaskContext context) {
        return TaskContractProjectionVerifier.requiresContract(context.definition());
    }

    public static final class QualificationException extends IOException {
        private final String reason;
        QualificationException(String reason, String message) {
            super(TaskContractProjectionVerifier.FAILURE_OUTCOME + ": " + reason + ": " + message);
            this.reason = reason;
        }
        public String reason() { return reason; }
    }

    public record PreparedContext(
            String contextRef,
            Optional<String> trustedTaskContractPayload,
            RepositoryFactBinding.Verified repositoryFactBinding,
            Optional<TaskContract> qualifiedTaskContract,
            String taskContractRef,
            String taskContractSha256,
            Optional<AuthoredExecutionContext.Snapshot> authoredContext
    ) {
    }

    public static final class AuthoredContextException extends IOException {
        AuthoredContextException(String message, Throwable cause) { super(message, cause); }
    }

    private static String safeFileName(String value) {
        var text = value == null || value.isBlank() ? "unknown" : value.trim();
        return text.replaceAll("[^A-Za-z0-9._-]", "_");
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.execution.AdapterSignal;
import dev.dual.core.execution.AdapterSignalType;
import dev.dual.core.execution.AgentExecutionAttempt;
import dev.dual.core.execution.AgentExecutionAttemptStatus;
import dev.dual.core.execution.AgentExecutionEvidence;
import dev.dual.core.execution.AgentExecutionFinalizer;
import dev.dual.core.execution.AgentExecutionOutcome;
import dev.dual.core.execution.AgentExecutionOutcomeResolver;
import dev.dual.core.execution.AgentExecutionProcessStatus;
import dev.dual.core.execution.AgentExecutionRetryPolicy;
import dev.dual.core.execution.AgentExecutionTimelineEventKind;
import dev.dual.core.execution.ArtifactContractResult;
import dev.dual.core.execution.ProcessResult;
import dev.dual.core.execution.ProcessUsability;
import dev.dual.core.execution.AgentResultContractResult;
import dev.dual.core.workflow.NodeResult;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Owns the run.json execution finalization projection.
 *
 * <p>Artifact validators provide result/artifact facts. This class is the
 * single runtime writer that combines those facts with process evidence and
 * persists terminal attempt/outcome fields into the agent run read model.</p>
 */
public final class AgentRunMetadataFinalizer {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private final AgentExecutionFinalizer executionFinalizer;

    public AgentRunMetadataFinalizer() {
        this(new AgentExecutionFinalizer(new AgentExecutionOutcomeResolver()));
    }

    AgentRunMetadataFinalizer(AgentExecutionFinalizer executionFinalizer) {
        if (executionFinalizer == null) {
            throw new IllegalArgumentException("executionFinalizer is required");
        }
        this.executionFinalizer = executionFinalizer;
    }

    public NodeResult finalizeNodeResult(Path workspaceRoot, NodeResult result) {
        return resolveNodeResult(workspaceRoot, result, true);
    }

    /** Read the same execution facts before publication, without writing a terminal run projection. */
    NodeResult assessPublication(Path workspaceRoot, NodeResult result) {
        return resolveNodeResult(workspaceRoot, result, false);
    }

    private NodeResult resolveNodeResult(Path workspaceRoot, NodeResult result, boolean persist) {
        if (AgentExecutionResultFacts.inputPreparationFailed(result)) return result;
        if (!AgentExecutionResultFacts.present(result)) {
            return result;
        }
        var outcome = finalizeRunMetadata(
                workspaceRoot,
                result,
                AgentExecutionResultFacts.agentResultContract(result),
                AgentExecutionResultFacts.artifactContractResults(result),
                AgentExecutionResultFacts.rereadReasons(result), persist
        );
        var finalized = new LinkedHashMap<String, Object>();
        finalized.putAll(result.result());
        finalized.put("agent_execution_outcome", outcomeToMap(outcome));
        return new NodeResult(
                outcome.nodeMaySucceed() ? result.outcome() : outcome.primaryReason(),
                outcome.nodeMaySucceed() ? result.status() : dev.dual.core.workflow.NodeStatus.FAILED,
                result.outputRefs(),
                finalized,
                outcome.nodeMaySucceed() ? result.errorMessage() : outcome.operatorMessage()
        );
    }

    AgentExecutionOutcome finalizeRunMetadata(
            Path workspaceRoot,
            NodeResult result,
            AgentResultContractResult agentResultContract,
            List<ArtifactContractResult> artifactContractResults,
            Object rereadReasons
    ) {
        return finalizeRunMetadata(workspaceRoot, result, agentResultContract, artifactContractResults, rereadReasons, true);
    }

    private AgentExecutionOutcome finalizeRunMetadata(
            Path workspaceRoot, NodeResult result, AgentResultContractResult agentResultContract,
            List<ArtifactContractResult> artifactContractResults, Object rereadReasons, boolean persist
    ) {
        var runMetadataRef = text(result.result().get("run_metadata"));
        if (runMetadataRef.isBlank()) throw new IllegalStateException("typed execution requires program-owned run metadata");
        var root = workspaceRoot.toAbsolutePath().normalize();
        var path = root.resolve(runMetadataRef).normalize();
        if (!path.startsWith(root)) throw new IllegalStateException("run metadata escapes workspace");
        try {
            var recorded = AgentRunCommitProtocol.recordedOutcome(workspaceRoot, path, result);
            if (recorded != null) return recorded;
            if (!Files.isRegularFile(path)) throw new java.io.IOException("typed run metadata is missing");
            var json = (ObjectNode) OBJECT_MAPPER.readTree(path.toFile());
            var process = processResultFromRunMetadata(json);
            if (process == null) throw new java.io.IOException("typed process evidence is missing; no legacy success inference");
            var signals = json.path("adapterSignals").isMissingNode()
                    ? resultAdapterSignals(result)
                    : adapterSignalsFromRunMetadata(json);
            var evidence = new AgentExecutionEvidence(
                    process,
                    agentResultContract,
                    artifactContractResults,
                    signals, permissionAssessments(result)
            );
            var processResult = mergedProcessResult(json, process);
            var finalized = executionFinalizer.finalize(baseAttempt(json, result), evidence);
            if (!persist) return finalized.outcome();
            json.put("schemaVersion", Math.max(json.path("schemaVersion").asInt(0), 3));
            json.put("status", finalized.legacyStatus());
            json.put("failureReason", finalized.legacyFailureReason());
            json.put("recoverable", finalized.legacyRecoverable());
            json.set("processResult", OBJECT_MAPPER.valueToTree(processResult));
            json.set("adapterSignals", OBJECT_MAPPER.valueToTree(signals.stream()
                    .map(AgentRunMetadataFinalizer::adapterSignalToMap)
                    .toList()));
            json.set("permissionAssessments", OBJECT_MAPPER.valueToTree(evidence.permissionAssessments()));
            json.set("agentResultContract", OBJECT_MAPPER.valueToTree(
                    AgentExecutionResultFacts.agentResultContractToMap(agentResultContract)));
            json.set("artifactContractResults", OBJECT_MAPPER.valueToTree(artifactContractResults.stream()
                    .map(AgentExecutionResultFacts::artifactContractToMap)
                    .toList()));
            if (rereadReasons != null) {
                json.set("reread_reasons", OBJECT_MAPPER.valueToTree(rereadReasons));
            }
            appendTimelineEvent(json, AgentExecutionTimelineEventKind.CONTRACT_VALIDATED);
            json.set("executionAttempt", OBJECT_MAPPER.valueToTree(executionAttemptToMap(finalized.attempt())));
            json.set("executionOutcome", OBJECT_MAPPER.valueToTree(outcomeToMap(finalized.outcome())));
            AgentRunCommitProtocol.recordOutcome(workspaceRoot, path, result, finalized.outcome(), json);
            new dev.dual.ledger.file.AtomicJsonWriter().write(path, json);
            return finalized.outcome();
        } catch (Exception failure) {
            throw new IllegalStateException("failed to finalize typed agent run metadata", failure);
        }
    }

    static List<AdapterSignal> resultAdapterSignals(NodeResult result) {
        if (result.result().containsKey("adapter_signals")) {
            return adapterSignalsFromValue(result.result().get("adapter_signals"));
        }
        return legacyAdapterSignals(result);
    }

    private static List<AgentExecutionEvidence.PermissionAssessment> permissionAssessments(NodeResult result) {
        var raw = result.result().get(PermissionEvidence.FACT);
        if (raw == null) return List.of();
        if (!(raw instanceof List<?> items)) throw new IllegalArgumentException("permission assessments must be an array");
        return items.stream().map(item -> OBJECT_MAPPER.convertValue(item, AgentExecutionEvidence.PermissionAssessment.class)).toList();
    }

    private static List<AdapterSignal> legacyAdapterSignals(NodeResult result) {
        var reason = text(result.result().get("acpx_failure.reason"));
        if (reason.isBlank()) {
            return List.of();
        }
        var type = switch (reason) {
            case "RECOVERABLE_AGENT_RECONNECT" -> AdapterSignalType.AGENT_RECONNECT_REQUIRED;
            case "RECOVERABLE_AGENT_MODEL_MISMATCH" -> AdapterSignalType.MODEL_MISMATCH;
            case "RECOVERABLE_SESSION_BOOTSTRAP_FAILED" -> AdapterSignalType.SESSION_BOOTSTRAP_FAILED;
            case "RECOVERABLE_SESSION_MISSING" -> AdapterSignalType.SESSION_RESUME_FAILED;
            case "RECOVERABLE_AGENT_AUTH_FAILED" -> AdapterSignalType.AUTH_FAILED;
            case "RECOVERABLE_PROVIDER_CONNECTION_FAILED" -> AdapterSignalType.PROVIDER_CONNECTION_FAILED;
            case "RECOVERABLE_RATE_LIMIT", "RECOVERABLE_AGENT_OVERLOADED" -> AdapterSignalType.RATE_LIMITED;
            case "RECOVERABLE_CONTEXT_WINDOW" -> AdapterSignalType.CONTEXT_WINDOW_EXCEEDED;
            case "RECOVERABLE_AGENT_PERMISSION_BLOCKED" -> AdapterSignalType.PERMISSION_BLOCKED;
            case "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED" -> AdapterSignalType.PROCESS_STALLED;
            case "RECOVERABLE_TRANSPORT_FAILED" -> AdapterSignalType.PROCESS_STALLED;
            default -> null;
        };
        return type == null ? List.of() : List.of(new AdapterSignal(type, reason, 0));
    }

    static List<AdapterSignal> adapterSignalsFromRunMetadata(ObjectNode json) {
        var existing = json.path("adapterSignals");
        if (!existing.isArray()) {
            throw new IllegalArgumentException("typed adapterSignals must be an array");
        }
        var signals = new ArrayList<AdapterSignal>();
        for (var item : existing) {
            if (!item.isObject()) {
                throw new IllegalArgumentException("typed adapterSignals entries must be objects");
            }
            var type = enumValue(AdapterSignalType.class, item.path("type").asText(""), null);
            if (type == null) {
                throw new IllegalArgumentException("typed adapterSignals.type is missing or invalid");
            }
            signals.add(new AdapterSignal(
                    type,
                    item.path("message").asText(""),
                    item.path("observedSequence").isNumber() ? Math.max(0L, item.path("observedSequence").asLong()) : 0L,
                    item.path("source").asText(""),
                    item.path("sessionId").asText(""),
                    item.path("superseded").isBoolean() && item.path("superseded").asBoolean(),
                    item.hasNonNull("operationRef") ? OBJECT_MAPPER.convertValue(item.get("operationRef"), AdapterSignal.OperationRef.class) : null
            ));
        }
        return List.copyOf(signals);
    }

    private static List<AdapterSignal> adapterSignalsFromValue(Object value) {
        if (!(value instanceof List<?> list)) {
            throw new IllegalArgumentException("typed adapter_signals must be a list");
        }
        var signals = new ArrayList<AdapterSignal>();
        for (var item : list) {
            if (!(item instanceof Map<?, ?> map)) {
                throw new IllegalArgumentException("typed adapter_signals entries must be maps");
            }
            var type = enumValue(AdapterSignalType.class, text(map.get("type")), null);
            if (type == null) {
                throw new IllegalArgumentException("typed adapter_signals.type is missing or invalid");
            }
            var sequence = map.get("observedSequence") instanceof Number number
                    ? Math.max(0L, number.longValue())
                    : 0L;
            signals.add(new AdapterSignal(
                    type,
                    text(map.get("message")),
                    sequence,
                    text(map.get("source")),
                    text(map.get("sessionId")),
                    Boolean.TRUE.equals(map.get("superseded")),
                    map.get("operationRef") == null ? null : OBJECT_MAPPER.convertValue(map.get("operationRef"), AdapterSignal.OperationRef.class)
            ));
        }
        return List.copyOf(signals);
    }

    static Map<String, Object> outcomeToMap(AgentExecutionOutcome outcome) {
        var map = new LinkedHashMap<String, Object>();
        map.put("status", outcome.status().name());
        map.put("primaryReason", outcome.primaryReason());
        map.put("nodeMaySucceed", outcome.nodeMaySucceed());
        map.put("retryPolicy", outcome.retryPolicy().name());
        map.put("recoveryCategory", outcome.recoveryCategory().name());
        map.put("operatorMessage", outcome.operatorMessage());
        map.put("secondarySignals", outcome.secondarySignals().stream()
                .map(AgentRunMetadataFinalizer::signalToMap)
                .toList());
        return map;
    }

    private static Map<String, Object> signalToMap(AdapterSignal signal) {
        var map = new LinkedHashMap<String, Object>();
        map.put("type", signal.type().name());
        map.put("severity", signal.type().severity().name());
        map.put("message", signal.message());
        map.put("observedSequence", signal.observedSequence());
        map.put("source", signal.source());
        map.put("sessionId", signal.sessionId());
        map.put("superseded", signal.superseded());
            if (signal.operationRef() != null) map.put("operationRef", signal.operationRef());
        return map;
    }

    private static Map<String, Object> processResultToMap(ProcessResult process) {
        var map = new LinkedHashMap<String, Object>();
        map.put("command", process.command());
        map.put("pid", process.pid());
        map.put("exitCode", process.exitCode());
        map.put("usability", process.usability().name());
        map.put("durationMs", process.durationMs());
        map.put("stdoutPath", process.stdoutPath());
        map.put("stderrPath", process.stderrPath());
        map.put("interrupted", process.interrupted());
        map.put("timedOut", process.timedOut());
        return map;
    }

    private static AgentExecutionAttempt baseAttempt(ObjectNode json, NodeResult result) {
        var attempt = json.path("executionAttempt");
        var runId = firstNonBlank(json.path("runId").asText(""), text(result.result().get("run_id")), "run-unknown");
        return new AgentExecutionAttempt(
                firstNonBlank(attempt.path("attemptId").asText(""), "att-" + runId),
                runId,
                firstNonBlank(json.path("workstreamId").asText(""), attempt.path("workstreamId").asText("")),
                firstNonBlank(json.path("nodeId").asText(""), attempt.path("nodeId").asText("")),
                firstNonBlank(json.path("agent").asText(""), attempt.path("agent").asText(""), text(result.result().get("agent"))),
                AgentExecutionAttemptStatus.RUNNING,
                AgentExecutionProcessStatus.RUNNING,
                null,
                false,
                false,
                firstNonBlank(attempt.path("message").asText(""), "process exited"),
                attempt.path("stderrPath").asText(""),
                attempt.path("transcriptPath").asText(""),
                attempt.path("sessionName").asText(""),
                attempt.path("sessionId").asText(""),
                attempt.path("sessionScope").asText(""),
                attempt.path("sessionSegmentKey").asText(""),
                firstInstant(attempt.path("startedAt").asText(""), json.path("startedAt").asText("")),
                firstInstant(attempt.path("finishedAt").asText(""), json.path("finishedAt").asText(""))
        );
    }

    private static Map<String, Object> executionAttemptToMap(AgentExecutionAttempt attempt) {
        var map = new LinkedHashMap<String, Object>();
        map.put("attemptId", attempt.attemptId());
        map.put("runId", attempt.runId());
        map.put("workstreamId", attempt.workstreamId());
        map.put("nodeId", attempt.nodeId());
        map.put("agent", attempt.agent());
        map.put("status", attempt.status().name());
        map.put("processStatus", attempt.processStatus().name());
        map.put("failureSignal", attempt.failureSignal() == null ? null : attempt.failureSignal().name());
        map.put("recoverable", attempt.recoverable());
        map.put("retrySafe", attempt.retrySafe());
        map.put("message", attempt.message());
        map.put("stderrPath", attempt.stderrPath());
        map.put("transcriptPath", attempt.transcriptPath());
        map.put("sessionName", attempt.sessionName());
        map.put("sessionId", attempt.sessionId());
        map.put("sessionScope", attempt.sessionScope());
        map.put("sessionSegmentKey", attempt.sessionSegmentKey());
        map.put("startedAt", attempt.startedAt() == null ? null : attempt.startedAt().toString());
        map.put("finishedAt", attempt.finishedAt() == null ? null : attempt.finishedAt().toString());
        return map;
    }

    private static Map<String, Object> mergedProcessResult(ObjectNode json, ProcessResult process) {
        var merged = new LinkedHashMap<String, Object>();
        var existing = json.path("processResult");
        if (existing.isObject()) {
            existing.fields().forEachRemaining(entry -> merged.put(entry.getKey(), OBJECT_MAPPER.convertValue(entry.getValue(), Object.class)));
        }
        var semantic = processResultToMap(process);
        for (var entry : semantic.entrySet()) {
            if (entry.getValue() != null && !String.valueOf(entry.getValue()).isBlank()) {
                merged.put(entry.getKey(), entry.getValue());
            }
        }
        return merged;
    }

    static ProcessResult processResultFromRunMetadata(ObjectNode json) {
        var existing = json.path("processResult");
        if (existing.isMissingNode()) {
            return null;
        }
        if (!existing.isObject()) {
            throw new IllegalArgumentException("typed processResult must be an object");
        }
        var usability = enumValue(ProcessUsability.class, existing.path("usability").asText(""), null);
        if (usability == null) {
            throw new IllegalArgumentException("typed processResult.usability is missing or invalid");
        }
        Long pid = existing.path("pid").isNumber() ? existing.path("pid").asLong() : null;
        Integer exitCode = existing.path("exitCode").isNumber() ? existing.path("exitCode").asInt() : null;
        return new ProcessResult(
                existing.path("command").asText(""),
                pid,
                exitCode,
                usability,
                existing.path("durationMs").isNumber() ? Math.max(0L, existing.path("durationMs").asLong()) : 0L,
                existing.path("stdoutPath").asText(""),
                existing.path("stderrPath").asText(""),
                existing.path("interrupted").asBoolean(false),
                existing.path("timedOut").asBoolean(false)
        );
    }

    private static Map<String, Object> adapterSignalToMap(AdapterSignal signal) {
        var map = new LinkedHashMap<String, Object>();
        map.put("type", signal.type().name());
        map.put("severity", signal.type().severity().name());
        map.put("source", signal.source());
        map.put("message", signal.message());
        map.put("sessionId", signal.sessionId());
        map.put("observedSequence", signal.observedSequence());
        map.put("superseded", signal.superseded());
            if (signal.operationRef() != null) map.put("operationRef", signal.operationRef());
        return map;
    }

    private static Instant instantOrNull(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }
        try {
            return Instant.parse(value);
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    private static Instant firstInstant(String first, String second) {
        var parsed = instantOrNull(first);
        return parsed == null ? instantOrNull(second) : parsed;
    }

    private static <E extends Enum<E>> E enumValue(Class<E> type, String value, E fallback) {
        if (value == null || value.isBlank()) {
            return fallback;
        }
        try {
            return Enum.valueOf(type, value);
        } catch (RuntimeException ignored) {
            return fallback;
        }
    }

    private static int intValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        if (value == null) {
            return 0;
        }
        try {
            return Integer.parseInt(String.valueOf(value));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    private static String firstNonBlank(String first, String second) {
        return firstNonBlank(new String[]{first, second});
    }

    private static String firstNonBlank(String... values) {
        if (values == null) {
            return "";
        }
        for (var value : values) {
            if (value != null && !value.isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private static void appendTimelineEvent(ObjectNode json, AgentExecutionTimelineEventKind kind) {
        var timeline = new ArrayList<Map<String, Object>>();
        var existing = json.get("executionTimeline");
        if (existing != null && existing.isArray()) {
            for (var item : existing) {
                timeline.add(OBJECT_MAPPER.convertValue(item, MAP_TYPE));
            }
        }
        var startedAt = instantOrNull(text(json.get("startedAt")));
        var observedAt = Instant.now();
        timeline.add(Map.of(
                "kind", kind.wireName(),
                "source", "runtime",
                "sequence", timeline.size() + 1L,
                "observedAt", observedAt.toString(),
                "elapsedMs", startedAt == null ? 0L : Math.max(0L, Duration.between(startedAt, observedAt).toMillis())
        ));
        json.set("executionTimeline", OBJECT_MAPPER.valueToTree(timeline));
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.execution.ArtifactContractResult;
import dev.dual.core.execution.AgentResultContractResult;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Pattern;

public final class ArtifactContractValidator {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private final AgentResultEnvelopeParser resultParser = new AgentResultEnvelopeParser();
    private final AgentResultEnvelopeValidator resultValidator = new AgentResultEnvelopeValidator();
    private final AgentResultDocumentProjector resultProjector = new AgentResultDocumentProjector();
    private final dev.dual.ledger.file.WorkflowFileLedger ledger;
    private final TaskContractRevisionContextResolver revisionContextResolver;

    public ArtifactContractValidator(dev.dual.ledger.file.WorkflowFileLedger ledger) {
        this.ledger = java.util.Objects.requireNonNull(ledger);
        this.revisionContextResolver = new TaskContractRevisionContextResolver(ledger);
    }
    private final TaskContractProposalRevisionMerger revisionMerger =
            new TaskContractProposalRevisionMerger();

    public NodeResult validate(Path workspaceRoot, NodeDefinition nodeDefinition, NodeResult result) throws Exception {
        return validate(workspaceRoot, "", "", nodeDefinition, List.of(), result);
    }

    public NodeResult validate(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            NodeResult result
    ) throws Exception {
        return validate(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, List.of(), result);
    }

    public NodeResult validate(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result
    ) throws Exception {
        return prepare(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result)
                .complete(workspaceRoot, false, ledger);
    }

    /** Validate in memory, persist one execution decision, then publish only eligible candidates. */
    public NodeResult validateAndFinalize(
            Path workspaceRoot, String workstreamId, String nodeInstanceId,
            NodeDefinition nodeDefinition, List<String> inputRefs, NodeResult result
    ) throws Exception {
        return prepare(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result)
                .complete(workspaceRoot, true, ledger);
    }

    private Validation prepare(
            Path workspaceRoot, String workstreamId, String nodeInstanceId,
            NodeDefinition nodeDefinition, List<String> inputRefs, NodeResult result
    ) throws Exception {
        if (AgentExecutionResultFacts.inputPreparationFailed(result)) return new Validation(result, null);
        if (EvidenceCollection.FAILURE.equals(result.outcome())) return new Validation(result, null);
        if (!"acpx.agent_run".equals(nodeDefinition.handlerType()) || Boolean.TRUE.equals(result.result().get("prepared"))) {
            return new Validation(result, null);
        }
        try {
            EvidenceCollection.verify(ledger, workspaceRoot, workstreamId, nodeInstanceId);
        } catch (java.io.IOException | IllegalArgumentException invalid) {
            return evidenceFailure(result, invalid);
        }
        if (!ContractRegistry.hasContract(nodeDefinition.id())) {
            return new Validation(result, null);
        }
        var acquisitionContract = AgentExecutionResultFacts.agentResultContract(result);
        if (acquisitionContract.present() && !acquisitionContract.valid()) {
            // Re-parsing a well-formed final candidate must not erase the acquisition's stricter diff rejection.
            return contractViolation(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, result,
                    ContractRegistry.forNode(nodeDefinition.id()), "", null,
                    ContractViolation.of("AGENT_RESULT_CONTRACT_VIOLATION", acquisitionContract.validationError(), Map.of()));
        }
        return validateAgentOutput(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result);
    }

    private static Validation evidenceFailure(NodeResult source, Exception failure) {
        return new Validation(evidenceFailureResult(source, failure), null);
    }

    static NodeResult evidenceFailureResult(NodeResult source, Exception failure) {
        var facts = new LinkedHashMap<String, Object>(source.result());
        facts.put("failure_code", EvidenceCollection.FAILURE);
        facts.put("error", String.valueOf(failure.getMessage()));
        var failed = new NodeResult(EvidenceCollection.FAILURE, NodeStatus.FAILED, source.outputRefs(), facts, failure.getMessage());
        if (AgentExecutionResultFacts.present(source)) {
            failed = AgentExecutionResultFacts.attach(failed, AgentExecutionResultFacts.agentResultContract(source),
                    List.of(new ArtifactContractResult("verification_evidence", true, true, false, "", EvidenceCollection.FAILURE,
                            String.valueOf(failure.getMessage()))), AgentExecutionResultFacts.rereadReasons(source));
        }
        return failed;
    }

    private Validation validateAgentOutput(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result
    ) throws Exception {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var contract = ContractRegistry.forNode(nodeDefinition.id());
        ContractViolation lastInvalid = null;
        String lastSourceRef = "";
        var repositoryFactBindingRef = text(result.result().get("repository_fact_binding_ref"));
        var observations = result.result().get(VerificationEvidence.FACT);
        var observationRef = observations == null ? "" : new com.fasterxml.jackson.databind.ObjectMapper()
                .convertValue(observations, dev.dual.core.contract.TaskContract.Reference.class).ref();
        for (int i = result.outputRefs().size() - 1; i >= 0; i--) {
            var ref = result.outputRefs().get(i);
            if (ref.startsWith("artifact://")
                    || !ref.endsWith(".json")
                    || ref.equals(repositoryFactBindingRef) || ref.equals(observationRef)) {
                continue;
            }
            var path = root.resolve(ref).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path)) {
                continue;
            }
            var candidate = Files.readString(path, StandardCharsets.UTF_8);
            var parsed = resultParser.parse(candidate);
            if (!parsed.valid()) {
                lastInvalid = ContractViolation.of(parsed.errorCode(), parsed.message(), Map.of());
                lastSourceRef = ref;
                break;
            }
            var expectedRunId = text(result.result().get("run_id"));
            var validation = resultValidator.validate(parsed.envelope(), workstreamId, expectedRunId, contract);
            if (!validation.valid()) {
                lastInvalid = ContractViolation.of(
                        "AGENT_RESULT_CONTRACT_VIOLATION",
                        "AgentResultEnvelope failed contract validation: " + validation.errors(),
                        Map.of("errors", validation.errors())
                );
                lastSourceRef = ref;
                break;
            }
            try {
                EvidenceCollection.verifyResult(ledger, root, workstreamId, nodeInstanceId, parsed.envelope().result());
            } catch (java.io.IOException | IllegalArgumentException invalid) {
                return evidenceFailure(result, invalid);
            }
            if (parsed.envelope().result() instanceof AgentResultEnvelope.DesignResult design) {
                var errors = DesignScopeValidator.validate(ledger, root, workstreamId, design.design());
                if (!errors.isEmpty()) {
                    return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                            parsed.envelope(), ContractViolation.of("DESIGN_SCOPE_INVALID",
                                    "Design is not within the approved contract", Map.of("errors", errors)));
                }
            }
            if (parsed.envelope().result() instanceof AgentResultEnvelope.PlanResult plan) {
                var errors = PlanScopeValidator.validate(ledger, root, workstreamId, plan.plan());
                if (!errors.isEmpty()) {
                    return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                            parsed.envelope(), ContractViolation.of("PLAN_SCOPE_INVALID",
                                    "Plan is not within the approved contract", Map.of("errors", errors)));
                }
            }
            var repositoryFactBinding = resolveRepositoryFactBinding(
                    root, workstreamId, nodeInstanceId, expectedRunId, result);
            var proposalResolution = resolveProposalCandidate(
                    root, workstreamId, nodeInstanceId, nodeDefinition, parsed.envelope(), ref,
                    repositoryFactBinding);
            if (proposalResolution.failure() != null) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                        parsed.envelope(), proposalResolution.failure());
            }
            return withResultSidecars(
                    root, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result, contract,
                    parsed.envelope(), ref, path, proposalResolution
            );
        }
        return contractViolation(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, result, contract,
                lastSourceRef, null, lastInvalid);
    }

    private ProposalResolution resolveProposalCandidate(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            AgentResultEnvelope envelope,
            String sourceOutputRef,
            RepositoryFactBinding.Verification repositoryFactBinding
    ) {
        var isProposal = envelope.result() instanceof AgentResultEnvelope.TaskContractProposalResult;
        var isPatch = envelope.result() instanceof AgentResultEnvelope.TaskContractRevisionPatchResult;
        if (!isProposal && !isPatch) {
            return ProposalResolution.none();
        }
        if (!repositoryFactBinding.valid()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REPOSITORY_FACT_BINDING_INVALID",
                    "task contract proposal has no valid repository fact occurrence binding",
                    Map.of("errors", repositoryFactBinding.errors())));
        }
        if (!"intake.claude_brainstorm".equals(nodeDefinition.id())) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_PROPOSAL_INVALID",
                    "task contract proposal output is only allowed for intake",
                    Map.of()));
        }
        var resolved = revisionContextResolver.resolveForNode(root, workstreamId, nodeInstanceId);
        if (!resolved.valid()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REVISION_CONTEXT_INVALID",
                    "task contract proposal revision context could not be resolved",
                    Map.of("errors", resolved.errors())));
        }
        var context = resolved.context();
        TaskContractProposal proposal;
        AgentOutputContractDocument.ProposalDerivation derivation = null;
        if (isProposal) {
            if (context.revision()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_SHAPE_INVALID",
                        "revision iteration requires task_contract_revision_patch",
                        Map.of()));
            }
            var proposalResult = (AgentResultEnvelope.TaskContractProposalResult) envelope.result();
            var resolvedScope = new TaskContractScopeResolver().resolve(
                    proposalResult.scope().included(), root);
            if (!resolvedScope.valid()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_SCOPE_RESOLUTION_FAILED",
                        "task contract scope paths could not be resolved",
                        Map.of("errors", resolvedScope.errors())));
            }
            proposal = resultProjector.taskContractProposal(proposalResult, resolvedScope.entries());
        } else {
            if (!context.revision()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_SHAPE_INVALID",
                        "initial iteration requires task_contract_proposal",
                        Map.of()));
            }
            var merged = revisionMerger.merge(
                    context, (AgentResultEnvelope.TaskContractRevisionPatchResult) envelope.result(), root);
            if (!merged.valid()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_PATCH_INVALID",
                        "task contract revision patch could not be merged",
                        Map.of("errors", merged.errors())));
            }
            proposal = merged.proposal();
            derivation = new AgentOutputContractDocument.ProposalDerivation(
                    "revision_patch_merge",
                    context.previousReference().proposalId(),
                    context.previousReference().sha256(),
                    context.previousReference(),
                    sourceOutputRef);
        }

        var proposalValidator = new TaskContractProposalValidator();
        var errors = proposalValidator.validate(proposal, root,
                context.approvedScopeBaseline(), context.originalBaseCommit(), context.scopeReviewCandidates());
        if (!errors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_PROPOSAL_VALIDATION_FAILED",
                    "task_contract_proposal failed mechanical validation: " + errors,
                    Map.of("errors", errors)));
        }
        var coverageErrors = context.revision()
                ? proposalValidator.validateRevisionCoverage(proposal, context.obligations())
                : proposalValidator.validateInitialIteration(proposal);
        if (!coverageErrors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REVISION_COVERAGE_INVALID",
                    "task_contract_proposal failed revision obligation coverage",
                    Map.of("errors", coverageErrors)));
        }
        var evidenceErrors = proposalValidator.validateEvidenceTraceability(
                proposal, root, repositoryFactBinding.verified());
        if (!evidenceErrors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_EVIDENCE_TRACEABILITY_INVALID",
                    "task_contract_proposal is not grounded in the tracked inventory",
                    Map.of("errors", evidenceErrors)));
        }
        if (context.revision()) {
            var deltaErrors = proposalValidator.validateRevisionDelta(context.previousProposal(), proposal);
            if (!deltaErrors.isEmpty()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_DELTA_INVALID",
                        "task_contract_proposal contains an invalid revision delta",
                        Map.of(
                                "error_codes", deltaErrors.stream()
                                        .map(TaskContractProposalValidator.RevisionDeltaError::code).distinct().toList(),
                                "errors", deltaErrors.stream()
                                        .map(TaskContractProposalValidator.RevisionDeltaError::message).toList())));
            }
        }
        return new ProposalResolution(proposal, derivation, repositoryFactBinding.verified(), null);
    }

    private Validation withResultSidecars(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result,
            NodeOutputContract contract,
            AgentResultEnvelope envelope,
            String outputRef,
            Path outputPath,
            ProposalResolution proposalResolution
    ) throws Exception {
        var document = resultProjector.outputContract(
                envelope, contract, nodeDefinition.handlerType(), nodeInstanceId, outputRef,
                proposalResolution.proposal(), proposalResolution.derivation());
        var requiredReviewSubject = text(nodeDefinition.config().get("review_subject_artifact"));
        if (!requiredReviewSubject.isBlank()) {
            if (!"task_contract_proposal".equals(requiredReviewSubject)) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope,
                        ContractViolation.of("REVIEW_SUBJECT_UNSUPPORTED",
                                "unsupported review_subject_artifact: " + requiredReviewSubject,
                                Map.of("review_subject_artifact", requiredReviewSubject)));
            }
            var reviewSubject = TaskContractProposalReference.resolveFromRefs(
                    root, workstreamId, inputRefs, OBJECT_MAPPER);
            if (reviewSubject.isEmpty()) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope,
                        ContractViolation.of("REVIEW_SUBJECT_MISSING",
                                "exactly one validated task_contract_proposal reference is required",
                                Map.of("review_subject_artifact", requiredReviewSubject)));
            }
            document.put("review_subject", reviewSubject.get().reference().toMap());
        }
        if (proposalResolution.proposal() != null) {
            document.put("repository_fact_binding",
                    RepositoryFactBinding.reference(proposalResolution.repositoryFactBinding()).toMap());
        }
        AgentContractSemantics.addSidecarFields(document);
        var validatedDocument = AgentOutputContractDocument.from(document);
        var semanticFailure = AgentContractSemantics.validateOutputContract(validatedDocument);
        if (semanticFailure.isPresent()) {
            return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                    envelope,
                    semanticFailure.get());
        }

        var sidecarPath = AgentOutputContractSidecar.pathFor(outputPath);
        if (AuthoredStageLineageResolver.participates(nodeDefinition.id())) {
            try {
                var authoredRef = AuthoredExecutionContext.validatePublication(ledger, root, workstreamId, nodeInstanceId,
                        envelope.runId(), envelope.result());
                document.put("authored_context", Map.of("ref", authoredRef.ref(), "sha256", authoredRef.sha256()));
            } catch (java.io.IOException | IllegalArgumentException failure) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope, ContractViolation.of("AUTHORED_CONTEXT_INVALID", failure.getMessage(), Map.of()));
            }
        }
        try {
            EvidenceCollection.verifyResult(ledger, root, workstreamId, nodeInstanceId, envelope.result());
        } catch (java.io.IOException | IllegalArgumentException invalid) {
            return evidenceFailure(result, invalid);
        }
        try {
            VerificationEvidence.verify(ledger, root, workstreamId, nodeInstanceId, result, envelope.result());
        } catch (java.io.IOException | IllegalArgumentException invalid) {
            return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                    envelope, ContractViolation.of("VERIFICATION_EVIDENCE_INVALID", invalid.getMessage(), Map.of()));
        }
        var validated = AgentExecutionResultFacts.attach(result,
                AgentResultContractResult.valid(envelope.result().decision()),
                List.of(ArtifactContractResult.requiredValid(envelope.result().artifactType())),
                document.get("reread_reasons"));
        validated = PermissionEvidence.assess(ledger, root, workstreamId, nodeInstanceId, nodeDefinition.id(),
                validated, envelope.result());
        var bytes = (OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(document) + "\n").getBytes(StandardCharsets.UTF_8);
        var sidecarRef = root.relativize(sidecarPath).toString();
        var writes = new LinkedHashMap<String, String>();
        writes.put(sidecarRef, java.util.Base64.getEncoder().encodeToString(bytes));
        var refs = new ArrayList<>(result.outputRefs());
        if (!refs.contains(sidecarRef)) refs.add(sidecarRef);
        var fields = new LinkedHashMap<String, Object>();
        fields.put("decision", envelope.result().decision()); fields.put("summary", envelope.result().summary());
        fields.put("contract_sidecar_ref", sidecarRef); fields.put("contract_sidecar_sha256", TaskContractArtifactWriter.sha256(bytes));
        if (proposalResolution.proposal() != null) {
            var proposal = TaskContractProposalReference.preparePublication(root, workstreamId, sidecarPath, validatedDocument, bytes, OBJECT_MAPPER);
            writes.put(proposal.referenceRef(), java.util.Base64.getEncoder().encodeToString(OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsBytes(proposal.reference())));
            refs.add(proposal.referenceRef()); fields.put("task_contract_proposal_ref", proposal.referenceRef());
            fields.put("task_contract_proposal_id", proposal.reference().proposalId());
        }
        if (envelope.result() instanceof AgentResultEnvelope.PlanResult plan) {
            var ref = root.relativize(PlanArtifactSidecar.pathFor(outputPath)).toString();
            writes.put(ref, java.util.Base64.getEncoder().encodeToString((OBJECT_MAPPER.writerWithDefaultPrettyPrinter()
                    .writeValueAsString(resultProjector.planArtifact(plan)) + "\n").getBytes(StandardCharsets.UTF_8)));
            refs.add(ref); fields.put("plan_artifact_ref", ref);
        }
        return new Validation(validated, new Publication(workstreamId, nodeInstanceId, refs, fields, writes,
                new dev.dual.core.contract.TaskContract.Reference(outputRef, TaskContractArtifactWriter.sha256(outputPath))));
    }

    /** Fixed byte publication, subordinate to the unique execution outcome. No reevaluation on restart. */
    record Publication(String workstream, String node, List<String> outputRefs,
                       Map<String, Object> fields, Map<String, String> bytes,
                       dev.dual.core.contract.TaskContract.Reference candidate) {
        NodeResult publish(dev.dual.ledger.file.WorkflowFileLedger ledger, Path root, NodeResult execution) throws Exception {
            EvidenceCollection.verify(ledger, root, workstream, node);
            VerificationEvidence.verifyPublication(ledger, root, workstream, node, execution, candidate);
            for (var entry : bytes.entrySet()) {
                var path = root.toAbsolutePath().normalize().resolve(entry.getKey()).normalize();
                if (!path.startsWith(root.toAbsolutePath().normalize()) || Path.of(entry.getKey()).isAbsolute())
                    throw new java.io.IOException("publication escapes workspace");
                var content = java.util.Base64.getDecoder().decode(entry.getValue());
                if (Files.exists(path)) {
                    if (!java.util.Arrays.equals(Files.readAllBytes(path), content)) throw new java.io.IOException("publication target changed: " + entry.getKey());
                } else new dev.dual.ledger.file.AtomicJsonWriter().writeBytes(path, content);
            }
            var facts = new LinkedHashMap<String, Object>(execution.result()); facts.putAll(fields);
            return new NodeResult(execution.outcome(), execution.status(), outputRefs, facts, execution.errorMessage());
        }
    }

    private record Validation(NodeResult result, Publication publication) {
        NodeResult complete(Path root, boolean persistExecution, dev.dual.ledger.file.WorkflowFileLedger ledger) throws Exception {
            var finalizer = new AgentRunMetadataFinalizer();
            if (persistExecution && publication != null) AgentRunCommitProtocol.recordPublication(root, result, publication);
            var execution = persistExecution ? finalizer.finalizeNodeResult(root, result)
                    : publication == null ? result : finalizer.assessPublication(root, result);
            if (publication == null || execution.status() == NodeStatus.FAILED) return execution;
            return publication.publish(ledger, root, execution);
        }
    }

    public static NodeResult completeRecorded(dev.dual.ledger.file.WorkflowFileLedger ledger, Path root, dev.dual.ledger.file.WorkstreamPaths paths,
                                              dev.dual.ledger.file.NodeExecutionDocument execution) throws Exception {
        var candidate = AgentRunCommitProtocol.recordedCandidate(paths, execution);
        var finalized = new AgentRunMetadataFinalizer().finalizeNodeResult(root, candidate);
        var publication = AgentRunCommitProtocol.recordedPublication(root, paths, execution);
        if (publication == null || finalized.status() == NodeStatus.FAILED) return finalized;
        return publication.publish(ledger, root, finalized);
    }

    private record ProposalResolution(
            TaskContractProposal proposal,
            AgentOutputContractDocument.ProposalDerivation derivation,
            RepositoryFactBinding.Verified repositoryFactBinding,
            ContractViolation failure
    ) {
        static ProposalResolution none() {
            return new ProposalResolution(null, null, null, null);
        }

        static ProposalResolution failure(ContractViolation failure) {
            return new ProposalResolution(null, null, null, failure);
        }
    }

    private RepositoryFactBinding.Verification resolveRepositoryFactBinding(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            NodeResult result
    ) {
        var bindingRef = text(result.result().get("repository_fact_binding_ref"));
        var bindingSha256 = text(result.result().get("repository_fact_binding_sha256"));
        if (bindingRef.isBlank() || bindingSha256.isBlank() || !result.outputRefs().contains(bindingRef)) {
            return new RepositoryFactBinding.Verification(
                    null,
                    List.of("adapter-owned repository fact binding ref/sha is missing or not routed"));
        }
        return RepositoryFactBinding.verify(
                root,
                workstreamId,
                bindingRef,
                bindingSha256,
                nodeInstanceId,
                runId,
                OBJECT_MAPPER);
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        return list.stream()
                .filter(item -> item != null && !String.valueOf(item).isBlank())
                .map(item -> String.valueOf(item).trim())
                .toList();
    }

    private static String normalizeRepoPath(String value) {
        var text = value == null ? "" : value.trim();
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    private static Validation contractViolation(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            NodeResult result,
            NodeOutputContract contract,
            String sourceOutputRef,
            AgentResultEnvelope validatedEnvelope,
            ContractViolation lastInvalid
    ) throws Exception {
        var reason = lastInvalid == null
                ? "AGENT_RESULT_MISSING"
                : lastInvalid.errorCode();
        var message = lastInvalid == null
                ? "No readable agent output artifact found for contract validation."
                : lastInvalid.message();
        var details = lastInvalid == null ? Map.<String, Object>of() : lastInvalid.details();
        var diagnostic = ContractFailureDiagnosticWriter.write(
                workspaceRoot,
                workstreamId,
                nodeInstanceId,
                nodeDefinition,
                contract,
                sourceOutputRef,
                reason,
                message,
                details
        );
        var failed = new LinkedHashMap<String, Object>();
        failed.putAll(result.result());
        failed.put("reason", "AGENT_OUTPUT_CONTRACT_VIOLATION");
        failed.put("contract_node_id", nodeDefinition.id());
        failed.put("contract_required_keys", List.copyOf(contract.requiredKeys()));
        failed.put("contract_allowed_decisions", List.copyOf(contract.allowedDecisions()));
        failed.put("parse_error", Map.of(
                "code", reason,
                "message", message,
                "details", details
        ));
        if (diagnostic.present()) {
            failed.put("contract_failure_diagnostic_ref", diagnostic.jsonRef());
            failed.put("contract_failure_diagnostic_markdown_ref", diagnostic.markdownRef());
        }
        failed.put("message", message);
        var outputRefs = new ArrayList<>(result.outputRefs());
        if (diagnostic.present() && !outputRefs.contains(diagnostic.jsonRef())) {
            outputRefs.add(diagnostic.jsonRef());
        }
        if (diagnostic.present() && !outputRefs.contains(diagnostic.markdownRef())) {
            outputRefs.add(diagnostic.markdownRef());
        }
        return new Validation(AgentExecutionResultFacts.attach(new NodeResult(
                "AGENT_OUTPUT_CONTRACT_VIOLATION",
                NodeStatus.FAILED,
                outputRefs,
                failed,
                message
        ), terminalResultFor(reason, message, validatedEnvelope),
                List.of(artifactResultFor(nodeDefinition, reason, message, validatedEnvelope)), null), null);
    }

    private static AgentResultContractResult terminalResultFor(
            String reason,
            String message,
            AgentResultEnvelope validatedEnvelope
    ) {
        if (validatedEnvelope != null) {
            return AgentResultContractResult.valid(validatedEnvelope.result().decision());
        }
        if (reason == null || reason.isBlank() || "AGENT_RESULT_MISSING".equals(reason)) {
            return AgentResultContractResult.missing();
        }
        return AgentResultContractResult.invalid(message);
    }

    private static ArtifactContractResult artifactResultFor(
            NodeDefinition nodeDefinition,
            String reason,
            String message,
            AgentResultEnvelope validatedEnvelope
    ) {
        if (validatedEnvelope != null) {
            return new ArtifactContractResult(
                    requiredArtifactTypeOrDefault(nodeDefinition),
                    true,
                    true,
                    false,
                    "",
                    reason,
                    message
            );
        }
        if (reason != null && (reason.startsWith("AGENT_RESULT_") && !"AGENT_RESULT_MISSING".equals(reason))) {
            return new ArtifactContractResult(
                    requiredArtifactTypeOrDefault(nodeDefinition),
                    true,
                    false,
                    false,
                    "",
                    reason,
                    message
            );
        }
        return ArtifactContractResult.optionalMissing(requiredArtifactTypeOrDefault(nodeDefinition));
    }

    private static String requiredArtifactType(NodeDefinition nodeDefinition) {
        var configured = text(nodeDefinition.config().get("expected_artifact"));
        if (!configured.isBlank()) {
            return configured;
        }
        var contract = ContractRegistry.forNode(nodeDefinition.id());
        return contract.outputArtifactTypes().size() == 1
                ? contract.outputArtifactTypes().iterator().next()
                : "agent_output_contract";
    }

    private static String requiredArtifactTypeOrDefault(NodeDefinition nodeDefinition) {
        var required = requiredArtifactType(nodeDefinition);
        return required == null || required.isBlank() ? "agent_output_contract" : required;
    }

    private static Optional<Path> resolveWorkspaceRef(Path root, String ref) {
        if (ref == null || ref.isBlank()) {
            return Optional.empty();
        }
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root)) {
            return Optional.empty();
        }
        return Optional.of(path);
    }

    private static Object fieldOrLegacy(ObjectNode node, String field, String legacyField) {
        if (node.has(field)) {
            return OBJECT_MAPPER.convertValue(node.get(field), Object.class);
        }
        return OBJECT_MAPPER.convertValue(node.path(legacyField), Object.class);
    }

    private static String firstNonBlank(String first, String second) {
        return firstNonBlank(new String[]{first, second});
    }

    private static String firstNonBlank(String... values) {
        if (values == null) {
            return "";
        }
        for (var value : values) {
            if (value != null && !value.isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static Optional<Map<String, Object>> readMap(Path path) {
        try {
            return Optional.of(OBJECT_MAPPER.readValue(path.toFile(), MAP_TYPE));
        } catch (Exception ignored) {
            return Optional.empty();
        }
    }

    private static List<String> capabilityKinds(ObjectNode report) {
        var values = new LinkedHashSet<String>();
        for (var item : mapList(OBJECT_MAPPER.convertValue(report.path("actualCapabilityUsages"), Object.class))) {
            var kind = text(item.get("kind"));
            if (!kind.isBlank()) {
                values.add(kind);
            }
        }
        return List.copyOf(values);
    }

    private static List<Map<String, Object>> mapList(Object value) {
        if (!(value instanceof Iterable<?> iterable)) {
            return List.of();
        }
        var values = new ArrayList<Map<String, Object>>();
        for (var item : iterable) {
            if (!(item instanceof Map<?, ?> map)) {
                continue;
            }
            var copy = new LinkedHashMap<String, Object>();
            for (var entry : map.entrySet()) {
                if (entry.getKey() instanceof String key) {
                    copy.put(key, entry.getValue());
                }
            }
            values.add(copy);
        }
        return List.copyOf(values);
    }

    private static Map<String, String> stringMap(Object value) {
        if (!(value instanceof Map<?, ?> map)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, String>();
        for (var entry : map.entrySet()) {
            if (entry.getKey() instanceof String key && entry.getValue() != null) {
                var text = String.valueOf(entry.getValue()).trim();
                if (!text.isBlank()) {
                    copy.put(key, text);
                }
            }
        }
        return Map.copyOf(copy);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class ArtifactValidateHandler implements TaskHandler {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .enable(SerializationFeature.INDENT_OUTPUT);

    @Override
    public String type() {
        return "artifact.validate";
    }

    @Override
    public NodeResult execute(TaskContext context) throws Exception {
        var qualified = qualifiedContract(context);
        if (qualified.failure() != null) {
            return qualificationFailure(qualified.failure());
        }
        var evidenceDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId())
                .resolve("artifacts")
                .resolve("git-evidence");
        Files.createDirectories(evidenceDir);

        var evidence = collectEvidence(context.workspaceRoot(), context.workstreamId(), evidenceDir);
        writeEvidenceJson(evidenceDir.resolve("git-evidence.json"), evidence);
        var evaluation = evaluateChangeScope(evidence, qualified.contract());
        var evaluationPath = evidenceDir.resolve("change-scope-evaluation.json");
        OBJECT_MAPPER.writeValue(evaluationPath.toFile(), evaluation);
        var occurrence = ChangeScopeEvaluationArtifact.publish(
                context.workspaceRoot(),
                context.workstreamId(),
                context.instance().nodeInstanceId(),
                evaluation);

        var outputRefs = new ArrayList<String>();
        outputRefs.addAll(AgentEvidenceIndex.fromRefs(
                        context.ledger(), context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), OBJECT_MAPPER)
                .validatedSidecarRefs(context.workspaceRoot()));
        for (String fileName : List.of(
                "git-evidence.json",
                "base-commit.txt",
                "head-commit.txt",
                "branch.txt",
                "git-root.txt",
                "git-status-short.txt",
                "git-name-status.txt",
                "diff.stat",
                "diff.patch",
                "changed-files.txt",
                "hygiene-warnings.txt",
                "change-scope-evaluation.json"
        )) {
            var path = evidenceDir.resolve(fileName);
            if (Files.exists(path)) {
                outputRefs.add(toWorkspaceRef(context.workspaceRoot(), path));
            }
        }
        outputRefs.add(occurrence.ref());

        var result = new LinkedHashMap<String, Object>();
        result.put("validation", evidence.available() ? "git_evidence_collected" : "git_unavailable");
        result.put("mode", "git-evidence");
        result.put("git_available", evidence.available());
        result.put("has_changes", evidence.hasChanges());
        result.put("changed_file_count", evidence.changedFileCount());
        result.put("hygiene_warning_count", evidence.hygieneWarningCount());
        result.put("change_scope_status", evaluation.status().name());
        result.put("change_scope_violation_count", evaluation.violations().size());
        result.put("change_scope_missing_declared_count", evaluation.missingDeclared().size());
        result.put("evidence_path", toWorkspaceRef(
                context.workspaceRoot(),
                evidenceDir.resolve("git-evidence.json")
        ));
        result.put("change_scope_evaluation_path", toWorkspaceRef(context.workspaceRoot(), evaluationPath));
        result.put("change_scope_evaluation_ref", occurrence.ref());
        result.put("change_scope_evaluation_sha256", occurrence.sha256());
        result.put("error", evidence.error());

        if (!evaluation.passed()) {
            var outcome = evaluation.status() == ChangeScopeEvaluation.Status.UNAVAILABLE
                    ? "CHANGE_SCOPE_EVIDENCE_UNAVAILABLE"
                    : "CHANGE_SCOPE_VIOLATION";
            var error = evaluation.error() == null
                    ? "actual Git changes do not satisfy TaskContract.scope"
                    : evaluation.error();
            if (evaluation.status() == ChangeScopeEvaluation.Status.FAIL && routesScopeViolation(context)) {
                if (qualified.reference() != null) {
                    result.putAll(new TaskContractRevisionContextResolver(context.ledger()).captureScopeReworkBaseline(
                            context.workspaceRoot(), context.workstreamId(), qualified.reference(), occurrence));
                }
                result.put("change_scope_disposition", "CHANGE_SCOPE_VIOLATION");
                result.put("change_scope_message", error);
                return new NodeResult(outcome, NodeStatus.COMPLETED, outputRefs, result, null);
            }
            return new NodeResult(outcome, NodeStatus.FAILED, outputRefs, result, error);
        }
        return NodeResult.completed("completed", outputRefs, result);
    }

    private static boolean routesScopeViolation(TaskContext context) {
        var configured = context.definition().config().get("route_scope_violation");
        if (configured == null) {
            return false;
        }
        if (!(configured instanceof Boolean enabled)) {
            throw new IllegalArgumentException("route_scope_violation must be a boolean");
        }
        return enabled;
    }

    private static GitEvidence collectEvidence(Path workdir, String workstreamId, Path evidenceDir) throws IOException, InterruptedException {
        var generatedAt = Instant.now().toString();
        var gitRoot = git(workdir, "rev-parse", "--show-toplevel");
        if (gitRoot.exitCode() != 0) {
            return new GitEvidence(
                    "1",
                    false,
                    workdir.toAbsolutePath().normalize().toString(),
                    null,
                    null,
                    null,
                    null,
                    null,
                    null,
                    null,
                    false,
                    0,
                    0,
                    generatedAt,
                    "git repository unavailable: " + gitRoot.output().trim(),
                    List.of()
            );
        }

        var branchResult = git(workdir, "branch", "--show-current");
        var headResult = git(workdir, "rev-parse", "HEAD");
        var statusResult = git(workdir, "status", "--short", "--untracked-files=all", "--", ".", ":!.agent");
        if (branchResult.exitCode() != 0 || headResult.exitCode() != 0 || statusResult.exitCode() != 0) {
            return new GitEvidence(
                    "1",
                    false,
                    workdir.toAbsolutePath().normalize().toString(),
                    gitRoot.output().trim(),
                    null,
                    null,
                    null,
                    null,
                    null,
                    null,
                    false,
                    0,
                    0,
                    generatedAt,
                    "required Git evidence command failed",
                    List.of()
            );
        }
        var branch = branchResult.output().trim();
        var headCommit = headResult.output().trim();
        var base = readWorkspaceBase(workdir, workstreamId);
        var statusShort = statusResult.output();
        var untrackedResult = git(
                workdir,
                "ls-files",
                "--others",
                "--exclude-standard",
                "-z",
                "--",
                ".",
                ":!.agent"
        );
        if (untrackedResult.exitCode() != 0) {
            return unavailableGitEvidence(
                    workdir,
                    gitRoot.output().trim(),
                    branch,
                    base,
                    headCommit,
                    generatedAt,
                    "git ls-files --others failed: " + untrackedResult.output().trim()
            );
        }
        final List<String> untrackedFiles;
        try {
            untrackedFiles = parseNulPaths(untrackedResult.output());
        } catch (IllegalArgumentException exception) {
            return unavailableGitEvidence(
                    workdir,
                    gitRoot.output().trim(),
                    branch,
                    base,
                    headCommit,
                    generatedAt,
                    "git ls-files --others returned malformed NUL framing: " + exception.getMessage()
            );
        }
        var branchRange = base.baseCommit() == null || base.baseCommit().isBlank()
                ? null
                : base.baseCommit() + "...HEAD";
        if (branchRange != null && !commitExists(workdir, base.baseCommit())) {
            branchRange = null;
        }
        var diffStat = buildDiffStat(workdir, untrackedFiles, branchRange);
        var diffPatch = buildDiffPatch(workdir, untrackedFiles, branchRange);
        var nameStatus = buildNameStatus(workdir, untrackedFiles, base.baseCommit());
        if (nameStatus.exitCode() != 0) {
            return new GitEvidence(
                    "1",
                    false,
                    workdir.toAbsolutePath().normalize().toString(),
                    gitRoot.output().trim(),
                    branch,
                    base.baseBranch(),
                    base.baseCommit(),
                    headCommit,
                    base.source(),
                    branchRange,
                    false,
                    0,
                    0,
                    generatedAt,
                    "git diff --name-status failed: " + nameStatus.output().trim(),
                    List.of()
            );
        }
        final List<ChangeScopeEvaluation.ActualChange> actualChanges;
        try {
            actualChanges = ChangeScopeEvaluator.parseNameStatus(nameStatus.exitCode(), nameStatus.output());
        } catch (IllegalArgumentException exception) {
            return unavailableGitEvidence(
                    workdir,
                    gitRoot.output().trim(),
                    branch,
                    base,
                    headCommit,
                    generatedAt,
                    "git diff --name-status returned malformed NUL framing: " + exception.getMessage()
            );
        }
        var changedFiles = actualChanges.stream()
                .map(ChangeScopeEvaluation.ActualChange::path)
                .distinct()
                .toList();
        var hygieneWarnings = hygieneWarnings(changedFiles);

        write(evidenceDir.resolve("git-root.txt"), gitRoot.output().trim() + "\n");
        write(evidenceDir.resolve("branch.txt"), branch + "\n");
        write(evidenceDir.resolve("base-commit.txt"), textOrEmpty(base.baseCommit()) + "\n");
        write(evidenceDir.resolve("head-commit.txt"), headCommit + "\n");
        write(evidenceDir.resolve("git-status-short.txt"), statusShort);
        write(evidenceDir.resolve("git-name-status.txt"), nameStatus.output());
        write(evidenceDir.resolve("diff.stat"), diffStat);
        write(evidenceDir.resolve("diff.patch"), diffPatch);
        var changedFilesText = String.join("\n", changedFiles) + (changedFiles.isEmpty() ? "" : "\n");
        write(evidenceDir.resolve("changed-files.txt"), changedFilesText);
        if (!hygieneWarnings.isEmpty()) {
            write(evidenceDir.resolve("hygiene-warnings.txt"), String.join("\n", hygieneWarnings) + "\n");
        }

        return new GitEvidence(
                "1",
                true,
                workdir.toAbsolutePath().normalize().toString(),
                gitRoot.output().trim(),
                branch,
                base.baseBranch(),
                base.baseCommit(),
                headCommit,
                base.source(),
                branchRange,
                !statusShort.isBlank() || !changedFiles.isEmpty(),
                changedFiles.size(),
                hygieneWarnings.size(),
                generatedAt,
                null,
                actualChanges
        );
    }

    private static GitEvidence unavailableGitEvidence(
            Path workdir,
            String gitRoot,
            String branch,
            WorkspaceBase base,
            String headCommit,
            String generatedAt,
            String error
    ) {
        return new GitEvidence(
                "1",
                false,
                workdir.toAbsolutePath().normalize().toString(),
                gitRoot,
                branch,
                base.baseBranch(),
                base.baseCommit(),
                headCommit,
                base.source(),
                null,
                false,
                0,
                0,
                generatedAt,
                error,
                List.of()
        );
    }

    private static CommandResult buildNameStatus(Path workdir, List<String> untrackedFiles, String baseCommit)
            throws IOException, InterruptedException {
        var comparisonBase = baseCommit != null && !baseCommit.isBlank() && commitExists(workdir, baseCommit)
                ? baseCommit
                : "HEAD";
        var result = git(
                workdir,
                "diff",
                "--name-status",
                "-z",
                "--find-renames",
                comparisonBase,
                "--",
                ".",
                ":!.agent"
        );
        if (result.exitCode() != 0) {
            return result;
        }
        var builder = new StringBuilder(result.output());
        for (var file : untrackedFiles) {
            if (!Files.isDirectory(workdir.resolve(file))) {
                builder.append("A").append('\0').append(file).append('\0');
            }
        }
        return new CommandResult(0, builder.toString());
    }

    private static String buildDiffStat(Path workdir, List<String> untrackedFiles, String branchRange)
            throws IOException, InterruptedException {
        var builder = new StringBuilder();
        if (branchRange != null) {
            builder.append(git(workdir, "diff", "--stat", branchRange, "--", ".", ":!.agent").output());
        }
        builder.append(git(workdir, "diff", "--cached", "--stat", "--", ".", ":!.agent").output());
        builder.append(git(workdir, "diff", "--stat", "--", ".", ":!.agent").output());
        for (String file : untrackedFiles) {
            if (Files.isDirectory(workdir.resolve(file))) {
                continue;
            }
            var result = git(workdir, "diff", "--no-index", "--stat", "--", "/dev/null", file);
            if (!result.output().isBlank()) {
                builder.append(result.output());
            }
        }
        return builder.toString();
    }

    private static String buildDiffPatch(Path workdir, List<String> untrackedFiles, String branchRange)
            throws IOException, InterruptedException {
        var builder = new StringBuilder();
        if (branchRange != null) {
            builder.append(git(workdir, "diff", branchRange, "--", ".", ":!.agent").output());
        }
        builder.append(git(workdir, "diff", "--cached", "--", ".", ":!.agent").output());
        builder.append(git(workdir, "diff", "--", ".", ":!.agent").output());
        for (String file : untrackedFiles) {
            if (Files.isDirectory(workdir.resolve(file))) {
                continue;
            }
            var result = git(workdir, "diff", "--no-index", "--", "/dev/null", file);
            if (!result.output().isBlank()) {
                builder.append(result.output());
            }
        }
        return builder.toString();
    }

    private static WorkspaceBase readWorkspaceBase(Path workdir, String workstreamId) throws IOException {
        if (workstreamId == null || workstreamId.isBlank()) {
            return WorkspaceBase.unavailable();
        }
        var paths = new WorkstreamPaths(workdir, new dev.dual.core.id.DualId(workstreamId));
        if (!Files.isRegularFile(paths.workstreamJson())) {
            return WorkspaceBase.unavailable();
        }
        var workstream = OBJECT_MAPPER.readTree(paths.workstreamJson().toFile());
        var workspaceId = workstream.path("primaryWorkspaceId").asText("");
        if (workspaceId.isBlank()) {
            return WorkspaceBase.unavailable();
        }
        var workspaceJson = paths.workstreamDir().resolve("workspaces").resolve(workspaceId + ".json");
        if (!Files.isRegularFile(workspaceJson)) {
            return WorkspaceBase.unavailable();
        }
        var workspace = OBJECT_MAPPER.readTree(workspaceJson.toFile());
        return new WorkspaceBase(
                textOrNull(workspace.path("baseBranch").asText("")),
                textOrNull(workspace.path("baseCommit").asText("")),
                "workspace_metadata"
        );
    }

    private static boolean commitExists(Path workdir, String commit) throws IOException, InterruptedException {
        return git(workdir, "cat-file", "-e", commit + "^{commit}").exitCode() == 0;
    }

    private static List<String> parseNulPaths(String framedPaths) {
        if (framedPaths == null || framedPaths.isEmpty()) {
            return List.of();
        }
        var fields = framedPaths.split(String.valueOf('\0'), -1);
        if (fields.length < 2 || !fields[fields.length - 1].isEmpty()) {
            throw new IllegalArgumentException("git path output is not NUL terminated");
        }
        var paths = new ArrayList<String>(fields.length - 1);
        for (var index = 0; index < fields.length - 1; index++) {
            if (fields[index].isEmpty()) {
                throw new IllegalArgumentException("git path output contains an empty path");
            }
            paths.add(fields[index]);
        }
        return List.copyOf(paths);
    }

    private static List<String> hygieneWarnings(List<String> changedFiles) {
        var warnings = new ArrayList<String>();
        for (String file : changedFiles) {
            if (isLikelyGeneratedByproduct(file)) {
                warnings.add(file + " looks like a generated self-test byproduct; remove it unless it is an intentional deliverable.");
            }
        }
        return warnings;
    }

    private static boolean isLikelyGeneratedByproduct(String file) {
        return file.equals("__pycache__/")
                || file.startsWith("__pycache__/")
                || file.contains("/__pycache__/")
                || file.equals(".pytest_cache/")
                || file.startsWith(".pytest_cache/")
                || file.contains("/.pytest_cache/")
                || file.endsWith(".pyc")
                || file.endsWith(".pyo")
                || file.endsWith(".coverage")
                || file.endsWith(".tmp")
                || file.endsWith(".log")
                || file.equals(".DS_Store")
                || file.endsWith("/.DS_Store");
    }

    private static void write(Path path, String content) throws IOException {
        Files.writeString(path, content, StandardCharsets.UTF_8);
    }

    private static void writeEvidenceJson(Path path, GitEvidence evidence) throws IOException {
        var json = new LinkedHashMap<String, Object>();
        json.put("schemaVersion", evidence.schemaVersion());
        json.put("available", evidence.available());
        json.put("workdir", evidence.workdir());
        json.put("gitRoot", evidence.gitRoot());
        json.put("branch", evidence.branch());
        json.put("baseBranch", evidence.baseBranch());
        json.put("baseCommit", evidence.baseCommit());
        json.put("headCommit", evidence.headCommit());
        json.put("baseSource", evidence.baseSource());
        json.put("comparisonRange", evidence.comparisonRange());
        json.put("hasChanges", evidence.hasChanges());
        json.put("changedFileCount", evidence.changedFileCount());
        json.put("hygieneWarningCount", evidence.hygieneWarningCount());
        json.put("generatedAt", evidence.generatedAt());
        json.put("error", evidence.error());
        json.put("actualChanges", evidence.actualChanges());
        OBJECT_MAPPER.writeValue(path.toFile(), json);
    }

    private static ChangeScopeEvaluation evaluateChangeScope(
            GitEvidence evidence,
            TaskContract contract
    ) {
        if (!evidence.available()) {
            return ChangeScopeEvaluation.unavailable("Git evidence is unavailable");
        }
        if (evidence.comparisonRange() == null || evidence.comparisonRange().isBlank()) {
            return ChangeScopeEvaluation.unavailable("Workspace base commit is unavailable");
        }
        if (contract == null) {
            return ChangeScopeEvaluation.unavailable("TaskContract artifact is missing");
        }
        return ChangeScopeEvaluator.evaluate(contract, evidence.actualChanges());
    }

    private static QualifiedContract qualifiedContract(TaskContext context) {
        if (!AgentRunGovernanceContext.requiresApprovedTaskContract(context))
            return new QualifiedContract(null, TaskContractProjectionVerifier.Failure.of(
                    "CONTRACT_PHASE_MISSING", "change-scope validation requires an explicit EXECUTION phase"));
        var resolution = TaskContractProjectionVerifier.resolve(context.ledger(), context.workspaceRoot(), context.workstreamId(), TaskContractProjectionVerifier.requiredPhase(context.definition()));
        if (resolution.failure() != null) {
            return new QualifiedContract(null, resolution.failure());
        }
        return resolution.qualified()
                .map(value -> new QualifiedContract(value.contract(), null, value))
                .orElseGet(() -> new QualifiedContract(null, TaskContractProjectionVerifier.Failure.of(
                        "APPROVAL_BINDING_MISSING", "change-scope validation requires an approved task contract")));
    }

    private static NodeResult qualificationFailure(TaskContractProjectionVerifier.Failure failure) {
        return new NodeResult(
                TaskContractProjectionVerifier.FAILURE_OUTCOME,
                NodeStatus.FAILED,
                List.of(),
                Map.of(
                        "failure_code", TaskContractProjectionVerifier.FAILURE_OUTCOME,
                        "reason", failure.reason(),
                        "error", failure.message()),
                failure.message());
    }

    private static String toWorkspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static CommandResult git(Path workdir, String... args) throws IOException, InterruptedException {
        var command = new ArrayList<String>();
        command.add("git");
        command.addAll(List.of(args));
        var process = new ProcessBuilder(command)
                .directory(workdir.toFile())
                .redirectErrorStream(true)
                .start();
        var output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        var exitCode = process.waitFor();
        return new CommandResult(exitCode, output);
    }

    private record CommandResult(int exitCode, String output) {
    }

    private record QualifiedContract(TaskContract contract, TaskContractProjectionVerifier.Failure failure,
                                     TaskContractProjectionVerifier.QualifiedTaskContract reference) {
        QualifiedContract(TaskContract contract, TaskContractProjectionVerifier.Failure failure) {
            this(contract, failure, null);
        }
    }

    private static String textOrNull(String value) {
        return value == null || value.isBlank() ? null : value.trim();
    }

    private static String textOrEmpty(String value) {
        return value == null ? "" : value;
    }

    private record WorkspaceBase(String baseBranch, String baseCommit, String source) {
        static WorkspaceBase unavailable() {
            return new WorkspaceBase(null, null, "unavailable");
        }
    }

    private record GitEvidence(
            String schemaVersion,
            boolean available,
            String workdir,
            String gitRoot,
            String branch,
            String baseBranch,
            String baseCommit,
            String headCommit,
            String baseSource,
            String comparisonRange,
            boolean hasChanges,
            int changedFileCount,
            int hygieneWarningCount,
            String generatedAt,
            String error,
            List<ChangeScopeEvaluation.ActualChange> actualChanges
    ) {
        GitEvidence {
            actualChanges = List.copyOf(actualChanges == null ? List.of() : actualChanges);
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Map;
import com.fasterxml.jackson.core.type.TypeReference;

/** Runtime-owned provenance of required authored inputs; it never grants an approval. */
public final class AuthoredExecutionContext {
    static final ObjectMapper JSON = new ObjectMapper().registerModule(new JavaTimeModule());
    public static final String SECTION_NAME = "authored-context";
    private static final TypeReference<Map<String, Object>> MAP = new TypeReference<>() { };

    private AuthoredExecutionContext() { }

    public static void validateDefinition(dev.dual.core.workflow.WorkflowDefinition definition) {
        AuthoredStageLineageResolver.validateDefinition(definition);
    }

    public static Optional<Snapshot> prepare(TaskHandler.TaskContext context, String runId) throws IOException {
        if (!AuthoredStageLineageResolver.participates(context.definition().id())) return Optional.empty();
        var paths = new dev.dual.ledger.file.WorkstreamPaths(context.workspaceRoot(), new dev.dual.core.id.DualId(context.workstreamId()));
        return context.ledger().inspect(paths, (scoped, files) -> {
            try {
                var actual = scoped.loadNode(paths, context.instance().nodeInstanceId());
                var current = scoped.loadCurrent(paths);
                require(!current.status().isTerminal() && current.activeNodeInstanceIds().contains(actual.nodeInstanceId())
                        && java.util.Set.of(dev.dual.core.workflow.NodeStatus.READY, dev.dual.core.workflow.NodeStatus.RUNNING).contains(actual.status()),
                        "AUTHORED_NODE_NOT_CURRENT");
                var snapshot = new AuthoredStageLineageResolver(scoped, context.workspaceRoot(), context.workstreamId(), Long.MAX_VALUE)
                        .prepare(context.instance().nodeInstanceId(), runId);
                require(snapshot.nodeId().equals(context.definition().id())
                        && snapshot.nodeId().equals(context.instance().nodeDefinitionId()), "AUTHORED_CONTEXT_NODE_MISMATCH");
                verifyDirectInputs(context.workspaceRoot(), snapshot);
                return Optional.of(snapshot);
            } catch (IllegalArgumentException failure) {
                throw new IOException("AUTHORED_CONTEXT_INVALID", failure);
            }
        });
    }

    public static void verifyManifest(Path root, Path manifestPath, Snapshot expected) throws IOException {
        var ref = root.toAbsolutePath().normalize().relativize(manifestPath.toAbsolutePath().normalize()).toString();
        var path = manifestPath(root, expected.workstreamId(), expected.runId(), ref);
        var document = JSON.readValue(path.toFile(), MAP);
        var actual = snapshot(document);
        require(expected.equals(actual), "AUTHORED_MANIFEST_IDENTITY_MISMATCH");
        require(expected.workstreamId().equals(document.get("workstreamId"))
                && expected.runId().equals(document.get("runId")) && expected.nodeId().equals(document.get("nodeId")),
                "AUTHORED_MANIFEST_RUN_MISMATCH");
        var required = expected.render(root);
        var sections = document.get("sections");
        require(sections instanceof List<?>, "AUTHORED_MANIFEST_SECTIONS_MISSING");
        int count = 0;
        for (var value : (List<?>) sections) {
            if (!(value instanceof Map<?, ?> section) || !SECTION_NAME.equals(section.get("name"))) continue;
            count++;
            require(Boolean.TRUE.equals(section.get("required")) && expected.nodeInstanceId().equals(section.get("sourceRef"))
                    && TaskContractArtifactWriter.sha256(required.getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(section.get("sha256")),
                    "AUTHORED_REQUIRED_SECTION_MISMATCH");
        }
        require(count == 1, "AUTHORED_REQUIRED_SECTION_MISSING_OR_DUPLICATED");
        var promptPath = Path.of(String.valueOf(document.get("promptPath"))).toAbsolutePath().normalize();
        require(Files.isRegularFile(promptPath) && Files.isSameFile(promptPath.getParent(), path.getParent()), "AUTHORED_PROMPT_PATH_INVALID");
        var prompt = Files.readString(promptPath);
        require(prompt.contains(required), "AUTHORED_REQUIRED_CONTENT_MISSING");
    }

    static Reference validatePublication(dev.dual.ledger.file.WorkflowFileLedger ledger, Path root, String ws, String nodeInstanceId, String runId,
                                         AgentResultEnvelope.AgentResult result) throws IOException {
        var paths = new dev.dual.ledger.file.WorkstreamPaths(root, new dev.dual.core.id.DualId(ws));
        return ledger.inspect(paths, (scoped, files) -> validatePublicationSnapshot(scoped, root, ws, nodeInstanceId, runId, result));
    }

    private static Reference validatePublicationSnapshot(dev.dual.ledger.file.WorkflowFileLedger ledger, Path root, String ws,
            String nodeInstanceId, String runId, AgentResultEnvelope.AgentResult result) throws IOException {
        var loaded = runSnapshot(root, ws, nodeInstanceId, runId);
        var expected = new AuthoredStageLineageResolver(ledger, root, ws, Long.MAX_VALUE).prepare(nodeInstanceId, runId);
        // New unrelated ledger events do not change the input identity.
        expected = new Snapshot(expected.workstreamId(), expected.nodeInstanceId(), expected.nodeId(), expected.runId(),
                loaded.snapshot().historyThrough(), expected.contract(), expected.reviewedDesign(), expected.reviewedPlan(),
                expected.parent(), expected.subject(), expected.trigger(), expected.obligations());
        verifyManifest(root, verifiedPath(root, loaded.reference()), expected);
        verifyDirectInputs(root, expected);
        List<AgentResultEnvelope.AuthoredRevisionResponse> responses = switch (result) {
            case AgentResultEnvelope.DesignResult design -> design.revisionResponses();
            case AgentResultEnvelope.PlanResult plan -> plan.revisionResponses();
            default -> null;
        };
        if (result instanceof AgentResultEnvelope.DesignResult || result instanceof AgentResultEnvelope.PlanResult) {
            var errors = AuthoredRevisionValidator.validate(responses, expected.obligations().stream().map(Obligation::id).toList());
            require(errors.isEmpty(), String.join("; ", errors));
        }
        return loaded.reference();
    }

    private static Bound runSnapshot(Path root, String ws, String nodeId, String runId) throws IOException {
        var runPath = canonicalPath(root, ".agent/workstreams/" + ws + "/runs/" + runId + "/run.json");
        var run = JSON.readValue(runPath.toFile(), MAP);
        var declaredPath = String.valueOf(run.get("promptManifestPath"));
        var absolute = Path.of(declaredPath);
        var relative = absolute.isAbsolute() ? root.toAbsolutePath().normalize().relativize(absolute.normalize()).toString() : declaredPath;
        var path = manifestPath(root, ws, runId, relative);
        var snapshot = snapshot(JSON.readValue(path.toFile(), MAP));
        require(snapshot.workstreamId().equals(ws) && snapshot.nodeInstanceId().equals(nodeId)
                && snapshot.runId().equals(runId), "AUTHORED_RUN_SNAPSHOT_MISMATCH");
        return new Bound(reference(root, relative), snapshot);
    }

    private static Snapshot snapshot(Map<String, Object> document) throws IOException {
        require(document.get("authoredContext") instanceof Map<?, ?>, "AUTHORED_MANIFEST_CONTEXT_MISSING");
        try { return JSON.convertValue(document.get("authoredContext"), Snapshot.class); }
        catch (IllegalArgumentException failure) { throw new IOException("AUTHORED_MANIFEST_CONTEXT_INVALID", failure); }
    }

    private static Path manifestPath(Path root, String ws, String run, String ref) throws IOException {
        var path = canonicalPath(root, ref);
        var directory = root.toAbsolutePath().normalize().resolve(".agent/workstreams/" + ws + "/runs/" + run + "/prompts");
        require(directory.equals(path.getParent()), "AUTHORED_MANIFEST_OUTSIDE_RUN");
        return path;
    }

    private static void verifyDirectInputs(Path root, Snapshot snapshot) throws IOException {
        var candidates = new java.util.ArrayList<Candidate>();
        if (snapshot.reviewedDesign() != null) candidates.add(snapshot.reviewedDesign().candidate());
        if (snapshot.reviewedPlan() != null) candidates.add(snapshot.reviewedPlan().candidate());
        if (snapshot.parent() != null) candidates.add(snapshot.parent());
        if (snapshot.subject() != null) candidates.add(snapshot.subject());
        for (var candidate : candidates) {
            var bound = verifiedCandidateSnapshot(root, snapshot.workstreamId(), candidate);
            require(sameAuthorization(root, bound.contract(), snapshot.contract()), "AUTHORED_CONTRACT_EPOCH_MISMATCH");
            if (candidate.artifactType().equals("plan_result"))
                require(Objects.equals(bound.reviewedDesign(), snapshot.reviewedDesign()), "AUTHORED_PLAN_DESIGN_MISMATCH");
        }
    }

    /** Design/plan are authored under GOAL; execution must bind that exact goal, not impersonate its approval. */
    private static boolean sameAuthorization(Path root, ContractIdentity authored, ContractIdentity consumer) throws IOException {
        if (Objects.equals(authored, consumer)) return true;
        if (authored == null || consumer == null) return false;
        var goal = TaskContractArtifactWriter.mapper().readValue(verifiedPath(root, authored.contract()).toFile(),
                dev.dual.core.contract.TaskContract.class);
        var execution = TaskContractArtifactWriter.mapper().readValue(verifiedPath(root, consumer.contract()).toFile(),
                dev.dual.core.contract.TaskContract.class);
        return goal.phase() == dev.dual.core.contract.TaskContract.Phase.GOAL
                && execution.phase() == dev.dual.core.contract.TaskContract.Phase.EXECUTION
                && goal.epoch() == execution.epoch()
                && new dev.dual.core.contract.TaskContract.Reference(authored.contract().ref(), authored.contract().sha256())
                    .equals(execution.goalContract())
                && Objects.equals(goal.source(), execution.source());
    }

    static Snapshot verifiedCandidateSnapshot(Path root, String ws, Candidate candidate) throws IOException {
        var doc = JSON.readValue(verifiedPath(root, candidate.sidecar()).toFile(), MAP);
        require(doc.get("authored_context") instanceof Map<?, ?>, "AUTHORED_CANDIDATE_INPUT_BINDING_MISSING");
        final Reference ref;
        try { ref = JSON.convertValue(doc.get("authored_context"), Reference.class); }
        catch (IllegalArgumentException failure) { throw new IOException("AUTHORED_CANDIDATE_INPUT_BINDING_INVALID", failure); }
        // Publication already verified the prompt. Consumers follow its sealed binding,
        // not the historical run locator or a recursive replay of ancestor prompts.
        var path = manifestPath(root, ws, candidate.runId(), ref.ref());
        verifiedPath(root, ref);
        var manifest = JSON.readValue(path.toFile(), MAP);
        var bound = snapshot(manifest);
        require(ws.equals(bound.workstreamId()) && candidate.nodeInstanceId().equals(bound.nodeInstanceId())
                && candidate.runId().equals(bound.runId()) && candidate.nodeId().equals(bound.nodeId())
                && ws.equals(manifest.get("workstreamId")) && candidate.runId().equals(manifest.get("runId"))
                && candidate.nodeId().equals(manifest.get("nodeId")), "AUTHORED_INPUT_BINDING_MISMATCH");
        return bound;
    }

    private static void require(boolean value, String message) throws IOException {
        AuthoredStageLineageResolver.require(value, message);
    }
    private record Bound(Reference reference, Snapshot snapshot) { }

    public record Reference(String ref, String sha256) {
        public Reference {
            Objects.requireNonNull(ref);
            if (sha256 == null || !sha256.matches("[0-9a-f]{64}")) throw new IllegalArgumentException("invalid authored SHA");
        }
    }

    public record ContractIdentity(String compileNodeInstanceId, String approvalGateRef, String approvalEventId,
                                   Reference contract, Reference resolution) { }

    public record Candidate(Reference sidecar, String nodeInstanceId, String nodeId, String runId, String artifactType) { }

    public record ReviewedCandidate(Reference decision, String eventId, Candidate candidate) { }

    public record Obligation(String id, Reference source, String text) { }

    public record Snapshot(String workstreamId, String nodeInstanceId, String nodeId, String runId,
                           long historyThrough, ContractIdentity contract, ReviewedCandidate reviewedDesign,
                           ReviewedCandidate reviewedPlan, Candidate parent, Candidate subject, Reference trigger,
                           List<Obligation> obligations) {
        public Snapshot { obligations = List.copyOf(obligations); }

        Snapshot withHistoryThrough(long through) {
            return new Snapshot(workstreamId, nodeInstanceId, nodeId, runId, through, contract,
                    reviewedDesign, reviewedPlan, parent, subject, trigger, obligations);
        }

        public String render(Path root) throws IOException {
            var text = new StringBuilder("# Required Authored Context\n\n");
            text.append("The following verified inputs are mandatory. Respond to every active obligation; ")
                    .append("ADDRESSED does not close it. Use NOT_ADDRESSED honestly. Initial authors return [].\n\n");
            append(text, root, "Reviewed design", reviewedDesign == null ? null : reviewedDesign.candidate());
            append(text, root, "Reviewed plan", reviewedPlan == null ? null : reviewedPlan.candidate());
            append(text, root, "Revision parent", parent);
            append(text, root, "Review candidate", subject);
            text.append("## Active obligations\n\n")
                    .append(JSON.writerWithDefaultPrettyPrinter().writeValueAsString(obligations)).append('\n');
            return text.toString();
        }

        private static void append(StringBuilder text, Path root, String title, Candidate candidate) throws IOException {
            if (candidate == null) return;
            var path = verifiedPath(root, candidate.sidecar());
            text.append("## ").append(title).append("\n\n")
                    .append(candidate.sidecar().ref()).append("\n\n")
                    .append(Files.readString(path)).append("\n\n");
        }
    }

    static Path verifiedPath(Path root, Reference reference) throws IOException {
        var path = canonicalPath(root, reference.ref());
        if (!TaskContractArtifactWriter.sha256(Files.readAllBytes(path)).equals(reference.sha256()))
            throw new IOException("AUTHORED_SOURCE_HASH_MISMATCH: " + reference.ref());
        return path;
    }

    static Path canonicalPath(Path root, String ref) throws IOException {
        var base = root.toAbsolutePath().normalize();
        if (ref == null || ref.isBlank() || ref.indexOf('\\') >= 0 || Path.of(ref).isAbsolute())
            throw new IOException("AUTHORED_REF_INVALID");
        var path = base.resolve(ref).normalize();
        if (!path.startsWith(base) || !base.relativize(path).toString().equals(ref)
                || !Files.isRegularFile(path) || !path.toRealPath().equals(base.toRealPath().resolve(ref)))
            throw new IOException("AUTHORED_REF_INVALID: " + ref);
        return path;
    }

    static Reference reference(Path root, String ref) throws IOException {
        return new Reference(ref, TaskContractArtifactWriter.sha256(Files.readAllBytes(canonicalPath(root, ref))));
    }
}

package dev.dual.runtime.handler;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

/** Checks response shape and exact coverage, never whether the claimed repair is correct. */
final class AuthoredRevisionValidator {
    private AuthoredRevisionValidator() { }

    static List<String> shapeErrors(List<AgentResultEnvelope.AuthoredRevisionResponse> responses) {
        var errors = new ArrayList<String>();
        if (responses == null) {
            return List.of("AUTHORED_RESPONSES_MISSING: result.revision_responses must be explicit");
        }
        var ids = new HashSet<String>();
        for (int index = 0; index < responses.size(); index++) {
            var response = responses.get(index);
            if (response == null || !validId(response.obligationId())) {
                errors.add(invalidIdMessage(index, response == null ? null : response.obligationId()));
                continue;
            }
            if (!ids.add(response.obligationId())) errors.add("AUTHORED_RESPONSE_DUPLICATE");
            if (response.disposition() == null) errors.add("AUTHORED_RESPONSE_DISPOSITION_MISSING");
            if (response.evidence() == null || response.evidence().isBlank()) errors.add("AUTHORED_RESPONSE_EVIDENCE_MISSING");
        }
        return List.copyOf(errors);
    }

    static String invalidIdMessage(int index, String id) {
        return "AUTHORED_RESPONSE_ID_INVALID: index=" + index + ", length=" + (id == null ? "missing" : id.length())
                + ", expected sha256:<64 lowercase hex>#must_fix:<index> or #human-note:0";
    }

    private static boolean validId(String id) {
        return id != null && id.matches("sha256:[0-9a-f]{64}#(?:must_fix:[0-9]+|human-note:0)");
    }

    static List<Integer> repairableReferenceIndexes(List<AgentResultEnvelope.AuthoredRevisionResponse> responses,
                                                    List<String> activeIds) {
        if (responses == null || responses.isEmpty() || activeIds == null || responses.size() != activeIds.size()
                || activeIds.stream().anyMatch(id -> !validId(id))
                || new HashSet<>(activeIds).size() != activeIds.size()) return List.of();
        var seen = new HashSet<String>();
        var indexes = new ArrayList<Integer>();
        for (int index = 0; index < responses.size(); index++) {
            var response = responses.get(index);
            if (response == null || response.obligationId() == null || response.obligationId().isBlank()
                    || response.disposition() == null || response.evidence() == null || response.evidence().isBlank()
                    || !seen.add(response.obligationId())) return List.of();
            if (!validId(response.obligationId())) indexes.add(index);
            else if (!activeIds.contains(response.obligationId())) return List.of();
        }
        return List.copyOf(indexes);
    }

    static List<String> validate(List<AgentResultEnvelope.AuthoredRevisionResponse> responses, List<String> activeIds) {
        var errors = new ArrayList<>(shapeErrors(responses));
        if (!errors.isEmpty()) return List.copyOf(errors);
        var actual = new HashSet<String>();
        responses.forEach(response -> actual.add(response.obligationId()));
        if (!actual.equals(new HashSet<>(activeIds))) errors.add("AUTHORED_RESPONSE_COVERAGE_MISMATCH");
        return List.copyOf(errors);
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.ledger.file.GateDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkflowIterationDocument;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import static dev.dual.runtime.handler.AuthoredExecutionContext.*;

/** Resolves the two registered authored stages from declared edges and routed occurrences. */
final class AuthoredStageLineageResolver {
    enum Stage {
        DESIGN("design.claude_design", "design.codex_arch_review", "design.decision", "design_result", "design", "READY_FOR_ARCH_REVIEW"),
        PLAN("plan.claude_plan", "plan.codex_plan_review", "plan.decision", "plan_result", "plan", "READY_TO_IMPLEMENT");

        final String author, reviewer, decision, artifact, purpose, ready;
        Stage(String author, String reviewer, String decision, String artifact, String purpose, String ready) {
            this.author = author; this.reviewer = reviewer; this.decision = decision;
            this.artifact = artifact; this.purpose = purpose; this.ready = ready;
        }
    }

    private static final TypeReference<Map<String, Object>> MAP = new TypeReference<>() { };
    private final Path root;
    private final String ws;
    private final String prefix;
    private final WorkstreamPaths paths;
    private final WorkflowFileLedger ledger;
    private final WorkflowDefinition definition;
    private final List<Event> events;
    private final long through;

    AuthoredStageLineageResolver(WorkflowFileLedger ledger, Path root, String ws, long through) throws IOException {
        this.ledger = java.util.Objects.requireNonNull(ledger);
        this.root = root.toAbsolutePath().normalize(); this.ws = ws;
        this.prefix = ".agent/workstreams/" + ws + "/";
        this.paths = new WorkstreamPaths(root, new DualId(ws));
        this.definition = ledger.loadDefinition(paths);
        var history = new ArrayList<Event>();
        long previous = -1;
        for (var line : Files.readAllLines(paths.eventsJsonl())) {
            if (line.isBlank()) continue;
            var event = JSON.readValue(line, MAP);
            var id = text(event.get("event_id"));
            if (!id.matches("evt-[0-9]{6,}")) {
                require(!"node_routed".equals(text(event.get("event_type"))), "AUTHORED_EVENT_ID_INVALID");
                continue;
            }
            long sequence;
            try { sequence = Long.parseLong(id.substring(4)); }
            catch (NumberFormatException failure) { throw new IOException("AUTHORED_EVENT_ID_INVALID", failure); }
            require(sequence > previous, "AUTHORED_EVENT_ORDER_INVALID");
            previous = sequence;
            if ("node_routed".equals(text(event.get("event_type")))) {
                var payload = map(event.get("payload"));
                var target = definition.node(text(payload.get("to")));
                var occurrence = ledger.loadNode(paths, text(payload.get("node_instance_id")));
                require(target.id().equals(occurrence.nodeDefinitionId()), "AUTHORED_ROUTE_TARGET_MISMATCH");
            }
            if (sequence <= through) history.add(new Event(sequence, id, text(event.get("event_type")), map(event.get("payload"))));
        }
        this.events = List.copyOf(history);
        this.through = history.isEmpty() ? 0 : history.getLast().sequence();
    }

    static boolean participates(String nodeId) {
        return nodeId.equals(Stage.DESIGN.author) || nodeId.equals(Stage.DESIGN.reviewer)
                || nodeId.equals(Stage.PLAN.author) || nodeId.equals(Stage.PLAN.reviewer)
                || Set.of("implement.claude_implement", "implement.claude_self_test_report").contains(nodeId);
    }

    static void validateDefinition(WorkflowDefinition definition) {
        if (definition.nodes().stream().noneMatch(node -> participates(node.id()))) return;
        for (var stage : Stage.values()) {
            var author = definition.node(stage.author);
            definitionRequire(author.kind() == NodeKind.TASK && author.handlerType().equals("acpx.agent_run"), "author role mismatch");
            var gates = definition.nodes().stream().filter(node -> stage.purpose.equals(text(node.config().get("gate_purpose")))).toList();
            definitionRequire(gates.size() == 1, "one " + stage.purpose + " gate is required");
            var gate = gates.getFirst();
            definitionRequire(gate.kind() == NodeKind.GATE && gate.handlerType().equals("human.review"), "gate role mismatch");
            var incoming = definition.edges().stream().filter(edge -> edge.to().equals(gate.id())).toList();
            definitionRequire(!incoming.isEmpty(), "gate must have a candidate source");
            var next = soleSuccessor(definition, author.id(), "completed");
            var context = definition.node(next);
            definitionRequire(context.handlerType().equals("context.build_package") && context.kind() == NodeKind.TASK
                    && stage.reviewer.equals(text(context.config().get("target_node"))), "review context role mismatch");
            definitionRequire(soleSuccessor(definition, next, "completed").equals(stage.reviewer), "review context successor mismatch");
            var reviewer = definition.node(stage.reviewer);
            definitionRequire(reviewer.kind() == NodeKind.TASK && reviewer.handlerType().equals("acpx.agent_run"), "reviewer role mismatch");
            definitionRequire(soleSuccessor(definition, stage.reviewer, "completed").equals(stage.decision), "review decision successor mismatch");
            var decision = definition.node(stage.decision);
            definitionRequire(decision.kind() == NodeKind.DECISION && decision.handlerType().equals("review.decision"), "decision role mismatch");
            definitionRequire(incoming.stream().allMatch(edge -> edge.from().equals(stage.decision)
                    && (edge.on().equals("BLOCKED") || stage == Stage.PLAN
                    && edge.on().equals(VerificationReadiness.REQUIRED))), "ordinary review must not create a human gate");
            if (stage == Stage.PLAN)
                definitionRequire(soleSuccessor(definition, stage.decision, VerificationReadiness.REQUIRED).equals(gate.id()),
                        "missing verification readiness must reach the plan gate");
            definitionRequire(definition.edges().stream().filter(edge -> edge.to().equals(next))
                    .allMatch(edge -> edge.from().equals(stage.author) && edge.on().equals("completed")), "review context has an unrelated producer");
            definitionRequire(definition.edges().stream().filter(edge -> edge.to().equals(stage.reviewer))
                    .allMatch(edge -> edge.from().equals(next) && edge.on().equals("completed")), "reviewer bypasses its context");
            definitionRequire(definition.edges().stream().filter(edge -> edge.to().equals(stage.decision))
                    .allMatch(edge -> edge.from().equals(stage.reviewer) && edge.on().equals("completed")), "decision bypasses its reviewer");
            definitionRequire(soleSuccessor(definition, stage.decision, "NEEDS_REVISION").equals(stage.author), "revision must return to author");
            definitionRequire(soleSuccessor(definition, stage.decision, stage.ready)
                    .equals(stage == Stage.DESIGN ? Stage.PLAN.author : "contract.compile_execution"), "READY must use the reviewed candidate");
            definitionRequire(soleSuccessor(definition, gate.id(), "revise").equals(stage.author)
                    && soleSuccessor(definition, gate.id(), "approved").equals(stage.author), "human resolution must receive fresh independent review");
        }
    }

    private static String soleSuccessor(WorkflowDefinition definition, String source, String outcome) {
        var edges = definition.edgesFrom(source).stream().filter(edge -> edge.on().equals(outcome)).toList();
        definitionRequire(edges.size() == 1, "exactly one " + outcome + " edge required for " + source);
        return edges.getFirst().to();
    }

    private static void definitionRequire(boolean valid, String message) {
        if (!valid) throw new IllegalArgumentException("AUTHORED_DEFINITION_INVALID: " + message);
    }

    Snapshot prepare(String nodeInstanceId, String runId) throws IOException {
        var node = node(nodeInstanceId);
        require(participates(node.nodeDefinitionId()), "AUTHORED_ROLE_UNSUPPORTED");
        var contractResolution = TaskContractProjectionVerifier.resolve(ledger, root, ws,
                TaskContractProjectionVerifier.requiredPhase(definition.node(node.nodeDefinitionId())));
        require(contractResolution.failure() == null && contractResolution.qualified().isPresent(), "AUTHORED_CONTRACT_NOT_QUALIFIED");
        var qualified = contractResolution.qualified().orElseThrow();
        var contract = new ContractIdentity(qualified.compileNodeInstanceId(), qualified.approvalGateRef(), qualified.approvalEventId(),
                new Reference(qualified.contractRef(), qualified.sha256()), new Reference(qualified.resolutionRef(), qualified.resolutionSha256()));
        require(events.stream().anyMatch(event -> event.id().equals(contract.approvalEventId())), "AUTHORED_CONTRACT_OUTSIDE_HISTORY");
        ReviewedCandidate design = null, plan = null;
        Candidate parent = null, subject = null;
        Reference trigger = null;
        List<Obligation> obligations = List.of();
        var id = node.nodeDefinitionId();
        if (!id.equals(Stage.DESIGN.author) && !id.equals(Stage.DESIGN.reviewer)) design = reviewed(Stage.DESIGN, node);
        if (id.equals("implement.claude_implement") || id.equals("implement.claude_self_test_report")) plan = reviewed(Stage.PLAN, node);
        for (var stage : Stage.values()) {
            if (id.equals(stage.author)) {
                var baseline = baseline(stage, node, new HashSet<>());
                parent = baseline.parent(); trigger = baseline.trigger(); obligations = baseline.obligations();
            } else if (id.equals(stage.reviewer)) {
                subject = reviewSubject(stage, node);
                obligations = baseline(stage, node(subject.nodeInstanceId()), new HashSet<>()).obligations();
            }
        }
        var snapshot = new Snapshot(ws, nodeInstanceId, id, runId, through, contract, design, plan, parent, subject, trigger, obligations);
        var origins = events.stream().filter(event -> event.type().equals("node_routed")
                && nodeInstanceId.equals(text(event.payload().get("node_instance_id")))).toList();
        require(origins.size() == 1, "AUTHORED_NODE_ORIGIN_NOT_UNIQUE");
        if (!origins.isEmpty() && origins.getFirst().sequence() < through) {
            // Node creation, not execution retry, fixes the semantic input epoch.
            var original = new AuthoredStageLineageResolver(ledger, root, ws, origins.getFirst().sequence()).prepare(nodeInstanceId, runId);
            require(snapshot.withHistoryThrough(original.historyThrough()).equals(original), "AUTHORED_NODE_AUTHORITY_CHANGED");
            return original;
        }
        return snapshot;
    }

    ReviewedCandidate reviewed(Stage stage, NodeInstanceDocument consumer) throws IOException {
        var cursor = consumer;
        var visited = new HashSet<String>();
        while (visited.add(cursor.nodeInstanceId())) {
            if (cursor.nodeDefinitionId().equals(stage.decision)) {
                completed(cursor);
                require(stage.ready.equals(text(cursor.result().get("decision"))), "AUTHORED_REVIEW_NOT_READY");
                var facts = reviewedFacts(stage, cursor);
                // Compare the persisted JSON representation: an epoch read into a generic map may
                // be Integer even though TaskContract exposes long. Do not confuse that with drift.
                require(JSON.readTree(JSON.writeValueAsBytes(facts)).equals(JSON.valueToTree(cursor.result().get("reviewed_candidate"))),
                        "AUTHORED_REVIEWED_FACTS_MISMATCH");
                var author = JSON.convertValue(facts.get("author_artifact"), Reference.class);
                var doc = AgentOutputContractDocument.read(verifiedPath(root, author), JSON).orElseThrow();
                var candidate = new Candidate(author, doc.nodeInstanceId(), doc.nodeId(), doc.runId(), doc.sourceArtifactType());
                var event = events.stream().filter(e -> e.type().equals("node_routed")
                        && cursorId(facts).equals(text(e.payload().get("source_node_instance_id")))
                        && stage.ready.equals(text(e.payload().get("outcome")))).toList();
                require(event.size() == 1, "AUTHORED_READY_ROUTE_NOT_UNIQUE");
                return new ReviewedCandidate(reference(root, prefix + "nodes/" + cursor.nodeInstanceId() + ".json"),
                        event.getFirst().id(), candidate);
            }
            var source = text(cursor.inputTransition().get("source_node_instance_id"));
            require(!source.isBlank(), "AUTHORED_REVIEWED_MISSING: " + stage.purpose);
            var parent = node(source);
            var cursorInstanceId = cursor.nodeInstanceId();
            var origins = events.stream().filter(event -> event.type().equals("node_routed")
                    && cursorInstanceId.equals(text(event.payload().get("node_instance_id")))).toList();
            require(origins.size() == 1 && source.equals(text(origins.getFirst().payload().get("source_node_instance_id"))),
                    "AUTHORED_NODE_ORIGIN_NOT_UNIQUE");
            var route = origins.getFirst();
            require(parent.nodeDefinitionId().equals(text(route.payload().get("from")))
                    && cursor.nodeDefinitionId().equals(text(route.payload().get("to"))), "AUTHORED_ROUTE_TARGET_MISMATCH");
            if (Boolean.TRUE.equals(cursor.inputTransition().get("readiness_repair"))) {
                // An explicitly recorded repair consumes the failed node's inputs, not its unsuccessful outputs.
                var repair = JSON.valueToTree(parent.result().get("readiness_repair"));
                var refs = new java.util.LinkedHashSet<>(parent.inputRefs());
                refs.addAll(strings(parent.result().get("readiness_repair") instanceof Map<?, ?> fact ? fact.get("evidence_refs") : null));
                require(parent.status() == NodeStatus.FAILED && cursor.nodeDefinitionId().equals(Stage.PLAN.author)
                        && "revise_readiness".equals(text(route.payload().get("outcome")))
                        && repair.path("action").asText().equals("revise_readiness") && !repair.path("note").asText().isBlank()
                        && repair.equals(JSON.valueToTree(route.payload().get("repair")))
                        && cursor.inputRefs().equals(List.copyOf(refs)), "AUTHORED_REPAIR_ROUTE_MISMATCH");
            } else {
                completed(parent);
                require(cursor.inputRefs().equals(parent.outputRefs()), "AUTHORED_ROUTE_INPUT_MISMATCH");
                edge(parent.nodeDefinitionId(), text(route.payload().get("outcome")), cursor.nodeDefinitionId());
            }
            require(reference(root, prefix + "nodes/" + source + ".json").sha256()
                    .equals(text(cursor.inputTransition().get("source_node_sha256"))), "AUTHORED_ROUTE_SOURCE_CHANGED");
            cursor = parent;
        }
        throw new IOException("AUTHORED_ROUTE_CYCLE");
    }

    private static String cursorId(Map<String, Object> facts) { return text(facts.get("decision_occurrence")); }

    Map<String, Object> reviewedFacts(Stage stage, String decisionId) throws IOException {
        return reviewedFacts(stage, node(decisionId));
    }

    Map<String, Object> reviewedFacts(Stage stage, NodeInstanceDocument decision) throws IOException {
        require(decision.nodeDefinitionId().equals(stage.decision), "AUTHORED_DECISION_ROLE_MISMATCH");
        var reviewer = unique(decision.inputRefs(), stage.reviewer, "agent_output_contract");
        require(stage.ready.equals(document(reviewer).decision()), "AUTHORED_REVIEW_NOT_READY");
        var reviewerNode = node(reviewer.nodeInstanceId());
        require(reviewerNode.nodeInstanceId().equals(text(decision.inputTransition().get("source_node_instance_id")))
                && reference(root, prefix + "nodes/" + reviewer.nodeInstanceId() + ".json").sha256()
                    .equals(text(decision.inputTransition().get("source_node_sha256"))), "AUTHORED_REVIEW_ROUTE_MISMATCH");
        var author = reviewSubject(stage, reviewerNode);
        var reviewedInput = verifiedCandidateSnapshot(root, ws, reviewer);
        require(author.equals(reviewedInput.subject()), "AUTHORED_REVIEW_SUBJECT_MISMATCH");
        var authorInput = verifiedCandidateSnapshot(root, ws, author);
        require(authorInput.contract().equals(reviewedInput.contract()), "AUTHORED_REVIEW_CONTRACT_MISMATCH");
        var contractRef = authorInput.contract().contract();
        var contract = TaskContractArtifactWriter.mapper().readValue(verifiedPath(root, contractRef).toFile(),
                dev.dual.core.contract.TaskContract.class);
        var result = new LinkedHashMap<String, Object>();
        result.put("schema_version", 1);
        result.put("stage", stage.purpose);
        result.put("author_occurrence", author.nodeInstanceId());
        result.put("reviewer_occurrence", reviewer.nodeInstanceId());
        result.put("decision_occurrence", decision.nodeInstanceId());
        result.put("author_artifact", author.sidecar());
        result.put("review_artifact", reviewer.sidecar());
        result.put("review_decision", stage.ready);
        result.put("contract", Map.of("phase", contract.phase().name(), "epoch", contract.epoch(),
                "ref", contractRef.ref(), "sha256", contractRef.sha256()));
        result.put("checks", List.of(Map.of("rule_id", "review.subject.and.route", "rule_version", "2", "result", "PASSED",
                "input_refs", List.of(author.sidecar(), reviewer.sidecar()))));
        return Map.copyOf(result);
    }

    private boolean routedAfter(Event origin, NodeInstanceDocument source, String outcome) throws IOException {
        for (var event : events) {
            if (event.sequence() <= origin.sequence() || !event.type().equals("node_routed")) continue;
            // A later occurrence of the same gate cannot supply this occurrence's completion.
            if (source.nodeDefinitionId().equals(text(event.payload().get("to")))) return false;
            if (!source.nodeDefinitionId().equals(text(event.payload().get("from")))
                    || !outcome.equals(text(event.payload().get("outcome")))) continue;
            var successor = node(text(event.payload().get("node_instance_id")));
            require(successor.nodeDefinitionId().equals(text(event.payload().get("to")))
                    && successor.iterationId().equals(source.iterationId())
                    && successor.inputRefs().equals(source.outputRefs()), "AUTHORED_APPROVAL_SUCCESSOR_MISMATCH");
            edge(source.nodeDefinitionId(), outcome, successor.nodeDefinitionId());
            return true;
        }
        return false;
    }

    private Gate gate(Event event) throws IOException {
        var payload = event.payload();
        var node = node(text(payload.get("node_instance_id")));
        require(node.kind() == NodeKind.GATE && node.nodeDefinitionId().equals(text(payload.get("to"))), "AUTHORED_GATE_NODE_MISMATCH");
        var ref = reference(root, prefix + "gates/" + text(payload.get("gate_id")) + ".json");
        var gate = JSON.readValue(verifiedPath(root, ref).toFile(), GateDocument.class);
        require(gate.gateId().equals(text(payload.get("gate_id")))
                && gate.nodeInstanceId().equals(node.nodeInstanceId()), "AUTHORED_GATE_INSTANCE_MISMATCH");
        require(strings(gate.result().get("subject_input_refs")).equals(node.inputRefs()), "AUTHORED_GATE_SUBJECT_MISMATCH");
        var source = text(payload.get("source_node_instance_id"));
        require(!source.isBlank() && source.equals(text(gate.result().get("source_node_instance_id")))
                && source.equals(text(node.result().get("source_node_instance_id"))), "AUTHORED_GATE_SOURCE_MISMATCH");
        require(text(gate.result().get("human_action")).equals(text(node.result().get("human_action")))
                && text(gate.result().get("note")).equals(text(node.result().get("note"))), "AUTHORED_GATE_ACTION_MISMATCH");
        var producer = node(source);
        completed(producer);
        require(producer.nodeDefinitionId().equals(text(payload.get("from"))), "AUTHORED_GATE_EVENT_SOURCE_MISMATCH");
        require(producer.iterationId().equals(node.iterationId()), "AUTHORED_GATE_ITERATION_MISMATCH");
        edge(producer.nodeDefinitionId(), text(payload.get("outcome")), node.nodeDefinitionId());
        return new Gate(node, gate, ref, producer);
    }

    private Candidate gateSubject(Stage stage, Gate gate) throws IOException {
        if (gate.source().nodeDefinitionId().equals(stage.author)) {
            require(stage == Stage.PLAN, "AUTHORED_DIRECT_DESIGN_GATE_UNSUPPORTED");
            return candidate(stage, gate.node().inputRefs(), gate.source());
        }
        require(gate.source().nodeDefinitionId().equals(stage.decision), "AUTHORED_GATE_SOURCE_ROLE_INVALID");
        var review = unique(gate.node().inputRefs(), stage.reviewer, "agent_output_contract");
        require(gate.source().inputRefs().contains(review.sidecar().ref()), "AUTHORED_DECISION_INPUT_MISMATCH");
        var reviewer = node(review.nodeInstanceId());
        require(reviewer.iterationId().equals(gate.source().iterationId()), "AUTHORED_REVIEW_ITERATION_MISMATCH");
        var doc = document(review);
        require(doc.decision().equals(text(gate.source().result().get("decision"))), "AUTHORED_DECISION_MISMATCH");
        edge(stage.reviewer, "completed", stage.decision);
        var subject = reviewSubject(stage, reviewer);
        var inputs = verifiedCandidateSnapshot(root, ws, review);
        require(subject.equals(inputs.subject()), "AUTHORED_REVIEW_INPUT_MISMATCH");
        return subject;
    }

    GateView gateView(String nodeInstanceId) throws IOException {
        var event = gateEvent(nodeInstanceId);
        var gate = gate(event);
        Stage stage = null;
        var purpose = text(definition.node(gate.node().nodeDefinitionId()).config().get("gate_purpose"));
        for (var value : Stage.values()) if (value.purpose.equals(purpose)) stage = value;
        require(stage != null, "AUTHORED_GATE_ROLE_UNSUPPORTED");
        var candidate = gateSubject(stage, gate);
        var inputs = verifiedCandidateSnapshot(root, ws, candidate);
        var latest = gate.source().nodeDefinitionId().equals(stage.author) ? candidate
                : unique(gate.node().inputRefs(), stage.reviewer, "agent_output_contract");
        var candidateDocument = JSON.readValue(verifiedPath(root, candidate.sidecar()).toFile(), MAP);
        var projection = new LinkedHashMap<String, Object>();
        projection.put("candidate", candidate);
        projection.put("contract", inputs.contract());
        projection.put("reviewedDesign", inputs.reviewedDesign());
        projection.put("activeObligations", inputs.obligations());
        projection.put("revisionResponses", candidateDocument.get("revision_responses"));
        projection.put("plannedFiles", candidateDocument.get("design"));
        projection.put("plan", candidateDocument.get("plan_artifact"));
        projection.put("newMustFix", latest.equals(candidate) ? List.of() : document(latest).mustFix());
        return new GateView(java.util.Collections.unmodifiableMap(projection), document(latest), latest.sidecar().ref());
    }

    record GateView(Map<String, Object> projection, AgentOutputContractDocument decision, String sidecarRef) { }

    String contextBody(TaskHandler.TaskContext context) throws IOException {
        var target = text(context.definition().config().get("target_node"));
        for (var stage : Stage.values()) {
            if (!target.equals(stage.reviewer)) continue;
            var subject = unique(context.instance().inputRefs(), stage.author, stage.artifact);
            var inputs = verifiedCandidateSnapshot(root, ws, subject);
            var body = new StringBuilder(inputs.render(root));
            body.append("\n## Current review candidate\n\n").append(subject.sidecar().ref()).append("\n\n")
                    .append(Files.readString(verifiedPath(root, subject.sidecar())));
            return body.toString();
        }
        if (target.equals("implement.claude_implement")) {
            var approved = reviewed(Stage.PLAN, node(context.instance().nodeInstanceId()));
            var inputs = verifiedCandidateSnapshot(root, ws, approved.candidate());
            return inputs.render(root) + "\n## Reviewed implementation plan\n\n"
                    + Files.readString(verifiedPath(root, approved.candidate().sidecar()));
        }
        return "";
    }

    private Candidate reviewSubject(Stage stage, NodeInstanceDocument reviewer) throws IOException {
        var matches = new LinkedHashMap<String, NodeInstanceDocument>();
        for (var event : events) {
            if (!event.type().equals("node_routed")) continue;
            var publisher = node(text(event.payload().get("node_instance_id")));
            if (!publisher.handlerType().equals("context.build_package")) continue;
            var config = definition.node(publisher.nodeDefinitionId()).config();
            if (!stage.reviewer.equals(text(config.get("target_node")))) continue;
            if (publisher.outputRefs().stream().noneMatch(reviewer.inputRefs()::contains)) continue;
            completed(publisher);
            require(publisher.iterationId().equals(reviewer.iterationId()), "AUTHORED_CONTEXT_ITERATION_MISMATCH");
            edge(publisher.nodeDefinitionId(), "completed", stage.reviewer);
            edge(stage.author, "completed", publisher.nodeDefinitionId());
            matches.put(publisher.nodeInstanceId(), publisher);
        }
        require(matches.size() == 1, "AUTHORED_CONTEXT_PUBLISHER_NOT_UNIQUE");
        var publisher = matches.values().iterator().next();
        var candidate = unique(publisher.inputRefs(), stage.author, stage.artifact);
        require(node(candidate.nodeInstanceId()).iterationId().equals(publisher.iterationId()), "AUTHORED_CANDIDATE_ITERATION_MISMATCH");
        return candidate;
    }

    private Baseline baseline(Stage stage, NodeInstanceDocument author, Set<String> visiting) throws IOException {
        require(visiting.add(author.nodeInstanceId()), "AUTHORED_REVISION_CYCLE");
        var iterationRef = prefix + "iterations/" + author.iterationId() + ".json";
        var iteration = JSON.readValue(canonicalPath(root, iterationRef).toFile(), WorkflowIterationDocument.class);
        require(iteration.iterationId().equals(author.iterationId()), "AUTHORED_ITERATION_MISMATCH");
        if (!stage.author.equals(iteration.targetNodeDefinitionId()) || iteration.triggerNodeInstanceId().isBlank())
            return new Baseline(null, null, List.of());
        var source = node(iteration.triggerNodeInstanceId());
        Candidate parent;
        Reference trigger;
        var added = new ArrayList<Obligation>();
        if (source.kind() == NodeKind.GATE) {
            require(stage.purpose.equals(text(definition.node(source.nodeDefinitionId()).config().get("gate_purpose"))), "AUTHORED_REVISION_STAGE_MISMATCH");
            require(Set.of("revise", "approved").contains(iteration.triggerAction()), "AUTHORED_REVISION_ACTION_INVALID");
            var event = gateEvent(source.nodeInstanceId());
            var gate = gate(event);
            require(source.status() == NodeStatus.COMPLETED && gate.document().status().equals("resolved")
                    && text(gate.document().result().get("human_action")).equals(iteration.triggerAction()), "AUTHORED_REVISION_GATE_UNRESOLVED");
            var note = text(gate.document().result().get("note"));
            require(!note.isBlank(), "AUTHORED_REVISION_NOTE_MISSING");
            edge(source.nodeDefinitionId(), iteration.triggerAction(), stage.author);
            parent = gateSubject(stage, gate); trigger = gate.reference();
            if (gate.source().nodeDefinitionId().equals(stage.decision)) {
                addReview(added, unique(gate.node().inputRefs(), stage.reviewer, "agent_output_contract"));
            }
            added.add(new Obligation("sha256:" + trigger.sha256() + "#human-note:0", trigger, note));
        } else if (stage == Stage.PLAN && iteration.triggerAction().equals("revise_readiness")) {
            require(source.status() == NodeStatus.FAILED, "AUTHORED_REPAIR_FAILURE_MISSING");
            var repair = JSON.valueToTree(source.result().get("readiness_repair"));
            require(repair.path("action").asText().equals("revise_readiness") && !repair.path("note").asText().isBlank(),
                    "AUTHORED_REPAIR_DECISION_MISSING");
            parent = JSON.treeToValue(repair.path("parent_candidate"), Candidate.class);
            require(parent.equals(reviewed(Stage.PLAN, source).candidate()), "AUTHORED_REPAIR_PARENT_MISMATCH");
            trigger = reference(root, prefix + "nodes/" + source.nodeInstanceId() + ".json");
            added.add(new Obligation("sha256:" + trigger.sha256() + "#human-note:0", trigger, repair.path("note").asText()));
        } else {
            require(source.nodeDefinitionId().equals(stage.decision)
                    && iteration.triggerAction().equals("NEEDS_REVISION"), "AUTHORED_REVISION_TRIGGER_INVALID");
            completed(source);
            require(text(source.result().get("decision")).equals("NEEDS_REVISION"), "AUTHORED_REVISION_DECISION_MISMATCH");
            edge(source.nodeDefinitionId(), "NEEDS_REVISION", stage.author);
            var review = unique(source.inputRefs(), stage.reviewer, "agent_output_contract");
            require(document(review).decision().equals("NEEDS_REVISION"), "AUTHORED_REVIEW_DECISION_MISMATCH");
            parent = reviewSubject(stage, node(review.nodeInstanceId())); trigger = review.sidecar();
            require(parent.equals(verifiedCandidateSnapshot(root, ws, review).subject()), "AUTHORED_REVIEW_INPUT_MISMATCH");
            addReview(added, review);
        }
        require((iteration.triggerAction().equals("revise_readiness") || node(parent.nodeInstanceId()).iterationId().equals(iteration.parentIterationId()))
                && source.iterationId().equals(iteration.parentIterationId()), "AUTHORED_REVISION_PARENT_MISMATCH");
        var previous = baseline(stage, node(parent.nodeInstanceId()), visiting);
        var all = new LinkedHashMap<String, Obligation>();
        previous.obligations().forEach(value -> all.put(value.id(), value));
        added.forEach(value -> all.putIfAbsent(value.id(), value));
        return new Baseline(parent, trigger, List.copyOf(all.values()));
    }

    private void addReview(List<Obligation> result, Candidate review) throws IOException {
        var issues = document(review).mustFix();
        for (int i = 0; i < issues.size(); i++) result.add(new Obligation(
                "sha256:" + review.sidecar().sha256() + "#must_fix:" + i, review.sidecar(), issues.get(i)));
    }

    private Event gateEvent(String id) throws IOException {
        var matches = events.stream().filter(event -> event.type().equals("node_routed")
                && id.equals(text(event.payload().get("node_instance_id")))).toList();
        require(matches.size() == 1, "AUTHORED_GATE_EVENT_NOT_UNIQUE");
        return matches.getFirst();
    }

    private Candidate candidate(Stage stage, List<String> refs, NodeInstanceDocument producer) throws IOException {
        var candidate = unique(refs, stage.author, stage.artifact);
        require(candidate.nodeInstanceId().equals(producer.nodeInstanceId()), "AUTHORED_CANDIDATE_SOURCE_MISMATCH");
        return candidate;
    }

    private Candidate unique(List<String> refs, String expectedNode, String type) throws IOException {
        var matches = new LinkedHashMap<String, Candidate>();
        for (var ref : refs) {
            if (!ref.endsWith(".contract.json")) continue;
            var path = canonicalPath(root, ref);
            var document = AgentOutputContractDocument.read(path, JSON).orElseThrow(() -> new IOException("AUTHORED_SIDECAR_INVALID"));
            if (!document.nodeId().equals(expectedNode) || !document.sourceArtifactType().equals(type)) continue;
            require(document.hasRequiredTypedPayload(), "AUTHORED_TYPED_PAYLOAD_MISSING");
            var violation = AgentOutputLineageVerifier.violation(ledger, root, ws, path, document);
            require(violation.isEmpty(), "AUTHORED_CANDIDATE_LINEAGE_INVALID: " + violation.orElse(""));
            matches.put(ref, new Candidate(reference(root, ref), document.nodeInstanceId(), document.nodeId(), document.runId(), type));
        }
        require(matches.size() == 1, "AUTHORED_CANDIDATE_NOT_UNIQUE: " + expectedNode);
        return matches.values().iterator().next();
    }

    private AgentOutputContractDocument document(Candidate candidate) throws IOException {
        return AgentOutputContractDocument.read(verifiedPath(root, candidate.sidecar()), JSON)
                .orElseThrow(() -> new IOException("AUTHORED_SIDECAR_INVALID"));
    }

    private NodeInstanceDocument node(String id) throws IOException {
        require(!id.isBlank(), "AUTHORED_NODE_ID_MISSING");
        var node = JSON.readValue(canonicalPath(root, prefix + "nodes/" + id + ".json").toFile(), NodeInstanceDocument.class);
        require(node.nodeInstanceId().equals(id), "AUTHORED_NODE_ID_MISMATCH");
        return node;
    }

    private void edge(String from, String outcome, String to) throws IOException {
        require(definition.edgesFrom(from).stream().anyMatch(edge -> edge.on().equals(outcome) && edge.to().equals(to)), "AUTHORED_EDGE_NOT_DECLARED");
    }

    private static void completed(NodeInstanceDocument node) throws IOException {
        require(node.status() == NodeStatus.COMPLETED, "AUTHORED_SOURCE_NOT_COMPLETED");
    }

    static void require(boolean valid, String message) throws IOException { if (!valid) throw new IOException(message); }
    private static String text(Object value) { return value instanceof String text ? text : ""; }
    @SuppressWarnings("unchecked") private static Map<String, Object> map(Object value) { return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of(); }
    private static List<String> strings(Object value) { return value instanceof List<?> list ? list.stream().map(AuthoredStageLineageResolver::text).toList() : List.of(); }
    private record Event(long sequence, String id, String type, Map<String, Object> payload) { }
    private record Gate(NodeInstanceDocument node, GateDocument document, Reference reference, NodeInstanceDocument source) { }
    private record Baseline(Candidate parent, Reference trigger, List<Obligation> obligations) { }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContract;
import dev.dual.core.contract.TaskContractValidator;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;

record ChangeScopeEvaluation(
        int schemaVersion,
        Status status,
        List<ActualChange> actualChanges,
        List<String> matchedPaths,
        List<TaskContract.ScopeEntry> missingDeclared,
        List<Violation> violations,
        String error
) {
    ChangeScopeEvaluation {
        actualChanges = List.copyOf(actualChanges == null ? List.of() : actualChanges);
        matchedPaths = List.copyOf(matchedPaths == null ? List.of() : matchedPaths);
        missingDeclared = List.copyOf(missingDeclared == null ? List.of() : missingDeclared);
        violations = List.copyOf(violations == null ? List.of() : violations);
    }

    boolean passed() {
        return status == Status.PASS;
    }

    static ChangeScopeEvaluation unavailable(String error) {
        return new ChangeScopeEvaluation(1, Status.UNAVAILABLE, List.of(), List.of(), List.of(), List.of(), error);
    }

    enum Status {
        PASS,
        FAIL,
        UNAVAILABLE
    }

    enum ActualOperation {
        CREATE,
        MODIFY,
        DELETE,
        RENAME,
        UNKNOWN
    }

    record ActualChange(
            String path,
            ActualOperation operation,
            String previousPath,
            String rawStatus
    ) {}

    record Violation(
            String code,
            String path,
            TaskContract.ScopeOperation declaredOperation,
            ActualOperation actualOperation,
            String previousPath
    ) {}
}

final class ChangeScopeEvaluator {
    private ChangeScopeEvaluator() {}

    static List<ChangeScopeEvaluation.ActualChange> parseNameStatus(String nameStatus) {
        return parseNameStatus(0, nameStatus);
    }

    static List<ChangeScopeEvaluation.ActualChange> parseNameStatus(int exitCode, String nameStatus) {
        if (exitCode != 0) {
            throw new IllegalArgumentException("git name-status command failed with exit code " + exitCode);
        }
        if (nameStatus == null || nameStatus.isBlank()) {
            return List.of();
        }
        var fields = nameStatus.split(String.valueOf('\0'), -1);
        if (fields.length < 2 || !fields[fields.length - 1].isEmpty()) {
            throw new IllegalArgumentException("git name-status output is not NUL terminated");
        }
        var changes = new ArrayList<ChangeScopeEvaluation.ActualChange>();
        for (var index = 0; index < fields.length - 1;) {
            var rawStatus = fields[index++].trim();
            if (rawStatus.isEmpty()) {
                throw new IllegalArgumentException("git name-status output contains an empty status");
            }
            var code = rawStatus.isEmpty() ? '\0' : rawStatus.charAt(0);
            var operation = switch (code) {
                case 'A' -> ChangeScopeEvaluation.ActualOperation.CREATE;
                case 'M' -> ChangeScopeEvaluation.ActualOperation.MODIFY;
                case 'D' -> ChangeScopeEvaluation.ActualOperation.DELETE;
                case 'R' -> ChangeScopeEvaluation.ActualOperation.RENAME;
                default -> ChangeScopeEvaluation.ActualOperation.UNKNOWN;
            };
            var twoPathStatus = code == 'R' || code == 'C';
            var requiredFields = twoPathStatus ? 2 : 1;
            if (index + requiredFields > fields.length - 1) {
                throw new IllegalArgumentException("git name-status output is truncated for status " + rawStatus);
            }
            var previousPath = twoPathStatus ? fields[index++] : null;
            var path = fields[index++];
            if (path.isEmpty() || (twoPathStatus && previousPath.isEmpty())) {
                throw new IllegalArgumentException("git name-status output contains an empty path");
            }
            changes.add(new ChangeScopeEvaluation.ActualChange(path, operation, previousPath, rawStatus));
        }
        return List.copyOf(changes);
    }

    static ChangeScopeEvaluation evaluate(
            TaskContract contract,
            List<ChangeScopeEvaluation.ActualChange> actualChanges
    ) {
        var declaredByPath = new LinkedHashMap<String, TaskContract.ScopeEntry>();
        for (var entry : contract.scope().included()) {
            declaredByPath.put(entry.path(), entry);
        }

        var matchedPaths = new ArrayList<String>();
        var observedPaths = new LinkedHashSet<String>();
        var violations = new ArrayList<ChangeScopeEvaluation.Violation>();
        for (var actual : actualChanges) {
            observedPaths.add(actual.path());
            var declared = declaredByPath.get(actual.path());
            if (!TaskContractValidator.isCanonicalPath(actual.path())) {
                violations.add(violation("INVALID_ACTUAL_PATH", actual, declared));
                continue;
            }
            if (actual.operation() == ChangeScopeEvaluation.ActualOperation.DELETE
                    || actual.operation() == ChangeScopeEvaluation.ActualOperation.RENAME
                    || actual.operation() == ChangeScopeEvaluation.ActualOperation.UNKNOWN) {
                violations.add(violation("UNSUPPORTED_ACTUAL_OPERATION", actual, declared));
                continue;
            }
            if (declared == null) {
                violations.add(violation("UNEXPECTED_ACTUAL_CHANGE", actual, null));
                continue;
            }
            if (expectedActualOperation(declared.operation()) != actual.operation()) {
                violations.add(violation("OPERATION_MISMATCH", actual, declared));
                continue;
            }
            matchedPaths.add(actual.path());
        }

        var missingDeclared = contract.scope().included().stream()
                .filter(entry -> !observedPaths.contains(entry.path()))
                .toList();
        return new ChangeScopeEvaluation(
                1,
                violations.isEmpty() ? ChangeScopeEvaluation.Status.PASS : ChangeScopeEvaluation.Status.FAIL,
                actualChanges,
                matchedPaths,
                missingDeclared,
                violations,
                null
        );
    }

    private static ChangeScopeEvaluation.ActualOperation expectedActualOperation(
            TaskContract.ScopeOperation operation
    ) {
        return switch (operation) {
            case CREATE -> ChangeScopeEvaluation.ActualOperation.CREATE;
            case MODIFY -> ChangeScopeEvaluation.ActualOperation.MODIFY;
        };
    }

    private static ChangeScopeEvaluation.Violation violation(
            String code,
            ChangeScopeEvaluation.ActualChange actual,
            TaskContract.ScopeEntry declared
    ) {
        return new ChangeScopeEvaluation.Violation(
                code,
                actual.path(),
                declared == null ? null : declared.operation(),
                actual.operation(),
                actual.previousPath()
        );
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.UUID;
import java.util.regex.Pattern;

final class ChangeScopeEvaluationArtifact {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .findAndRegisterModules()
            .enable(SerializationFeature.INDENT_OUTPUT);
    private static final Pattern REF = Pattern.compile(
            "\\.agent/workstreams/([^/]+)/artifacts/git-evidence/occurrences/([^/]+)/change-scope-evaluation-([0-9a-f]{64})\\.json");

    private ChangeScopeEvaluationArtifact() {
    }

    static Reference publish(
            Path workspaceRoot,
            String workstreamId,
            String sourceNodeInstanceId,
            ChangeScopeEvaluation evaluation
    ) throws IOException {
        var document = new Document(1, workstreamId, sourceNodeInstanceId, evaluation);
        var bytes = OBJECT_MAPPER.writeValueAsBytes(document);
        var sha256 = sha256(bytes);
        var ref = ".agent/workstreams/" + workstreamId
                + "/artifacts/git-evidence/occurrences/" + sourceNodeInstanceId
                + "/change-scope-evaluation-" + sha256 + ".json";
        var target = resolveInside(workspaceRoot, ref);
        Files.createDirectories(target.getParent());
        if (Files.exists(target)) {
            if (!Files.isRegularFile(target) || !sha256(Files.readAllBytes(target)).equals(sha256)) {
                throw new IOException("existing change-scope occurrence does not match its content address");
            }
            return new Reference(ref, sha256);
        }
        var temporary = target.resolveSibling(target.getFileName() + ".tmp-" + UUID.randomUUID());
        try {
            Files.write(temporary, bytes);
            try {
                Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE);
            } catch (IOException atomicMoveFailure) {
                Files.move(temporary, target);
            }
        } finally {
            Files.deleteIfExists(temporary);
        }
        return new Reference(ref, sha256);
    }

    static Verified verify(
            Path workspaceRoot,
            String expectedWorkstreamId,
            String expectedSourceNodeInstanceId,
            String ref,
            String expectedSha256
    ) throws IOException {
        var matcher = REF.matcher(ref == null ? "" : ref);
        if (!matcher.matches()
                || !expectedWorkstreamId.equals(matcher.group(1))
                || !expectedSourceNodeInstanceId.equals(matcher.group(2))) {
            throw new IOException("change-scope evaluation ref is not canonical for the expected occurrence");
        }
        if (expectedSha256 == null || !expectedSha256.matches("[0-9a-f]{64}")
                || !expectedSha256.equals(matcher.group(3))) {
            throw new IOException("change-scope evaluation ref sha256 does not match the lineage anchor");
        }
        var path = resolveInside(workspaceRoot, ref);
        if (!Files.isRegularFile(path)) {
            throw new IOException("change-scope evaluation occurrence is missing");
        }
        var bytes = Files.readAllBytes(path);
        var actualSha256 = sha256(bytes);
        if (!expectedSha256.equals(actualSha256)) {
            throw new IOException("change-scope evaluation occurrence sha256 mismatch");
        }
        final Document document;
        try {
            document = OBJECT_MAPPER.readValue(bytes, Document.class);
        } catch (Exception failure) {
            throw new IOException("change-scope evaluation occurrence cannot be parsed", failure);
        }
        if (document.schemaVersion() != 1
                || !expectedWorkstreamId.equals(document.workstreamId())
                || !expectedSourceNodeInstanceId.equals(document.sourceNodeInstanceId())
                || document.evaluation() == null) {
            throw new IOException("change-scope evaluation occurrence lineage mismatch");
        }
        return new Verified(ref, actualSha256, document, path);
    }

    static String sourceNodeInstanceId(String ref) {
        var matcher = REF.matcher(ref == null ? "" : ref);
        return matcher.matches() ? matcher.group(2) : "";
    }

    static Verified verifyGateSource(Path root, String workstreamId, String iterationId,
                                     java.util.List<String> inputRefs) throws IOException {
        var refs = inputRefs.stream().filter(ref -> isCanonicalRefForWorkstream(ref, workstreamId)).toList();
        if (refs.size() != 1) {
            throw new IOException("change-scope violation gate must receive exactly one occurrence evaluation");
        }
        var ref = refs.getFirst();
        var sourceId = sourceNodeInstanceId(ref);
        var sourcePath = resolveInside(root, ".agent/workstreams/" + workstreamId + "/nodes/" + sourceId + ".json");
        var source = OBJECT_MAPPER.readValue(sourcePath.toFile(), dev.dual.ledger.file.NodeInstanceDocument.class);
        if (!sourceId.equals(source.nodeInstanceId())
                || !"implement.artifact_validation".equals(source.nodeDefinitionId())
                || !"artifact.validate".equals(source.handlerType())
                || source.status() != dev.dual.core.workflow.NodeStatus.COMPLETED
                || !iterationId.equals(source.iterationId()) || !source.outputRefs().contains(ref)
                || !"FAIL".equals(source.result().get("change_scope_status"))
                || !"CHANGE_SCOPE_VIOLATION".equals(source.result().get("change_scope_disposition"))
                || !ref.equals(source.result().get("change_scope_evaluation_ref"))) {
            throw new IOException("change-scope evaluation producer lineage is invalid");
        }
        var verified = verify(root, workstreamId, sourceId, ref,
                String.valueOf(source.result().get("change_scope_evaluation_sha256")));
        if (verified.document().evaluation().status() != ChangeScopeEvaluation.Status.FAIL) {
            throw new IOException("change-scope occurrence is not a failed evaluation");
        }
        return verified;
    }

    static boolean isCanonicalRefForWorkstream(String ref, String workstreamId) {
        var matcher = REF.matcher(ref == null ? "" : ref);
        return matcher.matches() && workstreamId.equals(matcher.group(1));
    }

    private static Path resolveInside(Path workspaceRoot, String ref) throws IOException {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root)) {
            throw new IOException("change-scope evaluation ref escapes the workspace");
        }
        return path;
    }

    private static String sha256(byte[] bytes) throws IOException {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (NoSuchAlgorithmException impossible) {
            throw new IOException("SHA-256 is unavailable", impossible);
        }
    }

    record Document(
            int schemaVersion,
            String workstreamId,
            String sourceNodeInstanceId,
            ChangeScopeEvaluation evaluation
    ) {
    }

    record Reference(String ref, String sha256) {
    }

    record Verified(String ref, String sha256, Document document, Path path) {
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeInstance;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.ledger.file.GoalDomainOutcome;
import dev.dual.ledger.file.GoalSatisfactionDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowDefinitionDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkflowInstanceDocument;
import dev.dual.ledger.file.WorkstreamPaths;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Resolves final completion evidence exclusively through persisted ledger lineage. */
public final class CompletionEvidenceLineageResolver {
    public static final String GOAL_NOT_CONFIGURED = "COMPLETION_GOAL_NOT_CONFIGURED";
    public static final String GOAL_NOT_FINAL = "COMPLETION_GOAL_NOT_FINAL";
    public static final String GOAL_INVALID = "COMPLETION_GOAL_INVALID";
    public static final String ACCEPTANCE_INVALID = "COMPLETION_ACCEPTANCE_LINEAGE_INVALID";
    public static final String CONTEXT_INVALID = "COMPLETION_CONTEXT_LINEAGE_INVALID";
    public static final String SELF_TEST_INVALID = "COMPLETION_SELF_TEST_LINEAGE_INVALID";

    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule())
            .registerModule(new dev.dual.ledger.file.EdgeConditionModule());

    private CompletionEvidenceLineageResolver() {
    }

    public static Resolution resolveCurrent(WorkflowFileLedger ledger, Path workspaceRoot, String workstreamId) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        if (!Files.isRegularFile(paths.goalSatisfactionJson())) {
            return Resolution.notConfigured("goal satisfaction document is not configured");
        }
        try {
            var goal = OBJECT_MAPPER.readValue(paths.goalSatisfactionJson().toFile(), GoalSatisfactionDocument.class);
            if (!workstreamId.equals(goal.workstreamId())) {
                return Resolution.invalid(GOAL_INVALID, "goal workstream_id does not match", goal);
            }
            var current = ledger.loadCurrent(paths);
            var instance = OBJECT_MAPPER.readValue(paths.workflowInstanceJson().toFile(), WorkflowInstanceDocument.class);
            var definitionDocument = OBJECT_MAPPER.readValue(
                    paths.workflowDefinitionJson().toFile(), WorkflowDefinitionDocument.class);
            var definition = new WorkflowDefinition(
                    definitionDocument.workflowId(),
                    definitionDocument.version(),
                    definitionDocument.entryNodeId(),
                    definitionDocument.nodes(),
                    definitionDocument.edges());
            if (!goal.workflowInstanceId().equals(current.workflowInstanceId())
                    || !goal.workflowInstanceId().equals(instance.workflowInstanceId())
                    || !current.workflowId().equals(definition.workflowId())
                    || current.definitionVersion() != definition.version()
                    || !instance.workflowId().equals(definition.workflowId())
                    || instance.definitionVersion() != definition.version()) {
                return Resolution.invalid(GOAL_INVALID, "goal workflow identity does not match persisted workflow", goal);
            }
            if (!"acceptance.decision".equals(goal.nodeDefinitionId())
                    || !Set.of(GoalDomainOutcome.SATISFIED, GoalDomainOutcome.SATISFIED_WITH_NOTES)
                    .contains(goal.domainOutcome())) {
                return Resolution.notFinal(goal, "current goal is not a final satisfied acceptance");
            }

            var decisionNode = ledger.loadNode(paths, goal.nodeInstanceId());
            var decisionViolation = decisionViolation(goal, decisionNode);
            if (!decisionViolation.isBlank()) {
                return Resolution.invalid(GOAL_INVALID, decisionViolation, goal);
            }

            var acceptance = acceptanceEvidence(ledger, root, workstreamId, paths, definition, goal, decisionNode);
            if (acceptance.failure() != null) {
                return Resolution.invalid(ACCEPTANCE_INVALID, acceptance.failure(), goal);
            }
            var context = contextNode(ledger, root, workstreamId, paths, definition, goal, acceptance.evidence());
            if (context.failure() != null) {
                return Resolution.invalid(CONTEXT_INVALID, context.failure(), goal);
            }
            var selfTest = selfTestEvidence(
                    ledger, root, workstreamId, paths, definition, goal, context.node(), context.definitionConfig());
            if (selfTest.failure() != null) {
                return Resolution.invalid(SELF_TEST_INVALID, selfTest.failure(), goal);
            }
            VerificationEvidence.verifyPublished(ledger, root, workstreamId, acceptance.evidence().document());
            VerificationEvidence.verifyPublished(ledger, root, workstreamId, selfTest.evidence().document());
            return Resolution.available(goal, decisionNode, context.node(), acceptance.evidence(), selfTest.evidence());
        } catch (Exception e) {
            return Resolution.invalid(GOAL_INVALID, "completion evidence cannot be resolved: " + e.getMessage(), null);
        }
    }

    public static Resolution resolveForReport(
            WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            NodeInstance reportNode
    ) {
        var resolution = resolveCurrent(ledger, workspaceRoot, workstreamId);
        if (resolution.status() != Status.AVAILABLE) {
            return resolution;
        }
        if (!"acceptance.generate_final_report".equals(reportNode.nodeDefinitionId())) {
            return Resolution.invalid(GOAL_INVALID, "report node definition is not acceptance.generate_final_report",
                    resolution.goal());
        }
        if (!resolution.goal().iterationId().equals(reportNode.iterationId())) {
            return Resolution.invalid(GOAL_INVALID, "report node iteration does not match final goal",
                    resolution.goal());
        }
        if (!sameRefs(resolution.goal().evidenceRefs(), reportNode.inputRefs())) {
            return Resolution.invalid(GOAL_INVALID, "report routed refs do not match final goal evidence refs",
                    resolution.goal());
        }
        return resolution;
    }

    private static String decisionViolation(GoalSatisfactionDocument goal, NodeInstanceDocument node) {
        if (!goal.nodeInstanceId().equals(node.nodeInstanceId())
                || !goal.nodeDefinitionId().equals(node.nodeDefinitionId())) {
            return "goal does not identify the persisted acceptance decision node";
        }
        if (node.status() != NodeStatus.COMPLETED || !goal.iterationId().equals(node.iterationId())) {
            return "acceptance decision node is not completed in the goal iteration";
        }
        if (!goal.outcome().equals(text(node.result().get("decision")))) {
            return "goal outcome does not match acceptance decision node result";
        }
        if (!sameRefs(goal.evidenceRefs(), node.outputRefs())) {
            return "goal evidence refs do not match acceptance decision output refs";
        }
        return "";
    }

    private static EvidenceRead acceptanceEvidence(
            WorkflowFileLedger ledger,
            Path root,
            String workstreamId,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            GoalSatisfactionDocument goal,
            NodeInstanceDocument decisionNode
    ) {
        try {
            var predecessors = definition.edges().stream()
                    .filter(edge -> "acceptance.decision".equals(edge.to()))
                    .map(edge -> edge.from())
                    .collect(java.util.stream.Collectors.toUnmodifiableSet());
            var matches = AgentEvidenceIndex.fromRefs(ledger, root, workstreamId, decisionNode.outputRefs(), OBJECT_MAPPER)
                    .recent(Math.max(1, decisionNode.outputRefs().size()))
                    .stream()
                    .filter(entry -> predecessors.contains(entry.document().nodeId()))
                    .filter(entry -> ContractRegistry.hasContract(entry.document().nodeId()))
                    .filter(entry -> ContractRegistry.forNode(entry.document().nodeId())
                            .emitsArtifact(entry.document().sourceArtifactType()))
                    .filter(entry -> "acceptance_review".equals(entry.document().sourceArtifactType()))
                    .filter(entry -> goal.outcome().equals(entry.document().decision()))
                    .toList();
            if (matches.size() != 1) {
                return EvidenceRead.failed("expected exactly one routed final acceptance sidecar, found " + matches.size());
            }
            var entry = matches.getFirst();
            var producer = ledger.loadNode(paths, entry.document().nodeInstanceId());
            if (!goal.iterationId().equals(producer.iterationId())) {
                return EvidenceRead.failed("acceptance sidecar producer is from another iteration");
            }
            return EvidenceRead.found(evidence(root, entry));
        } catch (Exception e) {
            return EvidenceRead.failed("acceptance evidence is invalid: " + e.getMessage());
        }
    }

    private static ContextRead contextNode(
            WorkflowFileLedger ledger,
            Path root,
            String workstreamId,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            GoalSatisfactionDocument goal,
            Evidence acceptance
    ) {
        try {
            var producer = ledger.loadNode(paths, acceptance.document().nodeInstanceId());
            var packageRefs = producer.inputRefs().stream()
                    .filter(ref -> canonicalContextPackageRef(workstreamId, ref))
                    .toList();
            if (packageRefs.size() != 1) {
                return ContextRead.failed("expected exactly one acceptance context package ref, found "
                        + packageRefs.size());
            }
            var packageRef = normalizeRef(packageRefs.getFirst());
            var packagePath = root.resolve(packageRef).normalize();
            if (!regularFileWithin(root, packagePath)) {
                return ContextRead.failed("acceptance context package is not a regular workspace file");
            }
            var fileName = packagePath.getFileName().toString();
            var contextNodeId = fileName.substring(0, fileName.length() - ".md".length());
            var contextNode = ledger.loadNode(paths, contextNodeId);
            if (!contextNodeId.equals(contextNode.nodeInstanceId())
                    || contextNode.status() != NodeStatus.COMPLETED
                    || !goal.iterationId().equals(contextNode.iterationId())
                    || !"context.build_package".equals(contextNode.handlerType())
                    || !containsRef(contextNode.outputRefs(), packageRef)) {
                return ContextRead.failed("context package is not published by the completed context node occurrence");
            }
            var contextDefinition = definition.node(contextNode.nodeDefinitionId());
            var profile = text(contextDefinition.config().get("profile"));
            var target = text(contextDefinition.config().get("target_node"));
            if (!"acceptance".equals(profile) || !acceptance.document().nodeId().equals(target)) {
                return ContextRead.failed("context node definition does not target the acceptance producer");
            }
            var metadataRef = packageRef.substring(0, packageRef.length() - ".md".length()) + ".json";
            if (!containsRef(producer.inputRefs(), metadataRef)
                    || !containsRef(contextNode.outputRefs(), metadataRef)
                    || !regularFileWithin(root, root.resolve(metadataRef).normalize())) {
                return ContextRead.failed("acceptance context metadata is not published by the same context occurrence");
            }
            return ContextRead.found(contextNode, contextDefinition.config());
        } catch (Exception e) {
            return ContextRead.failed("acceptance context lineage is invalid: " + e.getMessage());
        }
    }

    private static EvidenceRead selfTestEvidence(
            WorkflowFileLedger ledger,
            Path root,
            String workstreamId,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            GoalSatisfactionDocument goal,
            NodeInstanceDocument contextNode,
            Map<String, Object> contextConfig
    ) {
        try {
            var required = requiredEvidence(contextConfig.get("required_agent_evidence"));
            var requiredDefinition = definition.node(required.nodeId());
            if (!ContractRegistry.hasContract(required.nodeId())
                    || !ContractRegistry.forNode(required.nodeId()).emitsArtifact(required.sourceArtifactType())
                    || !"acpx.agent_run".equals(requiredDefinition.handlerType())) {
                return EvidenceRead.failed("required self-test evidence is not compatible with its workflow contract");
            }
            var matches = AgentEvidenceIndex.fromRefs(ledger, root, workstreamId, contextNode.inputRefs(), OBJECT_MAPPER)
                    .recent(Math.max(1, contextNode.inputRefs().size()))
                    .stream()
                    .filter(entry -> required.nodeId().equals(entry.document().nodeId()))
                    .filter(entry -> required.sourceArtifactType().equals(entry.document().sourceArtifactType()))
                    .filter(entry -> required.decision().equals(entry.document().decision()))
                    .filter(entry -> entry.document().hasRequiredTypedPayload())
                    .toList();
            if (matches.size() != 1) {
                return EvidenceRead.failed("expected exactly one routed self-test sidecar, found " + matches.size());
            }
            var entry = matches.getFirst();
            var producer = ledger.loadNode(paths, entry.document().nodeInstanceId());
            if (!goal.iterationId().equals(producer.iterationId())) {
                return EvidenceRead.failed("self-test sidecar producer is from another iteration");
            }
            return EvidenceRead.found(evidence(root, entry));
        } catch (Exception e) {
            return EvidenceRead.failed("self-test evidence is invalid: " + e.getMessage());
        }
    }

    private static RequiredEvidence requiredEvidence(Object configured) {
        if (!(configured instanceof Map<?, ?> values)) {
            throw new IllegalArgumentException("required_agent_evidence must be an object");
        }
        return new RequiredEvidence(
                requiredText(values, "node_id"),
                requiredText(values, "source_artifact_type"),
                requiredText(values, "decision"));
    }

    private static String requiredText(Map<?, ?> values, String key) {
        var value = text(values.get(key));
        if (value.isBlank()) {
            throw new IllegalArgumentException("required_agent_evidence." + key + " is required");
        }
        return value;
    }

    private static Evidence evidence(Path root, AgentEvidenceIndex.Entry entry) {
        return new Evidence(
                normalizeRef(root.relativize(entry.path()).toString()),
                entry.path(),
                entry.document());
    }

    private static boolean canonicalContextPackageRef(String workstreamId, String ref) {
        var normalized = normalizeRef(ref);
        var prefix = ".agent/workstreams/" + workstreamId + "/context/";
        if (!normalized.startsWith(prefix) || !normalized.endsWith(".md")) {
            return false;
        }
        var name = normalized.substring(prefix.length(), normalized.length() - ".md".length());
        return !name.isBlank() && !name.contains("/") && !name.contains("\\");
    }

    private static boolean regularFileWithin(Path root, Path path) {
        try {
            return path.startsWith(root)
                    && Files.isRegularFile(path)
                    && !Files.isSymbolicLink(path)
                    && path.toRealPath().startsWith(root.toRealPath());
        } catch (Exception e) {
            return false;
        }
    }

    private static boolean sameRefs(List<String> left, List<String> right) {
        return left.stream().map(CompletionEvidenceLineageResolver::normalizeRef).toList()
                .equals(right.stream().map(CompletionEvidenceLineageResolver::normalizeRef).toList());
    }

    private static boolean containsRef(List<String> refs, String expected) {
        var normalized = normalizeRef(expected);
        return refs.stream().map(CompletionEvidenceLineageResolver::normalizeRef).anyMatch(normalized::equals);
    }

    private static String normalizeRef(String value) {
        return value == null ? "" : value.replace('\\', '/');
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    public enum Status {
        AVAILABLE,
        NOT_CONFIGURED,
        NOT_FINAL,
        INVALID
    }

    public record Evidence(String ref, Path path, AgentOutputContractDocument document) {
    }

    public record Resolution(
            Status status,
            String failureCode,
            String detail,
            GoalSatisfactionDocument goal,
            NodeInstanceDocument decisionNode,
            NodeInstanceDocument contextNode,
            Evidence acceptance,
            Evidence selfTest
    ) {
        static Resolution available(
                GoalSatisfactionDocument goal,
                NodeInstanceDocument decisionNode,
                NodeInstanceDocument contextNode,
                Evidence acceptance,
                Evidence selfTest
        ) {
            return new Resolution(Status.AVAILABLE, "", "", goal, decisionNode, contextNode, acceptance, selfTest);
        }

        static Resolution notConfigured(String detail) {
            return new Resolution(Status.NOT_CONFIGURED, GOAL_NOT_CONFIGURED, detail,
                    null, null, null, null, null);
        }

        static Resolution notFinal(GoalSatisfactionDocument goal, String detail) {
            return new Resolution(Status.NOT_FINAL, GOAL_NOT_FINAL, detail,
                    goal, null, null, null, null);
        }

        static Resolution invalid(String code, String detail, GoalSatisfactionDocument goal) {
            return new Resolution(Status.INVALID, code, detail, goal, null, null, null, null);
        }
    }

    private record EvidenceRead(Evidence evidence, String failure) {
        static EvidenceRead found(Evidence evidence) {
            return new EvidenceRead(evidence, null);
        }

        static EvidenceRead failed(String failure) {
            return new EvidenceRead(null, failure);
        }
    }

    private record ContextRead(NodeInstanceDocument node, Map<String, Object> definitionConfig, String failure) {
        static ContextRead found(NodeInstanceDocument node, Map<String, Object> definitionConfig) {
            return new ContextRead(node, definitionConfig, null);
        }

        static ContextRead failed(String failure) {
            return new ContextRead(null, null, failure);
        }
    }

    private record RequiredEvidence(String nodeId, String sourceArtifactType, String decision) {
    }
}

package dev.dual.runtime.handler;

