package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.adapter.git.GitPatchMergeService;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeResult;
import dev.dual.ledger.file.DeliveryCandidateDocument;
import dev.dual.ledger.file.DeliveryCandidateWriter;
import dev.dual.ledger.file.WorkstreamDocument;
import dev.dual.ledger.file.WorkspaceDocument;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class DeliveryPrepareHandler implements TaskHandler {
    private static final int MAX_SECTION_CHARS = 4_000;

    private final GitPatchMergeService git;
    private final DeliveryCandidateWriter candidateWriter;
    private final ObjectMapper objectMapper;

    public DeliveryPrepareHandler() {
        this(new GitPatchMergeService(), new DeliveryCandidateWriter(), new ObjectMapper().findAndRegisterModules());
    }

    DeliveryPrepareHandler(
            GitPatchMergeService git,
            DeliveryCandidateWriter candidateWriter,
            ObjectMapper objectMapper
    ) {
        this.git = git;
        this.candidateWriter = candidateWriter;
        this.objectMapper = objectMapper;
    }

    @Override
    public String type() {
        return "delivery.prepare_pr";
    }

    @Override
    public NodeResult execute(TaskContext context) throws Exception {
        var paths = new WorkstreamPaths(context.workspaceRoot(), new DualId(context.workstreamId()));
        var existing = candidateWriter.existing(paths, context.instance().nodeInstanceId());
        if (existing != null) {
            restoreStableProjections(paths, existing.document());
            return result(paths, existing);
        }

        var sourceIdentity = sourceIdentity(paths, context.workspaceRoot());
        var capture = git.capture(context.workspaceRoot());
        var commitMessage = renderCommitMessage(context.workstreamId(), paths.workstreamDir());
        var prBody = renderPrBody(context, paths.workstreamDir());
        var patchBytes = capture.patch().getBytes(StandardCharsets.UTF_8);
        var commitBytes = commitMessage.getBytes(StandardCharsets.UTF_8);
        var prBodyBytes = prBody.getBytes(StandardCharsets.UTF_8);
        var occurrenceDir = paths.deliveryCandidateDir(context.instance().nodeInstanceId());
        var patchRef = workspaceRef(paths.workspaceRoot(), occurrenceDir.resolve("merge.patch"));
        var commitRef = workspaceRef(paths.workspaceRoot(), occurrenceDir.resolve("commit-message.txt"));
        var prBodyRef = workspaceRef(paths.workspaceRoot(), occurrenceDir.resolve("pr-body.md"));
        var candidate = new DeliveryCandidateDocument(
                1,
                context.workstreamId(),
                context.instance().nodeInstanceId(),
                context.instance().iterationId(),
                sourceIdentity.workspaceId(),
                sourceIdentity.effectiveWorkdir(),
                capture.baseCommit(),
                capture.baseTree(),
                capture.acceptedFiles(),
                capture.excludedFiles(),
                new DeliveryCandidateDocument.ArtifactReference(patchRef, DeliveryCandidateWriter.sha256(patchBytes)),
                capture.expectedResultTree(),
                new DeliveryCandidateDocument.ArtifactReference(commitRef, DeliveryCandidateWriter.sha256(commitBytes)),
                new DeliveryCandidateDocument.ArtifactReference(prBodyRef, DeliveryCandidateWriter.sha256(prBodyBytes)),
                context.instance().startedAt() == null ? Instant.now() : context.instance().startedAt()
        );
        var published = candidateWriter.publish(paths, candidate, Map.of(
                "merge.patch", patchBytes,
                "commit-message.txt", commitBytes,
                "pr-body.md", prBodyBytes
        ));
        restoreStableProjections(paths, candidate);
        return result(paths, published);
    }

    private NodeResult result(WorkstreamPaths paths, DeliveryCandidateWriter.Published published) {
        var stableCommitRef = workspaceRef(paths.workspaceRoot(), paths.deliveryDir().resolve("commit-message.txt"));
        var stablePrBodyRef = workspaceRef(paths.workspaceRoot(), paths.deliveryDir().resolve("pr-body.md"));
        var result = new LinkedHashMap<String, Object>();
        result.put("commit_message_path", stableCommitRef);
        result.put("pr_body_path", stablePrBodyRef);
        result.put("delivery_candidate_ref", published.ref());
        result.put("delivery_candidate_sha256", published.sha256());
        result.put("expected_result_tree", published.document().expectedResultTree());
        result.put("prepared_at", published.document().createdAt().toString());
        return NodeResult.completed(
                "completed",
                List.of(stableCommitRef, stablePrBodyRef, published.ref()),
                result
        );
    }

    private SourceIdentity sourceIdentity(WorkstreamPaths paths, Path workspaceRoot) throws IOException {
        if (!Files.isRegularFile(paths.workstreamJson())) {
            throw new IOException("workstream identity is missing: " + paths.workstreamJson());
        }
        var workstream = objectMapper.readValue(paths.workstreamJson().toFile(), WorkstreamDocument.class);
        if (workstream.primaryWorkspaceId() == null || workstream.primaryWorkspaceId().isBlank()) {
            throw new IOException("workstream primary workspace identity is missing");
        }
        var workspacePath = paths.workspaceJson(new DualId(workstream.primaryWorkspaceId()));
        if (!Files.isRegularFile(workspacePath)) {
            throw new IOException("workspace identity is missing: " + workspacePath);
        }
        var workspace = objectMapper.readValue(workspacePath.toFile(), WorkspaceDocument.class);
        var effective = Path.of(workspace.effectiveWorkdir()).toAbsolutePath().normalize();
        if (!workspace.workstreamId().equals(workstream.workstreamId())
                || !workspace.workspaceId().equals(workstream.primaryWorkspaceId())
                || !effective.equals(workspaceRoot.toAbsolutePath().normalize())) {
            throw new IOException("delivery source workspace identity does not match the execution workspace");
        }
        return new SourceIdentity(workspace.workspaceId(), effective.toString());
    }

    private void restoreStableProjections(WorkstreamPaths paths, DeliveryCandidateDocument candidate) throws IOException {
        Files.createDirectories(paths.deliveryDir());
        Files.copy(resolveRef(paths.workspaceRoot(), candidate.commitMessage().ref()),
                paths.deliveryDir().resolve("commit-message.txt"), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
        Files.copy(resolveRef(paths.workspaceRoot(), candidate.prBody().ref()),
                paths.deliveryDir().resolve("pr-body.md"), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
    }

    private static String renderCommitMessage(String workstreamId, Path workstreamDir) throws IOException {
        var summary = firstNonBlankLine(readOrDefault(workstreamDir.resolve("requirement.md"), "Dual agent task"));
        return """
                feat: dual agent task %s

                %s

                Run report: .agent/workstreams/%s/reports/latest-final-report.md
                """.formatted(workstreamId, summary, workstreamId);
    }

    private static String renderPrBody(TaskContext context, Path workstreamDir) throws IOException {
        var builder = new StringBuilder();
        builder.append("# Dual Agent Run PR\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Generated At: ").append(Instant.now()).append("\n");
        builder.append("- Final Report: .agent/workstreams/")
                .append(context.workstreamId()).append("/reports/latest-final-report.md\n\n");
        builder.append("## User Request\n\n")
                .append(readOrDefault(workstreamDir.resolve("requirement.md"), "(requirement.md not found)"))
                .append("\n\n");
        builder.append("## Summary\n\n")
                .append(snippet(readOrDefault(workstreamDir.resolve("reports/latest-final-report.md"), "(final report not generated)")))
                .append("\n\n");
        builder.append("## Verification\n\n")
                .append(readEvidenceFile(workstreamDir, "diff.stat", "(diff stat not available)"))
                .append("\n\n");
        builder.append("## Codex Final Acceptance\n\n")
                .append("See the typed acceptance evidence summarized in the final report.\n\n");
        builder.append("## Changed Files\n\n").append(readChangedFiles(workstreamDir)).append("\n\n");
        builder.append("## Run Artifacts\n\n")
                .append("- Final report: .agent/workstreams/").append(context.workstreamId()).append("/reports/latest-final-report.md\n")
                .append("- Git evidence: .agent/workstreams/").append(context.workstreamId()).append("/artifacts/git-evidence/\n")
                .append("- Events: .agent/workstreams/").append(context.workstreamId()).append("/events.jsonl\n")
                .append("- Runs: .agent/workstreams/").append(context.workstreamId()).append("/runs/\n\n")
                .append("## Risks / Notes\n\nReview the final acceptance evidence and immutable delivery candidate before merging.\n");
        return builder.toString();
    }

    private static String readChangedFiles(Path workstreamDir) throws IOException {
        var changed = readEvidenceFile(workstreamDir, "changed-files.txt", "");
        if (changed.isBlank()) return "(no changed files recorded)";
        var builder = new StringBuilder();
        for (var line : changed.split("\\R")) {
            if (!line.isBlank()) builder.append("- ").append(line.trim()).append("\n");
        }
        return builder.toString().stripTrailing();
    }

    private static String readEvidenceFile(Path workstreamDir, String fileName, String fallback) throws IOException {
        return readOrDefault(workstreamDir.resolve("artifacts/git-evidence").resolve(fileName), fallback);
    }

    private static String readOrDefault(Path path, String fallback) throws IOException {
        return Files.exists(path) ? Files.readString(path, StandardCharsets.UTF_8).stripTrailing() : fallback;
    }

    private static String firstNonBlankLine(String text) {
        return text.lines().map(String::trim).filter(line -> !line.isBlank()).findFirst().orElse("Dual agent task");
    }

    private static String snippet(String content) {
        return content.length() <= MAX_SECTION_CHARS
                ? content
                : content.substring(0, MAX_SECTION_CHARS).stripTrailing() + "\n\n[truncated]";
    }

    private static String workspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static Path resolveRef(Path workspaceRoot, String ref) throws IOException {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root)) throw new IOException("delivery artifact ref escapes workspace: " + ref);
        return path;
    }

    private record SourceIdentity(String workspaceId, String effectiveWorkdir) {
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContract;
import dev.dual.core.contract.TaskContractValidator;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

/** Checks declared file scope, never business relevance or actual Git changes. */
final class DesignScopeValidator {
    private DesignScopeValidator() {
    }

    static List<String> shapeErrors(AgentResultEnvelope.Design design) {
        if (design == null || design.plannedFiles() == null) {
            return List.of("DESIGN_SCOPE_MISSING: result.design.planned_files is required");
        }
        var errors = new ArrayList<String>();
        var paths = new HashSet<String>();
        for (var file : design.plannedFiles()) {
            if (file == null) {
                errors.add("DESIGN_SCOPE_ENTRY_INVALID: null entry");
                continue;
            }
            if (!TaskContractValidator.isCanonicalPath(file.path())) {
                errors.add("DESIGN_SCOPE_PATH_INVALID: " + file.path());
            }
            if (!paths.add(file.path())) {
                errors.add("DESIGN_SCOPE_PATH_DUPLICATE: " + file.path());
            }
            if (file.operation() == null) {
                errors.add("DESIGN_SCOPE_OPERATION_MISSING: " + file.path());
            }
            if (file.responsibility() == null || file.responsibility().isBlank()) {
                errors.add("DESIGN_SCOPE_RESPONSIBILITY_MISSING: " + file.path());
            }
        }
        return List.copyOf(errors);
    }

    static List<String> validate(dev.dual.ledger.file.WorkflowFileLedger ledger, Path root, String workstreamId, AgentResultEnvelope.Design design) {
        var errors = shapeErrors(design);
        if (!errors.isEmpty()) {
            return errors;
        }
        var resolution = TaskContractProjectionVerifier.resolve(ledger, root, workstreamId, dev.dual.core.contract.TaskContract.Phase.GOAL);
        if (resolution.failure() != null || resolution.qualified().isEmpty()) {
            return List.of("DESIGN_CONTRACT_NOT_QUALIFIED: " + (resolution.failure() == null
                    ? "approved contract is absent" : resolution.failure().reason()));
        }
        return scopeErrors(design, resolution.qualified().orElseThrow().contract());
    }

    static List<String> scopeErrors(AgentResultEnvelope.Design design, TaskContract contract) {
        return proposedScopeErrors(design.plannedFiles().stream()
                .map(file -> new TaskContract.ScopeEntry(file.path(), file.operation())).toList(), contract);
    }

    static List<String> proposedScopeErrors(List<TaskContract.ScopeEntry> files, TaskContract contract) {
        var errors = new ArrayList<String>();
        for (var file : files) {
            if (file == null || !TaskContractValidator.isCanonicalPath(file.path()) || file.operation() == null) {
                errors.add("PROPOSED_SCOPE_INVALID");
                continue;
            }
            if (file.path().equals(".agent") || file.path().startsWith(".agent/")
                    || file.path().equals(".git") || file.path().startsWith(".git/")
                    || contract.scope().excluded().stream().anyMatch(excluded -> file.path().equals(excluded)
                        || (TaskContractValidator.isCanonicalPath(excluded) && file.path().startsWith(excluded + "/")))) {
                errors.add("PROPOSED_SCOPE_EXCLUDED: " + file.path());
            }
            if (contract.phase() == TaskContract.Phase.EXECUTION
                    && !contract.scope().included().contains(file)) {
                errors.add("PROPOSED_SCOPE_REQUIRES_NEW_APPROVAL: " + file.path());
            }
        }
        return List.copyOf(errors);
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.*;
import dev.dual.ledger.file.*;
import java.io.IOException;
import java.nio.file.*;
import java.util.*;

/** Human-approved source identity for evidence collection, shared by inline and queued execution. */
public final class EvidenceCollection {
    public static final String FAILURE = "EVIDENCE_COLLECTION_SOURCE_INVALID";
    private static final ObjectMapper MAPPER = new ObjectMapper().findAndRegisterModules();
    private EvidenceCollection() {}

    /** CLI/API already hold the workstream lock; ordinary decisions retain their existing semantics. */
    public static void resolveGate(WorkflowFileLedger ledger, WorkstreamPaths paths, WorkflowDefinition definition,
                                   String action, String note) throws IOException {
        if (!HumanGateActionSemantics.COLLECT_EVIDENCE.equals(action)) {
            ledger.resolveOpenGate(paths, definition, action, note);
            return;
        }
        if (note == null || note.isBlank()) throw new IOException("collection requires an explicit note");
        var baseline = captureBaseline(ledger, paths, definition, action);
        ledger.collectEvidence(paths, definition, note, baseline);
    }

    static EvidenceCollectionBaseline captureBaseline(WorkflowFileLedger ledger, WorkstreamPaths paths,
                                                       WorkflowDefinition definition, String action) throws IOException {
        var current = ledger.loadCurrent(paths);
        if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN || current.activeNodeInstanceIds().size() != 1
                ) throw new IOException("collection requires a waiting human gate");
        var node = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
        var gate = ledger.loadOpenGateForNode(paths, node.nodeInstanceId());
        if (gate == null || !HumanGateActionSemantics.allowedActions(definition.node(node.nodeDefinitionId()),
                String.valueOf(gate.result().get("source_outcome"))).contains(action))
            throw new IOException("collection is not available at this gate");
        var resolution = TaskContractProjectionVerifier.resolve(ledger, paths.workspaceRoot(), paths.workstreamId().value());
        var qualified = resolution.qualified().orElseThrow(() -> new IOException(
                "collection requires a qualified approved task contract: " + resolution.failure()));
        var included = qualified.contract().scope().included().stream().map(entry -> entry.path()).toList();
        var source = EvidenceCollectionSource.capture(paths.workspaceRoot(), included);
        var baseline = new EvidenceCollectionBaseline(node.nodeInstanceId(), qualified.contractRef(), qualified.sha256(),
                source.head(), source.indexSha256(), source.sha256(), source.paths());
        verifySource(paths.workspaceRoot(), baseline);
        return baseline;
    }

    @FunctionalInterface public interface Execution { NodeResult run() throws Exception; }

    /** Advisory projection only; execute() and publication validation own enforcement. */
    public static Optional<String> promptInstruction(WorkflowFileLedger ledger, Path root, String workstreamId, String nodeId) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        var refs = requiredReferences(ledger, root, workstreamId, nodeId);
        var collecting = ledger.inspect(paths, (scoped, files) ->
                scoped.loadNode(paths, nodeId).inputTransition().containsKey("evidence_collection_gate"));
        if (!collecting) return Optional.empty();
        return Optional.of("This occurrence collects evidence against a human-approved source baseline. "
                + "Do not modify product source, tests, dependencies, or Git state. "
                + "Write evidence only to the designated run artifacts. If verification needs a code change, "
                + "report the concrete must_fix or missing_evidence instead of implementing it."
                + (refs.isEmpty() ? "" : "\nExternal verification materials (operator-declared execution, not automatic proof of success):\n"
                + String.join("\n", refs) + "\nRead these exact files. Include each exact ref as a separate string in result.evidence. "
                + "Assess their relevance and sufficiency; missing or failed verification must remain incomplete/rejected. "
                + "Do not replace refs with summaries or treat a submission as approval."));
    }

    static List<String> requiredReferences(WorkflowFileLedger ledger, Path root, String workstreamId, String nodeId) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        if (!Files.exists(paths.workstreamJson()) && !Files.exists(paths.nodeJson(nodeId))) return List.of();
        return ledger.inspect(paths, (scoped, files) -> {
            if (!files.exists(paths.nodeJson(nodeId))) return List.of();
            var guard = openSnapshot(ledger, scoped, root, workstreamId, scoped.loadNode(paths, nodeId));
            return guard == null || guard.submission() == null ? List.of() : ExternalVerificationEvidence.refs(paths, guard.submission());
        });
    }

    static void verifyResult(WorkflowFileLedger ledger, Path root, String workstreamId, String nodeId, AgentResultEnvelope.AgentResult result) throws IOException {
        var refs = requiredReferences(ledger, root, workstreamId, nodeId);
        if (refs.isEmpty()) return;
        List<String> evidence = result instanceof AgentResultEnvelope.SelfTestResult self ? self.evidence()
                : result instanceof AgentResultEnvelope.AcceptanceReviewResult acceptance ? acceptance.evidence() : null;
        if ((result instanceof AgentResultEnvelope.SelfTestResult || result instanceof AgentResultEnvelope.AcceptanceReviewResult)
                && (evidence == null || !evidence.containsAll(refs)))
            throw new IOException("result.evidence must contain every exact bound material ref");
    }

    public static NodeResult execute(WorkflowFileLedger ledger, Path root, String workstreamId, NodeInstanceDocument node, Execution execution)
            throws Exception {
        Guard guard;
        try { guard = open(ledger, root, workstreamId, node); }
        catch (IOException | IllegalArgumentException invalid) { return AgentExecutionResultFacts.inputPreparationFailed(FAILURE, FAILURE, List.of(String.valueOf(invalid.getMessage()))); }
        if (guard == null) return execution.run();
        NodeResult result;
        try { result = execution.run(); }
        catch (Exception failure) {
            try { guard.verify(); }
            catch (IOException | IllegalArgumentException invalid) { failure.addSuppressed(invalid); }
            throw failure;
        }
        try { guard.verify(); }
        catch (IOException | IllegalArgumentException invalid) { return ArtifactContractValidator.evidenceFailureResult(result, invalid); }
        return result;
    }

    /** Recheck at sidecar publication too, including cold or direct validator calls. */
    static void verify(WorkflowFileLedger ledger, Path root, String workstreamId, String nodeId) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        if (!Files.exists(paths.workstreamJson()) && !Files.exists(paths.nodeJson(nodeId))) return;
        ledger.inspect(paths, (scoped, files) -> {
            if (files.exists(paths.nodeJson(nodeId))) openSnapshot(ledger, scoped, root, workstreamId, scoped.loadNode(paths, nodeId));
            return null;
        });
    }

    static Guard open(WorkflowFileLedger ledger, Path root, String workstreamId, NodeInstanceDocument node) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        return ledger.inspect(paths, (scoped, files) -> {
            var actual = scoped.loadNode(paths, node.nodeInstanceId());
            if (!actual.nodeDefinitionId().equals(node.nodeDefinitionId()) || !actual.iterationId().equals(node.iterationId())
                    || !actual.inputTransition().equals(node.inputTransition()) || !actual.inputRefs().equals(node.inputRefs()))
                throw new IOException("collection input identity changed before execution");
            return openSnapshot(ledger, scoped, root, workstreamId, actual);
        });
    }

    private static Guard openSnapshot(WorkflowFileLedger owner, WorkflowFileLedger scoped, Path root,
                                      String workstreamId, NodeInstanceDocument node) throws IOException {
        var transition = node.inputTransition();
        var id = transition.get("evidence_collection_gate");
        var sha = transition.get("evidence_collection_gate_sha256");
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        // A cold retry must not silently become ordinary self-test if its marker was removed.
        if (Files.isRegularFile(paths.eventsJsonl())) {
            try (var lines = Files.lines(paths.eventsJsonl())) {
                for (var iterator = lines.iterator(); iterator.hasNext();) {
                    var line = iterator.next();
                    if (line.isBlank()) continue;
                    var event = MAPPER.readTree(line);
                    if (!"node_routed".equals(event.path("event_type").asText())
                            || !node.nodeInstanceId().equals(event.path("payload").path("node_instance_id").asText())) continue;
                    var routed = event.path("payload").path("transition");
                    var routedId = routed.path("evidence_collection_gate").isMissingNode() ? null
                            : routed.path("evidence_collection_gate").asText();
                    var routedSha = routed.path("evidence_collection_gate_sha256").isMissingNode() ? null
                            : routed.path("evidence_collection_gate_sha256").asText();
                    if (!Objects.equals(id, routedId) || !Objects.equals(sha, routedSha))
                        throw new IOException("collection transition differs from its persisted route");
                }
            }
        }
        if (id == null && sha == null) return null;
        if (!(id instanceof String gateId) || !gateId.matches("[A-Za-z0-9._-]+")
                || !(sha instanceof String hash) || !hash.matches("[0-9a-f]{64}"))
            throw new IOException("invalid collection approval reference");
        var file = paths.nodeJson(gateId);
        requireCanonical(root, file);
        if (!hash.equals(TaskContractArtifactWriter.sha256(file))) throw new IOException("collection approval changed");
        var approval = MAPPER.readValue(file.toFile(), NodeInstanceDocument.class);
        if (!gateId.equals(approval.nodeInstanceId()) || approval.kind() != NodeKind.GATE
                || approval.status() != NodeStatus.COMPLETED
                || !("collect_evidence".equals(approval.result().get("human_action"))
                || "submit_evidence".equals(approval.result().get("human_action")))
                || !(approval.result().get("note") instanceof String note) || note.isBlank())
            throw new IOException("collection approval is not a completed human decision");
        var gateFile = paths.gateJson("gate-" + gateId);
        requireCanonical(root, gateFile);
        var gate = MAPPER.readValue(gateFile.toFile(), GateDocument.class);
        if (!"resolved".equals(gate.status()) || !gateId.equals(gate.nodeInstanceId())
                || !Objects.equals(approval.result().get("human_action"), gate.result().get("human_action"))
                || !Objects.equals(gate.result().get("note"), approval.result().get("note"))
                || !Objects.equals(gate.result().get("subject_input_refs"), approval.inputRefs()))
            throw new IOException("collection gate resolution is missing");
        var baseline = MAPPER.convertValue(approval.result().get("evidence_collection_baseline"), EvidenceCollectionBaseline.class);
        if (baseline == null || !gateId.equals(baseline.gateNodeInstanceId()))
            throw new IOException("collection source baseline is missing");
        var submission = MAPPER.convertValue(approval.result().get("external_evidence"), EvidenceSubmission.class);
        if ("submit_evidence".equals(approval.result().get("human_action")) != (submission != null)
                || (submission != null && !baseline.equals(submission.baseline())))
            throw new IOException("missing or inconsistent external material binding");
        var guard = new Guard(owner, root, paths, file, hash, gateFile, TaskContractArtifactWriter.sha256(gateFile),
                node.nodeInstanceId(), baseline, submission);
        guard.verifySnapshot(scoped);
        return guard;
    }

    record Guard(WorkflowFileLedger ledger, Path root, WorkstreamPaths paths, Path approvalFile, String approvalSha, Path gateFile,
                 String gateSha, String nodeId, EvidenceCollectionBaseline baseline, EvidenceSubmission submission) {
        void verify() throws IOException {
            ledger.inspect(paths, (scoped, files) -> { verifySnapshot(scoped); return null; });
        }
        private void verifySnapshot(WorkflowFileLedger scoped) throws IOException {
            requireCanonical(root, approvalFile);
            if (!approvalSha.equals(TaskContractArtifactWriter.sha256(approvalFile)))
                throw new IOException("collection approval changed during execution");
            requireCanonical(root, gateFile);
            if (!gateSha.equals(TaskContractArtifactWriter.sha256(gateFile)))
                throw new IOException("collection gate changed during execution");
            var node = scoped.loadNode(paths, nodeId);
            if (!baseline.gateNodeInstanceId().equals(node.inputTransition().get("evidence_collection_gate"))
                    || !approvalSha.equals(node.inputTransition().get("evidence_collection_gate_sha256")))
                throw new IOException("collection execution lost its approval binding");
            if (!baseline.contractRef().startsWith(".agent/workstreams/" + paths.workstreamId().value() + "/artifacts/contracts/"))
                throw new IOException("collection contract belongs to another workstream");
            verifySource(root, baseline);
            if (submission != null) {
                var manifest = ExternalVerificationEvidence.verify(paths, submission);
                var approval = MAPPER.readValue(approvalFile.toFile(), NodeInstanceDocument.class);
                if (!manifest.note().equals(approval.result().get("note"))) throw new IOException("material note mismatch");
            }
        }
    }

    static void verifySource(Path root, EvidenceCollectionBaseline baseline) throws IOException {
        var contract = root.resolve(baseline.contractRef());
        requireCanonical(root, contract);
        if (!baseline.contractSha256().equals(TaskContractArtifactWriter.sha256(contract)))
            throw new IOException("collection approved contract changed");
        var actual = EvidenceCollectionSource.capture(root, baseline.paths());
        if (!actual.head().equals(baseline.head()) || !actual.indexSha256().equals(baseline.indexSha256())
                || !actual.paths().equals(baseline.paths()) || !actual.sha256().equals(baseline.sourceSha256()))
            throw new IOException("product source differs from the human-approved collection baseline");
    }

    private static void requireCanonical(Path root, Path file) throws IOException {
        if (!file.toRealPath().equals(root.toRealPath().resolve(root.toAbsolutePath().normalize().relativize(file.toAbsolutePath().normalize()))))
            throw new IOException("noncanonical collection authority path");
    }

    private static NodeResult rejected(Exception invalid) {
        return new NodeResult(FAILURE, NodeStatus.FAILED, List.of(),
                Map.of("failure_code", FAILURE, "error", String.valueOf(invalid.getMessage())), invalid.getMessage());
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContractValidator;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

/** Raw worktree bytes, not Git's filtered blobs or the path-only inventory digest. */
public record EvidenceCollectionSource(String head, String indexSha256, String sha256, List<String> paths) {
    public static EvidenceCollectionSource capture(Path workspace, List<String> retainedPaths) throws IOException {
        var root = workspace.toRealPath();
        if (!root.equals(Path.of(GitTrackedPathInventory.command(root, "rev-parse", "--show-toplevel").trim()).toRealPath()))
            throw new IOException("collection workspace must be the Git root");
        var head = GitTrackedPathInventory.command(root, "rev-parse", "HEAD").trim();
        var index = GitTrackedPathInventory.commandBytes(root, "ls-files", "--stage", "-z", "--", ".", ":!.agent");
        var paths = new TreeSet<>(retainedPaths);
        paths.addAll(GitTrackedPathInventory.parseNulPaths(GitTrackedPathInventory.commandBytes(root,
                "ls-files", "--cached", "--others", "--exclude-standard", "-z", "--", ".", ":!.agent")));
        var digest = digest();
        for (var path : paths) {
            if (!TaskContractValidator.isCanonicalPath(path) || path.equals(".git") || path.startsWith(".git/")
                    || path.equals(".agent") || path.startsWith(".agent/"))
                throw new IOException("invalid collection source path: " + path);
            var file = root.resolve(path);
            for (var component = file; !component.equals(root); component = component.getParent()) {
                if (Files.isSymbolicLink(component)) throw new IOException("collection source symlink is unsupported: " + path);
            }
            update(digest, path);
            if (!Files.exists(file, LinkOption.NOFOLLOW_LINKS)) {
                update(digest, "absent");
            } else {
                if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS))
                    throw new IOException("collection source is not a regular file: " + path);
                update(digest, Files.isExecutable(file) ? "executable" : "file");
                var content = digest();
                try (var input = Files.newInputStream(file)) {
                    byte[] buffer = new byte[8192];
                    for (int count; (count = input.read(buffer)) != -1;) content.update(buffer, 0, count);
                }
                update(digest, HexFormat.of().formatHex(content.digest()));
            }
        }
        // Do not accept an inventory that changed while we were reading its files.
        if (!head.equals(GitTrackedPathInventory.command(root, "rev-parse", "HEAD").trim())
                || !Arrays.equals(index, GitTrackedPathInventory.commandBytes(root, "ls-files", "--stage", "-z", "--", ".", ":!.agent")))
            throw new IOException("repository identity changed during collection capture");
        return new EvidenceCollectionSource(head, HexFormat.of().formatHex(digest().digest(index)),
                HexFormat.of().formatHex(digest.digest()), List.copyOf(paths));
    }
    private static MessageDigest digest() {
        try { return MessageDigest.getInstance("SHA-256"); }
        catch (NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
    private static void update(MessageDigest digest, String text) {
        digest.update(text.getBytes(StandardCharsets.UTF_8));
        digest.update((byte) 0);
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Stream;

/**
 * Rebuildable evidence index for one workstream.
 *
 * The manifest is not the evidence source of truth. It points to ledger and
 * artifact files so context packages can reuse known facts without expanding
 * raw transcripts or re-discovering the repository from scratch.
 */
final class EvidenceManifest {
    static final String MANIFEST_REF_NAME = "memory/evidence-manifest.json";

    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private final String workstreamId;
    private final String updatedAt;
    private final List<EvidenceItem> items;

    EvidenceManifest(String workstreamId, String updatedAt, List<EvidenceItem> items) {
        this.workstreamId = workstreamId;
        this.updatedAt = updatedAt;
        this.items = List.copyOf(items);
    }

    static EvidenceManifest empty(String workstreamId) {
        return new EvidenceManifest(workstreamId, Instant.now().toString(), List.of());
    }

    static EvidenceManifest rebuild(dev.dual.ledger.file.WorkflowFileLedger ledger, Path workspaceRoot, Path workstreamDir, String workstreamId,
                                    List<String> routedRefs, ObjectMapper objectMapper) throws IOException {
        return rebuild(ledger, workspaceRoot, workstreamDir, workstreamId, routedRefs, objectMapper, Optional.empty());
    }

    static EvidenceManifest rebuild(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            Path workstreamDir,
            String workstreamId,
            List<String> routedRefs,
            ObjectMapper objectMapper,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        var items = new ArrayList<EvidenceItem>();
        addFixedArtifacts(workspaceRoot, workstreamDir, objectMapper, items, qualifiedContract);
        addRoutedAgentContracts(ledger, workspaceRoot, workstreamDir, workstreamId, routedRefs, objectMapper, items);
        addHumanDecisions(workspaceRoot, workstreamDir, objectMapper, items);
        items.sort(Comparator
                .comparing(EvidenceItem::stageId)
                .thenComparing(EvidenceItem::iterationId)
                .thenComparing(EvidenceItem::type)
                .thenComparing(EvidenceItem::sourceRef));
        return new EvidenceManifest(workstreamId, Instant.now().toString(), items);
    }

    Path write(Path workstreamDir, ObjectMapper objectMapper) throws IOException {
        var memoryDir = workstreamDir.resolve("memory");
        Files.createDirectories(memoryDir);
        var path = memoryDir.resolve("evidence-manifest.json");
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(path.toFile(), toMap());
        return path;
    }

    List<EvidenceItem> items() {
        return items;
    }

    List<String> sourceRefs() {
        return items.stream()
                .map(EvidenceItem::sourceRef)
                .filter(ref -> !ref.isBlank())
                .distinct()
                .toList();
    }

    List<EvidenceItem> stageHandoffs() {
        return items.stream()
                .filter(item -> "stage_handoff".equals(item.type()))
                .toList();
    }

    List<EvidenceItem> reviewItems() {
        return items.stream()
                .filter(item -> List.of(
                        "task_contract",
                        "contract_resolution",
                        "agent_output_contract",
                        "design_result",
                        "self_test_report",
                        "acceptance_review",
                        "git_evidence",
                        "human_decision"
                ).contains(item.type()))
                .toList();
    }

    Map<String, Object> toMap() {
        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("workstreamId", workstreamId);
        document.put("updatedAt", updatedAt);
        document.put("items", items.stream().map(EvidenceItem::toMap).toList());
        return document;
    }

    private static void addFixedArtifacts(
            Path workspaceRoot,
            Path workstreamDir,
            ObjectMapper objectMapper,
            List<EvidenceItem> items,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        if (qualifiedContract.isPresent()) {
            items.add(itemFromJson(
                    workspaceRoot, workstreamDir, workspaceRoot.resolve(qualifiedContract.get().contractRef()), "task_contract",
                    qualifiedContract.get().document()));
            items.add(itemFromJson(
                    workspaceRoot,
                    workstreamDir,
                    workspaceRoot.resolve(qualifiedContract.get().resolutionRef()),
                    "requirement_resolution",
                    qualifiedContract.get().resolutionDocument()));
        }
        addJsonArtifact(workspaceRoot, workstreamDir, objectMapper, items,
                workstreamDir.resolve("artifacts/next-stage/handoff.json"), "stage_handoff");
        addJsonArtifact(workspaceRoot, workstreamDir, objectMapper, items,
                workstreamDir.resolve("artifacts/failure-classification.json"), "failure_classification");

        var gitEvidence = workstreamDir.resolve("artifacts/git-evidence/git-evidence.json");
        if (Files.isRegularFile(gitEvidence)) {
            addJsonArtifact(workspaceRoot, workstreamDir, objectMapper, items, gitEvidence, "git_evidence");
        }
    }

    private static void addRoutedAgentContracts(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Path workspaceRoot,
            Path workstreamDir,
            String workstreamId,
            List<String> routedRefs,
            ObjectMapper objectMapper,
            List<EvidenceItem> items
    ) {
        for (var entry : AgentEvidenceIndex.fromRefs(
                ledger, workspaceRoot, workstreamId, routedRefs, objectMapper).recent(Integer.MAX_VALUE)) {
            var document = entry.document();
            var type = switch (document.sourceArtifactType()) {
                case "design_result" -> "design_result";
                case "self_test_report" -> "self_test_report";
                case "acceptance_review" -> "acceptance_review";
                case "stage_handoff" -> "stage_handoff";
                default -> "agent_output_contract";
            };
            var sourceRef = workspaceRef(workspaceRoot, entry.path());
            var claims = new ArrayList<String>();
            claims.addAll(document.completedWork());
            claims.addAll(document.importantDecisions());
            if (!document.decision().isBlank()) {
                claims.add("Decision: " + document.decision());
            }
            var risks = new ArrayList<String>();
            risks.addAll(document.openRisks());
            risks.addAll(document.mustFix());
            risks.addAll(document.missingEvidence());
            items.add(new EvidenceItem(
                    stableId(type, sourceRef),
                    type,
                    inferStageFromNode(document.nodeId()),
                    "",
                    document.nodeInstanceId(),
                    "",
                    sourceRef,
                    document.summary().isBlank() ? type : document.summary(),
                    List.copyOf(claims),
                    document.changedFiles(),
                    List.copyOf(risks),
                    "available"
            ));
        }
    }

    private static void addHumanDecisions(Path workspaceRoot, Path workstreamDir, ObjectMapper objectMapper,
                                          List<EvidenceItem> items) throws IOException {
        var nodesDir = workstreamDir.resolve("nodes");
        if (!Files.exists(nodesDir)) {
            return;
        }
        try (Stream<Path> paths = Files.list(nodesDir)) {
            var nodes = paths
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted()
                    .toList();
            for (var node : nodes) {
                var json = readJson(objectMapper, node).orElse(Map.of());
                var result = mapValue(json.get("result"));
                if (!result.containsKey("human_action")) {
                    continue;
                }
                items.add(new EvidenceItem(
                        stableId("human_decision", workspaceRef(workspaceRoot, node)),
                        "human_decision",
                        stageId(json),
                        text(json.get("iterationId")),
                        text(json.get("nodeInstanceId")),
                        "",
                        workspaceRef(workspaceRoot, node),
                        "Human action: " + text(result.get("human_action")),
                        List.of(text(result.get("note"))).stream().filter(s -> !s.isBlank()).toList(),
                        List.of(),
                        List.of(),
                        "available"
                ));
            }
        }
    }

    private static void addJsonArtifact(Path workspaceRoot, Path workstreamDir, ObjectMapper objectMapper,
                                        List<EvidenceItem> items, Path path, String type) throws IOException {
        if (!Files.isRegularFile(path)) {
            return;
        }
        var json = readJson(objectMapper, path).orElse(Map.of());
        items.add(itemFromJson(workspaceRoot, workstreamDir, path, type, json));
    }

    private static EvidenceItem itemFromJson(Path workspaceRoot, Path workstreamDir, Path path,
                                             String type, Map<String, Object> json) {
        var sourceRef = workspaceRef(workspaceRoot, path);
        var claims = claims(json);
        var files = files(json);
        var risks = risks(json);
        return new EvidenceItem(
                stableId(type, sourceRef),
                type,
                firstNonBlank(stageId(json), inferStageFromPath(workstreamDir, path)),
                text(json.get("iteration_id")).isBlank() ? text(json.get("iterationId")) : text(json.get("iteration_id")),
                text(json.get("node_instance_id")).isBlank() ? text(json.get("nodeInstanceId")) : text(json.get("node_instance_id")),
                text(json.get("node_execution_id")).isBlank() ? text(json.get("nodeExecutionId")) : text(json.get("node_execution_id")),
                sourceRef,
                summary(json, type),
                claims,
                files,
                risks,
                "available"
        );
    }

    private static String summary(Map<String, Object> json, String type) {
        for (var key : List.of("summary", "objective", "reasoning", "verification_summary", "verificationSummary")) {
            var value = text(json.get(key));
            if (!value.isBlank()) {
                return value;
            }
        }
        var decision = firstNonBlank(text(json.get("decision")), text(json.get("status")), text(json.get("lifecycle_status")));
        if (!decision.isBlank()) {
            return type + ": " + decision;
        }
        return type;
    }

    private static List<String> claims(Map<String, Object> json) {
        var result = new ArrayList<String>();
        for (var key : List.of("completedWork", "completed_work", "importantDecisions", "important_decisions", "acceptance_criteria")) {
            result.addAll(listOfText(json.get(key)));
        }
        var decision = firstNonBlank(text(json.get("decision")), text(json.get("status")), text(json.get("lifecycle_status")));
        if (!decision.isBlank()) {
            result.add("Decision: " + decision);
        }
        return List.copyOf(result);
    }

    private static List<String> files(Map<String, Object> json) {
        var result = new ArrayList<String>();
        for (var key : List.of("changedFiles", "changed_files", "touched_files", "files")) {
            result.addAll(listOfText(json.get(key)));
        }
        return List.copyOf(result);
    }

    private static List<String> risks(Map<String, Object> json) {
        var result = new ArrayList<String>();
        for (var key : List.of("openRisks", "open_risks", "must_fix", "missing_evidence", "risk_areas")) {
            result.addAll(listOfText(json.get(key)));
        }
        var failure = mapValue(json.get("failure"));
        var category = firstNonBlank(text(failure.get("category_hint")), text(failure.get("category")));
        if (!category.isBlank()) {
            result.add("Failure category: " + category);
        }
        return List.copyOf(result);
    }

    private static Optional<Map<String, Object>> readJson(ObjectMapper objectMapper, Path path) throws IOException {
        if (!Files.isRegularFile(path)) {
            return Optional.empty();
        }
        try {
            return Optional.of(objectMapper.readValue(path.toFile(), MAP_TYPE));
        } catch (IOException | RuntimeException e) {
            var fallback = new LinkedHashMap<String, Object>();
            fallback.put("summary", "Invalid JSON artifact: " + path.getFileName());
            fallback.put("raw_size", Files.isRegularFile(path)
                    ? Files.readString(path, StandardCharsets.UTF_8).length()
                    : 0);
            return Optional.of(fallback);
        }
    }

    private static String stageId(Map<String, Object> json) {
        return firstNonBlank(
                text(json.get("stage_id")),
                text(json.get("stageId")),
                inferStageFromNode(text(json.get("node_id"))),
                inferStageFromNode(text(json.get("nodeDefinitionId")))
        );
    }

    private static String inferStageFromPath(Path workstreamDir, Path path) {
        var ref = workstreamDir.relativize(path).toString();
        if (ref.contains("git-evidence")) return "implementation";
        if (ref.contains("next-stage")) return "handoff";
        if (ref.contains("failure-classification")) return "acceptance";
        return "";
    }

    private static String inferStageFromNode(String nodeId) {
        if (nodeId == null || nodeId.isBlank()) {
            return "";
        }
        var dot = nodeId.indexOf('.');
        return dot > 0 ? nodeId.substring(0, dot) : "";
    }

    private static String stableId(String type, String sourceRef) {
        return type + ":" + Integer.toHexString(sourceRef.hashCode());
    }

    private static String workspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize())
                .toString();
    }

    private static Map<String, Object> mapValue(Object value) {
        if (!(value instanceof Map<?, ?> map)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (var entry : map.entrySet()) {
            if (entry.getKey() instanceof String key) {
                copy.put(key, entry.getValue());
            }
        }
        return copy;
    }

    private static List<String> listOfText(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        return items.stream()
                .map(EvidenceManifest::text)
                .filter(item -> !item.isBlank())
                .toList();
    }

    private static String firstNonBlank(String... values) {
        for (var value : values) {
            if (value != null && !value.isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    record EvidenceItem(
            String id,
            String type,
            String stageId,
            String iterationId,
            String nodeInstanceId,
            String nodeExecutionId,
            String sourceRef,
            String summary,
            List<String> claims,
            List<String> files,
            List<String> riskTags,
            String status
    ) {
        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("id", id);
            map.put("type", type);
            map.put("stageId", stageId);
            map.put("iterationId", iterationId);
            map.put("nodeInstanceId", nodeInstanceId);
            map.put("nodeExecutionId", nodeExecutionId);
            map.put("sourceRef", sourceRef);
            map.put("summary", summary);
            map.put("claims", claims);
            map.put("files", files);
            map.put("riskTags", riskTags);
            map.put("status", status);
            return map;
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.contract.TaskContract;
import dev.dual.ledger.file.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

/** D07: an operator decision authorizes a new attempt, never rewrites an unknown effect as not executed. */
public final class ExecutionRecoveryAdjudication {
    private static final ObjectMapper JSON = new AtomicJsonWriter().objectMapper();
    private ExecutionRecoveryAdjudication() {}

    public record Request(String schema, @JsonProperty("request_id") String requestId,
            String workstream, String node, String task, String execution, String attempt,
            @JsonProperty("frozen_identity") Map<String, String> frozenIdentity,
            @JsonProperty("input_epoch") long inputEpoch,
            @JsonProperty("last_event") String lastEvent,
            @JsonProperty("node_sha256") String nodeSha256,
            TaskContract.Reference prepared,
            String disposition, @JsonProperty("evidence_refs") List<TaskContract.Reference> evidenceRefs,
            @JsonProperty("accept_duplicate_effect_risk") boolean acceptDuplicateEffectRisk,
            @JsonProperty("operator_note") String operatorNote) {}

    /** Read-only proposal: fields are bound, but neither a disposition nor risk acceptance is preselected. */
    public static Map<String, Object> describe(WorkflowFileLedger ledger, WorkstreamPaths paths) throws IOException {
        return ledger.inspect(paths, (scoped, files) -> {
            var current = scoped.loadCurrent(paths);
            if (current.activeNodeInstanceIds().size() != 1) return Map.of();
            var node = scoped.loadNode(paths, current.activeNodeInstanceIds().getFirst());
            if (!"UNKNOWN".equals(node.result().get("external_effect"))) return Map.of();
            var execution = scoped.latestNodeExecution(paths, node).orElseThrow(() -> new IOException("unknown effect without execution"));
            var prepared = AgentRunCommitProtocol.boundPreparation(paths, execution);
            var binding = JSON.readTree(prepared.path().toFile()).path("binding");
            var contract = originalContract(scoped, paths, node, binding);
            var request = new Request("dual.execution-recovery.v1", "", paths.workstreamId().value(), node.nodeInstanceId(),
                    execution.agentTaskId(), execution.nodeExecutionId(), binding.path("run").path("runId").asText(),
                    ledger.frozenRuntimeIdentity(), contract == null ? 0 : contract.epoch(), current.lastEventId(), hash(files.readBytes(paths.nodeJson(node.nodeInstanceId()))),
                    new TaskContract.Reference(prepared.reference().get("ref"), prepared.reference().get("sha256")), "", List.of(), false, "");
            return Map.of("decision_template", request, "executor_owns_invocation", AgentRunCommitProtocol.executorOwnsInvocation(paths, execution),
                    "external_effect", "UNKNOWN", "risk", "A new attempt can repeat effects; a successful stop does not prove they never happened.");
        });
    }

    public static void apply(WorkflowFileLedger ledger, WorkstreamPaths paths, Request request) throws IOException {
        require(request != null && "dual.execution-recovery.v1".equals(request.schema())
                && request.requestId() != null && request.requestId().matches("[A-Za-z0-9._-]{1,80}")
                && request.execution() != null && request.execution().matches("[A-Za-z0-9_-]{1,100}")
                && Set.of("AUTHORIZE_NEW_ATTEMPT", "ABORT", "ADOPT_VERIFIED_RESULT").contains(request.disposition())
                && request.operatorNote() != null && !request.operatorNote().isBlank(), "invalid recovery decision");
        require(paths.workstreamId().value().equals(request.workstream())
                && ledger.frozenRuntimeIdentity().equals(request.frozenIdentity()), "wrong workstream or frozen identity");
        var requestJson = JSON.readTree(JSON.writeValueAsBytes(request));
        try (var write = ledger.writeSession(paths, "adjudicate unknown execution", request.requestId())) {
            var scoped = write.ledger();
            var execution = write.files().read(paths.nodeExecutionJson(request.execution()), NodeExecutionDocument.class);
            var previous = JSON.valueToTree(execution.result()).path("recovery_decisions").path(request.requestId());
            if (!previous.isMissingNode()) {
                require(previous.path("request").equals(requestJson), "request id was used with different content");
                return;
            }
            var current = scoped.loadCurrent(paths);
            require(current.lastEventId().equals(request.lastEvent())
                    && current.activeNodeInstanceIds().equals(List.of(request.node())), "recovery observation is stale");
            var node = scoped.loadNode(paths, request.node());
            require(execution.nodeInstanceId().equals(node.nodeInstanceId()) && execution.agentTaskId().equals(request.task())
                    && node.latestExecutionId().equals(execution.nodeExecutionId())
                    && hash(write.files().readBytes(paths.nodeJson(node.nodeInstanceId()))).equals(request.nodeSha256()),
                    "node, task or execution identity changed");
            var prepared = AgentRunCommitProtocol.boundPreparation(paths, execution);
            require(request.prepared() != null && prepared.reference().get("ref").equals(request.prepared().ref())
                    && prepared.reference().get("sha256").equals(request.prepared().sha256()), "prepared reference mismatch");
            var input = JSON.readTree(prepared.path().toFile());
            var binding = input.path("binding");
            require(binding.path("run").path("runId").asText().equals(request.attempt()), "attempt mismatch");
            require(!AgentRunCommitProtocol.executorOwnsInvocation(paths, execution), "original executor is still active");
            var contractRef = binding.path("contract_ref").asText();
            var contractSha = binding.path("contract_sha256").asText();
            var contract = originalContract(scoped, paths, node, binding);
            require((contract == null ? 0 : contract.epoch()) == request.inputEpoch(), "input epoch mismatch");
            if (request.disposition().equals("ADOPT_VERIFIED_RESULT")) {
                var result = AgentRunCommitProtocol.readCompletion(paths, execution);
                var completion = new TaskContract.Reference(String.valueOf(result.result().get("completion_ref")),
                        String.valueOf(result.result().get("completion_sha256")));
                require(request.evidenceRefs() != null && request.evidenceRefs().equals(List.of(completion)),
                        "adoption requires the original fixed completion, not a pasted result");
                require(!request.acceptDuplicateEffectRisk(), "adoption is not a new-attempt authorization");
                var decision = JSON.convertValue(request, new TypeReference<LinkedHashMap<String, Object>>() {});
                decision.put("request", requestJson);
                decision.put("executor_stopped", true);
                decision.put("executor_check", "original invocation is quiescent; fixed R03 process/result verified; no new dispatch");
                decision.put("completion_ref", completion.ref()); decision.put("completion_sha256", completion.sha256());
                scoped.adjudicateUnknownExecution(paths, node.nodeInstanceId(), execution.nodeExecutionId(), decision, result);
                dev.dual.runtime.WorkflowRuntime.emitDomainEvents(scoped, paths, node.nodeDefinitionId(), node.handlerType(), node.nodeInstanceId(), result);
                write.commit();
                return;
            }
            require(request.evidenceRefs() != null && !request.evidenceRefs().isEmpty(), "native stop evidence is required");
            long lastProductiveIntent = 0;
            try (var entries = Files.list(prepared.path().getParent())) {
                for (var entry : entries.filter(p -> p.getFileName().toString().startsWith(execution.nodeExecutionId() + "-command-")
                        && p.getFileName().toString().endsWith("-intent.json")).toList()) {
                    var intent = JSON.readTree(entry.toFile());
                    if (!intent.path("details").path("cleanup").asBoolean(false))
                        lastProductiveIntent = Math.max(lastProductiveIntent, intent.path("ordinal").asLong());
                }
            }
            boolean stopped = false;
            for (var ref : request.evidenceRefs()) {
                var bytes = verified(paths.workspaceRoot(), ref);
                var path = paths.workspaceRoot().resolve(ref.ref()).toAbsolutePath().normalize();
                require(path.getParent().equals(prepared.path().getParent())
                        && path.getFileName().toString().startsWith(execution.nodeExecutionId() + "-command-"), "foreign command evidence");
                var evidence = JSON.readTree(bytes);
                var details = evidence.path("details");
                require(evidence.path("schema").asText().equals("dual.run.command.v1")
                        && evidence.path("kind").asText().equals("command_result")
                        && evidence.path("prepared").equals(JSON.valueToTree(prepared.reference()))
                        && details.path("session").asText().equals(binding.path("run").path("session").asText()),
                        "stop evidence identity mismatch");
                var commandId = details.path("command_id").asText();
                require(commandId.matches("[a-f0-9-]{36}") && path.getFileName().toString().equals(
                        execution.nodeExecutionId() + "-command-" + commandId + "-result.json"), "stop receipt path mismatch");
                var intentPath = prepared.path().getParent().resolve(execution.nodeExecutionId() + "-command-" + commandId + "-intent.json");
                var intent = JSON.readTree(intentPath.toFile());
                var withoutObservation = ((com.fasterxml.jackson.databind.node.ObjectNode) details).deepCopy();
                withoutObservation.remove("observation");
                require(intent.path("schema").equals(evidence.path("schema"))
                        && "command_intent".equals(intent.path("kind").asText())
                        && intent.path("prepared").equals(evidence.path("prepared"))
                        && intent.path("ordinal").isIntegralNumber() && intent.path("ordinal").asLong() > 0
                        && intent.path("ordinal").equals(evidence.path("ordinal"))
                        && intent.path("details").equals(withoutObservation), "stop receipt does not match its original command");
                stopped |= evidence.path("ordinal").asLong() > lastProductiveIntent
                        && details.path("cleanup").asBoolean(false)
                        && Set.of("session_cancel", "session_close").contains(details.path("purpose").asText())
                        && details.path("observation").path("success").asBoolean(false)
                        && !details.path("observation").path("timed_out").asBoolean(true);
            }
            require(stopped, "native client has not acknowledged a stop; parent PID absence is insufficient");
            if (request.disposition().equals("AUTHORIZE_NEW_ATTEMPT")) {
                require(request.acceptDuplicateEffectRisk(), "explicit duplicate-effect risk acceptance is required");
                if (contract != null) {
                    var resolution = TaskContractProjectionVerifier.resolve(scoped, paths.workspaceRoot(), request.workstream(), contract.phase());
                    var qualified = resolution.qualified().orElseThrow(() -> new IOException("current execution is not qualified"));
                    require(qualified.contractRef().equals(contractRef) && qualified.sha256().equals(contractSha),
                            "scope or permission contract changed; new approval is required");
                }
            }
            var decision = JSON.convertValue(request, new TypeReference<LinkedHashMap<String, Object>>() {});
            decision.put("request", requestJson);
            decision.put("executor_stopped", true);
            decision.put("executor_check", "invocation released or original PID/start absent; native stop acknowledged");
            decision.put("external_effect", "UNKNOWN");
            scoped.adjudicateUnknownExecution(paths, node.nodeInstanceId(), execution.nodeExecutionId(), decision);
            write.commit();
        }
    }

    private static TaskContract originalContract(WorkflowFileLedger ledger, WorkstreamPaths paths,
            NodeInstanceDocument node, com.fasterxml.jackson.databind.JsonNode binding) throws IOException {
        var ref = binding.path("contract_ref").asText();
        var sha = binding.path("contract_sha256").asText();
        var definition = ledger.loadDefinition(paths).node(node.nodeDefinitionId());
        if (ref.isBlank() && sha.isBlank()) {
            require(!TaskContractProjectionVerifier.requiresContract(definition), "required prepared contract binding is missing");
            return null; // Pre-GOAL exploration has no contract epoch; the exact R01 and claim remain required.
        }
        require(!ref.isBlank() && !sha.isBlank(), "incomplete prepared contract binding");
        var contract = JSON.readValue(verified(paths.workspaceRoot(), new TaskContract.Reference(ref, sha)), TaskContract.class);
        require(contract.phase() == TaskContractProjectionVerifier.requiredPhase(definition), "prepared contract phase mismatch");
        return contract;
    }

    private static byte[] verified(Path root, TaskContract.Reference ref) throws IOException {
        var base = root.toAbsolutePath().normalize();
        var path = base.resolve(ref.ref()).normalize();
        require(!Path.of(ref.ref()).isAbsolute() && path.startsWith(base) && path.toRealPath().startsWith(base.toRealPath()), "evidence escapes workspace");
        var bytes = Files.readAllBytes(path);
        require(hash(bytes).equals(ref.sha256()), "evidence bytes changed");
        return bytes;
    }
    private static String hash(byte[] bytes) { return TaskContractArtifactWriter.sha256(bytes); }
    private static void require(boolean accepted, String message) throws IOException { if (!accepted) throw new IOException(message); }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.*;
import dev.dual.ledger.file.*;
import java.io.IOException;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;

/** Explicit operator material ingestion. No execution, approval inference, or directory discovery. */
public final class ExternalVerificationEvidence {
    private static final ObjectMapper JSON = new ObjectMapper().findAndRegisterModules();
    private static final int FILE_LIMIT = 8 * 1024 * 1024;
    private static final int TOTAL_LIMIT = 32 * 1024 * 1024;
    public record Reference(String ref, String sha256) {}
    public record Preparation(EvidenceCollectionBaseline baseline, Instant recordedAt) {}
    public record Declaration(String command, String environment, Instant startedAt, Instant finishedAt,
                              int exitCode, String purpose) {
        public Declaration {
            if (blank(command) || blank(environment) || blank(purpose) || startedAt == null || finishedAt == null
                    || finishedAt.isBefore(startedAt)) throw new IllegalArgumentException("complete execution declaration required");
        }
    }
    public record Material(String ref, String sha256, long size, String name) {}
    public record Manifest(String requestId, Reference preparation, EvidenceCollectionBaseline baseline,
                           Declaration declaredExecution, String note, List<Material> materials) {}
    private ExternalVerificationEvidence() {}

    public static Reference prepare(WorkflowFileLedger ledger, WorkstreamPaths paths) throws IOException {
        var preparation = ledger.inspect(paths, (scoped, files) -> new Preparation(
                EvidenceCollection.captureBaseline(scoped, paths, scoped.loadDefinition(paths), "submit_evidence"), Instant.now()));
        // Material production grants no authority. Submission rechecks the fixed baseline under L05.
        return save(paths, "preparations", JSON.writeValueAsBytes(preparation), ".json");
    }

    public static EvidenceSubmission submit(WorkflowFileLedger ledger, WorkstreamPaths paths, Reference preparation,
                                             String requestId, List<Path> files, Declaration execution, String note) throws IOException {
        if (blank(note) || requestId == null || !requestId.matches("[A-Za-z0-9._-]{1,80}")
                || files == null || files.isEmpty() || files.size() > 32 || execution == null)
            throw new IOException("submission requires request id, note, declaration, and 1-32 explicit files");
        var prepared = readPreparation(paths, preparation);
        if (execution.startedAt().isBefore(prepared.recordedAt()))
            throw new IOException("declared execution precedes preparation; timestamps are operator declarations, not machine proof");
        EvidenceCollection.verifySource(paths.workspaceRoot(), prepared.baseline());
        var materials = new ArrayList<Material>();
        long total = 0;
        for (var file : files) {
            var source = file.toAbsolutePath().normalize();
            if (!source.toRealPath().equals(source) || !Files.isRegularFile(source, LinkOption.NOFOLLOW_LINKS))
                throw new IOException("material must be a canonical regular file: " + source);
            byte[] bytes;
            try (var input = Files.newInputStream(source, LinkOption.NOFOLLOW_LINKS)) { bytes = input.readNBytes(FILE_LIMIT + 1); }
            total += bytes.length;
            if (bytes.length > FILE_LIMIT || total > TOTAL_LIMIT) throw new IOException("material size limit exceeded");
            var name = source.getFileName().toString();
            var dot = name.lastIndexOf('.');
            var extension = dot >= 0 ? name.substring(dot) : ".bin";
            if (!extension.matches("\\.[A-Za-z0-9]{1,10}")) extension = ".bin";
            var stored = save(paths, "files", bytes, extension);
            materials.add(new Material(stored.ref(), stored.sha256(), bytes.length, source.getFileName().toString()));
        }
        var manifest = new Manifest(requestId, preparation, prepared.baseline(), execution, note, List.copyOf(materials));
        var reference = save(paths, "submissions", JSON.writeValueAsBytes(manifest), ".json");
        var submission = new EvidenceSubmission(requestId, preparation.ref(), preparation.sha256(),
                reference.ref(), reference.sha256(), prepared.baseline());
        try (var write = ledger.writeSession(paths, "submit evidence", requestId)) {
            var scoped = write.ledger();
            verify(paths, submission);
            var definition = scoped.loadDefinition(paths);
            var gateNode = scoped.loadNode(paths, prepared.baseline().gateNodeInstanceId());
            // Only a fully routed prior decision is idempotent. Partial gate writes never authorize another route.
            if (gateNode.status() == NodeStatus.COMPLETED) {
                var prior = JSON.convertValue(gateNode.result().get("external_evidence"), EvidenceSubmission.class);
                if (!submission.equals(prior) || !"submit_evidence".equals(gateNode.result().get("human_action")))
                    throw new IOException("gate already resolved with different evidence");
                var gate = JSON.readValue(paths.gateJson("gate-" + gateNode.nodeInstanceId()).toFile(), GateDocument.class);
                if (!"resolved".equals(gate.status()) || !gateNode.nodeInstanceId().equals(gate.nodeInstanceId())
                        || !"submit_evidence".equals(gate.result().get("human_action"))
                        || !note.equals(gate.result().get("note")) || !note.equals(gateNode.result().get("note")))
                    throw new IOException("inconsistent prior evidence decision");
                var routed = false;
                try (var lines = Files.lines(paths.eventsJsonl())) {
                    for (var iterator = lines.iterator(); iterator.hasNext();) {
                        var line = iterator.next();
                        if (line.isBlank()) continue;
                        var event = JSON.readTree(line);
                        if ("node_routed".equals(event.path("event_type").asText())
                                && gateNode.nodeInstanceId().equals(event.path("payload").path("transition")
                                .path("evidence_collection_gate").asText())) routed = true;
                    }
                }
                if (!routed) throw new IOException("partial evidence decision; no automatic recovery");
                return prior;
            }
            var currentBaseline = EvidenceCollection.captureBaseline(scoped, paths, definition, "submit_evidence");
            if (!prepared.baseline().equals(currentBaseline)) throw new IOException("preparation no longer belongs to current source/gate");
            scoped.submitEvidence(paths, definition, note, submission);
            write.commit();
            return submission;
        }
    }

    static Manifest verify(WorkstreamPaths paths, EvidenceSubmission submission) throws IOException {
        var preparation = new Reference(submission.preparationRef(), submission.preparationSha256());
        var prepared = readPreparation(paths, preparation);
        var manifest = JSON.readValue(read(paths, new Reference(submission.manifestRef(), submission.manifestSha256())), Manifest.class);
        if (!Objects.equals(manifest.preparation(), preparation) || !Objects.equals(manifest.baseline(), submission.baseline())
                || !Objects.equals(prepared.baseline(), submission.baseline()) || !submission.requestId().equals(manifest.requestId())
                || blank(manifest.note()) || manifest.declaredExecution() == null
                || manifest.declaredExecution().startedAt().isBefore(prepared.recordedAt())
                || manifest.materials() == null || manifest.materials().isEmpty() || manifest.materials().size() > 32)
            throw new IOException("external material manifest identity mismatch");
        long total = 0;
        for (var material : manifest.materials()) {
            var bytes = read(paths, new Reference(material.ref(), material.sha256()));
            total += bytes.length;
            if (bytes.length != material.size() || bytes.length > FILE_LIMIT || total > TOTAL_LIMIT)
                throw new IOException("external material size mismatch");
        }
        EvidenceCollection.verifySource(paths.workspaceRoot(), submission.baseline());
        return manifest;
    }

    static List<String> refs(WorkstreamPaths paths, EvidenceSubmission submission) throws IOException {
        var manifest = verify(paths, submission);
        var refs = new LinkedHashSet<String>();
        refs.add(submission.manifestRef());
        for (var material : manifest.materials()) refs.add(material.ref());
        return List.copyOf(refs);
    }

    private static Preparation readPreparation(WorkstreamPaths paths, Reference ref) throws IOException {
        var preparation = JSON.readValue(read(paths, ref), Preparation.class);
        if (preparation.baseline() == null || preparation.recordedAt() == null)
            throw new IOException("invalid evidence preparation");
        return preparation;
    }

    private static byte[] read(WorkstreamPaths paths, Reference reference) throws IOException {
        var prefix = ".agent/workstreams/" + paths.workstreamId().value() + "/artifacts/verification/";
        if (reference == null || reference.ref() == null || !reference.ref().startsWith(prefix)
                || !dev.dual.core.contract.TaskContractValidator.isCanonicalPath(reference.ref().substring(prefix.length()))
                || reference.sha256() == null || !reference.sha256().matches("[0-9a-f]{64}"))
            throw new IOException("invalid material reference");
        var file = paths.workspaceRoot().resolve(reference.ref());
        if (!file.toRealPath().equals(paths.workspaceRoot().toRealPath().resolve(reference.ref()))
                || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) throw new IOException("noncanonical material reference");
        byte[] bytes;
        try (var input = Files.newInputStream(file, LinkOption.NOFOLLOW_LINKS)) { bytes = input.readNBytes(FILE_LIMIT + 1); }
        if (bytes.length > FILE_LIMIT || !sha(bytes).equals(reference.sha256())) throw new IOException("material SHA mismatch");
        return bytes;
    }

    private static Reference save(WorkstreamPaths paths, String kind, byte[] bytes, String extension) throws IOException {
        var directory = paths.workstreamDir().resolve("artifacts/verification/" + kind);
        var root = paths.workspaceRoot().toRealPath();
        var cursor = root;
        for (var segment : paths.workspaceRoot().relativize(directory)) {
            cursor = cursor.resolve(segment);
            if (!Files.exists(cursor, LinkOption.NOFOLLOW_LINKS)) Files.createDirectory(cursor);
            if (!Files.isDirectory(cursor, LinkOption.NOFOLLOW_LINKS) || !cursor.toRealPath().equals(cursor))
                throw new IOException("noncanonical material storage");
        }
        var hash = sha(bytes);
        var target = directory.resolve(hash + extension);
        if (!Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
            var temporary = Files.createTempFile(directory, ".evidence-", ".tmp");
            try {
                Files.write(temporary, bytes);
                Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE);
            } finally { Files.deleteIfExists(temporary); }
        }
        var ref = new Reference(paths.workspaceRoot().relativize(target).toString().replace('\\', '/'), hash);
        read(paths, ref);
        return ref;
    }

    private static String sha(byte[] bytes) {
        try { return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes)); }
        catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
    private static boolean blank(String value) { return value == null || value.isBlank(); }
}

package dev.dual.runtime.handler;

import dev.dual.core.arbitration.FailureCategory;
import dev.dual.core.arbitration.FailureClassification;

import java.time.Instant;
import java.util.List;
import java.util.Objects;

/** Consumes the canonical category only after shared acceptance semantic validation. */
public final class FailureArbiter {
    public FailureClassification classify(FailureCategory category, List<String> evidence) {
        Objects.requireNonNull(category, "validated acceptance category is required");
        var action = switch (category) {
            case CONTRACT_GAP, CONTRACT_AMBIGUITY -> "Revise the proposal and obtain new approvals before compiling";
            case IMPLEMENTATION_BUG -> "Repair within the approved contract, then run self-test";
            case VERIFICATION_INSUFFICIENT -> "Collect existing verification evidence in self-test";
            case CONTEXT_INSUFFICIENT, TOOL_LIMITATION ->
                    "Obtain human disposition of the missing prerequisites: collect evidence or explicitly authorize repair";
            case REVIEW_NOISE -> "Re-run acceptance review";
        };
        return new FailureClassification(category, "Validated explicit acceptance category: " + category,
                action, "deterministic", Instant.now(), 0, "REJECT", List.copyOf(evidence));
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.arbitration.FailureClassification;
import dev.dual.core.arbitration.FailureCategory;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * TaskHandler that classifies acceptance review failures using FailureArbiter.
 * Type: "acceptance.failure_classify"
 *
 * Reads TaskContract and ledger-routed acceptance evidence,
 * runs FailureArbiter, and writes failure-classification.json.
 * Produces compound outcome strings: REJECT_{CATEGORY}.
 */
public final class FailureClassifyHandler implements TaskHandler {

    private final FailureArbiter arbiter = new FailureArbiter();
    private final ObjectMapper objectMapper = new ObjectMapper().registerModule(new JavaTimeModule());

    @Override
    public String type() {
        return "acceptance.failure_classify";
    }

    @Override
    public NodeResult execute(TaskContext context) throws IOException {
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent/workstreams").resolve(context.workstreamId());

        TaskContractProjectionVerifier.QualifiedTaskContract qualified = null;
        if (AgentRunGovernanceContext.requiresApprovedTaskContract(context)) {
            var resolution = TaskContractProjectionVerifier.resolve(context.ledger(), context.workspaceRoot(), context.workstreamId(), TaskContractProjectionVerifier.requiredPhase(context.definition()));
            if (resolution.failure() != null || resolution.qualified().isEmpty()) {
                var failure = resolution.failure() == null
                        ? TaskContractProjectionVerifier.Failure.of(
                                "APPROVAL_BINDING_MISSING", "failure classification requires an approved task contract")
                        : resolution.failure();
                return qualificationFailure(failure);
            }
            qualified = resolution.qualified().orElseThrow();
        } else {
            return qualificationFailure(TaskContractProjectionVerifier.Failure.of(
                    "CONTRACT_PHASE_MISSING", "failure classification requires an explicit EXECUTION phase"));
        }

        var evidenceRead = AgentEvidenceIndex.latestDecisionFromRefs(context.ledger(), context.workspaceRoot(),
                context.workstreamId(), context.instance().inputRefs(), objectMapper);
        if (evidenceRead.entry() == null) {
            var missing = evidenceRead.missing();
            return failedEvidence(
                    missing ? "MISSING_CONTRACT_SIDECAR" : "INVALID_CONTRACT_SIDECAR",
                    missing
                            ? "No acceptance contract sidecar found in failure-classification input refs."
                            : evidenceRead.message(),
                    context,
                    evidenceRead
            );
        }

        var reviewMetadata = evidenceRead.entry().document();
        if (!"acceptance_review".equals(reviewMetadata.sourceArtifactType())) {
            return new NodeResult("ACCEPTANCE_CLASSIFICATION_INVALID", NodeStatus.FAILED, List.of(),
                    Map.of("reason", "ACCEPTANCE_CLASSIFICATION_INVALID"), "An acceptance_review sidecar is required");
        }
        var semanticViolation = AgentContractSemantics.validateOutputContract(reviewMetadata);
        if (semanticViolation.isPresent()) {
            var invalid = semanticViolation.get();
            return new NodeResult(invalid.errorCode(), NodeStatus.FAILED, List.of(),
                    Map.of("reason", invalid.errorCode(), "error", invalid.message()), invalid.message());
        }
        var reviewDecision = reviewMetadata.decision();
        if (!"REJECT".equals(reviewDecision)) {
            return failedDecision(reviewDecision, context, evidenceRead.entry().path());
        }
        var stageOutcome = reviewMetadata.canonicalStageOutcome().isBlank()
                ? StageOutcome.fromDecision(reviewDecision).name()
                : reviewMetadata.canonicalStageOutcome();
        var failure = reviewMetadata.failure();

        final FailureCategory category;
        try {
            category = FailureCategory.valueOf(failure.categoryHint());
        } catch (IllegalArgumentException invalid) {
            return new NodeResult("ACCEPTANCE_CLASSIFICATION_INVALID", NodeStatus.FAILED, List.of(),
                    Map.of("reason", "ACCEPTANCE_CLASSIFICATION_INVALID"), "Canonical acceptance category is required");
        }
        var supportingEvidence = new ArrayList<String>();
        supportingEvidence.addAll(failure.contractGaps());
        supportingEvidence.addAll(reviewMetadata.mustFix());
        supportingEvidence.addAll(failure.outOfScopeFiles());
        supportingEvidence.addAll(failure.missingTests());
        supportingEvidence.addAll(reviewMetadata.missingEvidence());
        supportingEvidence.addAll(failure.contextGaps());
        if (!failure.reason().isBlank()) supportingEvidence.add(failure.reason());
        var classification = arbiter.classify(category, supportingEvidence);
        Map<String, Object> baseline = Map.of();
        if (category == FailureCategory.CONTRACT_GAP || category == FailureCategory.CONTRACT_AMBIGUITY) {
            try {
                if (qualified == null) throw new IOException("contract repair requires a qualified contract");
                baseline = new TaskContractRevisionContextResolver(context.ledger()).captureAcceptanceReworkBaseline(
                        context.workspaceRoot(), context.workstreamId(), qualified, evidenceRead.entry());
            } catch (IOException invalid) {
                return new NodeResult("ACCEPTANCE_REWORK_BASELINE_INVALID", NodeStatus.FAILED, List.of(),
                        Map.of("reason", "ACCEPTANCE_REWORK_BASELINE_INVALID", "error", invalid.getMessage()),
                        invalid.getMessage());
            }
        }

        var artifactsDir = workstreamDir.resolve("artifacts");
        Files.createDirectories(artifactsDir);
        var classificationPath = artifactsDir.resolve("failure-classification.json");
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(classificationPath.toFile(), classification);

        var outcome = "REJECT_" + classification.category().name();

        var classificationRef = ".agent/workstreams/" + context.workstreamId()
                + "/artifacts/failure-classification.json";
        var outputRefs = new ArrayList<String>();
        outputRefs.add(context.workspaceRoot().toAbsolutePath().normalize()
                .relativize(evidenceRead.entry().path()).toString());
        outputRefs.add(classificationRef);
        var result = new LinkedHashMap<String, Object>();
        result.putAll(baseline);
        result.put("category", classification.category().name());
        result.put("reasoning", classification.reasoning());
        result.put("suggested_action", classification.suggestedAction());
        result.put("matched_rule", classification.matchedRule());
        result.put("review_decision", reviewDecision);
        result.put("stage_outcome", stageOutcome);
        result.put("classification_ref", classificationRef);

        var candidateRef = writeCalibrationCandidateIfNeeded(
                context, workstreamDir, classification, classificationRef, stageOutcome);
        if (candidateRef != null) {
            outputRefs.add(candidateRef);
            result.put("calibration_candidate_ref", candidateRef);
        }

        var summaryRef = writeCurrentFailureSummary(
                context, workstreamDir, classification, classificationRef, candidateRef, stageOutcome);
        outputRefs.add(summaryRef);
        result.put("failure_summary_ref", summaryRef);

        return NodeResult.completed(outcome, outputRefs, result);
    }

    private NodeResult qualificationFailure(TaskContractProjectionVerifier.Failure failure) {
        return new NodeResult(
                TaskContractProjectionVerifier.FAILURE_OUTCOME,
                NodeStatus.FAILED,
                List.of(),
                Map.of(
                        "failure_code", TaskContractProjectionVerifier.FAILURE_OUTCOME,
                        "reason", failure.reason(),
                        "error", failure.message()),
                failure.message());
    }

    private NodeResult failedEvidence(String outcome, String message, TaskContext context,
                                      AgentEvidenceIndex.DecisionRead read) {
        var parseError = read.errorCode().isBlank()
                ? Map.of()
                : Map.of(
                    "code", read.errorCode(),
                    "message", read.message(),
                    "path", read.path()
                );
        return new NodeResult(outcome, NodeStatus.FAILED, List.of(), Map.of(
                "reason", outcome,
                "message", message,
                "input_refs", context.instance().inputRefs(),
                "parse_error", parseError
        ), message);
    }

    private NodeResult failedDecision(String decision, TaskContext context, Path sidecarPath) {
        var outcome = "ACCEPTANCE_CLASSIFICATION_NOT_REQUIRED";
        var message = "Failure classification requires a REJECT acceptance decision, but received: " + decision;
        return new NodeResult(outcome, NodeStatus.FAILED, List.of(), Map.of(
                "reason", outcome,
                "message", message,
                "review_decision", decision,
                "input_refs", context.instance().inputRefs(),
                "acceptance_sidecar", context.workspaceRoot().toAbsolutePath().normalize()
                        .relativize(sidecarPath).toString()
        ), message);
    }


    private String writeCalibrationCandidateIfNeeded(
            TaskContext context,
            Path workstreamDir,
            FailureClassification classification,
            String classificationRef,
            String stageOutcome
    ) throws IOException {
        var updateType = proposedUpdateType(classification.category());
        if (updateType == null) {
            return null;
        }

        var candidateId = context.instance().nodeInstanceId() + "-"
                + classification.category().name().toLowerCase().replace('_', '-');
        var candidatesDir = workstreamDir.resolve("calibration").resolve("candidates");
        Files.createDirectories(candidatesDir);

        var jsonRef = ".agent/workstreams/" + context.workstreamId()
                + "/calibration/candidates/" + candidateId + ".json";
        var mdRef = ".agent/workstreams/" + context.workstreamId()
                + "/calibration/candidates/" + candidateId + ".md";

        var candidate = new LinkedHashMap<String, Object>();
        candidate.put("schemaVersion", 1);
        candidate.put("candidateId", candidateId);
        candidate.put("sourceWorkstreamId", context.workstreamId());
        candidate.put("sourceNodeId", context.instance().nodeDefinitionId());
        candidate.put("failureCategory", classification.category().name());
        candidate.put("reviewDecision", classification.reviewDecision());
        candidate.put("stageOutcome", stageOutcome);
        candidate.put("matchedRule", classification.matchedRule());
        candidate.put("proposedUpdateType", updateType);
        candidate.put("reasoning", classification.reasoning());
        candidate.put("suggestedAction", classification.suggestedAction());
        candidate.put("evidenceRefs", List.of(classificationRef));
        candidate.put("status", "DRAFT");

        objectMapper.writerWithDefaultPrettyPrinter()
                .writeValue(candidatesDir.resolve(candidateId + ".json").toFile(), candidate);
        Files.writeString(candidatesDir.resolve(candidateId + ".md"),
                renderCalibrationCandidateMarkdown(candidate, mdRef), StandardCharsets.UTF_8);
        return jsonRef;
    }

    private String proposedUpdateType(FailureCategory category) {
        return switch (category) {
            case CONTRACT_GAP, CONTRACT_AMBIGUITY -> "CONTRACT_TEMPLATE";
            case CONTEXT_INSUFFICIENT -> "CONTEXT_RULE";
            case IMPLEMENTATION_BUG -> "REGRESSION_TEST";
            case VERIFICATION_INSUFFICIENT -> null;
            case TOOL_LIMITATION, REVIEW_NOISE -> null;
        };
    }

    private String renderCalibrationCandidateMarkdown(Map<String, Object> candidate, String mdRef) {
        return """
                # Calibration Candidate

                - Candidate: %s
                - Status: %s
                - Failure Category: %s
                - Proposed Update Type: %s
                - Review Decision: %s
                - Stage Outcome: %s
                - Source Node: %s

                ## Reasoning

                %s

                ## Suggested Action

                %s

                ## Artifact

                %s
                """.formatted(
                candidate.get("candidateId"),
                candidate.get("status"),
                candidate.get("failureCategory"),
                candidate.get("proposedUpdateType"),
                candidate.get("reviewDecision"),
                candidate.get("stageOutcome"),
                candidate.get("sourceNodeId"),
                candidate.get("reasoning"),
                candidate.get("suggestedAction"),
                mdRef
        );
    }

    private String writeCurrentFailureSummary(
            TaskContext context,
            Path workstreamDir,
            FailureClassification classification,
            String classificationRef,
            String candidateRef,
            String stageOutcome
    ) throws IOException {
        var recoveryDir = workstreamDir.resolve("recovery");
        Files.createDirectories(recoveryDir);
        var summaryRef = ".agent/workstreams/" + context.workstreamId()
                + "/recovery/current-failure.md";
        var candidateLine = candidateRef == null ? "- Calibration Candidate: N/A\n"
                : "- Calibration Candidate: " + candidateRef + "\n";
        var content = """
                # Current Failure

                - Node: %s
                - Decision: %s
                - Stage Outcome: %s
                - Category: %s
                - Matched Rule: %d
                - Classification: %s
                %s
                ## Reasoning

                %s

                ## Suggested Action

                %s
                """.formatted(
                context.instance().nodeDefinitionId(),
                classification.reviewDecision(),
                stageOutcome,
                classification.category().name(),
                classification.matchedRule(),
                classificationRef,
                candidateLine,
                classification.reasoning(),
                classification.suggestedAction()
        );
        Files.writeString(recoveryDir.resolve("current-failure.md"), content, StandardCharsets.UTF_8);
        return summaryRef;
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeInstance;
import dev.dual.core.workflow.NodeResult;

import java.nio.file.Path;

public interface GateHandler {
    String type();

    NodeResult openOrInspect(GateContext context) throws Exception;

    record GateContext(
            Path workspaceRoot,
            String workstreamId,
            NodeDefinition definition,
            NodeInstance instance,
            String sourceOutcome,
            dev.dual.ledger.file.WorkflowFileLedger ledger
    ) {
        public GateContext {
            if (ledger == null) throw new IllegalArgumentException("assembled ledger is required");
            if (workspaceRoot == null) {
                throw new IllegalArgumentException("workspaceRoot is required");
            }
            if (workstreamId == null || workstreamId.isBlank()) {
                throw new IllegalArgumentException("workstreamId is required");
            }
            if (definition == null) {
                throw new IllegalArgumentException("definition is required");
            }
            if (instance == null) {
                throw new IllegalArgumentException("instance is required");
            }
            if (sourceOutcome == null || sourceOutcome.isBlank()) {
                throw new IllegalArgumentException("sourceOutcome is required");
            }
        }
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContractValidator;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;

/** Authoritative tracked-path snapshot for contract discovery; it does not infer task relevance. */
record GitTrackedPathInventory(String head, String sha256, List<String> paths) {
    GitTrackedPathInventory {
        head = text(head);
        sha256 = text(sha256);
        paths = paths == null ? List.of() : List.copyOf(paths);
    }

    static GitTrackedPathInventory capture(Path workspaceRoot) throws IOException {
        var root = workspaceRoot.toRealPath();
        var gitRoot = text(command(root, "rev-parse", "--show-toplevel"));
        if (!root.equals(Path.of(gitRoot).toRealPath())) {
            throw new IOException("effective workspace is not the Git worktree root: " + root);
        }
        var head = text(command(root, "rev-parse", "HEAD"));
        var raw = commandBytes(root, "ls-files", "-z", "--cached", "--", ".", ":!.agent");
        var paths = parseNulPaths(raw).stream()
                .map(GitTrackedPathInventory::normalize)
                .filter(TaskContractValidator::isCanonicalPath)
                .distinct()
                .sorted()
                .toList();
        return new GitTrackedPathInventory(head, digest(paths), paths);
    }

    static GitTrackedPathInventory empty() {
        return new GitTrackedPathInventory("", "", List.of());
    }

    static String command(Path root, String... args) throws IOException {
        return new String(commandBytes(root, args), StandardCharsets.UTF_8);
    }

    static byte[] commandBytes(Path root, String... args) throws IOException {
        var command = new ArrayList<String>();
        command.add("git");
        command.addAll(List.of(args));
        var process = new ProcessBuilder(command)
                .directory(root.toFile())
                .start();
        var stdout = process.getInputStream().readAllBytes();
        var stderr = new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8).trim();
        try {
            var exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new IOException("git " + String.join(" ", args) + " failed: " + stderr);
            }
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            throw new IOException("git inventory capture interrupted", interrupted);
        }
        return stdout;
    }

    static List<String> parseNulPaths(byte[] raw) throws IOException {
        var paths = new ArrayList<String>();
        var start = 0;
        for (var index = 0; index < raw.length; index++) {
            if (raw[index] != 0) {
                continue;
            }
            if (index > start) {
                paths.add(new String(raw, start, index - start, StandardCharsets.UTF_8));
            }
            start = index + 1;
        }
        if (start != raw.length) {
            throw new IOException("git tracked-path inventory has malformed NUL framing");
        }
        return List.copyOf(paths);
    }

    private static String digest(List<String> paths) throws IOException {
        try {
            var digest = MessageDigest.getInstance("SHA-256");
            for (var path : paths) {
                digest.update(path.getBytes(StandardCharsets.UTF_8));
                digest.update((byte) 0);
            }
            return HexFormat.of().formatHex(digest.digest());
        } catch (NoSuchAlgorithmException impossible) {
            throw new IOException("SHA-256 is unavailable", impossible);
        }
    }

    private static String normalize(String value) {
        var normalized = text(value).replace('\\', '/');
        while (normalized.startsWith("./")) {
            normalized = normalized.substring(2);
        }
        return normalized;
    }

    private static String text(String value) {
        return value == null ? "" : value.trim();
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.workflow.NodeKind;

import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Function;

public final class HandlerRegistry {
    private final Map<String, TaskHandler> taskHandlers;
    private final Map<String, DecisionHandler> decisionHandlers;
    private final Map<String, GateHandler> gateHandlers;

    public HandlerRegistry(
            List<TaskHandler> taskHandlers,
            List<DecisionHandler> decisionHandlers,
            List<GateHandler> gateHandlers
    ) {
        this.taskHandlers = index(taskHandlers == null ? List.of() : taskHandlers, TaskHandler::type);
        this.decisionHandlers = index(decisionHandlers == null ? List.of() : decisionHandlers, DecisionHandler::type);
        this.gateHandlers = index(gateHandlers == null ? List.of() : gateHandlers, GateHandler::type);
    }

    public Object resolve(NodeKind kind, String type) {
        if (kind == null) {
            throw new IllegalArgumentException("kind is required");
        }
        return switch (kind) {
            case TASK -> task(type);
            case DECISION -> decision(type);
            case GATE -> gate(type);
        };
    }

    public TaskHandler task(String type) {
        var handler = taskHandlers.get(requiredType(type));
        if (handler == null) {
            throw new IllegalArgumentException("missing handler: " + type);
        }
        return handler;
    }

    public DecisionHandler decision(String type) {
        var handler = decisionHandlers.get(requiredType(type));
        if (handler == null) {
            throw new IllegalArgumentException("missing handler: " + type);
        }
        return handler;
    }

    public GateHandler gate(String type) {
        var handler = gateHandlers.get(requiredType(type));
        if (handler == null) {
            throw new IllegalArgumentException("missing handler: " + type);
        }
        return handler;
    }

    private static String requiredType(String type) {
        if (type == null || type.isBlank()) {
            throw new IllegalArgumentException("handler type is required");
        }
        return type;
    }

    private static <T> Map<String, T> index(List<T> handlers, Function<T, String> typeExtractor) {
        var indexed = new LinkedHashMap<String, T>();
        for (T handler : handlers) {
            if (handler == null) {
                throw new IllegalArgumentException("handler is required");
            }
            var type = requiredType(typeExtractor.apply(handler));
            if (indexed.containsKey(type)) {
                throw new IllegalArgumentException("duplicate handler: " + type);
            }
            indexed.put(type, handler);
        }
        return Map.copyOf(indexed);
    }
}

package dev.dual.runtime.handler;

import java.util.Map;

public final class HumanGateSemantics {
    private HumanGateSemantics() {
    }

    public static String purposeForDefinitionId(String nodeDefinitionId) {
        return switch (nodeDefinitionId) {
            case "gate.human_requirement_review" -> "requirement";
            case "gate.contract_review" -> "contract";
            case "gate.human_design_approval" -> "design";
            case "gate.human_plan_approval" -> "plan";
            case "gate.human_acceptance" -> "acceptance";
            case "gate.human_next_stage_approval" -> "next_stage";
            default -> "general";
        };
    }

    public static boolean terminalGate(String nodeDefinitionId) {
        return "gate.human_next_stage_approval".equals(nodeDefinitionId);
    }

    public static String purpose(Map<String, Object> config, String nodeDefinitionId) {
        var configured = config.get("gate_purpose");
        if (configured instanceof String text && !text.isBlank()) {
            return text;
        }
        return purposeForDefinitionId(nodeDefinitionId);
    }

    public static boolean terminal(Map<String, Object> config, String nodeDefinitionId) {
        var configured = config.get("terminal_gate");
        if (configured instanceof Boolean value) {
            return value;
        }
        return terminalGate(nodeDefinitionId);
    }

    public static boolean requiresOperatorDecision(
            Map<String, Object> config,
            String nodeDefinitionId,
            String sourceOutcome
    ) {
        if ("design".equals(purpose(config, nodeDefinitionId))) {
            return true;
        }
        return "BLOCKED".equals(sourceOutcome) || "NEEDS_REVISION".equals(sourceOutcome);
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.HumanGateActionSemantics;
import dev.dual.ledger.file.DeliveryCandidateWriter;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkstreamPaths;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class HumanReviewGateHandler implements GateHandler {
    private final ObjectMapper objectMapper = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .enable(SerializationFeature.INDENT_OUTPUT);

    @Override
    public String type() {
        return "human.review";
    }

    @Override
    public NodeResult openOrInspect(GateContext context) throws Exception {
        var authored = authoredGate(context);
        var decision = latestAgentDecision(context, authored);
        var subject = latestReviewSubject(context, authored);
        assertBlockedSourceMatchesReview(context, decision);
        assertChangeScopeViolationSource(context);
        var contractRevision = contractRevision(context);
        var contractView = contractView(context);
        var allowedActions = HumanGateActionSemantics.allowedActions(context.definition(), context.sourceOutcome());
        var packetRef = reviewPacketRef(context, ".md");
        var packetJsonRef = reviewPacketRef(context, ".json");
        writeReviewPacket(context, allowedActions, packetRef, packetJsonRef, contractView, authored, decision, subject,
                contractRevision);

        return NodeResult.waiting("open", Map.of(
                "allowed_actions", allowedActions,
                "review_packet", packetRef,
                "review_packet_json", packetJsonRef
        ));
    }

    private void assertBlockedSourceMatchesReview(GateContext context, AgentDecisionSummary review) {
        if (!"BLOCKED".equals(context.sourceOutcome())) {
            return;
        }
        var decision = review.decision();
        if (!"BLOCKED".equals(decision) && !matchesRevisionLimitEscalation(context, decision)) {
            throw new IllegalStateException(
                    "BLOCKED gate source does not match the validated reviewer decision");
        }
    }

    private boolean matchesRevisionLimitEscalation(GateContext context, String decision) {
        var result = context.instance().result();
        if (!"revision_limit_reached".equals(text(result.get("reason")))
                || decision.isBlank()
                || !decision.equals(text(result.get("revision_limit_original_outcome")))) {
            return false;
        }
        var maxRevisions = integralValue(result.get("max_revisions"));
        var currentRevisionCount = integralValue(result.get("current_revision_count"));
        return maxRevisions >= 0 && currentRevisionCount >= maxRevisions;
    }

    private void assertChangeScopeViolationSource(GateContext context) {
        if (!"CHANGE_SCOPE_VIOLATION".equals(context.sourceOutcome())) {
            return;
        }
        changeScopeEvaluationSummary(context);
    }

    private long integralValue(Object value) {
        if (!(value instanceof Number number)) {
            return -1;
        }
        var asDouble = number.doubleValue();
        var asLong = number.longValue();
        return Double.isFinite(asDouble) && asDouble == asLong ? asLong : -1;
    }

    private String reviewPacketRef(GateContext context, String extension) {
        return ".agent/workstreams/" + context.workstreamId()
                + "/reviews/" + context.instance().nodeInstanceId() + extension;
    }

    private void writeReviewPacket(
            GateContext context,
            List<String> allowedActions,
            String packetRef,
            String packetJsonRef,
            GateContractView contractView,
            AuthoredStageLineageResolver.GateView authored,
            AgentDecisionSummary decision,
            Map<String, Object> subject,
            Map<String, Object> contractRevision
    ) throws Exception {
        var packetPath = context.workspaceRoot().resolve(packetRef);
        var packetJsonPath = context.workspaceRoot().resolve(packetJsonRef);
        Files.createDirectories(packetPath.getParent());

        var packet = new LinkedHashMap<String, Object>();
        packet.put("schemaVersion", 1);
        packet.put("workstreamId", context.workstreamId());
        packet.put("gateNodeInstanceId", context.instance().nodeInstanceId());
        packet.put("gateNodeDefinitionId", context.instance().nodeDefinitionId());
        packet.put("stageId", context.instance().stageId());
        packet.put("iterationId", context.instance().iterationId());
        packet.put("sourceOutcome", context.sourceOutcome());
        packet.put("runtimeDisposition", runtimeDisposition(context));
        packet.put("actionRequests", context.instance().result().getOrDefault("action_requests", List.of()));
        packet.put("allowedActions", allowedActions);
        if (allowedActions.contains("submit_evidence")) packet.put("externalEvidenceInstructions",
                "CLI only: review prepare-evidence before verification, then review submit-evidence with preparation ref/SHA, explicit files and execution declaration. Submission continues to self-test; it is not acceptance.");
        packet.put("inputRefs", context.instance().inputRefs());
        packet.put("inputArtifacts", inputArtifactSummaries(context));
        packet.put("reviewPacketPath", packetRef);
        packet.put("taskContract", taskContractSummary(context, contractView));
        packet.put("requirementResolution", requirementResolutionSummary(context, contractView));
        packet.put("latestAgentDecision", decision.toReviewPacketMap());
        packet.put("reviewSubject", subject);
        if (!contractRevision.isEmpty()) packet.put("contractRevision", contractRevision);
        if (authored != null) packet.put("authoredStage", authored.projection());
        packet.put("gitEvidence", gitEvidenceSummary(context));
        packet.put("delivery", deliverySummary(context));
        packet.put("operatorGuidance", operatorGuidance(context, allowedActions, decision));
        packet.put("createdAt", Instant.now().toString());

        objectMapper.writeValue(packetJsonPath.toFile(), packet);
        Files.writeString(packetPath, renderMarkdown(context, allowedActions, contractView, authored, decision, subject,
                contractRevision), StandardCharsets.UTF_8);
    }

    private String renderMarkdown(
            GateContext context,
            List<String> allowedActions,
            GateContractView contractView,
            AuthoredStageLineageResolver.GateView authored,
            AgentDecisionSummary decision,
            Map<String, Object> subject,
            Map<String, Object> contractRevision
    ) throws Exception {
        var builder = new StringBuilder();
        builder.append("# Human Review Packet\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Gate: ").append(context.instance().nodeDefinitionId()).append("\n");
        builder.append("- Gate Instance: ").append(context.instance().nodeInstanceId()).append("\n");
        builder.append("- Stage: ").append(context.instance().stageId()).append("\n");
        builder.append("- Iteration: ").append(context.instance().iterationId()).append("\n");
        builder.append("- Source Outcome: ").append(context.sourceOutcome()).append("\n");
        var runtimeDisposition = runtimeDisposition(context);
        if (!runtimeDisposition.isEmpty()) {
            builder.append("- Runtime Disposition: ").append(runtimeDisposition).append("\n");
        }
        builder.append("- Allowed Actions: ").append(String.join(", ", allowedActions)).append("\n\n");
        if (allowedActions.contains("submit_evidence")) builder.append(
                "External evidence: use `review prepare-evidence` before testing unchanged source, then `review submit-evidence --help`. "
                + "CLI-only ingestion; submitted materials must still pass self-test and acceptance.\n\n");

        appendOperatorGuidance(builder, context, allowedActions, decision);

        builder.append("## Review Focus\n\n");
        builder.append("- Read the complete referenced design and review sidecars before approving; the packet summary is not a substitute.\n");
        builder.append("- Use `approve` only when the current gate is good enough to continue.\n");
        builder.append("- Use `revise` when the agent should address concrete feedback first.\n\n");

        appendReviewSummary(builder, context, contractView, decision);
        appendTaskContract(builder, context, contractView);
        appendRequirementResolution(builder, context, contractView);
        appendLatestAgentDecision(builder, decision);
        if (authored != null) {
            builder.append("## Authored Candidate And Revision History\n\n")
                    .append("Historical obligations remain active until approval. Responses are claims, not verified closure. ")
                    .append("New must-fix items were raised after this candidate and enter its next revision.\n\n")
                    .append("```json\n").append(objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(authored.projection()))
                    .append("\n```\n\n");
        }
        if (authored == null) appendReviewSubject(builder, subject);
        builder.append(ContextBuildPackageHandler.renderContractRevision(contractRevision));
        appendGitEvidence(builder, context);
        appendDelivery(builder, context);

        appendInputArtifacts(builder, context);
        return builder.toString();
    }

    private void appendInputArtifacts(StringBuilder builder, GateContext context) {
        builder.append("## Input Artifacts\n\n");
        var artifacts = inputArtifactSummaries(context);
        if (artifacts.isEmpty()) {
            builder.append("No input artifacts were attached to this gate.\n");
            return;
        }
        builder.append("Raw agent logs are not embedded here by default. Use the paths below when deeper debugging is needed.\n\n");
        for (var artifact : artifacts) {
            builder.append("### ").append(text(artifact.get("ref"))).append("\n\n");
            appendField(builder, "Status", text(artifact.get("status")));
            appendField(builder, "Kind", text(artifact.get("kind")));
            appendField(builder, "Sidecar", text(artifact.get("sidecar")));
            appendField(builder, "Decision", text(artifact.get("decision")));
            appendField(builder, "Summary", text(artifact.get("summary")));
            appendList(builder, "Must Fix", artifact.get("mustFix"));
            appendList(builder, "Open Risks", artifact.get("openRisks"));
            appendField(builder, "Raw Artifact", text(artifact.get("ref")));
            builder.append("\n");
        }
    }

    private void appendOperatorGuidance(StringBuilder builder, GateContext context, List<String> allowedActions,
                                       AgentDecisionSummary decision) {
        var guidance = operatorGuidance(context, allowedActions, decision);
        if (guidance.isEmpty()) {
            return;
        }
        builder.append("## Operator Guidance\n\n");
        appendField(builder, "Recommended Action", text(guidance.get("recommendedAction")));
        appendField(builder, "Reason", text(guidance.get("reason")));
        appendList(builder, "Suggested Checks", guidance.get("suggestedChecks"));
        builder.append("\n");
    }

    private void appendReviewSummary(
            StringBuilder builder,
            GateContext context,
            GateContractView contractView,
            AgentDecisionSummary decision
    ) {
        builder.append("## Review Summary\n\n");
        var contract = taskContractSummary(context, contractView);
        appendField(builder, "Objective", text(contract.get("objective")));
        appendField(builder, "Stage Outcome", decision.stageOutcome());
        appendField(builder, "Latest Decision", decision.decision());
        appendField(builder, "Latest Summary", decision.summary());
        appendField(builder, "Blocking", Boolean.toString(decision.blocking()));
        appendList(builder, "Must Fix", decision.mustFix());
        appendList(builder, "Missing Evidence", decision.missingEvidence());
        appendList(builder, "Open Risks", decision.openRisks());
        builder.append("\n");
    }

    private Map<String, Object> runtimeDisposition(GateContext context) {
        if (!"revision_limit_reached".equals(text(context.instance().result().get("reason")))) {
            return Map.of();
        }
        var result = new LinkedHashMap<String, Object>();
        result.put("reason", "revision_limit_reached");
        result.put("originalOutcome", text(context.instance().result().get("revision_limit_original_outcome")));
        result.put("maxRevisions", context.instance().result().get("max_revisions"));
        result.put("currentRevisionCount", context.instance().result().get("current_revision_count"));
        return Map.copyOf(result);
    }

    private void appendTaskContract(
            StringBuilder builder,
            GateContext context,
            GateContractView contractView
    ) {
        var contract = taskContractSummary(context, contractView);
        if (contract.isEmpty()) {
            return;
        }
        builder.append("## Task Contract\n\n");
        appendField(builder, "Objective", text(contract.get("objective")));
        appendField(builder, "Status", text(contract.get("status")));
        appendList(builder, "Included Scope", contract.get("includedScope"));
        appendList(builder, "Excluded Scope", contract.get("excludedScope"));
        appendList(builder, "Acceptance Criteria", contract.get("acceptanceCriteria"));
        appendList(builder, "Test Requirements", contract.get("testRequirements"));
        appendList(builder, "Constraints", contract.get("constraints"));
        appendList(builder, "Nonessential Operation Declarations", contract.get("nonessentialOperationDeclarations"));
        builder.append("\n");
    }

    private void appendRequirementResolution(
            StringBuilder builder,
            GateContext context,
            GateContractView contractView
    ) {
        var resolution = requirementResolutionSummary(context, contractView);
        if (resolution.isEmpty()) {
            return;
        }
        builder.append("## Requirement Resolution\n\n");
        appendField(builder, "Decision", text(resolution.get("decision")));
        appendField(builder, "Approved By", text(resolution.get("approvedBy")));
        appendField(builder, "Gate Ref", text(resolution.get("gateRef")));
        appendList(builder, "Resolved Questions", resolution.get("resolvedQuestions"));
        appendList(builder, "Assumptions", resolution.get("assumptions"));
        appendList(builder, "Accepted Risks", resolution.get("acceptedRisks"));
        builder.append("\n");
    }

    private void appendLatestAgentDecision(StringBuilder builder, AgentDecisionSummary decision) {
        if (decision.isEmpty()) {
            return;
        }
        builder.append("## Latest Agent Decision\n\n");
        appendField(builder, "Node", decision.nodeId());
        appendField(builder, "Stage Outcome", decision.stageOutcome());
        appendField(builder, "Decision", decision.decision());
        appendField(builder, "Summary", decision.summary());
        appendField(builder, "Blocking", Boolean.toString(decision.blocking()));
        appendList(builder, "Must Fix", decision.mustFix());
        appendList(builder, "Missing Evidence", decision.missingEvidence());
        appendList(builder, "Open Risks", decision.openRisks());
        appendList(builder, "Changed Files", decision.changedFiles());
        appendField(builder, "Verification", decision.verificationSummary());
        appendField(builder, "Evidence State", decision.evidenceState().toMap().toString());
        appendField(builder, "Contract Sidecar", decision.sidecarPath());
        builder.append("\n");
    }

    private void appendGitEvidence(StringBuilder builder, GateContext context) {
        var evidence = gitEvidenceSummary(context);
        if (evidence.isEmpty()) {
            return;
        }
        builder.append("## Git Evidence\n\n");
        if (evidence.get("changeScopeEvaluation") instanceof Map<?, ?> scope) {
            appendField(builder, "Scope Evaluation", text(scope.get("ref")));
            appendField(builder, "SHA256", text(scope.get("sha256")));
            appendPreformatted(builder, "Scope Violations", text(scope.get("violations")));
            builder.append("Scope revision requests do not approve these paths. The revised contract must pass both approval gates.\n\n");
        }
        appendList(builder, "Changed Files", evidence.get("changedFiles"));
        appendPreformatted(builder, "Diff Stat", text(evidence.get("diffStat")));
        appendPreformatted(builder, "Status", text(evidence.get("statusShort")));
        builder.append("\n");
    }

    private void appendDelivery(StringBuilder builder, GateContext context) {
        var delivery = deliverySummary(context);
        if (delivery.isEmpty()) {
            return;
        }
        builder.append("## Delivery Artifacts\n\n");
        appendField(builder, "Candidate", text(delivery.get("candidateRef")));
        appendField(builder, "Candidate SHA-256", text(delivery.get("candidateSha256")));
        appendField(builder, "Expected Git Tree", text(delivery.get("expectedResultTree")));
        appendList(builder, "Accepted Files", delivery.get("acceptedFiles"));
        appendList(builder, "Excluded Files", delivery.get("excludedFiles"));
        appendField(builder, "PR Body", text(delivery.get("prBodyPath")));
        appendField(builder, "Commit Message", text(delivery.get("commitMessagePath")));
        builder.append("\n");
    }

    private Map<String, Object> taskContractSummary(GateContext context, GateContractView contractView) {
        if (contractView.contract() == null) {
            return Map.of();
        }
        var summary = new LinkedHashMap<String, Object>();
        var document = contractView.contract();
        summary.put("objective", document.objective());
        summary.put("status", text(document.status()));
        summary.put("includedScope", document.scope() == null
                ? List.of()
                : document.scope().included().stream()
                        .map(entry -> Map.of(
                                "path", entry.path(),
                                "operation", entry.operation().name()))
                        .toList());
        summary.put("excludedScope", document.scope() == null ? List.of() : document.scope().excluded());
        summary.put("acceptanceCriteria", document.acceptanceCriteria());
        summary.put("testRequirements", document.testRequirements());
        summary.put("constraints", document.constraints());
        summary.put("nonessentialOperationDeclarations", TaskContractArtifactWriter.nonessentialOperationDescriptions(document));
        summary.put("path", contractView.contractRef());
        summary.put("authority", contractView.authority());
        if (contractView.qualified()) {
            summary.put("sha256", contractView.contractSha256());
        }
        return summary;
    }

    private Map<String, Object> requirementResolutionSummary(
            GateContext context,
            GateContractView contractView
    ) {
        if (contractView.resolution().isEmpty()) {
            return Map.of();
        }
        var tree = contractView.resolution();
        var summary = new LinkedHashMap<String, Object>();
        summary.put("decision", text(tree.get("decision")));
        summary.put("approvedBy", text(tree.get("approved_by")));
        summary.put("gateRef", text(tree.get("gate_ref")));
        summary.put("resolvedQuestions", resolvedQuestionTexts(tree.get("resolved_questions")));
        summary.put("assumptions", stringList(tree.get("assumptions")));
        summary.put("acceptedRisks", stringList(tree.get("accepted_risks")));
        summary.put("path", contractView.resolutionRef());
        summary.put("authority", contractView.qualified() ? "qualified_approval" : "requirement_history");
        if (contractView.qualified()) {
            summary.put("sha256", contractView.resolutionSha256());
        }
        return summary;
    }

    private GateContractView contractView(GateContext context) throws java.io.IOException {
        if ("contract".equals(gatePurpose(context))) {
            var candidate = new TaskContractRevisionContextResolver(context.ledger()).contractGateCandidate(
                    context.workspaceRoot(), context.workstreamId(), context.instance().nodeInstanceId());
            return new GateContractView(candidate.contract(), candidate.resolutionDocument(),
                    candidate.contractRef(), candidate.resolutionRef(),
                    TaskContractArtifactWriter.sha256(candidate.rawJson().getBytes(StandardCharsets.UTF_8)),
                    TaskContractArtifactWriter.sha256(candidate.rawResolutionJson().getBytes(StandardCharsets.UTF_8)),
                    false, "unapproved_candidate");
        }
        if (!requiresApprovedTaskContract(context)) {
            return new GateContractView(null, Map.of(), "", "", "", "", false, "unavailable");
        }
        var resolved = TaskContractProjectionVerifier.resolve(context.ledger(), context.workspaceRoot(), context.workstreamId(), TaskContractProjectionVerifier.requiredPhase(context.definition()));
        if (resolved.failure() != null || resolved.qualified().isEmpty()) {
            var failure = resolved.failure() == null
                    ? TaskContractProjectionVerifier.Failure.of(
                            "APPROVAL_BINDING_MISSING", "human gate requires an approved task contract")
                    : resolved.failure();
            throw new IllegalStateException(TaskContractProjectionVerifier.FAILURE_OUTCOME
                    + ": " + failure.reason() + ": " + failure.message());
        }
        var qualified = resolved.qualified().orElseThrow();
        return new GateContractView(
                qualified.contract(),
                qualified.resolutionDocument(),
                qualified.contractRef(),
                qualified.resolutionRef(),
                qualified.sha256(),
                qualified.resolutionSha256(),
                true,
                "qualified_approval");
    }



    private boolean requiresApprovedTaskContract(GateContext context) {
        return TaskContractProjectionVerifier.requiresContract(context.definition());
    }

    private List<String> resolvedQuestionTexts(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : items) {
            if (item instanceof Map<?, ?> map) {
                var question = text(map.get("question"));
                var resolution = text(map.get("resolution"));
                if (!question.isBlank()) {
                    result.add(resolution.isBlank() ? question : question + " -> " + resolution);
                }
            }
        }
        return List.copyOf(result);
    }

    private Map<String, Object> contractRevision(GateContext context) throws java.io.IOException {
        var purpose = text(context.definition().config().get("gate_purpose"));
        if (!"requirement".equals(purpose) && !"contract".equals(purpose)) return Map.of();
        var resolver = new TaskContractRevisionContextResolver(context.ledger());
        var iterationId = context.instance().iterationId();
        if ("contract".equals(purpose)) {
            // EXECUTION may follow a plan revision. Requirement obligations still belong to
            // its approved GOAL, never to that technical revision's iteration.
            var goal = TaskContractProjectionVerifier.resolve(context.ledger(), context.workspaceRoot(),
                    context.workstreamId(), dev.dual.core.contract.TaskContract.Phase.GOAL);
            if (goal.qualified().isEmpty()) throw new java.io.IOException("GOAL_CONTRACT_NOT_QUALIFIED");
            var paths = new dev.dual.ledger.file.WorkstreamPaths(context.workspaceRoot(),
                    new dev.dual.core.id.DualId(context.workstreamId()));
            iterationId = context.ledger().loadNode(paths, goal.qualified().orElseThrow().compileNodeInstanceId()).iterationId();
        }
        var resolved = resolver.resolveForDisplayIteration(
                context.workspaceRoot(), context.workstreamId(), iterationId);
        if (!resolved.valid()) {
            throw new java.io.IOException("CONTRACT_REVISION_CONTEXT_INVALID: " + resolved.errors());
        }
        if (resolved.context().lateRoot() == null) return Map.of();
        TaskContractProposalReference candidate;
        if ("contract".equals(purpose)) {
            candidate = resolver.proposalForContractGate(context.workspaceRoot(), context.workstreamId(),
                    context.instance().nodeInstanceId());
        } else {
            var candidates = new java.util.LinkedHashSet<TaskContractProposalReference>();
            for (var ref : context.instance().inputRefs()) {
                AgentEvidenceIndex.validatedDocument(context.ledger(), context.workspaceRoot(), context.workstreamId(), ref, objectMapper)
                        .filter(document -> "intake.codex_product_review".equals(document.nodeId()))
                        .map(AgentOutputContractDocument::reviewSubject)
                        .ifPresent(candidates::add);
            }
            if (candidates.size() != 1) {
                throw new java.io.IOException("CONTRACT_REVISION_CONTEXT_INVALID: exactly one reviewed candidate required");
            }
            candidate = candidates.iterator().next();
        }
        return ContextBuildPackageHandler.contractRevisionProjection(context.ledger(), context.workspaceRoot(), context.workstreamId(),
                iterationId, candidate);
    }

    private AuthoredStageLineageResolver.GateView authoredGate(GateContext context) {
        var purpose = String.valueOf(context.definition().config().getOrDefault("gate_purpose", ""));
        if (!purpose.equals("design") && !purpose.equals("plan")) return null;
        try {
            var paths = new dev.dual.ledger.file.WorkstreamPaths(context.workspaceRoot(), new dev.dual.core.id.DualId(context.workstreamId()));
            return context.ledger().inspect(paths, (scoped, files) ->
                    new AuthoredStageLineageResolver(scoped, context.workspaceRoot(), context.workstreamId(), Long.MAX_VALUE)
                            .gateView(context.instance().nodeInstanceId()));
        } catch (java.io.IOException | IllegalArgumentException failure) {
            throw new IllegalStateException("AUTHORED_GATE_LINEAGE_INVALID: " + failure.getMessage(), failure);
        }
    }

    private AgentDecisionSummary latestAgentDecision(GateContext context, AuthoredStageLineageResolver.GateView authored) {
        if (authored != null) return AgentDecisionSummary.from(authored.decision(), authored.sidecarRef());
        var fromRefs = AgentEvidenceIndex.latestFromRefs(
                        context.ledger(), context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), objectMapper)
                .map(entry -> agentDecisionFromSidecar(context, entry));
        if (fromRefs.isPresent() && !fromRefs.get().isEmpty()) {
            return fromRefs.get();
        }
        return AgentDecisionSummary.empty();
    }

    private Map<String, Object> latestReviewSubject(GateContext context, AuthoredStageLineageResolver.GateView authored) {
        if (authored != null) return authored.projection();
        return AgentEvidenceIndex.latestFromRefs(
                        context.ledger(), context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), objectMapper)
                .map(entry -> entry.document().reviewSubject())
                .filter(java.util.Objects::nonNull)
                .map(TaskContractProposalReference::toMap)
                .orElse(Map.of());
    }

    private void appendReviewSubject(StringBuilder builder, Map<String, Object> subject) {
        if (subject.isEmpty()) {
            return;
        }
        builder.append("## Review Subject\n\n");
        appendField(builder, "Proposal ID", text(subject.get("proposal_id")));
        appendField(builder, "Artifact Ref", text(subject.get("artifact_ref")));
        appendField(builder, "SHA-256", text(subject.get("sha256")));
        builder.append("\n");
    }

    private AgentDecisionSummary agentDecisionFromSidecar(GateContext context, AgentEvidenceIndex.Entry entry) {
        if (entry == null || !entry.document().hasDecision()) {
            return AgentDecisionSummary.empty();
        }
        return AgentDecisionSummary.from(entry.document(), displayRef(context.workspaceRoot(), entry.path()));
    }

    private Map<String, Object> gitEvidenceSummary(GateContext context) {
        if ("CHANGE_SCOPE_VIOLATION".equals(context.sourceOutcome())) {
            return Map.of("changeScopeEvaluation", changeScopeEvaluationSummary(context));
        }
        var evidenceDir = workstreamDir(context).resolve("artifacts/git-evidence");
        var changedFiles = readLines(evidenceDir.resolve("changed-files.txt"));
        var diffStat = readText(evidenceDir.resolve("diff.stat"));
        var status = readText(evidenceDir.resolve("git-status-short.txt"));
        if (changedFiles.isEmpty() && diffStat.isBlank() && status.isBlank()) {
            return Map.of();
        }
        var summary = new LinkedHashMap<String, Object>();
        summary.put("changedFiles", changedFiles);
        summary.put("diffStat", diffStat);
        summary.put("statusShort", status);
        return summary;
    }

    private Map<String, Object> changeScopeEvaluationSummary(GateContext context) {
        try {
            var verified = ChangeScopeEvaluationArtifact.verifyGateSource(context.workspaceRoot(), context.workstreamId(),
                    context.instance().iterationId(), context.instance().inputRefs());
            var evaluation = verified.document().evaluation();
            var summary = new LinkedHashMap<String, Object>();
            summary.put("ref", verified.ref());
            summary.put("sha256", verified.sha256());
            summary.put("violations", evaluation.violations());
            summary.put("missingDeclared", evaluation.missingDeclared());
            return Map.copyOf(summary);
        } catch (IllegalStateException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IllegalStateException("change-scope evaluation verification failed", failure);
        }
    }

    private Map<String, Object> deliverySummary(GateContext context) {
        var deliveryDir = workstreamDir(context).resolve("delivery");
        var summary = new LinkedHashMap<String, Object>();
        var prBody = deliveryDir.resolve("pr-body.md");
        var commitMessage = deliveryDir.resolve("commit-message.txt");
        if (Files.isRegularFile(prBody)) {
            summary.put("prBodyPath", displayRef(context.workspaceRoot(), prBody));
        }
        if (Files.isRegularFile(commitMessage)) {
            summary.put("commitMessagePath", displayRef(context.workspaceRoot(), commitMessage));
        }
        var candidateRefs = context.instance().inputRefs().stream()
                .filter(ref -> ref.matches("\\.agent/workstreams/[^/]+/delivery/candidates/[^/]+/candidate-[0-9a-f]{64}\\.json"))
                .toList();
        if ("acceptance".equals(gatePurpose(context))) {
            if (candidateRefs.size() != 1) {
                throw new IllegalStateException("acceptance gate must receive exactly one delivery candidate");
            }
            try {
                var candidatePath = resolveInsideWorkspace(context.workspaceRoot(), candidateRefs.get(0));
                if (candidatePath == null || candidatePath.getParent() == null) {
                    throw new IllegalStateException("acceptance delivery candidate ref is invalid");
                }
                var paths = new WorkstreamPaths(context.workspaceRoot(), new DualId(context.workstreamId()));
                var published = new DeliveryCandidateWriter().existing(
                        paths, candidatePath.getParent().getFileName().toString());
                if (published == null || !published.ref().equals(candidateRefs.get(0))) {
                    throw new IllegalStateException("acceptance delivery candidate is not the published occurrence");
                }
                summary.put("candidateRef", published.ref());
                summary.put("candidateSha256", published.sha256());
                summary.put("baseCommit", published.document().baseCommit());
                summary.put("expectedResultTree", published.document().expectedResultTree());
                summary.put("acceptedFiles", published.document().acceptedFiles());
                summary.put("excludedFiles", published.document().excludedFiles());
            } catch (Exception failure) {
                throw new IllegalStateException("acceptance delivery candidate verification failed", failure);
            }
        }
        return summary;
    }

    private List<Map<String, Object>> inputArtifactSummaries(GateContext context) {
        var result = new ArrayList<Map<String, Object>>();
        for (var inputRef : context.instance().inputRefs()) {
            result.add(inputArtifactSummary(context, inputRef));
        }
        return List.copyOf(result);
    }

    private Map<String, Object> inputArtifactSummary(GateContext context, String inputRef) {
        var summary = new LinkedHashMap<String, Object>();
        summary.put("ref", inputRef);
        var path = resolveInsideWorkspace(context.workspaceRoot(), inputRef);
        if (path == null) {
            summary.put("status", "outside_workspace");
            summary.put("kind", "unavailable");
            return summary;
        }
        if (!Files.isRegularFile(path)) {
            summary.put("status", "not_found");
            summary.put("kind", "unavailable");
            return summary;
        }
        summary.put("status", "available");
        summary.put("kind", artifactKind(path));

        var sidecar = sidecarPath(path);
        if (Files.isRegularFile(sidecar)) {
            summary.put("sidecar", displayRef(context.workspaceRoot(), sidecar));
            appendSidecarSummary(context, summary, inputRef);
        }
        return summary;
    }

    private String artifactKind(Path path) {
        var name = path.getFileName().toString();
        if (name.endsWith(".contract.json")) {
            return "contract_sidecar";
        }
        if (name.endsWith(".stderr.log")) {
            return "stderr_log";
        }
        if (name.endsWith(".md")) {
            return "markdown_output";
        }
        if (name.endsWith(".json")) {
            return "json";
        }
        return "file";
    }

    private Path sidecarPath(Path artifactPath) {
        var name = artifactPath.getFileName().toString();
        if (name.endsWith(".contract.json")) {
            return artifactPath;
        }
        if (name.endsWith(".md")) {
            return artifactPath.resolveSibling(name.substring(0, name.length() - ".md".length()) + ".contract.json");
        }
        return AgentOutputContractSidecar.pathFor(artifactPath);
    }

    private void appendSidecarSummary(
            GateContext context,
            Map<String, Object> summary,
            String inputRef
    ) {
        var document = AgentEvidenceIndex.validatedDocument(
                        context.ledger(), context.workspaceRoot(), context.workstreamId(), inputRef, objectMapper)
                .orElseThrow(() -> new IllegalStateException(
                        "routed human review sidecar is unavailable: " + inputRef));
        summary.put("decision", document.decision());
        summary.put("summary", document.summary());
        summary.put("mustFix", document.mustFix());
        summary.put("openRisks", document.openRisks());
    }

    private Map<String, Object> operatorGuidance(GateContext context, List<String> allowedActions,
                                               AgentDecisionSummary decision) {
        var decisionText = decision.decision();
        var blocking = decision.blocking();
        var mustFix = decision.mustFix();
        var missingEvidence = decision.missingEvidence();
        var openRisks = decision.openRisks();
        var gatePurpose = gatePurpose(context);
        var terminalGate = terminalGate(context);

        var guidance = new LinkedHashMap<String, Object>();
        if (allowedActions.contains("complete") && terminalGate) {
            guidance.put("recommendedAction", "complete");
            guidance.put("reason", "This is a next-stage gate. Complete the current workstream when the handoff and next-stage prompt are acceptable.");
        } else if (blocking && allowedActions.contains("revise")) {
            guidance.put("recommendedAction", "revise");
            guidance.put("reason", "The latest structured review marks the issue as blocking.");
        } else if (!mustFix.isEmpty() && allowedActions.contains("revise")) {
            guidance.put("recommendedAction", "revise");
            guidance.put("reason", "The latest agent decision still contains Must Fix items.");
        } else if ("acceptance".equals(gatePurpose) && !missingEvidence.isEmpty() && allowedActions.contains("revise")) {
            guidance.put("recommendedAction", "revise");
            guidance.put("reason", "The latest acceptance review reports missing evidence.");
        } else if (isNegativeDecision(decisionText) && allowedActions.contains("revise")) {
            guidance.put("recommendedAction", "revise");
            guidance.put("reason", "The latest agent decision indicates the work is not ready to continue.");
        } else if (isPositiveDecision(decisionText) && allowedActions.contains("approve")) {
            guidance.put("recommendedAction", "approve");
            guidance.put("reason", "The latest agent decision is positive. Approve only after checking the packet evidence.");
        } else {
            guidance.put("recommendedAction", allowedActions.isEmpty() ? "inspect" : allowedActions.get(0));
            guidance.put("reason", "No decisive recommendation is available. Read the packet and choose an allowed action.");
        }
        guidance.put("suggestedChecks", suggestedChecks(gatePurpose, mustFix, missingEvidence, openRisks));
        return guidance;
    }

    private List<String> suggestedChecks(
            String gatePurpose,
            List<String> mustFix,
            List<String> missingEvidence,
            List<String> openRisks
    ) {
        var checks = new ArrayList<String>();
        checks.add("Confirm the TaskContract objective, scope, non-goals, and acceptance criteria still match the task.");
        if (!mustFix.isEmpty()) {
            checks.add("Do not approve until every Must Fix item is addressed or explicitly accepted by the human reviewer.");
        }
        if (!missingEvidence.isEmpty()) {
            checks.add("Check whether missing evidence is acceptable for this gate or requires another agent pass.");
        }
        if (!openRisks.isEmpty()) {
            checks.add("Review open risks and decide whether they are acceptable for this stage.");
        }
        if ("acceptance".equals(gatePurpose)) {
            checks.add("Compare Codex acceptance, developer self-test evidence, Git evidence, and changed files before approval.");
        } else if ("design".equals(gatePurpose) || "plan".equals(gatePurpose)) {
            checks.add("Check whether the design or plan stays inside scope and avoids unnecessary implementation detail.");
        } else if ("next_stage".equals(gatePurpose)) {
            checks.add("Check the handoff and next-stage prompt before completing the current workstream.");
        }
        return List.copyOf(checks);
    }

    private static String gatePurpose(GateContext context) {
        return HumanGateSemantics.purpose(context.definition().config(), context.instance().nodeDefinitionId());
    }

    private static boolean terminalGate(GateContext context) {
        return HumanGateSemantics.terminal(context.definition().config(), context.instance().nodeDefinitionId());
    }

    private boolean isPositiveDecision(String decision) {
        return switch (StageOutcome.fromDecision(decision)) {
            case READY, ACCEPTED, ACCEPTED_WITH_NOTES -> true;
            default -> false;
        };
    }

    private boolean isNegativeDecision(String decision) {
        return switch (StageOutcome.fromDecision(decision)) {
            case NEEDS_REVISION, BLOCKED, REJECTED, INSUFFICIENT_EVIDENCE -> true;
            default -> false;
        };
    }

    private Path workstreamDir(GateContext context) {
        return context.workspaceRoot()
                .resolve(".agent/workstreams")
                .resolve(context.workstreamId())
                .normalize();
    }

    private Path resolveInsideWorkspace(Path workspaceRoot, String ref) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root)) {
            return null;
        }
        return path;
    }

    private List<String> readLines(Path path) {
        var text = readText(path);
        if (text.isBlank()) {
            return List.of();
        }
        return text.lines()
                .map(String::trim)
                .filter(line -> !line.isBlank())
                .toList();
    }

    private String readText(Path path) {
        try {
            if (!Files.isRegularFile(path)) {
                return "";
            }
            return Files.readString(path, StandardCharsets.UTF_8).trim();
        } catch (Exception ignored) {
            return "";
        }
    }

    private List<String> stringList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : items) {
            var text = text(item);
            if (!text.isBlank()) {
                result.add(text);
            }
        }
        return List.copyOf(result);
    }

    private void appendField(StringBuilder builder, String label, String value) {
        if (!value.isBlank()) {
            builder.append("- ").append(label).append(": ").append(value.replace("\n", " / ")).append("\n");
        }
    }

    private void appendList(StringBuilder builder, String label, Object value) {
        var items = stringList(value);
        if (items.isEmpty()) {
            return;
        }
        builder.append("- ").append(label).append(":\n");
        for (var item : items) {
            builder.append("  - ").append(item.replace("\n", " / ")).append("\n");
        }
    }

    private void appendPreformatted(StringBuilder builder, String label, String value) {
        if (value.isBlank()) {
            return;
        }
        builder.append("### ").append(label).append("\n\n");
        builder.append("```text\n").append(value).append("\n```\n\n");
    }

    private String displayRef(Path workspaceRoot, Path path) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var normalized = path.toAbsolutePath().normalize();
        if (normalized.startsWith(root)) {
            return root.relativize(normalized).toString();
        }
        return normalized.toString();
    }

    private String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private record GateContractView(
            TaskContract contract,
            Map<String, Object> resolution,
            String contractRef,
            String resolutionRef,
            String contractSha256,
            String resolutionSha256,
            boolean qualified,
            String authority
    ) {
        private static GateContractView empty() {
            return new GateContractView(null, Map.of(), "", "", "", "", false, "unavailable");
        }
    }
}

