package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.NodeResult;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;

public final class PromptGenerateNextStageHandler implements TaskHandler {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    @Override
    public String type() {
        return "prompt.generate_next_stage";
    }

    @Override
    public NodeResult execute(TaskContext context) throws IOException {
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());
        var outputDir = workstreamDir.resolve("artifacts").resolve("next-stage");
        Files.createDirectories(outputDir);

        var sourceRefs = readableInputRefs(context);
        var structured = structuredHandoff(context, sourceRefs);
        if (structured.isEmpty()) {
            return new NodeResult(
                    "STAGE_HANDOFF_CONTRACT_MISSING",
                    dev.dual.core.workflow.NodeStatus.FAILED,
                    sourceRefs,
                    java.util.Map.of("reason", "validated stage_handoff sidecar is required"),
                    "validated stage_handoff sidecar is required; Markdown fallback is not a workflow fact"
            );
        }
        var handoffSource = new HandoffSource(structured.get(), renderStructuredHandoffContext(structured.get()));
        var handoff = withLatestVerificationState(sourceRefs, context, handoffSource.document());
        var handoffContextText = renderStructuredHandoffContext(handoff);
        var suggestedPrompt = handoff.suggestedNextPrompt();
        var promptPath = outputDir.resolve("next-stage-prompt.md");
        Files.writeString(promptPath, renderPrompt(context, sourceRefs, suggestedPrompt, handoffContextText), StandardCharsets.UTF_8);

        var handoffJsonPath = outputDir.resolve("handoff.json");
        Files.writeString(handoffJsonPath, renderHandoffJson(handoff), StandardCharsets.UTF_8);

        var promptRef = toWorkspaceRef(context.workspaceRoot(), promptPath);
        var handoffJsonRef = toWorkspaceRef(context.workspaceRoot(), handoffJsonPath);
        var result = new LinkedHashMap<String, Object>();
        result.put("generated", true);
        result.put("mode", "structured-handoff");
        result.put("prompt_path", promptRef);
        result.put("handoff_json_path", handoffJsonRef);
        result.put("source_refs", sourceRefs);
        result.put("used_suggested_prompt_section", !suggestedPrompt.isBlank());
        result.put("generated_at", Instant.now().toString());
        return NodeResult.completed("completed", List.of(promptRef, handoffJsonRef), result);
    }

    private static String renderPrompt(TaskContext context, List<String> sourceRefs, String suggestedPrompt, String handoffText) {
        var builder = new StringBuilder();
        builder.append("# Next Stage Prompt\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Builder Node: ").append(context.definition().id()).append("\n");
        builder.append("- Generated At: ").append(Instant.now()).append("\n");
        builder.append("- Source Handoff Refs: ").append(sourceRefs.isEmpty() ? "(none)" : String.join(", ", sourceRefs)).append("\n\n");

        builder.append("## Prompt\n\n");
        if (!suggestedPrompt.isBlank()) {
            builder.append(suggestedPrompt.stripTrailing()).append("\n\n");
        } else {
            builder.append("Continue the next stage using the handoff below. Preserve the existing scope, review open risks first, and do not invent unrelated requirements.\n\n");
        }

        builder.append("## Handoff Context\n\n");
        if (handoffText.isBlank()) {
            builder.append("(no handoff artifact was available)\n");
        } else {
            builder.append(handoffText.stripTrailing()).append("\n");
        }
        return builder.toString();
    }

    private static String renderStructuredHandoffContext(StageHandoffDocument handoff) {
        var builder = new StringBuilder();
        builder.append("### Source\n\n");
        builder.append(handoff.sourceHandoffPath().isBlank() ? "(unknown)" : handoff.sourceHandoffPath()).append("\n\n");
        appendList(builder, "Completed Work", handoff.completedWork());
        appendList(builder, "Important Decisions", handoff.importantDecisions());
        appendList(builder, "Changed Files", handoff.changedFiles());
        if (!handoff.verificationState().isBlank()) {
            builder.append("### Verification State\n\n").append(handoff.verificationState()).append("\n\n");
        }
        appendList(builder, "Open Risks", handoff.openRisks());
        if (!handoff.recommendedNextStage().isBlank()) {
            builder.append("### Recommended Next Stage\n\n").append(handoff.recommendedNextStage()).append("\n\n");
        }
        return builder.toString().stripTrailing();
    }

    private static void appendList(StringBuilder builder, String title, List<String> items) {
        if (items.isEmpty()) {
            return;
        }
        builder.append("### ").append(title).append("\n\n");
        for (var item : items) {
            builder.append("- ").append(item).append("\n");
        }
        builder.append("\n");
    }

    private static List<String> readableInputRefs(TaskContext context) {
        return context.instance().inputRefs().stream()
                .filter(ref -> !ref.startsWith("artifact://"))
                .filter(ref -> Files.isRegularFile(context.workspaceRoot().resolve(ref).normalize()))
                .toList();
    }

    private static String toWorkspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static String renderHandoffJson(StageHandoffDocument handoff) throws IOException {
        return OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(handoff.toMap());
    }

    private static StageHandoffDocument withLatestVerificationState(List<String> sourceRefs, TaskContext context, StageHandoffDocument handoff)
            throws IOException {
        var verificationState = latestVerificationState(sourceRefs, context);
        if (verificationState.isBlank()) {
            return handoff;
        }
        return new StageHandoffDocument(
                handoff.schemaVersion(),
                handoff.workstreamId(),
                handoff.stageId(),
                handoff.iterationId(),
                handoff.sourceHandoffPath(),
                handoff.completedWork(),
                handoff.importantDecisions(),
                handoff.changedFiles(),
                handoff.openRisks(),
                verificationState,
                handoff.recommendedNextStage(),
                handoff.suggestedNextPrompt(),
                handoff.generatedAt()
        );
    }

    private static String latestVerificationState(List<String> sourceRefs, TaskContext context) {
        var parts = new java.util.ArrayList<String>();
        latestInputContract(sourceRefs, context, "implement-claude-self-test.contract.json")
                .map(AgentOutputContractDocument::verificationSummary)
                .filter(summary -> !summary.isBlank())
                .ifPresent(summary -> parts.add("Self-test: " + summary));
        latestInputContract(sourceRefs, context, "acceptance-codex-review.contract.json")
                .filter(document -> !document.verificationSummary().isBlank())
                .map(document -> "Acceptance (" + document.decision() + "): " + document.verificationSummary())
                .filter(summary -> !summary.isBlank())
                .ifPresent(parts::add);
        return String.join("\n", parts);
    }

    private static java.util.Optional<AgentOutputContractDocument> latestInputContract(
            List<String> sourceRefs,
            TaskContext context,
            String fileName
    ) {
        for (int i = sourceRefs.size() - 1; i >= 0; i--) {
            var ref = sourceRefs.get(i);
            if (!Path.of(ref).getFileName().toString().equals(fileName)) {
                continue;
            }
            var path = context.workspaceRoot().resolve(ref).normalize();
            var document = AgentOutputContractDocument.read(path, OBJECT_MAPPER);
            if (document.isPresent() && AgentOutputLineageVerifier.violation(
                    context.ledger(), context.workspaceRoot(), context.workstreamId(), path, document.get()).isEmpty()) {
                return document;
            }
        }
        return java.util.Optional.empty();
    }

    private static java.util.Optional<StageHandoffDocument> structuredHandoff(TaskContext context, List<String> sourceRefs) throws IOException {
        for (String sourceRef : sourceRefs) {
            var outputPath = context.workspaceRoot().resolve(sourceRef).normalize();
            var sidecarPath = AgentOutputContractSidecar.pathFor(outputPath);
            var sidecar = AgentOutputContractDocument.read(sidecarPath, OBJECT_MAPPER);
            if (sidecar.isEmpty()
                    || AgentOutputLineageVerifier.violation(
                            context.ledger(), context.workspaceRoot(), context.workstreamId(), sidecarPath, sidecar.get()).isPresent()
                    || !sidecar.get().isStageHandoffArtifact()) {
                continue;
            }
            var changedFiles = sidecar.get().changedFiles();
            if (changedFiles.isEmpty()) {
                changedFiles = changedFilesFromGitEvidence(context);
            }
            return java.util.Optional.of(new StageHandoffDocument(
                    1,
                    context.workstreamId(),
                    context.instance().stageId(),
                    context.instance().iterationId(),
                    toWorkspaceRef(context.workspaceRoot(), sidecarPath),
                    sidecar.get().completedWork(),
                    sidecar.get().importantDecisions(),
                    changedFiles,
                    sidecar.get().openRisks(),
                    sidecar.get().verificationSummary(),
                    sidecar.get().recommendedNextStage(),
                    sidecar.get().suggestedNextPrompt(),
                    Instant.now().toString()
            ));
        }
        return java.util.Optional.empty();
    }

    private static List<String> changedFilesFromGitEvidence(TaskContext context) throws IOException {
        var path = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId())
                .resolve("artifacts")
                .resolve("git-evidence")
                .resolve("changed-files.txt");
        if (!Files.isRegularFile(path)) {
            return List.of();
        }
        return Files.readAllLines(path, StandardCharsets.UTF_8).stream()
                .map(String::strip)
                .filter(line -> !line.isBlank())
                .toList();
    }

    private record HandoffSource(StageHandoffDocument document, String contextText) {
    }

}

package dev.dual.runtime.handler;

import java.util.List;

/**
 * Central catalog of reasons an agent may re-read a file already covered by the
 * read-reuse contract. Shared by {@code RepoScopeGovernance} (which writes the
 * contract into {@code read-reuse-contract.json}) and the artifact-contract
 * validator (which validates declared {@code reread_reasons}) so the allowed
 * set has exactly one source of truth.
 */
public final class ReadReuseContractReasons {
    public static final List<String> ALLOWED_REPEATED_READ_REASONS = List.of(
            "file changed after prior read",
            "exact current content is needed before editing",
            "previous evidence does not cover the selected stage");

    static boolean isAllowed(String reason) {
        return reason != null && ALLOWED_REPEATED_READ_REASONS.contains(reason);
    }

    private ReadReuseContractReasons() {
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.contract.TaskContract;
import dev.dual.runtime.governance.AgentCapabilityCatalog;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Builds passive repository-scope governance artifacts for one context package.
 *
 * These documents are execution guardrails and evidence projections, not
 * workflow truth. They are rebuildable from the effective workdir, task
 * contract, evidence manifest, and node context, then consumed by prompts,
 * trace, and operator views to compare planned scope with actual agent
 * behavior.
 */
final class RepoScopeGovernance {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private static final int MAX_SCOPE_FILES = 24;

    private RepoScopeGovernance() {
    }

    static Documents build(
            Path workspaceRoot,
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper
    ) throws IOException {
        return build(workspaceRoot, workstreamDir, context, objectMapper, Optional.empty());
    }

    static Documents build(
            Path workspaceRoot,
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        return build(workspaceRoot, workstreamDir, context, objectMapper, qualifiedContract, "");
    }

    static Documents build(
            Path workspaceRoot,
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract,
            String runId
    ) throws IOException {
        var stageId = stageId(context);
        var targetNodeDefinitionId = targetNodeDefinitionId(context);
        var memoryDir = workstreamDir.resolve("memory");
        var workstreamMemoryPath = memoryDir.resolve("workstream-memory.json");
        var existingMemory = readWorkstreamMemory(workstreamMemoryPath, objectMapper);
        var governanceDir = workstreamDir.resolve("artifacts").resolve("context-governance");
        var nodeKey = safeFileName(context.instance().nodeInstanceId());
        var occurrenceKey = runId == null || runId.isBlank()
                ? nodeKey
                : nodeKey + "-" + safeFileName(runId);
        var occurrenceDir = governanceDir.resolve("occurrences").resolve(occurrenceKey);
        var repoMapPath = occurrenceDir.resolve("repo-map.json");
        var planPath = occurrenceDir.resolve("file-relevance-plan.json");
        var policyPath = occurrenceDir.resolve("stage-scope-policy.json");
        var workingSetPath = occurrenceDir.resolve("working-set.json");
        var fileSummariesPath = occurrenceDir.resolve("file-summaries.json");
        var readReuseContractPath = occurrenceDir.resolve("read-reuse-contract.json");
        var capabilityCatalogPath = occurrenceDir.resolve("agent-capability-catalog.json");
        var reportPath = occurrenceDir.resolve("planned-report.json");
        var bindingPath = occurrenceDir.resolve("binding.json");
        Files.createDirectories(memoryDir);
        Files.createDirectories(occurrenceDir);
        var trackedInventory = contractDiscovery(context)
                ? GitTrackedPathInventory.capture(workspaceRoot)
                : GitTrackedPathInventory.empty();
        var plan = buildFileRelevancePlan(
                workstreamDir, context, objectMapper, stageId, targetNodeDefinitionId, qualifiedContract,
                trackedInventory, ref(workspaceRoot, repoMapPath));
        var repoMapPaths = contractDiscovery(context)
                ? trackedInventory.paths()
                : textList(plan.get("readCandidates"));
        var repoMap = buildRepoMap(
                workspaceRoot,
                workstreamDir,
                context,
                objectMapper,
                repoMapPaths,
                trackedInventory
        );
        var policy = buildStageScopePolicy(context, stageId, plan, targetNodeDefinitionId);
        var report = buildInitialReport(context, stageId, plan, policy, targetNodeDefinitionId);
        var workingSet = buildWorkingSet(context, stageId, plan, policy, targetNodeDefinitionId);
        var fileSummaries = buildFileSummaries(context, stageId, workingSet);
        var readReuseContract = buildReadReuseContract(context, stageId, plan, policy, targetNodeDefinitionId, existingMemory);
        var capabilityCatalog = AgentCapabilityCatalog.detect(
                context.workstreamId(),
                targetNodeDefinitionId,
                context.definition().config()
        );
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(repoMapPath.toFile(), repoMap);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(planPath.toFile(), plan);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(policyPath.toFile(), policy);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(workingSetPath.toFile(), workingSet);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(fileSummariesPath.toFile(), fileSummaries);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(readReuseContractPath.toFile(), readReuseContract);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(capabilityCatalogPath.toFile(), capabilityCatalog.toDocument());
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(reportPath.toFile(), report);
        var binding = RepositoryFactBinding.write(
                workspaceRoot,
                bindingPath,
                context.workstreamId(),
                context.instance().nodeInstanceId(),
                runId,
                trackedInventory.head(),
                trackedInventory.sha256(),
                trackedInventory.paths().size(),
                Map.of(
                        "repoMap", repoMapPath,
                        "fileRelevancePlan", planPath,
                        "stageScopePolicy", policyPath,
                        "workingSet", workingSetPath,
                        "fileSummaries", fileSummariesPath,
                        "readReuseContract", readReuseContractPath,
                        "agentCapabilityCatalog", capabilityCatalogPath,
                        "plannedReport", reportPath
                ),
                objectMapper
        );
        var workstreamMemory = buildWorkstreamMemory(
                context,
                workspaceRoot,
                stageId,
                existingMemory,
                repoMapPath,
                planPath,
                policyPath,
                workingSetPath,
                fileSummariesPath,
                readReuseContractPath,
                binding.path()
        );
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(workstreamMemoryPath.toFile(), workstreamMemory);

        return new Documents(
                repoMap,
                plan,
                policy,
                report,
                workingSet,
                fileSummaries,
                readReuseContract,
                capabilityCatalog.toDocument(),
                repoMapPath,
                planPath,
                policyPath,
                reportPath,
                workingSetPath,
                fileSummariesPath,
                readReuseContractPath,
                capabilityCatalogPath,
                workstreamMemoryPath,
                binding
        );
    }

    static void appendMarkdownGuidance(StringBuilder builder, Documents documents, Path workspaceRoot) {
        appendMarkdownGuidance(builder, documents, workspaceRoot, false);
    }

    static void appendMarkdownGuidance(StringBuilder builder, Documents documents, Path workspaceRoot, boolean compact) {
        if (documents == null) {
            return;
        }
        builder.append("## Repo Scope Guidance\n\n");
        builder.append("This section is a passive harness guardrail. It guides repository exploration but does not replace task contract, artifact validation, or human approval.\n\n");
        builder.append("- Stage: ").append(text(documents.policy().get("stageId"))).append("\n");
        if (compact) {
            appendCompactMarkdownGuidance(builder, documents, workspaceRoot);
            return;
        }
        builder.append("- Repo map: ").append(ref(workspaceRoot, documents.repoMapPath())).append("\n");
        builder.append("- Repository fact binding: ")
                .append(documents.repositoryFactBinding().ref()).append("\n");
        appendInventoryIdentity(builder, documents);
        builder.append("- File relevance plan: ").append(ref(workspaceRoot, documents.fileRelevancePlanPath())).append("\n");
        builder.append("- Stage scope policy: ").append(ref(workspaceRoot, documents.stageScopePolicyPath())).append("\n");
        builder.append("- Workstream memory: ").append(ref(workspaceRoot, documents.workstreamMemoryPath())).append("\n");
        builder.append("- Working set: ").append(ref(workspaceRoot, documents.workingSetPath())).append("\n");
        builder.append("- File summaries: ").append(ref(workspaceRoot, documents.fileSummariesPath())).append("\n");
        builder.append("- Read reuse contract: ").append(ref(workspaceRoot, documents.readReuseContractPath())).append("\n");
        builder.append("- Agent capability catalog: ").append(ref(workspaceRoot, documents.agentCapabilityCatalogPath())).append("\n");
        builder.append("- Governance report: ").append(ref(workspaceRoot, documents.governanceReportPath())).append("\n\n");
        appendPathList(builder, "Recommended read files", textList(documents.plan().get("readCandidates")), 8);
        appendPathList(builder, "Contract scope candidates", textList(documents.plan().get("contractScopeCandidates")), 12);
        appendPathList(builder, "Allowed write files", textList(documents.policy().get("writeScope")), 8);
        appendPathList(builder, "Forbidden scope", textList(documents.policy().get("forbiddenScope")), 8);
        appendPathList(builder, "Already inspected files", textList(documents.plan().get("previouslyReadFiles")), 8);
        appendReadAvoidanceRules(builder, documents);
        builder.append("Read recommendations are context only. Declared edits must match TaskContract.scope and are verified from Git evidence.\n\n");
    }

    private static void appendCompactMarkdownGuidance(StringBuilder builder, Documents documents, Path workspaceRoot) {
        builder.append("- Governance refs: capabilityCatalog=")
                .append(ref(workspaceRoot, documents.agentCapabilityCatalogPath()))
                .append("; readReuseContract=")
                .append(ref(workspaceRoot, documents.readReuseContractPath()))
                .append("; repoMap=")
                .append(ref(workspaceRoot, documents.repoMapPath()))
                .append("; repositoryFactBinding=")
                .append(documents.repositoryFactBinding().ref())
                .append("\n\n");
        appendInventoryIdentity(builder, documents);
        builder.append("- Available context capabilities: ")
                .append(inlineList(capabilitySummaries(documents.agentCapabilityCatalog()), 4))
                .append("\n\n");
        appendPathList(builder, "Recommended read files", textList(documents.plan().get("readCandidates")), 4);
        appendPathList(builder, "Expected edit files", textList(documents.policy().get("writeScope")), 4);
    }

    private static Map<String, Object> buildRepoMap(
            Path workspaceRoot,
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper,
            List<String> knownPaths,
            GitTrackedPathInventory trackedInventory
    ) throws IOException {
        var files = new ArrayList<Map<String, Object>>();
        var root = workspaceRoot.toAbsolutePath().normalize();
        for (var relative : new LinkedHashSet<>(knownPaths)) {
            var path = root.resolve(relative).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path) || ignoredPath(relative)) {
                continue;
            }
            var item = new LinkedHashMap<String, Object>();
            item.put("path", relative);
            item.put("kind", fileKind(relative));
            item.put("sizeBytes", safeSize(path));
            files.add(item);
        }
        files.sort(Comparator.comparing(item -> text(item.get("path"))));
        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "repo_map");
        document.put("workstreamId", context.workstreamId());
        document.put("generatedAt", Instant.now().toString());
        document.put("effectiveWorkdir", workspaceRoot.toAbsolutePath().normalize().toString());
        document.put("baseCommit", readBaseCommit(workstreamDir, objectMapper));
        document.put("source", contractDiscovery(context)
                ? "git_tracked_inventory"
                : "task_contract_scope+git_evidence");
        document.put("inventoryHead", trackedInventory.head());
        document.put("inventorySha256", trackedInventory.sha256());
        document.put("inventoryPathCount", trackedInventory.paths().size());
        document.put("files", files);
        document.put("fileCount", files.size());
        document.put("truncated", false);
        return document;
    }

    private static Map<String, Object> buildFileRelevancePlan(
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper,
            String stageId,
            String targetNodeDefinitionId,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract,
            GitTrackedPathInventory trackedInventory,
            String trackedInventoryRef
    ) throws IOException {
        var contractScope = contractScopePaths(
                context.workspaceRoot(), workstreamDir, qualifiedContract);
        var candidates = new LinkedHashSet<String>();
        candidates.addAll(contractScope);
        addGitChangedFiles(candidates, workstreamDir);
        if (contractDiscovery(context)) {
            candidates.addAll(trackedInventory.paths());
        }
        var readCandidates = bounded(candidates, MAX_SCOPE_FILES);
        var writeCandidates = stageAllowsBusinessWrites(stageId)
                ? contractScope
                : List.<String>of();
        var previousReads = previousReadCounts(workstreamDir, "", objectMapper);
        var evidenceFiles = evidenceFiles(workstreamDir, objectMapper);
        var repeatedReadAvoidance = repeatedReadAvoidance(readCandidates, previousReads, evidenceFiles);

        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "file_relevance_plan");
        document.put("workstreamId", context.workstreamId());
        document.put("stageId", stageId);
        document.put("nodeInstanceId", context.instance().nodeInstanceId());
        document.put("nodeDefinitionId", context.definition().id());
        document.put("builderNodeDefinitionId", context.definition().id());
        document.put("targetNodeDefinitionId", targetNodeDefinitionId);
        document.put("iterationId", context.instance().iterationId());
        document.put("source", contractDiscovery(context)
                ? "git_tracked_inventory+task_contract_scope+git_evidence"
                : "task_contract_scope+git_evidence");
        document.put("trackedInventoryRef", contractDiscovery(context) ? trackedInventoryRef : "");
        document.put("trackedInventoryHead", trackedInventory.head());
        document.put("trackedInventorySha256", trackedInventory.sha256());
        document.put("trackedInventoryPathCount", trackedInventory.paths().size());
        document.put("readCandidates", readCandidates);
        document.put("contractScopeCandidates", contractScope);
        document.put("writeCandidates", writeCandidates);
        document.put("previouslyReadFiles", previousReads.keySet().stream().limit(MAX_SCOPE_FILES).toList());
        document.put("repeatedReadAvoidance", repeatedReadAvoidance);
        document.put("expansionRules", List.of(
                "Use only routed artifacts and canonical task-contract or Git facts as prepared context.",
                "Do not re-read previously inspected files unless this stage needs fresh file contents.",
                "Do not infer task relevance from filenames, directory layout, or requirement prose."
        ));
        document.put("generatedAt", Instant.now().toString());
        return document;
    }

    private static Map<String, Object> buildStageScopePolicy(
            TaskHandler.TaskContext context,
            String stageId,
            Map<String, Object> plan,
            String targetNodeDefinitionId
    ) {
        var writeCandidates = textList(plan.get("writeCandidates"));
        var previouslyReadFiles = textList(plan.get("previouslyReadFiles"));
        var policy = new LinkedHashMap<String, Object>();
        policy.put("schemaVersion", 1);
        policy.put("artifactType", "stage_scope_policy");
        policy.put("workstreamId", context.workstreamId());
        policy.put("stageId", stageId);
        policy.put("nodeInstanceId", context.instance().nodeInstanceId());
        policy.put("nodeDefinitionId", context.definition().id());
        policy.put("builderNodeDefinitionId", context.definition().id());
        policy.put("targetNodeDefinitionId", targetNodeDefinitionId);
        policy.put("iterationId", context.instance().iterationId());
        policy.put("writeScope", writeCandidates);
        policy.put("previouslyReadFiles", previouslyReadFiles);
        policy.put("readReusePolicy", Map.of(
                "preferExistingEvidence", true,
                "avoidRepeatedReads", previouslyReadFiles.stream().limit(12).toList(),
                "requireReasonWhenRereading", targetSupportsRereadReasonField(targetNodeDefinitionId),
                "reasonField", targetSupportsRereadReasonField(targetNodeDefinitionId)
                        ? "agent_output_contract.reread_reasons"
                        : ""
        ));
        policy.put("forbiddenScope", forbiddenScope(stageId));
        policy.put("generatedAt", Instant.now().toString());
        return policy;
    }

