    private static Map<String, Object> readWorkstreamMemory(Path workstreamMemoryPath, ObjectMapper objectMapper) {
        if (!Files.isRegularFile(workstreamMemoryPath)) {
            return new LinkedHashMap<>();
        }
        try {
            return new LinkedHashMap<>(objectMapper.readValue(workstreamMemoryPath.toFile(), MAP_TYPE));
        } catch (IOException ignored) {
            return new LinkedHashMap<>();
        }
    }

    private static List<Map<String, Object>> reusableReadFiles(Map<String, Object> workstreamMemory) {
        var files = new ArrayList<Map<String, Object>>();
        for (var item : mapList(workstreamMemory.get("readFiles"))) {
            if (!Boolean.TRUE.equals(item.get("trusted")) || !text(item.get("invalidationReason")).isBlank()) {
                continue;
            }
            files.add(readReuseFile(item, "reuse_existing_summary"));
        }
        return files.stream()
                .sorted(Comparator.comparing(file -> text(file.get("path"))))
                .limit(24)
                .toList();
    }

    private static List<Map<String, Object>> invalidatedReadFiles(Map<String, Object> workstreamMemory) {
        var files = new ArrayList<Map<String, Object>>();
        for (var item : mapList(workstreamMemory.get("readFiles"))) {
            if (text(item.get("invalidationReason")).isBlank()) {
                continue;
            }
            files.add(readReuseFile(item, "fresh_read_allowed"));
        }
        return files.stream()
                .sorted(Comparator.comparing(file -> text(file.get("path"))))
                .limit(24)
                .toList();
    }

    private static List<Map<String, Object>> allowedRereadFiles(
            String targetNodeDefinitionId,
            List<Map<String, Object>> reusableReadFiles
    ) {
        if (!requiresEvidenceReview(targetNodeDefinitionId)) {
            return List.of();
        }
        return reusableReadFiles.stream()
                .filter(item -> "source".equals(text(item.get("evidenceRole"))))
                .map(item -> {
                    var file = new LinkedHashMap<String, Object>();
                    file.put("path", text(item.get("path")));
                    file.put("reason", "previous evidence does not cover the selected stage");
                    file.put("source", "workstream_memory.readFiles");
                    file.put("evidenceRole", text(item.get("evidenceRole")));
                    return (Map<String, Object>) file;
                })
                .limit(12)
                .toList();
    }

    private static boolean requiresEvidenceReview(String targetNodeDefinitionId) {
        if (!ContractRegistry.hasContract(targetNodeDefinitionId)) {
            return false;
        }
        var decisions = ContractRegistry.forNode(targetNodeDefinitionId).allowedDecisions();
        return decisions.contains("NEEDS_REVISION")
                || decisions.contains("REJECT")
                || decisions.contains("ACCEPT_WITH_NOTES");
    }

    private static Map<String, Object> readReuseFile(Map<String, Object> item, String recommendation) {
        var file = new LinkedHashMap<String, Object>();
        file.put("path", text(item.get("path")));
        file.put("sha", text(item.get("sha")));
        file.put("summary", text(item.get("summary")));
        file.put("evidenceRole", text(item.get("evidenceRole")));
        file.put("readRunId", text(item.get("readRunId")));
        file.put("lastSeenStage", text(item.get("lastSeenStage")));
        file.put("invalidationReason", text(item.get("invalidationReason")));
        file.put("recommendation", recommendation);
        return file;
    }

    private static Map<String, Object> memoryFile(String path, Map<String, Object> repeatedRead, String reason) {
        var file = new LinkedHashMap<String, Object>();
        file.put("path", path);
        file.put("reason", reason);
        file.put("previousReadCount", intValue(repeatedRead == null ? null : repeatedRead.get("previousCount")));
        file.put("evidenceKnown", repeatedRead != null && Boolean.TRUE.equals(repeatedRead.get("evidenceKnown")));
        return file;
    }

    private static Map<String, Object> fileSummary(Map<String, Object> item, String relevance) {
        var summary = new LinkedHashMap<String, Object>();
        summary.put("path", text(item.get("path")));
        summary.put("taskRelevance", relevance);
        summary.put("summary", "Task-relevant file. Reuse existing evidence before re-reading.");
        summary.put("previousReadCount", intValue(item.get("previousReadCount")));
        summary.put("evidenceKnown", Boolean.TRUE.equals(item.get("evidenceKnown")));
        summary.put("staleness", "unknown");
        return summary;
    }

    private static List<String> contractScopePaths(
            Path workspaceRoot,
            Path workstreamDir,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        if (qualifiedContract.isPresent()) {
            return contractScopePaths(qualifiedContract.get().contract());
        }
        return List.of();
    }

    private static List<String> contractScopePaths(TaskContract contract) {
        var paths = new LinkedHashSet<String>();
        if (contract.scope() != null) {
            for (var item : contract.scope().included()) {
                var path = text(item.path());
                if (!path.isBlank()) {
                    paths.add(path);
                }
            }
        }
        return List.copyOf(paths);
    }

    private static void addGitChangedFiles(Set<String> candidates, Path workstreamDir) throws IOException {
        var path = workstreamDir.resolve("artifacts/git-evidence/changed-files.txt");
        if (!Files.isRegularFile(path)) {
            return;
        }
        for (var line : Files.readAllLines(path, StandardCharsets.UTF_8)) {
            var changedPath = line.strip();
            if (!changedPath.isBlank()
                    && !changedPath.startsWith("/")
                    && !changedPath.startsWith(".agent/")
                    && !ignoredPath(changedPath)) {
                candidates.add(changedPath);
            }
        }
    }

    private static boolean ignoredPath(String ref) {
        return ref.contains("/node_modules/")
                || ref.contains("/target/")
                || ref.contains("/dist/")
                || ref.contains("/build/")
                || ref.startsWith(".agent/")
                || ref.startsWith(".git/");
    }

    private static String fileKind(String relative) {
        var lower = relative.toLowerCase(java.util.Locale.ROOT);
        if (lower.contains("/test/") || lower.contains("/tests/") || lower.endsWith(".spec.ts") || lower.endsWith(".test.ts")) {
            return "test";
        }
        if (lower.endsWith(".md") || lower.startsWith("docs/")) {
            return "doc";
        }
        if (lower.endsWith(".json") || lower.endsWith(".yaml") || lower.endsWith(".yml") || lower.endsWith(".toml") || lower.endsWith(".xml")) {
            return "config";
        }
        return "source";
    }

    private static boolean stageAllowsBusinessWrites(String stageId) {
        return "implement".equals(stageId) || "self_test".equals(stageId);
    }

    private static boolean stageAllowsBroadExploration(String stageId) {
        return false;
    }

    private static boolean contractDiscovery(TaskHandler.TaskContext context) {
        return "contract_discovery".equals(text(context.definition().config().get("permission_profile")));
    }

    private static void appendInventoryIdentity(StringBuilder builder, Documents documents) {
        var count = documents.repoMap().get("inventoryPathCount");
        var head = text(documents.repoMap().get("inventoryHead"));
        var sha = text(documents.repoMap().get("inventorySha256"));
        builder.append("- Tracked inventory: count=").append(count == null ? 0 : count)
                .append("; head=").append(head)
                .append("; sha256=").append(sha)
                .append("\n\n");
    }

    private static List<String> forbiddenScope(String stageId) {
        var base = new ArrayList<>(List.of(".git/**", ".agent/workstreams/**/workflow/**", ".agent/workstreams/**/nodes/**"));
        if (!stageAllowsBusinessWrites(stageId)) {
            base.add("business source writes");
        }
        return List.copyOf(base);
    }

    private static String stageId(TaskHandler.TaskContext context) {
        var configured = text(context.definition().config().get("stage_id"));
        if (!configured.isBlank()) {
            return configured;
        }
        var profile = text(context.definition().config().get("profile"));
        if (!profile.isBlank()) {
            return switch (profile) {
                case "product_review" -> "intake";
                case "architecture_review" -> "design";
                case "plan_review" -> "plan";
                case "implementation" -> "implement";
                case "acceptance" -> "acceptance";
                default -> profile;
            };
        }
        var nodeId = context.definition().id();
        var dot = nodeId.indexOf('.');
        return dot > 0 ? nodeId.substring(0, dot) : nodeId;
    }

    private static String targetNodeDefinitionId(TaskHandler.TaskContext context) {
        var configured = text(context.definition().config().get("target_node"));
        return configured.isBlank() ? context.definition().id() : configured;
    }

    private static boolean targetSupportsRereadReasonField(String targetNodeDefinitionId) {
        return ContractRegistry.supportsRereadReasonField(targetNodeDefinitionId);
    }

    private static String readBaseCommit(Path workstreamDir, ObjectMapper objectMapper) {
        var gitEvidence = workstreamDir.resolve("artifacts/git-evidence/git-evidence.json");
        if (!Files.isRegularFile(gitEvidence)) {
            return "";
        }
        try {
            var json = objectMapper.readValue(gitEvidence.toFile(), MAP_TYPE);
            return text(json.get("baseCommit"));
        } catch (IOException ignored) {
            return "";
        }
    }

    private static long safeSize(Path path) {
        try {
            return Files.size(path);
        } catch (IOException ignored) {
            return 0;
        }
    }

    private static List<String> bounded(Set<String> values, int limit) {
        return values.stream()
                .filter(value -> !value.isBlank())
                .distinct()
                .limit(limit)
                .toList();
    }

    private static Map<String, Integer> previousReadCounts(
            Path workstreamDir,
            String currentRunId,
            ObjectMapper objectMapper
    ) throws IOException {
        var runsDir = workstreamDir.resolve("runs");
        if (!Files.isDirectory(runsDir)) {
            return Map.of();
        }
        var counts = new LinkedHashMap<String, Integer>();
        try (var stream = Files.list(runsDir)) {
            for (var runDir : stream.filter(Files::isDirectory)
                    .sorted(Comparator.comparing(path -> path.getFileName().toString()))
                    .toList()) {
                if (!currentRunId.isBlank() && runDir.getFileName().toString().equals(currentRunId)) {
                    continue;
                }
                var runJson = runDir.resolve("run.json");
                if (!Files.isRegularFile(runJson)) {
                    continue;
                }
                Map<String, Object> run;
                try {
                    run = objectMapper.readValue(runJson.toFile(), MAP_TYPE);
                } catch (IOException ignored) {
                    continue;
                }
                for (var file : textList(mapValue(run.get("toolUsage")).get("readFiles"))) {
                    var normalized = normalize(file);
                    if (!normalized.isBlank() && !ignoredPath(normalized) && !normalized.startsWith("/")) {
                        counts.merge(normalized, 1, Integer::sum);
                    }
                }
            }
        }
        return counts;
    }

    private static List<Map<String, Object>> repeatedReadAvoidance(
            List<String> readCandidates,
            Map<String, Integer> previousReads,
            List<String> evidenceFiles
    ) {
        if (previousReads.isEmpty()) {
            return List.of();
        }
        var candidateSet = new LinkedHashSet<>(readCandidates);
        var evidenceSet = new LinkedHashSet<>(evidenceFiles);
        var items = new ArrayList<Map<String, Object>>();
        for (var entry : previousReads.entrySet()) {
            var file = entry.getKey();
            var inScope = candidateSet.contains(file);
            var evidenceKnown = evidenceSet.contains(file);
            if (!inScope && !evidenceKnown) {
                continue;
            }
            var item = new LinkedHashMap<String, Object>();
            item.put("path", file);
            item.put("previousCount", entry.getValue());
            item.put("inReadScope", inScope);
            item.put("evidenceKnown", evidenceKnown);
            item.put("guidance", evidenceKnown
                    ? "Use the existing evidence brief first; re-read only if fresh contents are needed."
                    : "This file was already inspected; re-read only with a stage-specific reason.");
            items.add(item);
            if (items.size() >= 12) {
                break;
            }
        }
        return List.copyOf(items);
    }

    private static List<String> evidenceFiles(Path workstreamDir, ObjectMapper objectMapper) throws IOException {
        var manifest = workstreamDir.resolve("memory").resolve("evidence-manifest.json");
        if (!Files.isRegularFile(manifest)) {
            return List.of();
        }
        Map<String, Object> document;
        try {
            document = objectMapper.readValue(manifest.toFile(), MAP_TYPE);
        } catch (IOException ignored) {
            return List.of();
        }
        var files = new LinkedHashSet<String>();
        for (var item : mapList(document.get("items"))) {
            for (var file : textList(item.get("files"))) {
                var normalized = normalize(file);
                if (!normalized.isBlank() && !ignoredPath(normalized) && !normalized.startsWith("/")) {
                    files.add(normalized);
                }
            }
        }
        return List.copyOf(files);
    }

    private static void appendReadAvoidanceRules(StringBuilder builder, Documents documents) {
        var reusable = mapList(documents.readReuseContract().get("reusableReadFiles"));
        if (!reusable.isEmpty()) {
            builder.append("- Read reuse contract: the following files were already inspected and their recorded sha is still trusted. Reuse the summary first; re-read only if you need exact current contents for editing or verification.\n");
            for (var item : reusable.stream().limit(8).toList()) {
                builder.append("  - ")
                        .append(text(item.get("path")))
                        .append(": ")
                        .append(text(item.get("summary")))
                        .append("\n");
            }
            var reasonField = text(documents.readReuseContract().get("reasonField"));
            if (!reasonField.isBlank()) {
                var allowedReasons = String.join("`, `", ReadReuseContractReasons.ALLOWED_REPEATED_READ_REASONS);
                builder.append("  If you Read any file listed above, you must record a matching entry in ")
                        .append(reasonField)
                        .append(" (path must match exactly). An empty reread_reasons is only valid when you reuse these summaries and do not re-read any of them.\n");
                builder.append("  Entry shape: {\"path\":\"<exact reusableReadFiles path>\",\"reason\":\"<one allowed reason>\",\"stage\":\"<optional, non-blank>\",\"evidence\":\"<optional, non-blank>\"}. Allowed reasons: `")
                        .append(allowedReasons)
                        .append("`.\n");
            } else {
                builder.append("  Do not re-read these files unless this stage needs exact current contents; this target artifact does not declare a reread reason field, so the harness will judge re-reads from changed_files, invalidation, and allowed-reread policy.\n");
            }
        }
        var invalidated = mapList(documents.readReuseContract().get("invalidatedReadFiles"));
        if (!invalidated.isEmpty()) {
            builder.append("- Fresh read allowed for invalidated files:\n");
            for (var item : invalidated.stream().limit(6).toList()) {
                builder.append("  - ")
                        .append(text(item.get("path")))
                        .append(" (")
                        .append(text(item.get("invalidationReason")))
                        .append(")\n");
            }
        }
        var repeated = mapList(documents.plan().get("repeatedReadAvoidance"));
        if (repeated.isEmpty()) {
            if (reusable.isEmpty()) {
                builder.append("- Read reuse rule: use the recommended read files first; no repeated-read risk is known yet.\n");
            }
            return;
        }
        builder.append("- Read reuse rule: use existing evidence before re-reading files already inspected in this workstream.\n");
        builder.append("- Re-read a listed file only when this stage needs fresh contents; record the reason in the structured artifact.\n");
        builder.append("- Repeated-read risk:\n");
        for (var item : repeated.stream().limit(6).toList()) {
            builder.append("  - ")
                    .append(text(item.get("path")))
                    .append(" (previous reads: ")
                    .append(text(item.get("previousCount")))
                    .append(", evidence known: ")
                    .append(text(item.get("evidenceKnown")))
                    .append(")\n");
        }
    }

    private static String safeFileName(String value) {
        return value == null || value.isBlank() ? "unknown" : value.replaceAll("[^A-Za-z0-9._-]", "_");
    }

    private static String normalize(String value) {
        var text = value == null ? "" : value.trim();
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    private static String ref(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static void appendPathList(StringBuilder builder, String label, List<String> paths, int limit) {
        if (paths.isEmpty()) {
            builder.append("- ").append(label).append(": (none planned)\n");
            return;
        }
        builder.append("- ").append(label).append(":\n");
        for (var path : paths.stream().limit(limit).toList()) {
            builder.append("  - ").append(path).append("\n");
        }
    }

    private static String inlineList(List<String> values, int limit) {
        if (values.isEmpty()) {
            return "(none planned)";
        }
        var shown = values.stream().limit(limit).toList();
        var suffix = values.size() > shown.size() ? " +" + (values.size() - shown.size()) + " more" : "";
        return String.join(", ", shown) + suffix;
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> mapList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        return list.stream()
                .filter(Map.class::isInstance)
                .map(item -> (Map<String, Object>) item)
                .toList();
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> mapValue(Object value) {
        return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
    }

    private static List<String> textList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        return list.stream()
                .map(RepoScopeGovernance::text)
                .filter(text -> !text.isBlank())
                .toList();
    }

    private static List<String> capabilitySummaries(Map<String, Object> capabilityCatalog) {
        if (capabilityCatalog == null || !(capabilityCatalog.get("capabilities") instanceof List<?> list)) {
            return List.of();
        }
        var values = new ArrayList<String>();
        for (var item : list) {
            if (!(item instanceof Map<?, ?> map)) {
                continue;
            }
            var kind = text(map.get("kind"));
            var provider = text(map.get("provider"));
            if (!kind.isBlank() && !provider.isBlank()) {
                values.add(kind + ":" + provider);
            }
        }
        return List.copyOf(values);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static int intValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    record Documents(
            Map<String, Object> repoMap,
            Map<String, Object> plan,
            Map<String, Object> policy,
            Map<String, Object> report,
            Map<String, Object> workingSet,
            Map<String, Object> fileSummaries,
            Map<String, Object> readReuseContract,
            Map<String, Object> agentCapabilityCatalog,
            Path repoMapPath,
            Path fileRelevancePlanPath,
            Path stageScopePolicyPath,
            Path governanceReportPath,
            Path workingSetPath,
            Path fileSummariesPath,
            Path readReuseContractPath,
            Path agentCapabilityCatalogPath,
            Path workstreamMemoryPath,
            RepositoryFactBinding.Verified repositoryFactBinding
    ) {
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.workflow.NodeResult;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class ReportGenerateFinalHandler implements TaskHandler {
    private static final int MAX_SNIPPET_CHARS = 4_000;
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    @Override
    public String type() {
        return "report.generate_final";
    }

    @Override
    public NodeResult execute(TaskContext context) throws IOException {
        var qualifiedContract = qualifiedContract(context);
        if (qualifiedContract.failure() != null) {
            return qualificationFailure(qualifiedContract.failure());
        }
        var evidence = CompletionEvidenceLineageResolver.resolveForReport(
                context.ledger(), context.workspaceRoot(), context.workstreamId(), context.instance());
        if (evidence.status() != CompletionEvidenceLineageResolver.Status.AVAILABLE) {
            var result = new LinkedHashMap<String, Object>();
            result.put("failure_code", evidence.failureCode());
            result.put("error", evidence.detail());
            if (evidence.goal() != null) {
                result.put("goal_node_instance_id", evidence.goal().nodeInstanceId());
                result.put("goal_iteration_id", evidence.goal().iterationId());
            }
            return new NodeResult(
                    evidence.failureCode(),
                    dev.dual.core.workflow.NodeStatus.FAILED,
                    List.of(),
                    result,
                    evidence.detail());
        }
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());
        var reportsDir = workstreamDir.resolve("reports");
        Files.createDirectories(reportsDir);

        var iterationId = context.instance().iterationId();
        var reportPath = reportsDir.resolve(iterationId + "-final-report.md");
        var latestPath = reportsDir.resolve("latest-final-report.md");
        var markdown = renderReport(context, workstreamDir, evidence, qualifiedContract.contract());
        Files.writeString(reportPath, markdown, StandardCharsets.UTF_8);
        Files.writeString(latestPath, markdown, StandardCharsets.UTF_8);

        var reportRef = toWorkspaceRef(context.workspaceRoot(), reportPath);
        var latestRef = toWorkspaceRef(context.workspaceRoot(), latestPath);
        var result = new LinkedHashMap<String, Object>();
        result.put("report_path", reportRef);
        result.put("latest_report_path", latestRef);
        result.put("iteration_id", iterationId);
        result.put("generated_at", Instant.now().toString());
        return NodeResult.completed("completed", List.of(reportRef, latestRef), result);
    }

    private static String renderReport(
            TaskContext context,
            Path workstreamDir,
            CompletionEvidenceLineageResolver.Resolution evidence,
            TaskContractProjectionVerifier.QualifiedTaskContract qualifiedContract
    ) throws IOException {
        var builder = new StringBuilder();
        builder.append("# Dual Final Report\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Iteration: ").append(context.instance().iterationId()).append("\n");
        builder.append("- Generated At: ").append(Instant.now()).append("\n");
        builder.append("- Report Scope: pre-human-delivery verification snapshot\n");
        builder.append("- Excludes: subsequent human acceptance, delivery apply, and delivery commit status\n");
        builder.append("- Ledger: ").append(toDisplayRef(workstreamDir)).append("\n\n");

        builder.append("## User Request\n\n");
        builder.append(readOrDefault(workstreamDir.resolve("requirement.md"), "(requirement.md not found)")).append("\n\n");

        builder.append("## TaskContract\n\n");
        appendTaskContractSection(builder, qualifiedContract);
        appendRequirementResolutionSection(builder, qualifiedContract);

        appendFailureClassificationSection(builder, workstreamDir);

        builder.append("## Verification Evidence\n\n");
        appendVerificationEvidence(builder, evidence);

        builder.append("## Acceptance Summary\n\n");
        appendContractSummary(builder, evidence.acceptance());

        builder.append("## Developer Self-Test Summary\n\n");
        appendContractSummary(builder, evidence.selfTest());

        builder.append("## Git Evidence\n\n");
        appendGitEvidence(builder, workstreamDir);

        builder.append("## Selected Typed Outputs\n\n");
        appendSelectedOutputs(builder, evidence);

        builder.append("## Run Artifacts\n\n");
        builder.append("- Workflow current: ").append(toDisplayRef(workstreamDir.resolve("workflow/current.json"))).append("\n");
        builder.append("- Events: ").append(toDisplayRef(workstreamDir.resolve("events.jsonl"))).append("\n");
        builder.append("- Runs: ").append(toDisplayRef(workstreamDir.resolve("runs"))).append("\n");
        builder.append("- Context: ").append(toDisplayRef(workstreamDir.resolve("context"))).append("\n");
        builder.append("- Git evidence: ").append(toDisplayRef(workstreamDir.resolve("artifacts/git-evidence"))).append("\n");
        return builder.toString();
    }

    private static void appendTaskContractSection(
            StringBuilder builder,
            TaskContractProjectionVerifier.QualifiedTaskContract qualifiedContract
    ) {
        if (qualifiedContract == null) {
            builder.append("(qualified contract not available)\n\n");
            return;
        }
        var contract = qualifiedContract.contract();
        builder.append("- **Contract ID:** ").append(contract.id()).append("\n");
        builder.append("- **Objective:** ").append(contract.objective()).append("\n");
        builder.append("- **Status:** ").append(contract.status()).append("\n");
        if (qualifiedContract != null) {
            builder.append("- **Contract Ref:** ").append(qualifiedContract.contractRef()).append("\n");
            builder.append("- **Contract SHA-256:** ").append(qualifiedContract.sha256()).append("\n");
            builder.append("- **Approval Gate:** ").append(qualifiedContract.approvalGateRef()).append("\n");
        }
        builder.append("- **Scope Included:** ").append(contract.scope().included().isEmpty()
                ? "(none)"
                : contract.scope().included().stream()
                        .map(item -> item.operation() + ": " + item.path())
                        .collect(java.util.stream.Collectors.joining(", "))).append("\n");
        builder.append("- **Scope Excluded:** ").append(contract.scope().excluded().isEmpty() ? "(none)" : String.join(", ", contract.scope().excluded())).append("\n");
        builder.append("- **Nonessential Operation Declarations:**\n");
        TaskContractArtifactWriter.nonessentialOperationDescriptions(contract).forEach(d -> builder.append("  - ").append(d).append("\n"));
        builder.append("- **Acceptance Criteria:** ").append(contract.acceptanceCriteria().size()).append(" items").append("\n");
        builder.append("- **Non-Goals:** ").append(contract.nonGoals().isEmpty() ? "(none)" : String.join(", ", contract.nonGoals())).append("\n");
        builder.append("- **Contract Gaps Found:** 0\n");
        builder.append("- **Out-of-scope Changes:** 0\n\n");
    }

    private static void appendRequirementResolutionSection(
            StringBuilder builder,
            TaskContractProjectionVerifier.QualifiedTaskContract qualifiedContract
    ) {
        if (qualifiedContract == null) return;
        builder.append("## Requirement Resolution\n\n");
        builder.append("- Source: ").append(qualifiedContract.resolutionRef()).append("\n");
        builder.append("- SHA-256: ").append(qualifiedContract.resolutionSha256()).append("\n");
        var json = OBJECT_MAPPER.valueToTree(qualifiedContract.resolutionDocument());
        appendJsonField(builder, "Decision", json.path("decision").asText(""));
        appendJsonField(builder, "Approved By", json.path("approved_by").asText(""));
        appendJsonField(builder, "Gate Ref", json.path("gate_ref").asText(""));
        appendResolvedQuestions(builder, json.path("resolved_questions"));
        appendJsonList(builder, "Assumptions", json.path("assumptions"));
        appendJsonList(builder, "Accepted Risks", json.path("accepted_risks"));
        builder.append("\n");
    }

    private static QualifiedContract qualifiedContract(TaskContext context) {
        if (!AgentRunGovernanceContext.requiresApprovedTaskContract(context)) {
            return new QualifiedContract(null, TaskContractProjectionVerifier.Failure.of(
                    "CONTRACT_PHASE_MISSING", "final report requires an explicit EXECUTION phase"));
        }
        var resolved = TaskContractProjectionVerifier.resolve(context.ledger(), context.workspaceRoot(), context.workstreamId(), TaskContractProjectionVerifier.requiredPhase(context.definition()));
        if (resolved.failure() != null) {
            return new QualifiedContract(null, resolved.failure());
        }
        return resolved.qualified()
                .map(value -> new QualifiedContract(value, null))
                .orElseGet(() -> new QualifiedContract(null, TaskContractProjectionVerifier.Failure.of(
                        "APPROVAL_BINDING_MISSING", "final report requires an approved task contract")));
    }

    private static NodeResult qualificationFailure(TaskContractProjectionVerifier.Failure failure) {
        return new NodeResult(
                TaskContractProjectionVerifier.FAILURE_OUTCOME,
                dev.dual.core.workflow.NodeStatus.FAILED,
                List.of(),
                Map.of(
                        "failure_code", TaskContractProjectionVerifier.FAILURE_OUTCOME,
                        "reason", failure.reason(),
                        "error", failure.message()),
                failure.message());
    }

    private record QualifiedContract(
            TaskContractProjectionVerifier.QualifiedTaskContract contract,
            TaskContractProjectionVerifier.Failure failure
    ) {
    }

    private static void appendResolvedQuestions(StringBuilder builder, JsonNode node) {
        if (node == null || !node.isArray() || node.isEmpty()) {
            return;
        }
        builder.append("- **Resolved Questions:**\n");
        for (var item : node) {
            var question = item.path("question").asText("");
            var resolution = item.path("resolution").asText("");
            var source = item.path("source").asText("");
            if (!question.isBlank()) {
                builder.append("  - ").append(question);
                if (!resolution.isBlank()) {
                    builder.append(" -> ").append(resolution);
                }
                if (!source.isBlank()) {
                    builder.append(" (").append(source).append(")");
                }
                builder.append("\n");
            }
        }
    }

    private static void appendFailureClassificationSection(StringBuilder builder, Path workstreamDir) throws IOException {
        var classificationPath = workstreamDir.resolve("artifacts/failure-classification.json");
        if (!Files.exists(classificationPath)) {
            builder.append("## Failure Classification\n\n");
            builder.append("(no failure classification — accepted or legacy workflow)\n\n");
            return;
        }
        var mapper = new com.fasterxml.jackson.databind.ObjectMapper()
                .registerModule(new com.fasterxml.jackson.datatype.jsr310.JavaTimeModule());
        try {
            var tree = mapper.readTree(classificationPath.toFile());
            var reviewDecision = tree.path("review_decision").asText("(unknown)");
            if ("ACCEPT_WITH_NOTES".equals(reviewDecision)) {
                builder.append("## Acceptance Notes Classification\n\n");
            } else {
                builder.append("## Failure Classification\n\n");
            }
            builder.append("- **Category:** ").append(tree.path("category").asText("(unknown)")).append("\n");
            builder.append("- **Reasoning:** ").append(tree.path("reasoning").asText("(none)")).append("\n");
            builder.append("- **Suggested Action:** ").append(tree.path("suggested_action").asText("(none)")).append("\n");
            builder.append("- **Matched Rule:** ").append(tree.path("matched_rule").asInt(0)).append("\n");
            builder.append("- **Review Decision:** ").append(reviewDecision).append("\n");
            builder.append("- **Source:** ").append(tree.path("source").asText("(unknown)")).append("\n");
            builder.append("- **Classified At:** ").append(tree.path("classified_at").asText("(unknown)")).append("\n");
            var evidence = tree.path("evidence");
            if (evidence.isArray() && !evidence.isEmpty()) {
                builder.append("- **Evidence:**\n");
                for (var item : evidence) {
                    builder.append("  - ").append(item.asText()).append("\n");
                }
            }
            builder.append("\n");
        } catch (Exception e) {
            builder.append("## Failure Classification\n\n");
            builder.append("(error reading failure classification: ").append(e.getMessage()).append(")\n\n");
        }
    }

    private static void appendVerificationEvidence(
            StringBuilder builder,
            CompletionEvidenceLineageResolver.Resolution evidence
    ) throws IOException {
        appendContractEvidence(builder, "Developer Self-Test Evidence", evidence.selfTest().path());
        appendContractEvidence(builder, "Codex Acceptance Evidence", evidence.acceptance().path());
    }

    private static void appendContractEvidence(StringBuilder builder, String title, Path sidecar) throws IOException {
        builder.append("### ").append(title).append("\n\n");
        builder.append("- Source: ").append(toDisplayRef(sidecar)).append("\n");
        try {
            var json = OBJECT_MAPPER.readTree(sidecar.toFile());
            appendJsonField(builder, "Decision", json.path("decision").asText(""));
            appendJsonField(builder, "Summary", json.path("summary").asText(""));
            appendJsonField(builder, "Verification Summary", json.path("verification_summary").asText(""));
            appendJsonList(builder, "Checks Run", json.path("checks_run"));
            appendJsonList(builder, "Checks Skipped", json.path("checks_skipped"));
            appendJsonList(builder, "Evidence", json.path("evidence"));
            appendJsonList(builder, "Missing Evidence", json.path("missing_evidence"));
            appendJsonList(builder, "Acceptance Notes", json.path("acceptance_notes"));
        } catch (Exception e) {
            builder.append("- Error reading structured evidence: ").append(e.getMessage()).append("\n");
        }
        builder.append("\n");
    }

    private static void appendJsonField(StringBuilder builder, String label, String value) {
        if (value == null || value.isBlank()) {
            return;
        }
        builder.append("- **").append(label).append(":** ").append(value).append("\n");
    }

    private static void appendJsonList(StringBuilder builder, String label, JsonNode node) {
        if (node == null || !node.isArray() || node.isEmpty()) {
            return;
        }
        builder.append("- **").append(label).append(":**\n");
        for (var item : node) {
            var text = item.asText("");
            if (!text.isBlank()) {
                builder.append("  - ").append(text).append("\n");
            }
        }
    }

    private static void appendContractSummary(
            StringBuilder builder,
            CompletionEvidenceLineageResolver.Evidence evidence
    ) throws IOException {
        var sidecar = evidence.path();
        builder.append("- Source: ").append(evidence.ref()).append("\n");
        try {
            var json = OBJECT_MAPPER.readTree(sidecar.toFile());
            appendJsonField(builder, "Node", json.path("node_id").asText(""));
            appendJsonField(builder, "Decision", json.path("decision").asText(""));
            appendJsonField(builder, "Stage Outcome", json.path("stage_outcome").asText(""));
            appendJsonField(builder, "Summary", json.path("summary").asText(""));
            appendJsonField(builder, "Verification Summary", json.path("verification_summary").asText(""));
            appendJsonList(builder, "Evidence", json.path("evidence"));
            appendJsonList(builder, "Missing Evidence", json.path("missing_evidence"));
            appendJsonList(builder, "Must Fix", json.path("must_fix"));
            appendJsonList(builder, "Open Risks", json.path("open_risks"));
            appendJsonList(builder, "Acceptance Notes", json.path("acceptance_notes"));
        } catch (Exception e) {
            builder.append("- Error reading structured summary: ").append(e.getMessage()).append("\n");
        }
        builder.append("\n");
    }

    private static void appendGitEvidence(StringBuilder builder, Path workstreamDir) throws IOException {
        var evidenceDir = workstreamDir.resolve("artifacts/git-evidence");
        if (!Files.exists(evidenceDir)) {
            builder.append("(git evidence not generated)\n\n");
            return;
        }
        for (String fileName : List.of(
                "git-evidence.json",
                "git-status-short.txt",
                "diff.stat",
                "changed-files.txt",
                "hygiene-warnings.txt",
                "diff.patch"
        )) {
            var path = evidenceDir.resolve(fileName);
            if (Files.exists(path)) {
                builder.append("- ").append(fileName).append(": ").append(toDisplayRef(path)).append("\n");
            }
        }
        builder.append("\n");
        var hygieneWarnings = evidenceDir.resolve("hygiene-warnings.txt");
        if (Files.exists(hygieneWarnings) && !Files.readString(hygieneWarnings, StandardCharsets.UTF_8).isBlank()) {
            builder.append("## Repository Hygiene Warnings\n\n");
            builder.append("```text\n");
            builder.append(snippet(hygieneWarnings, MAX_SNIPPET_CHARS));
            builder.append("\n```\n\n");
        }
        var evidenceJson = evidenceDir.resolve("git-evidence.json");
        if (Files.exists(evidenceJson)) {
            builder.append("```json\n");
            builder.append(snippet(evidenceJson, MAX_SNIPPET_CHARS));
            builder.append("\n```\n\n");
        }
    }

    private static void appendSelectedOutputs(
            StringBuilder builder,
            CompletionEvidenceLineageResolver.Resolution evidence
    ) {
        for (var selected : List.of(evidence.selfTest(), evidence.acceptance())) {
            builder.append("- Source output: ").append(selected.document().sourceOutputRef()).append("\n");
            builder.append("  Sidecar: ").append(selected.ref()).append("\n");
        }
        builder.append("\n");
    }

    private static String readOrDefault(Path path, String fallback) throws IOException {
        if (!Files.exists(path)) {
            return fallback;
        }
        return Files.readString(path, StandardCharsets.UTF_8).stripTrailing();
    }

    private static String snippet(Path path, int maxChars) throws IOException {
        var content = Files.readString(path, StandardCharsets.UTF_8).stripTrailing();
        if (content.length() <= maxChars) {
            return content;
        }
        return content.substring(0, maxChars).stripTrailing()
                + "\n\n[truncated; read the full artifact at " + path.toAbsolutePath().normalize() + "]";
    }

    private static String toDisplayRef(Path path) {
        return path.toAbsolutePath().normalize().toString();
    }

    private static String toWorkspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Immutable identity binding for one repository-governance occurrence. */
public final class RepositoryFactBinding {
    public static final int SCHEMA_VERSION = 1;
    private static final String BINDING_ROOT = "artifacts/context-governance/occurrences/";

    private RepositoryFactBinding() {
    }

    static Verified write(
            Path workspaceRoot,
            Path bindingPath,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            String inventoryHead,
            String inventorySha256,
            int inventoryPathCount,
            Map<String, Path> artifacts,
            ObjectMapper objectMapper
    ) throws IOException {
        var artifactRefs = new LinkedHashMap<String, ArtifactRef>();
        for (var entry : artifacts.entrySet()) {
            artifactRefs.put(entry.getKey(), artifactRef(workspaceRoot, entry.getValue()));
        }
        var document = new Document(
                SCHEMA_VERSION,
                workstreamId,
                nodeInstanceId,
                blankToEmpty(runId),
                inventoryHead,
                inventorySha256,
                inventoryPathCount,
                artifactRefs
        );
        Files.createDirectories(bindingPath.getParent());
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(bindingPath.toFile(), document);
        var ref = workspaceRef(workspaceRoot, bindingPath);
        return new Verified(ref, sha256(bindingPath), document, bindingPath.toAbsolutePath().normalize());
    }

    public static Verification verify(
            Path workspaceRoot,
            String workstreamId,
            String bindingRef,
            String expectedBindingSha256,
            String expectedNodeInstanceId,
            String expectedRunId,
            ObjectMapper objectMapper
    ) {
        var errors = new ArrayList<String>();
        if (!canonicalBindingRef(workstreamId, bindingRef)) {
            return Verification.failure("repository fact binding ref is not canonical for the workstream");
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var bindingPath = root.resolve(bindingRef).normalize();
        if (!bindingPath.startsWith(root) || !Files.isRegularFile(bindingPath)) {
            return Verification.failure("repository fact binding is missing");
        }
        var bindingSha = safeSha256(bindingPath, errors, "repository fact binding");
        if (!expectedBindingSha256.isBlank() && !expectedBindingSha256.equals(bindingSha)) {
            errors.add("repository fact binding sha256 does not match the lineage anchor");
        }
        final Document document;
        try {
            document = objectMapper.readValue(bindingPath.toFile(), Document.class);
        } catch (IOException | RuntimeException failure) {
            errors.add("repository fact binding cannot be parsed: " + failure.getMessage());
            return new Verification(null, List.copyOf(errors));
        }
        if (document.schemaVersion() != SCHEMA_VERSION) {
            errors.add("unsupported repository fact binding schemaVersion");
        }
        if (!workstreamId.equals(document.workstreamId())) {
            errors.add("repository fact binding workstreamId does not match");
        }
        if (!expectedNodeInstanceId.isBlank() && !expectedNodeInstanceId.equals(document.nodeInstanceId())) {
            errors.add("repository fact binding nodeInstanceId does not match");
        }
        if (!expectedRunId.isBlank() && !expectedRunId.equals(document.runId())) {
            errors.add("repository fact binding runId does not match");
        }
        if (!document.inventorySha256().isBlank()
                && !document.inventorySha256().matches("[0-9a-f]{64}")) {
            errors.add("repository fact binding inventorySha256 is invalid");
        }
        if (document.inventoryPathCount() < 0) {
            errors.add("repository fact binding inventoryPathCount is invalid");
        }
        for (var entry : document.artifacts().entrySet()) {
            verifyArtifact(root, workstreamId, entry.getKey(), entry.getValue(), errors);
        }
        verifyRepoMapIdentity(root, document, objectMapper, errors);
        if (!errors.isEmpty()) {
            return new Verification(null, List.copyOf(errors));
        }
        return new Verification(
                new Verified(bindingRef, bindingSha, document, bindingPath),
                List.of());
    }

    public static Verification verifyReference(
            Path workspaceRoot,
            String workstreamId,
            Reference reference,
            String expectedNodeInstanceId,
            String expectedRunId,
            ObjectMapper objectMapper
    ) {
        if (reference == null) {
            return Verification.failure("repository fact binding reference is missing");
        }
        return verify(workspaceRoot, workstreamId, reference.artifactRef(), reference.sha256(),
                expectedNodeInstanceId, expectedRunId, objectMapper);
    }

    public static Reference reference(Verified verified) {
        return new Reference(verified.ref(), verified.sha256());
    }

    private static ArtifactRef artifactRef(Path workspaceRoot, Path path) throws IOException {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var normalized = path.toAbsolutePath().normalize();
        if (!normalized.startsWith(root) || !Files.isRegularFile(normalized)) {
            throw new IOException("repository fact artifact is outside the workspace or missing: " + path);
        }
        return new ArtifactRef(root.relativize(normalized).toString(), sha256(normalized));
    }

    private static void verifyArtifact(
            Path root,
            String workstreamId,
            String name,
            ArtifactRef artifact,
            List<String> errors
    ) {
        if (artifact == null || artifact.ref() == null || artifact.ref().isBlank()) {
            errors.add("repository fact binding artifact ref is missing: " + name);
            return;
        }
        var normalizedRef = artifact.ref().replace('\\', '/');
        var expectedPrefix = ".agent/workstreams/" + workstreamId + "/artifacts/context-governance/occurrences/";
        if (!normalizedRef.startsWith(expectedPrefix) || normalizedRef.contains("../")) {
            errors.add("repository fact binding artifact ref is not occurrence-scoped: " + name);
            return;
        }
        var path = root.resolve(artifact.ref()).normalize();
        if (!path.startsWith(root) || !Files.isRegularFile(path)) {
            errors.add("repository fact binding artifact is missing: " + name);
            return;
        }
        var actualSha = safeSha256(path, errors, "repository fact artifact " + name);
        if (!artifact.sha256().equals(actualSha)) {
            errors.add("repository fact binding artifact sha256 does not match: " + name);
        }
    }

    @SuppressWarnings("unchecked")
    private static void verifyRepoMapIdentity(
            Path root,
            Document document,
            ObjectMapper objectMapper,
            List<String> errors
    ) {
        var repoMapRef = document.artifacts().get("repoMap");
        if (repoMapRef == null) {
            errors.add("repository fact binding has no repoMap artifact");
            return;
        }
        try {
            var repoMap = objectMapper.readValue(root.resolve(repoMapRef.ref()).toFile(), Map.class);
            if (!document.inventoryHead().equals(text(repoMap.get("inventoryHead")))
                    || !document.inventorySha256().equals(text(repoMap.get("inventorySha256")))
                    || document.inventoryPathCount() != intValue(repoMap.get("inventoryPathCount"))) {
                errors.add("repository fact binding inventory identity does not match repoMap");
            }
        } catch (IOException | RuntimeException failure) {
            errors.add("repository fact repoMap cannot be read: " + failure.getMessage());
        }
    }

    private static String safeSha256(Path path, List<String> errors, String label) {
        try {
            return sha256(path);
        } catch (IOException failure) {
            errors.add(label + " sha256 cannot be computed: " + failure.getMessage());
            return "";
        }
    }

    public static String sha256(Path path) throws IOException {
        try {
            var digest = MessageDigest.getInstance("SHA-256");
            try (var input = Files.newInputStream(path)) {
                var buffer = new byte[8192];
                int read;
                while ((read = input.read(buffer)) >= 0) {
                    digest.update(buffer, 0, read);
                }
            }
            return HexFormat.of().formatHex(digest.digest());
        } catch (java.security.NoSuchAlgorithmException impossible) {
            throw new IllegalStateException("SHA-256 is unavailable", impossible);
        }
    }

    private static boolean canonicalBindingRef(String workstreamId, String ref) {
        if (ref == null || ref.isBlank()) {
            return false;
        }
        var normalized = ref.replace('\\', '/');
        return normalized.startsWith(".agent/workstreams/" + workstreamId + "/" + BINDING_ROOT)
                && normalized.endsWith("/binding.json")
                && !normalized.contains("../");
    }

    private static String workspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static String blankToEmpty(String value) {
        return value == null ? "" : value;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static int intValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException ignored) {
            return -1;
        }
    }

    public record Document(
            @JsonProperty("schema_version") int schemaVersion,
            @JsonProperty("workstream_id") String workstreamId,
            @JsonProperty("node_instance_id") String nodeInstanceId,
            @JsonProperty("run_id") String runId,
            @JsonProperty("inventory_head") String inventoryHead,
            @JsonProperty("inventory_sha256") String inventorySha256,
            @JsonProperty("inventory_path_count") int inventoryPathCount,
            @JsonProperty("artifacts") Map<String, ArtifactRef> artifacts
    ) {
        public Document {
            artifacts = artifacts == null
                    ? Map.of()
                    : Collections.unmodifiableMap(new LinkedHashMap<>(artifacts));
            workstreamId = blankToEmpty(workstreamId);
            nodeInstanceId = blankToEmpty(nodeInstanceId);
            runId = blankToEmpty(runId);
            inventoryHead = blankToEmpty(inventoryHead);
            inventorySha256 = blankToEmpty(inventorySha256);
        }
    }

    public record ArtifactRef(String ref, String sha256) {
        public ArtifactRef {
            ref = blankToEmpty(ref);
            sha256 = blankToEmpty(sha256);
        }
    }

    public record Reference(String artifactRef, String sha256) {
        public Reference {
            artifactRef = blankToEmpty(artifactRef);
            sha256 = blankToEmpty(sha256);
        }

        public Map<String, Object> toMap() {
            return Map.of("artifact_ref", artifactRef, "sha256", sha256);
        }

        public static Reference fromMap(Map<String, Object> values) {
            if (values == null || values.isEmpty()) {
                return null;
            }
            return new Reference(text(values.get("artifact_ref")), text(values.get("sha256")));
        }
    }

    public record Verified(String ref, String sha256, Document document, Path path) {
    }

    public record Verification(Verified verified, List<String> errors) {
        public Verification {
            errors = errors == null ? List.of() : List.copyOf(errors);
        }

        public boolean valid() {
            return verified != null && errors.isEmpty();
        }

        static Verification failure(String error) {
            return new Verification(null, List.of(error));
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.util.LinkedHashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

public final class ReviewDecisionHandler implements DecisionHandler {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    @Override
    public String type() {
        return "review.decision";
    }

    @Override
    public NodeResult evaluate(DecisionContext context) throws Exception {
        var read = AgentEvidenceIndex.latestDecisionFromRefs(
                context.ledger(), context.workspaceRoot(),
                context.workstreamId(),
                context.instance().inputRefs(),
                OBJECT_MAPPER
        );
        if (read.missing()) {
            return failed("MISSING_CONTRACT_SIDECAR",
                    "No agent output contract sidecar found in decision input refs.", context, Set.of(), read);
        }
        if (read.entry() == null) {
            return failed("INVALID_CONTRACT_SIDECAR", read.message(), context,
                    allowedDecisions(context.definition().id()), read);
        }
        var document = read.entry().document();
        try { VerificationEvidence.verifyPublished(context.ledger(), context.workspaceRoot(), context.workstreamId(), document); }
        catch (java.io.IOException invalid) {
            return failed("VERIFICATION_EVIDENCE_INVALID", invalid.getMessage(), context,
                    allowedDecisions(context.definition().id()), read);
        }
        if ("implement.self_test_decision".equals(context.definition().id())
                && !"self_test_report".equals(document.sourceArtifactType())) {
            return failed("INVALID_CONTRACT_SIDECAR", "self-test decision requires a self_test_report",
                    context, allowedDecisions(context.definition().id()), read);
        }
        var allowed = allowedDecisions(context.definition().id());
        var decision = document.decision().trim();
        if (decision.isBlank()) {
            return failed("INVALID_CONTRACT_SIDECAR", "contract sidecar missing required decision",
                    context, allowed, read);
        }
        if (!allowed.contains(decision)) {
            return failed("INVALID_DECISION",
                    "Unsupported decision for " + context.definition().id() + ": " + decision,
                    context, allowed, read);
        }
        var facts = new LinkedHashMap<String, Object>(Map.of(
                "decision", decision,
                "source", "contract-sidecar",
                "summary", document.summary()));
        if ("self_test_report".equals(document.sourceArtifactType())) {
            if ("SELF_TEST_COMPLETE".equals(decision)) {
                var violation = AgentContractSemantics.validateOutputContract(document);
                if (violation.isPresent()) {
                    return failed("INVALID_CONTRACT_SIDECAR", violation.get().message(), context, allowed, read);
                }
            }
            facts.put("continuation_kind", switch (decision) {
                case "SELF_TEST_COMPLETE" -> "COMPLETE";
                case "SELF_TEST_INCOMPLETE" -> document.mustFix().isEmpty()
                        ? "HUMAN_REVIEW" : "IMPLEMENTATION_REPAIR";
                case "BLOCKED" -> "HUMAN_REVIEW";
                default -> throw new IllegalStateException("unsupported self-test decision: " + decision);
            });
        }
        if (java.util.Set.of("READY_FOR_ARCH_REVIEW", "READY_TO_IMPLEMENT").contains(decision)) {
            for (var stage : AuthoredStageLineageResolver.Stage.values()) {
                if (!stage.decision.equals(context.definition().id())) continue;
                var resolver = new AuthoredStageLineageResolver(context.ledger(), context.workspaceRoot(),
                        context.workstreamId(), Long.MAX_VALUE);
                facts.put("reviewed_candidate", resolver.reviewedFacts(stage, context.instance().nodeInstanceId()));
            }
        }
        if ("plan.decision".equals(context.definition().id()) && "READY_TO_IMPLEMENT".equals(decision)) {
            var paths = new dev.dual.ledger.file.WorkstreamPaths(context.workspaceRoot(),
                    new dev.dual.core.id.DualId(context.workstreamId()));
            var missing = context.ledger().inspect(paths, (ledger, files) -> {
                var resolution = TaskContractProjectionVerifier.resolve(ledger, context.workspaceRoot(),
                        context.workstreamId(), dev.dual.core.contract.TaskContract.Phase.GOAL);
                if (resolution.failure() != null || resolution.qualified().isEmpty())
                    throw new java.io.IOException("Plan has no current approved GOAL");
                var reviewed = OBJECT_MAPPER.convertValue(facts.get("reviewed_candidate"), Map.class);
                var author = OBJECT_MAPPER.convertValue(reviewed.get("author_artifact"), AuthoredExecutionContext.Reference.class);
                var authorDocument = AgentOutputContractDocument.read(AuthoredExecutionContext.verifiedPath(context.workspaceRoot(), author), OBJECT_MAPPER);
                var plan = authorDocument.map(AgentOutputContractDocument::planArtifact).orElse(null);
                if (plan == null || plan.missingRequiredField().isPresent())
                    throw new java.io.IOException("Reviewed plan is incomplete");
                try {
                    VerificationReadiness.validateBindings(ledger, context.workspaceRoot(), context.workstreamId(),
                            resolution.qualified().orElseThrow(), plan.verificationBindings());
                    return "";
                } catch (java.io.IOException failure) {
                    return failure.getMessage();
                }
            });
            if (!missing.isEmpty()) {
                facts.put("readiness_reason", VerificationReadiness.REQUIRED);
                facts.put("readiness_detail", missing);
                // Preserve the independent review; this is a program-owned routing decision.
                return NodeResult.completed(VerificationReadiness.REQUIRED, context.instance().inputRefs(), facts);
            }
        }
        return NodeResult.completed(decision, context.instance().inputRefs(), facts);
    }

    private NodeResult failed(String reason, String message, DecisionContext context,
                              Set<String> allowed, AgentEvidenceIndex.DecisionRead read) {
        return new NodeResult(reason, NodeStatus.FAILED, List.of(), Map.of(
                "reason", reason,
                "message", message,
                "input_refs", context.instance().inputRefs(),
                "allowed_decisions", List.copyOf(allowed),
                "contract_values", read.entry() == null ? Map.of() : read.entry().document().control(),
                "parse_error", read.errorCode().isBlank() ? Map.of() : Map.of(
                        "code", read.errorCode(), "message", read.message(), "path", read.path())
        ), message);
    }

    private Set<String> allowedDecisions(String nodeId) {
        if (ContractRegistry.hasContract(nodeId)) {
            return ContractRegistry.forNode(nodeId).allowedDecisions();
        }
        return new LinkedHashSet<>(List.of("PASS", "NEEDS_REVISION", "BLOCKED"));
    }

}

package dev.dual.runtime.handler;

import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import java.io.IOException;
import java.util.Set;

/** Application entry for human decisions: qualify the subject and commit under the same local session. */
public final class ReviewGateActions {
    private ReviewGateActions() {}

    public static void revise(WorkflowFileLedger ledger, WorkstreamPaths paths, String expectedSubject, String note) throws IOException {
        if (expectedSubject == null || expectedSubject.isBlank()) {
            resolve(ledger, paths, "revise", note);
            return;
        }
        try (var write = ledger.writeSession(paths, "readiness revision", java.util.UUID.randomUUID().toString())) {
            var owned = write.ledger();
            var current = owned.loadCurrent(paths);
            if (!current.activeNodeInstanceIds().equals(java.util.List.of(expectedSubject)))
                throw new IOException("revision subject is no longer current");
            var source = owned.loadNode(paths, expectedSubject);
            if (source.kind() == dev.dual.core.workflow.NodeKind.GATE) {
                EvidenceCollection.resolveGate(owned, paths, owned.loadDefinition(paths), "revise", note);
            } else {
                var lineage = new AuthoredStageLineageResolver(owned, paths.workspaceRoot(), paths.workstreamId().value(), Long.MAX_VALUE);
                var parent = lineage.reviewed(AuthoredStageLineageResolver.Stage.PLAN, source).candidate();
                var json = TaskContractArtifactWriter.mapper();
                var parentMap = json.convertValue(parent, new com.fasterxml.jackson.core.type.TypeReference<java.util.Map<String, Object>>() {});
                var refs = new java.util.ArrayList<String>();
                refs.add(parent.sidecar().ref());
                if (source.result().get("readiness_refs") instanceof java.util.List<?> values)
                    for (var value : values) if (value instanceof java.util.Map<?, ?> ref && ref.get("ref") instanceof String path) refs.add(path);
                owned.reviseReadinessFailure(paths, expectedSubject, note, parentMap, refs);
            }
            write.commit();
        }
    }

    public static void resolve(WorkflowFileLedger ledger, WorkstreamPaths paths, String action, String note) throws IOException {
        try (var write = ledger.writeSession(paths, "human review " + action, java.util.UUID.randomUUID().toString())) {
            var owned = write.ledger();
            var current = owned.loadCurrent(paths);
            var definition = owned.loadDefinition(paths);
            if (Set.of("approve", "approved").contains(action) && current.activeNodeInstanceIds().size() == 1) {
                var subject = owned.loadNode(paths, current.activeNodeInstanceIds().getFirst());
                if ("contract".equals(definition.node(subject.nodeDefinitionId()).config().get("gate_purpose")))
                    TaskContractProjectionVerifier.executionCandidate(owned, paths.workspaceRoot(),
                            paths.workstreamId().value(), subject.nodeInstanceId(), true);
            }
            EvidenceCollection.resolveGate(owned, paths, definition, action, note);
            write.commit();
        }
    }
}

