package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Typed boundary for artifacts/next-stage/handoff.json.
 *
 * The final assistant result is strict JSON; once projected to this sidecar the runtime
 * should consume this record instead of spreading hand-written map lookups.
 */
record StageHandoffDocument(
        int schemaVersion,
        String workstreamId,
        String stageId,
        String iterationId,
        String sourceHandoffPath,
        List<String> completedWork,
        List<String> importantDecisions,
        List<String> changedFiles,
        List<String> openRisks,
        String verificationState,
        String recommendedNextStage,
        String suggestedNextPrompt,
        String generatedAt
) {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    static Optional<StageHandoffDocument> read(Path path, ObjectMapper objectMapper) {
        try {
            return Optional.of(from(objectMapper.readValue(path.toFile(), MAP_TYPE)));
        } catch (IOException | RuntimeException e) {
            return Optional.empty();
        }
    }

    static StageHandoffDocument from(Map<String, Object> document) {
        return new StageHandoffDocument(
                intValue(document.get("schemaVersion"), 1),
                text(document.get("workstreamId")),
                text(document.get("stageId")),
                text(document.get("iterationId")),
                text(document.get("sourceHandoffPath")),
                stringList(document.get("completedWork")),
                stringList(document.get("importantDecisions")),
                stringList(document.get("changedFiles")),
                stringList(document.get("openRisks")),
                text(document.get("verificationState")),
                text(document.get("recommendedNextStage")),
                text(document.get("suggestedNextPrompt")),
                text(document.get("generatedAt"))
        );
    }

    Map<String, Object> toMap() {
        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", schemaVersion);
        document.put("workstreamId", workstreamId);
        document.put("stageId", stageId);
        document.put("iterationId", iterationId);
        document.put("sourceHandoffPath", sourceHandoffPath);
        document.put("completedWork", completedWork);
        document.put("importantDecisions", importantDecisions);
        document.put("changedFiles", changedFiles);
        document.put("openRisks", openRisks);
        document.put("verificationState", verificationState);
        document.put("recommendedNextStage", recommendedNextStage);
        document.put("suggestedNextPrompt", suggestedNextPrompt);
        document.put("generatedAt", generatedAt);
        return document;
    }

    boolean hasCompletedWork() {
        return !completedWork.isEmpty();
    }

    boolean hasChangedFiles() {
        return !changedFiles.isEmpty();
    }

    boolean hasImportantDecisions() {
        return !importantDecisions.isEmpty();
    }

    boolean hasOpenRisks() {
        return !openRisks.isEmpty();
    }

    boolean hasRecommendedNextStage() {
        return !recommendedNextStage.isBlank();
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : items) {
            var text = text(item);
            if (!text.isBlank()) {
                result.add(text);
            }
        }
        return List.copyOf(result);
    }

    private static int intValue(Object value, int fallback) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.handler;

/**
 * Canonical stage outcome compiled by the orchestrator from Agent decisions,
 * declared artifact status, evidence fields, and runtime facts.
 *
 * Agent output may propose a decision, but workflow routing should consume this
 * normalized stage outcome plus the original routing decision. This keeps
 * runtime failures, semantic review results, and evidence gaps from collapsing
 * into one overloaded "decision" string.
 */
enum StageOutcome {
    READY,
    NEEDS_REVISION,
    BLOCKED,
    ACCEPTED,
    ACCEPTED_WITH_NOTES,
    REJECTED,
    INSUFFICIENT_EVIDENCE,
    UNKNOWN;

    static StageOutcome fromDecision(String decision) {
        return switch (normalized(decision)) {
            case "PASS",
                 "READY_FOR_PRODUCT_REVIEW",
                 "READY_FOR_ARCH_REVIEW",
                 "READY_FOR_PLAN_REVIEW",
                 "READY_TO_IMPLEMENT",
                 "IMPLEMENTED",
                 "SELF_TEST_COMPLETE",
                 "HANDOFF_READY",
                 "READY_FOR_REVIEW" -> READY;
            case "NEEDS_REVISION",
                 "NEEDS_CLARIFICATION",
                 "NEEDS_SCOPE_REDUCTION" -> NEEDS_REVISION;
            case "BLOCKED" -> BLOCKED;
            case "ACCEPT" -> ACCEPTED;
            case "ACCEPT_WITH_NOTES" -> ACCEPTED_WITH_NOTES;
            case "REJECT",
                 "REJECTED",
                 "REJECT_CONTRACT_GAP",
                 "REJECT_CONTRACT_AMBIGUITY",
                 "REJECT_IMPLEMENTATION_BUG",
                 "REJECT_CONTEXT_INSUFFICIENT",
                 "REJECT_TOOL_LIMITATION",
                 "REJECT_REVIEW_NOISE" -> REJECTED;
            case "REJECT_VERIFICATION_INSUFFICIENT" -> INSUFFICIENT_EVIDENCE;
            case "SELF_TEST_INCOMPLETE",
                 "NOTED_CONTEXT_INSUFFICIENT",
                 "NOTED_VERIFICATION_INSUFFICIENT" -> INSUFFICIENT_EVIDENCE;
            case "NOTED_CONTRACT_GAP",
                 "NOTED_CONTRACT_AMBIGUITY",
                 "NOTED_IMPLEMENTATION_BUG",
                 "NOTED_TOOL_LIMITATION",
                 "NOTED_REVIEW_NOISE" -> ACCEPTED_WITH_NOTES;
            default -> UNKNOWN;
        };
    }

    static StageOutcome fromText(String value) {
        try {
            return StageOutcome.valueOf(normalized(value));
        } catch (IllegalArgumentException e) {
            return UNKNOWN;
        }
    }

    private static String normalized(String value) {
        return value == null ? "" : value.trim().toUpperCase();
    }
}

package dev.dual.runtime.handler;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;

/**
 * Compiles Agent-proposed status fields into a canonical stage outcome.
 *
 * This is the orchestration boundary between "the LLM said X" and "the
 * workflow may route as Y". Rules here are intentionally mechanical. A future
 * semantic judge can add recommendations, but the final canonical outcome must
 * still be produced by this compiler and recorded in the sidecar.
 */
final class StageOutcomeCompiler {
    private StageOutcomeCompiler() {
    }

    static StageOutcomeCompilation compile(String decision, String declaredStatus) {
        var derived = StageOutcome.fromDecision(decision);
        if (declaredStatus == null || declaredStatus.isBlank()) {
            return StageOutcomeCompilation.valid(derived, "decision");
        }
        var declared = StageOutcome.fromText(declaredStatus);
        if (declared == StageOutcome.UNKNOWN) {
            return StageOutcomeCompilation.invalid(
                    derived,
                    "STRUCTURED_ARTIFACT_UNKNOWN_STATUS",
                    "structured artifact lifecycle_status is not recognized: " + declaredStatus
            );
        }
        if (declared == derived) {
            return StageOutcomeCompilation.valid(declared, "declared_status");
        }
        if (derived == StageOutcome.REJECTED && declared == StageOutcome.INSUFFICIENT_EVIDENCE) {
            return StageOutcomeCompilation.valid(declared, "declared_status");
        }
        return StageOutcomeCompilation.invalid(
                derived,
                "STRUCTURED_ARTIFACT_STATUS_MISMATCH",
                "structured artifact lifecycle_status " + declared
                        + " conflicts with decision " + decision
        );
    }

    static void addSidecarFields(Map<String, Object> sidecar) {
        var declared = text(sidecar.get("lifecycle_status"));
        var compilation = compile(text(sidecar.get("decision")), declared);
        var outcome = compilation.outcome();
        var evidenceState = AgentEvidenceState.fromSidecar(sidecar);
        sidecar.put("stage_outcome", outcome.name());
        sidecar.put("stage_outcome_source", compilation.source());
        sidecar.put("lifecycle_status", outcome.name());
        sidecar.put("evidence_state", evidenceState.toMap());
    }

    static Optional<ContractViolation> validateEvidenceContract(
            String expectedType,
            String decision,
            String declaredStatus,
            AgentEvidenceState evidenceState,
            AgentOutputContractDocument.FailureFields failure
    ) {
        var compilation = compile(decision, declaredStatus);
        if (!compilation.valid()) {
            return violation(expectedType, compilation.errorCode(), compilation.message());
        }
        var outcome = compilation.outcome();
        if (outcome == StageOutcome.READY
                && evidenceState.hasBlockingDecisionIssues()) {
            return violation(
                    expectedType,
                    "POSITIVE_STATUS_EVIDENCE_CONFLICT",
                    "decision " + decision + " cannot include blocking=true or must_fix"
            );
        }
        if (outcome == StageOutcome.ACCEPTED
                && evidenceState.hasFinalAcceptanceConflicts()) {
            return violation(
                    expectedType,
                    "FINAL_ACCEPTANCE_EVIDENCE_CONFLICT",
                    "decision " + decision + " cannot include blocking=true, must_fix, or missing_evidence"
            );
        }
        if (outcome == StageOutcome.ACCEPTED_WITH_NOTES
                && evidenceState.hasBlockingDecisionIssues()) {
            return violation(
                    expectedType,
                    "NOTES_STATUS_BLOCKING_CONFLICT",
                    "decision " + decision + " cannot include blocking=true or must_fix; use REJECT for blocking issues"
            );
        }
        if ((outcome == StageOutcome.NEEDS_REVISION
                || outcome == StageOutcome.BLOCKED
                || outcome == StageOutcome.REJECTED
                || outcome == StageOutcome.INSUFFICIENT_EVIDENCE)
                && !evidenceState.hasBlockingIssues()
                && failure.isEmpty()) {
            return violation(
                    expectedType,
                    "NEGATIVE_STATUS_MISSING_EVIDENCE",
                    "decision " + decision + " must include blocking=true, must_fix, missing_evidence, or failure reason"
            );
        }
        return Optional.empty();
    }

    private static Optional<ContractViolation> violation(
            String expectedType,
            String code,
            String message
    ) {
        return Optional.of(ContractViolation.of(
                "STRUCTURED_ARTIFACT_SEMANTIC_VIOLATION",
                code + ": " + message,
                Map.of("required_artifact_type", expectedType, "semantic_code", code)
        ));
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    record StageOutcomeCompilation(
            StageOutcome outcome,
            String source,
            boolean valid,
            String errorCode,
            String message
    ) {
        static StageOutcomeCompilation valid(StageOutcome outcome, String source) {
            return new StageOutcomeCompilation(outcome, source, true, "", "");
        }

        static StageOutcomeCompilation invalid(StageOutcome fallback, String errorCode, String message) {
            return new StageOutcomeCompilation(fallback, "invalid", false, errorCode, message);
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("outcome", outcome.name());
            map.put("source", source);
            map.put("valid", valid);
            if (!errorCode.isBlank()) {
                map.put("error_code", errorCode);
                map.put("message", message);
            }
            return map;
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.stream.Collectors;

final class TaskContractArtifactWriter {

    private static final ObjectMapper MAPPER = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
            .enable(SerializationFeature.INDENT_OUTPUT);

    private TaskContractArtifactWriter() {}

    static void writeJson(TaskContract contract, Path artifactsDir) throws IOException {
        Files.createDirectories(artifactsDir);
        var jsonPath = artifactsDir.resolve("task-contract.json");
        MAPPER.writeValue(jsonPath.toFile(), contract);
    }

    static void writeMarkdown(TaskContract contract, Path artifactsDir) throws IOException {
        Files.createDirectories(artifactsDir);
        Files.writeString(artifactsDir.resolve("task-contract.md"), renderMarkdown(contract), StandardCharsets.UTF_8);
    }

    static String renderMarkdown(TaskContract contract) {
        var md = new StringBuilder();
        md.append("# Task Contract\n\n");

        md.append("## Objective\n\n").append(contract.objective()).append("\n\n");

        md.append("## Scope\n\n");
        if (contract.scope() != null) {
            if (!contract.scope().included().isEmpty()) {
                md.append("**Included:**\n");
                for (var item : contract.scope().included()) {
                    md.append("- ").append(item.operation()).append(": ").append(item.path()).append("\n");
                }
                md.append("\n");
            }
            if (!contract.scope().excluded().isEmpty()) {
                md.append("**Excluded:**\n");
                for (var item : contract.scope().excluded()) {
                    md.append("- ").append(item).append("\n");
                }
                md.append("\n");
            }
        }

        md.append("## Acceptance Criteria\n\n");
        for (var criterion : contract.acceptanceCriteria()) {
            md.append("- [ ] ").append(criterion.id()).append(": ").append(criterion.text()).append("\n");
        }
        md.append("\n");

        appendListSection(md, "Test Requirements", contract.testRequirements().stream().map(c -> c.id() + ": " + c.text()).toList());
        appendListSection(md, "Constraints", contract.constraints());
        appendListSection(md, "Non-Goals", contract.nonGoals());
        appendListSection(md, "Risk Areas", contract.riskAreas());
        appendListSection(md, "Evidence References", contract.evidenceRefs());
        appendListSection(md, "Ambiguity Notes", contract.ambiguityNotes());
        appendListSection(md, "Human Questions", contract.humanQuestions());

        appendListSection(md, "Nonessential Operation Declarations", nonessentialOperationDescriptions(contract));

        if (contract.source() != null) {
            md.append("## Source\n\n");
            md.append("- **Created by:** ").append(contract.source().createdBy()).append("\n");
            if (contract.source().rawRequestRef() != null) {
                md.append("- **Raw request:** ").append(contract.source().rawRequestRef()).append("\n");
            }
            md.append("\n");
        }

        return md.toString();
    }

    static java.util.List<String> nonessentialOperationDescriptions(TaskContract contract) {
        return contract.nonessentialOperationDeclarations().isEmpty() ? java.util.List.of("None")
                : contract.nonessentialOperationDeclarations().stream().map(d -> d.id() + ": " + d.rationale()
                    + "; node=" + d.nodeDefinitionId() + "; kind=" + d.operationKind()
                    + "; criteria=" + d.criterionIds() + "; parameters_sha256=" + d.operationParametersSha256()
                    + "; source=" + d.nodeContractRef() + "; rule=" + d.ruleIdentity()).toList();
    }

    static ObjectMapper mapper() {
        return MAPPER;
    }

    static String sha256(byte[] bytes) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (Exception failure) {
            throw new IllegalStateException("SHA-256 digest is unavailable", failure);
        }
    }

    static String sha256(Path path) throws IOException {
        return sha256(Files.readAllBytes(path));
    }

    private static void appendListSection(StringBuilder md, String title, java.util.List<String> items) {
        if (items == null || items.isEmpty()) {
            return;
        }
        md.append("## ").append(title).append("\n\n");
        for (var item : items) {
            md.append("- ").append(item).append("\n");
        }
        md.append("\n");
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.contract.TaskContractValidator;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.GateDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.LedgerSession;
import dev.dual.ledger.file.WorkstreamPaths;
import dev.dual.core.id.DualId;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Pattern;

/** Resolves the last human-approved contract.compile occurrence into one immutable snapshot. */
final class TaskContractProjectionVerifier {
    static final String FAILURE_OUTCOME = "TASK_CONTRACT_PROJECTION_QUALIFICATION_FAILED";
    private static final Pattern WORKFLOW_EVENT_ID = Pattern.compile("evt-(\\d{6,})");
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private TaskContractProjectionVerifier() {
    }

    static boolean requiresContract(dev.dual.core.workflow.NodeDefinition definition) {
        if (definition.config().containsKey("requires_approved_task_contract"))
            throw new IllegalArgumentException("legacy contract qualification flag is not supported: " + definition.id());
        if (!definition.config().containsKey("required_contract_phase")) return false;
        requiredPhase(definition);
        return true;
    }

    static TaskContract.Phase requiredPhase(dev.dual.core.workflow.NodeDefinition definition) {
        var value = definition.config().get("required_contract_phase");
        if (!(value instanceof String phase)) throw new IllegalArgumentException("required_contract_phase is missing: " + definition.id());
        try { return TaskContract.Phase.valueOf(phase); }
        catch (IllegalArgumentException invalid) { throw new IllegalArgumentException("invalid contract phase: " + definition.id()); }
    }

    static Resolution resolve(WorkflowFileLedger ledger, Path workspaceRoot, String workstreamId) {
        return resolve(ledger, workspaceRoot, workstreamId, TaskContract.Phase.EXECUTION);
    }

    static Resolution resolve(WorkflowFileLedger ledger, Path workspaceRoot, String workstreamId, TaskContract.Phase phase) {
        var paths = new WorkstreamPaths(workspaceRoot, new DualId(workstreamId));
        try {
            return ledger.inspect(paths, (snapshot, files) -> phase == TaskContract.Phase.GOAL
                    ? resolveGoal(snapshot, files) : resolveExecution(snapshot, files));
        } catch (IOException | IllegalArgumentException failure) {
            return Resolution.failed(Failure.of("CONTRACT_SNAPSHOT_UNAVAILABLE", failure.getMessage()));
        }
    }

    private static Resolution resolveGoal(WorkflowFileLedger ledger, LedgerSession files) throws IOException {
        var paths = files.paths();
        var root = paths.workspaceRoot();
        var ws = paths.workstreamId().value();
        var nodes = readNodes(files, paths.nodesDir());
        if (nodes.failure() != null) return Resolution.failed(nodes.failure());
        var candidates = nodes.nodes().stream().filter(n -> "contract.compile".equals(n.handlerType())
                && n.status() == NodeStatus.COMPLETED && "GOAL".equals(text(n.result().get("contract_phase"))))
                .sorted(java.util.Comparator.comparingLong((NodeInstanceDocument n) -> longValue(n.result().get("contract_epoch"))).reversed())
                .toList();
        if (candidates.isEmpty()) return Resolution.absent();
        var compile = candidates.getFirst();
        long epoch = longValue(compile.result().get("contract_epoch"));
        if (epoch < 1 || candidates.stream().filter(n -> longValue(n.result().get("contract_epoch")) == epoch).count() != 1)
            return Resolution.failed(Failure.of("CONTRACT_EPOCH_INVALID", "GOAL authorization epoch is missing or duplicated"));
        var prefix = ".agent/workstreams/" + ws + "/artifacts/contracts/" + compile.nodeInstanceId() + "/";
        var contractRef = prefix + "task-contract.json";
        var resolutionRef = prefix + "contract-resolution.json";
        if (!compile.outputRefs().containsAll(List.of(contractRef, resolutionRef)))
            return Resolution.failed(Failure.of("OUTPUT_REF_MISMATCH", "GOAL compile does not publish its occurrence artifacts"));
        var bytes = files.readBytes(root.resolve(contractRef));
        var resolutionBytes = files.readBytes(root.resolve(resolutionRef));
        var contract = TaskContractArtifactWriter.mapper().readValue(bytes, TaskContract.class);
        if (contract.phase() != TaskContract.Phase.GOAL || contract.epoch() != epoch
                || !TaskContractValidator.validate(contract).isEmpty()
                || !contract.id().equals(text(compile.result().get("contract_id")))
                || !contract.status().name().equals(text(compile.result().get("contract_status")))
                || contract.version() != intValue(compile.result().get("contract_version"))
                || !TaskContractArtifactWriter.sha256(bytes).equals(text(compile.result().get("task_contract_sha256")))
                || !TaskContractArtifactWriter.sha256(resolutionBytes).equals(text(compile.result().get("contract_resolution_sha256"))))
            return Resolution.failed(Failure.of("GOAL_CONTRACT_INVALID", "GOAL identity, shape or immutable bytes do not match its compiler"));
        var approval = contract.source().goalApproval();
        var approvalPath = root.resolve(approval.ref());
        if (!approvalPath.normalize().getParent().equals(paths.gatesDir().toAbsolutePath().normalize())
                || !approval.sha256().equals(TaskContractArtifactWriter.sha256(files.readBytes(approvalPath))))
            return Resolution.failed(Failure.of("GOAL_APPROVAL_INVALID", "GOAL approval reference is not an unchanged workstream gate"));
        var gate = files.read(approvalPath, GateDocument.class);
        var gateNode = node(nodes.nodes(), gate.nodeInstanceId());
        if (gateNode == null || gateNode.status() != NodeStatus.COMPLETED
                || !"gate.human_requirement_review".equals(gateNode.nodeDefinitionId())
                || !"resolved".equals(gate.status())
                || !"approved".equals(text(gate.result().get("human_action")))
                || !"approved".equals(text(gateNode.result().get("human_action")))
                || !text(gate.result().get("note")).equals(text(gateNode.result().get("note")))
                || !textList(gate.result().get("subject_input_refs")).equals(gateNode.inputRefs())
                || !compile.inputRefs().equals(gateNode.outputRefs())
                || !gateNode.nodeInstanceId().equals(text(compile.inputTransition().get("source_node_instance_id")))
                || !TaskContractArtifactWriter.sha256(files.readBytes(paths.nodeJson(gateNode.nodeInstanceId())))
                        .equals(text(compile.inputTransition().get("source_node_sha256"))))
            return Resolution.failed(Failure.of("GOAL_APPROVAL_INVALID", "GOAL compiler is not routed from the matching completed human decision"));
        var review = AgentEvidenceIndex.latestDecisionFromRefs(ledger, root, ws, gateNode.inputRefs(), OBJECT_MAPPER);
        if (review.entry() == null || !"intake.codex_product_review".equals(review.entry().document().nodeId())
                || review.entry().document().reviewSubject() == null)
            return Resolution.failed(Failure.of("GOAL_SUBJECT_INVALID", "approved review subject is not verifiable"));
        var subject = review.entry().document().reviewSubject();
        if (!contract.source().proposal().ref().equals(subject.artifactRef())
                || !contract.source().proposal().sha256().equals(subject.sha256())
                || !subject.sha256().equals(TaskContractArtifactWriter.sha256(files.readBytes(root.resolve(subject.artifactRef())))))
            return Resolution.failed(Failure.of("GOAL_SUBJECT_INVALID", "GOAL does not bind the approved proposal bytes"));
        String approvalEvent = null;
        long last = -1;
        for (var line : files.readLines(paths.eventsJsonl())) {
            var event = OBJECT_MAPPER.readValue(line, MAP_TYPE);
            var id = text(event.get("event_id"));
            var matcher = WORKFLOW_EVENT_ID.matcher(id);
            if (!matcher.matches()) {
                if ("node_routed".equals(text(event.get("event_type")))) throw new IOException("invalid route event identity");
                continue;
            }
            long sequence = Long.parseLong(matcher.group(1));
            if (sequence <= last) throw new IOException("unordered workflow events");
            last = sequence;
            var payload = map(event.get("payload"));
            if (!"node_routed".equals(text(event.get("event_type")))
                    || !compile.nodeInstanceId().equals(text(payload.get("node_instance_id")))) continue;
            if (approvalEvent != null || !gateNode.nodeInstanceId().equals(text(payload.get("source_node_instance_id")))
                    || !gateNode.nodeDefinitionId().equals(text(payload.get("from")))
                    || !compile.nodeDefinitionId().equals(text(payload.get("to")))
                    || !"approved".equals(text(payload.get("outcome"))))
                throw new IOException("invalid GOAL approval routing occurrence");
            approvalEvent = id;
        }
        if (approvalEvent == null) return Resolution.failed(Failure.of("GOAL_APPROVAL_INVALID", "GOAL approval route is missing"));
        return Resolution.qualified(new QualifiedTaskContract(new String(bytes, StandardCharsets.UTF_8), contract,
                OBJECT_MAPPER.readValue(bytes, MAP_TYPE), TaskContractArtifactWriter.sha256(bytes), contractRef,
                new String(resolutionBytes, StandardCharsets.UTF_8), OBJECT_MAPPER.readValue(resolutionBytes, MAP_TYPE),
                TaskContractArtifactWriter.sha256(resolutionBytes), resolutionRef, compile.nodeInstanceId(),
                ".agent/workstreams/" + ws + "/nodes/" + compile.nodeInstanceId() + ".json", approval.ref(), approvalEvent));
    }

    private static Resolution resolveExecution(WorkflowFileLedger ledger, LedgerSession files) throws IOException {
        return resolveExecution(ledger, files, true);
    }

    /** Inspection of an approval boundary only; never usable as dispatch qualification. */
    static Resolution approvedExecutionBoundary(WorkflowFileLedger ledger, WorkstreamPaths paths) throws IOException {
        return ledger.inspect(paths, (scoped, files) -> resolveExecution(scoped, files, false));
    }

    private static Resolution resolveExecution(WorkflowFileLedger ledger, LedgerSession files, boolean qualifyReadiness) throws IOException {
        var workspaceRoot = files.paths().workspaceRoot();
        var workstreamId = files.paths().workstreamId().value();
        var workstreamDir = files.paths().workstreamDir();
        var nodes = readNodes(files, workstreamDir.resolve("nodes"));
        if (nodes.failure() != null) {
            return Resolution.failed(nodes.failure());
        }
        var occurrenceRead = lastContractGateOccurrence(files, workstreamDir.resolve("events.jsonl"));
        if (occurrenceRead.failure() != null) {
            return Resolution.failed(occurrenceRead.failure());
        }
        if (occurrenceRead.occurrence() == null) return Resolution.absent();
        var occurrence = occurrenceRead.occurrence();
        var gateNode = node(nodes.nodes(), occurrence.nodeInstanceId());
        if (gateNode == null || !"gate.contract_review".equals(gateNode.nodeDefinitionId())) {
            return Resolution.failed(Failure.of("GATE_NODE_MISSING", "contract approval gate node is missing"));
        }
        if (gateNode.status() != NodeStatus.COMPLETED) {
            return Resolution.failed(Failure.of("GATE_NOT_COMPLETED", "latest contract approval gate is not completed"));
        }
        var gateRead = readGate(files, workstreamDir.resolve("gates").resolve(occurrence.gateId() + ".json"));
        if (gateRead.failure() != null) {
            return Resolution.failed(gateRead.failure());
        }
        var gate = gateRead.gate();
        if (!gate.nodeInstanceId().equals(gateNode.nodeInstanceId()) || !"resolved".equals(gate.status())) {
            return Resolution.failed(Failure.of("GATE_LINEAGE_INVALID", "latest contract gate lineage or status is invalid"));
        }
        var gateAction = text(gate.result().get("human_action"));
        var nodeAction = text(gateNode.result().get("human_action"));
        if (!"approved".equals(gateAction) || !gateAction.equals(nodeAction)) {
            return Resolution.failed(Failure.of(
                    "CONTRACT_NOT_APPROVED", "latest contract gate action is not approved: " + gateAction));
        }
        if (!text(gate.result().get("note")).equals(text(gateNode.result().get("note")))) {
            return Resolution.failed(Failure.of("GATE_RESULT_MISMATCH", "contract gate note does not match node result"));
        }
        var gateRefs = textList(gate.result().get("subject_input_refs"));
        if (!gateRefs.equals(gateNode.inputRefs())) {
            return Resolution.failed(Failure.of("GATE_SUBJECT_MISMATCH", "contract gate subject refs do not match node input refs"));
        }
        var sourceId = text(gate.result().get("source_node_instance_id"));
        if (sourceId.isBlank()
                || !sourceId.equals(text(gateNode.result().get("source_node_instance_id")))
                || !sourceId.equals(occurrence.sourceNodeInstanceId())) {
            return Resolution.failed(Failure.of("GATE_SOURCE_MISMATCH", "contract gate source occurrence identity is missing or inconsistent"));
        }
        var compileNode = node(nodes.nodes(), sourceId);
        if (compileNode == null
                || !"contract.compile".equals(compileNode.handlerType())
                || !"EXECUTION".equals(text(compileNode.result().get("contract_phase")))
                || compileNode.status() != NodeStatus.COMPLETED) {
            return Resolution.failed(Failure.of("COMPILE_BINDING_MISSING", "approved source is not a completed contract.compile node"));
        }
        if (!compileNode.nodeDefinitionId().equals(occurrence.fromNodeDefinitionId())) {
            return Resolution.failed(Failure.of("EVENT_SOURCE_MISMATCH", "routing event source does not match approved compile node"));
        }
        var newerCompile = newerCompletedCompile(nodes.nodes(), compileNode);
        if (newerCompile != null) {
            return Resolution.failed(Failure.of(
                    "UNAPPROVED_RECOMPILE", "completed contract.compile is newer than the approved source: "
                            + newerCompile.nodeInstanceId()));
        }
        var artifactsDir = workstreamDir.resolve("artifacts/contracts").resolve(compileNode.nodeInstanceId());
        var contractPath = artifactsDir.resolve("task-contract.json");
        var resolutionPath = artifactsDir.resolve("contract-resolution.json");
        if (!files.exists(contractPath) || !files.exists(resolutionPath)) {
            return Resolution.failed(Failure.of("ARTIFACT_MISSING", "approved contract or requirement resolution artifact is missing"));
        }
        var contractRef = ".agent/workstreams/" + workstreamId + "/artifacts/contracts/" + compileNode.nodeInstanceId() + "/task-contract.json";
        var resolutionRef = ".agent/workstreams/" + workstreamId + "/artifacts/contracts/" + compileNode.nodeInstanceId() + "/contract-resolution.json";
        if (!compileNode.outputRefs().contains(contractRef)
                || !compileNode.outputRefs().contains(resolutionRef)
                || !gateRefs.contains(contractRef)
                || !gateRefs.contains(resolutionRef)) {
            return Resolution.failed(Failure.of("OUTPUT_REF_MISMATCH", "approved compile/gate refs do not bind both contract artifacts"));
        }

        final byte[] contractBytes;
        final byte[] resolutionBytes;
        final TaskContract contract;
        final Map<String, Object> document;
        final Map<String, Object> resolutionDocument;
        try {
            contractBytes = files.readBytes(contractPath);
            resolutionBytes = files.readBytes(resolutionPath);
            contract = TaskContractArtifactWriter.mapper().readValue(contractBytes, TaskContract.class);
            document = OBJECT_MAPPER.readValue(contractBytes, MAP_TYPE);
            resolutionDocument = OBJECT_MAPPER.readValue(resolutionBytes, MAP_TYPE);
        } catch (Exception failure) {
            return Resolution.failed(Failure.of("CONTRACT_INVALID", "approved contract artifacts cannot be parsed"));
        }
        var errors = TaskContractValidator.validate(contract);
        if (contract.phase() != TaskContract.Phase.EXECUTION || !errors.isEmpty()) {
            return Resolution.failed(Failure.of(
                    "CONTRACT_INVALID", "task-contract.json is invalid: " + String.join("; ", errors)));
        }

        var sha256 = TaskContractArtifactWriter.sha256(contractBytes);
        var resolutionSha256 = TaskContractArtifactWriter.sha256(resolutionBytes);
        var expectedSha = text(compileNode.result().get("task_contract_sha256"));
        var expectedResolutionSha = text(compileNode.result().get("contract_resolution_sha256"));
        if (expectedSha.isBlank() || expectedResolutionSha.isBlank()) {
            return Resolution.failed(Failure.of(
                    "COMPILE_BINDING_MISSING", "approved contract.compile has incomplete artifact SHA binding"));
        }
        if (!sha256.equals(expectedSha) || !resolutionSha256.equals(expectedResolutionSha)) {
            return Resolution.failed(Failure.of("HASH_MISMATCH", "approved contract artifact SHA-256 does not match compile result"));
        }
        if (!contract.id().equals(text(compileNode.result().get("contract_id")))
                || !contract.status().name().equals(text(compileNode.result().get("contract_status")))
                || contract.version() != intValue(compileNode.result().get("contract_version"))
                || contract.epoch() != longValue(compileNode.result().get("contract_epoch"))) {
            return Resolution.failed(Failure.of(
                    "IDENTITY_MISMATCH", "task-contract.json identity does not match compile result"));
        }
        var inputFailure = validateExecutionInputs(ledger, files, compileNode, contract, false);
        if (inputFailure == null && qualifyReadiness) {
            try {
                var bindings = currentVerificationBindings(ledger, files, contract, contractRef, sha256);
                VerificationReadiness.validateBindings(ledger, workspaceRoot, workstreamId,
                        resolveGoal(ledger, files).qualified().orElseThrow(), bindings);
            } catch (IOException invalid) { inputFailure = Failure.of(VerificationReadiness.REQUIRED, invalid.getMessage()); }
        }
        if (inputFailure != null) return Resolution.failed(inputFailure);
        var nodeRef = ".agent/workstreams/" + workstreamId + "/nodes/"
                + compileNode.nodeInstanceId() + ".json";
        var gateRef = ".agent/workstreams/" + workstreamId + "/gates/" + occurrence.gateId() + ".json";
        return Resolution.qualified(new QualifiedTaskContract(
                new String(contractBytes, StandardCharsets.UTF_8), contract, Map.copyOf(document), sha256,
                contractRef, new String(resolutionBytes, StandardCharsets.UTF_8), Map.copyOf(resolutionDocument),
                resolutionSha256, resolutionRef, compileNode.nodeInstanceId(), nodeRef, gateRef, occurrence.eventId()));
    }

    private static List<TaskContract.VerificationBinding> currentVerificationBindings(WorkflowFileLedger ledger,
            LedgerSession files, TaskContract approved, String contractRef, String sha) throws IOException {
        var paths = files.paths();
        var current = ledger.loadCurrent(paths);
        if (current.activeNodeInstanceIds().size() != 1) return approved.verificationBindings();
        var cursor = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
        var visited = new java.util.HashSet<String>();
        while (visited.add(cursor.nodeInstanceId())) {
            if (Boolean.TRUE.equals(cursor.result().get("authorization_reused"))) {
                if (cursor.status() != NodeStatus.COMPLETED || !"contract.compile".equals(cursor.handlerType())
                        || !contractRef.equals(cursor.result().get("approved_contract_ref"))
                        || !sha.equals(cursor.result().get("approved_contract_sha256")))
                    throw new IOException("invalid technical continuation approval binding");
                var lineage = new AuthoredStageLineageResolver(ledger, paths.workspaceRoot(), paths.workstreamId().value(), Long.MAX_VALUE);
                var plan = lineage.reviewed(AuthoredStageLineageResolver.Stage.PLAN, cursor);
                var design = lineage.reviewed(AuthoredStageLineageResolver.Stage.DESIGN, cursor);
                var expectedReviews = List.of(new TaskContract.Reference(design.decision().ref(), design.decision().sha256()),
                        new TaskContract.Reference(plan.decision().ref(), plan.decision().sha256()));
                if (!OBJECT_MAPPER.valueToTree(expectedReviews).equals(OBJECT_MAPPER.valueToTree(cursor.result().get("reviewed_candidates"))))
                    throw new IOException("technical continuation lost its independent reviews");
                var document = AgentOutputContractDocument.read(AuthoredExecutionContext.verifiedPath(paths.workspaceRoot(), plan.candidate().sidecar()), OBJECT_MAPPER).orElseThrow();
                if (!sameExecutionBoundary(ledger, paths, approved, document.planArtifact()))
                    throw new IOException("technical revision changed the execution authorization boundary");
                return document.planArtifact().verificationBindings();
            }
            var source = text(cursor.inputTransition().get("source_node_instance_id"));
            if (source.isBlank()) return approved.verificationBindings();
            var path = paths.nodeJson(source);
            if (!TaskContractArtifactWriter.sha256(files.readBytes(path)).equals(text(cursor.inputTransition().get("source_node_sha256"))))
                throw new IOException("technical continuation route source changed");
            cursor = ledger.loadNode(paths, source);
        }
        throw new IOException("technical continuation lineage cycle");
    }

    static boolean sameExecutionBoundary(WorkflowFileLedger ledger, WorkstreamPaths paths, TaskContract approved,
                                         PlanArtifactDocument plan) throws IOException {
        return approved.nonessentialOperationDeclarations().equals(ContractCompileHandler.nonessentialDeclarations(ledger, paths))
                && plan != null && new java.util.HashSet<>(approved.scope().included()).equals(new java.util.HashSet<>(plan.files()))
                && approved.authorityRefs().equals(plan.authorityRefs())
                && VerificationReadiness.sameVerificationBoundary(ledger, paths, approved.verificationBindings(), plan.verificationBindings());
    }

    private static Failure validateExecutionInputs(WorkflowFileLedger ledger, LedgerSession files,
                                                   NodeInstanceDocument compileNode, TaskContract contract,
                                                   boolean readiness) throws IOException {
        var workspaceRoot = files.paths().workspaceRoot();
        var workstreamId = files.paths().workstreamId().value();
        var goalResolution = resolveGoal(ledger, files);
        if (goalResolution.qualified().isEmpty()) return Failure.of("GOAL_CONTRACT_NOT_QUALIFIED", "current GOAL is required");
        var goal = goalResolution.qualified().orElseThrow();
        if (!new TaskContract.Reference(goal.contractRef(), goal.sha256()).equals(contract.goalContract())
                || contract.epoch() != goal.contract().epoch()
                || !contract.objective().equals(goal.contract().objective())
                || !contract.acceptanceCriteria().equals(goal.contract().acceptanceCriteria())
                || !contract.testRequirements().equals(goal.contract().testRequirements())
                || !contract.constraints().equals(goal.contract().constraints())
                || !contract.nonGoals().equals(goal.contract().nonGoals())
                || !contract.scope().excluded().equals(goal.contract().scope().excluded())
                || !contract.source().equals(goal.contract().source()))
            return Failure.of("EXECUTION_GOAL_MISMATCH", "execution contract no longer binds the approved goal");
        if (!contract.nonessentialOperationDeclarations().equals(ContractCompileHandler.nonessentialDeclarations(ledger, files.paths())))
            return Failure.of("EXECUTION_DECLARATION_MISMATCH", "nonessential declarations must bind the frozen node contracts");
        var lineage = new AuthoredStageLineageResolver(ledger, workspaceRoot, workstreamId, Long.MAX_VALUE);
        var reviewed = new ArrayList<TaskContract.Reference>();
        for (var stage : AuthoredStageLineageResolver.Stage.values()) {
            var value = lineage.reviewed(stage, compileNode);
            reviewed.add(new TaskContract.Reference(value.decision().ref(), value.decision().sha256()));
        }
        if (!reviewed.equals(contract.reviewedCandidates()))
            return Failure.of("EXECUTION_REVIEW_MISMATCH", "execution contract must consume its routed independent reviews");
        if (readiness) {
            try { VerificationReadiness.validateBindings(ledger, workspaceRoot, workstreamId, goal, contract.verificationBindings()); }
            catch (IOException failure) { return Failure.of(VerificationReadiness.REQUIRED, failure.getMessage()); }
        }
        return null;
    }

    /** The current gate's immutable subject. This read never confers execution approval. */
    static CandidateProjection executionCandidate(WorkflowFileLedger ledger, Path root, String ws, String gateNodeId,
                                                   boolean requireReady) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(ws));
        return ledger.inspect(paths, (snapshot, files) -> {
            var current = snapshot.loadCurrent(paths);
            if (!current.activeNodeInstanceIds().equals(List.of(gateNodeId))
                    || current.status() != dev.dual.core.workflow.WorkflowStatus.WAITING_FOR_HUMAN)
                throw new IOException("contract candidate requires its current waiting gate");
            var gateNode = snapshot.loadNode(paths, gateNodeId);
            var gate = snapshot.loadOpenGateForNode(paths, gateNodeId);
            var sourceId = text(gateNode.result().get("source_node_instance_id"));
            var origin = lastContractGateOccurrence(files, paths.eventsJsonl());
            if (!"gate.contract_review".equals(gateNode.nodeDefinitionId()) || gate == null || origin.failure() != null
                    || origin.occurrence() == null || !gateNodeId.equals(origin.occurrence().nodeInstanceId())
                    || !gate.gateId().equals(origin.occurrence().gateId())
                    || !sourceId.equals(origin.occurrence().sourceNodeInstanceId())
                    || !sourceId.equals(text(gate.result().get("source_node_instance_id")))
                    || !gateNode.inputRefs().equals(textList(gate.result().get("subject_input_refs"))))
                throw new IOException("contract gate subject or route is inconsistent");
            var compile = snapshot.loadNode(paths, sourceId);
            if (compile.status() != NodeStatus.COMPLETED || !"contract.compile".equals(compile.handlerType())
                    || !"EXECUTION".equals(compile.result().get("contract_phase"))
                    || !compile.nodeDefinitionId().equals(origin.occurrence().fromNodeDefinitionId())
                    || !sourceId.equals(text(gateNode.inputTransition().get("source_node_instance_id")))
                    || !TaskContractArtifactWriter.sha256(files.readBytes(paths.nodeJson(sourceId)))
                        .equals(text(gateNode.inputTransition().get("source_node_sha256"))))
                throw new IOException("contract gate does not bind its completed execution compiler");
            var prefix = ".agent/workstreams/" + ws + "/artifacts/contracts/" + sourceId + "/";
            var contractRef = prefix + "task-contract.json";
            var resolutionRef = prefix + "contract-resolution.json";
            if (!compile.outputRefs().containsAll(List.of(contractRef, resolutionRef))
                    || !gateNode.inputRefs().containsAll(List.of(contractRef, resolutionRef)))
                throw new IOException("contract candidate references are not published by its compiler");
            var bytes = files.readBytes(root.resolve(contractRef));
            var resolution = files.readBytes(root.resolve(resolutionRef));
            var contract = TaskContractArtifactWriter.mapper().readValue(bytes, TaskContract.class);
            if (contract.phase() != TaskContract.Phase.EXECUTION || !TaskContractValidator.validate(contract).isEmpty()
                    || !contract.id().equals(compile.result().get("contract_id"))
                    || contract.epoch() != longValue(compile.result().get("contract_epoch"))
                    || contract.version() != intValue(compile.result().get("contract_version"))
                    || !contract.status().name().equals(compile.result().get("contract_status"))
                    || !TaskContractArtifactWriter.sha256(bytes).equals(compile.result().get("task_contract_sha256"))
                    || !TaskContractArtifactWriter.sha256(resolution).equals(compile.result().get("contract_resolution_sha256")))
                throw new IOException("contract candidate bytes or identity changed");
            var failure = validateExecutionInputs(snapshot, files, compile, contract, requireReady);
            if (failure != null) throw new IOException(failure.reason() + ": " + failure.message());
            return new CandidateProjection(contract, OBJECT_MAPPER.readValue(bytes, MAP_TYPE), new String(bytes, StandardCharsets.UTF_8),
                    OBJECT_MAPPER.readValue(resolution, MAP_TYPE), new String(resolution, StandardCharsets.UTF_8), contractRef, resolutionRef);
        });
    }



    static Optional<String> trustedWrappedPayload(
            WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            List<String> inputRefs
    ) {
        var binding = AcceptanceContextBinding.fromRefs(workspaceRoot, workstreamId, nodeId, inputRefs, OBJECT_MAPPER);
        if (binding.isEmpty()) {
            return Optional.empty();
        }
        var resolution = resolve(ledger, workspaceRoot, workstreamId);
        if (resolution.failure() != null || resolution.qualified().isEmpty()) {
            throw new IllegalArgumentException(resolution.failure() == null
                    ? "qualified task contract is required"
                    : resolution.failure().reason() + ": " + resolution.failure().message());
        }
        var qualified = resolution.qualified().orElseThrow();
        var mismatch = binding.get().validate(qualified);
        if (mismatch.isPresent()) {
            throw new IllegalArgumentException(mismatch.get().reason() + ": " + mismatch.get().message());
        }
        return Optional.of(qualified.wrappedPayload());
    }

    static Resolution resolveRoutedAcceptance(
            WorkflowFileLedger ledger,
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            List<String> inputRefs
    ) {
        final Optional<AcceptanceContextBinding> binding;
        try {
            binding = AcceptanceContextBinding.fromRefs(
                    workspaceRoot, workstreamId, nodeId, inputRefs, OBJECT_MAPPER);
        } catch (IllegalArgumentException failure) {
            return Resolution.failed(Failure.of("CONTEXT_BINDING_INVALID", failure.getMessage()));
        }
        if (binding.isEmpty()) {
            return Resolution.absent();
        }
        var resolution = resolve(ledger, workspaceRoot, workstreamId);
        if (resolution.failure() != null || resolution.qualified().isEmpty()) {
            return resolution.failure() == null
                    ? Resolution.failed(Failure.of("COMPILE_BINDING_MISSING", "qualified task contract is required"))
                    : resolution;
        }
        var mismatch = binding.get().validate(resolution.qualified().orElseThrow());
        return mismatch.map(Resolution::failed).orElse(resolution);
    }

    private static OccurrenceRead lastContractGateOccurrence(LedgerSession files, Path eventsPath) throws IOException {
        if (!files.exists(eventsPath)) {
            return new OccurrenceRead(null, null);
        }
        ContractGateOccurrence last = null;
        long previous = -1;
        try {
            for (var line : files.readLines(eventsPath)) {
                if (line.isBlank()) {
                    continue;
                }
                final Map<String, Object> event;
                try {
                    event = OBJECT_MAPPER.readValue(line, MAP_TYPE);
                } catch (Exception failure) {
                    return new OccurrenceRead(null, Failure.of(
                            "EVENT_HISTORY_INVALID", "workflow event history contains invalid JSON"));
                }
                var eventId = text(event.get("event_id"));
                var matcher = WORKFLOW_EVENT_ID.matcher(eventId);
                if (!matcher.matches()) {
                    if ("node_routed".equals(text(event.get("event_type")))) {
                        return new OccurrenceRead(null, Failure.of(
                                "EVENT_HISTORY_INVALID", "routing event does not have a workflow event id"));
                    }
                    continue;
                }
                var sequence = Long.parseLong(matcher.group(1));
                if (sequence <= previous) {
                    return new OccurrenceRead(null, Failure.of(
                            "EVENT_HISTORY_INVALID", "workflow event history is not strictly ordered"));
                }
                previous = sequence;
                if (!"node_routed".equals(text(event.get("event_type")))) {
                    continue;
                }
                var payload = map(event.get("payload"));
                if (!"gate.contract_review".equals(text(payload.get("to")))) {
                    continue;
                }
                var gateId = text(payload.get("gate_id"));
                var nodeInstanceId = text(payload.get("node_instance_id"));
                var sourceNodeInstanceId = text(payload.get("source_node_instance_id"));
                var from = text(payload.get("from"));
                if (gateId.isBlank() || nodeInstanceId.isBlank()
                        || sourceNodeInstanceId.isBlank() || from.isBlank()) {
                    return new OccurrenceRead(null, Failure.of(
                            "GATE_SOURCE_MISSING", "contract gate routing event has incomplete source lineage"));
                }
                last = new ContractGateOccurrence(eventId, gateId, nodeInstanceId, sourceNodeInstanceId, from);
            }
            return new OccurrenceRead(last, null);
        } catch (IOException failure) {
            return new OccurrenceRead(null, Failure.of(
                    "EVENT_HISTORY_UNREADABLE", "cannot read workflow event history"));
        }
    }

    private static GateRead readGate(LedgerSession files, Path path) throws IOException {
        if (!files.exists(path)) {
            return new GateRead(null, Failure.of("GATE_DOCUMENT_MISSING", "contract approval gate document is missing"));
        }
        try {
            return new GateRead(files.read(path, GateDocument.class), null);
        } catch (Exception failure) {
            return new GateRead(null, Failure.of("GATE_DOCUMENT_INVALID", "contract approval gate document cannot be parsed"));
        }
    }

    private static NodeInstanceDocument node(List<NodeInstanceDocument> nodes, String nodeInstanceId) {
        var matches = nodes.stream().filter(node -> node.nodeInstanceId().equals(nodeInstanceId)).toList();
        return matches.size() == 1 ? matches.getFirst() : null;
    }

    private static NodeInstanceDocument newerCompletedCompile(
            List<NodeInstanceDocument> nodes,
            NodeInstanceDocument approved
    ) {
        if (approved.finishedAt() == null) {
            return approved;
        }
        return nodes.stream()
                .filter(node -> !node.nodeInstanceId().equals(approved.nodeInstanceId()))
                .filter(node -> "contract.compile".equals(node.handlerType()))
                .filter(node -> "EXECUTION".equals(text(node.result().get("contract_phase"))))
                .filter(node -> node.status() == NodeStatus.COMPLETED)
                .filter(node -> node.finishedAt() == null || !node.finishedAt().isBefore(approved.finishedAt()))
                .findFirst()
                .orElse(null);
    }

    private static Nodes readNodes(LedgerSession files, Path nodesDir) throws IOException {
        if (!files.exists(nodesDir)) {
            return new Nodes(List.of(), null);
        }
        var nodes = new ArrayList<NodeInstanceDocument>();
        try (var paths = files.list(nodesDir).stream()) {
            for (var path : paths.filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted().toList()) {
                try {
                    nodes.add(files.read(path, NodeInstanceDocument.class));
                } catch (Exception failure) {
                    return new Nodes(List.of(), Failure.of(
                            "NODE_LEDGER_UNREADABLE", "cannot read node ledger document " + path.getFileName()));
                }
            }
            return new Nodes(List.copyOf(nodes), null);
        } catch (IOException failure) {
            return new Nodes(List.of(), Failure.of("NODE_LEDGER_UNREADABLE", "cannot list node ledger"));
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object value) {
        return value instanceof Map<?, ?> raw ? (Map<String, Object>) raw : Map.of();
    }

    private static List<String> textList(Object value) {
        return value instanceof List<?> list ? list.stream().map(String::valueOf).toList() : List.of();
    }

    private static long longValue(Object value) { return value instanceof Number n ? n.longValue() : -1; }

    private static int intValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException ignored) {
            return Integer.MIN_VALUE;
        }
    }

    record QualifiedTaskContract(
            String rawJson,
            TaskContract contract,
            Map<String, Object> document,
            String sha256,
            String contractRef,
            String rawResolutionJson,
            Map<String, Object> resolutionDocument,
            String resolutionSha256,
            String resolutionRef,
            String compileNodeInstanceId,
            String compileNodeRef,
            String approvalGateRef,
            String approvalEventId
    ) {
        String wrappedPayload() {
            return TypedContextPayloadBoundary.wrap("```json\n" + rawJson + "\n```");
        }
    }

    record Failure(String reason, String message) {
        static Failure of(String reason, String message) {
            return new Failure(reason, message);
        }
    }

    record CandidateProjection(TaskContract contract, Map<String, Object> document, String rawJson,
                               Map<String, Object> resolutionDocument, String rawResolutionJson,
                               String contractRef, String resolutionRef) {}





    record Resolution(Optional<QualifiedTaskContract> qualified, Failure failure) {
        static Resolution absent() {
            return new Resolution(Optional.empty(), null);
        }

        static Resolution qualified(QualifiedTaskContract contract) {
            return new Resolution(Optional.of(contract), null);
        }

        static Resolution failed(Failure failure) {
            return new Resolution(Optional.empty(), failure);
        }
    }

    private record Nodes(List<NodeInstanceDocument> nodes, Failure failure) {
    }

    private record ContractGateOccurrence(
            String eventId,
            String gateId,
            String nodeInstanceId,
            String sourceNodeInstanceId,
            String fromNodeDefinitionId
    ) {
    }

    private record OccurrenceRead(ContractGateOccurrence occurrence, Failure failure) {
    }

    private record GateRead(GateDocument gate, Failure failure) {
    }

    private record AcceptanceContextBinding(String sha256, String compileNodeRef) {
        static Optional<AcceptanceContextBinding> fromRefs(
                Path workspaceRoot,
                String workstreamId,
                String nodeId,
                List<String> inputRefs,
                ObjectMapper objectMapper
        ) {
            var root = workspaceRoot.toAbsolutePath().normalize();
            var contextDir = root.resolve(".agent/workstreams").resolve(workstreamId).resolve("context").normalize();
            var matches = new ArrayList<Map<String, Object>>();
            for (var ref : inputRefs == null ? List.<String>of() : inputRefs) {
                var path = root.resolve(ref).normalize();
                if (!path.startsWith(contextDir)
                        || !contextDir.equals(path.getParent())
                        || !path.getFileName().toString().endsWith(".json")
                        || !Files.isRegularFile(path)
                        || Files.isSymbolicLink(path)) {
                    continue;
                }
                try {
                    var document = objectMapper.readValue(path.toFile(), MAP_TYPE);
                    if ("acceptance".equals(text(document.get("profile")))
                            && nodeId.equals(text(document.get("targetNode")))) {
                        matches.add(document);
                    }
                } catch (IOException failure) {
                    throw new IllegalArgumentException("cannot read routed acceptance context metadata", failure);
                }
            }
            if (matches.isEmpty()) {
                return Optional.empty();
            }
            if (matches.size() != 1) {
                throw new IllegalArgumentException("multiple routed acceptance context metadata documents");
            }
            var document = matches.getFirst();
            var sha256 = text(document.get("taskContractSha256"));
            var compileNodeRef = text(document.get("taskContractCompileNodeRef"));
            if (sha256.isBlank() || compileNodeRef.isBlank()) {
                throw new IllegalArgumentException("routed acceptance context metadata has no task contract binding");
            }
            return Optional.of(new AcceptanceContextBinding(sha256, compileNodeRef));
        }

        Optional<Failure> validate(QualifiedTaskContract qualified) {
            if (!sha256.equals(qualified.sha256())) {
                return Optional.of(Failure.of(
                        "CONTEXT_BINDING_HASH_MISMATCH", "routed context SHA does not match current task contract"));
            }
            if (!compileNodeRef.equals(qualified.compileNodeRef())) {
                return Optional.of(Failure.of(
                        "CONTEXT_BINDING_LINEAGE_MISMATCH", "routed context compile ref does not match current binding"));
            }
            return Optional.empty();
        }
    }
}

