package dev.dual.runtime.handler;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Estimates token count for text content.
 * Default implementation uses a simple character-to-token ratio (~4 chars/token for English).
 * Can be replaced with a real tokenizer (tiktoken, BPE) in the future.
 */
interface TokenEstimator {

    /** Estimate token count for the given text. */
    int estimate(String text);

    /** Estimate token count for the content of a file. */
    int estimateFile(Path path);

    /** Default estimator: ~4 chars per token (conservative for mixed CJK/English). */
    static TokenEstimator defaultEstimator() {
        return new CharRatioEstimator(4);
    }

    /** Create an estimator with a custom chars-per-token ratio. */
    static TokenEstimator withRatio(int charsPerToken) {
        return new CharRatioEstimator(charsPerToken);
    }
}

final class CharRatioEstimator implements TokenEstimator {
    private final int ratio;

    CharRatioEstimator(int ratio) {
        if (ratio <= 0) throw new IllegalArgumentException("ratio must be positive");
        this.ratio = ratio;
    }

    @Override
    public int estimate(String text) {
        if (text == null || text.isEmpty()) return 0;
        return (text.length() + ratio - 1) / ratio;
    }

    @Override
    public int estimateFile(Path path) {
        try {
            if (!Files.exists(path)) return 0;
            var content = Files.readString(path, StandardCharsets.UTF_8);
            return estimate(content);
        } catch (IOException e) {
            return 0;
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.io.IOException;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.function.UnaryOperator;

/**
 * Marks verified typed payloads inside a context package so later free-text
 * projections can preserve their serialized bytes.
 */
public final class TypedContextPayloadBoundary {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    static final String START = "<!-- dual:typed-payload:start -->";
    static final String END = "<!-- dual:typed-payload:end -->";

    private TypedContextPayloadBoundary() {
    }

    public static String wrap(String payload) {
        return START + "\n" + Objects.requireNonNull(payload, "payload") + "\n" + END;
    }

    public static String wrapJson(Object payload) {
        try {
            return wrap("```json\n"
                    + OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(payload)
                    + "\n```");
        } catch (IOException failure) {
            throw new IllegalArgumentException("typed context payload cannot be serialized", failure);
        }
    }

    public static Optional<String> wrapVerifiedProposal(
            TaskContractProposalReference reference,
            Path workspaceRoot,
            String workstreamId,
            ObjectMapper objectMapper
    ) {
        return reference.resolveVerifiedProposal(workspaceRoot, workstreamId, objectMapper)
                .map(TypedContextPayloadBoundary::wrapJson);
    }

    public static TrustedPayloads trustOnce(Set<String> trustedWrappedPayloads) {
        return new TrustedPayloads(trustedWrappedPayloads);
    }

    public static String transformUntyped(
            String content,
            TrustedPayloads trustedPayloads,
            UnaryOperator<String> transform
    ) {
        Objects.requireNonNull(content, "content");
        Objects.requireNonNull(trustedPayloads, "trustedPayloads");
        Objects.requireNonNull(transform, "transform");
        var result = new StringBuilder(content.length());
        int cursor = 0;
        while (cursor < content.length()) {
            int start = content.indexOf(START, cursor);
            if (start < 0) {
                result.append(transform.apply(content.substring(cursor)));
                break;
            }
            int end = content.indexOf(END, start + START.length());
            if (end < 0) {
                // An incomplete boundary is not trusted; sanitize it as free text.
                result.append(transform.apply(content.substring(cursor)));
                break;
            }
            result.append(transform.apply(content.substring(cursor, start)));
            int boundaryEnd = end + END.length();
            var candidate = content.substring(start, boundaryEnd);
            if (trustedPayloads.consume(candidate)) {
                result.append(content, start + START.length(), end);
            }
            cursor = boundaryEnd;
        }
        return result.toString();
    }

    public static final class TrustedPayloads {
        private final Set<String> remaining;

        private TrustedPayloads(Set<String> trustedWrappedPayloads) {
            this.remaining = new HashSet<>(Objects.requireNonNull(
                    trustedWrappedPayloads, "trustedWrappedPayloads"));
        }

        private boolean consume(String candidate) {
            return remaining.remove(candidate);
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.execution.AgentExecutionEvidence.ToolObservation;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeResult;
import dev.dual.ledger.file.*;
import java.io.IOException;
import java.nio.file.*;
import java.util.*;

/** Program-owned execution observations and criterion evidence checks. Never executes a test or judges assertion prose. */
public final class VerificationEvidence {
    private static final ObjectMapper JSON = new ObjectMapper().findAndRegisterModules();
    public static final String FACT = "verification_observations";
    private static final String FILE = "verification-observations.json";
    public record Baseline(TaskContract.Reference contract, EvidenceCollectionSource source) {}
    public record Observation(String schema, String workstream, String node, String execution, String run,
                              String agent, Map<String, String> prepared, Baseline baseline,
                              EvidenceCollectionSource afterSource, List<ToolObservation> tools, List<dev.dual.core.execution.AdapterSignal> permissionSignals) {}
    private VerificationEvidence() {}

    public static Baseline prepare(TaskHandler.TaskContext context) throws IOException {
        var qualified = TaskContractProjectionVerifier.resolve(context.ledger(), context.workspaceRoot(), context.workstreamId(),
                TaskContract.Phase.EXECUTION).qualified().orElseThrow(() -> new IOException("approved EXECUTION required for source capture"));
        return new Baseline(new TaskContract.Reference(qualified.contractRef(), qualified.sha256()),
                EvidenceCollectionSource.capture(context.workspaceRoot(), qualified.contract().scope().included().stream()
                        .map(TaskContract.ScopeEntry::path).toList()));
    }

    public static NodeResult record(TaskHandler.TaskContext context, AgentRunCommitProtocol.Prepared prepared,
                                    Baseline baseline, String agent, List<ToolObservation> observations, NodeResult result) throws IOException {
        if (baseline == null) return result;
        var runDir = prepared.path().getParent().getParent();
        var record = new Observation("dual.verification.observations.v1", context.workstreamId(),
                context.instance().nodeInstanceId(), prepared.execution().nodeExecutionId(), runDir.getFileName().toString(),
                agent, prepared.reference(), baseline,
                EvidenceCollectionSource.capture(context.workspaceRoot(), baseline.source().paths()), List.copyOf(observations), AgentRunMetadataFinalizer.resultAdapterSignals(result));
        var ref = AgentRunCommitProtocol.recordObservation(context.workspaceRoot(), context.workstreamId(), prepared, record);
        var facts = new LinkedHashMap<String, Object>(result.result()); facts.put(FACT, ref);
        var outputs = new ArrayList<>(result.outputRefs()); outputs.add(ref.ref());
        return new NodeResult(result.outcome(), result.status(), List.copyOf(outputs), facts, result.errorMessage());
    }

    static List<AgentResultEnvelope.VerificationCheck> checks(AgentResultEnvelope.AgentResult result) {
        return result instanceof AgentResultEnvelope.SelfTestResult self ? self.verificationChecks()
                : result instanceof AgentResultEnvelope.AcceptanceReviewResult acceptance ? acceptance.verificationChecks() : null;
    }

    /** Required routed evidence is current execution input, not a historical display. */
    static void verifyRequired(WorkflowFileLedger ledger, Path root, String ws, List<String> refs, Object configured) throws IOException {
        require(configured instanceof Map<?, ?>, "required evidence definition is missing");
        var required = (Map<?, ?>) configured;
        var matches = AgentEvidenceIndex.fromRefs(ledger, root, ws, refs, JSON).recent(refs.size()).stream()
                .map(AgentEvidenceIndex.Entry::document)
                .filter(d -> Objects.equals(required.get("node_id"), d.nodeId())
                        && Objects.equals(required.get("source_artifact_type"), d.sourceArtifactType())
                        && Objects.equals(required.get("decision"), d.decision()) && d.hasRequiredTypedPayload()).toList();
        require(matches.size() == 1, "exactly one routed required evidence occurrence is needed");
        verifyPublished(ledger, root, ws, matches.getFirst());
    }

    /** Recheck the completed context's actual inputs immediately before a verifier command. */
    static void verifyAcceptanceInputs(TaskHandler.TaskContext context) throws IOException {
        if (!"acceptance_review".equals(context.definition().config().get("expected_artifact"))) return;
        var root = context.workspaceRoot();
        var paths = new WorkstreamPaths(root, new DualId(context.workstreamId()));
        var prefix = ".agent/workstreams/" + context.workstreamId() + "/context/";
        var packages = context.instance().inputRefs().stream()
                .filter(r -> r.startsWith(prefix) && r.endsWith(".md") && !r.substring(prefix.length()).contains("/")).toList();
        require(packages.size() == 1, "acceptance requires one routed context occurrence");
        var ref = packages.getFirst();
        var id = ref.substring(prefix.length(), ref.length() - 3);
        var producer = context.ledger().loadNode(paths, id);
        require(producer.status() == dev.dual.core.workflow.NodeStatus.COMPLETED
                && "context.build_package".equals(producer.handlerType()) && producer.outputRefs().contains(ref)
                && producer.iterationId().equals(context.instance().iterationId()), "invalid acceptance context producer");
        var definition = context.ledger().loadDefinition(paths).node(producer.nodeDefinitionId());
        require("acceptance".equals(definition.config().get("profile"))
                && context.definition().id().equals(definition.config().get("target_node")), "wrong acceptance context target");
        verifyRequired(context.ledger(), root, context.workstreamId(), producer.inputRefs(), definition.config().get("required_agent_evidence"));
    }

    static void verifyPublished(WorkflowFileLedger ledger, Path root, String ws, AgentOutputContractDocument document) throws IOException {
        if (!("self_test_report".equals(document.sourceArtifactType()) && "SELF_TEST_COMPLETE".equals(document.decision())
                || "acceptance_review".equals(document.sourceArtifactType()) && accepted(document.decision()))) return;
        var paths = new WorkstreamPaths(root, new DualId(ws));
        var fixed = ledger.inspect(paths, (snapshot, files) -> {
            var node = snapshot.loadNode(paths, document.nodeInstanceId());
            var execution = snapshot.latestNodeExecution(paths, node).orElseThrow(() -> new IOException("verification lacks its execution"));
            var result = AgentRunCommitProtocol.readCompletion(paths, execution);
            require(result.outputRefs().contains(document.sourceOutputRef()), "verification source is not in the fixed completion");
            return result;
        });
        var parsed = new AgentResultEnvelopeParser().parse(Files.readString(root.resolve(document.sourceOutputRef())));
        require(parsed.valid() && document.decision().equals(parsed.envelope().result().decision()), "invalid published verification result");
        verify(ledger, root, ws, document.nodeInstanceId(), fixed, parsed.envelope().result());
    }

    static void verifyPublication(WorkflowFileLedger ledger, Path root, String ws, String node,
                                  NodeResult execution, TaskContract.Reference candidate) throws IOException {
        var parsed = new AgentResultEnvelopeParser().parse(new String(read(root, candidate), java.nio.charset.StandardCharsets.UTF_8));
        require(parsed.valid(), "fixed publication candidate is invalid");
        verify(ledger, root, ws, node, execution, parsed.envelope().result());
    }

    /** Called before publication, again by completion/lineage consumers for the same approved requirements. */
    static void verify(WorkflowFileLedger ledger, Path root, String ws, String node, NodeResult executionResult,
                       AgentResultEnvelope.AgentResult result) throws IOException {
        boolean success = result instanceof AgentResultEnvelope.SelfTestResult && "SELF_TEST_COMPLETE".equals(result.decision())
                || result instanceof AgentResultEnvelope.AcceptanceReviewResult && accepted(result.decision());
        if (!success) return;
        var resolution = TaskContractProjectionVerifier.resolve(ledger, root, ws, TaskContract.Phase.EXECUTION);
        var qualified = resolution.qualified().orElseThrow(() -> new IOException("verification requires the approved EXECUTION contract"));
        var checks = checks(result);
        require(checks != null && checks.size() == qualified.contract().verificationBindings().size(),
                "successful verification requires one evidence check for each approved criterion");
        var seen = new HashSet<String>();
        var observations = new LinkedHashMap<String, Observation>();
        for (var check : checks) {
            require(check != null && seen.add(check.criterionId()) && check.assertion() != null && !check.assertion().isBlank(),
                    "missing/duplicate criterion assertion");
            var binding = qualified.contract().verificationBindings().stream().filter(b -> b.criterionId().equals(check.criterionId()))
                    .findFirst().orElseThrow(() -> new IOException("unapproved verification criterion"));
            require(dev.dual.core.contract.TaskContractValidator.verificationEvidenceErrors(binding).isEmpty(), "invalid evidence requirements");
            require(check.materialRefs() != null && check.toolCallIds() != null, "evidence selectors must be explicit");
            if (binding.evidenceKind() == TaskContract.EvidenceKind.OPERATOR_DECLARATION_WITH_MATERIAL) {
                var refs = EvidenceCollection.requiredReferences(ledger, root, ws, node);
                require(!refs.isEmpty() && refs.getFirst().equals(check.executionRef()),
                        "operator assertion requires the bound, verified external submission");
                require(!check.materialRefs().isEmpty() && check.materialRefs().stream().allMatch(r -> r != null && refs.subList(1, refs.size()).contains(r.ref())),
                        "operator assertion must reference the submitted materials");
                require(check.toolCallIds().isEmpty(), "operator declaration cannot claim program tool calls");
            } else {
                var evidence = observations.get(check.executionRef());
                if (evidence == null) {
                    evidence = load(ledger, root, ws, node, executionResult, check.executionRef());
                    observations.put(check.executionRef(), evidence);
                }
                require(evidence.baseline().contract().equals(new TaskContract.Reference(qualified.contractRef(), qualified.sha256())),
                        "tool evidence belongs to a different approved contract");
                require(evidence.baseline().source().equals(evidence.afterSource()), "source changed during observed execution");
                // An empty selection means the fixed execution's complete tool-result set, so clients
                // need not copy opaque ACP IDs. It never means that no observed execution is required.
                var selected = check.toolCallIds().isEmpty() ? evidence.tools().stream()
                        .filter(ToolObservation::hasExecutionResult).map(ToolObservation::toolCallId).toList() : check.toolCallIds();
                require(!selected.isEmpty() && new HashSet<>(selected).size() == selected.size(),
                        "criterion must have actual tool results without duplicate identities");
                var selectedObservations = new ArrayList<ToolObservation>();
                for (var callId : selected) {
                    require(callId != null && !callId.isBlank(), "tool call identity is missing");
                    var matches = evidence.tools().stream().filter(t -> callId.equals(t.toolCallId())).toList();
                    require(matches.size() == 1 && matches.getFirst().hasExecutionResult(), "missing, ambiguous or incomplete tool call: " + callId);
                    selectedObservations.add(matches.getFirst());
                }
                verifySelectedExits(binding, selectedObservations);
            }
            for (var material : check.materialRefs()) read(root, material);
        }
        // One fresh source read per distinct baseline at this consumption point. Multiple
        // criteria sharing the same execution do not each launch another Git inventory.
        // Nothing is cached across preparation, dispatch, publication or recovery calls.
        for (var source : observations.values().stream().map(Observation::afterSource).distinct().toList())
            require(source.equals(EvidenceCollectionSource.capture(root, source.paths())), "source changed after observed execution");
    }

    public static void verifyExit(TaskContract.VerificationBinding binding, ToolObservation observation) throws IOException {
        if (!Boolean.TRUE.equals(binding.actualExitRequired())) return;
        require(observation.actualExitCode() != null && observation.actualExitSource() != null
                && !observation.actualExitSource().isBlank(), "required actual process exit is unavailable; native status is insufficient");
        require(binding.expectedExitCode() == null || binding.expectedExitCode().equals(observation.actualExitCode()),
                "actual process exit does not match approved requirement");
    }

    static void verifySelectedExits(TaskContract.VerificationBinding binding, List<ToolObservation> observations) throws IOException {
        if (!Boolean.TRUE.equals(binding.actualExitRequired())) return;
        // Reading a test report has no process exit. It may accompany a process result, but
        // cannot replace one or exempt an execution tool whose actual exit is unavailable.
        var executions = observations.stream().filter(t -> "execute".equals(t.kind()) || t.actualExitCode() != null).toList();
        require(!executions.isEmpty(), "required actual process exit is unavailable; native status is insufficient");
        for (var execution : executions) verifyExit(binding, execution);
    }

    static Observation load(WorkflowFileLedger ledger, Path root, String ws, String node, NodeResult result, String selector) throws IOException {
        require(selector != null && !selector.isBlank(), "execution_ref must be CURRENT or a fixed observation reference");
        TaskContract.Reference ref;
        boolean own = "CURRENT".equals(selector);
        if (own) {
            require(result.result().get(FACT) != null, "current execution has no program tool observation");
            ref = JSON.convertValue(result.result().get(FACT), TaskContract.Reference.class);
        } else {
            var path = root.resolve(selector).normalize();
            require(path.startsWith(root.toAbsolutePath().normalize()) && path.getFileName().toString().equals(FILE), "invalid tool observation selector");
            ref = new TaskContract.Reference(selector, TaskContractArtifactWriter.sha256(path));
        }
        require(ref.ref().startsWith(".agent/workstreams/" + ws + "/runs/") && ref.ref().endsWith("/outputs/" + FILE), "foreign observation reference");
        var observed = JSON.readValue(read(root, ref), Observation.class);
        require(observed != null && observed.prepared() != null && observed.prepared().get("ref") != null
                && observed.baseline() != null && observed.baseline().source() != null && observed.baseline().contract() != null
                && observed.afterSource() != null && observed.tools() != null && observed.tools().stream().noneMatch(Objects::isNull),
                "incomplete observation record");
        require("dual.verification.observations.v1".equals(observed.schema()) && ws.equals(observed.workstream()), "invalid observation schema/workstream");
        require(ref.ref().equals(".agent/workstreams/" + ws + "/runs/" + observed.run() + "/outputs/" + FILE)
                && observed.prepared().get("ref").equals(".agent/workstreams/" + ws + "/runs/" + observed.run()
                    + "/outputs/" + observed.execution() + "-prepared.json"), "observation run differs from its preparation");
        if (own) require(node.equals(observed.node()) && observed.run().equals(String.valueOf(result.result().get("run_id"))), "foreign current observation");
        var paths = new WorkstreamPaths(root, new DualId(ws));
        ledger.inspect(paths, (snapshot, files) -> {
            var execution = files.read(paths.nodeExecutionJson(observed.execution()), NodeExecutionDocument.class);
            require(execution.nodeInstanceId().equals(observed.node()) && observed.prepared().equals(execution.result().get("prepared_run")),
                    "tool observation lacks its actual prepared execution binding");
            var prepared = JSON.readTree(read(root, new TaskContract.Reference(observed.prepared().get("ref"), observed.prepared().get("sha256"))));
            require(prepared.path("binding").path("verification_source").equals(JSON.valueToTree(observed.baseline())), "source identity is not the prepared baseline");
            if (!own) {
                var completed = AgentRunCommitProtocol.readCompletion(paths, execution);
                require(completed.outputRefs().contains(ref.ref())
                        && JSON.valueToTree(ref).equals(JSON.valueToTree(completed.result().get(FACT))),
                        "observation was not fixed by its original execution completion");
            }
            return null;
        });
        return observed;
    }

    static byte[] read(Path root, TaskContract.Reference ref) throws IOException {
        require(ref != null && ref.ref() != null && ref.sha256() != null && ref.sha256().matches("[0-9a-f]{64}")
                && !Path.of(ref.ref()).isAbsolute() && !ref.ref().isBlank(), "invalid evidence reference");
        var file = root.toAbsolutePath().normalize().resolve(ref.ref());
        require(file.normalize().equals(file) && file.startsWith(root.toAbsolutePath().normalize()), "evidence path escapes workspace");
        require(file.toRealPath().equals(root.toRealPath().resolve(ref.ref())), "noncanonical evidence path");
        var bytes = Files.readAllBytes(file);
        require(ref.sha256().equals(TaskContractArtifactWriter.sha256(bytes)), "evidence bytes changed");
        return bytes;
    }
    private static boolean accepted(String decision) { return "ACCEPT".equals(decision) || "ACCEPT_WITH_NOTES".equals(decision); }
    private static void require(boolean condition, String message) throws IOException { if (!condition) throw new IOException(message); }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/** Operator-owned readiness, never a tool result, execution approval or test verdict. */
public final class VerificationReadiness {
    public static final String REQUIRED = "VERIFICATION_READINESS_REQUIRED";
    private static final String EVENT = "verification_readiness_recorded";
    private static final String RULE = "verification-readiness-v1";
    private static final ObjectMapper JSON = new ObjectMapper().registerModule(new JavaTimeModule());

    public enum Action { RECORD, WITHDRAW }
    public enum Lifetime { AUTHORIZATION_EPOCH, EXPIRES_AT }
    public record Dependency(String path, String sha256, boolean absent) {}
    public record Environment(String workspace, String identity, String owner,
                              List<Dependency> dependencies) {
        public Environment { dependencies = List.copyOf(dependencies == null ? List.of() : dependencies); }
    }
    public record Request(int schema, String requestId, String subject,
                          TaskContract.Reference goal, long epoch, List<String> criterionIds,
                          String method, TaskContract.Executor executor, TaskContract.EvidenceKind evidenceKind,
                          Environment environment, String statement, String detailOwner,
                          Lifetime lifetime, Instant expiresAt, Action action,
                          TaskContract.Reference supersedes) {
        public Request { criterionIds = List.copyOf(criterionIds == null ? List.of() : criterionIds); }
    }
    public record Record(Request request, Instant receivedAt, String source, String rule) {}

    private VerificationReadiness() {}

    public static Request readRequest(Path file) throws IOException {
        return JSON.readValue(file.toFile(), Request.class);
    }

    public static TaskContract.Reference record(WorkflowFileLedger ledger, Path root, String workstreamId,
                                                 Request request) throws IOException {
        require(request != null && request.requestId() != null
                && request.requestId().matches("[A-Za-z0-9._-]{1,80}"), "invalid request identity");
        require(nonblank(request.subject()), "subject occurrence is required");
        var paths = new WorkstreamPaths(root.toAbsolutePath().normalize(), new DualId(workstreamId));
        try (var write = ledger.writeSession(paths, "record verification readiness", request.requestId())) {
            var owned = write.ledger();
            var ref = prefix(workstreamId) + request.requestId() + ".json";
            var target = paths.workspaceRoot().resolve(ref);
            if (write.files().exists(target)) {
                var previous = write.files().read(target, Record.class);
                require(previous.request().equals(request), "request id already has different content");
                var identity = new TaskContract.Reference(ref, TaskContractArtifactWriter.sha256(write.files().readBytes(target)));
                registered(owned, paths, identity);
                write.commit();
                return identity;
            }
            var current = owned.loadCurrent(paths);
            require(Set.of(WorkflowStatus.WAITING_FOR_HUMAN, WorkflowStatus.WAITING_FOR_RECOVERY)
                    .contains(current.status()) && current.activeNodeInstanceIds().equals(List.of(request.subject())),
                    "subject must be the current waiting occurrence");
            var node = owned.loadNode(paths, request.subject());
            var definition = owned.loadDefinition(paths).node(node.nodeDefinitionId());
            var gate = node.kind() == NodeKind.GATE && node.status() == NodeStatus.WAITING
                    && Set.of("plan", "contract").contains(definition.config().get("gate_purpose"));
            var failedPreparation = node.status() == NodeStatus.FAILED
                    && (REQUIRED.equals(node.result().get("readiness_reason"))
                    || node.result().get("input_preparation_failure") instanceof Map<?, ?> failure
                    && REQUIRED.equals(failure.get("code")) && Boolean.FALSE.equals(failure.get("providerInvoked")));
            require(gate || failedPreparation, "subject is not a readiness gate or failed preparation");
            var resolution = TaskContractProjectionVerifier.resolve(owned, paths.workspaceRoot(), workstreamId, TaskContract.Phase.GOAL);
            var goal = resolution.qualified().orElseThrow(() -> missing("current approved GOAL required"));
            validateRequest(request, paths.workspaceRoot(), goal, Instant.now());
            var active = activeRecords(owned, paths, goal);
            if (request.supersedes() != null) {
                var prior = active.stream().filter(r -> r.reference().equals(request.supersedes())).findFirst()
                        .orElseThrow(() -> missing("superseded record is not active in this GOAL"));
                require(new HashSet<>(prior.record().request().criterionIds()).equals(new HashSet<>(request.criterionIds())),
                        "replacement must identify the same criteria");
            } else {
                require(request.action() == Action.RECORD, "withdraw requires the original reference");
            }
            if (request.action() == Action.RECORD) {
                require(active.stream().filter(r -> !r.reference().equals(request.supersedes()))
                        .noneMatch(r -> r.record().request().criterionIds().stream().anyMatch(request.criterionIds()::contains)),
                        "conflicting readiness requires an explicit replacement");
            }
            // L04 stores bytes, subject refs and the event in one prepared mutation.
            var bytes = JSON.writeValueAsBytes(new Record(request, Instant.now(), "OPERATOR_ATTESTED", RULE));
            var identity = new TaskContract.Reference(ref, TaskContractArtifactWriter.sha256(bytes));
            owned.recordReadiness(paths, request.subject(), identity, bytes);
            write.commit();
            return identity;
        }
    }

    static void validateBindings(WorkflowFileLedger ledger, Path root, String ws,
                                 TaskContractProjectionVerifier.QualifiedTaskContract goal,
                                 List<TaskContract.VerificationBinding> bindings) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(ws));
        var active = activeRecords(ledger, paths, goal);
        var expected = goal.contract().acceptanceCriteria().stream().map(TaskContract.Clause::id).collect(java.util.stream.Collectors.toSet());
        var seen = new HashSet<String>();
        for (var binding : bindings) {
            require(dev.dual.core.contract.TaskContractValidator.verificationEvidenceErrors(binding).isEmpty(),
                    "verification exit evidence requirements must be explicit and consistent");
            require(expected.contains(binding.criterionId()) && seen.add(binding.criterionId()), "unexpected or duplicate criterion");
            require(!binding.environmentRefs().isEmpty() && !binding.feasibilityRefs().isEmpty(), "missing environment or feasibility reference");
            var refs = new HashSet<>(binding.environmentRefs()); refs.addAll(binding.feasibilityRefs());
            for (var ref : refs) {
                var value = active.stream().filter(r -> r.reference().equals(ref)).findFirst()
                        .orElseThrow(() -> missing("unregistered, withdrawn or superseded readiness: " + ref.ref()));
                var request = value.record().request();
                validateRequest(request, root, goal, Instant.now());
                require(request.criterionIds().contains(binding.criterionId()) && request.method().equals(binding.method())
                        && request.executor() == binding.executor() && request.evidenceKind() == binding.evidenceKind()
                        && request.detailOwner().equals(binding.detailOwner()), "readiness does not support the planned verification");
            }
        }
        require(seen.equals(expected), "every approved criterion needs a verification exit");
    }

    static boolean sameVerificationBoundary(WorkflowFileLedger ledger, WorkstreamPaths paths,
            List<TaskContract.VerificationBinding> before, List<TaskContract.VerificationBinding> after) throws IOException {
        if (before.size() != after.size()) return false;
        for (var old : before) {
            var matches = after.stream().filter(b -> b.criterionId().equals(old.criterionId())).toList();
            if (matches.size() != 1) return false;
            var next = matches.getFirst();
            if (!old.method().equals(next.method()) || old.executor() != next.executor()
                    || !Objects.equals(old.actualExitRequired(), next.actualExitRequired())
                    || !Objects.equals(old.expectedExitCode(), next.expectedExitCode())
                    || old.evidenceKind() != next.evidenceKind() || !old.detailOwner().equals(next.detailOwner())
                    || !old.authorityRefs().equals(next.authorityRefs())) return false;
            var oldEnvironments = new HashSet<Environment>();
            var nextEnvironments = new HashSet<Environment>();
            for (var ref : old.environmentRefs()) oldEnvironments.add(registered(ledger, paths, ref).request().environment());
            for (var ref : next.environmentRefs()) nextEnvironments.add(registered(ledger, paths, ref).request().environment());
            if (!oldEnvironments.equals(nextEnvironments)) return false;
        }
        return true;
    }

    /** Reference projection for authors/reviewers; never changes readiness or grants authority. */
    static String context(WorkflowFileLedger ledger, Path root, String ws,
                          TaskContractProjectionVerifier.QualifiedTaskContract goal) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(ws));
        return ledger.inspect(paths, (snapshot, files) -> {
            var entries = new ArrayList<Map<String, Object>>();
            for (var bound : activeRecords(snapshot, paths, goal)) {
                String state = "CURRENT_OPERATOR_DECLARATION";
                String detail = "";
                try { validateRequest(bound.record().request(), root, goal, Instant.now()); }
                catch (IOException unavailable) { state = "UNAVAILABLE"; detail = unavailable.getMessage(); }
                entries.add(Map.of("reference", bound.reference(), "declaration", bound.record(),
                        "state", state, "detail", detail));
            }
            return "## Verification readiness declarations\n\n"
                    + "These are operator declarations of prerequisites, not execution results, successful tests or grants. "
                    + "Bind exact refs only where criterion, method, executor and environment match. "
                    + "If prerequisites are missing, describe the missing items without inventing references.\n\n"
                    + JSON.writerWithDefaultPrettyPrinter().writeValueAsString(entries) + "\n\n";
        });
    }

    private static void validateRequest(Request r, Path root,
                                        TaskContractProjectionVerifier.QualifiedTaskContract goal, Instant now) throws IOException {
        require(r.schema() == 1 && r.action() != null && r.goal() != null && r.epoch() == goal.contract().epoch()
                && r.goal().equals(new TaskContract.Reference(goal.contractRef(), goal.sha256())), "GOAL identity changed");
        require(!r.criterionIds().isEmpty() && new HashSet<>(r.criterionIds()).size() == r.criterionIds().size()
                && goal.contract().acceptanceCriteria().stream().map(TaskContract.Clause::id).toList().containsAll(r.criterionIds()),
                "readiness must name approved criteria");
        require(r.environment() != null && r.environment().workspace() != null
                && root.toRealPath().toString().equals(r.environment().workspace()), "workspace identity changed");
        require(nonblank(r.method()) && nonblank(r.statement()) && nonblank(r.detailOwner())
                && nonblank(r.environment().identity()) && nonblank(r.environment().owner()), "incomplete declaration");
        require((r.executor() == TaskContract.Executor.AGENT && r.evidenceKind() == TaskContract.EvidenceKind.PROGRAM_TOOL_EXECUTION_AND_ASSERTIONS)
                || (r.executor() == TaskContract.Executor.OPERATOR && r.evidenceKind() == TaskContract.EvidenceKind.OPERATOR_DECLARATION_WITH_MATERIAL),
                "executor and final evidence kind must agree");
        require(r.lifetime() != null && (r.lifetime() == Lifetime.EXPIRES_AT
                ? r.expiresAt() != null : r.expiresAt() == null), "readiness lifetime unspecified");
        // Withdrawing an expired or changed environment must remain possible.
        if (r.action() == Action.WITHDRAW) return;
        require(r.lifetime() != Lifetime.EXPIRES_AT || now.isBefore(r.expiresAt()), "readiness expired");
        var seen = new HashSet<String>();
        for (var dependency : r.environment().dependencies()) {
            require(dependency != null && dependency.path() != null && seen.add(dependency.path()), "duplicate environment dependency");
            var path = Path.of(dependency.path());
            require(path.isAbsolute() && path.normalize().equals(path), "environment dependency must be canonical and absolute");
            if (dependency.absent()) {
                require((dependency.sha256() == null || dependency.sha256().isBlank())
                        && !Files.exists(path, LinkOption.NOFOLLOW_LINKS), "previously absent dependency now exists");
            } else {
                require(Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS) && path.toRealPath().equals(path)
                        && TaskContractArtifactWriter.sha256(Files.readAllBytes(path)).equals(dependency.sha256()), "environment dependency changed");
            }
        }
    }

    private record Bound(TaskContract.Reference reference, Record record) {}

    private static List<Bound> activeRecords(WorkflowFileLedger ledger, WorkstreamPaths paths,
                                            TaskContractProjectionVerifier.QualifiedTaskContract goal) throws IOException {
        var active = new ArrayList<Bound>();
        for (var line : ledger.files().readLines(paths.eventsJsonl())) {
            var event = JSON.readTree(line);
            if (!EVENT.equals(event.path("event_type").asText())) continue;
            var ref = JSON.treeToValue(event.path("payload").path("reference"), TaskContract.Reference.class);
            var value = registered(ledger, paths, ref);
            var r = value.request();
            if (!Objects.equals(r.goal(), new TaskContract.Reference(goal.contractRef(), goal.sha256()))) continue;
            if (r.supersedes() != null) {
                require(active.removeIf(b -> b.reference().equals(r.supersedes())), "broken readiness replacement chain");
            }
            if (r.action() == Action.RECORD) active.add(new Bound(ref, value));
        }
        return List.copyOf(active);
    }

    private static Record registered(WorkflowFileLedger ledger, WorkstreamPaths paths, TaskContract.Reference ref) throws IOException {
        require(ref.ref().startsWith(prefix(paths.workstreamId().value())), "readiness reference belongs to another workstream");
        var bytes = ledger.files().readBytes(paths.workspaceRoot().resolve(ref.ref()));
        require(TaskContractArtifactWriter.sha256(bytes).equals(ref.sha256()), "readiness bytes changed");
        var record = JSON.readValue(bytes, Record.class);
        require("OPERATOR_ATTESTED".equals(record.source()) && RULE.equals(record.rule()) && record.receivedAt() != null
                && ref.ref().equals(prefix(paths.workstreamId().value()) + record.request().requestId() + ".json"), "invalid readiness producer");
        boolean event = false;
        for (var line : ledger.files().readLines(paths.eventsJsonl())) {
            var e = JSON.readTree(line);
            if (EVENT.equals(e.path("event_type").asText()) && e.path("payload").path("reference").equals(JSON.valueToTree(ref))) {
                require(!event && record.request().subject().equals(e.path("payload").path("subject").asText()), "invalid readiness registration");
                event = true;
            }
        }
        require(event, "readiness was not committed by its owner");
        return record;
    }

    private static String prefix(String ws) { return ".agent/workstreams/" + ws + "/artifacts/verification-readiness/"; }
    private static boolean nonblank(String s) { return s != null && !s.isBlank(); }
    private static IOException missing(String detail) { return new IOException(REQUIRED + ": " + detail); }
    private static void require(boolean condition, String detail) throws IOException { if (!condition) throw missing(detail); }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Read-only projector from {@code workstream-memory.json} into the agent-facing
 * context-package memory sections.
 *
 * <p>The {@code working_memory} section (Claude implement) renders an
 * {@link #appendAgentHandoff AgentHandoff}; the {@code review_evidence} section
 * (Codex review) renders a {@link #appendReviewEvidenceBrief ReviewEvidenceBrief}.
 * Both are projections of the orchestrator-owned {@code WorkstreamMemory} (the
 * source of truth), not of the rebuilt {@code EvidenceManifest}. They embed real
 * ledger evidence refs so accuracy does not depend on dump volume: scope source,
 * prior verdict artifact path, changed-files/diff path, and readFiles with
 * path+sha+summary+trusted/invalidationReason.</p>
 *
 * <p>When memory is empty or key fields are missing, only minimal fallback refs
 * are emitted. The old top-N evidence dump is never restored.</p>
 */
public final class WorkstreamMemoryProjection {
    private static final ObjectMapper MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private static final int MAX_READS = 12;
    private static final int MAX_OPEN_ISSUES = 12;
    private static final int MAX_CHANGED_FILES = 16;

    private WorkstreamMemoryProjection() {
    }

    /**
     * Claude implement handoff: decided scope, non-goals, reusable + invalidated
     * reads, last stage outcome, open issues, the reuse directive, and evidence
     * refs. Appends section body only (the caller writes the {@code ##} heading).
     */
    public static void appendAgentHandoff(dev.dual.ledger.file.WorkflowFileLedger ledger, StringBuilder builder, Path workstreamDir, Path workspaceRoot) {
        var memory = readMemory(workstreamDir);
        var qualification = qualificationStatus(ledger, memory, workstreamDir, workspaceRoot);
        var decidedScope = strings(memory.get("decidedScope"));
        var nonGoals = strings(memory.get("nonGoals"));
        var reads = list(memory.get("readFiles"));
        var openIssues = openIssues(list(memory.get("openIssues")));
        var lastOutcome = map(memory.get("lastStageOutcome"));
        var decisions = list(memory.get("decisions"));
        var hasAny = !decidedScope.isEmpty() || !nonGoals.isEmpty() || !reads.isEmpty()
                || !openIssues.isEmpty() || !decisions.isEmpty() || !lastOutcome.isEmpty();

        builder.append("Orchestrator-owned memory for this workstream. Reuse it instead of re-reading files or re-deriving scope.\n\n");
        builder.append("TaskContract projection: ").append(qualification).append("\n\n");

        appendBullets(builder, "Decided scope", decidedScope, MAX_OPEN_ISSUES);
        appendBullets(builder, "Non-goals", nonGoals, MAX_OPEN_ISSUES);
        appendReusableReads(builder, reads, "Reusable reads (summary trusted, do not re-read)");
        appendInvalidatedReads(builder, reads);
        appendLastOutcome(builder, lastOutcome, decisions);
        appendBullets(builder, "Open issues (resolve before claiming done)", issueTexts(openIssues), MAX_OPEN_ISSUES);

        builder.append("\nDo NOT re-explore from README/docs/source/test to re-derive this scope. ")
                .append("Re-read a listed file only when editing or verifying it, its sha changed, or the summary does not cover this stage — ")
                .append("and record the reason in your structured artifact.\n\n");

        if (!hasAny) {
            builder.append("(memory has no recorded scope, reads, or decisions yet for this workstream; ")
                    .append("proceed with the task contract and read-reuse contract below.)\n\n");
        }
        appendEvidenceRefs(builder, workstreamDir, workspaceRoot);
    }

    /**
     * Codex review brief: prior verdict + unresolved must-fix, open issues,
     * acceptance criteria, this round's changed files, a compact reusable-read /
     * decision summary, the incremental-audit directive, and evidence refs.
     * Appends section body only (the caller writes the {@code ##} heading).
     */
    public static void appendReviewEvidenceBrief(dev.dual.ledger.file.WorkflowFileLedger ledger, StringBuilder builder, Path workstreamDir, Path workspaceRoot) {
        var memory = readMemory(workstreamDir);
        var qualification = qualificationStatus(ledger, memory, workstreamDir, workspaceRoot);
        var verdicts = list(memory.get("priorVerdicts"));
        var openIssues = openIssues(list(memory.get("openIssues")));
        var acceptance = List.<String>of();
        var changedFiles = readChangedFiles(workstreamDir);
        var reusablePaths = reusableReadPaths(memory);

        var hasAny = !verdicts.isEmpty() || !openIssues.isEmpty() || !acceptance.isEmpty()
                || !changedFiles.isEmpty() || !reusablePaths.isEmpty();

        builder.append("TaskContract projection: ").append(qualification).append("\n\n");

        if (!hasAny) {
            builder.append("(no cumulative review verdict recorded; no open issues, changed files, or reusable memory recorded yet) Evidence: ")
                    .append(ref(workspaceRoot, workstreamDir.resolve("memory/workstream-memory.json")))
                    .append(".\n\n");
            return;
        }

        if (verdicts.isEmpty()) {
            builder.append("No cumulative review verdict recorded. Review the complete current subject against the contract baseline.\n\n");
        } else {
            builder.append("Incremental acceptance from orchestrator memory; verify it against the complete current subject.\n\n");
        }

        if (!verdicts.isEmpty()) {
            var verdict = verdicts.get(verdicts.size() - 1);
            var line = new StringBuilder();
            if (!text(verdict.get("stage")).isBlank()) {
                line.append(text(verdict.get("stage"))).append(" / ");
            }
            line.append(text(verdict.get("decision")));
            if (Boolean.TRUE.equals(verdict.get("blocking"))) {
                line.append(" (blocking)");
            }
            builder.append("**Prior verdict:** ").append(line).append("\n\n");
            appendBullets(builder, "Prior must-fix (verify resolved)", strings(verdict.get("mustFix")), MAX_OPEN_ISSUES);
        }
        appendBullets(builder, "Open issues to confirm", issueTexts(openIssues), MAX_OPEN_ISSUES);
        appendBullets(builder, "Acceptance criteria", acceptance, MAX_OPEN_ISSUES);
        appendBullets(builder, "Changed files this round", changedFiles, MAX_CHANGED_FILES);
        if (!reusablePaths.isEmpty()) {
            builder.append("- Relevant memory (reuse, do not re-read): ").append(String.join("; ", reusablePaths)).append("\n\n");
        }

        if (verdicts.isEmpty()) {
            builder.append("Derive the complete current blocker set from the review subject and acceptance criteria; ");
        } else {
            builder.append("Confirm prior must-fix and derive any additional current blockers from the complete review subject; ");
        }
        builder.append("re-read a file only with a reason (edit/verify/sha-changed/stage-gap).\n");
        builder.append("Evidence: memory ").append(ref(workspaceRoot, workstreamDir.resolve("memory/workstream-memory.json")))
                .append("; diff ").append(ref(workspaceRoot, workstreamDir.resolve("artifacts/git-evidence/diff.patch")))
                .append("; changed ").append(ref(workspaceRoot, workstreamDir.resolve("artifacts/git-evidence/changed-files.txt")))
                .append(".\n\n");
    }

    private static List<String> reusableReadPaths(Map<String, Object> memory) {
        var out = new ArrayList<String>();
        for (var read : list(memory.get("readFiles")).stream()
                .filter(r -> Boolean.TRUE.equals(r.get("trusted")) && text(r.get("invalidationReason")).isBlank())
                .limit(5).toList()) {
            var path = text(read.get("path"));
            if (!path.isBlank()) {
                out.add(path);
            }
        }
        return out;
    }

    private static void appendReusableReads(StringBuilder builder, List<Map<String, Object>> reads, String label) {
        var items = new ArrayList<String>();
        for (var read : reads.stream().limit(MAX_READS).toList()) {
            if (!Boolean.TRUE.equals(read.get("trusted")) || !text(read.get("invalidationReason")).isBlank()) {
                continue;
            }
            items.add(text(read.get("path")) + " — " + text(read.get("summary"))
                    + " [sha " + shortSha(text(read.get("sha"))) + ", read " + text(read.get("readRunId")) + "]"
                    + " reuse unless editing/verifying");
        }
        appendBullets(builder, label, items, MAX_READS);
    }

    private static void appendInvalidatedReads(StringBuilder builder, List<Map<String, Object>> reads) {
        var items = new ArrayList<String>();
        for (var read : reads.stream().limit(MAX_READS).toList()) {
            var reason = text(read.get("invalidationReason"));
            if (reason.isBlank()) {
                continue;
            }
            items.add(text(read.get("path")) + " — fresh read allowed (" + reason + ")");
        }
        appendBullets(builder, "Invalidated reads (fresh read allowed)", items, MAX_READS);
    }

    private static void appendLastOutcome(StringBuilder builder, Map<String, Object> outcome, List<Map<String, Object>> decisions) {
        Map<String, Object> latest = outcome.isEmpty() ? latestDecision(decisions) : outcome;
        if (latest.isEmpty()) {
            return;
        }
        var stage = text(latest.getOrDefault("stage", latest.get("stageId")));
        var decision = text(latest.get("decision"));
        var summary = text(latest.get("summary"));
        var verification = text(latest.get("verificationSummary"));
        var line = new StringBuilder();
        if (!stage.isBlank()) {
            line.append(stage).append(" / ");
        }
        if (!decision.isBlank()) {
            line.append(decision);
        }
        if (!summary.isBlank()) {
            line.append(line.isEmpty() ? "" : " — ").append(summary);
        }
        if (!verification.isBlank()) {
            line.append(" (verification: ").append(verification).append(")");
        }
        if (!line.isEmpty()) {
            builder.append("**Last stage outcome:**\n- ").append(line).append("\n\n");
        }
    }

    private static Map<String, Object> latestDecision(List<Map<String, Object>> decisions) {
        if (decisions.isEmpty()) {
            return Map.of();
        }
        return decisions.get(decisions.size() - 1);
    }

    private static List<Map<String, Object>> openIssues(List<Map<String, Object>> issues) {
        var open = new ArrayList<Map<String, Object>>();
        for (var issue : issues) {
            if (!"resolved".equalsIgnoreCase(text(issue.get("status")))) {
                open.add(issue);
            }
        }
        return open;
    }

    private static List<String> issueTexts(List<Map<String, Object>> issues) {
        var texts = new ArrayList<String>();
        for (var issue : issues) {
            var desc = text(issue.get("desc"));
            if (!desc.isBlank()) {
                texts.add(desc);
            }
        }
        return texts;
    }

    private static void appendBullets(StringBuilder builder, String label, List<String> items, int limit) {
        var bounded = items.stream().filter(s -> !s.isBlank()).distinct().limit(limit).toList();
        if (bounded.isEmpty()) {
            return;
        }
        builder.append("**").append(label).append(":**\n");
        for (var item : bounded) {
            builder.append("- ").append(item).append("\n");
        }
        builder.append("\n");
    }

    private static void appendEvidenceRefs(StringBuilder builder, Path workstreamDir, Path workspaceRoot) {
        var memory = readMemory(workstreamDir);
        var refs = map(memory.get("refs"));
        var qualification = map(memory.get("qualifiedTaskContract"));
        builder.append("Evidence refs:\n");
        builder.append("- Memory: ").append(ref(workspaceRoot, workstreamDir.resolve("memory/workstream-memory.json"))).append("\n");
        var contractRef = text(qualification.get("ref"));
        var contractSha = text(qualification.get("sha256"));
        if (!contractRef.isBlank() && !contractSha.isBlank()) {
            builder.append("- Qualified scope source: ").append(contractRef)
                    .append(" @ ").append(contractSha).append("\n");
        } else {
            builder.append("- Qualified scope source: unavailable\n");
        }
        var readReuseRef = text(refs.get("readReuseContract"));
        if (!readReuseRef.isBlank()) {
            builder.append("- Read-reuse contract: ").append(readReuseRef).append("\n");
        }
        builder.append("\n");
    }

    private static Map<String, Object> readMemory(Path workstreamDir) {
        return readJson(workstreamDir.resolve("memory/workstream-memory.json"));
    }

    private static Map<String, Object> readJson(Path path) {
        if (!Files.isRegularFile(path)) {
            return Map.of();
        }
        try {
            return MAPPER.readValue(path.toFile(), MAP_TYPE);
        } catch (IOException | RuntimeException ignored) {
            return Map.of();
        }
    }

    private static String qualificationStatus(
            dev.dual.ledger.file.WorkflowFileLedger ledger,
            Map<String, Object> memory,
            Path workstreamDir,
            Path workspaceRoot
    ) {
        var projected = map(memory.get("qualifiedTaskContract"));
        var projectedRef = text(projected.get("ref"));
        var projectedSha = text(projected.get("sha256"));
        if (projectedRef.isBlank() || projectedSha.isBlank()) {
            return "unavailable";
        }
        var workstreamId = workstreamDir.getFileName().toString();
        final dev.dual.core.contract.TaskContract.Phase phase;
        try { phase = dev.dual.core.contract.TaskContract.Phase.valueOf(text(projected.get("phase"))); }
        catch (IllegalArgumentException missing) { return "stale_projection"; }
        var current = TaskContractProjectionVerifier.resolve(ledger, workspaceRoot, workstreamId, phase);
        if (current.failure() != null || current.qualified().isEmpty()) {
            return "stale_projection";
        }
        var qualified = current.qualified().orElseThrow();
        return projectedRef.equals(qualified.contractRef()) && projectedSha.equals(qualified.sha256())
                ? "qualified_projection"
                : "stale_projection";
    }

    private static List<String> readChangedFiles(Path workstreamDir) {
        var path = workstreamDir.resolve("artifacts/git-evidence/changed-files.txt");
        var out = new ArrayList<String>();
        if (!Files.isRegularFile(path)) {
            return out;
        }
        try {
            for (var line : Files.readAllLines(path, StandardCharsets.UTF_8)) {
                var trimmed = line.trim();
                if (!trimmed.isBlank()) {
                    out.add(trimmed);
                }
            }
        } catch (IOException ignored) {
            return out;
        }
        return out;
    }

    private static String shortSha(String sha) {
        return sha.length() > 8 ? sha.substring(0, 8) : sha;
    }

    private static String ref(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize()).toString();
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> list(Object value) {
        if (!(value instanceof List<?> raw) || raw.isEmpty()) {
            return List.of();
        }
        var out = new ArrayList<Map<String, Object>>();
        for (var item : raw) {
            if (item instanceof Map<?, ?> map) {
                var copy = new java.util.LinkedHashMap<String, Object>();
                for (var e : map.entrySet()) {
                    if (e.getKey() instanceof String key) {
                        copy.put(key, e.getValue());
                    }
                }
                out.add(copy);
            }
        }
        return out;
    }

    private static Map<String, Object> map(Object value) {
        if (!(value instanceof Map<?, ?> raw)) {
            return Map.of();
        }
        var copy = new java.util.LinkedHashMap<String, Object>();
        for (var e : raw.entrySet()) {
            if (e.getKey() instanceof String key) {
                copy.put(key, e.getValue());
            }
        }
        return copy;
    }

    private static List<String> strings(Object value) {
        if (!(value instanceof List<?> raw)) {
            return List.of();
        }
        var out = new ArrayList<String>();
        for (var item : raw) {
            var t = text(item);
            if (!t.isBlank()) {
                out.add(t);
            }
        }
        return out;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.lifecycle;

import dev.dual.core.workflow.WorkflowDefinition;

import java.io.IOException;

public final class LifecycleWorkflowDefinitionFactory {
    private final WorkflowDefinitionLoader loader;

    public LifecycleWorkflowDefinitionFactory() {
        this(new WorkflowDefinitionLoader());
    }

    LifecycleWorkflowDefinitionFactory(WorkflowDefinitionLoader loader) {
        this.loader = loader;
    }

    public WorkflowDefinition forVariant(String variant) {
        return loadBundled(variant);
    }

    private WorkflowDefinition loadBundled(String variant) {
        try {
            return loader.loadBundledVariant(variant);
        } catch (IOException e) {
            throw new IllegalStateException("failed to load bundled workflow definition: " + variant, e);
        }
    }
}

package dev.dual.runtime.lifecycle;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import dev.dual.core.workflow.EdgeDefinition;
import dev.dual.core.workflow.HumanGateActionSemantics;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.ledger.file.EdgeConditionModule;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public final class WorkflowDefinitionLoader {
    private static final String FULL_WORKFLOW_RESOURCE = "/dev/dual/runtime/lifecycle/agent-lifecycle.full.json";
    private static final String CONTRACT_WORKFLOW_RESOURCE = "/dev/dual/runtime/lifecycle/agent-lifecycle.contract.json";
    private static final String TERMINAL_DELIVERY_WORKFLOW_RESOURCE =
            "/dev/dual/runtime/lifecycle/agent-lifecycle.terminal-delivery.json";

    private final ObjectMapper objectMapper = new ObjectMapper()
            .registerModule(new EdgeConditionModule())
            .enable(SerializationFeature.INDENT_OUTPUT);

    public WorkflowDefinition loadOrDefault(Path workflowPath) throws IOException {
        return loadOrDefault(workflowPath, null);
    }

    public WorkflowDefinition loadOrDefault(Path workflowPath, String variant) throws IOException {
        if (workflowPath != null && Files.exists(workflowPath)) {
            return load(workflowPath);
        }
        return loadBundledVariant(variant);
    }

    public WorkflowDefinition load(Path workflowPath) throws IOException {
        if (!Files.exists(workflowPath)) {
            throw new IOException("workflow file not found: " + workflowPath);
        }
        try {
            var source = objectMapper.readValue(workflowPath.toFile(), WorkflowDefinitionSource.class);
            return toWorkflowDefinition(source);
        } catch (RuntimeException e) {
            throw new IOException("invalid workflow definition: " + workflowPath + ": " + e.getMessage(), e);
        }
    }

    private static List<NodeDefinition> applyDefaults(List<NodeDefinition> nodes, Map<String, Object> defaults) {
        if (nodes == null || nodes.isEmpty() || defaults == null || defaults.isEmpty()) {
            return nodes == null ? List.of() : nodes;
        }
        return nodes.stream()
                .map(node -> applyNodeDefaults(node, defaults))
                .toList();
    }

    private static NodeDefinition applyNodeDefaults(NodeDefinition node, Map<String, Object> defaults) {
        var config = new LinkedHashMap<>(node.config());
        if ("acpx.agent_run".equals(node.handlerType())) {
            applySessionDefault(config, defaults);
            applyRetryDefaults(config, objectMap(defaults.get("retry")));
        }
        if ("review.decision".equals(node.handlerType()) || "human.review".equals(node.handlerType())) {
            applyObjectDefaults(config, objectMap(defaults.get("revision")));
        }
        return new NodeDefinition(node.id(), node.kind(), node.handlerType(), config);
    }

    private static void applyRetryDefaults(LinkedHashMap<String, Object> config, Map<String, Object> retryDefaults) {
        for (var entry : retryDefaults.entrySet()) {
            config.putIfAbsent("retry." + entry.getKey(), entry.getValue());
        }
    }

    private static void applySessionDefault(LinkedHashMap<String, Object> config, Map<String, Object> defaults) {
        if (config.containsKey("session")) {
            return;
        }
        var agent = text(config.get("agent"));
        if (agent.isBlank()) {
            return;
        }
        var sessions = objectMap(defaults.get("sessions"));
        var session = sessions.get(agent);
        if (session != null && !String.valueOf(session).isBlank()) {
            config.put("session", session);
        }
    }

    private static void applyObjectDefaults(LinkedHashMap<String, Object> config, Map<String, Object> defaults) {
        for (var entry : defaults.entrySet()) {
            config.putIfAbsent(entry.getKey(), entry.getValue());
        }
    }

    private static Map<String, Object> objectMap(Object value) {
        if (!(value instanceof Map<?, ?> raw)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (var entry : raw.entrySet()) {
            if (entry.getKey() != null) {
                copy.put(String.valueOf(entry.getKey()), entry.getValue());
            }
        }
        return copy;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    WorkflowDefinition loadBundledFullWorkflow() throws IOException {
        // 内置生命周期定义的权威来源是 classpath JSON，而不是 Java factory。
        return loadBundledWorkflow(FULL_WORKFLOW_RESOURCE);
    }

    WorkflowDefinition loadBundledContractWorkflow() throws IOException {
        // contract 也是正式内置流程，权威来源同样必须是 JSON resource。
        // 这里保留 Java 入口只是为了 variant selection，不再手写 DAG。
        return loadBundledWorkflow(CONTRACT_WORKFLOW_RESOURCE);
    }

    WorkflowDefinition loadBundledTerminalDeliveryWorkflow() throws IOException {
        return loadBundledWorkflow(TERMINAL_DELIVERY_WORKFLOW_RESOURCE);
    }

    WorkflowDefinition loadBundledVariant(String variant) throws IOException {
        String normalized = variant == null ? "" : variant.trim().toLowerCase(java.util.Locale.ROOT);
        return switch (normalized) {
            case "", "full" -> loadBundledFullWorkflow();
            case "contract" -> loadBundledContractWorkflow();
            case "terminal-delivery" -> loadBundledTerminalDeliveryWorkflow();
            default -> throw new IllegalArgumentException(
                    "unknown workflow variant: " + variant
                            + ". Supported: contract, full, terminal-delivery");
        };
    }

    private WorkflowDefinition loadBundledWorkflow(String resourcePath) throws IOException {
        try (InputStream input = WorkflowDefinitionLoader.class.getResourceAsStream(resourcePath)) {
            if (input == null) {
                throw new IOException("bundled workflow resource not found: " + resourcePath);
            }
            var source = objectMapper.readValue(input, WorkflowDefinitionSource.class);
            return toWorkflowDefinition(source);
        } catch (RuntimeException e) {
            throw new IOException("invalid bundled workflow definition: " + resourcePath + ": " + e.getMessage(), e);
        }
    }

    private static WorkflowDefinition toWorkflowDefinition(WorkflowDefinitionSource source) {
        var definition = new WorkflowDefinition(
                source.workflowId(),
                source.version(),
                source.entryNodeId(),
                applyDefaults(source.nodes(), source.defaults()),
                source.edges()
        );
        validateApprovedTaskContractRequirements(definition);
        dev.dual.runtime.handler.AuthoredExecutionContext.validateDefinition(definition);
        return definition;
    }

    private static void validateApprovedTaskContractRequirements(WorkflowDefinition definition) {
        var contractRepairEdges = validateContractRepairEdges(definition);
        var contractGates = definition.nodes().stream()
                .filter(node -> "contract".equals(text(node.config().get("gate_purpose"))))
                .toList();
        if (contractGates.isEmpty()) {
            if (!contractRepairEdges.isEmpty()) {
                throw new IllegalArgumentException("acceptance contract repair requires a contract-purpose gate");
            }
            return;
        }
        if (contractGates.size() != 1) {
            throw new IllegalArgumentException("workflow must declare exactly one contract-purpose gate");
        }
        var contractGate = contractGates.getFirst();
        var approvedEdges = definition.edgesFrom(contractGate.id()).stream()
                .filter(edge -> "approved".equals(edge.on()))
                .toList();
        if (approvedEdges.size() != 1) {
            throw new IllegalArgumentException("contract-purpose gate must declare exactly one approved successor");
        }
        var approvedEdge = approvedEdges.getFirst();
        var reuseEdges = definition.edges().stream().filter(edge -> "authorization_unchanged".equals(edge.on())).toList();
        if (reuseEdges.size() > 1) throw new IllegalArgumentException("at most one same-authorization continuation is supported");
        var reuse = reuseEdges.isEmpty() ? null : reuseEdges.getFirst();
        var reuseOwner = reuse == null ? null : definition.node(reuse.from());
        if (reuse != null && (!"contract.compile".equals(reuseOwner.handlerType())
                || !"EXECUTION".equals(reuseOwner.config().get("contract_phase"))
                || !approvedEdge.to().equals(reuse.to()) || !"unconditional".equals(reuse.condition().type())
                || !"normal".equals(reuse.metadata().transitionType()) || !reuse.metadata().required()))
            throw new IllegalArgumentException("same-authorization continuation must be produced by EXECUTION compilation and rejoin the approved successor");
        // The compiler proves an existing approval; graph reachability alone cannot grant that authority.
        var negotiation = reachable(definition, definition.entryNodeId(), reuse == null ? Set.of(approvedEdge) : Set.of(approvedEdge, reuse));
        if (negotiation.contains(approvedEdge.to())) {
            throw new IllegalArgumentException("contract approved successor overlaps the pre-approval negotiation region");
        }
        var postContract = new HashSet<String>();
        var queue = new ArrayDeque<String>();
        queue.add(approvedEdge.to());
        while (!queue.isEmpty()) {
            var nodeId = queue.removeFirst();
            if (negotiation.contains(nodeId)) {
                throw new IllegalArgumentException(
                        "post-contract region overlaps the pre-approval negotiation region: " + nodeId);
            }
            if (!postContract.add(nodeId)) {
                continue;
            }
            definition.edgesFrom(nodeId).stream()
                    .filter(edge -> !contractRepairEdges.contains(edge))
                    .forEach(edge -> queue.addLast(edge.to()));
        }
        for (var edge : contractRepairEdges) {
            if (!postContract.contains(edge.from()) || !negotiation.contains(edge.to())) {
                throw new IllegalArgumentException("acceptance contract repair must cross from post-contract to negotiation");
            }
        }
        var goalCompilers = definition.nodes().stream().filter(node -> "contract.compile".equals(node.handlerType())
                && "GOAL".equals(node.config().get("contract_phase"))).toList();
        var executionCompilers = definition.nodes().stream().filter(node -> "contract.compile".equals(node.handlerType())
                && "EXECUTION".equals(node.config().get("contract_phase"))).toList();
        if (goalCompilers.size() != 1 || executionCompilers.size() != 1)
            throw new IllegalArgumentException("workflow requires one compiler for each contract phase");
        var goalEdges = definition.edgesFrom(goalCompilers.getFirst().id());
        if (goalEdges.size() != 1 || !"completed".equals(goalEdges.getFirst().on()))
            throw new IllegalArgumentException("GOAL compiler requires one completed successor");
        var beforeGoal = reachable(definition, definition.entryNodeId(), goalEdges.getFirst());
        if (beforeGoal.contains(goalEdges.getFirst().to()))
            throw new IllegalArgumentException("GOAL successor bypasses approved GOAL compilation");
        var executionEdges = definition.edgesFrom(executionCompilers.getFirst().id());
        if (executionEdges.size() != (reuse == null ? 1 : 2) || (reuse != null && !executionEdges.contains(reuse))
                || executionEdges.stream().filter(edge -> "completed".equals(edge.on())
                        && contractGate.id().equals(edge.to())).count() != 1)
            throw new IllegalArgumentException("EXECUTION compiler must feed the exact-scope approval gate");
        for (var node : definition.nodes()) {
            if (node.config().containsKey("requires_approved_task_contract"))
                throw new IllegalArgumentException("legacy contract requirement is unsupported: " + node.id());
            var expected = postContract.contains(node.id()) ? "EXECUTION" : beforeGoal.contains(node.id()) ? null : "GOAL";
            if (!java.util.Objects.equals(expected, node.config().get("required_contract_phase")))
                throw new IllegalArgumentException("contract phase requirement mismatch: " + node.id() + ", expected " + expected);
        }
        if (definition.edges().stream().anyMatch(edge -> "fork".equals(edge.metadata().transitionType())))
            throw new IllegalArgumentException("fork is not supported by this lifecycle commit protocol");
    }

    private static Set<EdgeDefinition> validateContractRepairEdges(WorkflowDefinition definition) {
        var repairs = new HashSet<EdgeDefinition>();
        for (var edge : definition.edges()) {
            if (!Set.of("REJECT_CONTRACT_GAP", "REJECT_CONTRACT_AMBIGUITY", "request_scope_revision").contains(edge.on())) {
                continue;
            }
            var source = definition.node(edge.from());
            var context = definition.node(edge.to());
            var sourceValid = edge.on().equals("request_scope_revision")
                    ? source.id().equals("gate.human_implementation_repair") && source.kind() == NodeKind.GATE
                        && source.handlerType().equals("human.review")
                        && "implementation_repair".equals(source.config().get("gate_purpose"))
                        && HumanGateActionSemantics.allowedActions(source).contains("request_scope_revision")
                    : source.id().equals("acceptance.classify_failure") && source.kind() == NodeKind.TASK
                        && source.handlerType().equals("acceptance.failure_classify");
            if (!sourceValid
                    || !"EXECUTION".equals(source.config().get("required_contract_phase"))
                    || !"context.intake_claude_brainstorm".equals(context.id())
                    || context.kind() != NodeKind.TASK
                    || !"context.build_package".equals(context.handlerType())
                    || !"intake.claude_brainstorm".equals(context.config().get("target_node"))
                    || !"loop".equals(edge.metadata().transitionType())
                    || !edge.metadata().branchGroupId().isBlank()
                    || !edge.metadata().required()
                    || !"unconditional".equals(edge.condition().type())) {
                throw new IllegalArgumentException("invalid acceptance contract repair edge: " + edge.from()
                        + " / " + edge.on() + " / " + edge.to());
            }
            var successors = definition.edgesFrom(context.id());
            if (successors.size() != 1
                    || !"completed".equals(successors.getFirst().on())
                    || !"intake.claude_brainstorm".equals(successors.getFirst().to())
                    || !"normal".equals(successors.getFirst().metadata().transitionType())
                    || !"unconditional".equals(successors.getFirst().condition().type())) {
                throw new IllegalArgumentException("acceptance contract repair context must lead only to proposal producer");
            }
            var producer = definition.node(successors.getFirst().to());
            if (producer.kind() != NodeKind.TASK
                    || !"acpx.agent_run".equals(producer.handlerType())
                    || !"task_contract_proposal".equals(producer.config().get("expected_artifact"))
                    || !"task_contract_proposal_compiler".equals(producer.config().get("artifact_compiler"))) {
                throw new IllegalArgumentException("acceptance contract repair requires the typed proposal producer");
            }
            if (definition.edgesFrom(source.id()).stream().filter(other -> edge.on().equals(other.on())).count() != 1) {
                throw new IllegalArgumentException("acceptance contract repair must have exactly one successor per outcome");
            }
            repairs.add(edge);
        }
        return Set.copyOf(repairs);
    }

    private static Set<String> reachable(
            WorkflowDefinition definition,
            String start,
            EdgeDefinition excludedEdge
    ) {
        return reachable(definition, start, Set.of(excludedEdge));
    }

    private static Set<String> reachable(WorkflowDefinition definition, String start, Set<EdgeDefinition> excludedEdges) {
        var reached = new HashSet<String>();
        var queue = new ArrayDeque<String>();
        queue.add(start);
        while (!queue.isEmpty()) {
            var nodeId = queue.removeFirst();
            if (!reached.add(nodeId)) {
                continue;
            }
            definition.edgesFrom(nodeId).stream()
                    .filter(edge -> !excludedEdges.contains(edge))
                    .forEach(edge -> queue.addLast(edge.to()));
        }
        return Set.copyOf(reached);
    }

    private record WorkflowDefinitionSource(
            String workflowId,
            int version,
            String entryNodeId,
            Map<String, Object> defaults,
            List<NodeDefinition> nodes,
            List<EdgeDefinition> edges
    ) {
    }
}

