    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private AgentOutputLineageFixture() {
    }

    public static void completeAndPublish(Path workspaceRoot, String workstreamId, Path sidecarPath) throws Exception {
        completeAndPublish(workspaceRoot, workstreamId, sidecarPath, "iteration-fixture", List.of());
    }

    public static void completeAndPublish(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            String iterationId,
            List<String> inputRefs
    ) throws Exception {
        var tree = MAPPER.readTree(sidecarPath.toFile());
        if (!(tree instanceof ObjectNode sidecar)) {
            throw new IllegalArgumentException("agent output sidecar must be a JSON object");
        }
        var runId = runId(sidecarPath);
        var source = sourcePath(sidecarPath);
        sidecar.put("workstream_id", workstreamId);
        sidecar.put("run_id", runId);
        sidecar.put("node_instance_id", "node-fixture-" + runId + "-"
                + sidecarPath.getFileName().toString().replaceAll("[^A-Za-z0-9._-]", "-"));
        sidecar.put("source_output_ref", relative(workspaceRoot, source));
        MAPPER.writerWithDefaultPrettyPrinter().writeValue(sidecarPath.toFile(), sidecar);
        publish(workspaceRoot, workstreamId, sidecarPath, iterationId, inputRefs);
    }

    public static void publish(Path workspaceRoot, String workstreamId, Path sidecarPath) throws Exception {
        publish(workspaceRoot, workstreamId, sidecarPath, "iteration-fixture");
    }

    public static void publish(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            String iterationId
    ) throws Exception {
        publish(workspaceRoot, workstreamId, sidecarPath, iterationId, List.of());
    }

    public static void publish(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            String iterationId,
            List<String> inputRefs
    ) throws Exception {
        var paths = new dev.dual.ledger.file.WorkstreamPaths(workspaceRoot, new dev.dual.core.id.DualId(workstreamId));
        if (!Files.exists(paths.workstreamJson())) {
            var definition = new dev.dual.core.workflow.WorkflowDefinition("evidence-fixture", 1, "fixture",
                    List.of(new dev.dual.core.workflow.NodeDefinition("fixture", NodeKind.TASK, "noop.task", Map.of())), List.of());
            dev.dual.runtime.RuntimeTestLedger.initialize(dev.dual.runtime.RuntimeTestLedger.ledger(), paths, "evidence-fixture", definition);
        }
        var sidecar = MAPPER.readValue(sidecarPath.toFile(), MAP_TYPE);
        var runId = text(sidecar.get("run_id"));
        var nodeId = text(sidecar.get("node_id"));
        var nodeInstanceId = text(sidecar.get("node_instance_id"));
        var sourceRef = text(sidecar.get("source_output_ref"));
        if (runId.isBlank() || nodeId.isBlank() || nodeInstanceId.isBlank() || sourceRef.isBlank()) {
            return;
        }
        var source = workspaceRoot.resolve(sourceRef).normalize();
        Files.createDirectories(source.getParent());
        if (!Files.exists(source)) {
            Files.writeString(source, "{}");
        }
        var sidecarRef = relative(workspaceRoot, sidecarPath);
        var decision = text(sidecar.get("decision"));
        var outputs = List.of(sourceRef, sidecarRef);
        var result = Map.<String, Object>of(
                "run_id", runId,
                "decision", decision,
                "contract_sidecar_sha256", AgentOutputContractSidecar.sha256(sidecarPath));
        var executionId = "nxe-" + nodeInstanceId.replaceAll("[^A-Za-z0-9._-]", "-");
        var workstreamDir = workspaceRoot.resolve(".agent/workstreams").resolve(workstreamId);
        var nodesDir = workstreamDir.resolve("nodes");
        var executionsDir = workstreamDir.resolve("executions/nodes");
        Files.createDirectories(nodesDir);
        Files.createDirectories(executionsDir);
        var now = Instant.parse("2026-07-21T00:00:00Z");
        MAPPER.writeValue(nodesDir.resolve(nodeInstanceId + ".json").toFile(), new NodeInstanceDocument(
                1, nodeInstanceId, nodeId, NodeKind.TASK, "acpx.agent_run", NodeStatus.COMPLETED,
                "stage-fixture", iterationId, inputRefs, Map.of(), outputs,
                result, runId, executionId, now, now));
        MAPPER.writeValue(executionsDir.resolve(executionId + ".json").toFile(), new NodeExecutionDocument(
                1, executionId, "agent-task-fixture", "workflow-execution-fixture",
                nodeInstanceId, nodeId, "acpx.agent_run", NodeExecutionStatus.SUCCEEDED,
                1L, "completed", NodeStatus.COMPLETED, outputs,
                result, "",
                runId, "", "fixture-agent", "fixture-session", 0, now, now, 1L));
    }

    private static String relative(Path root, Path path) {
        return root.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static String runId(Path sidecarPath) {
        for (var index = 0; index + 1 < sidecarPath.getNameCount(); index++) {
            if ("runs".equals(sidecarPath.getName(index).toString())) {
                return sidecarPath.getName(index + 1).toString();
            }
        }
        throw new IllegalArgumentException("sidecar is not under a run: " + sidecarPath);
    }

    private static Path sourcePath(Path sidecarPath) {
        var name = sidecarPath.getFileName().toString();
        if (!name.endsWith(".contract.json")) {
            throw new IllegalArgumentException("not an agent output sidecar: " + sidecarPath);
        }
        var stem = name.substring(0, name.length() - ".contract.json".length());
        var json = sidecarPath.resolveSibling(stem + ".json");
        var markdown = sidecarPath.resolveSibling(stem + ".md");
        if (Files.exists(json)) {
            return json;
        }
        return Files.exists(markdown) ? markdown : json;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.handler;

import org.junit.jupiter.api.Test;

import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AgentResultEnvelopeParserTest {
    private final AgentResultEnvelopeParser parser = new AgentResultEnvelopeParser();
    private final AgentResultEnvelopeValidator validator = new AgentResultEnvelopeValidator();
    private final NodeOutputContract contract = new NodeOutputContract(
            "design.claude_design",
            Set.of("decision", "summary"),
            Set.of("READY_FOR_ARCH_REVIEW"),
            Set.of(),
            Set.of("agent_output_contract")
    );

    @Test
    void parsesAndValidatesStrictTypedEnvelope() {
        var parsed = parser.parse(validEnvelope());

        assertTrue(parsed.valid());
        assertTrue(parsed.envelope().result() instanceof AgentResultEnvelope.AgentOutputResult);
        assertTrue(validator.validate(parsed.envelope(), "ws-1", "run-1", contract).valid());
    }

    @Test
    void rejectsDuplicateKeys() {
        var parsed = parser.parse(validEnvelope().replace(
                "\"schema_version\": 1,",
                "\"schema_version\": 1,\"schema_version\": 1,"));

        assertFalse(parsed.valid());
        assertEquals("AGENT_RESULT_PARSE_FAILED", parsed.errorCode());
        assertNotEquals(
                AgentResultEnvelopeParser.ParseFailureKind.UNEXPECTED_END_OF_INPUT,
                parsed.diagnostic().kind()
        );
    }

    @Test
    void classifiesUnclosedRootAsUnexpectedEndOfInputWithoutRelaxingParser() {
        var complete = validEnvelope().stripTrailing();
        var missingRootClose = complete.substring(0, complete.length() - 1);

        var parsed = parser.parse(missingRootClose);

        assertFalse(parsed.valid());
        assertEquals("AGENT_RESULT_PARSE_FAILED", parsed.errorCode());
        assertEquals(
                AgentResultEnvelopeParser.ParseFailureKind.UNEXPECTED_END_OF_INPUT,
                parsed.diagnostic().kind()
        );
        assertTrue(parsed.diagnostic().line() > 0);
        assertTrue(parsed.diagnostic().column() > 0);
        assertTrue(parser.parse(missingRootClose + "}").valid(), "strict parser must accept the complete original object");
    }

    @Test
    void rejectsTrailingProseAndMarkdownFence() {
        var trailing = parser.parse(validEnvelope() + "\nDone.");
        var fenced = parser.parse("```json\n" + validEnvelope() + "\n```");

        assertFalse(trailing.valid());
        assertFalse(fenced.valid());
        assertNotEquals(
                AgentResultEnvelopeParser.ParseFailureKind.UNEXPECTED_END_OF_INPUT,
                trailing.diagnostic().kind()
        );
        assertNotEquals(
                AgentResultEnvelopeParser.ParseFailureKind.UNEXPECTED_END_OF_INPUT,
                fenced.diagnostic().kind()
        );
    }

    @Test
    void rejectsUnknownFields() {
        var parsed = parser.parse(validEnvelope().replace(
                "\"summary\": \"ready\",",
                "\"summary\": \"ready\",\"unexpected\": true,"));

        assertFalse(parsed.valid());
        assertNotEquals(
                AgentResultEnvelopeParser.ParseFailureKind.UNEXPECTED_END_OF_INPUT,
                parsed.diagnostic().kind()
        );
    }

    @Test
    void rejectsStaleLineageAndInvalidDecision() {
        var parsed = parser.parse(validEnvelope()
                .replace("\"run_id\": \"run-1\"", "\"run_id\": \"old-run\"")
                .replace("READY_FOR_ARCH_REVIEW", "BLOCKED"));

        var result = validator.validate(parsed.envelope(), "ws-1", "run-1", contract);
        assertFalse(result.valid());
        assertTrue(result.errors().stream().anyMatch(value -> value.contains("run_id")));
        assertTrue(result.errors().stream().anyMatch(value -> value.contains("decision")));
    }

    @Test
    void rejectsBlankLineageEvenWhenCurrentExecutionIdentityIsAlsoBlank() {
        var parsed = parser.parse(validEnvelope()
                .replace("\"workstream_id\": \"ws-1\"", "\"workstream_id\": \"\"")
                .replace("\"run_id\": \"run-1\"", "\"run_id\": \"\""));

        var result = validator.validate(parsed.envelope(), "", "", contract);

        assertFalse(result.valid());
        assertTrue(result.errors().contains("workstream_id is required"));
        assertTrue(result.errors().contains("run_id is required"));
    }

    @Test
    void rejectsMissingTypedPayloadFieldWithoutRelaxingJsonParser() {
        var parsed = parser.parse(validEnvelope().replace("\"checks\": [],", ""));

        assertTrue(parsed.valid(), "syntax parser should return the typed candidate");
        var result = validator.validate(parsed.envelope(), "ws-1", "run-1", contract);
        assertFalse(result.valid());
        assertTrue(result.errors().contains("result.checks is required"));
        assertTrue(result.schemaCorrectionAllowed());
    }

    @Test
    void distinguishesMissingSchemaVersionFromExplicitUnsupportedVersion() {
        var missing = parser.parse(validEnvelope().replace("\"schema_version\": 1,", ""));
        var unsupported = parser.parse(validEnvelope().replace("\"schema_version\": 1", "\"schema_version\": 2"));

        var missingResult = validator.validate(missing.envelope(), "ws-1", "run-1", contract);
        var unsupportedResult = validator.validate(unsupported.envelope(), "ws-1", "run-1", contract);

        assertTrue(missing.valid());
        assertTrue(missingResult.schemaCorrectionAllowed());
        assertTrue(unsupported.valid());
        assertEquals(
                AgentResultEnvelopeValidator.CorrectionDisposition.NOT_REPAIRABLE,
                unsupportedResult.correctionDisposition()
        );
    }

    @Test
    void rejectsBlankSummaryAtTheTypedContractBoundary() {
        var parsed = parser.parse(validEnvelope().replace("\"summary\": \"ready\"", "\"summary\": \"  \""));

        assertTrue(parsed.valid());
        var result = validator.validate(parsed.envelope(), "ws-1", "run-1", contract);
        assertFalse(result.valid());
        assertTrue(result.errors().contains("result.summary is required"));
        assertEquals(
                AgentResultEnvelopeValidator.CorrectionDisposition.NOT_REPAIRABLE,
                result.correctionDisposition()
        );
    }

    @Test
    void mixedSchemaAndIdentityFailureIsNotRepairable() {
        var parsed = parser.parse(validEnvelope()
                .replace("\"checks\": [],", "")
                .replace("\"run_id\": \"run-1\"", "\"run_id\": \"stale-run\""));

        var result = validator.validate(parsed.envelope(), "ws-1", "run-1", contract);

        assertFalse(result.valid());
        assertTrue(result.errors().contains("result.checks is required"));
        assertTrue(result.errors().contains("run_id does not match current execution"));
        assertEquals(
                AgentResultEnvelopeValidator.CorrectionDisposition.NOT_REPAIRABLE,
                result.correctionDisposition()
        );
    }

    @Test
    void rejectsWrongPrimitiveType() {
        var parsed = parser.parse(validEnvelope().replace("\"blocking\": false", "\"blocking\": \"false\""));

        assertFalse(parsed.valid());
    }

    @Test
    void rejectWithMissingTestsRequiresTypedVerificationRemediation() {
        var acceptanceContract = new NodeOutputContract(
                "acceptance.codex_verifier_review",
                Set.of("decision", "summary"),
                Set.of("ACCEPT", "ACCEPT_WITH_NOTES", "REJECT"),
                Set.of(),
                Set.of("acceptance_review")
        );
        var missingRemediation = parser.parse(acceptanceRejectEnvelope("NONE"));
        var codeChange = parser.parse(acceptanceRejectEnvelope("TEST_CODE_CHANGE"));
        var unsupportedCodeChange = parser.parse(acceptanceRejectEnvelope("TEST_CODE_CHANGE")
                .replace("\"missing_tests\": [\"equal-date cycle-number tie-breaker\"]", "\"missing_tests\": []"));

        var rejected = validator.validate(
                missingRemediation.envelope(), "ws-1", "run-1", acceptanceContract);
        var accepted = validator.validate(
                codeChange.envelope(), "ws-1", "run-1", acceptanceContract);
        var unsupported = validator.validate(
                unsupportedCodeChange.envelope(), "ws-1", "run-1", acceptanceContract);

        assertFalse(rejected.valid());
        assertTrue(rejected.errors().contains(
                "result.failure.verification_remediation is required when REJECT lists missing_tests"));
        assertTrue(accepted.valid());
        assertFalse(unsupported.valid());
        assertTrue(unsupported.errors().contains(
                "result.failure.verification_remediation is only allowed when REJECT lists missing_tests"));
    }

    private static String acceptanceRejectEnvelope(String remediation) {
        return """
                {
                  "schema_version": 1,
                  "workstream_id": "ws-1",
                  "run_id": "run-1",
                  "node_id": "acceptance.codex_verifier_review",
                  "result": {
                    "artifact_type": "acceptance_review",
                    "decision": "REJECT",
                    "summary": "A regression test is missing.",
                    "lifecycle_status": "REJECTED",
                    "blocking": true,
                    "checks": ["reviewed implementation"],
                    "evidence": ["implementation behavior is correct"],
                    "missing_evidence": [],
                    "must_fix": ["add the regression test"],
                    "acceptance_notes": [],
                    "open_risks": [],
                    "changed_files": ["backend/tests/test_chemo.py"],
                    "verification_summary": "A test source change is required.",
                    "verification_checks": [],
                    "failure": {
                      "category_hint": "IMPLEMENTATION_BUG",
                      "verification_remediation": "%s",
                      "contract_gaps": [],
                      "out_of_scope_files": [],
                      "missing_tests": ["equal-date cycle-number tie-breaker"],
                      "context_gaps": [],
                      "reason": "Missing regression test"
                    }
                  }
                }
                """.formatted(remediation);
    }

    private static String validEnvelope() {
        return """
                {
                  "schema_version": 1,
                  "workstream_id": "ws-1",
                  "run_id": "run-1",
                  "node_id": "design.claude_design",
                  "result": {
                    "artifact_type": "agent_output_contract",
                    "decision": "READY_FOR_ARCH_REVIEW",
                    "summary": "ready",
                    "lifecycle_status": "READY",
                    "blocking": false,
                    "checks": [],
                    "evidence": [],
                    "missing_evidence": [],
                    "must_fix": [],
                    "acceptance_notes": [],
                    "open_risks": [],
                    "changed_files": [],
                    "verification_summary": "not run",
                    "failure": {
                      "category_hint": "",
                      "contract_gaps": [],
                      "out_of_scope_files": [],
                      "missing_tests": [],
                      "context_gaps": [],
                      "reason": ""
                    },
                    "reread_reasons": []
                  }
                }
                """;
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AgentResultEnvelopeValidatorTest {
    private static final ObjectMapper JSON = new ObjectMapper()
            .setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE);
    private final AgentResultEnvelopeParser parser = new AgentResultEnvelopeParser();
    private final AgentResultEnvelopeValidator validator = new AgentResultEnvelopeValidator();

    @Test
    void capturedV14ShapeParsesStrictlyButRejectsDuplicateTargetWithoutCorrection() throws Exception {
        var patch = new AgentResultEnvelope.TaskContractRevisionPatchResult(
                "task_contract_revision_patch", "READY_FOR_PRODUCT_REVIEW", "revision",
                "node-prev:0123456789abcdef", "a".repeat(64),
                List.of(
                        obligation("CO-1", "AC-1", "src/main/resources/application.yml"),
                        obligation("CO-3", "C-12", "src/main/resources/application.yml")));
        var captured = new AgentResultEnvelope(
                1, "ws-1", "run-1", "intake.claude_brainstorm", patch);
        var parsed = parser.parse(JSON.writeValueAsString(captured));

        assertTrue(parsed.valid(), parsed.message());

        var result = validator.validate(
                parsed.envelope(), "ws-1", "run-1", ContractRegistry.forNode("intake.claude_brainstorm"));

        assertFalse(result.valid());
        assertEquals(List.of(
                "DUPLICATE_EVIDENCE_PATCH_TARGET: src/main/resources/application.yml"), result.errors());
        assertEquals(AgentResultEnvelopeValidator.CorrectionDisposition.NOT_REPAIRABLE,
                result.correctionDisposition());
        assertFalse(result.schemaCorrectionAllowed());

        var correctedPatch = new AgentResultEnvelope.TaskContractRevisionPatchResult(
                patch.artifactType(), patch.decision(), patch.summary(),
                patch.baseProposalId(), patch.baseProposalSha256(),
                List.of(
                        patch.obligationPatches().get(0),
                        obligation("CO-3", "C-12", null)));
        var corrected = validator.validate(
                new AgentResultEnvelope(1, "ws-1", "run-1", "intake.claude_brainstorm", correctedPatch),
                "ws-1", "run-1", ContractRegistry.forNode("intake.claude_brainstorm"));
        assertTrue(corrected.valid(), corrected.errors().toString());
    }

    private static AgentResultEnvelope.ObligationPatch obligation(
            String obligationId,
            String clauseId,
            String evidenceRef
    ) {
        return new AgentResultEnvelope.ObligationPatch(
                obligationId,
                List.of(clauseId),
                List.of(new AgentResultEnvelope.ClauseChange(
                        AgentResultEnvelope.ClauseChangeOperation.ADD,
                        AgentResultEnvelope.ClauseSection.CONSTRAINTS,
                        clauseId,
                        "text")),
                List.of(),
                evidenceRef == null ? List.of() : List.of(evidenceRef));
    }
}

package dev.dual.runtime.handler;

import org.junit.jupiter.api.Test;

import java.util.Map;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AgentResultPromptContractTest {
    private final AgentResultEnvelopeParser parser = new AgentResultEnvelopeParser();
    private final AgentResultEnvelopeValidator validator = new AgentResultEnvelopeValidator();

    @Test
    void selfTestRequiresExplicitProductIssuesWithoutAcceptanceFailureSchema() throws Exception {
        var prompt = AgentResultPromptContract.render("ws-1", "run-1",
                "implement.claude_self_test_report", "SELF_TEST_COMPLETE", Set.of("SELF_TEST_COMPLETE"));
        var mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        var envelope = (com.fasterxml.jackson.databind.node.ObjectNode) mapper.readTree(
                prompt.substring(prompt.indexOf('{')));
        var result = (com.fasterxml.jackson.databind.node.ObjectNode) envelope.path("result");
        assertTrue(result.has("must_fix"));
        assertFalse(result.has("failure"));
        result.putArray("missing_evidence").add("External verification missing");
        var parsed = parser.parse(mapper.writeValueAsString(envelope));
        assertTrue(parsed.valid(), parsed.message());
        assertFalse(validator.validate(parsed.envelope(), "ws-1", "run-1",
                ContractRegistry.forNode("implement.claude_self_test_report")).valid());
    }

    @Test
    void designDeclaresPlannedFilesInsteadOfGenericOutput() {
        var prompt = AgentResultPromptContract.render(
                "ws-1", "run-1", "design.claude_design",
                "READY_FOR_ARCH_REVIEW", Set.of("READY_FOR_ARCH_REVIEW"));
        var parsed = parser.parse(prompt.substring(prompt.indexOf('{')));
        assertTrue(parsed.valid(), parsed.message());
        assertTrue("design_result".equals(parsed.envelope().result().artifactType()));
        assertTrue(prompt.contains("planned_files"));
        assertTrue(prompt.contains("\"revision_responses\" : [ ]"));
        assertTrue(prompt.contains("NOT_ADDRESSED"));
    }

    @Test
    void everyAgentNodePromptExampleIsStrictAndMatchesItsNodeContract() {
        var decisions = Map.ofEntries(
                Map.entry("intake.claude_brainstorm", "READY_FOR_PRODUCT_REVIEW"),
                Map.entry("intake.codex_product_review", "READY_FOR_PRODUCT_REVIEW"),
                Map.entry("design.claude_design", "READY_FOR_ARCH_REVIEW"),
                Map.entry("design.codex_arch_review", "READY_FOR_ARCH_REVIEW"),
                Map.entry("plan.claude_plan", "READY_FOR_PLAN_REVIEW"),
                Map.entry("plan.codex_plan_review", "READY_TO_IMPLEMENT"),
                Map.entry("implement.claude_implement", "IMPLEMENTED"),
                Map.entry("implement.claude_self_test_report", "SELF_TEST_COMPLETE"),
                Map.entry("acceptance.codex_verifier_review", "ACCEPT"),
                Map.entry("stage.claude_handoff", "HANDOFF_READY")
        );

        decisions.forEach((nodeId, decision) -> {
            var contractText = AgentResultPromptContract.render(
                    "ws-1", "run-1", nodeId, decision, Set.of(decision));
            assertFalse(contractText.contains("dual-control"));
            assertFalse(contractText.contains("dual-artifact"));
            var parsed = parser.parse(contractText.substring(contractText.indexOf('{')));
            assertTrue(parsed.valid(), () -> nodeId + ": " + parsed.message());
            var validation = validator.validate(parsed.envelope(), "ws-1", "run-1", ContractRegistry.forNode(nodeId));
            assertTrue(validation.valid(), () -> nodeId + ": " + validation.errors());
        });
    }

    @Test
    void promptMakesNodeSpecificRereadReasonShapeUnambiguous() {
        var productReview = AgentResultPromptContract.render(
                "ws-1", "run-1", "intake.codex_product_review",
                "READY_FOR_PRODUCT_REVIEW", Set.of("READY_FOR_PRODUCT_REVIEW"));
        var implementation = AgentResultPromptContract.render(
                "ws-1", "run-1", "implement.claude_implement", "IMPLEMENTED", Set.of("IMPLEMENTED"));

        assertTrue(productReview.contains("reread_reasons` must remain exactly `[]`"));
        assertTrue(implementation.contains(
                "result.reread_reasons` item is a closed object with exactly these fields: "
                        + "[path, reason, stage, evidence]"));
        ReadReuseContractReasons.ALLOWED_REPEATED_READ_REASONS.forEach(
                reason -> assertTrue(implementation.contains(reason)));
    }

    @Test
    void promptProjectsClosedStructuredItemFieldsWithoutAddingAnotherJsonObject() {
        var intake = AgentResultPromptContract.render(
                "ws-1", "run-1", "intake.claude_brainstorm",
                "READY_FOR_PRODUCT_REVIEW", Set.of("READY_FOR_PRODUCT_REVIEW"));
        var productReview = AgentResultPromptContract.render(
                "ws-1", "run-1", "intake.codex_product_review",
                "NEEDS_REVISION", Set.of("READY_FOR_PRODUCT_REVIEW", "NEEDS_REVISION"));

        assertTrue(intake.contains(
                "result.revision_responses` item is a closed object with exactly these fields: "
                        + "[review_obligation_id, resolved_by_clause_ids]"));
        assertTrue(intake.contains(
                "copying its `id` and `text` character-for-character from the verified previous proposal"));
        assertTrue(intake.contains("including whitespace, punctuation, capitalization, and Markdown backticks"));
        assertTrue(intake.contains(
                "Formatting normalization is a modification and is prohibited unless that clause ID is declared"));
        assertTrue(intake.contains("do not delete existing clause IDs"));
        assertTrue(intake.contains(
                "`result.scope.included` is the exhaustive authorization set for permitted repository changes"));
        assertTrue(intake.contains("Each scope path must name one exact file, not a directory"));
        assertTrue(intake.contains("must not end with `/`"));
        assertTrue(intake.contains("no `./`, `..`, repeated separators"));
        assertTrue(intake.contains(
                "Acceptance criteria, constraints, risks, and other prose cannot authorize an undeclared path"));
        assertTrue(intake.contains("Never describe the typed scope as illustrative or non-exhaustive"));
        assertTrue(intake.contains(
                "When a revision obligation identifies a scope gap, update the typed path entries directly"));
        assertTrue(productReview.contains(
                "result.contract_obligations` item is a closed object with exactly these fields: [id, text]"));
        assertTrue(intake.contains(
                "Every JSON object is closed. Do not add keys that are not declared for that object."));
        assertTrue(intake.contains("\"revision_responses\" : [ ]"));

        var parsed = parser.parse(intake.substring(intake.indexOf('{')));
        assertTrue(parsed.valid(), "the contract prompt must contain only its final envelope JSON object");
    }

    @Test
    void nonIntakeAgentOutputPromptsKeepReviewObligationsEmpty() {
