        var paths = new WorkstreamPaths(tempDir, new DualId("ws"));
        var occurrence = "node-delivery-prepare-pr";
        var writer = new DeliveryCandidateWriter();
        var existing = writer.existing(paths, occurrence);
        if (existing == null) {
            var dir = paths.deliveryCandidateDir(occurrence);
            var patchRef = workspaceRef(dir.resolve("merge.patch"));
            var commitRef = workspaceRef(dir.resolve("commit-message.txt"));
            var prRef = workspaceRef(dir.resolve("pr-body.md"));
            var patch = "diff --git a/README.md b/README.md\n".getBytes(StandardCharsets.UTF_8);
            var commit = "test commit\n".getBytes(StandardCharsets.UTF_8);
            var pr = "# test PR\n".getBytes(StandardCharsets.UTF_8);
            var candidate = new DeliveryCandidateDocument(
                    1, "ws", occurrence, "iter-001", "wsp-test", tempDir.toString(),
                    "1111111111111111111111111111111111111111",
                    "2222222222222222222222222222222222222222",
                    List.of("README.md"), List.of(),
                    new DeliveryCandidateDocument.ArtifactReference(patchRef, DeliveryCandidateWriter.sha256(patch)),
                    "3333333333333333333333333333333333333333",
                    new DeliveryCandidateDocument.ArtifactReference(commitRef, DeliveryCandidateWriter.sha256(commit)),
                    new DeliveryCandidateDocument.ArtifactReference(prRef, DeliveryCandidateWriter.sha256(pr)),
                    Instant.parse("2026-08-28T00:00:00Z")
            );
            existing = writer.publish(paths, candidate, Map.of(
                    "merge.patch", patch,
                    "commit-message.txt", commit,
                    "pr-body.md", pr
            ));
        }
        var refs = new java.util.ArrayList<>(List.of(inputRefs));
        refs.add(existing.ref());
        return List.copyOf(refs);
    }

    private NodeInstance contextDisplayNode(NodeInstance actual, List<String> refs) {
        return new NodeInstance(actual.nodeInstanceId(), actual.nodeDefinitionId(), actual.kind(), actual.handlerType(),
                actual.status(), actual.stageId(), actual.iterationId(), refs, actual.outputRefs(), actual.result(), actual.runRef(), actual.startedAt(), actual.finishedAt());
    }

    private String fixtureBaseCommit;
    private void writeTaskContract(TaskContract.ScopeEntry... entries) throws Exception {
        var f = ApprovedExecutionTestFixture.create(tempDir, "ws", List.of(entries));
        var path = f.paths.workstreamDir().resolve("workspaces/workspace-readiness.json");
        var mapper = new ObjectMapper();
        var workspace = (com.fasterxml.jackson.databind.node.ObjectNode) mapper.readTree(path.toFile());
        workspace.put("baseCommit", fixtureBaseCommit == null ? "" : fixtureBaseCommit);
        mapper.writeValue(path.toFile(), workspace);
    }
    private void writeWorkspaceBase(String baseCommit) { fixtureBaseCommit = baseCommit; }

    private String writeOutput(String name, String content) throws Exception {
        var path = tempDir.resolve(".agent").resolve("workstreams").resolve("ws").resolve("runs").resolve("run-001").resolve("outputs").resolve(name);
        Files.createDirectories(path.getParent());
        var publishLineage = false;
        if (name.endsWith(".contract.json")) {
            try {
                var mapper = new ObjectMapper();
                var json = mapper.readTree(content);
                if (json instanceof com.fasterxml.jackson.databind.node.ObjectNode object) {
                    var sourceName = name.substring(0, name.length() - ".contract.json".length()) + ".json";
                    var sourcePath = path.resolveSibling(sourceName);
                    object.put("workstream_id", "ws");
                    object.put("run_id", "run-001");
                    object.put("node_instance_id", "node-fixture-" + sourceName.replaceAll("[^A-Za-z0-9._-]", "-"));
                    object.put("source_output_ref", tempDir.relativize(sourcePath).toString());
                    content = mapper.writerWithDefaultPrettyPrinter().writeValueAsString(object);
                    publishLineage = true;
                }
            } catch (Exception ignored) {
                // Malformed sidecars are intentional fixtures in rejection tests.
            }
        }
        Files.writeString(path, content);
        if (publishLineage) {
            AgentOutputLineageFixture.publish(tempDir, "ws", path);
        }
        return tempDir.relativize(path).toString();
    }

    private static void git(Path workdir, String... args) throws Exception {
        gitOutput(workdir, args);
    }

    private static String gitOutput(Path workdir, String... args) throws Exception {
        var command = new java.util.ArrayList<String>();
        command.add("git");
        command.addAll(List.of(args));
        var process = new ProcessBuilder(command)
                .directory(workdir.toFile())
                .redirectErrorStream(true)
                .start();
        var output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        var exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new AssertionError("git command failed: " + command + "\n" + output);
        }
        return output;
    }
}

package dev.dual.runtime.handler;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class ChangeScopeEvaluationArtifactTest {
    @TempDir
    Path tempDir;

    @Test
    void publishesAndVerifiesOnlyTheExpectedOccurrence() throws Exception {
        var evaluation = new ChangeScopeEvaluation(
                1, ChangeScopeEvaluation.Status.FAIL, List.of(), List.of(), List.of(), List.of(), null);

        var reference = ChangeScopeEvaluationArtifact.publish(tempDir, "ws-one", "node-validation-001", evaluation);
        var verified = ChangeScopeEvaluationArtifact.verify(
                tempDir, "ws-one", "node-validation-001", reference.ref(), reference.sha256());

        assertEquals(ChangeScopeEvaluation.Status.FAIL, verified.document().evaluation().status());
        assertThrows(Exception.class, () -> ChangeScopeEvaluationArtifact.verify(
                tempDir, "ws-two", "node-validation-001", reference.ref(), reference.sha256()));
        assertThrows(Exception.class, () -> ChangeScopeEvaluationArtifact.verify(
                tempDir, "ws-one", "node-validation-002", reference.ref(), reference.sha256()));
        assertThrows(Exception.class, () -> ChangeScopeEvaluationArtifact.verify(
                tempDir, "ws-one", "node-validation-001",
                ".agent/workstreams/ws-one/artifacts/git-evidence/change-scope-evaluation.json",
                reference.sha256()));
    }

    @Test
    void rejectsDeletedOrTamperedOccurrence() throws Exception {
        var evaluation = new ChangeScopeEvaluation(
                1, ChangeScopeEvaluation.Status.FAIL, List.of(), List.of(), List.of(), List.of(), null);
        var deleted = ChangeScopeEvaluationArtifact.publish(tempDir, "ws", "node-one", evaluation);
        Files.delete(tempDir.resolve(deleted.ref()));
        assertThrows(Exception.class, () -> ChangeScopeEvaluationArtifact.verify(
                tempDir, "ws", "node-one", deleted.ref(), deleted.sha256()));

        var tampered = ChangeScopeEvaluationArtifact.publish(tempDir, "ws", "node-two", evaluation);
        Files.writeString(tempDir.resolve(tampered.ref()), "{}\n");
        assertThrows(Exception.class, () -> ChangeScopeEvaluationArtifact.verify(
                tempDir, "ws", "node-two", tampered.ref(), tampered.sha256()));
        assertThrows(Exception.class, () -> ChangeScopeEvaluationArtifact.publish(
                tempDir, "ws", "node-two", evaluation));
    }

    @Test
    void siblingPublicationCannotReplaceAnEarlierOccurrence() throws Exception {
        var firstEvaluation = new ChangeScopeEvaluation(
                1, ChangeScopeEvaluation.Status.FAIL, List.of(), List.of(), List.of(), List.of(), null);
        var secondEvaluation = ChangeScopeEvaluation.unavailable("second occurrence");
        var first = ChangeScopeEvaluationArtifact.publish(tempDir, "ws", "node-one", firstEvaluation);
        var firstBytes = Files.readAllBytes(tempDir.resolve(first.ref()));

        ChangeScopeEvaluationArtifact.publish(tempDir, "ws", "node-two", secondEvaluation);

        assertEquals(java.util.HexFormat.of().formatHex(
                        java.security.MessageDigest.getInstance("SHA-256").digest(firstBytes)),
                first.sha256());
        assertEquals(List.of(), ChangeScopeEvaluationArtifact.verify(
                tempDir, "ws", "node-one", first.ref(), first.sha256())
                .document().evaluation().violations());
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContract;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ChangeScopeEvaluationTest {
    @Test
    void approvedFileModificationIsNotProofOfEvidenceOnlyImmutability() {
        var result = ChangeScopeEvaluator.evaluate(
                contract(entry("src/Service.java", TaskContract.ScopeOperation.MODIFY)),
                List.of(new ChangeScopeEvaluation.ActualChange(
                        "src/Service.java", ChangeScopeEvaluation.ActualOperation.MODIFY, null, "M")));
        assertEquals(ChangeScopeEvaluation.Status.PASS, result.status(),
                "scope authorizes paths/operations; it cannot certify unchanged source bytes");
        assertEquals(List.of("src/Service.java"), result.matchedPaths());
    }

    @Test
    void parsesGitNameStatusIntoTypedActualChanges() {
        var changes = ChangeScopeEvaluator.parseNameStatus(
                "A\0new.txt\0"
                        + "M\0existing.txt\0"
                        + "D\0deleted.txt\0"
                        + "R100\0old.txt\0renamed.txt\0"
        );

        assertEquals(List.of(
                new ChangeScopeEvaluation.ActualChange(
                        "new.txt", ChangeScopeEvaluation.ActualOperation.CREATE, null, "A"),
                new ChangeScopeEvaluation.ActualChange(
                        "existing.txt", ChangeScopeEvaluation.ActualOperation.MODIFY, null, "M"),
                new ChangeScopeEvaluation.ActualChange(
                        "deleted.txt", ChangeScopeEvaluation.ActualOperation.DELETE, null, "D"),
                new ChangeScopeEvaluation.ActualChange(
                        "renamed.txt", ChangeScopeEvaluation.ActualOperation.RENAME, "old.txt", "R100")
        ), changes);
    }

    @Test
    void nulFramingPreservesUnicodeTabsAndNewlinesInPaths() {
        var path = "docs/路径\t说明\n补充.md";

        var changes = ChangeScopeEvaluator.parseNameStatus("M\0" + path + "\0");

        assertEquals(List.of(new ChangeScopeEvaluation.ActualChange(
                path,
                ChangeScopeEvaluation.ActualOperation.MODIFY,
                null,
                "M"
        )), changes);
    }

    @Test
    void lineFramedNameStatusIsRejected() {
        assertThrows(
                IllegalArgumentException.class,
                () -> ChangeScopeEvaluator.parseNameStatus("M\tREADME.md\n")
        );
    }

    @Test
    void failedGitNameStatusCommandCannotBecomeEmptyActualChanges() {
        assertThrows(
                IllegalArgumentException.class,
                () -> ChangeScopeEvaluator.parseNameStatus(128, "")
        );
    }

    @Test
    void missingDeclaredChangeIsObservationNotFailure() {
        var evaluation = ChangeScopeEvaluator.evaluate(
                contract(
                        entry("README.md", TaskContract.ScopeOperation.MODIFY),
                        entry("new.txt", TaskContract.ScopeOperation.CREATE)
                ),
                List.of(new ChangeScopeEvaluation.ActualChange(
                        "README.md",
                        ChangeScopeEvaluation.ActualOperation.MODIFY,
                        null,
                        "M"
                ))
        );

        assertEquals(ChangeScopeEvaluation.Status.PASS, evaluation.status());
        assertEquals(List.of("README.md"), evaluation.matchedPaths());
        assertEquals(List.of(entry("new.txt", TaskContract.ScopeOperation.CREATE)), evaluation.missingDeclared());
        assertTrue(evaluation.violations().isEmpty());
    }

    @Test
    void deleteAndRenameFailClosedBecauseContractDoesNotModelThem() {
        var evaluation = ChangeScopeEvaluator.evaluate(
                contract(entry("deleted.txt", TaskContract.ScopeOperation.MODIFY)),
                List.of(
                        new ChangeScopeEvaluation.ActualChange(
                                "deleted.txt", ChangeScopeEvaluation.ActualOperation.DELETE, null, "D"),
                        new ChangeScopeEvaluation.ActualChange(
                                "renamed.txt", ChangeScopeEvaluation.ActualOperation.RENAME, "old.txt", "R100")
                )
        );

        assertEquals(ChangeScopeEvaluation.Status.FAIL, evaluation.status());
        assertEquals(2, evaluation.violations().size());
        assertTrue(evaluation.violations().stream()
                .allMatch(violation -> "UNSUPPORTED_ACTUAL_OPERATION".equals(violation.code())));
    }

    private static TaskContract contract(TaskContract.ScopeEntry... entries) {
        return new TaskContract(2,
                dev.dual.core.contract.TaskContract.Phase.EXECUTION,
                1,
                "task-ws",
                1,
                java.time.Instant.parse("2026-07-26T00:00:00Z"),
                "Validate implementation changes",
                new TaskContract.Scope(List.of(entries), List.of()),
                dev.dual.runtime.RuntimeTestLedger.clauses("AC-", List.of("AC1", "AC2")),
                dev.dual.runtime.RuntimeTestLedger.clauses("TR-", List.of("Run tests")),
                List.of("Keep scope bounded"),
                List.of(),
                List.of(),
                java.util.List.of(),
                List.of(),
                List.of(),
                dev.dual.core.contract.ContractStatus.READY_FOR_REVIEW,
                1,
                new TaskContract.Source("requirement.md", "test", null, null),
                null,
                java.util.List.of(),
                java.util.List.of(),
                java.util.List.of());
    }

    private static TaskContract.ScopeEntry entry(String path, TaskContract.ScopeOperation operation) {
        return new TaskContract.ScopeEntry(path, operation);
    }
}

