        var gate = (com.fasterxml.jackson.databind.node.ObjectNode) mapper.readTree(gatePath.toFile());
        ((com.fasterxml.jackson.databind.node.ObjectNode) gate.path("result")).put("source_node_instance_id", "node-forged");
