        original.put("finishedAt", Instant.now().plusSeconds(2).toString());
        mapper.writeValue(fixture.paths.nodeJson("node-unapproved-recompile").toFile(), original);
        assertEquals("UNAPPROVED_RECOMPILE", resolve().failure().reason());
