                .replace("src/Auth.java", "src/Mutated.java"));
        var mapper = new ObjectMapper().registerModule(new JavaTimeModule());
        var definition = new NodeDefinition("ctx.acceptance", NodeKind.TASK, "context.build_package", Map.of(
