                    };
                    fixture.advanceToGate();
                    assertEquals(WorkflowStatus.WAITING_FOR_RECOVERY, fixture.ledger.loadCurrent(fixture.paths).status());
                    assertEquals("plan.claude_plan", fixture.calls.getLast());
