                try {
                    assertTrue(process.waitFor(20, TimeUnit.SECONDS));
                    assertEquals(0, process.exitValue(), Files.readString(f.root.resolve("cold-publication.err")));
                    assertEquals("REJECTED", Files.readString(stdout).trim());
