        writeMemory("ws-empty", """
                {"schemaVersion":1,"artifactType":"workstream_memory","workstreamId":"ws-empty",
                 "decidedScope":[],"nonGoals":[],"readFiles":[],"decisions":[],"openIssues":[]}
                """);
        var b = new StringBuilder();
        WorkstreamMemoryProjection.appendAgentHandoff(dev.dual.runtime.RuntimeTestLedger.ledger(), b, workstreamDir("ws-empty"), tempDir);
        var text = b.toString();
        assertFalse(text.contains("(no stage handoff evidence yet)"), text);
        assertTrue(text.contains("task-contract.json") || text.contains("workstream-memory.json"), text);
    }
}

package dev.dual.runtime.lifecycle;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.workflow.WorkflowDefinition;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.Path;
import java.util.List;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

class AcceptanceRepairWorkflowDefinitionTest {
    static final List<String> RESOURCES = List.of("full", "contract", "terminal-delivery",
            "small-plan-human-review-experiment");
    private static final ObjectMapper MAPPER = new ObjectMapper();
    @TempDir Path root;

    @Test
    void allFourDefinitionsDeclareBoundedContractRepairViaProposalContext() throws Exception {
        for (var variant : RESOURCES) {
            var definition = loadResource(root, variant);
            assertEquals(3, definition.node("acceptance.classify_failure").config().get("max_revisions"));
            for (var prerequisite : List.of("REJECT_TOOL_LIMITATION", "REJECT_CONTEXT_INSUFFICIENT")) {
                var routes = definition.edgesFrom("acceptance.classify_failure").stream()
                        .filter(edge -> prerequisite.equals(edge.on())).toList();
                assertEquals(1, routes.size());
                assertEquals("gate.human_implementation_repair", routes.getFirst().to());
                assertEquals("normal", routes.getFirst().metadata().transitionType(),
                        "missing prerequisites cannot start an automatic product revision");
            }
            var scope = definition.edgesFrom("gate.human_implementation_repair").stream()
                    .filter(edge -> edge.on().equals("request_scope_revision")).toList();
            assertEquals(1, scope.size());
            assertEquals("context.intake_claude_brainstorm", scope.getFirst().to());
            assertEquals("loop", scope.getFirst().metadata().transitionType());
            assertEquals(List.of("revise", "request_scope_revision", "request_action", "collect_evidence", "submit_evidence"), definition.node("gate.human_implementation_repair")
                    .config().get("allowed_actions"));
            for (var outcome : List.of("REJECT_CONTRACT_GAP", "REJECT_CONTRACT_AMBIGUITY")) {
                var edges = definition.edgesFrom("acceptance.classify_failure").stream()
                        .filter(edge -> outcome.equals(edge.on())).toList();
                assertEquals(1, edges.size());
                assertEquals("context.intake_claude_brainstorm", edges.getFirst().to());
                assertEquals("loop", edges.getFirst().metadata().transitionType());
            }
            assertEquals("intake.claude_brainstorm",
                    definition.edgesFrom("context.intake_claude_brainstorm").getFirst().to());
            assertEquals("task_contract_proposal",
                    definition.node("intake.claude_brainstorm").config().get("expected_artifact"));
            assertFalse(definition.node("context.intake_claude_brainstorm").config().containsKey("required_contract_phase"));
        }
    }

    @Test
    void scopeRequestCannotUseAnotherSourceOrSkipProposalReview() throws Exception {
        for (var target : List.of("intake.claude_brainstorm", "contract.compile", "context.implement_claude")) {
            var json = resource("full");
            edge(json, "gate.human_implementation_repair", "request_scope_revision").put("to", target);
            assertThrows(IOException.class, () -> load(json));
        }
        var json = resource("full");
        edge(json, "gate.human_implementation_repair", "request_scope_revision").put("from", "gate.human_plan_approval");
        assertThrows(IOException.class, () -> load(json));
    }

    @Test
    void customWorkflowIdentityDoesNotNeedABundledName() throws Exception {
        var json = resource("full");
        json.put("workflowId", "custom-documentation-workflow");
        assertEquals("custom-documentation-workflow", load(json).workflowId());
    }

    @Test
    void rejectsInvalidContractRepairSourcesTargetsAndProducers() throws Exception {
        List<Consumer<ObjectNode>> mutations = List.of(
                json -> repair(json).put("from", "acceptance.decision"),
                json -> node(json, "acceptance.classify_failure").put("handlerType", "noop.task"),
                json -> node(json, "acceptance.classify_failure").put("kind", "DECISION"),
                json -> config(json, "acceptance.classify_failure").put("required_contract_phase", "GOAL"),
                json -> repair(json).put("to", "contract.compile"),
                json -> repair(json).put("to", "intake.claude_brainstorm"),
                json -> repair(json).put("to", "context.intake_codex_product_review"),
                json -> repair(json).withObject("metadata").put("transitionType", "normal"),
                json -> repair(json).withObject("metadata").put("branchGroupId", "fan-out"),
                json -> repair(json).withObject("metadata").put("required", false),
                json -> repair(json).putObject("condition").put("type", "config_equals")
                        .putObject("params").put("key", "x").put("value", "y"),
                json -> node(json, "context.intake_claude_brainstorm").put("handlerType", "noop.task"),
                json -> config(json, "context.intake_claude_brainstorm").put("target_node", "contract.compile"),
                json -> edge(json, "context.intake_claude_brainstorm", "completed").put("to", "contract.compile"),
                json -> config(json, "intake.claude_brainstorm").put("expected_artifact", "agent_output_contract"),
                json -> config(json, "intake.claude_brainstorm").put("artifact_compiler", "agent_output_contract_compiler"),
                json -> node(json, "intake.claude_brainstorm").put("handlerType", "noop.task"),
                json -> json.withArray("edges").add(repair(json).deepCopy()),
                json -> json.put("entryNodeId", "acceptance.classify_failure")
        );
        for (int i = 0; i < mutations.size(); i++) {
            var json = resource("full");
            mutations.get(i).accept(json);
            assertThrows(IOException.class, () -> load(json), "mutation " + i);
        }
    }

    @Test
    void otherOutcomesCannotReuseNegotiationOrCompileEntry() throws Exception {
        for (var target : List.of("context.intake_claude_brainstorm", "intake.claude_brainstorm",
                "contract.compile", "gate.human_requirement_review")) {
            var json = resource("full");
            edge(json, "acceptance.classify_failure", "REJECT_IMPLEMENTATION_BUG").put("to", target);
            assertThrows(IOException.class, () -> load(json), target);
        }
    }

    static WorkflowDefinition loadResource(Path root, String variant) throws Exception {
        var path = root.resolve(variant + ".json");
        MAPPER.writeValue(path.toFile(), resource(variant));
        return new WorkflowDefinitionLoader().load(path);
    }

    private WorkflowDefinition load(ObjectNode json) throws Exception {
        var path = root.resolve("custom.json");
        MAPPER.writeValue(path.toFile(), json);
        return new WorkflowDefinitionLoader().load(path);
    }

    private static ObjectNode resource(String variant) throws Exception {
        try (var stream = AcceptanceRepairWorkflowDefinitionTest.class.getResourceAsStream(
                "/dev/dual/runtime/lifecycle/agent-lifecycle." + variant + ".json")) {
            assertNotNull(stream, variant);
            return (ObjectNode) MAPPER.readTree(stream);
        }
    }

    private static ObjectNode repair(ObjectNode json) {
        return edge(json, "acceptance.classify_failure", "REJECT_CONTRACT_GAP");
    }

    private static ObjectNode edge(ObjectNode json, String from, String outcome) {
        for (var edge : json.withArray("edges")) {
            if (from.equals(edge.path("from").asText()) && outcome.equals(edge.path("on").asText())) {
                return (ObjectNode) edge;
            }
        }
        throw new AssertionError(from + ":" + outcome);
    }

    private static ObjectNode node(ObjectNode json, String id) {
        for (var node : json.withArray("nodes")) {
            if (id.equals(node.path("id").asText())) return (ObjectNode) node;
        }
        throw new AssertionError(id);
    }

    private static ObjectNode config(ObjectNode json, String id) {
        return node(json, id).withObject("config");
    }
}

package dev.dual.runtime.lifecycle;

import dev.dual.core.id.DualId;
import dev.dual.core.workflow.EdgeDefinition;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.TransitionMetadata;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.*;

class AcceptanceRevisionBudgetTest {
    private static final String CLASSIFIER = "acceptance.classify_failure";
    @TempDir Path root;

    @Test
    void eachTargetStopsBeforeFourthRepairAfterColdReadsForAllDefinitions() throws Exception {
        for (var variant : AcceptanceRepairWorkflowDefinitionTest.RESOURCES) {
            var definition = budgetSlice(variant);
            for (var edge : definition.edgesFrom(CLASSIFIER)) {
                var paths = initialize(definition, variant + "-" + edge.on().toLowerCase());
                for (int round = 0; round < 3; round++) {
                    repairAndReturn(paths, definition, edge.on());
                }
                assertStoppedBeforeNextRepair(paths, definition, edge.on(), 3);
            }
        }
    }

    @Test
    void differentCategoriesSharingATargetShareTheSameBudget() throws Exception {
        var definition = budgetSlice("full");
        var contracts = initialize(definition, "contract-shared");
        repairAndReturn(contracts, definition, "REJECT_CONTRACT_GAP");
        repairAndReturn(contracts, definition, "REJECT_CONTRACT_AMBIGUITY");
        repairAndReturn(contracts, definition, "REJECT_CONTRACT_GAP");
        assertStoppedBeforeNextRepair(contracts, definition, "REJECT_CONTRACT_AMBIGUITY", 3);

        var implementation = initialize(definition, "implementation-shared");
        for (int round = 0; round < 3; round++) {
            repairAndReturn(implementation, definition, "REJECT_IMPLEMENTATION_BUG");
        }
        assertStoppedBeforeNextRepair(implementation, definition, "REJECT_IMPLEMENTATION_BUG", 3);
    }

    @Test
    void alternatingFourTargetsAllowsTwelveRepairsNotAGlobalThree() throws Exception {
        var definition = budgetSlice("full");
        var paths = initialize(definition, "alternating");
        var outcomes = List.of("REJECT_CONTRACT_GAP", "REJECT_IMPLEMENTATION_BUG",
                "REJECT_VERIFICATION_INSUFFICIENT", "REJECT_REVIEW_NOISE");
        assertEquals(4, definition.edgesFrom(CLASSIFIER).stream().map(EdgeDefinition::to).distinct().count());
        for (int round = 0; round < 3; round++) {
            for (var outcome : outcomes) repairAndReturn(paths, definition, outcome);
        }
        assertStoppedBeforeNextRepair(paths, definition, "REJECT_REVIEW_NOISE", 12);
    }

    @Test
    void separateJvmRunsCannotResetPersistedRevisionBudget() throws Exception {
        var definition = budgetSlice("full");
        var paths = initialize(definition, "cold-jvm");
        for (int round = 0; round < 3; round++) {
            var child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
                    "-cp", System.getProperty("surefire.test.class.path", System.getProperty("java.class.path")),
                    AcceptanceRevisionBudgetTest.class.getName(), root.toString(), "ws-cold-jvm")
                    .redirectErrorStream(true).start();
            try {
                assertTrue(child.waitFor(30, TimeUnit.SECONDS), "cold ledger run timed out");
                assertEquals(0, child.exitValue(), new String(child.getInputStream().readAllBytes(),
                        java.nio.charset.StandardCharsets.UTF_8));
            } finally {
                if (child.isAlive()) child.destroyForcibly().waitFor();
            }
        }
        assertStoppedBeforeNextRepair(paths, definition, "REJECT_REVIEW_NOISE", 3);
    }

    public static void main(String[] args) throws Exception {
        var paths = new WorkstreamPaths(Path.of(args[0]), new DualId(args[1]));
        var definition = dev.dual.runtime.RuntimeTestLedger.ledger().loadDefinition(paths);
        complete(paths, definition, "REJECT_REVIEW_NOISE");
        assertEquals("context.acceptance_codex_verifier_review", active(paths).nodeDefinitionId());
        complete(paths, definition, "completed");
        assertEquals(CLASSIFIER, active(paths).nodeDefinitionId());
    }

    @Test
    void explicitHumanRevisionKeepsItsExistingBudgetExemption() throws Exception {
        var definition = new WorkflowDefinition("human-revision", 1, "work", List.of(
                new NodeDefinition("work", NodeKind.TASK, "noop.task", Map.of()),
                new NodeDefinition("gate.review", NodeKind.GATE, "human.review",
                        Map.of("allowed_actions", List.of("revise"), "max_revisions", 0))), List.of(
                new EdgeDefinition("work", "completed", "gate.review"),
                new EdgeDefinition("gate.review", "revise", "work", null, TransitionMetadata.loop("human revision"))));
        var paths = initialize(definition, "human-revision");
        for (int i = 0; i < 4; i++) {
            complete(paths, definition, "completed");
            dev.dual.runtime.RuntimeTestLedger.ledger().resolveOpenGate(paths, definition, "revise", "explicit human revision " + i);
            assertEquals("work", active(paths).nodeDefinitionId());
            assertEquals(WorkflowStatus.RUNNING, dev.dual.runtime.RuntimeTestLedger.ledger().loadCurrent(paths).status());
        }
    }

    // Real classifier config and loop edges; repair work is completed explicitly, without providers.
    private WorkflowDefinition budgetSlice(String variant) throws Exception {
        var bundled = AcceptanceRepairWorkflowDefinitionTest.loadResource(root, variant);
        var edges = new ArrayList<>(bundled.edgesFrom(CLASSIFIER).stream()
                .filter(edge -> "loop".equals(edge.metadata().transitionType())).toList());
        var nodes = new ArrayList<NodeDefinition>();
        nodes.add(bundled.node(CLASSIFIER));
        edges.stream().map(EdgeDefinition::to).distinct().forEach(target -> nodes.add(bundled.node(target)));
        for (var target : nodes.stream().map(NodeDefinition::id).filter(id -> !CLASSIFIER.equals(id)).toList()) {
            edges.add(new EdgeDefinition(target, "completed", CLASSIFIER));
        }
        return new WorkflowDefinition("budget-" + variant, 1, CLASSIFIER, nodes, edges);
    }

    private WorkstreamPaths initialize(WorkflowDefinition definition, String id) throws Exception {
        var paths = new WorkstreamPaths(root, new DualId("ws-" + id));
        Files.createDirectories(paths.workstreamDir());
        dev.dual.runtime.RuntimeTestLedger.initialize(dev.dual.runtime.RuntimeTestLedger.ledger(), paths, "wf-" + id, definition);
        return paths;
    }

    private void repairAndReturn(WorkstreamPaths paths, WorkflowDefinition definition, String outcome) throws Exception {
        assertEquals(CLASSIFIER, active(paths).nodeDefinitionId());
        var target = definition.edgesFrom(CLASSIFIER).stream().filter(edge -> outcome.equals(edge.on()))
                .findFirst().orElseThrow().to();
        complete(paths, definition, outcome);
        var repair = active(paths);
        assertEquals(target, repair.nodeDefinitionId());
        assertEquals(NodeStatus.READY, repair.status());
        assertEquals("loop", repair.inputTransition().get("transition_type"));
        complete(paths, definition, "completed");
        assertEquals(CLASSIFIER, active(paths).nodeDefinitionId());
    }

    private void assertStoppedBeforeNextRepair(WorkstreamPaths paths, WorkflowDefinition definition,
                                               String outcome, int totalRepairs) throws Exception {
        var trigger = active(paths);
        long nodesBefore;
        try (var files = Files.list(paths.nodesDir())) { nodesBefore = files.count(); }
        complete(paths, definition, outcome);
        var ledger = dev.dual.runtime.RuntimeTestLedger.ledger();
        var current = ledger.loadCurrent(paths);
        assertEquals(WorkflowStatus.WAITING_FOR_RECOVERY, current.status());
        assertEquals(List.of(trigger.nodeInstanceId()), current.activeNodeInstanceIds());
        var blocked = active(paths);
        assertEquals(NodeStatus.BLOCKED, blocked.status());
        assertEquals("revision_limit_reached", blocked.result().get("reason"));
        assertEquals(3, blocked.result().get("max_revisions"));
        assertEquals(3, blocked.result().get("current_revision_count"));
        assertEquals(List.of("recovery-" + trigger.nodeInstanceId()), current.openGateIds());
        try (var files = Files.list(paths.nodesDir())) { assertEquals(nodesBefore, files.count()); }
        try (var files = Files.list(paths.iterationsDir())) { assertEquals(totalRepairs + 1, files.count()); }
        var events = Files.readString(paths.eventsJsonl());
        assertTrue(events.contains("revision_limit_reached"));
        assertFalse(Files.exists(paths.iterationJson("iter-" + String.format("%03d", totalRepairs + 2))));
    }

    private static NodeInstanceDocument active(WorkstreamPaths paths) throws Exception {
        var ledger = dev.dual.runtime.RuntimeTestLedger.ledger();
        var current = ledger.loadCurrent(paths);
        assertEquals(1, current.activeNodeInstanceIds().size());
        return ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
    }

    private static void complete(WorkstreamPaths paths, WorkflowDefinition definition, String outcome) throws Exception {
        var node = active(paths);
        dev.dual.runtime.RuntimeTestLedger.ledger().completeAndRoute(paths, definition, node.nodeInstanceId(), NodeStatus.COMPLETED,
                outcome, List.of("evidence-" + node.nodeInstanceId()), Map.of("decision", outcome));
    }
}

