    @Test
    void allAcceptanceProfilesDeclareTheSameRequiredSelfTestEvidence() throws Exception {
        var definitions = List.of(
                new LifecycleWorkflowDefinitionFactory().forVariant("full"),
                new LifecycleWorkflowDefinitionFactory().forVariant("contract"),
                new LifecycleWorkflowDefinitionFactory().forVariant("terminal-delivery"),
                loadExperiment());

        for (var definition : definitions) {
            var context = definition.node("context.acceptance_codex_verifier_review");
            assertEquals("acceptance", context.config().get("profile"), definition.workflowId());
            assertEquals("acceptance.codex_verifier_review", context.config().get("target_node"),
                    definition.workflowId());
            assertEquals(Map.of(
                            "node_id", "implement.claude_self_test_report",
                            "source_artifact_type", "self_test_report",
                            "decision", "SELF_TEST_COMPLETE"),
                    context.config().get("required_agent_evidence"), definition.workflowId());
        }
    }

    @Test
    void allDesignProfilesDeclareTypedDesignAndTheSameReviewConsumer() throws Exception {
        for (var definition : List.of(
                new LifecycleWorkflowDefinitionFactory().forVariant("full"),
                new LifecycleWorkflowDefinitionFactory().forVariant("contract"),
                new LifecycleWorkflowDefinitionFactory().forVariant("terminal-delivery"), loadExperiment())) {
            var producer = definition.node("design.claude_design");
            assertEquals("design_result", producer.config().get("expected_artifact"));
            assertEquals("GOAL", producer.config().get("required_contract_phase"));
            assertEquals(java.util.Set.of("design_result"),
                    dev.dual.runtime.handler.ContractRegistry.forNode(producer.id()).outputArtifactTypes());
            var consumer = definition.node("context.design_codex_arch_review");
            assertEquals("architecture_review", consumer.config().get("profile"));
            assertEquals("design.codex_arch_review", consumer.config().get("target_node"));
            assertEquals("context.design_codex_arch_review", definition.edgesFrom(producer.id()).getFirst().to());
        }
    }

    @Test
    void allLifecycleProfilesDeclareTheSameChangeScopeRepairRoute() throws Exception {
        var definitions = List.of(
                new LifecycleWorkflowDefinitionFactory().forVariant("full"),
                new LifecycleWorkflowDefinitionFactory().forVariant("contract"),
                new LifecycleWorkflowDefinitionFactory().forVariant("terminal-delivery"),
                loadExperiment());

        for (var definition : definitions) {
            assertEquals(true, definition.node("implement.artifact_validation")
                    .config().get("route_scope_violation"), definition.workflowId());
            var route = definition.edgesFrom("implement.artifact_validation").stream()
                    .filter(edge -> "CHANGE_SCOPE_VIOLATION".equals(edge.on()))
                    .findFirst().orElseThrow();
            assertEquals("gate.human_implementation_repair", route.to(), definition.workflowId());
            var repair = definition.edgesFrom("gate.human_implementation_repair").stream()
                    .filter(edge -> "revise".equals(edge.on()))
                    .findFirst().orElseThrow();
            assertEquals("Human authorized implementation repair", repair.metadata().loopReason(),
                    definition.workflowId());
        }
    }

    static dev.dual.core.workflow.WorkflowDefinition loadExperiment() throws Exception {
        return new WorkflowDefinitionLoader().load(resourcePath(EXPERIMENT_RESOURCE));
    }

    private static Path resourcePath(String resource) throws URISyntaxException {
        return Path.of(SmallWorkflowProfileDefinitionTest.class.getResource(resource).toURI());
    }

}

package dev.dual.runtime.lifecycle;

import org.junit.jupiter.api.Test;

import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TerminalDeliveryWorkflowDefinitionTest {
    private static final Set<String> OMITTED_TAIL_NODES = Set.of(
            "stage.claude_handoff",
            "stage.generate_next_prompt",
            "gate.human_next_stage_approval"
    );

    @Test
    void bundledVariantChangesOnlyTheAcceptedDeliveryTail() {
        var full = new LifecycleWorkflowDefinitionFactory().forVariant("full");
        var terminal = new LifecycleWorkflowDefinitionFactory().forVariant("terminal-delivery");

        assertEquals("agent-lifecycle-terminal-delivery", terminal.workflowId());
        assertEquals(9, terminal.nodes().stream()
                .filter(node -> "acpx.agent_run".equals(node.handlerType()))
                .count());

        assertTrue(terminal.nodes().stream().noneMatch(node -> OMITTED_TAIL_NODES.contains(node.id())));
        assertTrue(terminal.edges().stream().noneMatch(edge ->
                OMITTED_TAIL_NODES.contains(edge.from()) || OMITTED_TAIL_NODES.contains(edge.to())));
        assertTrue(terminal.edgesFrom("gate.human_acceptance").stream()
                .noneMatch(edge -> "approved".equals(edge.on())));
        assertEquals("context.implement_claude", terminal.edgesFrom("gate.human_acceptance").stream()
                .filter(edge -> "revise".equals(edge.on()))
                .findFirst()
                .orElseThrow()
                .to());
        assertEquals(true, terminal.node("gate.human_acceptance").config().get("terminal_gate"));
        assertEquals(1, terminal.node("implement.self_test_decision").config().get("max_revisions"));
        assertEquals(java.util.List.of("revise", "request_scope_revision", "request_action", "collect_evidence", "submit_evidence"),
                terminal.node("gate.human_implementation_repair").config().get("allowed_actions"));
        assertEquals(java.util.Map.of(
                        "SELF_TEST_COMPLETE", "implement.artifact_validation",
                        "SELF_TEST_INCOMPLETE", "context.implement_claude",
                        "BLOCKED", "gate.human_implementation_repair"),
                terminal.edgesFrom("implement.self_test_decision").stream()
                        .filter(edge -> edge.condition().evaluate(java.util.Map.of(
                                "continuation_kind", "IMPLEMENTATION_REPAIR")))
                        .collect(java.util.stream.Collectors.toMap(edge -> edge.on(), edge -> edge.to())));
        assertEquals("gate.human_implementation_repair", terminal.edgesFrom("implement.self_test_decision",
                "SELF_TEST_INCOMPLETE", java.util.Map.of("continuation_kind", "HUMAN_REVIEW"))
                .getFirst().to());

        for (var node : full.nodes()) {
            if (OMITTED_TAIL_NODES.contains(node.id()) || "gate.human_acceptance".equals(node.id())) {
                continue;
            }
            assertEquals(node, terminal.node(node.id()), node.id());
        }
        var expectedEdges = full.edges().stream()
                .filter(edge -> !OMITTED_TAIL_NODES.contains(edge.from()))
                .map(edge -> edge.from().equals("acceptance.generate_final_report")
                        ? new dev.dual.core.workflow.EdgeDefinition(edge.from(), edge.on(), "delivery.prepare_pr", edge.condition(), edge.metadata()) : edge)
                .filter(edge -> !OMITTED_TAIL_NODES.contains(edge.to()))
                .filter(edge -> !("gate.human_acceptance".equals(edge.from())
                        && "approved".equals(edge.on())))
                .toList();
        var json = new com.fasterxml.jackson.databind.ObjectMapper()
                .registerModule(new dev.dual.ledger.file.EdgeConditionModule());
        assertEquals(json.valueToTree(expectedEdges), json.valueToTree(terminal.edges()));

        assertFalse(Boolean.TRUE.equals(full.node("gate.human_acceptance").config().get("terminal_gate")));
        assertTrue(full.edgesFrom("gate.human_acceptance").stream().noneMatch(edge -> "approved".equals(edge.on())));
    }
}

