+async function assertQueueOwnerRejectsPolicyMismatch(): Promise<void> {
+  await withTempHome("acpx-queue-policy-conflict-", async (homeDir) => {
+    const cwd = path.join(homeDir, "workspace");
+    await fs.mkdir(cwd, { recursive: true });
+    const record = makeSessionRecord({
+      acpxRecordId: "queue-policy-conflict",
+      acpSessionId: "queue-policy-conflict-session",
+      agentCommand: `node ${JSON.stringify(MOCK_AGENT_PATH)}`,
+      cwd,
+      acpx: {
+        session_options: {
+          claude_execution_policy_ref: "runs/run-1/execution-authority/policy.json",
+          claude_execution_policy_sha256: "a".repeat(64),
+        },
+      },
+    });
+    await writeSessionRecordFile(homeDir, record);
+    const lockPath = queueLockFilePath(record.acpxRecordId, homeDir);
+    const payload = JSON.stringify({
+      sessionId: record.acpxRecordId,
+      permissionMode: "approve-reads",
+      sessionOptions: {
+        claudeExecutionPolicyRef: "runs/run-2/execution-authority/policy.json",
+        claudeExecutionPolicySha256: "b".repeat(64),
+      },
+    });
+    const child = spawn(process.execPath, [CLI_PATH, "__queue-owner"], {
+      env: {
+        ...process.env,
+        HOME: homeDir,
+        ACPX_QUEUE_OWNER_PAYLOAD: payload,
+      },
+      stdio: ["ignore", "ignore", "pipe"],
+    });
+    const stderrChunks: Buffer[] = [];
+    child.stderr?.on("data", (chunk: Buffer) => stderrChunks.push(chunk));
+
+    const { code } = await waitForProcessExit(child);
+    const stderr = Buffer.concat(stderrChunks).toString("utf8");
+    assert.notEqual(code, 0);
+    assert.match(stderr, /CLAUDE_EXECUTION_POLICY_CONFLICT/);
+    assert.equal(await fileExists(lockPath), false);
+  });
+}
